-- Korean locale additions for `quest_request_items_locale`.
-- Update existing rows and insert missing rows only when the parent exists.
-- Preserve existing Korean text and other locales.
DROP TEMPORARY TABLE IF EXISTS `_koKR_stage_quest_request_items_locale`;
CREATE TEMPORARY TABLE `_koKR_stage_quest_request_items_locale` (
    `ID` INT UNSIGNED NOT NULL,
    `CompletionText` LONGTEXT NULL,
    PRIMARY KEY (`ID`)
) ENGINE=InnoDB;

INSERT INTO `_koKR_stage_quest_request_items_locale` (`ID`, `CompletionText`) VALUES
(2, '$c, 당신이 가지고 있는 게 뭐죠? 설마…?'),
(5, '오, 형이 보낸 물건이군? 정말 좋군! 오늘따라 운이 참 좋군!'),
(6, '개릭의 오두막을 찾았나요? 드디어 그 악당에게서 벗어난 건가요?'),
(7, '사냥은 잘 되고 있나, $n? 그 해충들을 찾아서 처치했나?'),
(8, '네? 네? 무슨 일이죠? 버림받은 자들이요. 정말 식욕이 왕성하군요. 편히 쉬세요... 네, 피곤한 몸을 좀 쉬게 하세요. 필요한 게 있으면 제 이름은 르네니까 언제든 말씀하세요.'),
(9, '아, 돌아오셨군요! 수확의 파수꾼들을 소탕하느라 바쁘셨겠죠? 벌써 스무 마리는 처치하셨나요?'),
(10, '무슨 소식이 있습니까? 꽤 심한 싸움을 겪은 것 같은데… 스크림샹크는 살아 있습니까?'),
(11, '안녕하세요, $n님. 혹시 놀들을 처치하고 계셨나요...?'),
(12, '내 말을 명확히 전달하지 못한 것 같군, 맹세하건대. 인민 민병대와 빛의 종으로서 자질을 증명하려면 데피아스 사냥꾼 15명과 데피아스 밀수꾼 15명을 처치하고 임무를 완수하면 내게 돌아와라.'),
(13, '지금은 얘기할 시간이 없어, $n. 데피아스 약탈자들이 웨스트폴 주민들이 마땅히 누려야 할 평화와 번영을 빼앗고 있어. 데피아스 약탈자 15명과 데피아스 약탈자 15명을 반드시 처단해. 그래야만 부패가 이곳에서 용납되지 않는다는 분명한 메시지를 전달할 수 있을 거야.'),
(14, '$N, 지금은 쓸데없는 잡담을 할 때가 아니다. 인민 민병대에 당신의 능력을 증명하고 싶다면, 내가 아까 알려준 데피아들을 처치해야 한다. 임무를 완수하면 내게 돌아오라.'),
(15, '광산에 가본 적 있습니까? 보고할 준비가 되셨습니까?'),
(16, '농사는 목마른 일이라서 항상 시원한 샘물을 찾고 있어요. 혹시 샘물 있으시면 교환하고 싶습니다.'),
(17, '제 연금술 작업에 필요한 자홍색 버섯 갓을 구하셨나요? 갓이 없으면 보상도 없습니다!'),
(18, '나를 위해 그 반다나들을 다 모아두셨나요?'),
(19, '블랙록에서 오는 오크의 압박은 여전히 심각합니다. 하지만 적어도 타릴준은 제거했습니까?'),
(20, '혹시 오크들을 처치하고 다녔나, $n? 그렇다면 보여줘 봐...'),
(21, '힘든 일인 건 알지만, 노스셔의 안전을 위해 꼭 필요한 일이야, $n. 취재할 준비 됐나?'),
(22, '제가 만든 유명한 고기 파이에 필요한 재료는 고어터스크 간 8개뿐입니다!'),
(23, '그게 뭐죠, $r인가요?'),
(24, '네, $c요?'),
(25, '벌써 돌아오셨군요? 그쪽 상황은 어떻게 됐어요? 당신 덕분에 다 해결됐나요?'),
(30, '$n님, 제가 살펴볼 수 있도록 펜던트를 완성하셨나요? 부품을 찾는 데 도움이 필요하시면 지역 주민들에게 문의해 보세요. 원하시는 것을 찾으실 수 있을 뿐 아니라, 이 경이롭고 신성한 숲속을 탐험할 이유도 얻으실 수 있을 겁니다.'),
(31, '썬더 블러프로의 귀환을 환영하지만, 문글레이드에서 배운 것을 증명해야만 수중 생활로 돌아가는 법을 가르쳐 줄 수 있다. 바다사자의 펜던트를 가지고 있느냐?'),
(32, '죄송하지만, 저는 당신을 알지 못합니다... 하지만 상황을 보니 당신은 저에 대해 들어본 적이 있는 것 같군요. 무엇을 도와드릴까요? 저에게 맡기실 것이 있으신가요?'),
(33, '안녕 $n. 병든 어린 늑대 사냥은 어떻게 되어가고 있어?'),
(34, '벨리그럽은 아직도 활동하고 있나요, 아니면 레이크셔에서 그 골칫거리를 완전히 없애버리셨나요?'),
(36, '버나 펄브로우가 너무 그리울 거예요. 혹시 오시는 길에 그녀를 만나셨는지 모르겠네요?'),
(38, '다음 재료들을 가지고 돌아오세요: 질긴 독수리 고기 3개, 송곳니 괴물 주둥이 3개, 멀록 눈알 3개, 오크라 3개'),
(46, '사냥은 잘 되고 있나요, $n?'),
(47, '쉿! 혹시 나한테 줄 금가루 있어? 나한테?'),
(48, '딸꾹질! 호호! 앵콜을 원해? 덩굴이 휘감겨 뻗어가는 남쪽 땅에는 깊은 물이 흐르는 숨겨진 우물이 있네. 빛의 성스러운 딸처럼 순수한 그 물을 내게 가져다주시오.'),
(49, '앵콜이요? 물론이죠! 호박색은 제 인생에서 가장 오래 지속된 사랑의 색깔이에요. 마치 저 하늘의 황혼녘 마지막 불씨처럼요. 제 사랑이 태어날 수 있도록 보리, 호밀, 옥수수 한 자루씩 가져다 주세요.'),
(50, '앵콜 요청? 좋아, 친구! 우리가 원하는 대로 섞고 또 섞어서 완벽한 믹싱을 완성할 거야. 이건 우리만의 비밀 창고가 될 테니까. 튼튼한 금속으로 증류기를 만들어야겠어. 트루실버 좀 가져와 줘. 그래야 이 노래를 끝낼 수 있으니까.'),
(51, '앵콜이요? 당신을 위해서라면 뭐든지요! 아직 여과되지 않았지만 갓 증류된 것처럼, 마치 씨를 뿌리지 않은 땅을 갈아엎는 것 같아요. 다음으로는 숯더미를 만들고, 플라타너스 가지를 가져다줄게요. 그게 당신의 다음 목표예요.'),
(52, '당신은 그 늑대들과 곰들을 죽였습니까?'),
(53, '물론, 친구, 다시 불러줄게!$B$B아기 눈물처럼 맑고 부드러운 액체$B세월이 흐르면 아름다운 진한 호박색으로 변하지$B하지만 본격적으로 취하기 전에$BA탄 참나무 통을 만들어야 해.'),
(54, '맥브라이드에게서 소식 들었나? 노스셔는 엘윈 숲에 비하면 한적한 곳이지만, 맥브라이드 원수가 무슨 소식을 전할지 궁금하군. 자, 그의 서류 좀 줘 보시오...'),
(55, '모르벤트 펠이 패배했는가?!'),
(56, '당신은 그 전사들과 마법사들을 죽였습니까?'),
(57, '해골 악마 15마리와 해골 공포 15마리를 처치하고 나면 내게 돌아오시오, $n.'),
(58, '$n, 당신의 도움이 필요합니다. 북서쪽에 있는 묘지로 가서 동쪽 묘소에서 역병 전파자 20마리를 제거해 주십시오. 임무를 완료하면 저에게 돌아오십시오.'),
(59, '저는 스톰윈드 군대로부터 병사들에게 천과 가죽 갑옷을 공급하는 임무를 맡았습니다. 만약 저에게 주문서를 주실 분이 있다면, 기꺼이 제작해 드리겠습니다.'),
(60, '양초는 다 모았어?'),
(61, '오, 형이 보낸 물건이군? 정말 좋군! 오늘따라 운이 참 좋군!'),
(62, '$n님, 무슨 보고를 하실 건가요? 파르고딥 광산에 가보셨나요?'),
(63, '화로는 여전히 주변의 빛을 반사하고, 가까이 다가갈수록 불꽃의 모양이 살짝 움직입니다. 언덕을 따라 펼쳐진 부패는 여전히 그 자리에 남아 있는 듯하며, 몇몇 부품이 없어진 것을 제외하면, 화로는 정화된 물의 현현을 소환하는 의식을 치르기에 손색이 없어 보입니다.'),
(64, '혹시 제 시계를 찾으셨나요?'),
(68, '아, 기억나요. 스탈반이라는 사람에 대해 물어보셨던 분이시죠. 찾으시던 걸 찾으셨나요?'),
(70, '그게 뭐야? 내가 좀 살펴볼까…'),
(71, '안녕하세요, $n님. 롤프와 말라카이의 운명을 알아내셨나요?'),
(74, '그게 뭐예요? 잘 안 보여요. 시력이 너무 나빠요. 제 손에 쥐어 주세요.'),
(75, '제가 말씀드렸던 페이지 찾으셨나요, $n님?'),
(76, '안녕하세요, $n님. 무슨 보고 사항이 있으신가요? 재스퍼로드 광산을 정찰하셨습니까?'),
(77, '당신이 우리 캠프에 오신 목적은 현재 진행 중인 임무에 필수적인 리플 주스를 전달하기 위한 것이겠죠?'),
(78, '해거드 원수가 보냈나? 왜 진작 말하지 않았지? 아, 옛날 해거드 말이야. 불쌍한 녀석, 곧 완전히 눈이 멀겠지. 어쨌든, 뭘 가져왔는지 좀 보자.'),
(79, '$C, 이거 뭔가 대단한 거 보여줘야겠군. 네가 가진 게 뭔지, 그리고 무슨 이야기를 해줄 수 있는지 한번 보자. 하지만 신이시여, 어서 서둘러야 해. 다크샤이어 방어가 내 최우선 과제야. 쓸데없는 단서에 시간을 낭비할 여유가 없어.'),
(80, '또 왔어, $n? 이번엔 뭘 가져왔어?'),
(81, '물건을 사러 온 것도 아니고, 배송하러 온 것도 아니라면 제 시간을 낭비하는 겁니다! 그러니 제대로 한몫 챙기세요!'),
(82, '당신, 주니어 측량사 $n 맞죠? 빨리요, 아주 심각한 상황이 벌어졌습니다! 피즐다우저가 말했던 곤충 부품들을 가지고 있습니까?!'),
(83, '린넨이 부족해요, $n. 혹시 저에게 줄 린넨이 있나요?'),
(84, '아... 너무 배고파! $n, 파이 좀 줄래?'),
(86, '내 목걸이를 훔쳐간 녀석에게 음식을 주는 건 옳지 않다고 생각하지만, 내 것을 되찾으려면 어쩔 수 없지! 혹시 멧돼지 고기 있어?'),
(87, '안녕하세요, $n님. 제 목걸이 찾으셨나요?'),
(88, '그녀를 봤어? 그녀를 얻었어?'),
(89, '이 다리는 저절로 지어지지 않아! 자, 쇠창살이랑 쇠리벳은 어디 있지?'),
(90, '혹시 마른 늑대 옆구리살 10개를 찾으셨나요? 스톰윈드의 펠리시아에게서 약초는 구하셨나요?'),
(91, '섀도하이드 펜던트 10개를 제게 가져다주시면 보상을 드리겠습니다.'),
(92, '나는 여전히 질긴 콘도르 고기 5조각, 거대한 송곳니 주둥이 5개, 그리고 바삭한 거미 고기 5인분이 필요하다.'),
(93, '안녕, $n. 끈적끈적한 거미 다리 얻었어?'),
(94, '이 사자상은 수십 년 동안 이곳에 자리 잡고 악명 높은 일갈라르 탑을 외롭게 지켜보고 있습니다. 조각상 밑부분에는 움푹 들어간 곳이 있는데, 그곳에 보석이나 상형문자를 박아 넣었을지도 모릅니다.'),
(96, '돌아왔구나! 훌륭해! 실버파인까지 가는 여정은 어땠지? 오래 걸렸나? 그곳 땅이 너무 오염되어서 네가 얼마나 성공했는지 알기는 어려워. 악취가 네가 한 모든 선행을 덮어버렸지. 하지만 작은 성공도 때로는 큰 성공만큼 중요해. 그곳의 물을 정화한 건 너뿐만 아니라 모든 샤먼에게 매우 중요한 일이었어.'),
(97, '네, $n?'),
(98, '네, $n?'),
(99, '$n, 파이어우드 족쇄를 단단히 고정했나요?'),
(101, '구울 송곳니 10개, 해골 손가락 10개, 거미 독이 든 병 5개를 가져오시오. 그러면 당신에게 폭력을 행사하려는 자들을 해치는 고통의 토템을 마법으로 만들어 주겠소.'),
(102, '당신은 그 간악한 놀들의 발 8개를 모두 모았나요?'),
(103, '기름이 없으면 불꽃은 오래 타지 않을 것입니다.'),
(104, '그 악당, 올드 머크아이를 처치했습니까? 웨스트폴 해안가를 배회하는 게 목격됐습니다. 그 흉악한 짐승을 죽이면 제게 돌아오십시오.'),
(105, '$n, 당신에게 임무가 주어졌습니다. 임무 완료를 증명할 리치의 부적 조각을 가지고 있습니까?'),
(106, '뭐라고요?? 메이벨은 내 따분한 삶의 빛인데. 어서, 그녀의 편지 좀 보여줘!'),
(107, '"할머니" 스톤필드에게서 온 편지가 있구나? 밀드레드를 정말 오랜만에 보네! 무슨 말을 하실지 궁금하군...'),
(109, '혹시... 뭐 찾으셨어요??'),
(111, '친구들의 반응이 어떨지 너무 기대돼! 전혀 예상 못 할 거야.'),
(112, '혹시 그 수정 같은 거 있어요? 메이벨이 남자친구를 만나고 싶어 안달이 났을 거예요...'),
(113, '자, 신입 측량사 $n, 페슬주그 영감님이 보고서를 다 준비했나요?'),
(114, '내 편지 토미 조에게 전해줬어? 그가 뭐라고 했어?'),
(115, '그림자술사들과의 갈등은 어떻게 되어가고 있나요? 한밤의 구슬은 찾으셨나요?'),
(116, '웨스트폴 언덕에 있는 그림부즈 썬더브루에서 썬더브루 라거 한 통, 스톰윈드에서 메를로 와인 한 통, 다크샤이어에서 문샤인 한 병, 그리고 골드샤이어에서 스위트 럼 한 가죽을 구해다오. 그것들을 내게 가져다주면 보상을 해주겠다.'),
(117, '친구여, 서둘러, 서둘러 움직여. 우리 진한 라거 맥주가 스튜 맛이 아니라 맥주다운 맛을 내려면 홉이 필요하거든.'),
(118, '뭐라고요? 버너가 보냈다고요? 그럼 그의 편지를 보여주세요. 그리고 크게 말하세요!'),
(119, '잘 돌아왔구나! 신발은 구했어?'),
(120, '거기에 무엇을 가지고 있나요?'),
(121, '장군께서 소식을 보내셨습니까? 증원군이 오고 있습니까?'),
(122, '탐욕스러운 아르거스가 내가 비늘을 빨리 주지 않으면 사람을 보내서 가져가게 할 거라는 걸 알고 있어. 혹시 그 비늘을 찾았어?'),
(123, '뭐라고요?!? 우리 직원들이 엘윈 광산에서 일한 지 몇 달이나 됐다고요! 당신이 가지고 있는 그 메모 좀 보여주세요...'),
(124, '네? 제가 도와드릴 일이 있을까요?'),
(125, '제 도구를 찾으셨나요?'),
(126, '야울러는 위험한 생물이야, $n. 네가 그를 감당할 준비가 안 됐다면 이해해.'),
(127, '나한테 줄 붕어 좀 있어?'),
(128, '블랙록 용사 15마리를 처치한 후 돌아오세요.'),
(129, '다르시가 나한테 점심을 보내줬다고? 정말 마음씨가 착하네. 좋아... 받아먹자!'),
(131, '안녕하세요, $n님. 파커 씨는 제가 보낸 점심을 마음에 들어 하셨나요?'),
(132, '$n, 다시 뵙게 되어 반갑습니다. 와일리는 뭐라고 했나요?'),
(133, '집 뒤편에서 구울 떼가 바스락거리는 소리가 들리는 것 같아. 얼른 구울 인형을 세워둬야겠어! 구울 갈비 사 왔어?'),
(134, '제 상자 가지고 계신가요? 있다면, 제발... 빨리 주세요!'),
(135, '저랑 무슨 용건이 있으십니까? 저는 아주 바쁜 사람입니다.'),
(141, '쇼 선생께서 뭔가 밝혀주신 게 있었나요?'),
(142, '$n님, 혹시 정보를 수집하셨나요? 전달자를 찾으셨나요?'),
(143, '안녕하세요, $c님. 인민 민병대와 무슨 용건이 있으신가요?'),
(144, '인민 민병대가 곧 등장할 것으로 예상해야 할까요? 스토우트맨틀 경의 소식은 좋은 징조일까요?'),
(145, '$C님, 먼 곳에서 오신 것 같군요. 다크샤이어에 무슨 용무로 오셨습니까?'),
(146, '아, 다시 뵙게 되어 반갑습니다, 전령님. 야간 경비대가 다크샤이어에서 오고 있다는 소식을 원수께 전해드릴까요?'),
(147, '수집가를 찾았나요? 그가 누구를 위해 일하는지 알아냈나요?'),
(149, '제발, 저를 보지 마세요! 제가 제 손으로 이 눈들을 뽑아냈는데도 당신의 시선이 느껴져요! 저는 끔찍하게 못생겼어요! 정말 끔찍해요! 제발, 눈을 돌려주세요!!'),
(150, '지느러미 있어요? 서둘러요, 호수에서 멀록들을 쫓아내야 해요!'),
(151, '늙은 블랜치 할머니가 이제 거의 죽을 지경이에요. 혹시 할머니께 드릴 귀리 좀 찾으셨나요?'),
(152, '타이드헌터 7마리, 워리어 7마리, 오라클 7마리, 코스트러너 7마리를 처치하면 보상을 드리겠습니다.'),
(153, '빨간색 가죽 두건 15개를 가져오면 후하게 보상해 주겠다.'),
(154, '당신이 맹인 메리를 본 것 같군요. 제 빗을 가지고 계신가요...?'),
(155, '저랑 무슨 용건이 있으십니까? 저는 굉장히 바쁜 사람입니다...'),
(156, '안녕하세요, $n님. 혹시 저에게 주실 썩은 꽃이 있나요?'),
(157, '원치 않는 악령을 막기 위해 문과 창문에 귀신 머리카락 실을 꿰어야 하는데, 혹시 구해다 주셨나요?'),
(159, '이 춥고 어두운 밤에 몸을 따뜻하게 하려면 좀비 주스가 필요해. 사다 줬어?'),
(160, '애버크롬비...? 그런 이름은 처음 듣는데요. 애버크롬비라는 사람이 제게 보낸 편지가 있다고 하셨죠? 그럼 한번 읽어보시죠...'),
(161, '꼬마야, 뭐라고 했어? 귀에서 윙윙거리는 소리밖에 안 들려. 어이, 그거 뭐야?'),
(162, '평화와 고요가 함께하길, 나그네여. 오늘 나를 찾아온 이유가 무엇인가?'),
(163, '아, $n! 벌써 돌아왔군? 또 사냥을 나갔었나 보군? 혹시 어려움이 있었더라도 걱정 마. 결국엔 더 나아질 거야!$B$B...어쨌든 더 나빠질 순 없잖아...'),
(164, '$c, 당신은 늠름해 보이시군요. 우리와 함께 싸우러 오셨나요?'),
(166, '에드윈 밴클리프를 찾는 수사는 어떻게 진행되고 있나요?'),
(167, '제 동생의 흔적이라도 찾으셨나요? 이렇게 오랜 시간이 지났는데, 희망이 있을까요?'),
(168, '제 예전 동료의 광부 노조 회원증을 찾을 수 있었나요?'),
(169, '$r, 거기에 뭘 들고 계세요?'),
(170, '정말 끈질긴 녀석들이죠, 안 그래요?'),
(171, '$n님, 다시 뵙게 되어 반갑습니다. 어린이 주간 동안 자원 봉사하셨던 일들은 모두 처리하셨나요?'),
(173, '$n, 사냥은 어떻게 진행되고 있나요?'),
(174, '청동관을 제작할 숙련된 엔지니어를 찾으셨나요?'),
(176, '네, 호거는 저와 제 부하들에게 정말 골칫거리였습니다. 그 짐승에 대해 보고할 만한 것이 있습니까?'),
(177, '나는 코그에게 우리가 만든 별 관측 장치의 초기 모습을 보여주었다. 그는 감명을 받았다. 혹시 반사 장치를 찾으셨나요?'),
(178, '내가 펜던트를 통해 너와 대화했다고? 흠... 내게 줘 봐. 내가 연구해 볼 수 있도록.'),
(179, '늑대 때문에 골치 아프신가요? 날카로운 송곳니와 발톱 같은 날카로운 부분들을 피하는 게 좋겠죠?'),
(180, '법정에 어떤 소식을 전하시겠습니까?'),
(181, '자르크불을 설득해서 우리 실험에 쓸 외알 안경을 빌릴 수 있었나요?'),
(182, '제가 알아본 바로는 이 트롤들은 서리갈기 부족 출신입니다. 그 외에는 $n 님께 도움이 될 만한 정보는 거의 없는 것 같습니다.'),
(183, '사냥은 어떻게 진행되고 있나요?'),
(184, '자경단 같은 민간인들이 끼어들 필요는 없어, 얘야. 이 일은 전문가들에게 맡겨.'),
(185, '$n, 네가 가장 어린 호랑이를 먼저 사냥하는 데 능숙하다는 것을 증명하기 전까지는 너를 더 훈련시키는 데 확신이 서지 않아.'),
(186, '더 큰 도전을 원한다면 먼저 주어진 과제를 완수하여 실력을 증명해야 한다. 스트랭글쏜 호랑이 10마리를 처치하고 내게 돌아오라.'),
(187, '당신이 진정한 호랑이 사냥꾼인지 가려낼 마지막 도전을 받기 전에, 당신은 장로 스트랭글쏜 호랑이 10마리를 처치해야 합니다.'),
(188, '사냥은 어떻게 진행되고 있나요?'),
(189, '좋은 결과 얻으셨길 바라요! 악플러들이 사방에 널려 있더군요. 정말 더러운 악마들이에요. 아, 맞다! 생각났는데, 친구들에게도 꼭 알려주세요! 도움이 많이 필요하거든요!'),
(190, '진정한 표범 사냥꾼이라면 들판으로 나가 먹잇감을 쫓겠죠. $c, 목표에 대한 의지를 보여주고 다시 사냥터로 나가세요.'),
(191, '바그테라는 잡기 힘든 짐승임이 드러날 수 있다. 과연 사냥은 얼마나 공정할까?'),
(192, '바그테라는 잡기 힘든 짐승임이 드러날 수 있다. 과연 사냥은 얼마나 공정할까?'),
(193, '아직 살아있었군요! 훌륭합니다! 사냥은 어떻게 진행되고 있나요?'),
(194, '모닥불 주변에 서서 사냥감을 잡는 사냥꾼은 본 적이 없어요. 물론 우리 아버지는 예외지만요. 가시관목맹금류를 직접 사냥할 생각이었나요, 아니면 놈들이 늙어서 죽기를 바랐던 건가요?'),
(195, '진정한 사냥꾼은 사냥감에 집중한다. 하지만 자네는 모닥불 주위에서 수다 떠는 데 더 관심이 있는 것 같군. 자, 어서 나가서 꼬리감는새끼 10마리를 잡아라. 안 그러면 내가 가서 이 빌어먹을 정글에서 꼬리감는새끼들을 한 번에 다 없애버릴 테니까.'),
(196, '흥! 이봐, 넌 왜 거기 서서 서 있는 거야! 진정한 사냥꾼은 먹잇감을 발견하면 절대 포기하지 않아. 저 정글 사냥꾼들이 모닥불 앞으로 달려와서 뛰어들 리가 없잖아. 바보 같으니.'),
(197, '아, 테티스를 쫓고 있는 거였군? 캠프까지 쭉 추적해 왔나 보군.'),
(198, '네? 무슨 용건이십니까? 아, 고블린들이 보낸 물자입니다. $r이 배달하는 건 좀 이상하군. 보통은 자기들이 직접 보내는데. 어쨌든… 손대진 않았지? 다행이군… 우리 광산에 무슨 일이 생기면 안 되잖아.'),
(199, '혹시 단서를 발견하셨나요, $n님?'),
(201, '그래서, 캠프를 찾는 데 성공했나요?'),
(202, '커젠과 그의 옹호자들이 모두 죽었기를 감히 바라봐도 될까요, $n?'),
(203, '$n, 사냥에 성공했기를 바랍니다. 당신의 도움이 없으면 그를 상대로 오래 버틸 수 없을 겁니다.'),
(204, '저는 그 치료제와 추출물($n)을 기다리고 있습니다.'),
(205, '$n, 너도 그런 페티시가 있니? 그게 쿠르젠의 타락에 대한 비밀을 간직하고 있을지도 몰라... 꼭 알아야겠어!'),
(206, '내가 너에게 축복을 내리노라. 마이조스의 힘은 그의 사악함에 필적할 만하다.'),
(207, '$n! 트롤 전설을 가지고 있나요? 그 비밀을 꼭 알아야겠어요!'),
(208, '돌아왔군, 친구. 킹 방갈라쉬 때문에 몇 번이나 다시 캠프로 기어들어왔지. 힘내.'),
(209, '정말 까다로운 녀석들이죠? 혹시 소식 좀 있으세요? 좀 조급해 보여서 죄송하지만, 이 문제 때문에 정말 골머리를 앓고 있거든요! 어떻게 됐어요?'),
(210, '안녕하세요! 저한테 뭐 가져오셨어요?'),
(211, '$n, 당신에게 임무가 주어졌습니다. 임무 완료를 증명할 리치의 부적 조각을 가지고 있습니까?'),
(212, '$n! 그 대퇴골 있어요? 곧 손질을 시작해야겠어요. 안 그러면 연회가 망쳐질 거예요!'),
(213, '그 돌들이 필요해, $n. 무슨 수를 써서라도! 그냥 해, 자세한 건 말하지 마! 중요한 건 결과야, $n. 그 이상도 그 이하도 아니야.'),
(214, '당신은 데피아스 일당으로부터 우리 땅을 되찾고 있었습니까? 그렇다면 증거로 붉은색 실크 두건 10개를 보여주세요.'),
(216, '엉겅퀴털 부족에게 공격을 개시했습니까? 우리 기지 사이에 길이 확보되면 아셴베일 전체를 차지할 가능성이 크게 높아집니다.'),
(217, '그라무그와 그의 두 경호원, 그나셔와 브롤러는 아직 살아 있습니다. 이 셋을 모두 처치해야 당신의 임무는 완료됩니다. 드워프 제국이 당신에게 기대를 걸고 있습니다, $n.'),
(218, '$n! 혹시 찾으셨나요?'),
(219, '예?'),
(220, '안녕하세요, $n님. 잘 지내시는 것 같네요.$B$B이렇게 빨리 다시 연락 주신 이유가 뭐예요?'),
(221, '이렇게 빨리 돌아오다니, $n? 설마 포기했다는 말을 하러 온 건 아니겠지?'),
(222, '무시무시한 짐승들이지 않나? 하지만 두려워하지 마라, $n! 빛을 위해 싸우는 자들은 결코 쓰러지지 않을 것이다!'),
(223, '네, 무슨 일이죠? 빨리 말씀해 주세요, 급한 일이 있어서요.'),
(224, '로크 모단이 포위당했습니다, $n! 동맹의 모든 건장한 구성원들이 우리를 도와야 합니다. 스톤스플린터 트로그 10마리와 스톤스플린터 스카웃 10마리를 처치했습니까?'),
(226, '아직도 늑대 사냥을 하고 있는 거야...?'),
(228, '그와 문제가 생기더라도 당신을 탓하지 않겠습니다, $n. 우리 파수꾼 중 가장 뛰어난 몇몇이 모르라딤에게 희생되었으니까요.'),
(230, '뭘 찾았다고?? 제발, 나한테 보여줘...'),
(231, '날 내버려 둬...'),
(232, '네, 무엇을 도와드릴까요? 왕립 약제사 협회 업무로 오신 건가요, 아니면 제게 인사를 드리려고 오신 건가요?'),
(233, '네? 저에게 주실 것이 있으신가요?'),
(234, '제가 도와드릴 일이 있으신가요?'),
(236, '자, 어때? 불씨를 찾았어? 아니면 호드가 먼저 뺏어가서 널 울게 만들었어?'),
(237, '시간이 더 필요해, $r. 자네 임무는 스톤스플린터 스컬텀퍼 10마리와 스톤스플린터 시어 10마리를 처치하는 거야. 증원군이 도착할 때까지 적에게 계속 압박을 가해. 지금은 한가롭게 시간을 보낼 때가 아니야.'),
(238, '네, 저도 루카가 당신만큼이나 소름 끼치는 인물이라고 생각합니다. 하지만 상관없습니다. 현장 샘플링 키트를 주세요. 적절한 기초 재료를 조사하려면 몇 가지 조정을 해야 합니다. 키트는 가지고 계시죠?'),
(240, '$n, 여기 있었구나! 내 음식 있어?!?'),
(245, '거미를 다룰 때는 조심하는 게 좋을 거야. 내 부하 몇 명이 거미 때문에 죽었거든. 독이 스며들어 몸이 약해진 후에 거미줄에 거꾸로 매달려 있는 사람을 보는 건 정말 끔찍한 광경이지. BBI도 네가 거미에게 잡아먹히는 걸 보고 싶어 하지 않을 거야.'),
(246, '실례지만, $n 님, 저희는 지금 여러 가지 제약 때문에 어쩔 수 없이 이 일을 처리해야 합니다. 보고할 내용이 없으시다면 다른 업무를 봐야겠습니다.'),
(248, '이 항아리는 한때 고약한 냄새가 나는 술이 담겨 있었지만, 지금은 텅 비어 술통 두 개 위에 잊혀진 채 놓여 있다.'),
(249, '서둘러, $n! 모르간트가 자신의 힘을 퍼뜨릴 거라는 내 우려가 현실이 되기 전에!'),
(251, '은둔자 애버크롬비의 편지라니? 난 그를 모르지만, 만약 그가 공동묘지에 산다면 그의 뇌는 이미 썩어 없어졌을 거라고 생각해!'),
(252, '아, 그 메모는 번역되었나요? 제게 보여주세요...'),
(253, '엘리자의 무덤을 찾았나요? 방부처리사의 심장을 가지고 있나요?'),
(255, '혹시 좋은 소식 있으셨나요?'),
(256, '네? 제가 도와드릴 일이 있을까요?'),
(257, '운이 없다고? 너무 실망하지 마, 모두가 나처럼 될 순 없잖아.'),
(258, '세상에 너무 낯선 사람에게 뒤쳐지면 자괴감을 느끼는 건 당연한 일이죠. 하지만 자괴감에 빠지지 마세요, $n.$B$BHm? 제가 이름을 잘못 불렀나요?'),
(261, '재앙은 날이 갈수록 더욱 강력해지고 있다. 진정으로 재앙의 진격을 막고 싶다면, 내게 그 증거를 보여주어라.'),
(262, '당신이 찾고 있는 그 정체불명의 인물에게 속한 물건이 있다면, 내게 보여주시오. 내가 그것의 주인을 알아낼 수 있을지도 모르오.'),
(263, '벌써 돌아왔어? 내가 제대로 말했는지 모르겠지만, 자네가 스톤스플린터 샤먼 10마리와 스톤스플린터 본스내퍼 10마리를 처치해야 해, $n. 자, 어서 가서 해치워, 트로그 슬레이어!'),
(264, '돌은 만져보면 차갑지만, 분명히 심하게 훼손된 흔적이 역력하다. 주변에는 쓰레기가 널려 있고, 관 윗부분의 부조에는 흠집과 베인 자국이 가득하며, 무덤 주변의 풀들이 무성하게 자라나 무덤을 뒤덮고 있다. 이곳에 묻힌 사람들을 신경 쓰는 사람은 아무도 없으며, 특히 흑사병 희생자라면 더욱 그렇다.'),
(265, '때때로 저는 학자나 마법사, 또는 일기를 쓰고 싶어하는 사람들에게 빈 노트를 팔곤 합니다. 지난 몇 달 동안 제게 노트를 팔았던 모든 사람들을 생생하게 기억하고 있습니다...'),
(266, '스칼렛 레이븐호는 예전만큼 장사가 잘 되지는 않지만, 여전히 여행객들이 지나가곤 합니다. 찾으시는 분의 인상착의를 설명해 주시면 제가 기억해낼 수 있을지도 모릅니다.'),
(267, '트로그 석재 이빨 8개를 보여주시겠습니까? 없다면, 아직 할 일이 남아 있습니다, $n.'),
(268, '그 정체불명의 인물이 누구였는지 알아냈나요?'),
(269, '형제여, 편히 쉬십시오. 먼 길을 여행하셨고 무거운 짐을 지고 계신 것을 알 수 있습니다. 무엇이 당신을 그토록 어둡게 드리우는지 말씀해 주시겠습니까?'),
(271, '아, $n! 벌써 돌아왔군? 또 사냥을 나갔었나 보군? 혹시 중간에 어려움이 있었더라도 걱정 마. 결국엔 더 나아질 거야! ...어쨌든 지금보다 더 나빠질 순 없잖아...'),
(272, '$n님, 제가 살펴볼 수 있도록 펜던트를 완성하셨나요? 부품을 찾는 데 도움이 필요하시면 지역 주민들에게 문의해 보세요. 원하시는 것을 찾으실 수 있을 뿐 아니라, 이 경이롭고 신성한 숲속을 탐험할 이유도 얻으실 수 있을 겁니다.'),
(274, '애슐란에서 가져오는 것은 무엇인가요?'),
(275, '습지는 여전히 눈물을 흘리고, 늪지대 담쟁이덩굴은 여전히 맹렬하게 날뛰고 있다. 네 임무를 마치면 내게 돌아오라.'),
(276, '젊은 $C, 네 임무는 아직 남아 있다.'),
(277, '놀족의 불 피우는 도구를 가지고 있나요?'),
(278, '필요한 물품은 모두 준비하셨나요? 시간이 촉박합니다!!'),
(279, '고블러와 그 멀록들을 없애기 전까지는 우리 상인들이 안전하지 않을 겁니다.'),
(280, '맥주통 뚜껑이 천천히 돌려서 열립니다.'),
(282, '안녕! 조심해, $n. 던 모로그로 가는 터널에 트로그가 우글거려서 통행이 위험해.$B$B던 모로그에 급한 볼일이 없다면, 터널이 안전해질 때까지 앤빌마르에 머물러 줘야겠어.'),
(286, '조각상 가지고 계세요?'),
(287, '못 찾겠어? 내 설명은 아주 분명했는데! 시간이 얼마 없어, 서둘러야 해! 동굴을 찾을 때까지 돌아오지 마.'),
(288, '아, 너무 목이 마르네요! 이 불쌍하고 한심한 바보에게 음료수 좀 사주시겠어요?'),
(289, '꿈속에서 때때로 동족들의 절망적인 신음 소리가 들려옵니다! 부디, 그들을 속박에서 풀어주시고 울부짖음을 잠재워 주소서.'),
(290, '이 상자는 단단히 잠겨 있습니다.'),
(291, '음... 경비원들이 청원인들을 덜 차별하는 것 같군. 자, 뭘 원하십니까? 빨리 말씀해 주십시오.'),
(292, '술 취한 피츠시몬스가 당신을 저한테 보냈다고요? 글쎄, 맥주는 더 이상 없다고 전해주세요. 다른 사람한테 구걸이나 해야 할 겁니다!'),
(293, '당신이 가지고 있는 저 구슬은 뭐죠? 좀... 더러워 보이는데요.'),
(294, '얼룩무늬 랩터 10마리와 얼룩무늬 스크리처 10마리를 처치하세요. 제 동료들은 그런 운명을 맞을 자격이 없었어요. 이제 복수할 시간입니다.'),
(295, '얼룩무늬 낫발톱과 얼룩무늬 면도날턱이 저지른 짓에 대한 대가를 치르게 해주고 싶어. 너 그놈들 각각 10마리씩 잡았어?'),
(296, '살투스는 죽었습니까? 당신은 쓰러진 자의 명예를 회복했습니까?'),
(297, '그 우상들을 가지고 있습니까? 우리는 그것들을 연구하고 그 결과를 아이언포지에 보고해야 합니다!'),
(298, '오, 현장 진행 상황 보고서군요? 아주 좋습니다!'),
(299, '$n, 네 조각을 모두 찾았나요? 아도스, 모드르, 골름, 네루 말이에요...'),
(301, '저희 스톰파이크 가문은 사소한 일로 귀찮게 하는 걸 좋아하지 않습니다, $c. 부디 제가 귀 기울일 만한 가치 있는 소식을 가져오셨기를 바랍니다.'),
(303, '로고가 예비 병력과 연락이 닿지 않고 있습니다. 우리는 다크 아이언 진영에 공세를 펼쳐야 합니다, $c. 어서 나가서 마그니 왕을 위해 임무를 수행하십시오!'),
(304, '$c님, 혹시 그 파울러 발가라스를 찾으셨나요? 꽤 오랫동안 저희를 피해 다니고 있더라고요.'),
(306, '메린을 찾으셨나요? 그녀가 연락을 해왔나요?'),
(307, '$n님, 광부 장비 가지고 계신가요?'),
(308, '흠! 여기 아래에 술이 잔뜩 있는데, 절대 손대지 말라는 엄명을 받았어. 썬더 에일 한 모금만 맛볼 수 있다면 얼마나 좋을까... 진짜로, 정신이 번쩍 들 텐데!'),
(310, '이 통에 적힌 날짜를 보니 곧 수확할 것 같네요.'),
(311, '바꾸셨나요?'),
(312, '$n님, 제 고기 보관실에 들어가 보셨나요?'),
(313, '이봐, $n. 그리즐드 덴에 가봤어? 거기 웬디고들은 엄청 사나워.'),
(314, '바가쉬가 여전히 무리를 공포에 떨게 하고 있어요! 부디 저 끔찍한 짐승을 처치해서 저희를 도와주세요.'),
(315, '혹시 쉬머위드(Shimmerweed) 있으세요? 스타우트 한 배치를 거의 다 만들었는데, 거기에 쉬머위드를 넣어보고 싶거든요.'),
(317, '준비는 순조롭게 진행되고 있습니다. 사냥은 어떻게 진행되고 있나요?'),
(319, '야생 동물들을 잘 처리하셨나요?'),
(320, '에버샤인 받았어?'),
(322, '$c님, 제가 어떻게 도와드릴 수 있을까요?'),
(323, '힘내서 싸우세요, $Nn. 그리고 절망하지 마세요. 절망이야말로 악의 가장 강력한 무기니까요.'),
(324, '필요한 라이트포지 철을 찾으셨나요?'),
(325, '안녕하세요, $n님. 떠나신 지 얼마 안 됐는데, 전에는 보지 못했던 열정이 당신의 눈빛에서 느껴지네요.'),
(328, '금고는 청동으로 테두리가 둘러져 있어 매우 견고하고 무겁습니다.'),
(329, '토르센의 비밀을 아는 사람이 누구인지 알아냈습니까? 우리 중에 배신자가 있는 겁니까?'),
(332, '안녕하세요, $gmaster:madam님. 저희 고급 와인을 드셔보셨나요?'),
(333, '배글리 씨에게서 소식을 들으셨습니까?'),
(334, '옷을 사러 오셨나요?'),
(335, '위쇼크는 곧 우리에게 큰 골칫거리가 될 만큼 충분한 지지를 얻게 될 겁니다. 혹시 틸로아의 눈물이나 머스크애쉬 뿌리를 얻으셨나요?'),
(336, '내가 바쁜 게 안 보여? 내 말을 들어야 해! 나는 이 왕국의 미래에 아주 중요한 존재라고! 어... 그건 뭐야? 시원한 음료수 같네...'),
(337, '어머! 저기 있는 저 낡은 책은 뭐예요? 좀 볼 수 있을까요?'),
(338, '$n님, 챕터들을 다 모아 놓으셨나요?'),
(339, '혹시 1, 4, 6, 8페이지를 찾으셨나요? 1장을 다시 완성하려면 그 네 페이지만 있으면 됩니다.'),
(340, '제2장 $n을 완성하려면 아직 10, 11, 14, 16페이지가 더 필요합니다.'),
(341, '18, 20, 21, 24페이지는 찾았나요? 3장을 완성하려면 그 페이지들만 있으면 돼요.'),
(342, '4장 $n을 마무리하려면 세 페이지가 더 필요합니다. 25, 26, 27페이지는 준비하셨나요?'),
(346, '책을 찾으셨나요?'),
(347, '레스반 광석 가지고 계세요?'),
(348, '....엄마?$B$B...너무 추워...$B$B...뒤틀린 지옥으로 향하고 있어...흐흐-엄마, 안아줘....'),
(349, '주술사 운바그와는 야만인 목이 뭘 좋아하는지 알아. 맞아, 맞아! 내가 영혼과 대화해서 그를 불러낼 수 있지. 하지만 다른 고릴라 괴물들도 영혼과 대화하는 걸 좋아해. 네가 주술사 운바그와를 보호해 주면 내가 그를 너에게 보내줄게. 주술사 운바그와는 먼저 원하는 게 있어. 네가 고릴라 송곳니를 가져오면 내가 영혼과 대화를 시작할게!'),
(351, '자, 이제 로봇 닭의 잔해를 발견하신 것 같군요? 달걀 속에서 다시 목소리가 들려왔습니다. "훌륭합니다! 바로 제 귀환 로봇이군요. 하지만 센서에 따르면 수리를 위해 부티 베이로 돌아가려면 시동을 걸어줘야 합니다. 자, 이제 신호기를 로봇 안에 넣어 두세요. 신호기가 알아서 처리할 겁니다!"'),
(353, '스톰윈드에서 여기까지 오셨습니까? 인간 땅이 산적과 오크들이 활개를 치고 다닌다고 들었는데, $c가 실력을 증명하기에 딱 좋은 곳이죠!'),
(354, '아가만드족의 유해를 가지고 있습니까? 그 저주받은 짐승들은 마침내 완전히 파괴되었습니까?'),
(356, '순찰 보고서가 있습니까?'),
(357, '$n님, 책을 구하셨나요?'),
(358, '당신의 임무는 완료되었습니까? 그 개 같은 것들을 파괴하고 그 안에 든 피를 모두 빼냈습니까?'),
(361, '예?'),
(362, '데블린을 찾으셨나요?'),
(364, '가장 약한 좀비조차 처치하지 못한다면 이 새로운 삶에서 멀리 나아가지 못할 것이다, $n. 성공 사례를 보고할 때까지 돌아오지 마라.'),
(365, '데스가드 시머가 당신이 제게 꼭 필요한 재료를 제공해 줄 거라고 전해왔습니다. $n, 호박 10개는 다 모았나요?'),
(366, '너희 주인들은 너희를 여기로 보낸 게 정말 어리석은 짓이야! 나는 다시는 스컬지의 노예가 되지 않을 거야!'),
(367, '$n님, 다크하운드 혈액 샘플 5개를 모으셨나요? 시간이 얼마 남지 않았어요!'),
(368, '$n님, 멀록에게서 사악한 지느러미 비늘 5개를 얻으셨나요?'),
(369, '$n, 혹시 사나운 밤거미의 독을 좀 구했나요? 제 실험을 테스트하는 데 필요한 마지막 재료거든요.'),
(370, '젊은 $C, 당신의 백성들이 당신의 도움을 간절히 필요로 하는데 브릴에서 시간을 낭비할 여유가 없습니다. 어서 무기를 들고 남서쪽의 폐허가 된 탑으로 가서 페린 대장과 스칼렛 광신도 3명, 스칼렛 선교사 3명을 처치하십시오. 우리는 스칼렛 십자군을 가축처럼 몰아 멸망으로 몰아넣을 것입니다.'),
(371, '돌아왔군. 하지만 자네의 임무는 아직 끝나지 않았네. 혹시 하찮은 인간들이 어둠의 여왕의 계획을 방해하는 것에 만족하는 건가? 아니면 의무를 다해 바숑 대장과 그의 붉은 수도사 무리를 처치할 작정인가?'),
(372, '$c, 자네는 아직 임무를 다하지 않았네. 붉은 십자군이 우리 병사들을 괴롭히는 한, 어둠의 여왕의 계획을 제대로 실행할 수 없네. 어서 그들을 처단하고 실바나스에 대한 자네의 의무를 다하라!'),
(373, '네? 제가 도와드릴 일이 있으신가요?'),
(374, '$c님, 스칼렛 인시그니아 반지 10개 다 모으셨나요?'),
(375, '$n님, 황혼박쥐 가죽 5개와 굵은 실을 준비하셨나요?'),
(376, '내가 갑옷을 구해줄 때까지 최대한 다치지 않도록 조심하렴.'),
(377, '덱스트렌 워드처럼 죽은 자들을 학대한 자가 살아 있는 한, 정의는 배신당한 것이다. 에본록 경의 사형 선고가 워드에게 집행되면 내게 돌아오라. 우리는 죽은 자들의 유족들에게 마땅한 위로를 전할 것이며, 더 나아가 스톰윈드의 귀족들에게 분명한 경고를 보낼 것이다.'),
(378, '어리석은 인간 관료주의가 드워프의 일에 간섭하는 것을 용납하지 않겠다, $n. 캄 딥퓨리는 탄돌 스팬 공격의 공모자임이 입증되었다. 마그니 왕의 선량한 백성들이 딥퓨리의 기만 때문에 목숨을 잃었다. 인간들은 딥퓨리가 감옥에서 썩어가는 것을 내버려 두겠지만, 나는 딥퓨리가 처치될 때까지 편히 잠들 수 없을 것이다.'),
(379, '그럼 유목민들이 당신을 위해 그 물주머니들을 "자발적으로" 챙겨준 건가요?'),
(380, '거미의 독을 조심하세요. 만약 날카로운 작열감이 느껴진다면 진찰을 받아보는 것이 좋습니다.'),
(381, '저 바보들… 스스로 무덤으로 가는 걸 즐기는군.'),
(382, '임무는 잘 진행되고 있나요, $n?'),
(383, '네, 무엇을 원하세요?'),
(384, '크래그 보어 립이랑 랩소디 몰트 한 잔이 필요하겠어, $n.'),
(385, '내가 악어한테 손을 물어뜯길 뻔했던 얘기 했던가? 정말 끔찍한 놈이었어, 이빨이 칼날 같았거든. 하지만 운이 좋았지... 칼로 그 녀석 턱을 꽉 다물어 버렸거든. 그 칼은 아직도 어딘가에 있을 거야...'),
(386, '스톰윈드, 그 요새에 가보셨습니까? 타르고르 더 드레드를 이렇게 오랫동안 살려둔 계략이 결국 그를 풀어줄까 두렵습니다. 그는 사형 선고를 받았지, 귀족의 변덕에 따라 이용당하는 정치적 꼭두각시가 된 게 아닙니다.'),
(387, '요새는 여전히 점령당했다! 이 데피아스 쥐새끼들에게 그들의 행동을 용납하지 않겠다는 것을 보여줘야 한다. 어서 내려가서 힘을 보여줘라!'),
(388, '$c, 돌아왔구나. 감옥에 있는 데피아스 놈들한테서 빨간색 털실 두건 10개는 다 모았어?'),
(391, '네가 스레드의 머리를 가져오든지, 아니면 내가 네 머리를 가져가겠다. 알겠어, $n?'),
(392, '네, $n님? 뭘 찾으셨나요?'),
(393, '안녕하세요. $c님, 어떻게 도와드릴까요?'),
(396, '네, 맞죠? 바로스 알렉스톤 씨로부터 당신이 오신다는 소식을 들었습니다. 당신의 말씀이 정말 궁금합니다.'),
(398, '예?'),
(399, '$n! 운이 좋으셨나요?'),
(400, '음? 공성 무기 조종사치고는 좀 어려 보이는데. 하지만 상관없어... 뭐, 고쳐야 할 게 있나? 그럼 번호표 뽑고 편히 앉아 있어. 지금 엔진 몇 대를 수리 중이라 며칠 동안은 다른 일을 맡을 시간이 없거든. 아니면, 다른 용건으로 오셨나...?'),
(404, '내가 너에게 맡긴 임무를 완수했느냐? 네놈은 그 썩어빠진 발톱을 가지고 있느냐?'),
(405, '안녕하세요. 저를 모르시거나, 아니면 저에게 급한 용건이 있으신 것 같습니다. 만약 둘 다 아니라면, 저를 귀찮게 하실 만큼 어리석지는 않으시겠죠...'),
(407, '저리 가, 더럽고 불경스러운 괴물아! 빛이 나를 보호하소서! 붉은 성전이 아제로스에서 너의…$B$B…를 없애버릴 것이다…어, 잠깐. 저건 내 음식인가? 너무 배고파…'),
(408, '시간은 우리에게 주어진 사치가 아닙니다. 시간이 흐를수록 티리스팔 숲을 장악하고 있는 재앙의 영향력은 더욱 깊어지고 있습니다.'),
(409, '$c, 당신의 충성심을 증명할 증거를 기다리겠습니다.'),
(410, '이 테이블은 낡고, 흠집투성이에, 피투성이입니다.'),
(411, '군터의 책을 돌려주셨나요? 답장은 받았나요?'),
(412, '조종사들은 어서 다시 전투기에 올라타 전장으로 나가고 싶어 안달이 나 있습니다. 그들을 실망시키지 맙시다.'),
(413, '안녕하세요, $c님! 무슨 일로 여기까지 오셨나요? 뭔가 재밌는 일이 있으시길 바랍니다. 저는 요즘 제대로 된 싸움을 못 해서 맥주도 거의 다 마셨거든요...'),
(414, '안녕하세요, $c님, Thelsamar에 오신 것을 환영합니다!'),
(416, '안녕하세요, $n님. 쥐 잡는 건 잘 되고 있나요?'),
(417, '안녕하세요, $n님. 제 친구 힐델브의 소식을 아시나요?'),
(418, '요리할 준비는 다 됐는데, 재료 준비됐어?'),
(420, '안녕하세요? 저랑 같이 한잔 하실래요? 날씨가 너무 추워서 할 일도 별로 없네요.'),
(421, '내게 실력을 증명하고 싶다면, 달빛에 휩싸인 흰머리딱지 다섯 마리를 처치해야 한다. 그 임무를 완수하면, 네 능력을 더욱 가치 있는 일에 활용할 수 있도록 해주겠다.'),
(422, '$C, 우리가 지금 무엇을 상대하고 있는지 파악하기 전에, 아루갈의 치유 주문이라는 마법을 연구해야 합니다. 지금 당장 가져오지 않으면, 나는 마땅한 하인을 찾아야 할 것입니다.'),
(423, '아루갈을 위한 최종 해결책을 마련하려면 탐식의 족쇄 6개와 어둠의 영혼 족쇄 3개가 필요합니다. 자, 이제 내 명령에 따라 달의 분노 탐식자와 달의 분노 어둠의 영혼을 처치하여 필요한 족쇄를 모아 오십시오.'),
(424, '창백한 그림슨이 죽었는가? 바리마트라스는 우리가 그의 명령을 무시한다면 기뻐하지 않을 것이다.'),
(425, '이바르 더 파울을 처치했는가? 나와 내 동생을 위해서라도 하지 않겠다면, 포세이큰을 위해서라도 해 주시오.'),
(426, '재앙과의 전투는 계속됩니다, $n. 당신도 힘을 보태서 저주받은, 이성 없는 언데드들을 역병지대로 다시 던져버리세요!'),
(427, '어둠의 여왕에게 당신의 가치를 증명하고 싶다면, 스칼렛 워리어 10명을 처치하십시오. $C.'),
(429, '시간이 얼마 남지 않았어, $C. 어둠의 여신께서 내게 중대한 임무를 맡기셨거든.'),
(430, '제 여동생이 당신이 우리를 도우러 오셨다고 하던데요. 사실인가요?'),
(432, '정말 화가 나! 으르렁...'),
(433, '만약 우리가 골볼라르 채석장에서 트로그들을 제거할 수 있다면, 그것은 이 위협에서 벗어나기 위해 우리가 해야 할 많은 단계 중 첫 번째 단계가 될 것입니다.'),
(434, '네, $n? 티리온은 잘 지내고 있나요? 그가 상황을 알려줬고, 마르존을 속여서 성으로 오게 하는 걸 도왔습니다. 마르존은 스톰윈드에서 많은 사람들에게 골칫거리였는데, 그중에는 제 가까운 친구들도 많습니다. 제 친구들을 건드리는 건 누구에게도 용납 못 합니다... 특히 그들에게 무엇이 이로운지 안다면 말이죠. 다만, 그 과정에서 간접적으로 쇼와 SI:7에게 도움을 주고 있다는 게 좀 아쉽네요. 뭐, 모든 계획이 완벽할 순 없으니까요.'),
(437, '$n, 나이트래시를 물리쳤습니까? 부패한 가죽에 대한 우리의 성공은 그녀를 제거하는 데 달려 있습니다!'),
(439, '$n. 돌아오셨으니 조사에 성과가 있었겠죠?'),
(440, '안녕하세요, $n님. 브릴에 다시 오신 이유가 무엇인가요?'),
(441, '저 아세요?'),
(442, '재앙이 실버파인에 남아 있도록 내버려 둘 수는 없다, $n. 툴레의 죽음을 증명할 증거를 확보하면 다시 내게 연락해라.'),
(443, '썩은 가죽의 진액이 있나요, $n?'),
(444, '제 학업에는 상당한 집중력이 필요합니다. 그러니 부디 방문이 가벼운 목적이 아니길 바랍니다.'),
(445, '$c 님, 저랑 무슨 용무가 있으신가요?'),
(446, '안녕하세요, $n님. 베토르는 뭐라고 했나요?'),
(447, '안녕하세요, $c님. 왕립 약제사 협회와 무슨 용건이 있으신가요?'),
(449, '데스스토커들의 운명을 알아내셨나요?'),
(450, '$n 님, 돌아오셨군요.'),
(451, '$n, 무슨 일로 언더시티에 다시 오셨나요?'),
(453, '당신 누구세요?? 저리 내버려 두세요!'),
(455, '로크 모단에서 오시는 건가요? 알가즈 게이트의 오크 상황은 어떤가요?'),
(456, '놈들을 처리 하셨습니까?, $n. 새끼 밤호랑이 개체 수를 줄인 후에 다시 저에게 오십시오.'),
(457, '$n, 당신의 임무는 아직 끝나지 않았습니다. 꾀죄죄한 나이트세이버 5마리와 엉겅퀴 멧돼지 5마리를 처치하고 돌아오십시오.'),
(459, '내 의심을 풀어주시오, $n. 펠모스 8개를 가져오시오.'),
(460, '이 무덤은 급하게 파놓은 것이었다.'),
(461, '바로 여기야! 더 가까이 데려가 줘...'),
(464, '드래곤마우 야영지를 공격했습니까?'),
(465, '첫 번째 투석기가 당신 앞에 있습니다. 불을 붙이시겠습니까?'),
(466, '그 광석은 어디 있지, $n?!'),
(469, '안녕하세요, $C님. 부츠 한 켤레 어떠세요? 아니면 새로 건조된 가죽은 어떠세요?'),
(470, '제 가방 찾으셨나요?'),
(471, '내 제자는 내게 아들이나 마찬가지야. 한쪽 다리만으로 살아가야 한다는 게 쉽지 않겠군. 아, $n, 잘 지내? 내 가죽은 가지고 있나?'),
(474, '네크로쉬를 처치했나요?'),
(476, '세상에! 이건 정말 심각한 문제입니다! 과거에 퍼볼그의 타락으로 어려움을 겪은 적은 있지만, 텔드라실 정화 이후로는 그런 문제는 오래전에 해결되었어야 했습니다. 신들의 은총으로조차 우리의 위대한 나무를 구원할 수 없다면, 우리 모든 백성의 미래가 걱정됩니다.'),
(478, '$n, 뭔가 유용한 걸 배웠나요?'),
(479, '우리는 서두르1야 합니다. 그들의 계획이 실현되어서는 안 됩니다. 그렇지 않으면 실버파인 숲에 대한 우리의 지배권을 잃을지도 모릅니다.'),
(480, '시간이 얼마 남지 않았어요, $n!'),
(481, '네, $c요? 그게 뭐죠?'),
(483, '만약 우리가 서쪽에 있는 바네틸 무덤 동굴에서 깨어남의 유물을 되찾지 못한다면, 납치된 탈론의 드루이드들은 영원히 에메랄드 꿈에 갇히게 될 것입니다. 우리가 매 순간 지체할 때마다 그들의 운명은 영원한 파멸에 한 걸음 더 가까워집니다.'),
(484, '$n 맞죠? 제 스킨 가지고 계세요?'),
(485, '자, 이제 로봇 닭의 잔해를 발견하신 것 같군요? 달걀 속에서 다시 목소리가 들려왔습니다. "훌륭합니다! 바로 제 귀환 로봇이군요. 하지만 센서에 따르면 수리를 위해 부티 베이로 돌아가려면 시동을 걸어줘야 합니다. 자, 이제 신호기를 로봇 안에 넣어 두세요. 신호기가 알아서 처리할 겁니다!"'),
(486, '우르살 더 마울러가 죽기 전까지는 우리 형제들은 깨어날 수 없습니다.'),
(487, '그 길은 아직 안전하지 않아, $c. 앞으로 나아가서 그날파인 매복자 6명을 처치하고 내게 돌아오너라.'),
(488, '$n, 부지런한 작은 꿀벌이었니? 네가 내게 필요한 걸 가져다주기를 기다리고 있었어.'),
(489, '$n님, 저를 위해 뭘 준비하셨나요? 맛있는 간식이겠죠?'),
(491, '$n. 툴레 레이븐클로를 이겼습니까?'),
(492, '내게 믿음직한 소총만 있었다면 넌 이제 죽은 목숨이나 다름없을 텐데, $c. 증기 전차 여단이 날 구하러 도착할 때까지 기다려 봐!'),
(493, '저에게 주실 게 있으신가요?'),
(496, '돌아왔군요. 필요한 요원들을 다 모았기를 바랍니다. 또 하루가 지나가면 기분이 몹시 우울해질 것 같거든요.'),
(498, '서둘러야 해, $C. 인간들이 드룰과 토그타르에게 무슨 짓을 하고 있을지 생각만 해도 끔찍해.'),
(499, '개굴!'),
(500, '$n, 아직도 오우거 사냥 중인가? 내가 모아오라고 했던 뼈는 가지고 있나?'),
(501, '$n, 자네 기억나네. 내 최신 묘약을 만드는 걸 도와주기로 했었지. 힐스브래드 주민들에게 나만의 특별한 고통을 안겨주기 전에 자네의 피가 필요하거든.'),
(502, '씨?'),
(503, '$C, 열쇠를 줘. 내가 직접 자물쇠를 열게.'),
(504, '$n, 네가 처치해야 할 전쟁광들이 아직 많이 남아있어. 넌 무기를 집어넣고 여기 아래에 있을 게 아니라, 산 위에서 임무를 수행해야 해.'),
(505, '당신이 그 조직폭력배들을 처치했겠죠?'),
(507, '뭘 원하세요?'),
(508, '돌아왔군요, $n님. 성공하셨습니까?'),
(509, '네탄더 스테드에서 좋은 결과 얻으셨나요?'),
(510, '$n, 불안해 보이시네요. 저에게 하고 싶은 말씀이라도 있으신가요?'),
(511, '네, 사장님? 저와 볼일이 있으십니까?'),
(512, '신디케이트를 추적하고 있었습니까? 그 반지들을 가지고 있습니까?'),
(513, '$C, 내가 얼마나 바쁜지 안 보여? 암흑의 여왕이 노스렌드에서 몰려오는 스컬지가 우리를 덮치기 전에 새로운 역병을 퍼뜨리겠다고 했어. 게다가 남쪽에서 인간들이 닥쳐오는 위협 때문에 시간이 내게는 가장 소중한 자원이야. 이번 일은 정말 중요한 일이어야 할 거야!'),
(514, '사우스쇼어에 사는 딥스가 보냈군요? 그 책벌레는 잘 지내나요?'),
(515, '$n, 돌아와 줘서 정말 반가워. 여기선 너무 심심했어. 움피를 독살하고 병들게 해서 되살리는 것 말고는 재밌는 게 하나도 없었거든... 계속해서 반복하는 게 전부였어.$B$B지하 도시로 가는 길은 어땠어? 가는 길에 인간들을 좀 처치할 기회라도 있었어?'),
(516, '$n, 그들의 기지를 찾았습니까? 시간이 촉박합니다!'),
(517, '타렌 밀에서 너무 심심할 때면 가끔 포름알데히드 병뚜껑을 열어 향긋한 냄새가 공기 중에 퍼지게 하곤 해요. 움피는 좀 무서워하지만요.$B$B그래서 드워프들한테서 술통 좀 구해왔어? 이 치명적인 묘약을 하루 더 아무한테도 못 쓰게 쳐다보고 있어야 한다면 정말 소리 지를 것 같아.'),
(518, '$n, 당신의 임무가 아직 끝나지 않았군요. 샤를린드라에게 당신의 무능함을 알릴까요?'),
(519, '변명은 필요 없고, 그들의 목을 원한다.'),
(520, '내게는 머리가 세 개 있는데, 네 번째 머리가 필요해. 머그톨의 머리가 될 수도 있고, 네 머리가 될 수도 있지, $n. 그건 약속할게.'),
(521, '네? 신고하실 사항이 있으신가요?'),
(522, '숨이 차 보이시네요! 무슨 일 있으세요?'),
(523, '바론 바르두스가 사우스쇼어가 그의 부하들을 우리에게 보내는 것을 아무런 제재 없이 용납할 거라고 생각하는 건 착각이다. 그의 목을 베어라!'),
(524, '카펫에서 곰팡이 냄새가 난다.'),
(525, '$n. 산기슭과 산을 다시 여행하셨습니까? 무슨 소식을 가져오셨나요?'),
(526, '필요한 라이트포지 철을 찾으셨나요?'),
(527, '바리마트라스와 암흑의 여왕의 직속 부하인 타렌 밀의 최고 집행관으로서, 자네는 내 명령에 복종해야 한다. 혹시 동맹과의 전쟁을 가볍게 여기는 건가? 그렇다면 당장 여기서 자네의 목을 베어버리겠다. 그렇지 않다면, 서쪽 힐스브래드 마을로 가서 명령대로 인간들과 싸우도록 하라. (비켜섰다.)'),
(528, '$c, 당신은 명령을 받았소. 다른 곳에 할 일이 있는데 타렌 밀에서 꾸물거리지 마시오.'),
(529, 'C씨, 명령은 이행했습니까? 베링탄과 그의 부하들을 처리했습니까? 그리고 그 철 화물은 어디 있습니까?'),
(530, '$n, 당신은 그런 손을 가지고 있나요?'),
(531, '정말 잘했어, $n! 우리가 제대로 혼쭐을 내줬군! 자, 머리 좀 줘 봐. 내가 알아서 할게.'),
(532, '무슨 소식 있어요?'),
(533, '뭔가 발견한 게 있나? 골디르의 미래가 날이 갈수록 더 암담해지는 것 같아 걱정이군...'),
(535, '마실 것 좀 가져다주셨어요, 아니면 일을 마무리하러 다시 오신 건가요?'),
(536, '맥주 한 잔 더 주세요, 방금 마신 게 어디 갔는지 모르겠어요! 아, 여기 얼마나 더 갇혀 있어야 하는 거야? 아, 너였구나, $n. 멀록들은 다 잡았어?'),
(537, '아르거스 웨이크의 사절들을 찾으셨나요?'),
(539, '자네는 아주르로드 광산을 공격하라는 직접 명령을 받았네. 타렌 제분소에서 빈둥거리는 이유가 그럴듯하지 않으면 반역죄로 자네의 목을 베어버리겠다.'),
(540, '저도 유적을 탐색해 보고 싶지만, 이 뼈들이 산을 오르는 동안 저를 지탱해 줄 것 같지는 않네요. 그런데 $n 님은 지식을 찾아 나서는 여정이 어떻게 진행되고 있나요?'),
(541, '던 가록이 자네에게 너무 큰 장애물인가 보군, $C? 힐스브래드에서 훌륭하게 자리를 잡았다고 생각했는데 말이지.$B$B만약 자네가 이 임무를 수행할 능력이 없다면, 더 나은 결과를 낼 수 있는 다른 사람을 찾겠네. 자네는, 뭐, 티리스팔 숲에서 어둠의 여왕이 무덤 파는 사람을 더 필요로 할 테니 말이지.'),
(542, '$n, 돌아왔구나! 알터랙 탐험은 어땠어? 뭐 가져온 거라도 있어?'),
(543, '안녕하세요, $n님. 제 바지 밑단을 밟지 않도록 조심해 주세요. 이 옷은 새로 맞춘 거거든요.'),
(544, '도둑들을 찾았나요? 그리고 더 중요한 건, 그들이 무엇을 훔쳐갔는지도 찾았나요?'),
(545, '달라란 유적 주변의 순찰대 수를 줄였습니까?'),
(546, '행운의 $n이 돌아왔다고? 오늘 사람을 몇 명이나 죽였지? 수백 명은 됐겠지! $B$B내게 줄 해골 좀 있어?'),
(547, '$n, 내 검을 되찾았나? 최고 집행관 다르탈리아가 내 어리석음을 알게 되면 날 교수형에 처할 거야.'),
(549, '$c, 내 앞에 이렇게 서 있는 것 말고는 할 일이 없습니까? 최고 집행관으로서 저는 당신의 썩어가는 얼굴을 쳐다볼 시간이 없습니다.'),
(550, '$C라는 인물이 전장에서 언더시티까지 오게 된 이유는 무엇일까요?'),
(551, '아, 제가 좀 살펴봐줬으면 하는 게 있으신가요? 산에서 주워온 전설 조각 같은 거라도 좋으니 말이죠...'),
(552, '헬큘러의 지팡이를 찾았나요? 이 지역에는 예티가 너무 많아서 찾기가 정말 어려울 거예요. 하지만 앞으로 나아가려면 그 지팡이가 꼭 필요합니다.'),
(553, '헬쿨라르의 무덤은 신비로운 기운으로 가득 차 있다.'),
(554, '또 방해하시는 건가요? 아, 이 양피지에는 아주 복잡하고 정교하게 짜인 마법이 걸려 있군요. 물론 풀 수는 있지만 시간이 꽤 걸릴 겁니다. 그리고 시간은 저에게 아주 소중하거든요... 그냥 당신에게서 사야 할까요?'),
(555, '재료 구하는 데 성공했나요? 이 지역은 예전처럼 평화로운 곳이 아니더군요. 아, 이런 소동이 없었더라면 얼마나 좋았을까요…'),
(556, '$n님, 낡은 돌 토큰을 가지고 계신가요? 마법사가 그 비밀을 밝히고 싶어합니다.'),
(557, '안녕하세요, $n님. 정령들은 잡기 힘든 사냥감이지만, 당신이라면 충분히 해낼 수 있을 거라고 믿습니다. 속박의 팔찌를 가지고 계신가요?'),
(558, '나도 언젠가 자이나처럼 영웅이 되고 싶어... 물론 남자 영웅으로 말이야.'),
(559, '$n, 저 머리들 나한테 구해다 준 거야?'),
(560, '시민 여러분, 안녕하세요. 사우스쇼어의 안전을 지키는 데 힘을 보태주시겠습니까?'),
(562, '스톰윈드에 계신 사무엘슨 소령님께 보낼 편지를 준비했습니다. 이제 결과만 있으면 됩니다.'),
(563, '안녕하세요, 시민님. 스톰윈드 시 경비대가 도와드릴까요?'),
(564, '퓨마들이 우리 말들을 마구잡이로 죽여대는데 당신은 날씨나 어쩌고저쩌고 떠들어대고 있군. 진짜 영웅이나 찾아봐야겠어. 말은 그만하고 살육이나 더 많이 해야지.'),
(565, '그래서 당신은 위대한 바르톨로에게 돌아왔군요. 혹시 예티 털 망토를 만드는 데 필요한 재료를 다 모으셨나요? 아니면 그냥 저, 바르톨로의 위대함을 만끽하고 싶으신 건가요!'),
(566, '아, $n 님. 혹시 바르두스 남작의 현상금을 받으러 오셨나요?'),
(567, '예?'),
(568, '우리의 공급 노력은 여전히 토착 맹금류 개체 수로 인해 방해받고 있습니다.'),
(569, '$C님, 미즈자 유적의 오거들을 처리하는 데 진전이 있었나요?'),
(570, '무슨 소식을 전하시나요?'),
(571, '운이 좋으셨나 보군요, $n 님? 혹시 숙성된 고릴라 힘줄을 구하셨나요?'),
(572, '수집 활동은 결실을 맺었습니까?'),
(573, '마법을 거의 완성할 준비가 되었습니다. 제 명령을 수행했습니까?'),
(574, '요화 상사가 자네가 실력도 좋고 용감하다고 하던데요, C씨. 혹시 자랑할 만한 게 있나?'),
(575, '제 장비는 다 준비됐어요, $n. 스킨만 있으면 돼요. 리들복스를 기다리게 하고 싶진 않아요. 팅커스 연합의 최고 발명가를 만족시키지 못하는 건 누구에게도 좋은 생각이 아니니까요.'),
(576, '이봐, 친구! 잘 안 보일지 몰라도 항구 건너편에서도 네 냄새가 나. 내 눈이 정말 필요해. 선장님이 내 눈이 그 더러운 블러드세일 해적들 손에 들어갔다는 걸 알면 날 가만두지 않을 거야. 볼 수 없는 망보는 무슨 소용이야? 망루가 내 집이나 다름없었는데... 내 등대가 없었으면 뱃저기 청소라도 할 수 있었을 텐데.'),
(577, '드리즐릭의 엑셀시오르 가죽 부츠, 최고의 장인 정신으로 만들어졌으며, 100% 최고급 바닷물 악어 가죽으로 제작되었습니다. 이보다 더 좋을 순 없죠! 이렇게 찬사를 보낼 수 있을까요? 혹시 그 가죽을 저에게 주실 수 있다면 더할 나위 없이 좋겠죠?'),
(578, '트롤들은 정말 놀라운 마법 물건들을 가지고 있었군요, $n. 그리고 이제, 저도 제 방대한 컬렉션에 하나를 추가할 기회를 얻게 된 것 같습니다. 혹시 그 소문의 출처를 찾으셨나요?'),
(579, '안두인 왕은 학문을 매우 중요하게 여겨 여러 고서와 문헌의 사본을 대중이 이용할 수 있도록 자금을 지원해 왔습니다. 방법은 아주 간단합니다. 도서관 상품권을 가져오시면 제가 이용 가능한 책 중 한 권을 사본으로 드리겠습니다.'),
(580, '날 가라앉혀! 술이 거의 다 떨어졌어! 선장님은 닻을 올리실 거고, 올드 슬림은 타나리스 사막처럼 술 한 방울 없이 꼼짝 못 하게 될 거야. 그리고 항구가 없어진 걸 알게 되면… 맙소사!'),
(581, '$c. 블러드스칼프 부족을 사냥했다는 증거를 보여줘. 네 전리품을 보여줘.'),
(582, '$n. 우리 족장님의 아들이 걱정됩니다. 축소된 머리들을 가지고 계신가요? 제가 한번 살펴보겠습니다.'),
(584, '솥 안의 초록빛 국물이 보글보글 끓고 있다.'),
(585, '나는 해골들을 기다린다...'),
(586, '내 살점이 두개골에서 끓어오르며 떨어져 나가지만, 여전히 네 공포의 냄새가 느껴진다. 하! 넌 결코 내 임무를 완수하지 못할 것이다...'),
(587, '원하는 물건 찾았어, 친구?'),
(589, '조각들을 가지고 있나요, $n? 마음의 눈을 얻은 후 마지막 의식을 치르려면 그 조각들이 필요해요.'),
(591, '안녕하십니까, $n님. 정령들은 당신의 용맹함을 칭송하지만, 마이조스에 맞선 당신의 모험에 대한 이야기는 들려주지 않습니다. 혹시 ''눈''을 가지고 계십니까?'),
(592, '킨윌레이가 당신이 예니쿠를 잡으러 나섰다고 하던데요. 사실입니까? 그를 잡았습니까?'),
(593, '예니쿠는 당신 앞에 멍하니 서 있고, 그의 정신은 딴 데 가 있는 듯합니다...'),
(596, '블러드스칼프는 언젠가 다크스피어에게 멸망당할 것이다! 우리 파멸할 적의 목걸이를 가지고 있느냐?'),
(598, '스컬스플리터들은 우리를 전쟁터로 몰아넣은 날을 저주할 것이다! 네 임무는 완료되었는가?'),
(600, '혹시 그 수정 가지고 계세요? 저한테 필요해요! 그러니까... 악랄한 벤처 컴퍼니가 스트랭글쏜에서 세력을 잃어가고 있다는 걸 알아야 하거든요. 아시다시피, 우리 같은 정직한 사람들도 먹고 살아야 하잖아요!'),
(601, '$n님, 혹시 좋은 소식 있으셨나요?'),
(602, '괜찮으시다면, 지금 제가 좀 바빠서요.'),
(604, '안녕, $n. 남쪽 블러드세일 진영에 대한 소식은 어떻게 되는가?'),
(605, '그 파편들 다 모았어? 수익금의 상당 부분을 줄게!'),
(606, '어이! 당신이 나를 쳐다보는 눈빛이 마음에 안 드는데요, $gmister:lady;.'),
(607, '네, 네. 셰이키한테 돈 받았어요?'),
(608, '무슨 문제야, $n? 블러드세일 해적단보다 먼저 공격해야 해!'),
(609, '$n, 그 개 세 마리 찾았어? 걔네들 물건은 챙겼어?'),
(610, '난 전에 한 번도 져본 적이 없었어, 알잖아? 물론 칼에 베인 적은 있지, 칼싸움에서 그런 건 어쩔 수 없으니까. 하지만 걔가 그냥 내 머리 옆을 후려쳐서 정신을 잃게 만든 거야. 정신을 차려보니 칼이 없어져 있었지. 내 별명이 뭘 의미하는지는 몰라도, 난 여전히 싸울 때 칼이 필요하고, 나에게는 바로 그 칼이 필요해.'),
(611, '$n, 조수의 돌을 찾아왔나요? 이미 자리를 마련해 두고 멋진 받침대도 사 놨어요.'),
(613, '어이, $n! 모리의 열쇠를 찾았니?'),
(614, '어이, $n! 고를라쉬 찾았어? 저 상자는 내가 제일 아끼던 거였는데, 안에는 내 가장 소중한 보물들이 숨겨진 비밀 공간이 있었거든!'),
(617, '나랑 볼일 없으면 그냥 가버려, $n.'),
(618, '내 커틀러스 받았어, $n?'),
(619, '이것은 버려진 구명보트입니다. 옆면에는 긁히고 바랜 페인트로 "스모츠의 복수"라는 글자가 쓰여 있습니다.'),
(621, '잔질의 혼합물 샘플을 가지고 계신가요?'),
(622, '안녕하세요, $n님. 부티 베이에 도착하셨나요? 고블린 크라젝이 제 냄비를 고쳐줬나요?'),
(623, '응?'),
(627, '안녕하세요, $n님. 혈석 얻는 데 성공하셨나요?'),
(628, '어디선가 바닷물 악어가 서서히 멸종하고 있다는 글을 읽었어요... 제 사업에는 안 좋은 소식이죠? 어쨌든, 혹시 나이 든 바닷물 악어 가죽 있으세요?'),
(629, '태블릿 조각을 기다립니다, $n.'),
(630, '조상님들께 감사드립니다. 누군가 저를 도와주러 왔군요. 저를 풀어줄 열쇠를 가지고 계신가요?'),
(632, '$n, 올드 러스트록은 어디 갔지?'),
(633, '폭발물 저장소를 파괴해야 한다!'),
(637, '$c님, 먼 길을 여행하시고 많은 격동을 겪으신 것 같아 보이시네요. 우리가 사는 이 시대는 영혼을 시험하는 시대입니다. 이번에는 무슨 소식을 전해주실 건가요?'),
(639, '첫 번째 문장을 찾으셨나요? 아마 스트롬가드에 있는 신디케이트 요원 중 한 명이 소지하고 있을 겁니다.'),
(640, '트롬카, 젠구 씨가 당신이 제 도움이 필요하다고 말씀하셨죠?'),
(641, '$n! 두 번째 문장을 가지고 있나요?'),
(642, '이 파편 덩어리는 미즈라엘의 파편들과 매우 흡사해 보인다. 하지만 그곳에서 느껴지는 안정감은 전혀 느껴지지 않는다.'),
(643, '발로콜을 추적하는 건 쉽지 않을 겁니다, $n. 말을 타고 있으면 순식간에 이동할 수 있으니까요. 하지만 그의 문장을 확보해야 합니다.'),
(644, '돌아왔군, $n. 이그나에우스 트롤베인의 계보는 끊어진 건가?'),
(645, '트롤베인의 무덤 앞면에 새겨진 문양은 이그나에우스의 문장의 빛나는 선과 일치합니다...'),
(646, '$n! 칼을 가져갔나요?'),
(647, '좋은 소식 좀 알려줘, $r?'),
(651, '이것은 내면의 결속석입니다. 결속석 중에서 가장 강력하며, 다른 결속석들을 열려면 먼저 이 결속석의 잠금을 풀어야 합니다.'),
(652, '키스톤은 엄청난 지리적 에너지를 지니고 있습니다.'),
(654, '필요한 건 다 챙기셨나요?'),
(656, '미즈라엘의 파편들은 지금 이상할 정도로 조용하다.'),
(658, '$n, 그 택배원을 찾는 데 도움을 주셔서 감사합니다. 당신이 없는 동안 Kin이 여기 남쪽에 있는 그 집에서 약사가 나오는 것을 봤다고 하더군요. 저는 그들이 뭔가 꿍꿍이가 있다고 확신합니다. 다만 섣부른 행동을 하기 전에 증거가 필요해요. 혹시 단서를 찾으셨나요?'),
(662, '수색 및 복구 작전은 어떻게 진행되고 있나, $n? 메이든스 폴리호와 스피릿 오브 실버파인호의 항해일지와 해도들을 꼭 되찾아와야 해. 만약 그 자료들이 적의 손에 넘어간다면, 시혼 사령관님께서 우리를 배에서 떨어뜨리실 거야. 우리가 이 엉망진창인 상황에서 벗어날 수만 있다면 말이지…'),
(664, '에휴, 내가 직접 나가 놈들을 죽여버려야겠군. 넌 어차피 안 할 거잖아. 그럼 내가 뜨개질 바늘 좀 찾아서 네가 심심하지 않게 해 줄까?'),
(665, '지금은 얘기할 때가 아니야! 고글에 돌의 힘을 불어넣어야 해!'),
(666, '고글은 어땠나요? 모든 기능이 제대로 작동했나요? 필요하면 조정도 할 수 있습니다. 아, 그리고 다 끝나면 고글을 다시 돌려주셔야 해요. 오브린 선장님이 나중에 유용하게 쓰실 것 같거든요.'),
(668, '안녕하세요, $c님. 무슨 일로 다리에 오셨나요?'),
(669, '부티 베이에 무슨 일로 오셨나요, $c님?'),
(670, '그렇다면 시혼은 감명받았을까요? 분명 그의 미소는 부티 베이에서 래칫까지 닿았을 거예요.'),
(671, '한때 저주받았던 피가 여전히 내 혈관을 흐르고 있다, $n. 만약 누군가… 무언가가 악마를 소환하고 있다면, 반드시 막아야 한다.'),
(672, '고르물에게 맹금류의 힘을 조금이라도 줄 수 있는 부적을 만들겠습니다. 어쩌면 그것이 그의 내면에 잠재된 불꽃을 일깨워 줄지도 모릅니다...'),
(673, '내 혈관 속의 불길은… 날이 갈수록 거세지고 있다. 저 마법사를 반드시 막아야 한다.'),
(674, '겁쟁이의 손이 가장 강한 자를 쓰러뜨릴 수 있는데, 무슨 희망이 있겠습니까? 도대체 무슨 희망이 있단 말입니까!'),
(676, '나는 도끼를 갈 시간조차 없는데, 하물며 내 동족을 해치려는 짐승들을 처치하러 전초기지를 떠날 시간은 더더욱 없다. 자네는 보병조차 제대로 된 경험이 없어 보이는데, 대체 뭘 원하는 건가, $n?'),
(677, '만약 당신이 아직 내 임무를 완수하지 못했다면, 당신은 전쟁에 서툰 초보자일 뿐 아니라 마음씨도 겁쟁이일 것입니다.'),
(678, '망설이는군. 왜? 지금까지 넌 엄청난 강인함을 보여줬어, $n. 지금 날 실망시키지 마.'),
(679, '네 용기가 마침내 사그라드는군. 내 직감이 옳았던 것 같군. 네 힘은 허세에 비하면 아무것도 아니로구나. 짐승의 머리가 잘려나간 후에 내게 돌아오거나, 다시는 돌아오지 마라.'),
(680, '아라토르 탑 근처에서 오르칼라를 찾을 수 있을 겁니다. 그를 죽이면 해머폴에 대한 공격이 멈추고 제 남편의 목숨을 구할 수 있을 겁니다. 당신의 눈빛을 보니 제가 침묵하는 것을 나약하고 심지어 불명예스럽다고 생각하는 것 같군요. 언젠가 당신도 저처럼 사랑하는 것이 무엇인지 알게 될 겁니다. 그때 비로소 다른 종류의 강인함과 명예를 이해하게 될지도 모르죠. 그동안 제가 부탁하는 대로 오르칼라를 처치해 주십시오.'),
(681, '$N, 시간이 흐를수록 스트롬가르드에 대한 우리의 지배력은 더욱 약해지고 있습니다. 서두르지 않으면 우리 도시는 틀림없이 함락될 것입니다.'),
(682, '$n, 스트롬가드 배지를 회수했습니까? 신디케이트는 우리의 죽음을 통해 이득을 취할 수 없다는 것을 깨달아야 합니다.'),
(683, '당신이 바로 그 $c 회원이시군요? 당신이 동맹에 기여한 소식이 꽤 멀리까지 퍼졌습니다. 오늘 무슨 용무로 저를 찾아오셨습니까?'),
(684, '안녕하세요, $C님. 보고서를 작성하실 예정이신가요?'),
(685, '안녕하세요. 제출하실 보고서가 있으신가요?'),
(689, '$n, $n, $n! 설리 발루를 기리는 내 걸작을 시작할 만큼 충분한 알터랙 화강암이 있다고 말해줘.'),
(691, '$n, 지금까지 운이 좀 있었나?$B$B$B$B내 조사가 맞다면, 송곳니는 위더바크 트롤이라면 누구에게서든 얻을 수 있을 거야. 약주머니는 위더바크 주술사에게서, 그리고 위더바크 그림자 사냥꾼 중 가장 강한 자들은 통과의례를 마친 후 받는 특별한 칼을 가지고 있을 거고. 어떤 그림자 사냥꾼이 그 칼을 가지고 있는지는 전투를 해보기 전까지는 알 수 없어.'),
(692, '그 조각들을 찾았어?! 그녀를 다시 가두려면 미즈라엘의 두루마리가 필요할 거야, 너무 늦기 전에!'),
(693, '우리의 목표는 마법 지팡이 $n입니다. 지금은 거기에 집중하세요.'),
(694, '$n님, 안녕하세요. 혹시 푸른 마노를 찾으셨나요?'),
(696, '이렇게 하면 말린이 분명히 아주 만족해할 거예요.'),
(697, '네? 왠지 낯이 익네요. 죄송하지만, 혹시 만난 적이 있나요? 제가 너무 바빠서 헷갈리네요.'),
(698, '록타르, $C. 늪지를 통과하는 것은 결코 가볍게 여길 수 있는 위험이 아닙니다. 이곳에서 당신의 용기를 시험하다니 정말 대단하십니다.'),
(699, '맛있는 벌꿀술, 따뜻한 불, 오크 군대, 그리고 무기고… 해안가에서 우리에게 필요한 건 그게 전부야. 스토나드를 지키는 내 임무를 후회하진 않지만, 언젠가 굴이나 하다못해 망루라도 하나 가질 수 있으면 좋겠지.'),
(701, '준비는 다 끝났고, 이제 맹금류 심장만 있으면 돼.'),
(702, '또 돌아왔느냐? 사실 지금 내가 바라는 건 토르간의 동정뿐이다. 이번엔 뭘 가져왔느냐? 혹시 알록달록한 실타래라도? 아니면 이 고통을 끝낼 밧줄이라도?'),
(703, '안녕하세요, $n님. 제 날개를 가져다주셨나요?'),
(704, '$n, 그 항아리들을 찾았나요? 우리는 그것들과 트로그 사이의 연결고리를 찾아야 해요!'),
(705, '내 진주 가져왔어? 섬광탄 거의 다 떨어졌어!'),
(706, '사냥은 어떻게 진행되고 있나요, $C?'),
(709, '태블릿을 찾았나요? 그 안에는 분명 비밀이 담겨 있을 거예요! 우리를 구할 비밀이요!'),
(710, '이곳은 제 최신 프로젝트를 테스트하기에 완벽한 장소네요. 잠시만 이 부분을 제자리에 고정해 주시겠어요? 네, 바로 이렇게 벡터 법선 방향으로요. 아, 제가 무슨 말을 하고 있었더라... 아, 맞다. 제 최신 프로젝트를 테스트하기에 딱 좋은 곳이죠. 원재료도 풍부하고, 탁 트인 공간도... 지적이고 깨어있는 예술가에게 이보다 더 바랄 게 뭐가 있겠어요?'),
(711, '$n, 아주 기쁩니다. 제 마법이 예상대로 작은 조각들에 효과를 발휘했습니다. 이 실험이 제가 예상한 대로 성공적이라면, 제가 조종할 수 있게 될 정령들은 이전에 소환된 그 어떤 정령들보다 훨씬 강력할 겁니다.'),
(712, '찾아주신 돌판들은 정말 훌륭했어요, $n. 루시앙이 여기서 일이 끝나면 남은 돌판들을 카라노스로 가져갈 겁니다. 어쨌든 다시 유용하게 쓰일 수도 있으니까요. 예를 들어, 제가 고위력 폭발물에 대한 다학제적 접근 방식을 연구하기 시작하면, 그 돌판들을 이용해서 간이 대피소를 만들면 좋을 것 같아요.'),
(713, '제가 필요한 기름을 찾으셨나요? 찾으시면 정말 큰 도움이 될 거예요.'),
(714, '네, 네, 네. 잠시만 기다려 주세요.'),
(715, '그는 거의 마무리 단계에 접어들고 있어요. 당신 쪽은 어떻게 진행되고 있나요?'),
(716, '그 팔찌를 너무 오래 미루지 않는 게 좋을 거예요. 앞으로 무슨 일이 일어날지 누가 알겠어요?'),
(717, '강력한 마법과 힘으로 드레이크들이 오랫동안 감옥에 갇혀 있었지만, 블랙래시와 헤마투스가 풀려날 가능성은 절대 용납할 수 없습니다.'),
(718, '사막에서 배고프면 정말 끔찍한 일이 벌어지곤 해, 친구. 어... 저기 저건 뭐지...?'),
(719, '섀도우포지가 무엇을 찾고 있었는지는 확실하지 않지만, 분명 어떤 목적이 있었던 것 같다.'),
(722, '섀도우포지 일족은 위험합니다. 조심하세요. 당신은 반드시 부적을 찾아야 합니다.'),
(723, '오늘은 정말 안 좋은 날이었다고 말하고 싶지만, 여긴 배드랜드잖아요. 매일이 다 안 좋은 날이죠.'),
(724, '아, 그렇군요. 또 드워프에게 무언가를 구하는 여행자시군요. 죄송하지만, 지금은 쓸데없는 질문에 답할 시간이 없습니다.'),
(725, '음? 네, $c.'),
(727, '안녕하세요. 제 가게에 오신 것을 환영합니다. 하지만 무엇을 만지시는지 조심하세요. 지식은 치명적일 수 있습니다.'),
(728, '아, 열정적인 $c님이 계시군요. 제 컬렉션에서 배우러 오셨나요? 좋습니다! 하지만 경고하건대, 지식은 강자에게 힘을 주지만…약자는 미치게 만들 것입니다.'),
(731, '탐사자는 살아 있습니까?'),
(732, '유목민 오거 무리는 황무지를 가로질러 캠프 사이를 이동합니다. 건조한 땅에서 올라오는 열기와 휘몰아치는 바람 때문에 그들의 이동 경로를 추적하기는 어려울 것입니다. 가끔 보프 캠프를 지나간다는 이야기를 들었습니다. 길을 잃었다면 그곳에서 찾아보는 것도 좋겠습니다.'),
(733, '음, 있는 걸로 어떻게든 버텨보긴 했는데… 별로 도움이 안 되네요. 혹시 다른 물품은 찾으셨나요?'),
(735, '제가 부탁드린 유물을 가지고 계신가요?'),
(736, '임무는 잘 진행되고 있나요, $c님?'),
(737, '어머! 오랜만에 오셨군요. 요약본은 받으셨나요?'),
(739, '아그몬드의 행방에 대한 소식이 있나요? 그를 찾았나요?'),
(741, '$r님, 무엇을 도와드릴까요?'),
(743, '윈드퓨리는 치명적인 적이다. 그들의 전투력은 신선한 고기를 향한 욕망만큼이나 강력하다.'),
(744, '이 머리 장식은 분명히 제 남동생에게 훌륭한 선물이 될 거예요.'),
(745, '팔레마 사람들이 땅과 주민들을 좀 더 존중했더라면 이런 갈등은 결코 일어나지 않았을 것이다.'),
(746, '안녕하세요, $n님. 부서진 도구를 가지고 계신가요? 드워프들의 땅 파는 행위는 멀고르의 코도스를 분노하게 할 것입니다. 이 더럽힘을 반드시 막아야 합니다!'),
(747, '부족에게 고기와 깃털을 제공하는 것은 족장 앞에서 사냥꾼으로서의 자질을 증명하는 첫 번째 단계입니다.'),
(748, '$n, 발과 발톱이 있나요?'),
(750, '부족에게 가죽을 제공해 주실 수 있다면, 당신의 관대한 행동을 아버지이신 호크윈드 추장께 전해드리겠습니다.'),
(751, '안녕, $n. 벤처 컴퍼니가 우리 고향에서 추진하는 계획과 작전에 대해 새로운 정보를 얻었나? 만약 그들이 다른 나라들처럼 우리 땅도 착취하려 한다면, 아웃러너들은 신속히 그 일을 막을 것이다.'),
(753, '평원에서 돌아오신 것 같군요. 위대한 어머니 호크윈드에게서 소식 들으신 게 있나요?'),
(756, '$n, 내가 가져오라고 보낸 발톱은 가지고 있나? 썬더혼 우물은 시간이 지날수록 점점 더 오염되고 있어!'),
(757, '$n, 힘의 의식을 완료했습니까? 우리 부족의 적, 브리슬백에 맞서 당신이 보여준 용맹함을 증명할 증거가 필요합니다.'),
(759, '$n. 제가 부탁드린 이빨 있으세요?'),
(761, '$n, 그 새들을 찾았나요? 그 새들의 깃털은 가지고 있나요?'),
(762, '시간이 촉박합니다. 라그나로스는 우리가 준비할 시간을 기다려주지 않을 겁니다.'),
(763, '$c님, 무슨 일로 저희 마을에 오셨나요?'),
(764, '벤처 컴퍼니는 멀고어에서 채굴권을 거부당했지만, 그들은 거절을 쉽게 받아들이지 않는 것 같습니다. 우리 타우렌족은 돌려 말하는 법이 없으며, 우리의 뜻을 전달하는 다른 방법들을 가지고 있습니다.'),
(765, '벤처 컴퍼니가 이윤이라는 미명하에 우리에게 저지를 만행을 생각하면 분노가 치밀어 오릅니다.'),
(766, '열이 점점 심해지고 정신은 악몽 속으로 빠져드는 것 같아… 할아버지께서도 물리치지 못하신 짐승을 내가 감당할 수 있을 리 없다는 걸 알았어야 했는데… 치료제 재료를 가지고 계신가요? 빨리 치료하지 않으면 죽을 것 같아요.'),
(768, '안녕하세요. 사냥은 하셨나요? 혹시 저에게 줄 가죽이 있으신가요?'),
(769, '$n님, 제 물품 가지고 계신가요?'),
(771, '우물 주변에서 충분한 우물돌을 모으고 나무 아래에서 호박색 수수 열매를 모으면, 내가 예언자의 물을 준비해 드리겠습니다.'),
(776, '아라체아를 찾아냈나요?'),
(777, '톱니바퀴, $n, 톱니바퀴!'),
(778, '제가 예상했던 결과는 아니네요. 제 수갑 좀 돌려주시겠어요?'),
(779, '이곳에는 자수정 룬스톤, 오팔 룬스톤, 다이아몬드 룬스톤을 위한 세 개의 움푹 들어간 홈이 있는 지구의 인장이 놓여 있습니다.'),
(780, '배틀보어들의 공격성이 점점 심해지고 있습니다. 그들에게 분명한 경고를 보내고 코와 옆구리 부분을 좀 되찾아 오셨나요?'),
(781, '$n님, 표정에 걱정이 가득하시네요. 무슨 소식이 있으신가요?'),
(782, '토그룬의 배신이라니... 오우거들이 더 이상 호드에 속하지 않게 된 것도 놀랄 일이 아니겠는가? 그가 죽고 대지의 표식이 돌아오면 정말 기쁠 것이다. 아직 그를 처치하지 않았다면, 지체 없이 보프 진영으로 가라. 카르가스 남동쪽에 있다.'),
(784, '$n, 자네에게 명령이 내려졌네. 듀로타르의 안전이 위태롭네. 주어진 임무를 완수하든지, 아니면 수치스럽게 고개를 숙이게 될 것이네.$B$B명예를 증명하고 티라가르드 요새의 인간들을 물리치시오.'),
(786, '켄타우로스들은 호드에게 끊임없이 골칫거리였다. 그들이 우리 고향을 포위하려는 의도는 용납할 수 없다.'),
(788, '$n, 설마 벌써 임무를 완수했다고 말하려고 돌아온 거요? 그런 거라면 당신 다시 봐야겠는걸.'),
(789, '전갈 껍질이 아무리 두껍다 해도 용맹함을 갖춘 전사에겐 큰 문제가 되지 않는다오. 이길 수 있다는 마음가짐으로 강하게 내리치다 보면 전갈도 어려운 상대가 아니란 걸 곧 알게 될 거요.'),
(790, '아... 아버지는 늘 내가 별 볼일 없는 사람이 될 거라고 하셨는데, 이렇게 나무 아래 누워 생명이 서서히 꺼져가는 걸 보니, 아버지 말씀이 맞았던 것 같아 두렵다. 적어도 내 마지막 적이 죽었다는 걸 알고 죽고 싶다.'),
(791, '나는 이 땅이 개척되던 시절, 대족장과 함께 자랑스럽게 싸웠다. 전투의 상처가 내 피부에 새겨져 있다. 아르키몬드를 물리치고 인간, 엘프와 불가피한 동맹을 맺었을 때, 나는 도끼와 함성으로 호드의 명예를 지켰다. 하지만 파수꾼이자 공급자로서의 내 역할은 내게 새로운 자존감을 주었다.'),
(792, '불타는 검에 맞서 당신의 실력을 증명하려면 먼저 그 사악한 소환수들을 물리쳐야 합니다. 그것을 해낸 후에 제게 돌아오십시오.'),
(793, '용족보다 더 치명적인 적은 드물고, 블랙래시와 헤마투스처럼 맹렬하게 싸운 용 또한 드물었다.'),
(794, '임무는 완료했나, $n?'),
(795, '이곳에는 자수정 룬스톤, 오팔 룬스톤, 다이아몬드 룬스톤을 위한 세 개의 움푹 들어간 홈이 있는 지구의 인장이 놓여 있습니다.'),
(806, '$n, 피즐을 찾았나? 그와 불타는 칼날의 나머지 일당은 우리 땅에서 완전히 몰아내야 해!'),
(808, '$n, 내 동생 두개골 가지고 있어? 걔 드디어 풀려난 거야?'),
(812, '지금 모습 그대로 센진으로 돌아갈 수 없다는 게 오히려 다행인 것 같아. 내 나약함과 어리석음은 분명 조롱거리가 될 테니까.'),
(813, '명심하십시오. 어떤 동물을 사냥하든, 그 동물을 연구하고 행동을 이해하는 것이 좋습니다. 그러한 지식은 당신의 생명을 구할 수 있습니다.'),
(815, '아침, 점심, 저녁! 어떤 식사든 상관없어. 어쨌든 누군가는 요리해야 하잖아. 바로 내가 말이야!'),
(816, '크론이 내게 돌아오기를 기도하지만, 그의 운명은 이미 거의 확정된 것 같다.'),
(817, '제 첫 호랑이 사냥이 기억납니다. 에코 제도에서 가장 큰 섬을 사냥터로 정하고, 거의 하루 종일 숲 그늘에 꼼짝 않고 앉아 지켜보고 기다렸습니다. 온몸의 근육이 긴장했고, 공격할 준비가 되어 있었습니다. 마침내 호랑이가 미끼를 물었을 때, 그것은 제 인생 최고의 승리 중 하나였습니다.'),
(818, '시간은 당신의 진정한 힘과 의지를 시험하는 척도입니다. 인내심을 잃거나 나약함에 굴복하면 당신의 진정한 모습이 드러날 것입니다.'),
(819, '예?'),
(821, '수색은 어떻게 진행되고 있나요?'),
(822, '$n, 그 재료들을 구하느라 열심히 노력하고 있구나?'),
(824, '안녕하세요. 저는 물, 그러니까 물의 모든 요소들을 연구하는 데 많은 시간을 보내요. 너무 몰두하다 보니 가끔은 주변에 누가 있는지도 모를 때가 있어요. 혹시 도와드릴 일이 있으신가요?'),
(825, '인간들이 사용하는 기묘한 기계 장치의 작동 방식을 알게 되면, 앞으로의 전투에서 그들을 물리칠 가능성이 훨씬 높아질 것이다. 우리가 새롭게 얻은 지식으로 호드는 더욱 강력해질 것이다.'),
(826, '잘라잔이 패배했나요, $n?'),
(827, '$n님, 스컬 록에 들어가 보셨나요? 시어링 칼라는 가지고 계신가요?'),
(829, '$c 님, 진심으로 인사드립니다. 오늘 $r 형님을 어떻게 도와드릴 수 있을까요?'),
(830, '$c님 얼굴에 걱정스러운 표정이 보이네요. 무슨 일이에요?'),
(831, '제가 바쁜 거 안 보이세요? 정말 급한 일이어야 할 텐데요...'),
(832, '당신은 뭔가 중요한 것을 보고해야 할 것 같군요. 당신의 눈빛에서 그걸 느낄 수 있어요.'),
(833, '브리스틀백 침입자들은 우리의 신성한 매장지에서 반드시 쫓아내야 합니다.'),
(834, '오해하지는 마. 내가 얼마나 일을 잘한다고! 하지만 지금 상황에서 내가 뭘 어쩌겠어? 모래로 성이라도 지을까?'),
(835, '내 상사인 개즐로 같은 사람에게서 그런 말을 듣다니 믿기 어렵겠지만, 그는 항상 상황을 꿰뚫어 보고 있는 것 같았다. "큰 발걸음을 내딛는 걸 두려워하지 마."라고 그는 말했다. "하피들이 계속 우리를 괴롭히고, 캐러밴들이 공격받는 것도 우리가 뭔가 조치를 취하지 않으면 멈추지 않을 거야, 그렇지?"'),
(837, '퀼보어들이 어느 정도 지능과 조직력을 갖추고 있다는 점은 인정하지만, 그들이 칼림도어에서 그토록 넓은 영토를 점령하고 유지할 수 있었다는 사실은 늘 놀랍습니다. 어쩌면 그들은 제가 생각하는 것보다 훨씬 더 교활한 적일지도 모르겠습니다...'),
(840, '꼬맹아, 뭘 원하는 거니? 모집하러 온 게 아니라면 너랑 얘기할 시간 없어.'),
(841, '자, 물 주머니 10개는 다 가지고 계세요?'),
(842, '어이쿠, 이게 누구지? 카르갈이 나를 새로운 신병으로 뽑았나 보군.'),
(843, '벨 모단의 드워프들이 쳐들어왔을 때, 수많은 무고한 타우렌들이 목숨을 잃거나 조상의 고향에서 쫓겨났습니다. 내 땅을 되찾아야 합니다!'),
(844, '평원쥐 부리를 다 모으셨나요?'),
(845, '제브라를 몇 마리나 죽였습니까?'),
(846, '$n, 돌아왔군.$B$B카즈고름의 죽음으로 우리 조상의 땅에서의 발굴 작업이 다소 지연될 수는 있겠지만, 파괴가 완전히 멈추지는 않을 거야.$B$B벨 모단 요새는 점점 더 심각한 군사적 위협이 되고 있어. 발굴 현장을 방어하기 위해 지어졌지만, 이제는 공격 태세까지 갖추고 있지.$B$B내가 요청한 재료가 있다면, 성급한 드워프들이 이 황무지에서 벌이는 행동을 재고하게 만들 폭발물을 만들 수 있어.'),
(848, '포자를 가지고 계신가요, $n님? 저와 동료들은 이 현상을 연구해보고 싶어 합니다...'),
(849, '드워프의 비행기를 파괴하고 나면 복수의 달콤한 만족감을 느낄 수 있을 것이다.'),
(850, '안녕하세요, $n님. 코도바네의 머리를 가지고 계신가요?'),
(851, '베로그를 찾으셨나요, $n?'),
(852, '헤즈룰이 패배했나요, $n?'),
(853, '약제사 헬브림에게서 뭔가를 얻으셨나요?'),
(855, '사냥은 잘 되고 있나요, $n?'),
(857, '달의 눈물은 어디 있지? 지금 당장 필요해! 더 말할 필요가 있겠어!'),
(858, '빨리, 누가 의심하기 전에 여기서 나가야 해!'),
(861, '사냥은 어떻게 진행되고 있나요, $n?'),
(862, '땅굴쥐를 충분히 잡았어, $n?'),
(863, '도와드릴까요?'),
(864, '어서 오세요. 적어도 밀봉된 검사 키트를 가지고 돌아왔다면 말이죠. 그렇지 않다면, 당신의 완전한 무능함을 못 본 척하고 당신이 맡은 임무를 완수할 때까지 분노를 억누르겠습니다.'),
(865, '$n, 리퍼클로 왕의 뿔 얻었어? 내 첫 스마트 드링크를 시험해 봐야겠어!'),
(866, '안녕하세요, $n님. 뿌리 샘플은 받으셨나요?'),
(867, '충분히 잘랐나요? 계속 자르고 전리품을 챙기세요. 마녀날개 발톱 8개가 필요해요.'),
(868, '$n, 네가 찾은 달걀 조심해. 깨지면 나한테 쓸모가 없거든.'),
(869, '$n님, 그 헤드들을 가지고 계신가요?'),
(871, '이러한 공격을 막는 데 시간이 오래 걸릴수록, 교차로 지역 주민들에게 물자를 공급하는 것이 더욱 어려워질 것입니다.'),
(872, '그들의 지도자의 목을 베면 혼란이 일어난다. 이 교훈을 명심하라. 앞으로 큰 도움이 될 것이다.'),
(873, '물을 두려워하지 마세요, $r.'),
(875, '하피 중위 반지 6개를 모두 모았습니까? 호드를 향한 그들의 악랄한 공격에 대한 응징을 반드시 치러야 합니다.'),
(876, '세레나의 얼굴을 보기 전까지는 아무것도 못 줄 거야.'),
(877, '정체된 오아시스에 가보셨나요? 그곳 물 아래에 균열이 있었나요?'),
(878, '브리슬백의 현명한 자들을 처치하고 나면 호드에 대한 더 많은 정보를 얻을 수 있을 거야, $R. <콧방귀> 그 전에는 절대 안 돼! 맹글투스는 바보가 아니거든.'),
(879, '사냥은 어떻게 되어가고 있나, $R? $B$B토크는 자기 부족을 습격하는 자들이 누구인지 진실을 알고 있다고 생각하지만, 자네가 성공한다면 그가 얼마나 틀렸는지 알게 될 걸세. $B$B내 죽음은 피할 수 없지만, 자네가 내 적들에게 큰 고통을 안겨주었으니 맹글투스는 아무것도 후회하지 않네.'),
(880, '또 뭘 가져다주셨죠?'),
(881, '그 멋진 고양이가 당신을 부릅니다, $n.'),
(882, '$n, 이샤무할레를 이겼나요?'),
(883, '$n, 당신이 다가왔을 때 당신의 걸음걸이에서 새로운 힘을 보았습니다. 말해 보세요. 당신의 영혼이 위대한 라코타마니와 만났습니까?'),
(884, '$n, 당신의 눈에 새로운 힘이 깃들었군요! 당신은 위대한 오와탄카를 만난 것이 틀림없어요, 그렇죠?'),
(885, '당신 안에 새로운 결의가 싹트고 있군요, $n. 고통에서 비롯된 결의 말입니다... 와슈테 폰의 죽음이 당신을 짓누르고 있습니까?'),
(887, '해적질로 잃은 수익은 생각하기도 싫은데, 이제는 내 집 바로 앞에 진을 치다니? 이건 너무 심하잖아. 언더마인이 뭔가 조치를 취해야 해.'),
(888, '$n, 내 물건 찾았어?'),
(889, '맹글투스에게 피의 파편 10개를 가져오면 엄청난 속도를 축복해 주겠다. 제브라와 함께 달릴 수 있고 바람조차 너를 부러워할 것이다. 오래가지는 않겠지만, 황무지를 누비는 데는 충분할 것이다.'),
(890, '다음 배로 보낼 물품, $n?'),
(891, '전사한 용사들의 훈장으로 내 손을 가득 채운다면, 나는 쓰러진 나의 사략선 선원들에게 복수가 이루어졌음을 알게 될 것이다.'),
(892, '그렇다면 디지윅은 뭐라고 말했을까요?'),
(893, '나 역시 그 보잘것없는 퀼보어들이 대장장이 기술에 조금이라도 능숙할 수 있을지 의심스럽지만, 대족장의 명령대로 해야 하니 레이저메인 부족에 대해 알아볼 수 있는 것은 무엇이든 배우겠다. 나는 그보다 더 허드렛일도 해봤고, 오크족에게 도움이 된다면 기꺼이 할 것이다.'),
(895, '무슨 일 있으세요? 제가 도와드릴 일이 있으신가요? 배송할 물품이 있거나, 엔지니어링 관련 업무가 있으신가요?'),
(896, '광부들 중 누가 에메랄드를 발견했는지 알기만 한다면, 일은 식은 죽 먹기일 텐데...'),
(897, '$n, 뭔가 걱정스러워 보이시네요. 황무지에서의 수업은 어떠셨나요? 뭔가 마음에 걸리는 일이 있었나요?'),
(898, '예?'),
(899, '퀼보어가 이 일에 대한 대가를 치를 거야, $n. 맹세해.'),
(900, '제어 콘솔의 깜빡이는 표시등은 주 제어 밸브가 닫히지 않았음을 나타냅니다.'),
(901, '센터 콘솔 조명은 어두워져 있고, 계기판과 다이얼은 모두 0을 가리키고 있으며, 모든 것이 공회전 상태입니다.'),
(902, '어머, 돌아오셨군요, $n! 사모플란지 가지고 계신가요?'),
(903, '사냥은 잘 되고 있나요, $n?'),
(905, '둥지에 가본 적 있어요, $n?'),
(906, '네, 그게 뭐죠?'),
(907, '천둥 도마뱀들은 패배했나요, $n?'),
(908, '심해 핵을 찾는 데 성공했습니까? 그것 없이는 황혼의 망치가 심해에서 정확히 무슨 일을 꾸미고 있는지 알 수 없습니다.'),
(909, '아, 반가워요, $n. 늘 그렇듯 방금 바다의 파도 소리를 듣고 있었어요. 무슨 일로 이 외딴곳에 오셨어요?'),
(910, '아직 도착 안 했어요?'),
(911, '아직 도착 안 했어요?'),
(913, '끝났나요? 썬더호크를 처치했나요?'),
(914, '악몽의 기억들이 나를 괴롭히네, $n. 송곳니의 우두머리들을 물리치고 그들의 보석을 손에 넣었나?'),
(915, '딸기맛 말고 다른 맛의 아이스크림도 더 많이 만들어줬으면 좋겠지만, 다행히 딸기맛이 제가 제일 좋아하는 맛이에요!'),
(916, '독주머니를 모았나요, $n?'),
(917, '$n님, 그림자실 동굴 안에 들어가 보셨나요? 거미 알을 찾으셨나요?'),
(918, '씨앗 있으세요? 얼른 심고 싶어요.'),
(919, '안녕하세요, $n님. 물가 근처에서 새싹을 발견하셨나요?'),
(921, '달샘에는 영원의 샘물이 담겨 있는데, 이 샘은 우리 세계에 수많은 공포를 불러일으킨 고대의 마법의 근원입니다. 드루이드들은 이 샘의 효능을 이용하고, 파수꾼들은 이 샘을 엘룬 신을 모시는 성지로 숭배하지만, 마법은 누구에게도 금지되어 있습니다.'),
(922, '안녕하세요... 어떻게 도와드릴까요?'),
(923, '웰스프링 호수에 가보셨어요, $n? 거기서 나무 사냥해 보셨어요?'),
(924, '악마의 씨앗은 아직 존재한다. 그 힘이 느껴진다…'),
(925, '오크들이 홀로 남겨져 친구도 없을 때, 타우렌들은 그들을 낯선 땅으로 맞아들였고 아무런 대가도 바라지 않고 그들과 함께 나누어 주었다. 그것이 바로 명예다, $n.'),
(927, '$n! 저한테 줄 거 있으세요?'),
(928, '안녕하세요, $c님. 무슨 용건으로 이렇게 만나 뵙게 되었습니까?'),
(929, '안녕하세요, $n님. 작업은 완료하셨나요?'),
(930, '$n, 뭔가 할 말이 있는 것 같군요. 혹시 나무들에 관한 소식이 있나요?'),
(931, '저에게 주실 게 있으신가요?'),
(932, '멜레나스 경을 처치했습니까? 그를 신속하고 조용히 처리하는 것이 매우 중요합니다, $n. 그가 아직 살아 있다는 것은 우리 모두에게 수치스러운 일입니다.'),
(933, '다시 뵙게 되어 반갑습니다, $n. 코리트라스 문레이지를 위해 달샘물을 모으는 데 성공하셨군요. 그 과정에서 많은 것을 배우셨기를 바랍니다.'),
(934, '드루이드들과 함께 오라클 트리와 대천사 $C는 텔드라실의 성장을 면밀히 관찰해 왔습니다. 하지만 새로운 보금자리를 찾았다고 해서 우리의 불멸의 삶이 되찾아진 것은 아닙니다.'),
(935, '다시 뵙게 되어 반갑습니다. 당신이 곁에 계셔서 타린드렐라의 임무가 순조롭게 진행된 것 같군요.'),
(937, '그들의 날카로운 발톱과 뾰족한 부리는 당신의 능력으로는 감당하기 어려울지도 모르지만, 저는 당신이 이 임무에 실패하지 않을 것이라고 믿습니다.'),
(938, '안개... 내 잘못이야! 마녀들이 날 방심하게 만들었어... 널 데려가게 놔두지 말았어야 했는데...'),
(939, '무슨 일이야, $C? 걱정스러운 표정이네.'),
(940, '음... 자네는 숲의 정령을 강하게 지니고 있군, $c. 칼도레이의 대드루이드와는 무슨 용무가 있나?'),
(941, '이 화분에는 데날란에서 특별히 준비한 흙이 채워져 있습니다.'),
(942, '친구, 그거 뭐 들고 있어?'),
(943, '렐루의 돌을 이용하면 내 화석과 다크쇼어에 있는 렘트래블의 화석에 숨겨진 비밀을 밝혀낼 수 있을 것이다.'),
(944, '마스터의 글레이브, 그곳으로 가서 다시 나와 이야기해.'),
(947, '$n, 내 버섯 가지고 있어? 동굴에 가봤어?'),
(950, '$n. 당신은 돌아옵니다.'),
(951, '$n. 마티스트라 유적을 샅샅이 뒤진 보람이 있었나요?'),
(952, '아, $c. 오누 씨가 어떻게 도와드릴까요?'),
(953, '당신이 석판을 연구하여 아메스아란의 몰락에 대해 알게 되면, 저는 그 지식을 오버딘으로 가져가 고대인들의 모임에 알리겠습니다.'),
(955, '귀걸이를 손에 넣는 순간, 나를 묶고 있는 봉인의 행방을 찾는 마법을 시전할 것이다. 수 세기 동안 나는 그 봉인을 파괴하면 얻게 될 자유를 꿈꿔왔다… 어쩌면 그 세월이 내 정신에 회복 불가능한 상처를 남겼을지도 모른다…'),
(956, '이 신전의 기둥들은 내게 감옥의 창살과 같다, $n. 내게 남은 어떤 힘으로도 그것들을 부술 수 없고, 어떤 마법으로도 파괴할 수 없다… 천 년이 넘는 세월 동안 나는 그것들을 바라보며 생각했다. 마침내 내가 이 돌보다 오래 살아남는다면, 과연 자유로워질 수 있을까? 아니면 그때 나를 가두고 있는 것은 보이지 않는 창살일까…'),
(957, '사실, $n, 저는 두려워요... 당신이 오는 것, 이 모든 것이 그저 정신 나간 사람의 망상일까 봐 두려워요. 이게 얼마나 고통스러운지 아시나요? 저는... 제발, 빨리 가주세요.'),
(958, '만약 우리 세계를 파괴한 대재앙 속에서 그들의 파멸을 초래할 도구들이 함께 파괴될 수 있었다면 얼마나 좋았을까... 그럼에도 불구하고, 우리는 과거의 끔찍한 일들이 미래에 되풀이되지 않도록 우리가 할 수 있는 모든 것을 해야 한다.'),
(959, '부두 관리인은 미친 매글리쉬가 99년산 포트 와인을 훔쳐간 이후로 계속 나를 괴롭히고 있어. 아마 그 와인은 레빌가즈 남작이 가즈로에게 선물하려고 했던 거겠지. 만약 네가 용기와 인내심을 갖고 미친 매글리쉬를 찾아내서 그 포트 와인을 되찾아온다면, 내가 좋은 보상을 해줄게.'),
(962, '당신이 울부짖는 동굴에서 충분한 뱀꽃을 모을 수 있을지 정말 궁금합니다. 제 명령을 수행하도록 많은 뱀들을 보냈지만 아무도 돌아오지 않았습니다.'),
(963, '깊은 슬픔을 품고, 나는 샨도 스톰레이지를 따라 동면에 들어갔고, 그 슬픔을 꿈속으로 가져가 수천 년 동안 잠들었다.'),
(964, '$c, 많이 죽이고 자주 죽여라. 열쇠의 외피를 만들려면 적당한 해골 조각이 꽤 많이 필요할 테니까. 괜히 해골 열쇠라고 부르는 게 아니란다.'),
(966, '그들의 두루마리를 더 찾으셨나요? 그것들을 찾으시면 그 종교 집단의 전체적인 모습을 파악하는 데 도움이 될 것 같습니다.'),
(967, '저랑 볼일이라도 있으신가요, $c?'),
(968, '안녕하세요, 선생님. 제 책 중 한 권에 관심 있으신가요?'),
(969, '파편들을 다시 가져오면, 더 자세히 알려줄게!'),
(970, '영혼의 보석을 얻으셨나요?'),
(971, '애쉬엔베일로 가는 길은 멀고, 당신의 임무는 쉽지 않습니다. 하지만 원고를 제게 가져다주신다면, $n… 그만큼의 보상을 드리겠습니다.'),
(973, '$n님, 좀 놀라신 것 같네요. 괜찮으신가요?'),
(974, '저도 직접 가보고 싶지만… 거기 있는 불의 정령들이 좀 무서워요!'),
(976, '파수꾼들은 다크쇼어에서 전력을 보강하기 위해 많은 보급품이 필요합니다.'),
(977, '털 붙이는 작업은 거의 다 끝났어, $n. 어서 뿔 좀 가져와!'),
(978, '이러한 힘은 어디에서 비롯되었을까요? 저는 우리가 그 답을 찾을 수 있는 올바른 방향으로 가고 있다고 생각합니다, $n.'),
(982, '그 배들의 선장들은 훌륭한 나이트 엘프였고, 그들은 마땅히 받아야 할 더 나은 운명을 맞이했어야 했다. 어쩌면 그들의 유품을 정리해 주는 것이 그들의 영혼을 편히 쉬게 하는 가장 좋은 방법일지도 모른다.'),
(983, '버즈박스 827은 섬뜩한 정적 속에 놓여 있다. 깜빡이는 불빛 하나는 보관함에 크롤러 다리 6개를 넣어야 함을 나타낸다.'),
(984, '$n님, 검색은 잘 진행되고 있나요?'),
(985, '얘야, 해야 할 일을 주저하지 마라. 숲의 생물들을 죽이는 것이 얼마나 혐오스러운 일인지 알지만, 이번 경우에는 어쩔 수 없다. 숲에 퍼진 타락을 막을 방법은 아직 발견되지 않았고, 그 방법이 발견될 때까지 우리는 그 확산을 막기 위해 할 수 있는 모든 것을 해야 한다.'),
(986, '내가 너를 위해 그 망토를 만들어주기 전까지는 양심상 네가 볼코르를 찾아가는 것을 허락할 수 없어.'),
(992, '신입 측량사 $n님, 다시 오신 것을 환영합니다! 과제는 완료하셨나요?'),
(995, '네, $n?'),
(996, '당신은 병들고 변질된 듯한 바람꽃 식물을 발견했습니다. 식물에 매달린 열매는 썩어 독성이 있는 것으로 보입니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(997, '저에게 주실 게 있으신가요?'),
(998, '당신은 병들고 변질된 듯한 바람꽃 식물을 발견했습니다. 식물에 매달린 열매는 썩어 독성이 있는 것으로 보입니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(1001, '기계의 덮개가 열려 있고, 마치 3개의 탈곡기 눈이 안에 넣어지기를 기대하는 듯 보입니다.'),
(1002, '아직 달추적자 송곳니 6개를 안에 넣지는 않았지만, 안에서 잡음과 알아들을 수 없는 노움의 중얼거림이 들리는 것 같습니다. 혹시 누군가 벌써 기계를 고쳐놓은 걸까요?'),
(1003, '버즈박스 525에서 노래 소리가 들려옵니다. "크롤러 와인도 달콤하고, 스레셔 에일도 훌륭하고, 문스토커 문샤인도 끝내주지만, 엉겅퀴 곰 맥주만큼 귀한 건 없지. 그러니 당장 손에 쥐고 있어야겠어!" 뚜껑이 열려 있고, 4마리의 험상궂은 녀석들이 기다리고 있습니다. 노래가 계속해서 반복되는 동안 말이죠.'),
(1007, '조각상을 찾으셨나요, $n님?'),
(1008, '우리는 나가족이 우리 해안을 침략하는 것을 용납할 수 없습니다, $n. 조람 해변으로 가서 임무를 완수하는 것이 매우 중요합니다.'),
(1009, '조람의 반지가 도시 안의 모든 자물쇠를 열 수 있는 열쇠라고 전해집니다. 혹시 그 반지를 가지고 계신가요, $n?'),
(1010, '바트란의 머리카락을 모았습니까, $n? 아이의 건강이 시간이 지날수록 악화되고 있습니다...'),
(1011, '캠프를 찾았나요, $n? 질병이 든 병을 가지고 있나요?'),
(1012, '도르다닐 드루이드들의 고통이 아직도 내 꿈을 괴롭힌다, $n. 그들의 지도자들을 반드시 제거해야 한다!'),
(1013, '$n님, 책 찾으셨나요?'),
(1014, '아루갈의 죽음으로 우리는 로데론에서 어둠의 여왕의 세력을 더욱 강화할 수 있게 되었습니다.'),
(1016, '정령을 처치하려면 팔찌를 파괴해야 하므로, 점술 두루마리에 필요한 정보가 담긴 특정 팔찌를 찾는 것은 어려울 수 있습니다. 다른 사람과 팔찌를 교환하여 필요한 팔찌를 얻거나, 아니면 이미 점술 종이를 가지고 있을 수도 있습니다.'),
(1017, '끝난 건가요? 사릴루스 파울본은 죽었나요?'),
(1020, '죄송하지만 지금은 통화할 시간이 없습니다. 제 아이 렐라라가 몹시 아픕니다!'),
(1022, '신전의 서적은 신비로운 물건입니다. 그것은 전통적인 의미의 책이 아닙니다. 서적의 페이지들은 멜탄드리스 여신께서 직접 축복하셨으며, 그 안에는 중요한 사건들이 기록되어 있습니다. 제가 설명하기는 어렵습니다. 신전에 가보시면 이해하실 수 있을 겁니다.'),
(1023, '아, 다시 오신 걸 환영합니다, $n님.'),
(1024, '안녕하세요. 어떻게 지내세요?'),
(1025, '퍼볼그족이 항상 우리의 적은 아니었소, $n. 하지만 시대는 변했고, 이 어두운 숲에는 더 이상 평화가 없소.'),
(1026, '나무 정령들이 타락해 버린 것이 너무나 안타깝습니다. 그들을 도울 수 있는 일이 더 많았으면 좋겠습니다.'),
(1027, '$n, 낚싯대의 마지막 조각을 찾으셨나요?'),
(1028, '사당과 주변 나무들에서 미묘하지만 강력한 기운이 느껴집니다. 지팡이를 사당 안에 놓기 시작하자, 사당이 빛나기 시작하면서 주변에서 부드러운 진동 소리가 들려옵니다...'),
(1031, '그들을 찾았나요? 아닐리아는 뭐라고 했어요? 그녀는 어디에 있나요?'),
(1032, '제발, 아닐리아의 죽음에 대한 복수를 할 수 있도록 도와주세요.'),
(1033, '$n, 아이리스 호수를 찾았나요? 눈물은 가지고 있나요?'),
(1034, '$n님, 스타더스트를 가지고 계신가요?'),
(1035, '$n, 당신은 섀이드시켓 오라클과 맞섰습니까? 그렇다면 떨어진 월장석을 제게 넘겨주십시오. 렐라라는 이제 숨을 몇 번 쉴 힘밖에 남지 않았습니다!'),
(1038, '무슨 걸 알아냈어?'),
(1043, '준비되지 않은 자에게 숲은 위험합니다. 무기를 가까이 두고, 정신은 더욱 바짝 차리십시오. 그렇지 않으면 으스스한 숲으로의 다음 여정이 당신의 마지막이 될지도 모릅니다.'),
(1045, '친구여, 란을 처치했습니까? 나이트 엘프조차도 그의 분노를 받을 자격은 없습니다. 그의 증오는 저보다 훨씬 더 강렬하지만, 그의 정신은 더 이상 그의 것이 아닙니다. 그는 이 숲의 모든 생명체에게 위협적인 존재입니다.'),
(1046, '센티넬들은 애쉬엔베일에서 할 수 있는 모든 것을 다하고 있지만, 우리가 이만큼의 성과를 거둘 수 있었던 것은 여러분과 같은 인간들 덕분입니다.'),
(1048, '내 명령이 명확하지 않았던 것 같군, $c. 나는 고위 심문관 화이트메인을 완전히 제거하길 원한다. 그리고 김에 그녀의 상관들도 함께 처리해라.$B$B그 광신도, 스칼렛 사령관 모그레인을 죽여라. 스칼렛 챔피언 헤로드도 쓸어버려라. 그리고 사냥개 조련사 록시와 그의 더러운 개들도 몰살시켜라.$B$B이제 사라져라!'),
(1049, '케른은 용감하고 고결한 지도자이며, 나는 내 목숨을 걸고 그를 믿을 수 있다. 하지만 지금과 같은 정치적 상황에서는 다른 사람들을 믿을 수 없다. 모든 정보를 모을 기회가 생기면 족장께 현명한 조언을 드릴 수 있을 것이다. 티리스팔 숲이나 붉은 수도원에 가보셨나? ''타락한 자들의 총서''는 이 복잡한 퍼즐의 한 조각일 뿐이다…'),
(1050, '이 수도원은 팔라딘 수련생들을 위한 신학교였습니다. 한때 빛의 요새였던 이곳은 광기에 사로잡힌 붉은 십자군의 손에 넘어갔습니다. 십자군은 언데드 역병으로부터 땅을 정화한다는 고귀한 목표를 추구했지만, 광기가 그들의 목적을 더럽혔고, 이제 그들은 모두의 적이 되었습니다. "티탄의 신화"를 제게 가져다주십시오. 제가 연구하고 아이언포지에 보관하겠습니다. 타락한 수도원의 복도는 그런 역사적인 보물을 위한 장소가 아닙니다.'),
(1051, '낯선 이여, 당신은 무엇을 원하십니까?'),
(1052, '거기 누구세요? 저한테 뭘 원하시는 거예요?'),
(1053, '수도원의 부패는 최고위 관리들이 제거될 때까지 끝나지 않을 것이다. 빛의 이름으로, 대심문관 화이트메인, 스칼렛 사령관 모그레인, 스칼렛 챔피언 헤롯, 그리고 사냥개 조련사 록시를 처단하라. 그들이 쓰러지면 비로소 진정한 대의가 다시 살아날 수 있을 것이다. 그때까지 십자군의 길을 가로막는 자는 누구든 위험에 처할 것이다. 사우스쇼어에서 나아가 그들을 처단하라!'),
(1054, '퍼볼그족의 타락으로 인해 아셴베일은 과거의 영광을 잃고 초라해졌다.'),
(1057, '불에 탄 계곡을 예전처럼 울창한 숲으로 되돌리기까지는 해야 할 일이 산더미 같습니다. 그 지저분한 괴물들을 없애버려야 합니다! 그래야만 비로소 자연의 섭리를 되찾을 수 있을 것입니다.'),
(1058, '불쌍한 우리 엘프 친구들을 좀 봐. 뛰어놀 숲도 없이 우리에 갇혀 있잖아! 자, 혹시 수액 좀 구할 수 있었나? 황혼의 달리기 선수 수염은? 혹시 요정 용의 비늘은 없나? 그리고 눈! 눈이 많이 필요해! 눈이 듬뿍 들어가지 않으면 강력한 숲 마법 물약을 만들 수 없거든!'),
(1060, '당신은 좀 수상해 보이는데요. 제가 볼 만한 게 있으신가요?'),
(1062, '그레이트우드 계곡은 북서쪽에 있습니다. 가십시오! 이 땅을 약탈하려는 자들에게 공포를 심어주십시오!'),
(1065, '아, 제 새로운 실험 대상들과 함께 오셨군요?'),
(1066, '신디케이트 섀도우 마법사들을 찾아내서 그들의 피를 얻었습니까?'),
(1067, '돌아왔군요, $n. 약제사 라이던의 도움을 가져왔습니까?'),
(1068, '나무 정령들이 동족을 잃은 슬픔에 통곡하고 있습니다, $n. 파쇄기 XT:4와 XT:9를 파괴해야 합니다. 그렇지 않으면 스톤탈론은 결코 치유되지 못할 것 같습니다.'),
(1069, '$n, 계란은 받았어? 부두 관리인 디지윅이랑 이미 배송 계약은 맺었어!'),
(1071, '$n님, 전투는 어떻게 진행되고 있나요?'),
(1073, '물약이 없으면 니트로미르글리세로늄을 만들 수 없어... 그 물약들은 니트로미르글리세로늄을 만드는 데 필수적이야.'),
(1074, '아, 잘됐네, 돌아왔구나.'),
(1076, '안녕하세요, $n님. 제가 필요한 부품을 찾으셨나요?'),
(1077, '하하! 돌아왔구나! 그거 가지고 있어? 그 주문은?'),
(1078, '안녕하세요, $n님. 스톤탈론의 베일에서 그 비늘들을 가지고 돌아오셨나요?'),
(1079, '설계도 받았어, $n?'),
(1080, '어떻게 됐어, $n?'),
(1083, '처음 그을린 계곡을 봤을 때, 나는 거의 울 뻔했다.'),
(1084, '벤처 컴퍼니가 과거에 파편을 어떻게 사용했든 간에, 가심은 분명 그 파편을 활용할 방법을 찾아낼 것 같은 예감이 든다.'),
(1086, '벤처 컴퍼니 공항이 존재한다면, 반드시 찾아야 합니다, $n.'),
(1087, '여기서 마법을 사용하는 것은 구멍투성이 양동이로 우물에서 물을 길어 올리는 것과 같습니다.'),
(1088, '주인께서 내게 스톤탈론 정상으로 가라고 명하셨을 때, 나는 고대 아즈샤라 신전의 신성한 유적을 기어 다니는 나이트 엘프들을 쓸어버리는 일만 하면 될 거라고 생각했다. 그들의 손길이 닿은 곳은 신전의 신성함을 더럽히고 있었기 때문이다… 하지만 오르다누스는 내 손아귀에서 빠져나갔다.'),
(1089, '돌에는 열쇠 구멍 세 개가 새겨져 있다.'),
(1091, '네, $n님? 무엇을 도와드릴까요?'),
(1092, '제가 도와드릴 일이 있으신가요?'),
(1093, '그 설계도 찾았어? 새 상사한테 잘 보이고 싶거든. 내 충성심을 확신하게 되면—물론 완전히 확신할 수는 없겠지만… 고블린의 명예라는 게 있잖아?—내 뛰어난 천재성을 마음껏 활용해 주겠지.'),
(1094, '안녕하세요! 무엇을 도와드릴까요?'),
(1096, '스퍼터밸브는 게렌조가 죽었다는 증거를 원할 겁니다. 아마 그의 기계 팔이면 충분할 것 같네요.'),
(1100, '걱정스러운 표정을 보니 뭔가 잘못된 것 같네요...'),
(1101, '샤를가 레이저플랭크가 레이저펜 크롤에서 병력을 모으는 한, 이 땅은 큰 위험에 처해 있습니다.'),
(1102, '레이저펜 크롤의 흉악한 짐승들이 그 더러운 소굴에서 쫓겨났다는 것을 알게 되면, 복수가 이루어졌다는 생각에 편히 쉴 수 있을 것이다. 자네는 퀼보어를 크롤에서 몰아냈나? 레이저플랭크의 심장을 가져왔나?'),
(1103, '자, 사프타를 가지고 있니, $G 형제/자매?$B$BI는 타락한 물의 정령을 물리친 후에 어려움을 겪은 또 다른 사람을 알고 있어. 너무 오래 기다렸던 탓인지 영혼의 세계에서 너무 빨리 나와 버렸더라고. 다른 사람에게도 그런 일이 생기는 걸 보고 싶지 않아서, 다른 사람이 내 도움을 필요로 하지 않을 때까지 잠시 여기서 기다릴게.'),
(1104, '안녕 안녕 안녕! 독액 맞았어??'),
(1105, '내 동생이 새로운 연료 탱크 설계 작업을 진행하고 있는데, 그게 좀 걱정돼. 나도 최대한 빨리 거북이 등껍질로 만든 연료 탱크 제작에 착수해야겠어! $n, 혹시 등껍질은 구했어?'),
(1106, '자, 날 찾았군. 잘됐군. 내가 가스일조그를 위해 만든 도끼 때문에 온 건가? 아니면 파메이 공작부인의 명예를 되찾으러 온 건가? 사실, 어느 쪽이든 상관없군. 싸우러 온 거라면, 어서 끝내버리지.'),
(1107, '꼬리 지느러미는 있나요? 차가 자체 속도로부터 보호되지 않으면 이런 경주에서 오래 버티지 못할 겁니다.'),
(1108, '혹시 인두륨 조각을 찾으셨나요, $n? 제 화덕을 예열해 놓고 시험해 볼 준비가 되어 있습니다.'),
(1109, '아, 돌아오셨군요. 크롤 구아노는 구하셨나요?'),
(1110, '$n, 플랫츠 지역에 다녀왔어? 내가 원하던 부품들 가져왔어?'),
(1111, '크게 말씀해 주세요! 데려다 주시는 건가요, 아니면 데리러 오시는 건가요?'),
(1112, '라쳇까지 가서 부품들을 얻었나요?'),
(1113, '붉은 수도원에서 돌아왔나? 이 흥미진진한 실험을 위해 하트가 많이 필요하겠소! 틀림없이 바리마트라스와 어둠의 여왕도 붉은 수도원의 쓰레기들을 없애버려서 기뻐하겠지...'),
(1114, '저한테 줄 게 있으세요? 멋지네요! 보여주세요!'),
(1116, '벌써 돌아왔어? 내 꿈의 가루라도 가져갔어?'),
(1117, '나즈 스팀보일에 대해 뭐 알아낸 거 있어? 그가 비밀로 하고 싶어 할 만한 거라도?'),
(1118, '안녕하세요. 당신처럼 고귀한 분이 부티 베이에 무슨 일로 오셨나요?'),
(1119, '안녕하세요, $n님. Fizzlebub님이 저희를 도와주셨나요?'),
(1120, '안녕하세요! 저한테 주실 거 있으세요?'),
(1121, '뭘 보고 있는 거야?'),
(1122, '안녕하세요, $n님. 그 스타우트 맥주는 어땠어요? 꽤 독한 맥주죠?'),
(1124, '이곳은 너무 위험한 땅이니, $c. 무슨 일로 실리투스 황무지에 온 겁니까?'),
(1125, '얼라이언스든 호드든 상관없어. 그 어떤 존재도 고통받는 영혼으로 이 세상에 갇혀 있을 자격은 없어. 이 영혼들을 해방시키는 것이야말로 모든 것을 바로잡을 거야, $n.'),
(1126, '그래서, 성공했나요? 다행히 당신은 무사하네요. 뭐 찾은 거라도 있나요?'),
(1127, '$n님, 잔질 혼합물 가지고 계신가요?'),
(1131, '$n님, 그 사악한 스틸스냅을 물리치셨나요?'),
(1134, '$n, 프라이드윙 독주머니 가지고 있나? 오크들이 짐승의 독을 우리에게 사용하도록 내버려 둘 순 없어!'),
(1135, '$n님, 하이퍼치 찾으셨나요? 거기 있는 와이번들은 어떻게 됐어요?'),
(1136, '$n님, 알터랙 산맥에 가보셨나요? 찾기 힘든 프로스트모우와 맞서 싸우셨나요?'),
(1138, '...레몬 크랩, 휘퍼 루트 크랩, 그리고 아이언포지 서프라이즈 크랩. 그게 다예요. 아, 안녕하세요, $n님. 제가 말씀드렸던 그 고급 게살 덩어리 있나요?'),
(1139, '해머토의 임무는 반드시 완수해야 해, $n. 그에게 그럴 의무가 있어. 네가 울다만으로 돌아가는 건 그 목표 달성뿐 아니라 모든 드워프 종족의 안전을 위해서도 필수적이야. 다크 아이언 드워프들이 석판을 손에 넣으면 그들의 골렘 군대가 얼마나 강력해질지 아무도 모르는 일이지.'),
(1140, '사티로스의 역사가 나이트 엘프의 역사와 어떤 식으로든 관련이 있다는 소문을 들은 적이 있지만, 존경하는 주인님들께서는 그 문제에 대해 말씀하시기를 꺼려하셨습니다.'),
(1141, '다크쇼어 그루퍼로 만들 수 있는 맛있는 요리가 많아요. 그냥 먹어도 맛있지만, 전 잡는 재미가 더 크다고 생각해요. 혹시 다크쇼어 그루퍼 잡아보셨어요?'),
(1142, '무슨 일로 저희 집에 오셨어요, $r?'),
(1143, '아쓰리쿠스 나라신은 고대의 강력한 마법사입니다. 델그렌의 도움을 기다려야 할지도 모르지만, 그가 당신을 혼자 보낸 것을 보면 당신을 상당히 신뢰했던 것 같습니다.'),
(1145, '부럽군, $c. 자네는 오그리마 성벽 밖에서 꽤 오랜 시간을 보낸 사람처럼 보이는군. 나도 스랄 대족장이 내 능력을 필요로 하지 않았다면 대족장의 이름으로 여행을 떠났을 텐데 말이지. 하지만 스랄은 우리를 잘 이끌고 있고, 나는 그의 판단을 믿기에 그가 필요로 하는 한 여기에 남을 생각이네.'),
(1146, '전쟁 때문에 우리 일행은 시머링 플랫츠에 오게 되었습니다. 당신은 무슨 일로 여기에 오셨나요?'),
(1147, '그 경주들을 위해 플랫츠로 향하는 여행객들이 많으니, 모험을 즐기는 사람들을 충분히 설득해서 곤충 떼를 물리칠 수 있을 거라고 확신해요. 우리 일행은 그들이 올 때까지 떠날 수 없어요.'),
(1148, '아, 오랜만이군, $n. 무슨 일로 오셨나? 최근 전투를 많이 치른 듯 보이는데. 잘됐군... 호드에게도 좋고 자네에게도 좋은 일이지. 전투 경험이 많을수록 더 큰 도움이 되고 더 강해질 테니까.'),
(1149, '믿음. 그것은 많은 사람들이 생각하는 것보다 훨씬 더 중요합니다. 때로는 무엇을 믿느냐가 중요하지 않습니다. 중요한 것은 무언가를 믿는다는 사실입니다.'),
(1150, '여러분은 앞으로 닥쳐올 도전에 대비하여 영적으로, 육체적으로, 그리고 정신적으로 준비해야 합니다. 우리는 너무나 자주 준비가 되지 않은 채 서두르곤 합니다. 저는 어떤 부족에 속해 있든 모든 젊은이들이 집을 떠난 후 마주할 수 있는 위험에 대비하도록 돕는 것을 제 의무로 여깁니다.'),
(1151, '록알림은 천 개의 바늘 지대에 사는 켄타우로스 부족들에게 ''주먹질꾼''이라는 별명으로도 불리는데, 이는 그가 용감하거나 어리석게도 그의 길을 가로막는 생물들을 주먹으로 후려칠 때 나는 천둥 같은 소리 때문입니다.'),
(1153, '나는 다시 그 여행자들을 보았다. 내게 광석 샘플을 팔지 않으려 했던 바로 그들이었다. 나는 대족장을 돕지 않은 그들에게 침을 뱉었다. 그들이 비겁하게 전장에서 죽기를 바란다. 호드와 동맹을 맺은 모든 자들은 마땅히 전사로 죽어야 하는데 말이다.'),
(1154, '책을 다 공부한 후에 내게 가져오시오. 책을 받기 전까지는 질문을 하지 않겠습니다.'),
(1160, '스칼렛 크루세이드에게서 책을 훔치기 전에 그들에게 좀 고통을 안겨줬기를 바랍니다. 그들에 대한 제 생각은 근거 없는 것이 아닙니다. 한때 빛의 추종자였을지 모르지만, 이제는 자신들의 종교에 동조하지 않는 모든 존재를 말살하려 합니다. 그들은 언데드, 포세이큰이든 아니든 모두 정화되어야 한다고 믿으며, 그들의 땅을 여행하는 자들은 미쳤거나 언데드의 강력한 마법에 걸린 자들이라고 생각합니다. 멍청이들. 모두 다 멍청하고 바보들입니다.'),
(1164, '모두 죽이고 그들의 머리를 가져오라!'),
(1166, '술이 목마르군. 코담배도 그립고. 금고는 어디 있지? 가서 오버로드 목모록을 찾아와. 옛집 남쪽을 찾아봐. 난 오우거들을 이끌느라 너무 바빠서 못 가.'),
(1168, '목모록은 모든 오우거들에게 이곳에 남아 이곳을 지키라고 말했습니다. 제 생각에 오우거들은 흑룡 군대를 물리치고 옛 고향을 되찾아야 합니다. 당신은 오우거들이 고향을 되찾고 복수할 수 있도록 도와주세요.'),
(1169, '검은 용 군대의 불타버린 자손들의 심장과 혀를 이용해, 어떤 비열한 짐승이 우리 고향에 그 자식들을 풀어놓았는지 알아낼 수 있을 것이다. 침략자에 대한 더 깊은 이해를 통해, 우리는 그들을 완전히 섬멸하고 스톤몰 마을을 폐허에서 되찾을 수 있을지도 모른다. 물론, 목모록을 그 무기력하고 뚱뚱한 몸뚱이에서 이 진흙탕 구덩이에서 나오게 설득하는 것 자체가 하나의 장대한 모험이 될 것이다...'),
(1172, '$n, 드래곤머크로 서둘러 가야 해. 오닉시아의 알들이 와이번보그 곳곳에 흩어져 있어, 빨리 조치를 취하지 않으면 압도적인 적의 공격에 직면하게 될 거야.$b$b그녀의 알을 파괴해! 검은 용의 역병이 우리 고향에 퍼지는 것을 막아야 해!'),
(1173, '나는 네가 목모록을 마을에서 쫓아내려고 할 줄 알았는데, 오히려 나에게 와서 이야기를 나누려는 건가?'),
(1175, '경주 참가자들의 잔해를 치우는 것만으로도 충분히 끔찍한데, 거기에 불에 탄 동물 사체 속에서 그들을 찾아내야 한다니.'),
(1176, '그 뼈대 좀 가지고 계신가요? 조향 장치 경량화 작업을 시작하려던 참이었는데, 필요한 부품이 다 모이지 않은 상태에서는 섣불리 분해하고 싶지 않아서요.'),
(1177, '먹을 걸 내놔, 안 그러면 널 잡아먹을 거야.'),
(1179, '발밑 조심해! 조심 또 조심해!! 여기 보이는 건 아주 섬세한 물건이야, 이기려면 모든 게 완벽하게 작동해야 해!'),
(1182, '인정하기 싫지만, 저쪽 노움 팀은 꽤 잘하는 것 같아. 우리 선수들은 모든 이점을 활용해야 해.'),
(1183, '$n! 연료 조절기를 찾으셨나요?'),
(1187, '좀 더 힘을 북돋아 줄 무언가가 없이는 어떻게 트랙에서 얼굴을 드러낼 수 있겠어? 정말 어처구니없는 일이야.'),
(1188, '아시다시피, 기즈모리움은 여러분의 모든 DIY 요구를 충족시켜 드릴 수 있습니다! 어떻게 도와드릴까요?'),
(1189, '포직이 경주용 자동차에 모래 한 양동이를 올려놓았다는 게 믿어지세요? 좌석 밑에 모래 양동이가 있는데 어떻게 최고 속도를 낼 수 있겠어요?'),
(1192, '저는 경주용 차량의 여러 부분에 인두리움을 사용하고 싶지만, 이 부품들을 제작하려면 대량의 인두리움 원료가 필요합니다. 인두리움 광석은 바다 건너 카즈 모단에 있는 황무지의 울다만 발굴지에서 찾을 수 있습니다. 노움들이 자체적으로 인두리움을 확보하고 있기 때문에, 우리도 그들과 보조를 맞추려면 인두리움을 확보하는 것이 중요합니다.'),
(1193, '당신 앞에는 크고 부서진 덫이 놓여 있습니다. 보아하니 오우거들이 덫을 고치려 애썼지만 소용이 없었던 것 같습니다. 덫 옆에는 급하게 쓴 쪽지가 있는데, 이상하게도 수리에 필요한 것이 정확히 적혀 있습니다. 바로 토륨 부품과 서리 기름입니다. 만약 덫이 수리된다면 근처를 지나가는 오우거가 덫에 걸릴 수도 있고, 그러면 피할 수 있을 겁니다. 오우거들 중 글을 읽을 줄 아는 사람이 거의 없다는 건 참으로 다행스러운 일이죠.'),
(1195, '약병에 물을 채우면 천침공에 있는 내 동료 라우에게 보내면 됩니다. 물이 든 약병을 요청한 건 그였으니, 어떻게 활용해야 할지 더 잘 알 겁니다.'),
(1196, '혹시 잔겐의 지시를 받고 오신 건 아니겠죠?'),
(1197, '나는 갈라진 발굽을 어서 만져보고 싶어. 너는 이미 가져갔니?'),
(1199, '블랙패덤 심연은 한때 고대 나이트 엘프 사원이었습니다. 그곳에는 한때 매우 강력한 달의 샘이 있었죠. 황혼의 망치단이 지금 그곳에서 어떤 악을 만들어내고 있을지 누가 알겠습니까? 그들을 소탕하는 데 진전이 있었습니까?'),
(1200, '시간은 소중한 자원입니다, $c. 다르나서스에서 제 임무는 은빛 새벽단이 번성하도록 하고 칼림도어를 침략하는 악의 세력을 저지하는 것입니다. 용건을 빨리 말씀하시거나, 아니면 떠나십시오.'),
(1201, '침입자들을 찾았나요, $n?'),
(1202, '$n, 문서를 찾았나? 그 문서에는 얼라이언스의 안정에 매우 중요한 정보가 담겨 있고, 따라서 호드의 안보에도 필수적인 정보다.'),
(1203, '내 칼을 가지고 있니?'),
(1204, '갈라진 혀를 얻으셨나요?'),
(1205, '$n, 데드마이어의 이빨을 갖고 있나요? 그 괴물의 고통을 끝냈나요?'),
(1206, '그 눈은 어디에 있지?'),
(1218, '향신료. 우리 삶에 향신료가 좀 필요하잖아요? 동의하시나요?'),
(1219, '작성해야 할 보고서가 있으신가요?'),
(1220, '저에게 주실 게 있으신가요?'),
(1221, '$n님, 감자 있으세요?'),
(1222, '이그나츠 씨 보셨나요? 제가 얼마 전에 그를 늪으로 보냈는데 아직 돌아오지 않았어요!'),
(1238, '저에게 주실 게 있으신가요?'),
(1239, '$n 님, 보고하실 다른 사안이 있으신가요?'),
(1240, '형제여, 당신에게는 분노의 기운이 감도는군요. 킨웰레이에는 무슨 일로 오셨습니까?'),
(1241, '흥, 남이 낚시하는 걸 방해하려면 그럴 만한 이유가 있어야 할걸. 난 행상인도 싫어하는데, 하물며 거지들은 더더욱 싫어해.'),
(1242, '안녕하세요, $n님. 무엇을 도와드릴까요? 저희 특제 트리아스 체다 치즈를 드셔보시겠어요? 아니면 다르나시안 블루 치즈 한 덩어리는 어떠세요?'),
(1243, '숲 속을 돌아다니는 건 그다지 안전하지 않아, $n. 조심하고, 수상하거나 위험한 걸 발견하면 즉시 감시자들에게 연락해. 괜히 혼자서 해결하려고 하지 마. 무슨 일이 생겨도 우린 책임지지 않아. 하지만 어차피 넌 내 말 무시하고 어둠 속에서 나타나는 건 뭐든 다 싸울 거잖아, 안 그래? 하하, 그래, 너희 모험가들은 다 똑같아.'),
(1244, '조심해, $n. 트리아스가 널 여기로 보낸 건 알지만, 숲 속에 널 곤경에 빠뜨릴 만한 게 숨어있을 수도 있어... 특히 네가 데피아 일가를 조사하고 있는 상황이니까.'),
(1245, '돌아왔군, 그것도 무사히. 우리 둘 다 네가 치즈 때문에 온 게 아니라는 걸 알잖아, 그러니 형식적인 인사는 그만하고. 백커스가 도와줬어? 아니면 넌 아직 황혼의 숲으로 출발도 안 했어?'),
(1249, '그가 슬그머니 도망간 건가? 우리를 지켜보는 모습이 좀 수상해 보였어.'),
(1251, '$n, 당신이 들고 있는 건 뭐죠? 셰이디 레스트 여관 유적에서 나온 증거인가요?'),
(1252, '셰이디 레스트 인에서 흥미로운 것을 발견하셨나요?'),
(1253, '셰이디 레스트 인 부지에서 증거를 찾으셨습니까?'),
(1258, '머드록 혀벌레 연구는 순조롭게 진행되고 있습니다. 당신의 게 사냥은 잘 되시길 바랍니다.'),
(1261, '$n, 마그의 운명을 알아냈나요?'),
(1262, '더스트왈로우의 브래큰월 마을에서 오셨습니까? 나지르는 잘 지내고 있으며, 늪지대에서의 그의 노력은 어떻게 되어가고 있습니까?'),
(1265, '네, $n?'),
(1269, '셰이디 레스트 인에서 무슨 일이 일어났는지에 대한 단서를 찾으셨나요?'),
(1273, '리테를 찾으셨나요?'),
(1275, '연구에 필요한 샘플을 충분히 확보하면 비로소 진정한 연구가 시작될 수 있겠지. 블랙패덤 심해의 사티르와 나가의 변형된 뇌간을 분석해서 돌연변이 사이의 상관관계를 밝혀내 보려고 해. 어쩌면 그 지식을 바탕으로 블러드 엘프들이 더 이상 기형과 악의 세계로 빠져드는 것을 막을 수 있을지도 몰라.'),
(1276, '안녕하세요, $C님. 도와드릴 일이 있으신가요?'),
(1319, '제가 살펴볼 만한 게 있나요?'),
(1321, '저한테 주실 것 좀 있나요, $C?'),
(1322, '그 주머니들은 거미에게서 얻은 건가요?'),
(1324, '안녕하세요, $n님. 도와드려도 괜찮으시다면 양해 부탁드립니다만, 헨델이 탈출하거나, 더 심각하게는 죽는 일이 있어서는 안 됩니다.'),
(1338, '드워프 땅에서 온 편지라고? 저렇게 북쪽 먼 곳에서 누가 전화를 했을까… 어서 주문서를 보여주시오.'),
(1358, '제게 온 소포가 있나요?'),
(1359, '저에게 주실 게 있으신가요?'),
(1360, '자, 그럼 트로그들을 충분히 때려눕히고 내 상자 안으로 들어가 보물을 훔쳐갈 수 있었나?'),
(1361, '$n, 당신의 임무가 아직 끝나지 않았군요. 샤를린드라에게 당신의 무능함을 알릴까요?'),
(1364, '$r님, 무슨 일로 네더가드 요새에 오셨습니까?'),
(1365, '$n, 칸 데즈헤파를 물리쳤습니까?'),
(1366, '$n님, 귀 수집품은 어떠세요? 많으신가요?'),
(1367, '나가라! 마그람은 약한 자와는 대화하지 않는다. 우리는 약한 자를 죽인다! 나와 이야기하고 싶다면 네가 강하다는 것을 보여주어라. 겔키들을 많이 처치하고 돌아오라.'),
(1368, '네 두 발이 겔키스의 땅을 밟았다. 너는 이곳에 환영받지 못한다! 겔키스와의 우정을 원한다는 것을 증명해라. 마그람 켄타우로스를 죽여라. 땅이 마그람의 피로 젖으면 돌아와라.'),
(1369, '당신이 우리의 적이 아니라면, 내가 부탁하는 것을 들어줄 것이다!'),
(1370, '겔키스 가문에 당신의 가치를 더욱 증명한 후에 돌아오십시오!'),
(1371, '당신이 우리의 적이 아니라면, 내가 부탁하는 것을 들어줄 것이다!'),
(1373, '당신이 겔키스 가문의 친구임을 보여주세요, $n.'),
(1374, '당신이 겔키스 가문의 친구임을 보여주세요, $n.'),
(1375, '마그람을 위한 임무를 수행하면 제가 도와드리겠습니다.'),
(1380, '칸 흐라타는 죽었습니까? 열쇠 조각을 가지고 있습니까?'),
(1381, '내가 부탁하는 대로 해라. 네가 마그람의 동맹이라는 걸 증명해 봐!'),
(1382, '사라져라! 겔키스족은 네가 여기 있는 걸 원하지 않는다. 지금 당장 떠나라!! 마그람을 많이 죽이고 돌아오면 그때 너와 이야기하겠다.'),
(1383, '스토나드에 있는 그 침입자는 내 특별한 혈청을 마시고 나면 분명… 입을 열겠지. 하하! 필요한 재료를 구하는 건 결코 쉽지 않아. 섀도우 팬서는 늪지대에 흔하지만, 우리 목적에 필요한 만큼의 심장을 모으는 건 만만치 않지. 게다가 늪지대의 군주는 아주 까다로운 짐승이거든.'),
(1384, '당신은 부적을 가지고 있습니까? 당신은 콜카르에게 그들이 약하다는 것을 보여주었습니까?'),
(1385, '지금 당장 떠나지 않으면 마그람이 널 짓밟을 것이다! 우리의 친구가 되려면 겔키스를 죽여야 한다.'),
(1386, '콜카르가 두려운가? 왜 죽이지 않는가? 혹시 죽이는 법을 잊어버린 건가? 어서 콜카르를 죽여라! 그들이 죽기 전에!'),
(1387, '$n님, 보고서 있으신가요?'),
(1388, '당신이 우리의 소중한 친구인 약제사 파우스틴에게 도움이 되었기를 바랍니다.'),
(1389, '크리스탈 가지고 계세요?'),
(1391, '제발 저를 용서해 주십시오! 저는 동맹의 경계를 넘어서는 정보를 가지고 있습니다. 저는 호드를 옹호하는 사람은 아니지만, 지금 벌어지고 있는 정치적 배신을 반드시 밝혀내야 합니다!'),
(1392, '안녕하세요. 하버리지에 오신 것을 환영합니다.'),
(1395, '안녕하세요! 소란스럽긴 하지만 신경 쓰지 마세요. 네더가드 요새에서는 평소와 다름없이 영업 중입니다. 혹시 저에게 주실 말씀이 있으신가요?'),
(1396, '늪지대의 괴물들이 바짝 다가오고 있어요, $n. 제발, 캠프를 지켜내셔야 해요!'),
(1398, '$n, 혹시 표류목이라도 찾았어?'),
(1419, '턱뼈 있으세요?'),
(1420, '돌아오셨군요. 보고서가 있으신가요?'),
(1421, '마법사의 시약이 있나요, $n?'),
(1423, '저에게 주실 게 있으신가요?'),
(1424, '아탈하카르 사원 안에서 어떤 어둠의 행위가 자행되었는지는 아무도 모릅니다. 하지만 강력한 마법의 힘이 사용되었다는 것은 분명합니다. 우리는 그러한 마법에 대해 가능한 한 많은 것을 알아내야 합니다. 어쩌면 아탈라이의 주문이 호드에게 도움이 될지도 모릅니다. 눈물의 연못 주변에서 충분한 아탈라이 유물을 모으면, 트롤들이 무엇을 이루려 했는지, 그리고 무엇이 그토록 끔찍하게 잘못되었는지 이해할 수 있을 것입니다.'),
(1425, '저와 볼일이 있으십니까?'),
(1426, '나는 인내심이 강하다. 드레노어의 오래된 킨크 스톤처럼 인내심이 강하고 영원하다. 내가 살아있는 한, 물고기 인간들은 우리 국경을 넘지 못할 것이다. 만약 우리에게 군대가 있다면, 나는 이 세상과 다른 모든 세상에서 그들의 흔적을 없애버릴 것이다. 그들에 대해 이야기하는 것만으로도 내 안에서 증오심이 끓어오르는 것을 느낀다.'),
(1428, '바다와 그 모든 생명체들이 침묵할 때까지는 결코 만족하지 않을 것이다... 특히 그 역겨운 물고기 인간들은 더더욱.'),
(1429, '여기 오다니 용감하군요. 용감한 건지 어리석은 건지...'),
(1430, '$n 님, 당신의 성공을 기원하며 와인 한 통을 준비해 두었습니다. 고객에게 배송하기 전에 제가 먼저 맛을 보는 게 당연하겠죠.'),
(1434, '타우렌 동료가 사티르족이 겉모습과는 다르다고 경고했습니다. 그는 사티르족에게 뭔가 더 숨겨진 진실이 있으며, 그들의 악은 본성이 왜곡된 것이라고 믿습니다. 하지만 저는 그런 것을 본 적이 없습니다. 제가 본 것은 오직 약자를 무자비하게 학살하고 어둠의 힘을 추구하는 자들을 타락시키는 모습뿐입니다. 저는 대족장께서 다른 명령을 내리실 때까지 그들을 섬멸하는 임무를 계속 수행할 것입니다. 그때까지 저는 그들에게 조금의 동정도 느끼지 않을 것입니다.'),
(1435, '저는 마법을 최대한 간단하게 만들려고 노력했습니다. 희생자의 영혼을 상처 입은 몸에서 빼내는 것은 식은 죽 먹기일 것입니다. 보석의 힘만으로 적을 완전히 쓰러뜨리려 하지 마십시오. 적이 죽음에 가까워졌을 때만 보석을 활성화해야 하며, 그렇지 않으면 아무 소용이 없습니다.'),
(1439, '티라니스가 불타는 칼날의 비밀을 배우고 그들과 같은 부류가 되려 들까 두렵습니다. 그는 언제나 마법에 매료된 자들에게 마법이 가져다주는 힘을 동경해 왔으니까요. 티라니스의 영혼이 그런 위험에 빠져 있다는 소식을 가족에게 전한다면 도저히 견딜 수 없을 것 같습니다. 우리 종족에게 그런 것을 추구하는 것만으로도 끔찍한 죄악인데, 우리가 스스로를 지키려 애쓰는 바로 그 존재가 되어버린다는 건, 정말 두려운 일입니다.'),
(1442, '거룩한 길을 걷지 않는 자가 코르 보석에 대해 묻는다면 나는 그 자를 덜 신뢰할 것이다. 하지만 나는 내 동족 중 일부보다 너희 종족을 더 신뢰한다. 나는 너희 타락한 동족 중 단 한 명의 행동만으로 너희 종단 전체를 판단하지 않는다.'),
(1445, '만약 아탈라이 부적들이 하카르를 소환하고 자말란의 예언을 실현할 힘을 지니고 있다면, 반드시 그것을 확보해야 한다. 호드는 이러한 힘의 본질을 파악해야 한다!'),
(1446, '자말란이 제거되면 나는 내 부족으로 돌아갈 수 있을 것이다. 자말란이 정신적 지도자로 있는 한, 아탈라이 부족은 확실한 멸망에 직면할 것이다.'),
(1447, '내가 너를 멍청한 $C라고 말한 건 악의가 아니었어. 우리 친구잖아, 그렇지? 악감정은 없지?'),
(1448, '아제로스의 정글에서부터 카즈 모단의 눈 덮인 봉우리까지, 저는 세계를 누비고 다녔습니다. 지금까지 모험에서 도움을 요청한 적은 한 번도 없었지만, 이제는 제 몸이 너무 지쳤습니다. 탐험가 연맹의 마지막 임무를 완수하는 것보다 더 만족스러운 일은 없을 겁니다. C님, 아탈하카르의 사원을 찾는 데 도움을 주시면 정말 감사하겠습니다. 슬픔의 늪을 샅샅이 뒤져 발견한 것을 알려주세요!'),
(1452, '랩소디 몰트 마셔본 적 있어? 내가 직접 만든 맥주 중 최고라고 할 수 있지. 히컵! 하지만 그 운명의 비행, 그 늪지대 위에서의 끔찍한 기억을 다시 떠올리려면… 히컵… 좀 더 센 게 필요하겠군. 히컵! 내 칼림도르 칵테일에 풍미를 더해줄 닭똥집이랑 간 좀 찾았어? 히컵!'),
(1456, '니젤이라는 분께는 죄송하지만, 이 캠프는 제가 하룻밤 묵어본 곳 중 가장 편안한 곳은 아니었어요. 무슨 말인지 아시겠죠?'),
(1457, '사업이 잘 돼서 질문할 시간이 별로 없습니다, $n 님. 리클레이머스와 볼일이 있으시면 말씀해 주십시오. 그렇지 않으면 제 부하 직원에게 문의하셔야 할 겁니다. 여기 있는 사람들은 일 처리에 아주 능숙하거든요.'),
(1458, '혐오스러운 생물들, 사티로스. 전해지는 이야기에 따르면 걔네들이 나이트 엘프와 어떤 식으로든 연관이 있다고 하는데, 난 잘 모르겠어. 몇 년 전에 전쟁에 끌어들인 그 엘프 때문에 그런 관계가 생긴 것 같아. 그 이후로 세상은 완전히 달라졌지. 훨씬 더 위험해지고, 훨씬 더 무서워졌어.'),
(1459, '코도나 스코르파시를 어디서 찾을 수 있는지 알려드리지 못해 죄송합니다. 제가 그 지역에 대해 잘 모르고, 아직 탐험할 시간도 없었습니다.'),
(1464, '텔프 줄람에게 연락하여 또 다른 불의 삽타를 받으세요.'),
(1466, '데솔레이스에 이런 악마 같은 것들이 살고 있다는 사실조차 몰랐네요. 제가 마지막으로 읽은 바로는, 나이트 엘프들이 오래전에 떠난 후 켄타우로스가 이 땅을 거의 독점하고 있었다고 하던데. 도대체 왜, 그리고 어떻게 여기에 정착했는지 궁금하네요.'),
(1467, '만나서 반갑습니다, $n. 사업이 아주 잘 되고 있어요. 아이언포지에는 모루 두드리는 소리가 울려 퍼지고, 풀무질 소리에 불길도 활활 타오르고, 아내는 저녁 식사 후 디저트로 파이를 구워주고 있죠. 이보다 더 좋을 순 없을까요?'),
(1469, '드디어 돌아오셨군요, $n. 우리가 마지막으로 이야기 나눈 지 꽤 오래됐습니다. 제 의뢰를 잊으셨을까 봐 걱정했습니다.$B$B그 교활한 그리핀 기수는 찾으셨나요? 뭔가 보고할 게 있었나요?'),
(1470, '지금 당신의 힘은 미미하지만, 이미 가능성을 감지하고 있을 거라고 생각합니다. 죽은 자조차도 그 힘이 우리 안에 흐른다면 살아있음을 느낄 수 있을 겁니다.'),
(1471, '$n님, 저는 당신의 성공 소식을 기대합니다. 하지만 만약 실패하더라도, 제 기대에 미치지 못하는 것은 당신의 걱정거리 중 가장 사소한 것일 겁니다.'),
(1473, '에갈린은 나를 가르친 스승이었다. 그는 거의 눈길 한 번 주지 않고도 자신이 소환한 공허방랑자를 조종할 수 있었다. 내 차례가 되었을 때, 나는 지나치게 자신만만했다. 네가 휘두르는 힘을 함부로 다루지 마라, 그 힘은 아무리 경계심이 강한 자라도 집어삼킬 수 있다.'),
(1474, '심연 너머의 힘들 중에서도 서큐버스는 가장 위험한 존재 중 하나이며, 약한 자는 가장 쉽게 그 손아귀에 놀아납니다. 지금 그리고 앞으로도 이 점을 명심하십시오.'),
(1475, '제 탐험가 생활에 황혼이 드리우는 이 시점에, 저는 당신, $n께 탐험가 연맹을 위한 마지막 임무를 완수하는 데 도움을 청합니다. 제 늙은 몸이 슬픔의 늪과 가라앉은 사원을 헤쳐나갈 힘을 낼 수만 있다면, 저는 당신과 함께 싸웠을 것입니다. 자존심 때문에 아탈라이 석판을 모으는 데 당신의 도움을 청하는 것이 쉽지 않지만, 노령으로 인해 어쩔 수 없이 부탁하게 되었습니다. 부디 저를 도와주세요, $n. 탐험가 연맹의 마지막 임무를 완수하고 은퇴하고 싶습니다.'),
(1476, '$n, 지금까지 당신의 진척 속도가 예상보다 훨씬 빨라서 기쁩니다. 하트를 가져오시면 다시 한번 저를 감탄하게 하실 수 있을 겁니다.'),
(1479, '아직 도착 안 했어요?'),
(1480, '불타는 칼날은 자신들이 얼마나 약한 존재인지 깨닫기 시작했다. 그들의 마법은 보잘것없고, 힘은 미약했다. 그들의 유일한 힘은 섬기는 자들에게서 나오는 것이지, 진정한 힘과 지식에 대한 이해에서 나오는 것이 아니었다.'),
(1481, '$c, 잘못된 두피를 가져오지 마시오. 잘못된 시약을 사용하면 우리 모두 죽을 수도 있소. 마왕은 자신을 염탐하려는 자들을 죽이기 위한 비상 마법을 몸에 지니고 있을지도 모르오. 운명은 이미 내게 충분한 고통을 안겨주었소.'),
(1482, '저는 신탁 수정구를 받을 준비가 되었습니다, $C. 아즈레톡 군주를 찾아 처치하는 것은 우리 둘 모두에게 대족장의 호감을 얻는 데 큰 도움이 될 것입니다. 우리 둘 다 협력하여 신속하게 일을 처리하는 것이 우리의 목적을 달성하고 대족장의 환심을 사는 데 유리할 것입니다.'),
(1485, '당신이 마법으로 소환하는 존재들을 제어할 수 있어야 합니다. $C의 방식을 배우고자 하는 사람이 너무 적어서, 당신이 준비되지 않은 상태에서 무언가를 가르쳐 당신의 목숨을 앗아갈 위험을 감수하고 싶지 않습니다.'),
(1486, '저는 이 동굴들을 점령한 변종 생물들의 가죽을 조사하는 데 매우 관심이 있습니다. 혹시 $C님, 가죽을 수집하는 데 성공하셨나요?'),
(1487, '$N, 우리 나랄렉스의 제자들은 당신의 도움이 필요합니다. 스승님께서 뒤틀린 악몽에 갇히시면서 우리의 수는 점점 줄어들고 있습니다. 이 동굴을 배회하는 타락한 괴물들을 상대할 병력이 우리에게는 부족합니다. 부디 동굴로 들어와서 이 변종 괴물들과 싸워주십시오!');

INSERT INTO `_koKR_stage_quest_request_items_locale` (`ID`, `CompletionText`) VALUES
(1488, '호드에게 영광을, 적들에게 죽음을! 데솔레이스의 악마들은 그 어느 때보다 더 큰 위협이 되고 있다. 점점 더 많은 흉악한 괴물들이 나타나면서 대족장에게 돌아갈 희망이 점점 사라지고 있다. 차라리 켄타우로스 하나만 상대하면 됐으면 하고 바랄 때도 있다.'),
(1489, '너희 주인들은 너희를 여기로 보낸 게 정말 어리석은 짓이야! 나는 다시는 스컬지의 노예가 되지 않을 거야!'),
(1491, '내 울부짖음의 본질은 어디에 있는가?'),
(1492, '다음 배에 승선하시려 하십니까, 아니면 배에 실어 보내고 싶은 물건이 있으십니까?'),
(1498, '$n, 저울이 있습니까? 천둥 도마뱀의 공격을 견뎌낼 수 없다면 제 가르침은 소용없을 겁니다.'),
(1501, '$n님, 베르가의 석판을 가지고 계십니까? 만약 없으시다면, 석판을 구할 때까지는 당신과 이야기하고 싶지 않습니다.'),
(1503, '내 철근 가지고 있나요?'),
(1504, '보이드워커는 강력한 존재입니다. $n, 저도 한때 당신과 같은 처지였던 걸 기억합니다. 세월이 흐르면서 제 보이드워커는 저와 싸우는 횟수가 줄었지만, 그건 제가 방심하기를 바라는 마음 때문일 거라고 생각합니다. $n, 그 점을 기억하세요.'),
(1511, '네, 그게 뭐죠?'),
(1512, '돌아왔군. 서큐버스와 싸울 준비가 되었나?'),
(1513, '서큐버스를 보면 가슴이 벅차오르지만, 동시에 영혼이 마치 조수처럼 멀어져 가는 듯한 느낌도 듭니다. 조심하세요, 친구.'),
(1514, '당신은 병들고 변질된 듯한 바람꽃 식물을 발견했습니다. 식물에 매달린 열매는 썩어 독성이 있는 것으로 보입니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(1515, '으으으으...'),
(1516, '인내는 대지의 가장 위대한 미덕입니다. 대지는 모든 것의 순환을 목격합니다. 산이 사막이 되고, 강이 협곡이 되는 것을 말입니다. 대지는 모든 요소 중에서 가장 고집스럽고 현명하며, 조급함을 용납하지 않습니다. 지금 대지가 당신을 부르는 것은 갈등의 시기가 다가오고 있기 때문입니다. 당신이 내게 성공적으로 돌아올 때, 당신은 온전해지는 데 한 걸음 더 가까워질 것입니다. 다른 이들은 당신의 지혜를 시기하고 자신들의 무지 때문에 당신을 미워할 것입니다.'),
(1518, '저는 당신을 영원히 운명으로 이끌 네 갈래 길 중 첫 번째 길로 온전히 맞이하는 첫 번째 사람이 되고 싶습니다. 만약 당신이 대지가 준 돌을 가지고 있다면, 저는 대지가 약속한 토템을 드리겠습니다. 만약 그렇지 않다면, 당신이 스스로 길을 찾을 때까지 저는 당신과 함께 떠나겠습니다.'),
(1519, '대지는 인내심이 강해서 당신이 준비될 때까지 기다려 줄 것입니다. 모든 것은 시간이 지나면 닳고 다시 태어난다는 것을 알고 있기 때문입니다. 이것이 만물의 순환입니다. 산은 사막이 되고, 강은 협곡이 됩니다. 대지는 모든 요소 중에서 가장 끈질기면서도 현명합니다. 무엇보다 인내와 지구력을 길러야 합니다. 대지가 지금 당신을 부르는 것은 당신이 준비되었다고 느끼기 때문입니다. 성공한다면 이것을 당신의 재탄생으로 여기십시오. 그러면 다시는 무지로 돌아갈 수 없을 것입니다.'),
(1521, '안녕, $n. 자네가 임무를 완수하지 않았다면 내게 돌아오지 않았겠지. 자네가 앞으로 영원히 여정을 지배할 네 개의 길 중 첫 번째 길에 완전히 들어선 것을 진심으로 환영하네.$B$B만약 자네가 대지가 준 돌을 가지고 있다면, 나는 대지가 약속한 토템을 자네에게 주겠네. 그렇지 않다면, 자네가 안타깝군. 대지의 원소에 온전히 헌신했을 때 얻을 수 있는 자부심은 참으로 크네.'),
(1524, '안녕하세요, $n님. 잠들어 있는 불꽃의 신전에 오신 것을 환영합니다. 오직 샤머니즘에 정통한 자만이 이곳의 비밀과 그 안에 담긴 힘을 알 수 있습니다. 먼 길을 오셨는데 이제 돌아가셔야 한다니 안타깝습니다. 이곳까지 오는 길은 결코 안전하지 않으니까요. 하지만 저는 이 신전의 수호자로서 아무나 함부로 돌아다니도록 내버려 둘 수 없습니다.'),
(1525, '시약 주머니와 화염 타르만 찾으면 화염 사프타를 만들 재료는 충분히 있습니다. 불타는 칼날 광신도들은 대부분의 주문에 필요한 재료를 그 주머니에 넣어 다니고, 제가 필요한 재료도 보통 충분히 가지고 있어서 멀리까지 찾아다닐 필요는 없을 겁니다. 사프타는 항상 각 원소와 밀접하게 관련된 재료로 만들어집니다. 흑마법사들이 불과 깊은 연관이 있기 때문에 작업이 훨씬 수월하죠.'),
(1526, '화로는 당신 키의 약 3분의 1 정도 높이이며, 매끄러운 금속 레일을 따라 새겨진 글자를 제외하면 평범해 보인다. 금속에는 날씨로 인한 마모 흔적이 전혀 없고, 맨 위에 놓인 화로는 만져보면 시원하다.'),
(1527, '네, $n님? 거기에 뭘 가지고 계세요?'),
(1534, '물은 구했나요, $n? 전설에 따르면 유적지는 방문객을 싫어하는 거대한 자연의 생물들이 지키고 있다고 하는데, 이는 나이트 엘프의 적들을 겁주기 위한 신화일지도 몰라요. 어쨌든 조심하세요.'),
(1535, '이제 다른 임무를 보낼 준비가 거의 다 됐어. 가죽은 다 채웠나? 퀼보어가 얼마나 보호 본능이 강한지 잘 알고 있지. 저렇게 작은 수원이라도 그들에게는 엄청난 보물이야. 황무지에 아주 조금이라도 비가 내리면 성대한 잔치를 벌이기도 해. 물은 그들에게 너무나 귀중하기 때문에 신성한 거야. 이해하겠나?'),
(1536, '마을 안에 깨끗하게 남아 있는 우물을 보면 어렸을 적 들었던 이야기들이 떠오릅니다. 큰 고통과 슬픔 속에서도 한 줄기 희망, 우리가 의지할 수 있는 작은 상징을 찾을 수 있다는 이야기 말입니다. 오크들은 스랄을 그렇게 생각합니다. 그는 온갖 역경을 이겨내고 강인함과 모범을 통해 우리 부족을 이끌게 되었습니다. 그 어떤 오크도 스랄만큼 고통받지는 않았을 것이고, 동시에 그 어떤 오크도 스랄만큼 강하지 않을 것이라고 생각합니다.'),
(1558, '아직 도착 안 했어요?'),
(1578, '저는 지금 대화할 시간이 없습니다. 저와 볼일이 있으십니까?'),
(1579, '$n, 내 가퍼 잭 찾았어? 가퍼 잭 없이는 스틴틀 페그를 조율할 수가 없어!'),
(1580, '혹시 전기충격 미끼를 찾으셨나요? 오리 미끼에 대한 연구를 계속하려면 필요하거든요...'),
(1581, '안녕하세요, $n님. 교환하실 엘릭서 있으신가요?'),
(1582, '안녕하세요, $n님.'),
(1598, '내가 직접 책을 훔치기엔 너무 눈에 띄었다. 다행히 그들의 꼭두각시 중 하나가 나 대신 그 더러운 일을 해줬다.'),
(1599, '수련생들이 지니고 다니는 깃털 부적에는 어떤 마법적인 힘이 있는 것 같아. 연구해 보면 흥미로울 것 같아. 트롤들이 그런 힘을 가지고 있을 줄은 몰랐네.'),
(1618, '아이언포지에서 좋은 소식을 가지고 오셨길 바랍니다. 저는 정말 어찌할 바를 모르겠어요!'),
(1644, '존이 아이언포지에서 좀 더 좋은 일을 겪고 있기를 바라요. 그는 아이언포지 출장을 정말 싫어하는데, 아이들과 저를 두고 떠나야 하기 때문이에요. 하지만 어쩔 수 없다는 걸 알죠. 그는 정말 마음씨가 착해요. 어떤 해는 다른 해보다 나았지만, 올해는 유독 힘든 한 해였어요. 마치 뭔가 큰 변화를 예고하는 듯한 기운이 감돌아요. 하지만 누가 알겠어요?'),
(1648, '이곳과 아제로스 전역에 상인들이 몰려들면서, 저희 고아원 아이들의 옷을 만드는 데 필요한 재료들이 부족해졌습니다. 아내가 아이들에게 새 옷을 만들 수 있도록 아마포를 모으는 것을 도와주신 $n님의 고마운 마음에 진심으로 감사드립니다.$B$B조만간 아내에게 돌아갈 수 있기를 바랍니다.'),
(1654, '원하시는 재료를 구하기는 어렵겠지만, 제가 만들어 드릴 무기는 그만한 가치가 있을 거라고 장담합니다. 지금까지 제가 만든 것 중 최고의 작품이 될 것이며, 그 비용은 당신이 제게 베풀어주신 도움에 대한 작은 보답일 뿐입니다.'),
(1655, '그래서, 뭔가 성과가 있었나요? 하하, 그 오거들이 아직 당신을 이기지는 못했군요, 그렇죠?'),
(1656, '그래, 꼬마야? 카우트가 너를 위해 무엇을 해 줄 수 있을까? 메사에서 여기까지 오는 여정은 어떤 이들에게는 엄청난 짐이 될 수 있지만, 어떤 이들에게는 반가운 광경일 수도 있지. 너는 어떤 경우인지 궁금하구나.'),
(1657, '사우스쇼어 주민들에게 우리의 "선물"을 전달했습니까?<다크콜러 얀카가 사악하게 웃는다.>'),
(1665, '바틀비와의 싸움 봤어요. 멋지네요! 바틀비 머그컵은 얻었나요?'),
(1667, '내 배지 가지고 있어? 데드투스 잭이 그걸로 무슨 짓을 저지를지 생각하기도 싫어.'),
(1678, '$n, 베이렉의 오두막에 가본 적 있어? 네 몸에서 $R 냄새가 나는데?'),
(1679, '바꾸셨나요?'),
(1681, '아이언밴드의 기지에 들어가 보셨나요? 어둠의 광석을 찾으셨나요?'),
(1683, '$n, 뿔피리를 가지고 있습니까? 우리 달의 샘은 악마 볼루스에게서 벗어났습니까?'),
(1686, '$n님, 엘루라의 그림자를 물리치셨나요? 그리고 잃어버린 엘루나이트 광석은 가지고 계신가요?'),
(1687, '아직 도착 안 했어요?'),
(1688, '나이가 많고 지혜로운 사람이라도 젊음과 아름다움의 유혹에 넘어갈 수 있다는 것은 인생 전반에 걸쳐 명심해야 할 조언입니다.'),
(1689, '보이드워커를 제압하기 전까지는 보이드워커를 조종하는 방법을 알려드릴 수 없습니다.'),
(1690, '벌써 돌아왔군? 내가 부탁한 대로 그 황무지 도적떼들에게 고블린식 정의를 구현해냈기를 바라!'),
(1691, '자, 제가 부탁드린 대로 유목민들을 소탕하셨습니까? 가젯잔 상수도 회사는 당신의 성공을 바탕으로 새로운 계획을 세우고 있습니다! 우리를 실망시키지 말아 주십시오...'),
(1692, '안녕하세요, 젊은 $C님. 제 능력이 어떻게 도움이 될 수 있을까요?'),
(1700, '안녕하세요, 반갑습니다. 어떻게 도와드릴까요?'),
(1701, '보물찾기는 잘 진행되고 있나요, $n? 재료는 다 준비됐나요?'),
(1702, '안녕하세요! 요즘 날씨가 너무 건조하지 않나요?'),
(1703, 'C님께 인사드립니다.'),
(1704, '안녕하세요, 좋은 아침입니다. 아니면 좋은 저녁이신가요? 여기 너무 낮아서 잘 안 보이네요. 혹시 저에게 맡기실 일이 있으신가요?'),
(1705, '$N, 불타는 피와 바위 가지고 있어? 갑옷을 완성하려면 그것들이 필요해.'),
(1707, '필요한 웨이스트원더 물 파우치 5개를 모두 모으셨나요? 모으셨다면, 가젯잔 워터 컴퍼니 케어 패키지(모델 103-XB)를 드립니다!'),
(1708, '안녕하세요, $n님! 혹시 불타는 산호 있나요? 얼른 작업해 보고 싶어요!'),
(1710, '조개껍데기 있나요, $n? 꽤 단단해서 그걸로 옻칠을 만들어서 새 사슬 갑옷의 연결 부위에 칠할 수 있을 것 같아요.'),
(1712, '$n, 필요한 아이템들을 다 모았나요? 그 아이템들을 모으는 게 당신이 사이클로니안과 맞설 힘이 있다는 증거가 될 겁니다.'),
(1713, '$N, 난 분명 회오리바람 같은 심장을 가졌나 봐!'),
(1714, '가마솥에서 부글부글 끓어오른다. 김이 모락모락 피어오른다...'),
(1738, '$n님, 검색에 성공하셨나요?'),
(1739, '가끔 수레나가 내 마음을 뒤틀고 조종하려고 변장한 서큐버스가 아니었을까 하는 생각이 들어... 하! 내가 그녀를 너무 과대평가하는 것 같군.'),
(1740, '자르가인의 오브 조각들을 모으는 데는 여러 해가 걸렸지만, 그 오브는 제게 큰 도움이 되었고, 소란룩의 오브 또한 당신에게 큰 도움이 될 것이라고 확신합니다.'),
(1784, '돌아왔구나! 반갑다, $n. 상처는 다 나았고, 아내를 안심시킬 수만 있다면 헬름스 베드 호수로 돌아갈 준비가 거의 다 됐어.'),
(1787, '헨제는 안전한가요, $n? 임무는 성공했나요?$B$B당신의 무기 사용 능력과 빛의 힘을 고려하면, 영웅의 감시탑은 데피아스의 위협으로부터 안전할 거라고 생각하지만, 그건 왕과 그의 고문들이 판단할 문제죠.'),
(1795, '모든 $C는 지휘관으로 펠헌터를 보유해야 합니다. 길들이기는 어렵지만, 펠헌터가 주인에게 가져다주는 힘은 그 대가를 훨씬 능가합니다.'),
(1796, '$n님, 로브 찾는 건 어떻게 진행되고 있나요? 직접 만드신 건가요? 저는 그런 개인적인 손길이 마법을 불어넣는 과정을 훨씬 더 의미 있게 만들어준다고 생각해요. 성취감도 더 커지고요. 하지만 더 빠른 길을 택해서 누군가에게 제작을 맡기는 것도 이해해요. 그런 야망도 나름대로 의미가 있으니까요.'),
(1799, '그리고 당신은 마법사가 아니니, 당신을 완전히 믿을 수 있을지 모르겠네요. 당신에게서 마법의 기운이 느껴지지만, 당신 같은 부류에게서 흔히 풍기는 타락의 악취는 전혀 풍기지 않는 것 같군요. 네, 어떤 사람이 제게 도움을 청하러 왔습니다. 제가 무엇을 도와드릴 수 있을까요, 당신?'),
(1800, '아직 도착 안 했어요?'),
(1802, '소문이 사실로 밝혀졌나요, $n?'),
(1803, '어쩌면 당신은 동화 같은 이야기를 쫓고 있는지도 모르지만, 아무리 황당한 소문이라도 그 중심에는 진실이 숨어 있을 수 있습니다.'),
(1804, '오랜만에 이쪽에서 뵙는군요. 마법서랑 지팡이는 찾으셨나요?'),
(1805, '네, $n님? 제가 어떻게 도와드릴 수 있을까요?'),
(1819, '$n, 당신의 임무는 아직 끝나지 않았습니다. $C가 두려움을 드러내는 것은 현명하지 못합니다...'),
(1821, '$n님, 가보를 가지고 계신가요?'),
(1822, '당신이 돌려준 무기 세 자루는 제 고통과 상실의 기념품으로 간직하겠습니다. 하지만 $n, 부디 그중 가장 마음에 드는 것을 하나 골라 간직하세요. 그 무기가 저주받은 이전 주인들에게보다 당신에게 더 큰 의미를 갖기를 바랍니다.'),
(1824, '더듬이 가지고 있나요? 있다면 빨리 저에게 주세요. 꿈틀거리는 더듬이는 영원히 꿈틀거리지 않으니까요...'),
(1838, '내 두루마리에 있는 물건들 가지고 있나요, $n?'),
(1842, '$n, 발굽이 있나요? 발굽에는 강력한 마법이 깃들어 있어요.'),
(1844, '뿔이 있나요? 여족장은 고통에서 벗어났나요?'),
(1846, '$n, 정강이뼈 기다리고 있어. 네 다리 보호대 틀로 딱이겠는데.'),
(1858, '원하는 것을 바로 눈앞에 두고도 그것을 얻을 방법이 없다는 것은 답답하지 않나요?'),
(1861, '$n, 샘플을 가지고 있습니까? 스톰윈드와 엘윈 숲의 마법 흐름이 바뀌었는데, 그 마법이 물에도 스며들고 있는지 알아야 합니다.'),
(1878, '$n님, 다시 오셨나요? Wastewander 물 파우치가 다섯 개 더 있으시면, $n님 이름이 적힌 선물 꾸러미를 보내드릴게요!'),
(1880, '기즈모니터를 찾았나요? 에너지가 다 떨어지기 전에 꼭 가져야 해요!'),
(1882, '금어초를 가지고 있습니까? 그 꽃은 마법 에너지에 매우 민감해서, 역병지대와 가까운 곳에서 금어초를 연구하면 티리스팔 숲에 역병이 퍼졌는지 알 수 있습니다.'),
(1884, '서둘러야 해, $n. 주술 더미들을 없애버려!'),
(1886, '성공 사례를 보고하시겠습니까?'),
(1898, '안녕하세요. 제가 도와드릴 일이 있을까요?'),
(1899, '성공, $n?'),
(1918, '네, 무엇이 필요하세요?'),
(1920, '$n, 그 생물들을 포획했습니까? 그들이 나타난 이유를 알아내기 위해 연구를 해야 합니다.'),
(1921, '안녕하세요, $n님. 제네아가 당신이 오실 거라고 했어요. 저에게 주실 말씀이 있으신가요?'),
(1938, '$n, 그 책 가지고 있나요? 그 책에 담긴 비밀은 훈련받지 않은 자에게는 공개될 수 없으며, 그 깊이를 파헤치려다 보면 파멸에 이를 수도 있습니다.'),
(1940, '아, 네. 마법사의 성소의 마법사들이 당신이 저와 이야기할 거라고 하더군요. 필요한 비단은 가지고 계신가요?'),
(1944, '무사히 돌아오셔서 다행입니다, $n. 물 샘플은 가지고 계신가요? 그 특성을 연구해보고 싶습니다.'),
(1945, '안녕하세요, $n님. 데이노가 당신이 오실 거라고, 그리고 웃는 자매들의 머리카락을 가져오실 거라고 했는데, 가지고 계신가요?'),
(1948, '안녕하세요, $n님. 제가 필요한 물품을 가지고 계신가요?'),
(1950, '뭘 기다리고 있는 거야? 내 마법의 주문이 필요해!'),
(1951, '안녕하세요, $n님. 혹시 ''권력의 의식''이라는 책을 찾으셨나요?'),
(1954, '$n님, 지옥의 구슬을 가지고 계신가요?'),
(1955, '$n, 그 악마를 죽여야만 구슬에 묻은 오염을 제거할 수 있을 거야.'),
(1956, '$n님, 울다만에 가보셨나요? 흑요석 파수꾼을 물리치셨나요?'),
(1957, '당신은 필요한 양의 마나 서지를 제거하지 못했습니다, $n.'),
(1960, '$n, 소란의 원인을 조사했습니까? 그 생물들을 포획했습니까?'),
(1961, '아나스타시아가 당신이 내게 올 거라고 했고, 나는 당신의 옷을 만들 준비가 되어 있습니다. 보석과 아마포는 가지고 있습니까?'),
(1963, '어둠 속에서 칼을 휘두르는 것보다 도끼를 들고 돌격하는 것이 더 위험하다고 믿는 사람은 어리석은 사람이다.'),
(1978, '예?'),
(1998, '저는 당신이 바리마트라스 신을 위해 이 일을 수행해 줄 것이라고 전적으로 믿고 있습니다.'),
(1999, '$n님, 서류를 찾으셨나요?'),
(2038, '$n! 내 물건들은 어디 있지?!'),
(2040, '$n님, 그노암 스펙클스프로킷을 찾으셨나요?'),
(2078, '내 일등 항해사 $n은 어디 있느냐? 서두르지 않으면 곧 족쇄와 상어 떼가 너를 기다리고 있을 것이다!'),
(2098, '육지 촌놈아, 내 고장난 열쇠를 찾았느냐?'),
(2118, '병든 동물을 데려왔느냐, $n?$B$B덫을 놓는 데 실패하더라도 걱정하지 마라. 타르나리운의 희망은 영원하다. 다른 덫이 필요하면 작업을 중단하고 내게 보고하라.'),
(2138, '당신의 임무는 완료되었습니까?'),
(2139, '감염된 어미 곰이 죽었으니, 우리 땅으로 들어오는 광견병에 걸린 엉겅퀴곰의 개체 수가 줄어들었습니다. 시간을 낭비하지 마세요, $n.'),
(2159, '젊은이, 제가 어떻게 도와드릴까요? 여관에서 쉬러 오셨나요? 난로에 쓸 돌이 필요하신가요?'),
(2160, '안녕하세요! 들어오세요, 벽난로 옆에 앉아서 따뜻한 에일 한 병 드시면서 몸을 녹이세요.'),
(2161, '레이저 힐에 오신 것을 환영합니다!'),
(2178, '냄비가 텅 비었는데 배고파! 왜 이렇게 늦는 거야?'),
(2198, '이봐, 넌 엉뚱한 사람을 잡았어! 난 거기 없었어! 넌 아무것도 증명할 수 없어! 잠깐만... 넌 누구야? 이게 뭐야... 이 목걸이는 어디서 찾은 거야?'),
(2199, '내가 부탁한 은괴 다섯 개 가져왔나? 네가 지금 갖고 있는 목걸이에 얽힌 내 슬픈 이야기를 들려줄게… 하지만 그 은괴를 먼저 가져와야 해! 제발, 난쟁이 좀 도와줘!'),
(2201, '점술 그릇의 물속에서 탈바쉬의 모습이 선명하게 드러났다. "와, 아직 살아있었군! 보석은 찾았나? 정말 내가 바라던 대로 내 명예를 지켜줄 구세주인가? 설마 그냥 수다 떨려고 약병 값을 낭비한 건 아니겠지? 그거 엄청 비싼데, 난 지금 재정적으로 아주 어려운 상황이거든."'),
(2202, '제 연금술 작업에 필요한 자홍색 버섯 갓을 구하셨나요? 갓이 없으면 보상도 없습니다!'),
(2203, '내가 필요한 그을린 수호 용의 피를 얻기 위해 그 그릇들을 사용해 봤나? 위험한 임무라는 건 알지만… 내 회복 물약 제조법이 네 성공을 기다리고 있다. 위험을 감수해야 보상이 따르는 법이지, 친구… 위험과 보상…'),
(2204, '울다만을 떠나면서 몸단장조차 하지 않고 곧장 여기까지 왔군. 던전 특유의 냄새 따위는 아랑곳하지 않고 말이야. 이번 방문이 그저 냄새만 풍기는 방문이길 바라야겠군. 헛수고만은 아니길. 목걸이에 필요한 에너지원은 가지고 있나?'),
(2205, '도와드릴까요, $C님?'),
(2206, '당신이 병영에서 빈둥거리며 시간을 허비할 때마다 당신의 수명은 점점 줄어듭니다.'),
(2239, '나병 걸린 난쟁이의 악취가 즐거웠나요? 당신 얼굴에 광기 어린 미소가 지어져 있어서 묻는 겁니다. 오닌에서 무슨 소식을 가져왔나요?'),
(2240, '신고할 사항이 있으신가요?'),
(2241, '어머, 정말 멋지네요. 당신은 자신의 장례식에 꽃을 가져왔군요.'),
(2242, '세티르 고대인에 대해 보고할 내용이 있습니까, $n?'),
(2258, '제가 필요한 물품들을 구해왔나요? 그 시약들을 가져오지 않으면 급여를 받을 수 없을 겁니다.'),
(2278, '돌 감시자의 목소리가 당신의 내면 깊숙이 울려 퍼지는 듯합니다. "먼저 노르가논의 원반 데이터 동화 요건을 충족해야 합니다. 이 요건을 충족하면 저장된 데이터의 휴대용 버전을 얻을 수 있습니다. 먼저 이 저장소에 있는 정보를 완전히 탐색했는지 확인하십시오."'),
(2279, '네, 무슨 일로 오셨나요? 지금 정말 바쁘지만, 탐험가 연맹에 아주 중요한 일이라면 얼마든지 말씀해 드리겠습니다!'),
(2280, '저게 뭐예요? 디스크에서 뭘 배웠어요?'),
(2282, '오크 이야기를 빼먹었나? 오크들이 방앗간 근처에서 어슬렁거리고 있다는 소문이 들려.'),
(2283, '자, 목걸이 가지고 계십니까? 그 목걸이가 없으면 저희는 한 푼도 드리지 않겠습니다!'),
(2338, '생각해 보셨죠? 이 거래를 받아들이시면 정말 현명한 선택이 될 겁니다. 우리 둘 다 원하는 걸 얻게 될 거고, 드로퍼스 앤 선 살비지도 자기들이 원하는 걸 얻었다고 생각하겠죠.'),
(2339, '보석과 목걸이에 마법력을 다시 불어넣을 수 있는 동력원이 없다면, 울다만 심연으로 다시 한번 깊숙이 들어가야 할 겁니다. 보석은 오그리마에 있는 적들에게 가져다줘야 하고, 동력원은 제가 가지게 될 겁니다. 그게 바로 목걸이를 작동시키는 핵심이니까요.'),
(2340, '어머, 이게 누구야! 여기까지 오는 데 꽤 오래 걸렸군. 이번 일이 내 시간을 낭비하는 일이 아니길 바라야겠군! 내가 요구한 모든 것을 준비하지 않으면 돈은 줄 수 없어. 그리고 장담하는데, 모든 걸 두세 번씩 꼼꼼히 확인할 거야!'),
(2342, '청소는 끝이 없군... 이 박쥐들은 나와 내 빗자루를 조롱하는 데 혈안이 되어 있어. 제발 우리 가문의 보물을 되찾았다고 말해줘! 내가 은을 드렸는데, 그것으로는 부족한 건가?!'),
(2358, '악마 왕자의 뿔을 갖고 있나요?'),
(2359, '커넌 요원에게서 소식 있나요?'),
(2381, '그래도 적어도 신체 부위는 다 멀쩡하잖아. 보물은 찾았어?'),
(2383, '들고 있는 게 뭐죠? 양피지인가요? 설마 학자는 아니시겠죠...?'),
(2418, '혹시 파워 스톤 가지고 계세요, $n님? 로봇 설치류에 전원이 필요해서요...'),
(2438, '부디 어서 움직여 주세요. 제 에메랄드 드림캐처가 퍼볼그에게 무사했기를 바랄 뿐입니다. 혹시 $n 님, 드림캐처를 되찾으셨나요?'),
(2439, '아이언포지 금고에 오신 것을 환영합니다, $n님. 무엇을 도와드릴까요?'),
(2440, '안녕하세요, $c님! 연금술 훈련을 받으러 오셨나요, 아니면 다른 용건이 있으신가요?'),
(2459, '페로시타스와 그날파인 신비주의자들은 내 것을 돌려줘야 합니다. 부디 에메랄드를 되찾아 주셔서 제 에메랄드 드림캐처를 고칠 수 있도록 해 주세요.'),
(2478, '$n님, 보고할 사항이 있으신가요?'),
(2479, '이게 뭐지???'),
(2499, '$r님, 오켄스카울을 찾으셨나요?'),
(2500, '제가 필요한 물품들을 구해왔나요? 그 시약들을 가져오지 않으면 급여를 받을 수 없을 겁니다.'),
(2501, '내가 필요한 그을린 수호 용의 피를 얻기 위해 그 그릇들을 사용해 봤나? 위험한 임무라는 건 알지만… 내 회복 물약 제조법이 네 성공을 기다리고 있다. 위험을 감수해야 보상이 따르는 법이지, 친구… 위험과 보상…'),
(2518, '제가 당신에게 부탁드린 임무가 유감스럽지만, 사트라 여신께서는 이미 가망이 없으십니다. 저희는 엘룬께 방적모를 제물로 바치고자 합니다. 이 제물을 통해 엘룬께서 사트라 여신을 축복하시어 그녀가 다시 태어나 평안을 누리게 해 주실 것입니다.'),
(2520, '제물을 분수대에 바쳤습니까, $n?'),
(2521, '저는 흠 없는 드레네시스트 구체를 찾는 데 제 삶을 바쳤습니다. 평생을 말이죠!'),
(2522, '또 다른 완벽한 드레네시스트 구체를 찾으셨나요?'),
(2523, '당신은 병들고 변질된 듯한 송플라워 식물을 발견했습니다. 식물에서는 역겹고 불쾌한 냄새가 풍깁니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(2541, '내가 그 부적을 조사해 볼 수 있다면, 마법을 풀 방법을 알아낼 수 있을지도 몰라. 혹시 그런 부적을 찾았니?'),
(2561, '$N, 내 육신에 접근할 때는 조심해라. 내 육신에 걸린 마법은 상당히 강력하다.'),
(2581, '$n, 너 냄새가 고약하군. 유황밭을 헤매고 다녔나? 그리고 내 부품들은 어디 있지?!'),
(2582, '짐승의 장기를 가지고 있나요?'),
(2583, '장기들은 어디 있지, $n!?'),
(2584, '장기들은 어디 있지, $n!?'),
(2585, '장기들은 어디 있지, $n!?'),
(2586, '장기들은 어디 있지, $n!?'),
(2601, '요청하신 장기를 가지고 돌아오셨습니까?'),
(2602, '요청하신 장기를 가지고 돌아오셨습니까?'),
(2603, '시간 낭비하지 마세요, $n. 당신이 제가 요청한 물품들을 되찾지 않았다면 더 이상 논의할 게 없습니다.'),
(2604, '시간 낭비하지 마세요, $n. 당신이 제가 요청한 물품들을 되찾지 않았다면 더 이상 논의할 게 없습니다.'),
(2605, '제발, 이슬 수집기를 찾았다고 말해주세요.'),
(2606, '마린이 또 사고를 쳤군, 그렇지? 이 혼합물은 대체 뭘로 만든 거야?'),
(2608, '검사 준비가 되시면 바닥에 누우세요. 제가 채혈을 시작하겠습니다.'),
(2609, '그 ''병''을 고치고 싶다면, 그보다 더 열심히 노력해야 할 거야, $n. 치료에 필요한 약은 어디에 있지?'),
(2623, '명령을 기다리고 있습니다.'),
(2641, '저 호수 물속, 바로 그곳이 보라색 트라간을 찾을 수 있는 유일한 곳이야. 숨을 참을 수 있어야 할 걸!'),
(2661, '오, $n, 드디어 돌아왔구나. 뭘 가져왔어?'),
(2681, '쉬운 일은 아니야, $n. 포기하지 마!'),
(2741, '슈퍼 에그오매틱은 커글 크랭클홉의 최신 발명품입니다. 상당히 인상적인 기계 장치입니다. 당신이 제어판에 다가가면 슈퍼 에그오매틱은 심하게 덜컹거립니다.'),
(2742, '린지는 겁먹었어!'),
(2744, '여기서 뭐 하고 있는 거야?'),
(2746, '몇 주 동안 레스코바르를 감시해 왔습니다. 트리아스는 그를 결코 신뢰하지 않았지만, 데피아스 형제단과 연루되었을 거라고는 전혀 예상하지 못했습니다. 우리는 그가 황혼의 망치와 연관되어 있다는 단서를 쫓고 있었을 뿐입니다. 어쨌든 그는 이 도시가 감당하기에는 너무 위험한 존재가 되었고, 그래서 우리가 나선 겁니다. 그 물건들을 가져오면 내 계획을 실행할 수 있습니다.'),
(2747, '페랄라스에서 채취한 알 중에서 상태가 아주 좋은 것은 거의 본 적이 없습니다. 이런 알들은 정말 희귀한 종류입니다...'),
(2748, '훌륭한 알이란 이상적인 조건에서 고르둔니 오거들의 주문에 의한 악영향 없이 부화하는 알을 말합니다.'),
(2749, '일반적인 히포그리프 알은 절반 정도만 부화합니다. 저희는 최선을 다해 알을 돌보고, 운이 좋으면 부화할 것입니다.'),
(2750, '이것들은 살릴 수 없는 알들입니다. 절대로 부화하지 않을 거예요.'),
(2751, '청동, $n! 청동 더 많이!!'),
(2752, '$r, 당신의 헌신을 보여주세요.'),
(2753, '네 부츠의 압력에 그들의 두개골이 부서질 것이다!'),
(2754, '다리미에게 누가 주인인지 보여줘, $n!'),
(2756, '아투르크는 시간처럼 누구도 기다려주지 않아! 어서 서둘러, 바보야!'),
(2757, '당신 같은 부류는 정말 보기 드물군요, 친구. 그 휘장을 좀 보여주시죠.'),
(2758, '당신이 갈반의 차세대 제자가 될 수 있을까요?'),
(2759, '당신 같은 부류는 정말 보기 드물군요, 친구. 그 휘장을 좀 보여주시죠.'),
(2760, '만세! 더 가까이 오너라. 갈반에게 네 능력을 보여주어라.'),
(2761, '그렇게 채굴 작업을 하고 나면 근육이 불룩해지고 온몸이 쑤시게 됩니다!'),
(2762, '그렇게 채굴 작업을 하고 나면 근육이 불룩해지고 온몸이 쑤시게 됩니다!'),
(2763, '그렇게 채굴 작업을 하고 나면 근육이 불룩해지고 온몸이 쑤시게 됩니다!'),
(2766, '자, 당신이 발견한 것은... 로봇 닭의 잔해인 것 같군요? 달걀 속에서 다시 목소리가 들려왔습니다. "훌륭합니다! 이것은 제 귀환 로봇이 맞습니다. 하지만 센서에 따르면 수리를 위해 부티 베이로 돌아가기 전에 시동을 걸어줘야 합니다. 자, 비콘을 로버 안에 넣어 두세요. 비콘이 나머지를 알아서 처리할 겁니다!"'),
(2767, '네, 저는 오글소프 오브노티쿠스입니다. 당신을 위해 봉사할 뛰어난 발명가죠! 자, 무엇을 도와드릴까요?'),
(2768, '블라이 상사를 찾았나? 내 점술 지팡이는 가져왔나?'),
(2770, '저울 있으세요? 저울의 에너지를 활용하는 다양한 방법을 어서 시도해보고 싶어요!'),
(2771, '아이템 제작을 완료하셨나요, $n님?'),
(2772, '아이템 제작을 완료하셨나요, $n님?'),
(2773, '아이템 제작을 완료하셨나요, $n님?'),
(2781, '네, $c님. 저는 가젯잔 수도회사 직원입니다. 무엇을 도와드릴까요?'),
(2782, '자, 이게 대체 뭐지?'),
(2784, '내 말을 들어보세요.'),
(2801, '내 말을 들어봐, $n.'),
(2821, '두꺼운 예티 가죽 10장을 가져오시면 제가 직접 제작한 아이템 중 하나를 선택하실 수 있습니다. 저는 품질을 중요하게 생각하기 때문에 좋은 아이템을 보장해 드릴 수 있습니다! 예티를 찾기 어려우시다면, 제가 위치를 알고 있습니다. 잊혀진 해안에서 내륙 쪽으로 조금 들어가 야생의 흉터 골짜기 주변을 찾아보세요.'),
(2822, '두꺼운 예티 가죽 열 장 정도 구하셨나요? 제 가죽 제품은 최고 수준이니, 가죽이 있으시면 샘플을 나눠드리겠습니다. 예티를 찾기 어려우시다면, 제가 어디쯤 있을지 아는데요. 여기 서쪽, 잊혀진 해안 내륙 쪽의 야생 흉터 계곡 주변을 찾아보세요.'),
(2841, '설계도는 안 보이는데. 몸 어딘가에 숨겨둔 거야, 아니면 날 괴롭히려고 여기 서 있는 거야?'),
(2843, '준비됐어요!'),
(2845, '걱정했어! 셰이를 집으로 데려다줘서 정말 고마워, $n.'),
(2846, '$n, 티아라 가지고 있니? 벨라타는 내게 맞서는 대가를 치렀을까?'),
(2847, '앞서 말씀드렸듯이, 야생 가죽 갑옷 제작법을 배우는 동안 저를 위해 일하게 될 겁니다. 야생 덩굴은 강력하면서도 예측 불가능한 성질을 지니고 있어, 여러분이 만들게 될 이미 튼튼한 갑옷에 무작위적이지만 강력한 효과를 더해줍니다. 하지만 이 지식을 얻는 데는 저 역시 쉽지 않았습니다. 이 과정을 시작하는 데 필요한 초기 비용은 두꺼운 가죽 열 장입니다. 가죽이 준비되면, 여러분이 패턴을 얻기 위해 해야 할 일들을 시작할 겁니다.'),
(2848, '제가 필요한 두꺼운 갑옷 키트 6개와 야생 덩굴을 가지고 있나요? 갑옷 키트 제작을 단조로운 작업이라고 생각하지 마세요. 이 키트들을 만들면서 익히게 되는 꾸준한 제작 방식은 야생 가죽 갑옷을 만드는 데 필요한 정교한 기술을 연마하는 데 도움이 될 겁니다. 보세요, 당신이 저를 위해 이런 것들을 만드는 데에는 진짜 이유가 있는 겁니다...'),
(2849, '주문한 거북이 비늘 갑옷 두 개와 장갑은 준비됐나요? 그리고 야생 덩굴도 잊지 마세요! 가장 기본적인 패턴에서도 형태의 기본 원리가 더 복잡한 의상 제작에도 잘 적용된다는 것을 알 수 있습니다. 비록 다른 아이템이지만, 거북이 비늘 갑옷의 형태는 야생 가죽 조끼를 만드는 데 필요한 세부적인 작업에 도움이 될 것입니다. 그리고 장갑은… 음, 그냥 제가 쓸 거예요. 당신은 제 밑에서 일하는 거잖아요!'),
(2850, '야생 가죽 투구에 대한 지식을 전수하기 전에 튜닉과 머리띠, 그리고 야생 덩굴 한 조각이 필요합니다. 머리 장비는 모험가들 사이에서 매우 귀중한데, 단순한 머리띠든 머리 전체를 덮는 투구든 종류에 상관없이 그렇습니다. 장비의 외형과 상관없이 가치 있는 머리 장비를 만드는 기본 원칙은 동일합니다.'),
(2851, '바지, 부츠, 와일드바인즈 주문을 완료하셔야 패턴을 받으실 수 있습니다. 주문이 완료되셨나요? 우리가 처음 부츠 제작을 배우기 시작하면서, 좋은 부츠는 편안함과 기능성 사이의 아슬아슬한 균형을 유지해야 한다는 것을 깨닫게 됩니다. 이 두 가지를 모두 갖춘 부츠를 만들면 착용자는 저품질 제품을 신었을 때처럼 심한 피로감을 느끼지 않고 활동할 수 있습니다.'),
(2852, '거북이 비늘 팔찌와 투구는 준비됐나요? 제가 필요한 야생 덩굴 두 개도 잊지 마세요! 이제 야생 가죽 갑옷의 잠재력을 조금씩 깨닫고 있겠죠. 활용도가 무궁무진한 갑옷은 가죽세공사에게 거의 값을 매길 수 없을 만큼 귀중한 자산입니다. 제작에 필요한 자원의 양에만 제약이 있을 뿐, 완성품의 품질에는 전혀 문제가 되지 않아요!'),
(2853, '안녕하세요, $R님. 얼굴을 보니 저처럼 가죽공예가이신 것 같네요. 제 기술을 빌리러 오셨나요, 아니면 다른 용무가 있으신가요?'),
(2854, '분명히 말씀드리지만, 당신은 야생 가죽 갑옷 제작 기술을 배우는 동안 제자의 제자가 될 것입니다. 야생 덩굴은 강력하면서도 예측 불가능한 성질을 지니고 있어, 당신이 만들게 될 이미 견고한 갑옷에 무작위적이지만 강력한 이점을 더해줍니다. 하지만 이 기술을 얻는 데 저 또한 쉽지 않았습니다. 이 과정을 시작하는 데 필요한 초기 비용은 두꺼운 가죽 열 장입니다. 가죽이 준비되면, 당신은 패턴을 얻기 위해 필요한 작업을 시작하게 될 것입니다.'),
(2855, '제가 필요한 두꺼운 갑옷 키트 6개와 야생 덩굴을 가지고 계신가요? 갑옷 키트 제작은 꾸준하고 믿을 수 있는 제작 기술을 배우는 과정이라고 생각하세요. 이 키트들을 만들면서 익히게 되는 일관된 제작 방식은 야생 가죽 갑옷을 만드는 데 필요한 정교한 기술을 연마하는 데 도움이 됩니다. 모든 배움에는 목적이 있습니다. 각각의 배움을 그에 맞게 받아들이는 것이 중요합니다.'),
(2856, '거북이 비늘 갑옷 두 개와 장갑을 가지고 계신가요? 그리고 야생 덩굴도 잊지 마세요!$b$b가장 기본적인 패턴부터 시작해서, 형태의 기본 원리가 더 복잡한 의상 제작에도 잘 적용된다는 것을 배우게 됩니다. 비록 다른 아이템이지만, 거북이 비늘 갑옷의 형태는 야생 가죽 조끼를 만드는 데 필요한 세부적인 기술을 익히는 데 도움이 될 것입니다.$b$b수업이 진행될수록 제가 가르치는 기술들은 예술로 승화될 것입니다.'),
(2857, '야생 가죽 투구에 대한 지식을 전수하기 전에 튜닉과 머리띠, 그리고 야생 덩굴 한 조각이 필요합니다. 머리 장비는 모험가들 사이에서 매우 귀중한 자산인데, 단순한 머리띠든 머리 전체를 덮는 투구든 그 종류는 다양합니다. 가치 있는 머리 장비를 만드는 기본 원칙은 장비의 외형과 관계없이 동일합니다.'),
(2858, '바지, 부츠, 그리고 와일드바인즈를 패턴을 배우기 전에 제게 가져다주세요, $n. 제가 부탁한 대로 했나요?$b$b우리가 가장 먼저 부츠 만드는 법을 배울 때부터, 좋은 부츠는 편안함과 기능성 사이의 아슬아슬한 균형을 유지해야 한다는 것을 깨닫게 됩니다. 이 두 가지를 모두 갖춘 부츠를 만들면 착용자는 저품질 제품을 신었을 때처럼 심한 피로감을 느끼지 않고 활동할 수 있습니다.'),
(2859, '거북이 비늘 팔찌와 투구는 준비됐나요? 제가 요구하는 야생 덩굴 두 개도 잊지 마세요. 이제 야생 가죽 갑옷의 잠재력을 조금씩 깨닫기 시작했겠죠. 활용도가 무궁무진한 갑옷은 가죽세공인에게 거의 값을 매길 수 없을 만큼 귀중한 자산입니다. 제작에 필요한 자원의 양에만 제약이 있을 뿐, 완성품의 품질에는 전혀 문제가 되지 않으니까요!'),
(2860, '안녕하세요, $r님. 얼굴을 보니 저처럼 가죽공예가이신 것 같네요. 제 기술을 빌리러 오셨나요, 아니면 다른 용무가 있으신가요?'),
(2862, '우리가 그들을 물리쳤는데도 계속 공격해오네! 누군가 또는 무언가가 그들을 광란에 빠뜨리고 있는 게 틀림없어... 아, 돌아왔군, $n? 현상금을 받으려면 내가 원하는 갈기를 갖고 있나?'),
(2863, '시간이 얼마 남지 않았어, $n! 알파들을 제거했다는 보고를 하러 오지 않으면 시간을 낭비하는 거야!'),
(2865, '조개껍데기 있어요? 부티 베이에 사는 제 사촌이 조개껍데기 한 짐을 기다리고 있는데, 점점 초조해하고 있어요!'),
(2869, '$n, 당신이 제게 주어진 임무를 확인하러 오셨다면 아주 좋습니다. 제가 찾는 건 헤이트크레스트 비늘 10개입니다. 만약 잡담을 하러 오셨다면, 지금은 그런 시시콜콜한 이야기를 나눌 시간이 없습니다. 알아두십시오. 우리 나이트 엘프는 호전주의자가 아닙니다. 우리 종족은 평화와 조화를 지키는 데 헌신합니다. 하지만 그렇다고 해서 우리가 스스로의 이익을 적극적으로 지키지 않겠다는 뜻은 아닙니다. 이는 페더문 장군님과 요새에 대한 제 의무입니다.'),
(2870, '샬자루 경을 쓰러뜨리는 것은 그들의 계획을 몇 주, 아니 몇 달씩 지연시킬 것입니다. 게다가 그가 발견한 유물은 우리에게도 분명히 흥미로운 대상입니다. $n, 당신은 주어진 임무를 완수했습니까?'),
(2871, '네, 무엇을 도와드릴까요? 잠시만요, 페더문 장군님과 라트로를 도와 나가의 위협에 대처해 오셨던 분이시죠? 저는 베스티아, 라트로의, 아니, 라트로니쿠스의 아내입니다. 만나서 반갑습니다! 죄송하지만, 물론 업무차 오신 거죠. 혹시 남편분께서 제게 전해주실 게 있으신가요?'),
(2873, '$n님, 제 럼주 배송품 찾으셨나요?'),
(2874, '스톨리가 내 술을 토해냈나요?'),
(2875, '약간 멍해 보이시네요. 법률 문서를 읽어보셨나요?'),
(2876, '숨이 차 보이시네요. 저에게 무슨 말씀이라도 있으신가요?'),
(2877, '$r, 지금 맡은 임무에 대해 협상하려는 생각은 절대 하지 마! 신들이 저 점액 괴물들을 죽이길 원했다면 벌써 기적을 일으켜 해결했겠지?!'),
(2878, '당신은 병들고 변질된 듯한 송플라워 식물을 발견했습니다. 식물에서는 역겹고 불쾌한 냄새가 풍깁니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(2879, '이퀴넥스 모놀리스는 폐허 속에 조용히 서 있다. 저것은 무엇을 쥐고 있는 것일까?'),
(2880, '트롤들이 차고 다니는 부족 목걸이 다섯 개를 갖고 싶어요. 더 자세히 설명하자면, 트롤 한 마리를 처치하면 하나를 얻을 확률이 높아요! 와일드해머 가문에 당신의 가치를 증명해 보세요!'),
(2881, '트롤들이 차고 다니는 부족 목걸이 다섯 개를 갖고 싶어요. 더 자세히 설명하자면, 트롤 한 마리를 처치하면 하나를 얻을 확률이 높아요! 와일드해머 가문에 당신의 가치를 증명해 보세요!'),
(2882, '이 상자는 잠겨 있습니다!'),
(2903, '$n님, 다시 오신 것을 환영합니다. 놀족의 계획에 대한 구체적인 증거를 찾으셨나요?'),
(2904, '어? 커노비가 살아있다고??'),
(2922, '테크봇을 찾으셨나요? 메모리 코어를 회수하셨나요?'),
(2924, '필수 인공 물질은 가지고 계신가요?'),
(2926, '우리가 지금 난쟁이 종족 전체를 치료하려고 애쓰고 있는 거 안 보여?! 초록색 빛이 더 필요해!'),
(2928, '만약 이게 경주였다면, 당신은 벌써 졌을 거예요.'),
(2929, '임무가 완료되었습니까? 그는 선처를 구걸했습니까? 자비를 구걸했습니까?'),
(2930, '프리즘 펀치 카드 가지고 계세요?'),
(2932, '당신은 제 임무를 완료하지 못했습니다, $n.'),
(2933, '안녕하세요, 친절한 $C님. 오늘은 하루가 길었고, 실험은 하나도 성공하지 못했네요... 부디 좋은 소식을 전해주시길 바랍니다.'),
(2934, '$n, 손상되지 않은 독주머니를 가지고 있나요? 저는 그 신선한 독으로 실험을 해보고 싶어서, 실험에 사용할 작고 아주 귀여운 동물들을 주문해 놨어요!'),
(2936, '거미 신의 이름을 아시나요?'),
(2937, '독에 감염됐나요?'),
(2938, '당신이 오신다는 소식을 전했습니다, $n. 제게 주실 소포가 있습니까?'),
(2941, '편지라니, 나한테 온 편지인가?'),
(2942, '$n 님, 돌아오셔서 기쁩니다. 발견하신 내용을 빨리 듣고 싶습니다.'),
(2943, '안녕하세요, $n님. 다르나소스에 가보신 적 있으세요?'),
(2944, '드디어 돌아왔군, $n. 그리고 커글이 나를 위해 만들어준 장치도 가져왔군. 완벽해.'),
(2945, '당신 앞에 놓인 이 기괴한 기계에는 "스파클매틱 5200"이라는 명판이 붙어 있습니다. 명판 아래 설명서를 읽어보니, 이 기계는 물건에 묻은 먼지를 닦아내는 데 사용되는 것 같습니다. 동전 투입구가 있어, 물건을 안에 넣으면 은화 세 개를 넣어 작동을 시작할 수 있습니다. 아까 주운 먼지가 잔뜩 묻은 반지가 이 기계에 딱 맞는 물건처럼 보이네요!'),
(2946, '익숙해 보이는 이 받침대가 뜨거운 모래 위로 솟아 있다. 어쩌면 이것이 여기에 있는 데에는 어떤 의미가 있을지도 모른다...'),
(2947, '이봐요, 진정하세요. 전 아주 중요한 사업가랍니다! 택배 기사가 월세 배달을 늦었을 뿐이겠죠... 잠깐... 당신은 제 집주인이 아니시잖아요. 아, 물론 아니시죠. 제가 바보였네요! 당신은 아이언포지에서 가장 훌륭한 보석 세공사를 찾으러 오셨잖아요. 저주받은 물건은 절대 만들지 않는 그 보석 세공사를 말이죠! 네! 음... 무슨 용건이신가요?'),
(2948, '제가 필요한 재료를 가지고 계신가요? 제가 운이 좋았더라면 당신에게 부탁하지 않았을 거예요...'),
(2949, '우리가 그 더러운 난쟁이들을 능가할 방법을 스스로 찾아낼 거라고 생각했겠지. 심지어 그 장비도 애초에 우리 걸 훔쳐간 게 틀림없어! 쳇, 그 기름때 묻고 더러운... 어, 네? 뭐 필요한 거 있으세요?'),
(2950, '제가 필요한 재료를 가지고 계신가요? 제가 요청한 모든 것이 없으면 이 디자인을 개선할 수 없습니다.'),
(2951, '이 장치를 작동시키려면 먼지가 잔뜩 묻은 물체와 은화 세 개가 필요한 것 같습니다. 이 두 가지만 있으면 스파클매틱 5200은 작동할 것입니다.'),
(2953, '스파클매틱 5200은 비어 있습니다. 먼지가 잔뜩 묻은 물건과 은화 세 개만 있으면 작동을 시작할 수 있습니다!'),
(2954, '계속 진행하기 전에 돌지기의 목적을 알아야 합니다...'),
(2962, '흠, 빛이 나지 않네. 좋은 징조야.'),
(2966, '익숙해 보이는 이 받침대가 뜨거운 모래 위로 솟아 있다. 어쩌면 이것이 여기에 있는 데에는 어떤 의미가 있을지도 모른다...'),
(2967, '$n님, 다시 오신 것을 환영합니다. 디스크를 잘 활용하셨나요, 아니면 아무 소용이 없었나요?'),
(2970, '킨달은 준비할 시간이 필요하지만, 우리는 이미 수십 명을 처치했습니다. 그림토템 부족은 우리가 이 지역에 있다는 것을 잘 알고 있으며, 마치 독사처럼 우리를 노리고 있습니다. 그들은 우리의 목을 베기 위해 무슨 짓이든 할 겁니다. 경계를 늦추지 마십시오... 당신이 개입했으니 이제 당신도 그들의 표적이 될 겁니다.'),
(2972, '안녕하세요, 꼬마야. 사원에 더 강력한 모험가가 오게 되어 기쁘구나. 시간이 된다면 어린 모험가들에게 이야기 한두 편 들려줄 수 있겠니? 많은 이들이 너의 지혜에서 도움을 받을 수 있을 거야. 미안하구나, 내가 너무 무례했지. 자네는 도움을 청하러 사원에 왔는데, 폐를 끼치는 것 같네. 부디 용서해 주겠나. 빛의 종들이 자네를 위해 무엇을 해 줄 수 있는지 말해 주게.'),
(2973, '스프라이트 다터는 자극을 받으면 위험한 녀석들이니 조심해서 상대하세요, $c. 그리고 이 근처에 있는 나이트 엘프들은 더더욱 조심해야 합니다. 그 성가신 녀석들은 숲 속에 숨어 있는 경우가 많거든요. 날개를 충분히 모으면 알려주세요. 꼭 후하게 보상해 드리겠습니다!'),
(2974, '$C, 내 말을 진지하게 받아들여. 그림토템 일족은 사악해. 그들의 행방을 알아냈다면, 돌아가서 그들에게 첫 일격을 가해야 해... 그들이 우리 땅으로 쳐들어와 마을을 파괴하고 땅을 약탈하기 전에 말이야.'),
(2975, '$n, 어서 움직여. 아니면 내가 요청한 일이 너무 어려운 건가?'),
(2976, '빨리 와, $c. 오늘 해야 할 일이 많아.'),
(2977, '$n님, 다시 오신 것을 환영합니다. 디스크를 잘 활용하셨나요, 아니면 헛수고만 하셨나요?'),
(2978, '이게 뭔가요?'),
(2979, '우리는 고르둔니가 왜 여기에 있는지 더 자세히 알아내야 합니다.'),
(2980, '$n님, 유적을 찾으셨나요?'),
(2982, '고르둔니족 주변을 조심하세요. 그들의 마법은 그들이 서 있는 바로 그 땅에 재앙을 불러일으키는 것 같습니다.'),
(2987, '어서 올라가서 땅 파기 시작해! 갈 곳도 많고 만나야 할 사람도 있어. 시간은 금이야!'),
(2988, '새장들을 다 뒤져봤니, $n? 샤프비크를 찾아야 해!'),
(2989, '서둘러, $n! 만약 사악한 가지 트롤들이 날카로운 부리를 가지고 있다면, 그들이 그에게 무슨 짓을 할지 누가 알겠어!'),
(2990, '$n, 선물을 가져오셨나요?'),
(2991, '$n님, 네크룸의 메달을 가지고 계신가요? 그 안에 숨겨진 힘을 꼭 알아내고 싶습니다.'),
(2994, '샤프비크를 구해주세요!'),
(2995, '하이베일 엘프들을 고립시키는 것이 핵심입니다. 오두막을 찾으셨나요?'),
(3002, '$r, 뭘 가져오셨습니까?'),
(3022, '커글에서 또 다른 배송품이 온 거겠죠?'),
(3042, '$n, 네가 내게 화를 가져다준 거야?'),
(3062, '에다나가 전국에 퍼뜨리는 증오를 반드시 막아야 합니다.'),
(3063, '북쪽봄 하피의 날개는 밤처럼 검으니, 눈을 떼지 마라. 그렇지 않으면 어둠 속으로 사라져 버릴 테니까.'),
(3065, '전열을 강화할 또 다른 $r이군. 이 정도면 충분해. 도끼 같은 좋은 무기를 들기엔 좀 힘들겠지만, 창도 다른 어떤 무기 못지않게 좋아. 시련의 계곡에 온 걸 환영한다.'),
(3082, '젠샨이 앞에 선 훌륭한 $C를 보니 정령들도 흡족해하는구먼.$b$b$C의 길은 우리에게 가장 오래된 삶의 방식 중 하나지. 호드가 아제로스에서 겨우 살아남으려 애쓰던 시절, 그들은 우리를 찾아와 가르쳐 달라 했어. 많은 것의 비밀을 보여 달라고 말이야. 그들은 이미 강했지. $C의 방식으로도, $C의 방식으로도. 하지만 그때는 $C의 길이 그들의 길이 아니었어... 그때는.'),
(3083, '시련의 계곡에 오신 것을 환영합니다, $n. 제 태블릿을 받지 않으셨다면 여기까지 오지 못하셨겠죠. 그러니 바로 본론으로 들어가겠습니다. 저는 르와그이고, 이 계곡에서 도적, 도둑, 소매치기들을 훈련시키는 일을 맡고 있습니다. 앞으로 닥칠 일에 대비가 안 되신다면, 핸드가 도움을 요청할 대상이 바로 저입니다. 하지만 걱정 마세요. 핸드가 당신의 모든 행동을 통제하지는 않을 겁니다. 다만, 그들이 당신의 재능을 필요로 할 때는 협력하는 것이 현명할 겁니다.'),
(3084, '아, 반갑습니다, $n님. 오셔서 기쁩니다. 가르쳐야 할 학생들이 너무 많아 하루하루가 길고 바쁘지만, $n님 같은 분을 뵙게 되어 큰 성취감을 느낍니다. 저도 예전에 당신 나라의 샤먼 중 한 분께 가르침을 받았던 시절이 생각나네요.'),
(3085, '오셨군요... 정말 잘됐어요! 영혼들이 당신이 곧 켄자이를 만나러 올 거라고 말해줬어요. 시련의 계곡에 오신 걸 제일 먼저 환영해 드리고 싶네요. 이곳이 오래도록 당신의 집은 아니겠지만, 있는 동안 최선을 다해 보세요.'),
(3086, '벌써 마이아를 기쁘게 해 주려고 애쓰는구나, $n. 좋은 일이야. 마이아를 존중하면 마이아도 널 존중해 줄 거야. 하지만 그런 건 이제 그만하고, 넌 마법에 대해 배우러 온 거지 마이아의 말을 들으러 온 게 아니잖아. 마이아가 마법에 대해 가르쳐 줄 수 없는 게 딱 하나 있는데, 그건 바로 타락을 막는 방법이야, $n.'),
(3087, '많은 사람들이 저에게 $c가 되고 싶다는 소망을 품고 찾아오지만, 실제로 그 꿈을 이루는 사람은 드뭅니다. 사람들은 우리 일을 과소평가하기 쉽습니다. $c가 된다는 것은 단순히 조준하고 쏘는 것 이상의 의미를 지닙니다.'),
(3088, '쉿, 너무 크게 말하지 마. 적은 사방에 귀를 기울이고 있어.'),
(3089, '드디어 오셨군요. 언제쯤 모습을 드러내실지 궁금했습니다. 얼마 전에 양피지를 보냈는데, 도착했는지 확신할 수 없었거든요. 하지만 이제 잡담은 그만하고… 당신은 선택받았기 때문에 여기에 오신 겁니다. 우리 민족의 영적인 삶을 이끌도록 선택받으신 겁니다.'),
(3090, '드디어 도착했군... 그것도 아주 조용히 말이야. 잘됐군. 우리 세상은 어리석은 자들 투성이야, $n. 심지어 막강한 스랄조차도 대부분의 사람들이 알아채지 못하는 큰 결점을 가지고 있지. 그는 이 땅을 완전히 우리 것으로 만들기 위해 필요한 힘에 등을 돌렸어! 우리는 네더의 존재들에게 조종당하고 이용당했던 그 사람들이 아니야. 우리는 우리 스스로의 사람들이야. 우리는 자긍심이 강하고... 강하다고.'),
(3091, '아, 드디어 오셨군요, $c. 제 편지에 거짓말은 없었습니다, $n. 우리도 우리 부족의 드루이드나 샤먼과 마찬가지로 특별한 종족입니다. 당신도 그들 못지않게 중요한 존재입니다. 우리는 국경을 지키고, 켄타우로스를 사냥하고, 전쟁에 나서는 자들이니까요.'),
(3092, '나라체 캠프에 오신 것을 환영합니다, $n. 자네에 대한 좋은 이야기를 많이 들었네. 자네의 혈통은 강하고, 많은 장로들이 자네가 이미 뛰어난 재능을 지녔다고 생각하지만, 우리는 그것을 시험해 볼 것이네. 멀고어 평원은 당분간 자네의 보금자리가 될 것이니, 이곳을 잘 알아두도록 최선을 다해야 하네. 언젠가 자네는 더 높은 기술을 익히기 위해 미지의 땅으로 떠나게 될 것이네. 그때를 대비해야 하네.'),
(3093, '하늘에서 물방울이 떨어지는 것처럼 순식간에 당신이 내 앞에 나타났습니다. 이렇게 서두르신 것이 기쁩니다. 이는 당신이 우리의 만남과 당신이 이곳에 온 것의 중요성을 잘 알고 있다는 뜻이니까요. 저는 지도자는 아니지만 자연의 섭리를 이해하고 우리 민족의 영혼과 소통할 수 있습니다. 당신에게도 그렇게 할 수 있도록 가르쳐 드리겠습니다.'),
(3094, '도착하셨군요. 잘 오셨습니다. 우리 조상들의 영혼이 멀고어와 그 너머 지역에서 불안해하고 있지만, 그 이유는 알 수 없습니다. 자연의 정령들의 소리에 귀 기울이고 그들의 화신이 되는 법을 배우는 것은 영원히 당신의 의무가 될 것입니다. 이 점을 명심하십시오.'),
(3095, '아, 도착했군. 잘 왔어. 몇몇 사람들이 ''죽음''을 면하고 마을로 향하고 있다는 소식을 들었어. 그런 강인함이 미래에도 도움이 될지도 모르겠군. 자유를 준 건 실바나스 덕분이야... 정신과 육체의 자유 말이지. 비록 여전히 역병과 그 후유증에 시달리고 있지만, 이제 네 마음대로 자유롭게 드나들 수 있어.'),
(3096, '여기까지 왔군? 잘했어. 앞으로 더 많은 도적이 필요할 거야. 섀도우스토커즈는 적절한 시기가 되면 널 찾아낼 테니, 실수하거나 후회할 만한 짓은 하지 마. 그들에게 필요한 건 유능한 요원이지, 소매치기나 바보가 아니야.'),
(3097, '아, 화재, 역병, 폭동, 그리고 그보다 훨씬 더 끔찍한 일들 속에서 또 한 명의 "충실한 자"가 내 문을 두드리는군. 좋아, $c. 자네가 앞으로 나아가려는 동기를 갖기 전에 몇 가지 설명해 줄 게 있나? 자네에게는 성스러운 빛이 더 이상 중요하지 않고, 자네 조상들의 영혼은 허구이며, 저승의 존재들은 자네를 원하지 않아. 여기까지 이해했나?'),
(3098, '$n, 네가 내게 올 줄 알았어. 네가 자신의 길을 갈 의지가 없어서가 아니라, 우리는 마음이 통하는 사람들이기 때문이야. 우리 둘 다 고통을 느껴봤고, 괴로움을 겪었지. 그리고 이제 우리는 우리 것이라고 알고 있는 것들을 되찾을 힘을 원해. 이 땅, 우리의 삶, 우리의 운명을 말이야. 하지만 네가 배워야 할 것은 아직 많아.'),
(3099, '형제여, 어서 오소서. 오실 줄 알았습니다. 시간 문제였을 뿐이죠. 제가 한 말이 흥미로웠나 보군요. 당신의 마음을 건드렸어요... 제 말이 진실임을 직감하셨겠죠. 좋습니다. 하지만 이것만은 알아두십시오. 저는 실바나스를 배신하지 않습니다. 오히려 실바나스는 제 주장을 높이 평가할 겁니다. 포세이큰이 지금의 처지에 놓이게 된 것은 바로 그녀의 신념 때문이니까요.'),
(3100, '아, 내 편지 받았군, $n... 잘됐군. 최근 엘윈 숲에 전사들이 많이 몰려들었는데, 스톰윈드에는 좋은 일이지만 그 지역 오크들에게는 안 좋은 일이지.'),
(3101, '드디어! 형제끼리 얼굴을 마주 보게 되었군. 노스샤이어에 온 것을 환영한다. 이곳은 네가 이곳저곳을 익히며 지내는 짧은 기간 동안 너의 보금자리가 될 것이다. 하지만 스톰윈드는 멀지 않은 곳에 있고, 머지않아 너의 길은 그곳으로 이어질 것이다. 그때까지는 인내심을 가져라... 은빛 손 기사단의 일원이여.'),
(3102, '무사히 도착하셨군요. 그리고 당신을 본 사람도 별로 없는 것 같으니 다행입니다. 저는 여기서는 관심이 쏠리는 걸 좋아하지 않거든요... 조용하고 편안해야죠. 이해하시리라 믿습니다. 혹시 무슨 문제라도 있으신가요? 없으시다니 다행입니다. 하지만 곧 문제가 생길 겁니다.'),
(3103, '아, 드디어 오셨군요. 당신이 제게 올 줄 알았습니다. 성스러운 빛이 당신과 당신이 선택한 길을 비추고 있습니다. 지금은 험난한 시대입니다. 불타는 군단이 여전히 아제로스에 주둔하고 있고, 칼림도르 전체가 스스로의 시련을 극복할 새로운 방법을 모색하고 있습니다. 당신은 할 수 있는 한 많은 이들을 도와야 합니다.'),
(3104, '안녕하세요, $n님. 저는 켈든입니다. 도와드릴 일이 있으신가요?'),
(3105, '아, 드디어 오셨군요. 정말 다행입니다, $n. 방금 전 경비병 몇 명이 여기 와서 저를 이상한 눈으로 쳐다보더군요… 한심한 인간들 같으니.'),
(3106, '오늘 진짜 춥네, 그렇지? 눈이 절대 안 녹는 것 같아.'),
(3107, '드디어 왔군! 정말 다행이야. 콜드리지 밸리와 그 너머에는 할 일이 산더미 같아. 네가 내게 필요한 만큼 나도 네 도움이 필요할 거야! 이제 넌 실버 핸드 기사단의 일원이 되었으니, 그 역할을 다할 준비를 해.'),
(3108, '오셨군요! 잘 오셨다니 다행입니다! 저를 굳이 추적하지 않아도 이곳이 보이시죠? 하하!'),
(3109, '오셨군요! 훌륭합니다! 최근 우리 클랜에 많은 분들이 오셨는데, 아이언포지 클랜의 또 한 분이 합류하게 되어 기쁩니다. 차가운 칼날을 손에 쥐고 그림자처럼 따라다니는 것만큼 좋은 건 없죠. 여기 계신 걸 보면 무슨 말인지 정확히 아실 겁니다!'),
(3110, '아! 왔구나, $n! 정말 잘했어! 솔직히 네가 올 수 있을지 의심스러워서 포기할 뻔했어... 알겠어, 믿음을 잃다? 농담이야, 친구... 아, 됐어. 어차피 넌 내 시시한 농담 들으러 온 게 아니잖아.'),
(3112, '아, 또 임무 수행 중인 $R이 보낸 메모군... 참 특이하군.$B$B아니, 아니, 농담하는 거 아니야, 꼬마야. 네 끈기는 정말 존경스럽군. 아이언포지가 다크 아이언 드워프에게 점령당했다면 나도 똑같이 화가 났을 테니, 네 처지를 내가 이해 못 한다고 생각하지 마.'),
(3113, '제 편지를 받고 와주셔서 기쁩니다. 상사에게서 온 메모인 척해서 보낸 건 죄송해요... 기분 나쁘게 하려는 의도는 전혀 없었어요. 그냥 우리 둘뿐 아니라 같은 부류의 사람들이 서로 도와야 한다는 걸 알고 있었거든요. 같은 도시에 당신과 내 부류가 모여 사는 걸 좋게 생각하는 사람은 많지 않지만, 저는 우리가 잘 헤쳐나갈 수 있을 거라고 생각해요. 어떻게 생각하세요?'),
(3114, '네, 그게 뭐라고요, $r? 좀 더 크게 말씀해 주시겠어요? 맥주 몇 잔 마셔서 잘 안 들려요.'),
(3115, '훌륭하군! 내 메모를 받았군, 분명히.$b$b주변의 바보들은 무시해, $n. 성스러운 빛이라니?! 검과 방패라니?! 우리처럼 열린 마음을 가진 자들이 택할 길이 아니야. "일반적인" 마법이 우리 고향에 어떤 짓을 저질렀는지 봐. 그 빌어먹을 기계공들 때문에 우리 종족은 거의 멸종할 뻔했잖아. 그런데 이제 우리는 드워프들에게 의존해야 하는데, 그들은 우리 고향을 재건하는 걸 돕기보다는 인간과 동맹을 맺는 데 더 열중하고 있어. 우리는 마치 이등 시민 같아. 그들이 우리를 어떻게 바라보는지 봤나?'),
(3116, '오셨군요. 정말 기쁩니다. 지난 몇 년 동안 많은 일들이 일어났죠. 텔드라실의 건설, 이곳저곳 숲 생물들의 타락, 페랄라스처럼 잃어버렸다고 생각했던 땅의 발견… 정말 짧은 시간 안에 많은 일들이 벌어졌습니다. 하지만 우리가 여기에 온 이유는 그런 것들 외에도 많습니다. 가장 중요한 이유는 우리 종족을 더 이상의 악으로부터 지키는 것이죠.'),
(3117, '어서 오셨군요, $n. 섀도우글렌에 오신 것을 환영합니다. 제 문장이 당신을 잘 보살펴 주기를 바랍니다. 전에 말씀드렸듯이, 저는 당신을 $c로 훈련시키기 위해 왔습니다. 전투에서 도움을 줄 짐승들을 길들이고, 정확한 활쏘기를 가르치고, 우리가 고향이라 부르는 이 땅과 그 너머의 땅을 존중하는 법을 가르치기 위해서 말입니다.'),
(3118, '안녕하세요, $n님. 저를 찾아주셔서 기쁩니다. 혹시 오시는 길에 길을 잃으신 건가 싶었어요. 제가 인장을 보내드린 이후로 섀도우글렌에는 특별히 새로운 일은 없었지만, 정보 수집은 $n님께 맡기겠습니다. 원하시면 알드라실 주변 사람들에게도 물어보세요.'),
(3119, '$n 님, 이렇게 빨리 오셔서 기쁩니다. 환영합니다. 아마 들으셨겠지만, 텔드라실 전체가 여행자들의 왕래로 분주합니다. 얼라이언스 소속원들조차도 앞으로 다가올 모험을 준비하는 다른 칼도레이들을 만나기 위해 텔드라실의 숲에 들어올 수 있도록 허가를 받았습니다.'),
(3120, '아, 젊은 $c. 학업을 계속하고 싶어하는 것 같군. 좋아. 그런데 에메랄드 드림에서 얼마나 시간을 보냈는지 궁금하군. 아직 준비가 안 됐을지도 모르겠군… 시간이 지나면 괜찮아질 거야. 하지만 그때까지는 다른 이야기를 나눠보는 게 좋겠지.'),
(3121, '예?'),
(3122, '제라쉬 씨와 이야기해 보셨나요?'),
(3123, '짐승들을 포획할 수 있었나요?'),
(3124, '히포그리프를 포획할 수 있었나요?'),
(3125, '요정 용들의 음악을 포착할 수 있었나요?'),
(3126, '숲 속을 거니는 사람들의 모습을 포착하셨나요?'),
(3127, '산의 거인들을 포획할 수 있었나요?'),
(3128, '제가 필요한 자료들을 다 모아주셨나요?'),
(3141, '내 말을 끊지 마세요, $r.'),
(3161, '혹시 어려움을 겪고 계신가요?$B$B타나리스 어디에서든 가즈리디안을 찾을 수 있으니 계속 찾아보세요!$n'),
(3181, '아니요, 저는 문을 열어주지 않겠습니다.'),
(3182, '안녕하세요, 젊은이. 박물관 구경해 보시겠어요?'),
(3201, '난 그걸 믿지 않아.'),
(3281, '은을 가지고 계신가요?'),
(3301, '$c, 네 몸에서 황무지의 먼지 냄새가 나. 먼 길을 여행했구나.'),
(3321, '오늘 우리는 당신의 기사단에 대한 헌신을 기념하는 행사를 마무리합니다.'),
(3341, '이 문제는 매우 중요합니다, $n. 우리는 재앙의 세력이 병력을 증강하려는 모든 시도를 막아야 합니다.'),
(3361, '제 장비들만 다시 찾으면, 이곳을 떠나려고 해요.'),
(3362, '저 계곡에 있는 선인장을 좀 더 자세히 보고 싶은데... 그러니 일부는 온전하게 남겨두시겠어요?'),
(3363, '당신은 병들고 변질된 듯한 송플라워 식물을 발견했습니다. 식물에서는 역겹고 불쾌한 냄새가 풍깁니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(3364, '네, 저는 더넌 모피상입니다. 제게 주실 말씀이 있으신가요?'),
(3365, '뜨거운 아침 커피가 듀넌에게 제시간에 도착했기를 바라요! 제 머그잔도 잊지 않고 가져다주셨나요?'),
(3367, '난 못 갈 것 같아...'),
(3368, '<토리우스가 흐느낀다.>'),
(3369, '도와드릴 일이 있을까요?'),
(3370, '도와드릴 일이 있을까요?'),
(3372, '제단은 비어 있다.'),
(3373, '에라니쿠스가 말했던 정수의 샘에 가까워질수록 그의 목소리가 다시 한번 당신의 마음에 울려 퍼집니다. "그래, 필멸자여. 이 정수의 샘은 내 정신 속에 남아있는 순수한 기운을 이 보석에 담아 구원해 줄 것이다. 보석을 샘 안에 넣고 녹색 용군단의 마법으로 내 존재의 타락과 오염을 정화하도록 하라. 그래야만 진정한 해방을 찾을 수 있고, 녹색 용군단은 아탈라이에 대한 통치권을 되찾을 수 있을 것이다."'),
(3374, '우리는 또 다른 갈림길에 서 있다. 이제 또 다른 선택을 해야 할 때가 왔다. 필멸의 존재여, 당신은 어떤 선택을 하시겠습니까?'),
(3375, '또 다른 물약을 만들려면 마나 물약, 석탄 한 조각, 그리고 달콤한 꿀이 필요해. 거기에다가 엄청난 인내심도 필요하겠지.'),
(3376, '샤프터스크가 죽었다는 증거를 가져오면 그는 더 이상 우리를 괴롭히지 않을 것이다. 내가 원하는 건 그의 머리다, $n. 우리는 사냥을 위해 살고 있으며, 우리를 역습할 만큼 교활한 자를 사냥하는 것보다 더 짜릿한 사냥은 없다. 젊은이, 이 임무를 성공적으로 완수한다면 내 말이 무슨 뜻인지 알게 될 것이다.'),
(3377, '제 이야기를 마저 들려드리겠습니다.'),
(3378, '$n님, 무슨 일로 달의 신전에 오셨나요?'),
(3379, '어떤 정보를 가지고 계십니까?'),
(3381, '저는 주인님의 명령에 따라 이곳에 머물고 있습니다. 주인님의 탑까지 올라가는 교통비는 제가 원하는 대로 요구할 수 있도록 허락받았습니다. 지금은 제 특제 화살을 계속 만들기 위해 여행자 한 명당 깃털 두 개만 요구하고 있습니다. 조심하지 않으면 가격을 올리겠습니다. 금화 여섯 닢은 어떠십니까? 네, 그럴 줄 알았습니다. 조심만 하시면 가격을 그대로 유지하겠습니다.'),
(3382, '안드론을 만나봤어? 그는 언더시티를 거의 떠나지 않으니까 찾는 건 그리 어렵지 않을 거야.'),
(3385, '무역의 달인은 아직 살아있나요?'),
(3441, '제가 말을 마치도록... $r.'),
(3442, '필요한 재료는 다 모으셨나요?'),
(3443, '8개, $n. 8개가 필요해요!'),
(3444, '라쳇은 여기서 멀지 않아요, $n. 금방 도착할 거예요.'),
(3446, '조각상을 자세히 살펴보니, 옆면에 마본이 당신에게 준 토큰 크기만 한 움푹 들어간 부분이 눈에 띕니다...'),
(3449, '오, 오, 오, 여기 오셨군요, $n. 티모르의 탁본은 받으셨나요? 이곳이 위험하긴 하지만, 해안가에서는 별다른 사건이 없었어요. 나가들이 물속에서 헤엄치고 있어서 그런 걸지도 모르지만, 그건 제 문제가 아니죠... 저는 하늘을 순찰하니까요.'),
(3452, '적절한 신비로운 에너지원이 없으면 복수의 횃불은 완성될 수 없다.'),
(3453, '채널링 과정을 방해하지 마십시오.'),
(3461, '돌아왔구나! 반갑다. 내 그림 도구 세트도 가지고 있니?'),
(3463, '$n님, 길을 잃으셨나요?'),
(3501, '탐사에서 뭔가 성과를 거두셨나요?'),
(3502, '자, 드레네시스트? 기억나? (쿠미샤가 주먹을 꽉 쥐고 네 머리를 두드린다.) 누구 없니?'),
(3504, '아, 벨그롬이 드디어 눈치를 채고 자기 부하가 아닌 사람을 보내 우리를 돕게 했군. 이 진영에는 원래 전사가 열두 명이나 있었는데, 지금은 모두 죽었어. 그 마법사 림토리가 모두 죽였지. 벨그롬을 마치 류트처럼 조종했어… 심지어 유혹까지 했지. 내 알 바는 아니지만, 솔직히 말해서 그녀는 정말 유혹적인 여자야. 아마 그래서 내가 아직도 벨그롬을 돕고 있는 걸지도 몰라. 나라도 아마 똑같이 했을 거야.'),
(3505, '검은 가죽 표지에는 금박으로 ''칼도레이 소환의 서''라는 제목이 선명하게 새겨져 있다. 책장을 넘기자 매우 오래되었지만 상태가 훌륭한 책이라는 것을 알 수 있다. 글자는 고대 언어로 쓰여 있을 거라고 짐작된다... 혹시 칼도레이어일까? 본능적으로 블러드 엘프들의 배신에 대한 복수를 마친 후 이곳으로 다시 돌아와야 할 것 같다는 생각이 든다.'),
(3506, '$n, 블러드 엘프 반역자 학살은 어떻게 되어가고 있나? 진전은 있나? 네가 그 개 같은 년을 무릎 꿇게 할 만큼 강하길 바란다! 그 년은 자기가 저지른 모든 짓에 대한 대가로 고통스러운 죽음밖에 받을 자격이 없어!'),
(3507, '$C, 자네 기억나네. 날 배신한 그 계집애를 처치해달라고 아즈샤라에 가달라고 부탁했었지! 정말 오래전 일 같군. 설마 아그토르랑 다른 이들도 다 죽은 건 아니겠지!'),
(3510, '그들은 어디에 있나요?'),
(3511, '돌아왔군요! 놀랍습니다, $r. 진짜 이름을 알아냈나요?'),
(3513, '뭐 있어?'),
(3514, '우리는 동맹이 우리 땅에 들어오는 것을 용납할 수 없습니다, $n. 이 사실을 알리십시오.'),
(3517, '자네가 모아야 할 이 석판들은 적절한 사람들에게 전달하면 꽤 큰돈을 벌어다 줄 걸세. 석판들을 다 찾으면 누구에게 전달해야 하는지 알려줄게. 하지만 난 바보가 아니니까... 전달했다는 증거를 확보한 후에 자네 몫을 줄게. 그러니 어서 시작해. 시간이 없어. 어쩌면 다른 사람을 고용해야 할지도 몰라.'),
(3518, '네, $n님. 무슨 일로 오셨습니까? 처리해야 할 일이 많아서 빨리 말씀해 주시면 감사하겠습니다.'),
(3520, '$n, 당신은 비명 지르는 영혼의 정수를 모았습니까?'),
(3521, '재료를 모아주세요, $n. 이베론이 우리의 도움이 필요해요.'),
(3522, '오... $n, 돌아와 줘서 정말 기뻐요.'),
(3523, '저는 정치에는 관심이 없습니다. 당신이 호드 편이든 얼라이언스 편이든 상관없습니다. 저는 모든 종족에게 닥친 직접적이고 심각한 위협을 진압하는 데 더 관심이 있습니다... 그리고 이곳에는 아주 큰 위협이 도사리고 있죠. 만약 당신이 모든 종족을 위한 진정한 영웅이 될 의향이 있다면, 제가 당신에게 준 맹세석을 제게 넘겨주십시오. 저는... 이 지역 출신이 아닙니다. 우리 종족에게 맹세석은 약속의 증표로서 중요한 의미를 지닙니다.'),
(3524, '최근 들어 이 괴물들이 다크쇼어 해안에 놀라울 정도로 많이 나타나기 시작했습니다. 이는 분명 불길한 징조일지도 모릅니다. 남쪽에서 그 괴물의 뼈 샘플을 확보한다면 다르나서스에서 이 상황을 파악하는 데 도움이 될 것입니다!'),
(3526, '신병 냄새는 마치 훌륭한 폭발물 냄새처럼 멀리서도 맡을 수 있지. 폭발 기술의 달인이 되려고 온 건가?'),
(3527, '모세루의 예언이 새겨진 석판을 가지고 있습니까, $n? 제가 그 석판을 얻게 되면, 그것들을 연구하여 하카르의 정수를 담는 방법을 배우겠습니다!'),
(3528, '$n, 하카르의 화신을 물리쳤습니까? 그의 정수가 제가 당신에게 준 알에 힘을 불어넣었습니까?'),
(3541, '그래, 무슨 일이야? 오늘 처리해야 할 일이 많아서 넌 내 일정에 없어. 계속 졸라대면 바꿔줄게.'),
(3542, '어머나... 놀랍지도 않네요? 모험가시군요...! 제가 뭘 도와드릴까요...?'),
(3561, '무엇을 도와드릴까요, $n님?'),
(3562, '글쎄, 마가타가 뭐라고 했더라? 그 늙은 마녀는… 분명 꽤 불친절했을 거야.'),
(3563, '제스리몬과 이야기해 봤어? 그는 트롤 중에서도 좀 고약한 녀석이지만, 정보는 대체로 정확하고 보수도 괜찮아. 그의 태도만 견딜 수 있다면, 그의 사업을 통해 꽤 많은 돈을 벌 수 있을 거야.'),
(3564, '안드론을 만나봤어? 그는 언더시티를 거의 떠나지 않으니까 찾는 건 그리 어렵지 않을 거야.'),
(3565, '자일렘은 뭐라고 했어? 너한테 무슨 짓이라도 한 건 아니지? 마법을 걸었거나? 속여서 자기 일을 시킨 건 아니지?'),
(3566, '난 네 말을 믿지 않아! 증거를 보여줘!'),
(3568, '이게 어디로 이어질지 알잖아, $n? 저 여자는 절대 살아남을 수 없어... 저 여자 꼴 좀 봐. 지금 저 여자에게 가장 좋은 건 우리를 도와 전염병 치료법을 찾는 거야. 저 여자가 마신 물에 치료법을 알아낼 단서가 있을지도 몰라. 어차피 죽을 운명인데, 죽기 전에 우리 민족을 위해 숭고한 일을 하는 게 낫지 않을까? 동의하지 않아?'),
(3569, '언더시티에 온 이유는 이곳의 연금술사들이 자신들의 병을 치료하기 위해 오랫동안 고된 연구를 해왔다는 소문을 들었기 때문입니다. 어쩌면 그들이 저에게도 도움을 줄 수 있을지도 모른다는 생각이 들었습니다. 이곳은 저를 환영하는 분위기가 전혀 아니지만, 다른 선택의 여지가 없었습니다. 저를 덮친 병이 제 마음을 찢어놓고 있었고, 저는 그들의 도움이 절실히 필요했습니다.'),
(3570, '이게 어디로 이어질지 알잖아, $n? 저 여자는 절대 살아남을 수 없어... 저 여자 꼴 좀 봐. 지금 저 여자에게 가장 좋은 건 우리를 도와 전염병 치료법을 찾는 거야. 저 여자가 마신 물에 치료법을 알아낼 단서가 있을지도 몰라. 어차피 죽을 운명인데, 죽기 전에 우리 민족을 위해 숭고한 일을 하는 게 낫지 않을까? 동의하지 않아?'),
(3601, '저 빌어먹을 블러드 엘프 놈들. 내가 당신만큼 강했더라면 직접 내려가서 혼쭐을 내줬을 텐데! 하지만 어쩔 수 없이 당신에게 돈을 주고 그놈들을 처리해 달라고 해야겠군.'),
(3602, '악은 잠들지 않는다, 바보야. 네가 마침내 죽으면 쉴 시간이 생길 것이다. 자, 이제 그 수정들을 가져오너라.'),
(3621, '로라무스라니, 정말 오랜만에 듣는 이름이군요.'),
(3625, '단조 과정을 중단하면 불완전한 무기가 만들어질 수 있습니다. 인내심을 가지세요, $n.'),
(3627, '셋이 하나가 되고, 그 하나가 길을 밝히리라.'),
(3628, '더 이상 두려워할 것이 없다.'),
(3629, '신병 냄새는 마치 훌륭한 폭발물 냄새처럼 멀리서도 맡을 수 있지. 폭발 기술의 달인이 되려고 온 건가?'),
(3630, '네, 네, 오늘 어떤 필요 사항을 도와드릴까요? 물론이죠, 저는 여기 서서 사랑하는 우리 도시가 방사능에 오염된 죽음의 구름 속에 잠겨 있는 모습을 지켜보고만 있으니 그럴 시간은 충분히 있습니다.'),
(3632, '네, 네, 오늘 어떤 필요 사항을 도와드릴까요? 물론이죠, 저는 여기 서서 사랑하는 우리 도시가 방사능에 오염된 죽음의 구름 속에 잠겨 있는 모습을 지켜보고만 있으니 그럴 시간은 충분히 있습니다.'),
(3633, '신병 냄새는 마치 훌륭한 폭발물 냄새처럼 멀리서도 맡을 수 있지. 폭발 기술의 달인이 되려고 온 건가?'),
(3634, '네, 네, 오늘 어떤 필요 사항을 도와드릴까요? 물론이죠, 저는 여기 서서 사랑하는 우리 도시가 방사능에 오염된 죽음의 구름 속에 잠겨 있는 모습을 지켜보고만 있으니 그럴 시간은 충분히 있습니다.'),
(3635, '안녕하세요! 혹시 집 벽을 뚫고 들어온 추적 로봇 때문에 연락하셨다면, 제 변호사에게 먼저 상담받으시도록 안내해 드리겠습니다. 그 외에는, 오늘 무엇을 도와드릴까요?'),
(3636, '암넨나르는 반드시 박멸되어야 한다. 어서 가라.'),
(3637, '안녕하세요! 혹시 집 벽을 뚫고 들어온 추적 로봇 때문에 연락하셨다면, 제 변호사에게 먼저 상담받으시도록 안내해 드리겠습니다. 그 외에는, 오늘 무엇을 도와드릴까요?'),
(3638, '서류에 서명하셨고 저에게 건네주실 준비가 되셨다면, 그걸로 끝입니다. 이제 되돌릴 수 없는 여정이라는 걸 알려드렸습니다. 준비되셨다면, 탑승하세요!'),
(3639, '당신이 제작한 공학 아이템을 검토할 수 있게 되면, 우리만의 특별한 모임인 고블린 기술자 클럽에 가입하는 데 필요한 마지막 지식을 알려드리겠습니다!'),
(3640, '만약 당신이 서류에 서명했고 제게 넘겨줄 준비가 되었다면, 그걸로 끝입니다. 제가 당신과 공유할 비밀은 너무나 중대한 것이기에 비밀 서약서에 서명하는 것은 절대적으로 필수적입니다. 저도 서명했고, 제 형제자매인 노움 엔지니어들도 서명했습니다. 엔지니어 $n님, 당신은 아주 영광스러운 대열에 합류하게 될 겁니다!'),
(3641, '제가 여러분이 제작한 공학 아이템을 검토할 수 있게 되면, 여러분은 공인 노움 공학자가 되어 전 세계 어디에서든 노움 공학자 조련사를 무제한으로 이용할 수 있게 됩니다.'),
(3642, '당신이 서류에 서명했고 제게 넘겨줄 준비가 되었다면, 그걸로 끝입니다. 저는 그노메레간, 특히 그 얼간이 팅크마스터 오버스파크의 의견에 격렬하게 반대하지만, 정치적으로 비밀 서약은 그 무엇보다 중요합니다! 당신은 평생 동안 하나의 길을 선택하고 그 길에 충실히 따르겠다고 서약해야 합니다.'),
(3643, '제가 여러분이 제작한 공학 아이템을 검토할 수 있게 되면, 여러분은 공인 노움 공학자가 되어 전 세계 어디에서든 노움 공학자 조련사를 무제한으로 이용할 수 있게 됩니다.'),
(3644, '회원 카드를 갱신하려면 금화 두 닢의 갱신 수수료를 지불해야 합니다.'),
(3645, '회원 카드를 갱신하려면 금화 두 닢의 갱신 수수료를 지불해야 합니다.'),
(3646, '회원 카드를 갱신하려면 금화 두 닢의 갱신 수수료를 지불해야 합니다.'),
(3647, '회원 카드를 갱신하려면 금화 두 닢의 갱신 수수료를 지불해야 합니다.'),
(3661, '가능하면 그들을 피하세요, $n. 와일드킨은 당신의 관심을 자신들에게 해를 끼치려는 의도로 오해할 수도 있습니다.'),
(3701, '새로운 정보를 가져오셨나요?'),
(3702, '타우리산 이야기를 마저 들려드리겠습니다.'),
(3741, '안녕. 내 목걸이가 그리워. 아빠가 사주셨는데. 아빠는 호수에 괴물이 있다고 하셔. 혹시 괴물들을 물리쳤니?'),
(3761, '편히 쉬시오, 이등병. 운고로에서 흙을 내려놓으러 온 거라면 아주 잘 왔소! 그렇지 않다면, 사라지시오.'),
(3764, '아, 그래, 흙 말이지. 대드루이드는 모험가 한 명당 흙을 스무 짐씩 요구하는데, 우리는 그 스무 짐을 모두 얻을 것이다. 우리를 꾀하는 자들은 모두 쓰러져 버리게 놔두자!'),
(3781, '평화와 고요가 당신과 함께하길, 친구여. 당신은 대드루이드의 명령을 받고 이곳에 온 것이오, 맞소?'),
(3782, '평화가 함께하길, 친구여. 자네는 대드루이드의 명령을 받고 온 것이오, 그렇지?'),
(3783, '여기서 시작해야 할 일이 많아요. 모피들을 최대한 빨리 보내주세요!'),
(3785, '네, $n님, 대드루이드님의 중요한 연구를 위해 모로우그레인을 좀 재배하셨나요? 당신의 도움 덕분에 운고로 분화구의 신비로운 특성이 날이 갈수록 더 명확해지고 있습니다.'),
(3786, '네, $n님, 대드루이드님의 중요한 연구를 위해 모로우그레인을 좀 재배하셨나요? 당신의 도움 덕분에 운고로 분화구의 신비로운 특성이 날이 갈수록 더 명확해지고 있습니다.'),
(3791, '저는 모로우그레인 10알을 찾고 있습니다. 그 정도면 최소한 연구를 시작하기에는 충분할 것 같습니다. 물론 잘못된 방향으로 가다 보면 많이 낭비하게 되겠지만, 연구라는 게 원래 그런 거죠.'),
(3792, '안녕하세요, $n님. 제 연구는 꽤 잘 진행되고 있지만, 혹시 모로우그레인이 다섯 개 더 있으시면 기꺼이 받겠습니다. 음... ''기꺼이''라는 말은 비유적인 표현입니다. 모로우그레인 주변에 있을수록 불편한 기분이 들거든요. 하지만 연구를 위해서는 어쩔 수 없이 이 과정을 마무리해야 합니다.'),
(3802, '그 조각상은 당신 위로 불길하게 솟아 있습니다.'),
(3803, '대드루이드는 세나리온 서클의 지속적인 연구를 위해 항상 추가적인 모로우그레인을 찾고 있습니다. 모로우그레인은 10개 단위로 수집하며, 수집할 때마다 유용한 물품들을 보상으로 드립니다. 10개를 모으면 저에게 알려주세요. 그러면 그에 상응하는 보상을 드리겠습니다.'),
(3804, '대드루이드는 운고로 분화구에서 진행되는 세나리온 서클의 연구 프로젝트에 필요한 모로우그레인을 항상 찾고 있습니다. 모로우그레인은 10개 단위로 수집하며, 모을 때마다 유용한 물품들을 보상으로 드립니다. 10개를 모으면 저에게 알려주세요. 그러면 그에 맞춰 보상해 드리겠습니다.'),
(3822, '샤니 찾았어? 괜찮은 거야?'),
(3823, '병사, 자네 군복에 묻은 피는 턱없이 부족하군!'),
(3824, '오, 영광스러운 날이여! 머리를 가지고 돌아오셨습니까?'),
(3825, '그래서요? 그 행사를 그림으로 그리셨나요?'),
(3841, '안녕하세요, $c님. 제 위치에 속지 마세요. 사실 저는 경주 때문에 온 게 아닙니다... 물론 경주가 재미있긴 하지만요. 저는 지금 사우전드 니들즈에 와서 이 땅을 얼마나 되살릴 수 있는지 조사하고 있습니다. 새롭고 비옥한 토양으로 이 지역을 되살리고 복원하는 것이 제 일종의 사명이 되었거든요. 어쩌면 근처에서 수원지를 찾을 수도 있겠죠. 페랄라스와 사우전드 니들즈 사이의 경계가 얼마나 이상한지 눈치채지 못하셨나요? 그 경계가 생길 때 뭔가 기묘한 마법이 작용한 게 분명해요.'),
(3842, '여기 오래 머무를수록 이 경주에 참가하고 싶은 유혹이 점점 커지네요, $n. 정말 놀랍군요… 혹시 영약을 찾으셨나요? 알이 건강한지 아닌지 알게 되면 부화할 때까지 보관해 두시도록 돌려드리겠습니다. 알려주세요.'),
(3843, '안녕하세요, $n님. 어떻게 도와드릴까요?'),
(3845, '안녕하세요. 전에 본 적 있는 것 같은데요... 그렇지 않나요?'),
(3861, '닭은 차갑고 어두운 눈으로 당신을 응시합니다. 굶주린 듯 당신을 기다립니다. "바카아아! 꼬꼬댁... 꼬꼬댁... 꼬꼬댁."'),
(3881, '여기서 살아남으려면 식량이 가득 담긴 큰 상자가 꼭 필요할 거야. 그리고 연구 장비라도 일부 되찾을 수 있다면 이 끔찍한 상황 속에서 정말 다행스러운 일이겠지.'),
(3882, '나에 대해 어떻게 생각하든 상관없지만, 그들이 연구할 뼈가 고대 스테고돈이나 디메트라돈의 뼈인지, 아니면 우리가 야영지를 세우려 할 때 우리를 거의 잡아먹을 뻔했던 짐승들의 뼈인지는 신경도 안 쓸 거야. 난 그저 우리가 여기서 살아남기만 하면 행복할 뿐이야...'),
(3883, '$n님, 제가 연구할 수 있도록 고리시 벌집 샘플을 가지고 계신가요?'),
(3884, '안녕하세요! 저와 제 동료들은 이곳에서 흉포한 짐승들 외에 다른 생명체들을 보게 되어 기쁩니다! 운고로 분화구에는 무슨 일로 오셨나요?'),
(3901, '이 일에 미적거리는 자들은 마을에서 쓰러진 우리 형제자매들처럼 목적 없이 방황하게 될지도 모릅니다. 당신은 그들보다 더 나은 결과를 얻기를 바랍니다, 그렇죠?'),
(3902, '혹시 우리를 위해 쓸 만한 물건이라도 좀 구해 오셨나요? 버려진 물건을 재활용하는 건 부끄러운 일이 아니잖아요. 아무도 우리에게 구걸하지 않을 겁니다. 우리 포세이큰은 스스로 살아남아야 해요!'),
(3904, '$n, 내 수확물을 가지고 있나요?'),
(3905, '기분이 좋아 보이시네요! 이리 오세요! 앉으셔서 한잔 하세요!'),
(3906, '요소들이 여전히 뒤죽박죽입니다, $n.'),
(3907, '곧 이 땅이 불길에 휩싸일 것이다. 서두르라, $n!'),
(3908, '어머나... 링켄이 드디어 내게 검을 보내줬군요.'),
(3909, '벌써 돌아오셨어요?'),
(3911, '그것들을 내게 보여줘!'),
(3913, '이것이 바로 가에리얀이 언급했던 묘비임이 틀림없어...'),
(3914, '어머! 기억나요! 당신은… 아니, 말하지 마세요!'),
(3921, '$c님, 저는 지금 일이 너무 바빠요. 혹시 저에게 부탁하실 일이 없으시다면, 다른 곳으로 가주시는 게 좋겠습니다.'),
(3922, '$n님, 너겟 슬러그 있으세요? 이 사모플란지를 눈여겨보고 있는데, 어서 만져보고 싶네요.'),
(3923, '머리 조심해! 내 일에 방해되면 안 돼!'),
(3924, '설명서 있으세요?'),
(3961, '안녕하세요, $n님! 다시 인사드립니다!'),
(3962, '블레이저러너는 황금 불꽃을 사용하여 만들어낸 오라 뒤에서 거의 무적입니다. 오직 당신만이 아쿠에멘타스의 은빛 토템으로 그 오라를 제거할 수 있습니다.'),
(3982, '이 바보야, 방어해 봐!'),
(4001, '무슨 일로 이 신성한 곳에 오셨습니까?'),
(4003, '<모이라 공주는 두려움에 떨고 있다.>'),
(4005, '돌아왔군, 그렇지? 흠... 내가 한번 살펴볼까, $n.'),
(4021, '배너 있으세요?'),
(4022, '사이러스의 눈은 두 개의 불타는 구체를 이룬다.'),
(4023, '사이러스의 눈은 두 개의 불타는 구체를 이룬다.'),
(4024, '거인은 쓰러졌습니까?'),
(4041, '에보루트를 가져오면 비데레 엘릭서를 만들어 줄 수 있지. 난 약초랑 연금술에 대해 온갖 걸 다 안다고. 있잖아, 점심으로 먹으려던 치즈를 금으로 연금술한 이야기를 해줄까? 어이, 어디 가는 거야?'),
(4061, '이 일을 가볍게 여기지 마세요, $n!'),
(4062, '$r, 거기 뭘 들고 있는 거야?'),
(4063, '그였을까? 그는 정말 살아있었던 걸까?'),
(4081, '무슨 일이야, $r? 내가 소대를 지휘해야 하는 거 안 보여?$B$B'),
(4082, '또 너야? $n, 정말 끈질기구나.'),
(4083, '보석들은 성배 깊숙이 떨어질 때 아무 소리도 내지 않는다...'),
(4084, '블레이즈러너를 물리치는 데 필요한 힘에 대해 더 자세히 알려드릴 수 있지만, 먼저 제가 요구하는 것들을 모아야 합니다.'),
(4101, '펠우드가 고통받고 있다는 것을 압니다. 저 또한 고통받고 있습니다! 저는 제 신념을 굳건히 지켜야만 합니다. 제가 가진 지식이 악의 손에 넘어간다면 펠우드 전체에 재앙이 닥칠 것입니다. 죽인 워프우드 정령들에게서 뽑아낸 피의 호박을 제게 가져다주시면, 당신을 믿고 부패에 맞서 싸울 방법을 함께 마련하겠습니다.'),
(4102, '펠우드가 고통받고 있다는 것을 압니다. 저 또한 고통받고 있습니다! 저는 제 신념을 굳건히 지켜야만 합니다. 제가 가진 지식이 악의 손에 넘어간다면 펠우드 전체에 재앙이 닥칠 것입니다. 죽인 워프우드 정령들에게서 뽑아낸 피의 호박을 제게 가져다주시면, 당신을 믿고 부패에 맞서 싸울 방법을 함께 마련하겠습니다.'),
(4103, '세나리온 비컨을 소유하면 대의를 위해 처치된 타락한 짐승들에게서 타락한 영혼 조각을 볼 수 있습니다. 저는 그 조각들을 갈아서 세나리온 식물 연고를 만드는 데 필요한 재료로 사용합니다. 그 연고를 사용하면 타락한 식물을 다시 건강한 식물로 되돌릴 수 있습니다. 이 조각들을 대가로 제가 미리 만들어 둔 세나리온 식물 연고 몇 개를 드리겠습니다.'),
(4104, '펠우드에서 광물을 캐는 동안 세나리온 신호기를 가지고 있다면, 원광석 광맥을 오염시키는 오염된 황산을 볼 수 있을 겁니다. 저는 그 황산을 정화해서 세나리온 식물 연고를 만드는 방법을 알고 있습니다. 그 연고는 야생에서 발견되는, 살릴 필요가 있는 식물에 사용하면 됩니다. 오염된 황산을 모아두셨다면, 제가 미리 만들어둔 세나리온 식물 연고를 드리겠습니다.'),
(4105, '세나리온 신호기를 사용하면 숙련된 약초학자는 펠우드의 타락이 낳은 사악한 펠 크리프를 발견할 수 있습니다. 저는 이곳에서의 경험을 통해 펠 크리프를 정화하여 세나리온 식물 연고라고 부르는 약으로 만드는 방법을 터득했습니다. 펠우드에서 약초를 채집할 때 신호기를 가지고 있다면 펠 크리프를 발견할 수 있을 겁니다. 저에게 가져다주시면 미리 만들어둔 세나리온 식물 연고를 드리겠습니다.'),
(4106, '세나리온 신호기를 사용하면 숙련된 가죽 벗기기 전문가가 펠우드에서 사냥한 전리품에서 오염된 가죽 조각을 찾아낼 수 있습니다. 저는 이 쓸모없어 보이는 조각들을 걸쭉한 반죽으로 만들어 세나리온 식물 연고의 경화제로 사용합니다. 펠우드에서 사냥감을 가죽 벗길 때는 꼭 신호기를 휴대하세요! 오염된 가죽 조각을 모으면 저에게 가져오세요. 제가 미리 만들어둔 세나리온 식물 연고를 드리겠습니다.'),
(4107, '마법이 해제된 마법 아이템의 힘은 그것이 만들어내는 정수에서 느껴집니다. 저는 마법사들이 사용하는 원시 정수를 세나리온 식물 연고를 만드는 데 적합한 재료로 바꾸는 방법을 고안했습니다. 세나리온 비컨은 필요 없습니다. 하급 네더 정수를 생성하는 적절하게 마법이 해제된 아이템이면 무엇이든 사용할 수 있습니다. 저는 하급 네더 정수 하나만 있으면 됩니다. 그 대가로 세나리온 식물 연고를 드리겠습니다. 이 정수는 매우 강력해서 소량만으로도 효과가 뛰어납니다!'),
(4108, '세나리온 비컨을 소유하면 대의를 위해 처치된 타락한 짐승들에게서 타락한 영혼 조각을 볼 수 있습니다. 저는 그 조각들을 갈아서 세나리온 식물 연고를 만드는 데 필요한 재료로 사용합니다. 그 연고를 사용하면 타락한 식물을 다시 건강한 식물로 되돌릴 수 있습니다. 이 조각들을 대가로 제가 미리 만들어 둔 세나리온 식물 연고 몇 개를 드리겠습니다.'),
(4109, '펠우드에서 광물을 캐는 동안 세나리온 신호기를 가지고 있다면, 원광석 광맥을 오염시키는 오염된 황산을 볼 수 있을 겁니다. 저는 그 황산을 정화해서 세나리온 식물 연고를 만드는 방법을 알고 있습니다. 그 연고는 야생에서 발견되는, 살릴 필요가 있는 식물에 사용하면 됩니다. 오염된 황산을 모아두셨다면, 제가 미리 만들어둔 세나리온 식물 연고를 드리겠습니다.'),
(4110, '세나리온 신호기를 사용하면 숙련된 약초학자는 펠우드의 타락이 낳은 사악한 펠 크리프를 발견할 수 있습니다. 저는 이곳에서의 경험을 통해 펠 크리프를 정화하여 세나리온 식물 연고라고 부르는 약으로 만드는 방법을 터득했습니다. 펠우드에서 약초를 채집할 때 신호기를 가지고 있다면 펠 크리프를 발견할 수 있을 겁니다. 저에게 가져다주시면 미리 만들어둔 세나리온 식물 연고를 드리겠습니다.'),
(4111, '세나리온 신호기를 사용하면 숙련된 가죽 벗기기 전문가가 펠우드에서 사냥한 전리품에서 오염된 가죽 조각을 찾아낼 수 있습니다. 저는 이 쓸모없어 보이는 조각들을 걸쭉한 반죽으로 만들어 세나리온 식물 연고의 경화제로 사용합니다. 펠우드에서 사냥감을 가죽 벗길 때는 꼭 신호기를 휴대하세요! 오염된 가죽 조각을 모으면 저에게 가져오세요. 제가 미리 만들어둔 세나리온 식물 연고를 드리겠습니다.'),
(4112, '마법이 해제된 마법 아이템의 힘은 그것이 만들어내는 정수에서 느껴집니다. 저는 마법사들이 사용하는 원시 정수를 세나리온 식물 연고를 만드는 데 적합한 재료로 바꾸는 방법을 고안했습니다. 세나리온 비컨은 필요 없습니다. 하급 네더 정수를 생성하는 적절하게 마법이 해제된 아이템이면 무엇이든 사용할 수 있습니다. 저는 하급 네더 정수 하나만 있으면 됩니다. 그 대가로 세나리온 식물 연고를 드리겠습니다. 이 정수는 매우 강력해서 소량만으로도 효과가 뛰어납니다!'),
(4113, '당신은 병들고 변질된 듯한 송플라워 식물을 발견했습니다. 식물에서는 역겹고 불쾌한 냄새가 풍깁니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4114, '당신은 병들고 변질된 듯한 송플라워 식물을 발견했습니다. 식물에서는 역겹고 불쾌한 냄새가 풍깁니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4115, '당신은 병들고 변질된 듯한 바람꽃 식물을 발견했습니다. 식물에 매달린 열매는 썩어 독성이 있는 것으로 보입니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4116, '당신은 병들고 변질된 듯한 송플라워 식물을 발견했습니다. 식물에서는 역겹고 불쾌한 냄새가 풍깁니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4117, '당신은 병들고 변질된, 마치 덩굴풀처럼 보이는 식물을 발견했습니다. 식물의 뿌리는 질기고 가죽처럼 보이며, 미끈미끈한 막이 식물 표면에 드리워져 있습니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4118, '당신은 병들고 변질된 듯한 송플라워 식물을 발견했습니다. 식물에서는 역겹고 불쾌한 냄새가 풍깁니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4119, '당신은 병들고 변질된 듯한 나이트 드래곤 식물을 발견했습니다. 식물에 매달린 열매는 썩어 독성이 있는 것으로 보입니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4120, '악마의 기운이 닿는 모든 것에서 기묘한 초록빛이 뿜어져 나온다… 사악하지만 동시에 매우 강력한 기운이 느껴진다.'),
(4121, '나는 이 배신자 같은 쓰레기를 받아들이겠다, $n.'),
(4123, '당신은 산의 심장을 갖고 있습니까? 제게 있어 그 가치는 무한합니다.'),
(4126, '레시피 있으세요, $n님? 저 검은무쇠 드워프들이 우리 가문의 술을 마시는 건 상상도 하기 싫어요!'),
(4127, '아, $n님, 다시 오신 걸 환영합니다. 라스칼의 최후가 비극적이긴 하겠지만, 그에 대한 단서를 조금이라도 찾으셨기를 바랍니다.'),
(4129, '긴로가 보냈군, 그렇지? 내 심리 측정 결과는 정신적으로 꽤 부담스럽지… 하지만 칼림도르 홀덤에서 지는 것도 마찬가지야. 여기 요새에서는 날 "패배의 왕"이라고 부르지. 카드 운은 없지만… 자연의 비밀을 터득한 건 운이 좋다고 봐야겠지. 어쨌든, 물론 할 수 있지. 이게 바로 라스칼의 운명을 밝혀낼 결정적인 단서가 될지도 몰라. 칼을 건네주면 시작할 수 있지.'),
(4132, '블랙록의 도살자는 처치되었습니까?'),
(4134, '썬더브루 라거 레시피 있으세요, $n님?'),
(4136, '리블리를 가지고 계신가요? 아니면 적어도 리블리의 일부라도요?'),
(4141, '라리온은 분명 뭔가 끔찍한 일을 당하게 될 거야!'),
(4142, '저는 이 숲속에서 살고 있어요... 평화롭죠. 적어도 그럴 거라고 생각했어요. 그런데 아이언포지에 살았을 때보다 오히려 방문객이 훨씬 많네요!'),
(4143, '라리온은 아직도 나한테 말을 안 걸어! 정말 원한을 오래 품는구나.'),
(4144, '계획은 이렇습니다, $n: 나가서 피꽃잎 새싹을 좀 모아 오세요. 완전히 싹이 트지 않은 것들이요. 그걸 여기로 가져오면 아탈라이 안개가 어떤 효과를 낼지 알아볼 수 있죠.$B$B당신은 제가 복수심에 불타는 줄 알겠지만... 사실 당신 말이 맞아요!$B$B사실, 저는 여기서 나가는 길을 알고 있지만, 라리온이 제 말이 맞다는 걸 인정할 때까지는 여기 있을 겁니다!$B$B그러니 어서 가서 피꽃잎 새싹을 찾고 재밌는 시간을 보내자고요!'),
(4145, '무이긴이 먼저 사과해야만 다시 말을 걸겠어!'),
(4146, '정말 힘드네요, $n. 저것들이 도무지 저를 내버려 두지 않아요!'),
(4148, '전기 충격기가 작동하려면 목표 생물의 샘플이 필요해. 분화구로 나가서 피꽃 새싹을 채취해 와. 그러면 무이긴의 녀석들에게도 효과가 있도록 조정할 수 있지... 그 녀석이 그렇게 고집스럽지만 않았더라면 벌써 집으로 돌아갈 수 있었을 텐데... 하지만 그때까지는 그 녀석의 장난이 나에게 전혀 문제가 되지 않는다는 걸 보여줘야겠어!'),
(4161, '$n, 균형을 기억하세요. 저는 여러분이 살아있는 숲에 대한 이해와 깊은 공감을 키우기를 바랍니다.'),
(4181, '신병 냄새는 마치 훌륭한 폭발물 냄새처럼 멀리서도 맡을 수 있지. 폭발 기술의 달인이 되려고 온 건가?'),
(4182, '용 사냥은 어떻게 진행되고 있나요?'),
(4183, '안녕하세요, $n님. 전에 만난 적이 있나요? 왠지 낯이 익네요.'),
(4184, '스톰윈드 요새에 오신 이유가 무엇인가요?'),
(4185, '<볼바르가 당신을 유심히 지켜보고 있습니다.>'),
(4186, '볼바르 측에서 소식 있나요?'),
(4201, '재료 있으세요? 제 마음의 구멍이 저를 집어삼킬 것 같아요!'),
(4221, '당신은 병들고 변질된 듯한 바람꽃 식물을 발견했습니다. 식물에 매달린 열매는 썩어 독성이 있는 것으로 보입니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4222, '당신은 병들고 변질된 듯한 바람꽃 식물을 발견했습니다. 식물에 매달린 열매는 썩어 독성이 있는 것으로 보입니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4224, '존과 이야기해 봤어?'),
(4244, '미스릴 외피가 들어가는 패널은 여전히 닫혀 있다. A-Me 01의 나머지 부분은 여전히 움직이지 않는다.'),
(4245, 'A-Me를 도와주셨나요? 말씀하신 미스릴 외피가 파손된 게 문제의 원인이었던 것 같아요. 그걸 교체하면 A-Me가 다시 작동해서 집으로 돌아올 수 있을 거예요.'),
(4262, '잘린다 씨가 당신의 머리를 빤히 쳐다보고 있는 것 같습니다.'),
(4263, '그 악마는 죽었나요?'),
(4264, '<윈저 원수가 당신 손에 든 쪽지를 유심히 살핍니다.>$B$B그게 뭐죠, $n?'),
(4265, '신고할 내용이 있으신가요, $n님?'),
(4267, '친구여, 이 축복받은 사원에 오신 것을 환영합니다. 페더문 요새에서 당신이 이곳에 도착할 것이라는 예언을 받았습니다. 샨드리스 페더문이 가져오라고 부탁한 보고서를 가지고 있습니까?'),
(4281, '탈라나르에 오신 것을 환영합니다, $c님. 도움이 필요하신가요?'),
(4282, '머지않아 이 거대한 계략은 끝날 것이다.'),
(4283, '불타는 초원을 지배하라, 지배권을 장악하라.'),
(4284, '내가 뭔가 중요한 단서를 찾은 것 같아, $n!'),
(4285, '$n님, 그 전봇대에 가보셨나요?'),
(4286, '지금은 귀찮아, $n. 나랑 윙키가 회의에 참석해야 하거든.'),
(4287, '$n님, 그 전봇대에 가보셨나요?'),
(4288, '$n님, 그 전봇대에 가보셨나요?'),
(4289, '이곳의 괴물들에게 벌써 패배했단 말인가, $n? 그렇게 쉽게 낙담하지 마라. 운고로의 유인원들을 추적하고 물리치는 것은 위대한 사냥꾼에게조차 쉬운 일이 아니다.'),
(4290, '내 말을 가볍게 여기지 마시오, $n. 진정으로 이 괴물과 맞서 싸우고 싶다면 조심해야 하고… 현명해야 하오. 라르코르위를 끌어내어 물리치려면 엄청난 힘과 통찰력이 필요할 것이오.'),
(4291, '조심해, $n. 알 둥지 근처에 접근하면 어미들을 자극할 거야... 설령 네가 이미 어미에게서 분비샘을 확보했더라도 말이지. 어미들은 새끼를 지키기 위해 싸울 때는 라르코르위만큼이나 위험할 수 있어. 하지만 네가 성공한다면, 우리는 라르코르위를 숨어있는 곳에서 불러낼 확실한 방법을 얻게 될 거야.'),
(4292, '두려움에 굴복하지 마세요, $n. 두려움은 가장 큰 배신자입니다... 강해져야 합니다! 고기를 가져다가 작은 골짜기에 놓고, 그 위에 샘을 사용하세요. 그래야만 죽음이 당신을 찾아올 것입니다.'),
(4293, '대조군으로 사용할 변질된 샘플이 최소 다섯 개는 필요합니다, $n. 필요한 만큼의 펠우드 점액 샘플을 계속 수집해 주십시오. 실바나스 님께서 명하셨습니다...'),
(4294, '네, $n님? 검색은 잘 진행되고 있나요?'),
(4295, '오, 에일! 다크 아이언 에일 한 잔만 있으면 뭐든지 할 수 있어!! 빨리, 정신 차려야겠어! 술이 깨니까 시야가 흐릿해지잖아... 그리고 네가 지난주에 내가 죽인 $r처럼 보이잖아!'),
(4296, '$n, 당신은 일곱 신의 글을 가지고 있습니까? 그들의 석판에 새겨진 비밀을 알아냈습니까?'),
(4297, '$n, 고기 찾았어? 네 알이 이제 곧 부화할 것 같아. 첫 식사를 제대로 못 먹으면 일주일도 못 넘길지도 몰라. 그런 일이 생기면 정말 싫거든. 솔직히 말해서, $n. 네가 이 알을 얻게 된 것 자체가 부러워. 이렇게 도와준 걸 후회하게 만들지 마.'),
(4300, '제 고객들은 그렇게 참을성이 없거든요, $n. 발톱은 좀 얻으셨나요?'),
(4301, '우차... 그 짐승은 정말 웅장했어. 거대하고 붉은 털에 단검만 한 이빨을 가졌지. 팔은 나무줄기처럼 굵었고, 내가 본 어떤 퓨마보다도 빨랐어. 그런 용맹의 시험을 마주하게 된 걸 행운으로 여겨야 할 거야. 우리 부족은 그런 짐승을 몇 세대에 걸쳐 보지 못했을 테니까.'),
(4322, '$n님, 많이 지쳐 보이시네요. 벽난로 옆에 앉아서 좀 쉬시는 게 좋겠어요.'),
(4342, '제 이야기를 마저 들려드리겠습니다.'),
(4343, '당신은 병들고 변질된 듯한 바람꽃 식물을 발견했습니다. 식물에 매달린 열매는 썩어 독성이 있는 것으로 보입니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4381, '파일론 테이블을 사용하면 녹색 파워 크리스탈과 노란색 파워 크리스탈을 조합할 수 있습니다. JD의 설명서에 따르면, 이 조합은 자신이나 아군을 치료하는 데 사용할 수 있습니다.'),
(4382, '파일론 테이블을 사용하면 녹색 파워 크리스탈과 파란색 파워 크리스탈을 조합할 수 있습니다. JD의 설명서에 따르면, 이 조합은 정신력을 증가시키는 데 사용할 수 있습니다.'),
(4383, '파일론 테이블을 사용하면 녹색 파워 크리스탈과 빨간색 파워 크리스탈을 조합할 수 있습니다. JD의 설명서에 따르면, 이 조합을 사용하면 물리적 손상에 대한 보호력을 강화할 수 있습니다.'),
(4384, '파일론 테이블을 사용하면 빨간색 파워 크리스탈과 파란색 파워 크리스탈을 조합할 수 있습니다. JD의 설명서에 따르면, 이 조합을 사용하면 적의 방어력을 약화시킬 수 있습니다.'),
(4385, '파일론 테이블을 사용하면 빨간색 파워 크리스탈과 노란색 파워 크리스탈을 조합할 수 있습니다. JD의 설명서에 따르면, 이 조합을 사용하면 적에게 피해를 줄 수 있는 강력한 폭발을 일으킬 수 있습니다.'),
(4386, '파일론 테이블을 사용하면 파란색 파워 크리스탈과 노란색 파워 크리스탈을 조합할 수 있습니다. JD의 설명서에 따르면, 이 조합을 사용하면 적에게 피해를 주는 방패를 만들 수 있습니다.'),
(4401, '당신은 병들고 변질된 듯한 송플라워 식물을 발견했습니다. 식물에서는 역겹고 불쾌한 냄새가 풍깁니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4402, '선인장 열매 모으기 다 하셨어요?'),
(4403, '당신은 병들고 변질된 듯한 바람꽃 식물을 발견했습니다. 식물에 매달린 열매는 썩어 독성이 있는 것으로 보입니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4421, '이곳의 부패는 생물들을 광기로 몰아넣는다...'),
(4441, '이 물이 고대인의 영혼을 해방시켜 평화를 가져다주기를 바랍니다.'),
(4443, '당신은 병들고 변질된, 마치 덩굴풀처럼 보이는 식물을 발견했습니다. 식물의 뿌리는 질기고 가죽처럼 보이며, 미끈미끈한 막이 식물 표면에 드리워져 있습니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4444, '당신은 병들고 변질된, 마치 덩굴풀처럼 보이는 식물을 발견했습니다. 식물의 뿌리는 질기고 가죽처럼 보이며, 미끈미끈한 막이 식물 표면에 드리워져 있습니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4445, '당신은 병들고 변질된, 마치 덩굴풀처럼 보이는 식물을 발견했습니다. 식물의 뿌리는 질기고 가죽처럼 보이며, 미끈미끈한 막이 식물 표면에 드리워져 있습니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4446, '당신은 병들고 변질된, 마치 덩굴풀처럼 보이는 식물을 발견했습니다. 식물의 뿌리는 질기고 가죽처럼 보이며, 미끈미끈한 막이 식물 표면에 드리워져 있습니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4447, '당신은 병들고 변질된 듯한 나이트 드래곤 식물을 발견했습니다. 식물에 매달린 열매는 썩어 독성이 있는 것으로 보입니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4448, '당신은 병들고 변질된 나이트 드래곤 식물로 보이는 것을 발견했습니다. 식물에 매달린 열매는 썩어 독성이 있는 것으로 보입니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4449, '시간이 없어! 저 비단 천 조각들을 가져와! 아니, 지질학자들을 말이야. 저 지질학자들을 데려와! 저들은 내, 아니, 네 분노를 느껴야 마땅해.'),
(4450, '네, 네? 무슨 일로 오셨나요, $r님? 제가 지금 굉장히 바쁘고 많은 손님들이 제 서비스를 요청하고 있어서요. 좀 빨리 처리해 주실 수 있을까요? 실례되는 말씀은 아니지만, 밀린 일을 다 처리하려면 시간이 정말 부족해서요.'),
(4451, '*콜록* 누구세요? 제가 바쁜 거 안 보이세요?'),
(4461, '당신은 병들고 변질된, 마치 덩굴풀처럼 보이는 식물을 발견했습니다. 식물의 뿌리는 질기고 가죽처럼 보이며, 미끈미끈한 막이 식물 표면에 드리워져 있습니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4462, '당신은 병들고 변질된 나이트 드래곤 식물로 보이는 것을 발견했습니다. 식물에 매달린 열매는 썩어 독성이 있는 것으로 보입니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4463, '구성 요소를 제시하라, 필멸자여. $B$BI는 이 제작물에 대한 대가로 금화 30개를 요구할 것이다.'),
(4464, '당신은 병들고 변질된 듯한 송플라워 식물을 발견했습니다. 식물에서는 역겹고 불쾌한 냄새가 풍깁니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4465, '당신은 병들고 변질된 듯한 송플라워 식물을 발견했습니다. 식물에서는 역겹고 불쾌한 냄새가 풍깁니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4466, '당신은 병들고 변질된 듯한 바람꽃 식물을 발견했습니다. 식물에 매달린 열매는 썩어 독성이 있는 것으로 보입니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4467, '당신은 병들고 변질된 듯한 바람꽃 식물을 발견했습니다. 식물에 매달린 열매는 썩어 독성이 있는 것으로 보입니다. 이 식물을 정상으로 되돌리려면 어떤 조치든 시급히 필요합니다.'),
(4481, '이 세상 모든 것에는 대가가 따르기 마련입니다. 당신이 찾는 그 물건의 가격은 금화 서른 닢입니다. 물론, 당신이 모은 재료의 대부분은 제가 가지겠지만, 걱정 마세요. 당신은 그 장신구를 갖게 될 겁니다.'),
(4482, '금 30개, 루스 달러. 금 30개와 필요한 구성 요소.'),
(4483, '만약 당신이 회복력을 원한다면, 금 30개를 요구합니다.'),
(4484, '시간 낭비하지 마, $R. 내가 요구하는 것만 줘. 금화 30개랑 부품들.'),
(4491, '링고 때문에 너무 걱정했어요...'),
(4492, '뭐... 뭐라고요?'),
(4496, '적당한 향선(냄새샘)을 찾는 데 시간이 좀 걸릴지도 몰라요. 향선 자체는 손상될 수 없지만, 얻는 과정 자체가 쉽지 않거든요. 흙은 쉽게 구할 수 있을 거라고 생각해요. 그런데, 유인제를 만드는 데 필요한 재료는 다 가지고 계신가요?'),
(4501, '솔직히 말해서, 전 그 이상한 생물들에 대해 그다지 걱정하지 않았어요... 그러다 어느 날 커다란 돌에 "프테로닥스를 조심하라"라고 쓰여 있는 걸 보게 됐죠. 누가 썼는지 모르겠지만, 너무 소름 끼쳐서 그냥 지나칠 수가 없었어요!'),
(4502, '운고로의 화산이 활화산이라는 게 사실인가요? 화산재가 좀 있으면 배울 게 많을 것 같은데요, $n.'),
(4503, '모든 훌륭한 차량에는 이름이 필요하죠... 제 생각엔 ''Pwned''라고 부르는 게 좋을 것 같아요!'),
(4504, '트란렉이 또 해냈습니다! 이 초강력 접착제는 엄청난 인기를 끌 거예요!'),
(4505, '이건 정말 중요한 일입니다. 지금 바로 가세요.'),
(4506, '그곳으로 돌아갈 수 없다고 말하지 마! 어서 가!'),
(4507, '여왕의 뇌를 확보하는 것은 우리 연구에 절대적으로 필수적입니다. 우리가 알아낸 바에 따르면, 이 실리시드들은 악의적인 지능에 의해 조종되고 있을 가능성이 매우 높습니다. 그토록 간악한 실리시드를 조종할 수 있는 존재가 무엇일지 생각만 해도 소름이 끼칩니다.'),
(4508, '저들은 바보들이야, $n! 더 큰 위협이 주변에 있는지조차 생각 못 하잖아. 호드에 대한 저들의 비이성적인 증오가 우리 모두를 파멸로 이끌 거야. 실리시드의 위협을 더 어떻게 증명해야 할지 모르겠어. 차라리 벌집에 던져 넣어 직접 보게 하는 게 나을 것 같아!$B$BI 죄송하지만, 제게 알릴 소식이 있나요?'),
(4509, '저들은 바보들이야, $n! 주변에 더 큰 위협이 있는지조차 생각 못 하고 있어. 동맹에 대한 저들의 비이성적인 증오가 우리를 파멸로 이끌 거야. 실리시드의 위협을 더 어떻게 증명해야 할지 모르겠군. 차라리 벌집에 던져 넣어 직접 보게 하는 게 나을 것 같아! 그런데, 무슨 소식을 가져오셨나?'),
(4510, '엘루네아도르입니다. 오늘 무엇을 도와드릴까요?'),
(4511, '주크 주크! 오늘 무엇을 도와드릴까요, $c님?'),
(4512, '제가 진행했던 실험 중 일부는 정말 흥미롭습니다. 조금만 더 연구하면 이 생명체들의 본질과 아제로스에서 생명이 어떻게 발전했는지, 그리고 애초에 생명 발전과 어떤 관련이 있는지 알아낼 수 있을 것 같습니다. 제가 가진 가장 큰 가설 중 하나는 점액질 생명체들이 이 행성의 생성과 관련이 있다는 것입니다. 마치 행성에서 분비된 물질처럼 말이죠. 하지만 더 많은 샘플을 확보하기 전까지는 이를 증명하거나 반증할 수 없습니다.'),
(4513, '고려해야 할 사항이 너무 많군. 하지만 이게 무슨 의미일까? 그리고 아제로스 사람들의 삶에 어떤 영향을 미칠까?'),
(4521, '내가 맡긴 임무를 완료한 후 내게 보고해.'),
(4542, '$C, 무슨 일이야? 나한테 급한 메시지라도 있어?'),
(4561, '운고로 분화구에서 점액 샘플을 채취하여 테이블 위의 여러 시험관과 비커에 넣습니다. 액체가 끓어오르고 분출되면서 점액의 색깔이 변합니다. 과정이 느려지고 액체가 가라앉으면, 정제된 운고로 점액 샘플과 다른 잔여물이 담긴 작은 페트리 접시가 보입니다.'),
(4581, '저에게 주실 것이 있으신가요?'),
(4601, '이 장치를 작동시키려면 먼지가 잔뜩 묻은 물체와 은화 세 개가 필요한 것 같습니다. 이 두 가지만 있으면 스파클매틱 5200은 작동할 것입니다.'),
(4602, '이 장치를 작동시키려면 먼지가 잔뜩 묻은 물체와 은화 세 개가 필요한 것 같습니다. 이 두 가지만 있으면 스파클매틱 5200은 작동할 것입니다.'),
(4603, '스파클매틱 5200은 비어 있습니다. 먼지가 잔뜩 묻은 물건과 은화 세 개만 있으면 작동을 시작할 수 있습니다!'),
(4604, '스파클매틱 5200은 비어 있습니다. 먼지가 잔뜩 묻은 물건과 은화 세 개만 있으면 작동을 시작할 수 있습니다!'),
(4621, '이 망할 자식, 벌써 돌아왔군! 내 명령대로 했나? 우리를 실망시키면 널 배에서 떨어뜨릴 것이다.$B$BArrrrr...'),
(4641, '전갈의 갑각은 의지가 강한 전사의 힘을 막을 만큼 두껍지 않습니다. 강하고 망설임 없이 공격하면 전갈은 손쉬운 먹잇감이 될 것입니다.'),
(4642, '실험은 어떻게 진행되고 있나, $n? 자네가 가져온 샘플들을 계속 연구하겠네. 실바나스 님께서 왜 이 생명체들에 그토록 관심을 가지시는지 이제야 알겠군. 만약 이들이 정말로 고대 신들의 일부라면, 우리에게 어떤 이득을 가져다줄 수 있을지 누가 알겠는가.'),
(4661, '펠우드에서 점액 샘플을 채취하여 테이블 위의 여러 시험관과 비커에 넣습니다. 액체가 끓어오르고 분출되기 시작하면서 점액의 색깔이 변합니다. 과정이 느려지고 액체가 가라앉으면, 변형된 펠우드 점액 샘플과 다른 잔해들이 담긴 작은 페트리 접시가 보입니다.'),
(4681, '여기 서쪽 해역에서 발견된 생물의 잔해를 조사해 주시면, 다르나서스의 달의 신전에 정식 보고서를 제출할 수 있을 겁니다. 그러면 이 불행한 생물들이 왜 어둠의 해안가에서 생을 마감하는지 그 이유를 밝혀낼 수 있을지도 모릅니다.'),
(4701, '워그 위협의 근원을 발견하고 처리하셨습니까?'),
(4721, '주문 내역은 알고 계시죠, $n.'),
(4722, '안녕하세요, $n님. 혹시 해안으로 밀려온 생물에 대한 발견이나 보고할 내용이 있으신가요?'),
(4723, '어쩌면 언젠가 우리는 이 불쌍한 생명체들이 다크쇼어 해안에서 무고하게 생을 마감하는 것을 막을 방법을 찾을 수 있을지도 모릅니다. 그때까지 우리는 연구를 계속해야 합니다! 안녕, $n - 무슨 소식이 있나?'),
(4724, '무리의 우두머리를 처치했으니, 이제 우리는 첨탑을 지키는 워그 경비병들을 하나씩 제거하고 마침내 도시로 진격할 수 있을 것이다.'),
(4725, '$n님, 다시 뵙게 되어 반갑습니다. 저희는 왜 웅장한 해양 생물들이 다크쇼어 해안에 좌초되는지 그 미스터리를 밝히기 위해 많은 노력을 기울이고 있습니다. 하지만 하나의 질문에 대한 답을 찾을 때마다 두 가지 새로운 질문이 생겨나는 것 같습니다. 저희 연구에 더 많은 도움을 주시려고 오신 건가요?'),
(4726, '$n, 음울한 정수를 갖고 있나요? 어서 연구해보고 싶네요. 게다가… 제 후원자는 실망시키고 싶지 않은 분이시거든요.'),
(4727, '안녕하세요, $n님. 혹시 달의 신전에 알려야 할 좌초된 생물을 더 발견하셨나요?'),
(4728, '안녕하세요, $n님! 무슨 일로 오베르딘에 다시 오셨나요? 혹시 또 다른 발견 소식을 전하러 오신 건가요?'),
(4729, '<키블러는 투칸 스탠과 말다툼하느라 바쁘다.>'),
(4730, '안녕하세요, $n님! 또 다른 발견 사항을 보고하러 오셨나요?'),
(4731, '안녕하세요, $n님. 달의 사원을 위해 해주신 일들이 정말 훌륭했습니다. 앞으로도 저희를 위해 더 많은 노력을 기울여 주실 수 있을까요?'),
(4732, '안녕하세요, $n님. 달의 신전에 보고할 새로운 발견 사항이 있으신가요?'),
(4733, '엘룬 신께 감사드립니다. 친애하는 $n 님, 다시 뵙게 되어 기쁩니다. 달의 신전에서는 다크쇼어에서 벌어지고 있는 기이한 해변 좌초 현상에 대한 연구를 계속 진행하고 있습니다. 혹시 추가로 알려주실 내용이 있으신가요?'),
(4734, '$n, 에그실로스코프 테스트해봤어?'),
(4735, '$n님, 계란 가지고 계신가요? 제 후원자분께서 당신이 저를 위해 계란을 모아주신다는 소식을 듣고 몹시 기대하고 계십니다!'),
(4740, '안녕하세요, $c님. 센티넬이 오늘 무엇을 도와드릴까요? 혹시 머크딥 현상금에 대해 문의하러 오셨나요?'),
(4741, '겁난다고 하지 마! 어서 가!'),
(4742, '무엇보다 용기와 인내가 중요하다, 인간이여!'),
(4743, '필멸자가여, 시간을 낭비하지 마라. 네파리안은 우리 세계에 악을 퍼뜨리기 위해 필사적으로 노력하고 있다.'),
(4762, '클리프스프링 강의 오염은 다크쇼어에서 벌어지고 있는 심각한 문제의 시작일 뿐입니다. 제공해주시는 샘플은 저희가 계획을 수립하는 데 도움이 될 것입니다... 제가 보기엔 공격 계획인 것 같습니다.'),
(4763, '타락의 부적은 자연의 균형을 무너뜨리는 사악한 장치일 뿐이다. 퍼볼그들을 괴롭히는 사티로스에게서 이 물건을 얻어 내게 가져오면, 우리는 오늘 큰 승리를 거두게 될 것이다!'),
(4764, '혹시 잠금장치 있으신가요, $n님? 제 후원자께서 아주 후하게 지불하실 겁니다.'),
(4765, '전령이 온다는 말을 들었습니다. 블랙록 첨탑에서 온 선물을 가진 전령이라고요. 당신이 그 전령인가요?'),
(4767, '$n, 내가 찾는 와이번 알을 가져왔니? 윈드 라이더 훈련을 정말 간절히 시작하고 싶어!'),
(4768, '$n, 태블릿을 찾았나요? 그 비밀을 파헤치고 싶어요.'),
(4771, '명심하세요, $n - 우리는 관용적이어야 하지만 신념에 있어서는 확고해야 합니다!'),
(4781, '금괴요? 네... 네. 금괴 하나만 가져오시면 실을 좀 뽑아드릴 수 있는지 한번 봅시다. 그때까지는 좀 더 강해지는 데 집중하시는 게 좋을 겁니다. 가장 힘든 시련은 아직 오지 않았으니까요. 그리고 장담하는데... 아무리 강하다고 생각해도, 더 잘 준비했으면 좋았을 거라고 후회하게 될 겁니다.'),
(4783, '황량한 땅은 결코 친절한 곳이 아닙니다. 나가, 거인, 사티로스, 불타는 군단… 이 모든 것들과 전쟁을 벌이는 켄타우로스 부족들 때문에 조심하지 않으면 위험천만한 곳입니다. 앞서 말했듯이, 이곳은 당신의 힘과 지혜뿐 아니라 인내심까지 시험할 것입니다. 이 땅에서는 항상 경계하십시오.'),
(4784, '곧, $n. 약속드립니다. 그 가운은 당신의 필요를 충분히 충족시켜 줄 것이며, 분명히 경쟁자들보다 우위를 점하게 해 줄 것입니다.'),
(4786, '잠시만요, $n...'),
(4787, '고대의 알을 가지고 있습니까? 거대한 기운이 감도는 것을 느낍니다. 시간이 얼마 남지 않은 것 같습니다.'),
(4788, '$n, 첨탑에 가본 적 있나요? 다섯 번째와 여섯 번째 석판을 가지고 있나요?'),
(4801, '겨울봄에는 서리검이라는 거대한 고양이과 동물과 싸우게 될 겁니다. 이 짐승들은 엄청난 속도와 교활함을 가지고 있죠. 서리검의 속도를 얻고 싶다면, 그 녀석들에게서 얻은 에코를 내게 가져오시오. 참고로, 에코를 사냥하려면 인벤토리에 마우아리의 보물 상자가 있어야 합니다.'),
(4802, '윈터스프링에서 당신은 윈터폴 퍼볼그라는 타락한 무리와 싸우게 될 것입니다. 그들의 우두머리의 뜻에 따라 그들은 엄청난 힘을 얻었습니다. 윈터폴의 힘을 얻고 싶다면, 그들에게서 에코를 찾아 내게 가져오십시오. 참고로, 에코를 사냥하려면 인벤토리에 마우아리의 보물 상자가 있어야 합니다.'),
(4803, '윈터스프링에서는 가죽이 매우 두꺼운 큰 곰들을 만날 수 있습니다. 이 샤드투스 곰들은 두꺼운 가죽 덕분에 상당한 방어력을 갖추고 있죠. 불에 대한 저항력을 얻고 싶다면 샤드투스 곰에게서 얻은 에코를 제게 가져다주세요. 에코를 사냥하려면 인벤토리에 마우아리의 보물 상자가 있어야 한다는 걸 잊지 마세요.'),
(4804, '겨울봄에는 칠윈드라고 불리는 거대한 비행 생물과 싸우게 될 겁니다. 이 짐승들은 서리 마법을 휘두르는 힘을 가지고 있죠. 서리 저항력을 얻고 싶다면 칠윈드에게서 얻은 에코를 제게 가져오세요. 에코를 사냥하려면 마우아리의 보물 상자가 인벤토리에 있어야 한다는 걸 잊지 마세요.'),
(4805, '겨울봄에는 얼음엉겅퀴 예티라는 거대한 생물과 싸우게 될 겁니다. 이 짐승들은 움직임이 느리지만, 두꺼운 털 덕분에 많은 공격을 피할 수 있습니다. 공격을 피하는 능력을 얻고 싶다면, 이 예티에게서 얻은 에코를 제게 가져다주세요. 에코를 사냥하려면 인벤토리에 마우아리의 보물 상자가 있어야 한다는 것을 잊지 마세요.'),
(4806, '윈터스프링에서 당신은 프로스트마울이라는 거대한 얼음 거인과 싸웠습니다. 그들은 엄청난 힘과 위력을 가지고 있죠. 프로스트마울의 힘을 얻고 싶다면, 그들에게서 얻은 에코를 제게 가져오세요. $B$BRememba, 에코를 사냥하려면 인벤토리에 마우아리의 보물 상자가 있어야 한다는 걸 기억하세요.'),
(4807, '윈터스프링에서는 선천적인 마법 능력을 지닌 듯한 강력한 생물들과 싸우게 될 것입니다. 이 야생 생물들은 강력한 마법을 사용할 수 있습니다. 지능을 높이고 싶다면 그곳에서 발견하는 모든 올빼미 괴물에게서 얻은 에코를 저에게 가져오세요. 에코를 사냥하려면 인벤토리에 마우아리의 보물 상자가 있어야 한다는 것을 기억하세요.'),
(4808, '여기 너무 추워요! 담요 가져왔으면 좋겠네요!'),
(4809, '$n님, 칠윈드 혼 가지고 계세요?'),
(4810, '$n! 펠녹 씨랑 얘기했어? 내가 필요한 부품들 가져왔어?'),
(4811, '저 붉은 수정에 대해 무슨 보고할 내용이 있습니까? 정말 존재하는 건가요?'),
(4812, '그 수정은 다크쇼어의 숲이 우거진 풍경과 어우러져 매우 이질적으로 보인다. 그 속 깊은 곳에서 아주 희미한 윙윙거리는 소리가 들리는 듯하다.'),
(4821, '이 신비로운 알에 대해 더 알아봐야겠어. 그 안에서 무엇이 나올지 누가 알겠어?'),
(4822, '딸기맛 말고 다른 맛의 아이스크림도 더 많이 만들어줬으면 좋겠지만, 다행히 딸기맛이 제가 제일 좋아하는 맛이에요!'),
(4841, '자, $n, 자네가 아직 사냥감을 다 잡지 못한 걸 알고 있네. 녀석들을 찾아내면 감사의 표시로 보상을 주겠네.'),
(4842, '이 샘물은 아주 특이한 성질을 가지고 있는 것 같아요... 그게 무슨 의미인지는 아직 잘 모르겠어요...'),
(4862, '가방에 거미 알이 들어있는 건가요, 아니면 저를 보고 반가워서 그러는 건가요?'),
(4864, '그래... 소식 좀 알려줘.'),
(4866, '<래기드 존이 당신을 꼬집습니다.>'),
(4867, '아! 내 마법을 가지고 있나요?'),
(4882, '다른 업무 때문에 보고하시는 건가요?'),
(4883, '어떻게 도와드릴까요, $n님?'),
(4903, '<고어투스 군벌이 경례를 한다.>'),
(4904, '탈리아 앰버하이드:'),
(4906, '부디 펠우드의 생명체들이 겪는 고통을 끝내주세요.'),
(4921, '혹시 그녀의 흔적이라도 찾으셨나요? 가슴이 너무 아파서 최악의 상황이 벌어진 것 같지만, 그래도 그녀를 무사히 찾을 수 있기를 바랍니다.'),
(4941, '제가 방해받아서는 안 된다는 것을 모르시겠습니까?'),
(4961, '$n, 그 악마를 죽여야만 구슬에서 그 존재를 영구적으로 제거할 수 있을 거야.'),
(4962, '네, $n님? 선택하셨나요? 인페르날인가요, 아니면 펠하운드인가요?$B$B각각의 선택은 개인적인 것이며, 자신의 강점과 약점을 반영해야 합니다. $C가 부족한 부분을 보완하기보다는 오히려 자신을 더욱 강화하는 경우도 드물지 않습니다. 때로는 적을 압도하는 것이 균형 잡힌 마법사가 되는 것만큼 효과적인 전략일 수 있습니다.'),
(4963, '네, $n님? 선택하셨나요? 인페르날인가요, 아니면 펠하운드인가요?$B$B각각의 선택은 개인적인 것이며, 자신의 강점과 약점을 반영해야 합니다. $C가 부족한 부분을 보완하기보다는 오히려 자신을 더욱 강화하는 경우도 드물지 않습니다. 때로는 적을 압도하는 것이 균형 잡힌 마법사가 되는 것만큼 효과적인 전략일 수 있습니다.'),
(4970, '규율과 투지가 여러분의 목표입니다. 간단한 과제를 여러 번 요청할 수도 있지만, 매번 최선을 다해 수행해야 합니다.'),
(4971, '시간의 흐름이 왜곡된 곳이라면 어디든 시간의 기생충이 만연해 있습니다. 이곳에는 많은 기생충이 존재하는 것 같고, 이는 매우 불안한 징조입니다. 당신이 발견하는 모든 기생충을 제거해 준다면, 이곳의 악화되는 시간적 상황을 제가 더 잘 통제할 수 있을 것입니다. 모든 기생충이 제거되면 저는 그것을 감지할 수 있을 것입니다.'),
(4972, '내가 찾는 시간의 장신구는 단순한 장치들입니다. 주로 시계인데, 그 시계의 시침과 분침은 안도르할에 역병이 처음 창궐했을 때의 그 순간에 영원히 갇혀 있습니다. 시간은 결코 끝나지 않으며, 당신이 내게 가져다주는 시계들은 결국 원래 있던 자리로 돌아가게 될 것입니다... 물론, 이곳에서 혼란이 계속되는 한 말입니다.'),
(4973, '안도르할의 시계들은 마치 시청 폐허 위의 큰 시계처럼 모두 세 시에 멈춰 있습니다. 바로 그때 역병이 도시 전체로 퍼져나가 도시의 생기를 앗아갔기 때문입니다. 그날 일어난 일은 우리 모두에게 큰 후회거리이지만, 그 사건은 필멸자인 당신들이 인지하는 시간의 흐름을 바꿔놓았습니다. 청동 용군단은 시간의 흐름을 지켜나가야 합니다!'),
(4974, '<노예가 으르렁거린다.>'),
(4976, '타베타와 오브를 찾는 건 잘 되어가고 있나요, $n?$B$BTabetha는 마법적인 문제에 있어서는 정말 많은 도움을 준 사람이에요. 그녀를 찾을 수만 있다면 기꺼이 도와줄 거라고 확신해요.'),
(4982, '혹시 좋은 소식 있으셨나요?'),
(4983, '고블린은 어디 있지???'),
(4984, '흑사병에 감염된 늑대들은 없애야 합니다. 그들이 옮기는 병은 치료할 수 없어요. 저도 노력해 봤지만… 결국 저 자신도 흑사병에 걸려 죽었습니다.'),
(4985, '발소리가 들려요, $n. 시야는 흐릿해졌지만, 주변은 아직 느낄 수 있어요. 병든 회색곰들의 고통은 끝났나요?'),
(4986, '세나리온 서클을 대표하여, $c님, 이 공간에 오신 것을 환영합니다. 저희와 무슨 용건이 있으신가요?'),
(4987, '세나리온 서클을 대표하여, $C님, 이 공간에 오신 것을 환영합니다. 저희와 무슨 용건이 있으신가요?'),
(5001, '혹시 좋은 소식 있으셨나요?'),
(5002, '아, $n. 정말 오랜만이네요.'),
(5022, '스톰윈드 인구 조사 사무소에 오신 것을 환영합니다. 우리 마을 주민에 대한 정보가 필요하시면 제가 도와드리겠습니다.'),
(5023, '언더시티 인구 조사팀의 도움을 받으러 오신 건가요, 아니면 아는 사람이 죽었는지 물어보러 오신 건가요? 그런 질문을 많이 받거든요.'),
(5041, '물자 수색은 어떻게 진행되고 있나요, $n? 퀼보어는 당신의 실력으로 쉽게 제압할 수 있을 거라고 믿습니다.'),
(5042, '아가마간의 힘을 얻고 싶다면 피의 파편 4개가 필요하겠소. 이 축복을 받게 된다면 네 적들은 네 힘 앞에 떨게 될 것이오. <콧방귀> 레이저메인의 가장 위대한 전사들은 바로 그런 힘을 지니고 있지!'),
(5043, '우리 부족 최고의 정찰병들은 정확도 면에서 비할 데가 없다고 하고, 어떤 도적도 그들의 전투 속도에 비할 수 없다고 하네. (<콧방귀>) 피의 조각 4개를 가져오면 퀼보어 태생보다 더 민첩하게 만들어주겠다.'),
(5044, '퀼보어 부족의 샤먼과 지오맨서들은 <콧방귀> 전투와 의식에서 아가마간의 힘을 빌려 도움을 구합니다. $r.$B$B만약 당신도 주문에 아가마간의 축복을 더하고 싶다면, 내게 피의 조각 4개를 가져오십시오. 그러면 맹글투스가 당신을 도울 것입니다. <콧방귀>'),
(5045, '모든 종류의 전사들에게는 강인한 정신력이 필요합니다. <콧방귀> 모든 희망이 사라졌을 때에도 더 큰 위업을 이루도록 이끌어주죠. <콧방귀> 레이저메인도 이를 잘 알고 있습니다. 우리는 영적인 부족입니다. 전투에서의 기량보다 아가마간과의 연결을 더 자랑스럽게 생각하죠. <콧방귀> 피의 조각 4개를 가져오면 전투에서 당신의 정신을 축복해 드리겠습니다. <콧방귀>'),
(5046, '전쟁터에 나서는 모든 이에게는 보호가 필요하오. 뼈는 튼튼해야 하고, 피부는 질겨야 하네. 우리 부족도 이를 잘 알고 있지. 깃털과 가죽이 주는 자연적인 보호막에 더해, 전쟁에 나가기 전에 아가마간에게 보호를 청하곤 하네. 피의 조각 4개를 가져오면 같은 보호를 해 주겠소.'),
(5047, '응?'),
(5048, '내 잔디밭에서 나가라고 말하고 싶지만, 보시다시피 내겐 잔디밭이 없어요.'),
(5049, '누군가 바퀴벌레를 밟을 때마다 저는 울어요. 제발 저를 울리지 말아 주세요.'),
(5050, '존, 자기야... 당신 맞아? 갑자기 너무 추워...'),
(5051, '존, 구울들이 널 잡아먹지 못하게 해... 나도 구울들에게 잡히지 않게 해... 끔찍한 구울들이야... 우리의 부적이 우리를 지켜줄 거야.'),
(5052, '우리 부족들은 황무지 곳곳의 가시덤불 지대로 몰려듭니다. 그곳은 신성한 곳이기 때문입니다. 하지만 그중에서도 레이저펜만큼 신성한 곳은 없습니다. 레이저펜 전체는 아가마간의 몸으로 이루어져 있지만, 특히 다운즈는 그의 거대한 입에서 입구가 만들어져 있어 특별히 보호받고 있습니다! 그 입은 그에게 충성하지 않는 자들을 통째로 삼켜버리고, 씹어 먹은 후에는 그들의 몸을 뱉어냅니다! 아가마간은 우리를 보호하기 위해 자신의 육신을 남겨두었고, 우리가 그를 보호할 수 있도록 그의 영혼을 내어주었습니다.'),
(5054, '지금 가, $c. 우르시우스를 찾아라.'),
(5055, '브루머란이 당신을 부릅니다, $n.'),
(5056, '샤이-로탐은 대담하고 용서가 없으며, 열렬한 열정으로 동족을 옹호할 것이다.'),
(5059, '변소 문짝 가장자리가 갈라지기 시작했는데, 마치 누군가 끊임없이 억지로 열려고 시도한 것처럼 보였다. 지금은 변소 밖에서 굳게 잠겨 있다. 문을 덜컹거리자 안에서 짐승 같은 신음 소리가 들려온다! 안에 뭐가 있든 간에, 분명 좋은 소리는 아니다.'),
(5060, '튼튼한 캐비닛 하나가 내장된 자물쇠로 단단히 잠겨 당신 앞에 서 있습니다. 캐비닛 앞면에는 깊은 긁힘과 자국이 나 있습니다. 이는 캐비닛 안에 감춰진 비밀을 밝히려는 수많은 격렬한 시도가 실패로 돌아간 흔적으로 추측됩니다. 이 캐비닛을 열려면 열쇠를 찾아야 합니다.'),
(5061, '다르나서스로의 귀환은 환영받는 일이지만, 네게 수중 형태를 가르쳐주기 전에 문글레이드에서 배운 것을 증명할 증거가 필요하겠소. 바다사자의 펜던트를 가지고 있소?'),
(5062, '모테가 파이어메인이 아리카라에 대한 소식을 전해왔는데... 정말 심각한 소식이군. 아리카라는 끔찍한 악행을 저지른 자들에게 복수하기 위해 태어난 치명적인 괴물이라고 한다.'),
(5063, '제가 필요한 모든 것을 갖추고 있지 않다면, 제 시간을 낭비하는 겁니다.'),
(5064, '그림토템이 무슨 일을 꾸미고 있는지 알아냈나요?'),
(5065, '태블릿을 가지고 계신가요? 그 안에 적힌 내용이 우리 세계에 큰 위협이 될 것이 분명해서 두렵습니다.'),
(5067, '제가 필요한 모든 것을 갖추고 있지 않다면, 제 시간을 낭비하는 겁니다.'),
(5068, '제가 필요한 모든 것을 갖추고 있지 않다면, 제 시간을 낭비하는 겁니다.'),
(5081, '상태?'),
(5082, '도와주셔서 감사합니다!'),
(5083, '당신이 발견한 것은 무엇입니까?'),
(5085, '$n님, 뭔가 찾으셨길 바랍니다. 윈터폴이 점점 더 공격적으로 변하고 있어요!'),
(5086, '저는 우리가 여기서 무슨 일이 벌어지고 있는지 알아내기 시작했다고 생각합니다, $n.'),
(5087, '윈터폴이 독한 술을 구하지 못하면 어떻게 될지 두고 보자!'),
(5088, '$n, 당신은 사악한 뱀 아리카라를 처치했습니까?'),
(5089, '$n, 거기 뭘 들고 있는 거야?'),
(5092, '$n, 최악의 상황에 대비하세요. 모든 힘을 쏟아부어야 합니다. 우리 앞에 놓인 임무는 결코 쉽지 않을 겁니다. 이곳에 병력을 집결시켜 결국 재앙에 맞서 싸울 때, 당신은 그들과 맞서는 선봉대의 일원이 될 것입니다! 슬픔의 언덕에서 당신에게 맡겨진 임무는 승리로 가는 길의 시작이 될 것입니다!'),
(5097, '탑들을 표시해 놓으면 안도르할 공격의 최우선 목표물이 될 겁니다. 탑들을 무력화시키면 안도르할의 진짜 위협이 드러날 거라고 생각합니다. 그때부터는 도시 장악을 위한 정면 승부가 펼쳐지겠죠! 성공 보고하러 돌아온 거죠? 신호등도 잊지 마세요. 물자 관리는 필수입니다.'),
(5098, '탑들을 표시해 놓으면, 안도르할 공격의 최우선 목표물이 될 겁니다. 탑들을 무력화시키면 안도르할의 진짜 위협이 드러날 거라고 생각합니다. 그때부터는 도시 장악을 위한 정면 승부가 펼쳐지겠죠!$b$b성공 보고하러 돌아온 거죠? 신호등도 잊지 마세요. 물자 관리는 필수입니다.'),
(5102, '다 됐나요?'),
(5121, '윈터폴 빌리지(Winterfall Village, $n)에서 더 많은 정보를 얻을 수 있을지도 모릅니다.'),
(5122, '이 예배당의 힘은 내 마음속의 타락에 저항할 힘을 줍니다. 이곳을 떠나면 저는 죽음의 기사가 될 것입니다. 하지만 제게 떠날 힘을 줄 메달, 신앙의 메달이 있습니다. 부디, $n, 그 메달을 되찾아 주십시오. 그 메달은 스트라솔름 서쪽의 스칼렛 요새 깊숙한 곳에 있는, 광기에 휩싸인 스칼렛 브라더후드 단원 말로르 더 젤러스가 지키고 있습니다.'),
(5123, '자, 이게 뭐지? $n이네?'),
(5124, '시간은 돈이고, 나는 돈도 돈도 많지 않아.'),
(5127, '유혹에 넘어가지 마세요...'),
(5128, '에메랄드 서클은 누구에게나 친절합니다, $R님. 무엇을 도와드릴까요?'),
(5141, '용비늘 가죽세공인이 되기로 결심하고 평생을 바칠 준비가 되셨다면, 저는 당신을 제자로 받아들일 준비가 되어 있습니다. 제가 부탁드린 준비물을 가져오시면, 바로 교육을 시작하겠습니다.'),
(5143, '자연은 당신이 가죽 옷에 그 의지를 불어넣는 법을 배우기 전에 먼저 달래야 할 힘입니다. 이 힘에 바칠 제물을 가져오십시오. 그러면 제가 당신의 목소리가 들리도록 해 드리겠습니다.'),
(5144, '이런 종류의 가죽 갑옷을 만드는 데는 인내와 헌신이 필요합니다. 일단 자연의 힘과 하나가 되면, 그 힘을 거스를 수는 없습니다. 당신의 자격을 증명할 증거를 가져오십시오. 그러면 시작하겠습니다.'),
(5145, '용비늘 가죽세공인이 되기로 결심하고 평생을 바칠 준비가 되셨다면, 저는 당신을 제자로 받아들일 준비가 되어 있습니다. 제가 부탁드린 준비물을 가져오시면, 바로 교육을 시작하겠습니다.'),
(5146, '이런 종류의 가죽 갑옷을 만드는 데는 인내와 헌신이 필요합니다. 일단 자연의 힘과 하나가 되면, 그 힘을 거스를 수는 없습니다. 당신의 자격을 증명할 증거를 가져오십시오. 그러면 시작하겠습니다.'),
(5147, '살인마 아르낙 그림토템에 대한 소식은 없나요?'),
(5148, '자연은 당신이 가죽 옷에 그 의지를 불어넣는 법을 배우기 전에 먼저 달래야 할 힘입니다. 이 힘에 바칠 제물을 가져오십시오. 그러면 제가 당신의 목소리가 들리도록 해 드리겠습니다.'),
(5149, '내 인형 찾았어?'),
(5150, '다당가는 당신이 다가가자 당신을 올려다봅니다. 마치 무언가를 기대하는 듯한 표정입니다... 아마 배가 고픈가 봅니다! 분화구 안에는 커다란 초식동물에게 딱 맞는 간식이 자라고 있을 겁니다. 다당가는 덩치가 큰 아이이니, 뭘 가져다주든 넉넉하게 줘야 할 겁니다!'),
(5151, '내 하이퍼커패시터 가지고 있어?'),
(5153, '당신의 방문은 시기적절한 것 같군요. 혹시 미래에서 오신 건 아니시죠?'),
(5154, '$n님, 책 찾으셨나요?'),
(5155, '싸움은 잘 되어가고 있나, $n? 명예의 증표로 피를 흘리는 게 어떤 이들에게는 혐오스러울 수 있다는 걸 알지만, 두 가지 목적이 있다는 걸 이해해 줘야 해. 적의 수를 줄여줘서 내 임무가 더 쉬워지고, 서로에 대한 존중심이 생겨 앞으로 우리를 더욱 강하게 만들어 줄 테니까. $B$BI, 부디 이해해 주길 바라.'),
(5156, '$n님, 수색이 잘 되길 바랍니다. 저는 아직 그 북쪽으로는 가보지 않았지만, 지옥의 괴물과 마주칠지도 모른다는 생각에 조금 겁이 나네요. 그 괴물들은 뇌가 없긴 하지만, 그래도 꽤 위협적이니까요.'),
(5157, '달의 샘물을 얻으면 정화해서 섀도우 홀 안의 보호 화로를 끄는 데 쓰겠습니다. 그러면 더 깊숙한 방들을 들여다보고 이... 사이비 종교를 실제로 누가 이끌고 있는지 알아낼 충분한 시간이 생길 겁니다. 대지의 어머니께서 우리와 함께 하시기를 기도합니다.'),
(5158, '당신은 그저 라쳇으로 가는 길을 찾는 단순한 여행자가 아닌 것 같군요. 우리 캠프에 와서 편히 쉬세요. 준비가 되면 말씀해 주세요.'),
(5159, '아, 돌아왔군, $n. 잘됐군. 황무지에서 이슬렌을 찾았나? 아니면 목표를 달성하기 위해 다른 방법을 찾아야 할까?'),
(5160, '만나서 반가워요, $n.'),
(5163, '내 친구들이 어떤 반응을 보일지 너무 기대돼! 전혀 예상 못 할 거야!'),
(5165, '더 큰 전투에 대비하려면 화로를 꺼야 합니다. 아무런 정보 없이 용의 소굴로 들어가는 건 어리석은 짓입니다. 그리고 이건 용보다 훨씬 더 끔찍한 일입니다. 그림자 의회는 수많은 범죄와 만행의 배후에 있습니다. 그들을 막으려면 신속하게 움직여야 합니다.'),
(5166, '당신은 현명한 선택을 하셨습니다, $r.'),
(5167, '그런 물건은 만들어진 적이 없습니다!'),
(5168, '유물을 가지고 있나요, $n?'),
(5181, '$n, 해골이랑 칼 찾았어?'),
(5201, '퍼볼그족은 심각한 편집증에 시달리는 것 같다...'),
(5202, '내가 이 감옥에서 탈출할 수 있을지 의문이 들기 시작해. 그들이 숭배하는 악마에게 나를 제물로 바치는 건 시간 문제일 뿐이야. 저 괴물들!'),
(5203, '숨이 차 보이시네요, $n. 괜찮으신가요, 아니면 무슨 일 있으세요?'),
(5204, '시신을 살펴보니, 틀림없이 은빛 손 기사단의 트레이 라이트포지의 유해임이 분명했습니다. 잠시 아르코나린이 떠올랐고, 최근 당신이 섀도우 홀에서 탈출하도록 도운 나이트 엘프 포로에게 이 남자가 얼마나 소중했는지, 당신의 삶에서 그만한 의미를 지닌 사람이 또 있었을까 하는 생각이 들었습니다. 잠시 생각을 정리한 후, 고문자를 먼저 처치하지 않고서는 성기사의 유해를 제시르에게 가져갈 수 없다는 것을 깨달았습니다.'),
(5206, '해골들을 가지고 있나요? 크로미가 자신의 마법에 해골들이 필수적이라고 했어요. 그 마법을 사용하면 다로우셔를 구할 수 있을 거예요.'),
(5210, '서쪽에서 오셨습니까? 로데론의 나머지 지역은 어떻습니까? 안도르할은 함락된 것으로 알고 있지만, 스컬지가 아름다운 티리스팔까지 도달했는지 궁금합니다.'),
(5211, '다로우셔의 불쌍한 수호자들이 꿈속에서 내게 울부짖는다, $n. 당신은 그들을 구해야 한다!'),
(5212, '어떤 사람들은 내가 너무 걱정이 많다고 하는데, 나는 그들에게 ''당신이야말로 걱정을 너무 안 하는 거예요!''라고 말하죠.'),
(5213, '우리는 이 새로운 활성 전염병 병원체가 무엇인지 밝혀낼 직전에 있습니다!'),
(5214, '더 이상 못 참겠어, $n! 도와줘! 나 죽어가고 있어!'),
(5216, '마법 솥의 점검용 덮개는 단단히 잠겨 있습니다. 덮개를 열려면 열쇠를 찾아야 합니다.'),
(5217, '칠윈드 캠프의 비교적 안전한 곳으로 돌아오신 것을 환영합니다, $n님. 가마솥 작업은 어떻게 진행되고 있습니까?'),
(5218, '재앙의 역병 가마솥이 당신 앞에 서서 막대한 양의 독소를 공기 중으로 뿜어내고 있습니다. 가마솥의 거대한 받침대 바닥에는 작고 눈에 띄지 않는 접근 패널이 놓여 있습니다. 이미 가마솥의 군주를 물리치고 열쇠를 획득했으므로, 가마솥에 적절한 시약을 넣어 역병 치료제를 만들 수 있습니다.'),
(5219, '마법 솥의 점검용 덮개는 단단히 잠겨 있습니다. 덮개를 열려면 열쇠를 찾아야 합니다.'),
(5220, '우리는 각 가마솥이 전염병을 유발하는 독소를 생성하기 위해 서로 다른 시약 혼합물을 사용한다는 것을 알고 있습니다. 마찬가지로, 각 가마솥에 맞는 고유한 해독제를 개발해야 한다는 것도 알고 있습니다. 달슨의 눈물에서 채취한 샘플은 해당 가마솥에 필요한 고유한 시약을 알아내는 데 중요한 열쇠가 될 것입니다.'),
(5221, '재앙의 역병 가마솥이 당신 앞에 서서 막대한 양의 독소를 공기 중으로 뿜어내고 있습니다. 가마솥의 거대한 받침대 바닥에는 작고 눈에 띄지 않는 접근 패널이 놓여 있습니다. 이미 가마솥의 군주를 물리치고 열쇠를 획득했으므로, 가마솥에 적절한 시약을 넣어 역병 치료제를 만들 수 있습니다.'),
(5222, '마법 솥의 점검용 덮개는 단단히 잠겨 있습니다. 덮개를 열려면 열쇠를 찾아야 합니다.'),
(5223, '꿈틀거리는 유령의 가마솥에서 채취한 샘플을 성공적으로 분석하면, 재앙에 맞설 파괴적인 해독제를 전달할 수 있는 세 번째 방법을 확보하게 될 것입니다!'),
(5224, '재앙의 역병 가마솥이 당신 앞에 서서 막대한 양의 독소를 공기 중으로 뿜어내고 있습니다. 가마솥의 거대한 받침대 바닥에는 작고 눈에 띄지 않는 접근 패널이 놓여 있습니다. 이미 가마솥의 군주를 물리치고 열쇠를 획득했으므로, 가마솥에 적절한 시약을 넣어 역병 치료제를 만들 수 있습니다.'),
(5225, '마법 솥의 점검용 덮개는 단단히 잠겨 있습니다. 덮개를 열려면 열쇠를 찾아야 합니다.'),
(5226, '가론의 시들어가는 곳에는 우리가 동부에서 접근해야 할 마지막 가마솥이 있습니다. 그곳에서 뿜어져 나오는 역병 샘플을 확보하면, 네 개의 용기를 통해 시약을 환경에 투입할 수 있을 겁니다! 켈투자드의 힘이 뒷받침된다 하더라도, 스컬지는 우리가 이 네 개의 용기 모두에 접근하는 것을 막기 어려울 것입니다.'),
(5227, '재앙의 역병 가마솥이 당신 앞에 서서 막대한 양의 독소를 공기 중으로 뿜어내고 있습니다. 가마솥의 거대한 받침대 바닥에는 작고 눈에 띄지 않는 접근 패널이 놓여 있습니다. 이미 가마솥의 군주를 물리치고 열쇠를 획득했으므로, 가마솥에 적절한 시약을 넣어 역병 치료제를 만들 수 있습니다.'),
(5229, '마법 솥의 점검용 덮개는 단단히 잠겨 있습니다. 덮개를 열려면 열쇠를 찾아야 합니다.'),
(5230, '$n, 비교적 안전한 요새로 돌아오신 것을 환영합니다. 가마솥 작업은 어떻게 진행되고 있습니까?'),
(5231, '마법 솥의 점검용 덮개는 단단히 잠겨 있습니다. 덮개를 열려면 열쇠를 찾아야 합니다.'),
(5232, '우리는 각 가마솥이 전염병을 유발하는 독소를 생성하기 위해 서로 다른 시약 혼합물을 사용한다는 것을 알고 있습니다. 마찬가지로, 각 가마솥에 맞는 고유한 해독제를 개발해야 한다는 것도 알고 있습니다. 달슨의 눈물에서 채취한 샘플은 해당 가마솥에 필요한 고유한 시약을 알아내는 데 중요한 열쇠가 될 것입니다.'),
(5233, '마법 솥의 점검용 덮개는 단단히 잠겨 있습니다. 덮개를 열려면 열쇠를 찾아야 합니다.'),
(5234, '꿈틀거리는 유령의 가마솥에서 채취한 샘플을 성공적으로 분석하면, 재앙에 맞설 파괴적인 해독제를 개발할 수 있는 세 번째 방법을 확보하게 될 것입니다!'),
(5235, '마법 솥의 점검용 덮개는 단단히 잠겨 있습니다. 덮개를 열려면 열쇠를 찾아야 합니다.'),
(5236, '가론의 시들어가는 곳에는 우리가 서쪽에서 접근해야 할 마지막 가마솥이 있습니다. 그 가마솥에서 역병 샘플을 얻으면 네 개의 용기를 통해 시약을 환경에 투입할 수 있게 됩니다! 켈투자드의 힘이 뒷받침된다 하더라도 스컬지는 우리가 네 개의 용기 모두에 접근하는 것을 막기 어려울 것입니다.'),
(5242, '펠단이 없다면, 그림자 의회는 집중력을 잃고 내분에 빠질 것이다. 그들은 통제권을 놓고 서로 다투고 미래 계획을 위해 자산을 비축할 것이다. 그때가 바로 그들과 그들의 악마 노예들을 섬멸할 절호의 기회다.'),
(5243, '조심하세요, 도시가 파괴되는 과정에서 모든 보급품 상자가 살아남은 것은 아닐 겁니다. 재앙의 무리는 감히 물에 손대지 못하겠지만, 성수가 해충의 창궐을 막아줄 리는 없겠죠.'),
(5245, '당신은 왜 여기에 왔습니까?'),
(5246, '내가 당신을 도울 수 있을지 없을지는 오직 성경을 통해서만 알 수 있을 것입니다...'),
(5247, '이 유물은 오직 가장 신뢰할 수 있는 사람의 손에만 맡겨져야 합니다. 다시는 도난당해서는 안 됩니다...'),
(5248, '저주받았어... 영원히...'),
(5251, '명심하세요, $n - 우리는 관용적이어야 하지만 신념에 있어서는 확고해야 합니다!'),
(5252, '$n 님, 떠나신 지 꽤 됐네요. 잘 지내셨나요?'),
(5253, '네, R달러요?'),
(5262, '$n, 거기 뭘 들고 있는 거야?'),
(5263, '남작은 당신이 평생 동안 본 사람보다 더 많은 사람을 죽였습니다.'),
(5282, '연민이야말로 우리를 동물과 구분 짓는 요소입니다. 이 점을 기억하세요...'),
(5283, '아, 대장간에서 얻은 멋진 태닝만큼 좋은 건 없지. 앞치마 자국만 봐도 누가 진짜 멋진 태닝을 했는지 알 수 있어.'),
(5284, '아이로누스는 금화를 가지런히 쌓아 올리고 있다.'),
(5301, '숨이 멎을 때까지 쇠붙이를 두들길 것이다.'),
(5302, '호드의 영광을 위하여!'),
(5305, '그의 앞치마! 어디 있지?'),
(5306, '전설에 따르면 보쉬가진의 뱀돌을 한 번 사용하면 도끼날이 1000년 동안 면도날처럼 날카롭게 유지된다고 합니다!'),
(5307, '$n, 당신에게 맡겨진 임무가 무엇인지 잊으셨습니까?'),
(5321, '케를로니안이 도착했나요?'),
(5341, '$R, 내 앞에서 고개를 숙여라. 나는 귀족이고, 너는 돈 한 푼 없는 농민일 뿐이다.'),
(5342, '내 재산을 지키고 그 이익을 나눠 가져야겠다.'),
(5343, '내 미래를 보장해 준다면, 나는 당신의 미래를 보장해 드리겠습니다.'),
(5344, '당신은 돈을 받고 싶어하는 거죠, 그렇죠?'),
(5361, '무슨 소식이 있나, $c! 아, 내 동생에게서 온 메시지라고? 그럼, 보고서를 줘 봐!'),
(5381, '$n, 데몬 박스 가지고 있어?'),
(5382, '저 도살자를 반드시 막아야 해!'),
(5384, '조심하세요, 키르토노스는 노련한 전사입니다.'),
(5385, 'Jaedenar, $n에서 일은 어떻게 진행됐나요?'),
(5386, '튀긴 블러드벨리 생선을 생각만 해도 발굽이 저릿하고 입에 침이 고이네요... 혹시 가지고 계세요?'),
(5402, '하수인의 역병석은 역병 부대의 휘장입니다. 이 휘장은 역병지대에 배치된 약한 병사들에게서 종종 발견되지만, "약한"이라는 표현은 상황에 따라 다르게 해석될 수 있습니다. 역병은 어디에 있든 절대 과소평가해서는 안 됩니다.$B$B은빛 여명회는 현재 이 휘장 20개를 용맹 토큰으로 교환해 드립니다. 충분한 역병석을 모으셨다면 기꺼이 교환해 드리겠습니다!'),
(5403, '침략자의 역병석은 역병의 정예 부대가 지닌 문장입니다. 역병지대에 배치된 최정예 부대원들이 종종 이 문장을 지니고 있는 것을 볼 수 있습니다. 이러한 문장을 처치하는 것은 쉽지 않은 도전이지만, 악을 물리치겠다는 사명감으로 기꺼이 감수해야 할 일입니다. 은빛 여명회는 현재 이 문장 10개를 가져오시면 용맹 토큰을 드립니다. 이 문장을 제게 가져오시면 정당한 보상을 받으실 수 있도록 해 드리겠습니다.'),
(5404, '타락자의 역병석은 역병의 지배자들의 상징입니다. 역병을 지배하는 강력한 존재는 언제나 이 돌을 소유하고 있죠. 그런 사악한 존재를 처치하는 것은 은빛 새벽의 대의와 모든 선한 대의에 분명히 도움이 될 것입니다! 은빛 새벽을 대표하여, 이 상징물 하나를 가져오시면 용맹 토큰 하나를 드리겠습니다. 획득에 신중을 기하십시오. 이처럼 강력한 존재는 함부로 건드려서는 안 됩니다.'),
(5406, '타락자의 역병석은 역병의 지배자들의 상징입니다. 역병을 지배하는 강력한 존재는 언제나 이 돌을 소유하고 있죠. 그런 사악한 존재를 처치하는 것은 은빛 새벽의 대의와 모든 선한 대의에 분명히 도움이 될 것입니다! 은빛 새벽을 대표하여, 이 상징물 하나를 가져오시면 용맹 토큰 하나를 드리겠습니다. 획득에 신중을 기하십시오. 이처럼 강력한 존재는 함부로 건드려서는 안 됩니다.'),
(5407, '침략자의 역병석은 역병의 정예 부대가 지닌 문장입니다. 역병지대에 배치된 최정예 부대원들이 종종 이 문장을 지니고 있는 것을 볼 수 있습니다. 이러한 문장을 처치하는 것은 쉽지 않은 도전이지만, 악을 물리치겠다는 사명감으로 기꺼이 감수해야 할 일입니다. 은빛 여명회는 현재 이 문장 10개를 가져오시면 용맹 토큰을 드립니다. 이 문장을 제게 가져오시면 정당한 보상을 받으실 수 있도록 해 드리겠습니다.'),
(5408, '하수인의 역병석은 역병 부대의 휘장입니다. 이 휘장은 역병지대에 배치된 약한 병사들에게서 종종 발견되지만, "약한"이라는 표현은 상황에 따라 다르게 해석될 수 있습니다. 역병은 어디에 있든 절대 과소평가해서는 안 됩니다.$B$B은빛 여명회는 현재 이 휘장 20개를 용맹 토큰으로 교환해 드립니다. 충분한 역병석을 모으셨다면 기꺼이 교환해 드리겠습니다!'),
(5421, '내 해산물 좀 가져왔어, 친구?'),
(5441, '아무짝에도 쓸모없는 게으름뱅이들...$B$B엉? 내 가죽곤봉은 가져왔소? 일하다 말고 자는 놈들은 전부 잡았겠지?'),
(5461, '추억을 간직할 기념품은 찾기 힘든 귀한 물건입니다.'),
(5462, '답을 원하지 않는 질문은 하지 마세요.'),
(5463, '메네틸의 선물 주변 지역은 유난히 춥습니다.'),
(5464, '<레오니드는 몸서리쳤다.>'),
(5465, '당신은 불가능한 일을 해냈습니까?'),
(5466, '당신은 만 명의 불안한 영혼들의 짐을 짊어지고 있습니다, $n.'),
(5481, '그 쓸모없는 괴물은 어디 있지? 네가 내가 필요한 걸 가지고 있든가, 아니면 어서 나가서 찾아와.'),
(5482, '이거 정말 좋아야 할 텐데. 내가 필요한 파멸의 대마초를 전부 가지고 있겠지?'),
(5501, '뼈는 가지고 있소? 행렬이 곧 도착할 거야. 최고 기록을 달성하려면 코도 뼈 10개만 더 필요해. 최고 기록이라고!'),
(5502, '$n님, 다시 뵙게 되어 반갑습니다. 어린이 주간 동안 자원 봉사하셨던 일들은 모두 처리하셨나요?'),
(5504, '아, 고귀하신 $c님! 요청드린 용맹의 증표를 가져오셨습니까? 증표를 제게 주시면, 저희가 보유한 다양한 망토를 구매하실 수 있도록 해 드리겠습니다.'),
(5505, '자, 여기 $n 님, 완성된 만능 열쇠가 있습니다. 이 열쇠로 스콜로맨스에 들어갈 수 있을 거라고 확신합니다. 하지만 확실히 확인하는 방법은 하나뿐이죠. 어서 시험해 보세요.'),
(5507, '아, 고귀하신 $c님! 요청드린 용맹의 증표를 가져오셨습니까? 증표를 제게 주시면, 저희가 보유한 다양한 망토를 구매하실 수 있도록 해 드리겠습니다.'),
(5508, '타락자의 재앙석은 재앙의 지배자들의 상징입니다. 재앙을 지배하는 강력한 존재는 언제나 이 재앙석을 소유하고 있죠. 그런 사악한 존재를 처치하는 것은 은빛 새벽의 대의와 모든 선한 대의에 분명히 도움이 될 것입니다! 은빛 새벽을 대표하여, 이 재앙석 하나를 가져오시면 용맹 토큰 하나를 드리겠습니다. 획득하실 때는 신중을 기하십시오. 이처럼 강력한 존재는 함부로 건드려서는 안 됩니다.'),
(5509, '침략자의 역병석은 역병의 정예 부대가 지닌 문장입니다. 역병지대에 배치된 최정예 부대원들이 종종 이 문장을 지니고 있는 것을 볼 수 있습니다. 이러한 문장을 처치하는 것은 쉽지 않은 도전이지만, 악을 물리치겠다는 사명감으로 기꺼이 감수해야 할 일입니다. 은빛 여명회는 현재 이 문장 10개를 가져오시면 용맹 토큰을 드립니다. 이 문장을 제게 가져오시면 정당한 보상을 받으실 수 있도록 해 드리겠습니다.'),
(5510, '하수인의 역병석은 역병 부대의 휘장입니다. 이 휘장은 역병지대에 배치된 약한 병사들에게서 종종 발견되지만, "약한"이라는 표현은 상황에 따라 다르게 해석될 수 있습니다. 역병은 어디에 있든 절대 과소평가해서는 안 됩니다.$B$B은빛 여명회는 현재 이 휘장 20개를 용맹 토큰으로 교환해 드립니다. 충분한 역병석을 모으셨다면 기꺼이 교환해 드리겠습니다!'),
(5511, '자, 여기 $n 님, 완성된 만능 열쇠가 있습니다. 이 열쇠로 스콜로맨스에 들어갈 수 있을 거라고 확신합니다. 하지만 확실히 확인하는 방법은 하나뿐이죠. 어서 시험해 보세요.'),
(5513, '아, 고귀하신 $c님! 요청드린 용맹의 증표를 가져오셨습니까? 증표를 제게 주시면, 저희가 보유한 다양한 망토를 구매하실 수 있도록 해 드리겠습니다.'),
(5514, '그래, 당신이 누군지, 왜 여기 왔는지 알아요. 디더스가 당신이 도착하기 전에 전령을 보냈더군요. 자, 이제 본론으로 들어가죠. 제가 해골 열쇠를 만들 수 있는 주형을 가지고 있는데, 가격은 금화 15개 선불입니다. 흥정은 없어요. 제가 해골 조각들을 주형에 채워 넣어 드리고, 대장장이 기술 없이도 열쇠 자루를 만드는 법을 가르쳐 드릴게요. 그것도 무료로요. 누가 용병들이 경쟁력 있는 제안을 안 한다고 했죠!'),
(5515, '<에바의 모습이 초점이 맞았다 안 맞았다를 반복한다.>'),
(5517, '존경하는 $C 님! 제가 부탁드린 용맹의 토큰을 가져오셨습니까? 토큰을 건네주시면 새벽의 색채 망토를 수여해 드리겠습니다.'),
(5518, '오우거 탄닌이 아마 제가 그 옷을 만드는 데 필요한 재료 중 가장 구하기 힘든 것 같아요. 위층에 있을지도 모르겠네요? 이 쇠사슬 때문에 움직이기가 쉽지 않아서 정확히 알기는 어렵지만요... 어쨌든 필요한 재료들을 가져다주시면, 크롬크러쉬 선장님이 당신을 자기 부하로 착각할 만큼 멋진 오우거 옷을 뚝딱 만들어 드리겠습니다.'),
(5519, '새 옷이 필요하세요? 음, 난 당분간 어디 가지 않을 것 같으니, 전에 부탁드렸던 것들만 가져오시면 오거 옷을 하나 더 만들어 드리겠습니다.'),
(5521, '존경하는 $C 님! 제가 부탁드린 용맹의 토큰을 가져오셨습니까? 토큰을 건네주시면 새벽의 색채 망토를 수여해 드리겠습니다.'),
(5522, '블랙록 첨탑에서 말썽을 피우던 녀석이 너지? 내가 부탁한 물건을 가지고 있느냐?'),
(5524, '존경하는 $C 님! 제가 부탁드린 용맹의 토큰을 가져오셨습니까? 토큰을 건네주시면 새벽의 색채 망토를 수여해 드리겠습니다.'),
(5525, '이건 고르독 족쇄 열쇠라고 불려. 뭐, 이 "재밌는 녀석들"이 계속 그렇게 부르거든. 오우거들 중 누구든 가지고 있을 것 같긴 한데, 특정 오우거가 가지고 있는지는 확실하지 않아. 경비병들이 가지고 있을 확률이 더 높을지도 몰라...$B$B내가 무슨 소리를 하는 거지? 너 이미 가지고 있잖아?! 저기 있는 거 아니야?!'),
(5526, '봉인된 순수의 성물을 손에 넣었으니, 세상을 타락시키는 위협을 제거할 뿐만 아니라, 우리의 신중한 관찰 하에 그것을 연구할 수도 있을 것이다. 어쩌면 아제로스를 끊임없이 위협하는 타락의 오염에 맞서 싸울 새로운 방법을 고안해낼 수도 있을 것이다. 밀리도 분명 이런 결과를 원했을 것이다...'),
(5527, '순수의 성물함은 그 자체로 하나의 유물입니다. 제작된 수량이 극히 적었고, 거의 모두 세월이 흐르면서 사라진 것으로 여겨졌습니다. 솔직히 말씀드리자면, 저는 남풍에 있는 순수의 성물함에 대해 꽤 오래전부터 알고 있었습니다. 실리투스의 혼란이 가중되는 상황에서, 우리의 비밀은 그저 비밀로 남겨두는 것이 좋겠다고 생각했습니다. 괜히 건드리면 적들의 의심만 살 뿐이니까요. 하지만 엘드레탈라스의 상황을 고려하면, 더 이상 방심할 수 없습니다.'),
(5529, '스콜로맨스로 가세요, $n. 그 병든 새끼들이 자라기 전에 처치하세요!'),
(5531, '안녕하세요, $n님! 용의 알을 가지고 오셨다고 들었어요? 그럼, 알을 좀 보여주세요!'),
(5534, '자, $n? 룬은 어디 있지? 자네는 성실한 직원이지, 그렇지? 도와주려고 온 거잖아? 우리가 합의한 대로 돈을 줄 테니 두 번 생각할 필요 없어. 뭐라고? 아, 우리가 아무것도 합의하지 않았다고? 오, 좋아... 그럼 천천히 해. 하지만 오래 걸릴수록 훨씬 적게 줄 거라는 걸 알아둬.'),
(5535, '$c, 하이본 정령을 찾는 여정은 어떻게 되어가고 있나? 수많은 사건들이 아제로스의 모든 종족에게 큰 고통을 안겨주었지만, 유독 이 정령들은 모든 인류에게 재앙과도 같은 존재인 것 같군. 아마도 그들이 끊임없이 마법에 대한 욕망을 품고 있기 때문일지도 모르지. 그러한 욕망은 불타는 군단의 도래를 예고하는 징조이며, 우리는 그 결과가 어떠할지 잘 알고 있잖아.'),
(5536, '사티로스와의 전투는 어떻게 되어가고 있나, $c?$B$BA 생각했던 것만큼 강한가? 아니면 더 강한가? 아니면 네 힘에 비하면 아무것도 아니었나?'),
(5537, '좀 섬뜩하게 들릴지 모르지만, 열쇠의 외피를 만들려면 적당한 크기의 해골 조각들이 꽤 많이 필요할 거예요. 해골 열쇠라는 말이 괜히 붙은 게 아니잖아요.'),
(5538, '그래, 당신이 누군지, 왜 여기 왔는지 알아요. 아빙턴이 당신이 도착하기 전에 전령을 보냈더군요. 자, 이제 본론으로 들어가죠. 해골 열쇠를 만들 수 있는 주형이 있는데, 가격은 금화 15개 선불입니다. 흥정은 없어요. 해골 조각들을 주형에 채워 넣어 드리고, 대장장이 기술 전혀 없어도 열쇠 자루를 만드는 법도 가르쳐 드리겠습니다. 그것도 무료로요. 용병이라고 해서 경쟁력 있는 가격을 제시하지 않는다고 누가 그랬나요!'),
(5541, '혹시 탄약 때문에 오신 건 아니겠죠? 탄약이 거의 다 떨어졌거든요!'),
(5542, '악마 같은 개들을 불쌍히 여기지 마세요, $r. 그들은 혐오스러운 존재입니다!'),
(5543, '날개 달린 해충들을 얕보지 마십시오. 역병이 그들에게 초자연적인 능력을 부여했습니다.'),
(5544, '당신은 그 맛에 익숙해질 거예요, $R.'),
(5545, '마감일이 얼마 남지 않았으니, 서둘러 나무 묶음을 모아 오세요, $c.'),
(5561, '곧 캐러밴이 도착할 겁니다. 제가 부탁드렸던 새로 길들인 코도스는 가지고 계신가요?'),
(5581, '마노록 코븐에서 악마의 차원문을 없애버렸나요?'),
(5582, '$n, 나에게 보여줄 게 있나요?'),
(5621, '델로르, 우리의 강화 마법은 매우 강력합니다. 동료들이 모든 종류의 공격으로부터 추가적인 피해를 견딜 수 있게 해주고, 평소라면 쓰러졌을 상황에서도 살아남을 수 있게 해 줍니다. 하지만 이는 우리의 치유 능력에 비하면 아무것도 아닙니다. 사제보다 더 뛰어난 치유사는 없다는 것을 명심하십시오. 당신의 힘만으로도 전세를 쉽게 바꿀 수 있습니다.'),
(5624, '이미 알고 계시겠지만, 우리의 치유 마법은 이 험난한 시대에 우리 민족의 생존에 필수적입니다. 특히 무기와 마법을 들고 다양한 위협에 맞서 싸우는 모험가와 영웅들에게는 더욱 그렇습니다. 이 능력이 얼마나 중요한지 항상 기억하는 것이 좋습니다. 치유 마법은 강인함과 결합되어 동료들이 더 많은 공격을 견뎌낼 수 있도록 해주므로 전투에서 훨씬 더 강력한 힘을 발휘할 수 있게 해줍니다. 누구도 당신의 마법이 얼마나 강력한지 얕보도록 내버려 두지 마십시오.'),
(5625, '$n, 돌프를 찾았나요?$B$B이미 알고 있겠지만, 우리의 치유 능력은 매우 유용해요. 부상자를 치료할 수 있을 뿐만 아니라, 이름을 떨치려는 수많은 예비 영웅들의 생존에도 필수적인 존재죠. 내구력을 높여주는 인내력과 생명을 지켜주는 치유 마법 덕분에 우리가 극복하지 못할 것은 없어요!'),
(5648, '치유 마법이 강력하다는 건 누구나 아는 사실이지만, 그 위력을 제대로 이해하는 사람은 많지 않습니다. 죽어가는 사람들을 살릴 수도 있죠. 치유 마법에 강인함의 힘이 더해지면 그야말로 막강한 시너지 효과를 냅니다. 이 점을 명심하세요. 전사, 마법사, 그 외 모든 이들에게 유용한 마법입니다.'),
(5650, '우리의 능력은 수많은 상황에 적합하게 만들어주죠, $n. 하지만 무엇보다도, 상처를 치료하고 동료들의 내구력을 증가시키는 능력이 가장 중요한 재능으로 꼽힐 겁니다. 그렇다고 해서 $C로서 다른 길을 택하는 걸 포기하지 마세요. 당신은 다양한 방식으로 활약할 수 있으니까요. 하지만… 진정으로 마법 에너지로 적을 섬멸하고 싶다면, 어쩌면 아케인이 더 잘 맞을지도 모르겠네요.'),
(5713, '혹시 경비병 아이나샤를 길에서 보셨나요? 중요한 임무를 수행하러 나갔는데 아직 돌아오지 않았어요.'),
(5721, '밖에서 귀신 소리가 들리는 것 같아요. 귀신들이 제게 무서운 말을 속삭여요...'),
(5723, '심연을 찾는 건 어떻게 되어가고 있나? 그리고 트로그들은?$B$B이 위협이 계속되는 걸 용납할 수 없어. 계속된다면 우리 오크 동족에게만 해를 끼칠 뿐이야.'),
(5724, '$n, 뭔가 찾으셨나요? 그녀의 일족 중 한 명이 왜 무고하게 죽어야 했는지에 대한 단서라도 있으면 도움이 될 것 같습니다.'),
(5725, '처리해야 할 일이 백 가지도 넘는데, $C. 책은 가지고 있나?'),
(5726, '$n, 휘장을 얻었나? 그 휘장은 내가 생각하기에 호드에게 가장 큰 위협이 되는 곳에 침투하고, 마침내 우리의 새로운 고향에 평화를 가져오는 데 매우 중요한 도구가 될 것이다. 탐욕과 권력에 눈이 먼 인간과 오크들이 얼마나 복잡한 음모를 꾸밀 수 있는지 알게 될 것이다. 숨겨진 의도, 부패, 모든 것이 드러날 것이다. 자네는 자신이 존재조차 몰랐던 전쟁의 한복판에 놓이게 될 것이다.'),
(5727, '자, $c? 그가 우리의 계략을 믿는 건가, 아니면 내가 처음 예상했던 것보다 상황이 더 심각한 건가?$b$b네루에게 우리의 가치를 증명하면 그림자 의회 침투가 훨씬 쉬워질 거야. 그는 우리가 듀로타르에 쌓아온 모든 것을 파괴하려는 자들을 소탕하는 데 사용할 수 있는 많은 정보를 가지고 있을 테니까.'),
(5728, '$n, 그들을 찾았나? 작열하는 칼날의 지도자들을 말이야. 그림자 의회가 오그리마와 호드 전체를 내게서 빼앗으려 한다는 건 알고 있었지만, 이렇게 빨리 도시에 침투할 줄은 몰랐군. 이 괴물은 팔이 너무 많아… 지칠 때까지 잘라낼 수는 있겠지만, 시작했을 때보다 나아질 건 없을 거야. 첩자들에게 두 배로 노력하라고 해야겠어.'),
(5741, '빛의 홀을 가지고 있습니까?'),
(5742, '친구여, 부디 앉아서 내 이야기를 들어주십시오.'),
(5761, '그 괴물을 처치했습니까? 그는 분명 분노의 협곡에 있는 작열하는 칼날 무리의 우두머리일 겁니다.'),
(5762, '옷깃에 묻은 게 사막 먼지인가요? 음... 제 코가 제대로 맡아본다면 사막 먼지가 아니라 사막 소금인 것 같은데요! 쉬머링 플랫츠에 가보셨나요?'),
(5763, '앉아, $c. 곧 정글로 다시 돌아갈 수 있을 거야.'),
(5781, '그는 구원받아야 한다.'),
(5801, '해골 열쇠의 손잡이 부분은 완성되었습니까? 주형 구입 비용을 대부분 부담하셔야 해서 유감이지만, 우리 모두 재앙에 맞서 싸우기 위해 각자의 역할을 다해야 합니다. 미완성 열쇠를 제게 넘겨주시면, 이제 제작에 필요한 마지막 부품을 만들 준비가 된 겁니다. 결코 쉽지는 않겠지만, 안도르할 공격을 위해 지금까지 기울여온 노력이 이제 결실을 맺게 될 겁니다. 두고 보세요.'),
(5802, '해골 열쇠의 손잡이 부분은 완성되었습니까? 주형 구입 비용을 대부분 부담하셔야 해서 정말 죄송하지만, 우리 모두 재앙에 맞서 싸우기 위해 각자의 역할을 다해야 합니다. 미완성 열쇠를 제게 넘겨주시면, 이제 제작에 필요한 마지막 부품을 만들 준비가 된 겁니다. 결코 쉽지는 않겠지만, 안도르할 공격을 위해 지금까지 기울여온 노력이 이제 결실을 맺게 될 겁니다. 두고 보세요.'),
(5803, '자네는 여기까지 왔으니, 소환사 아라즈의 육체를 파괴해야만 열쇠를 완성할 수 있다. 무슨 수를 써서라도 아라즈의 풍뎅이를 구해 내게 가져오게. 내가 그것을 열쇠의 머리 부분으로 융합시키겠다.'),
(5804, '자네는 여기까지 왔으니, 소환사 아라즈의 육체를 파괴해야만 열쇠를 완성할 수 있다. 무슨 수를 써서라도 아라즈의 풍뎅이를 구해 내게 가져오게. 내가 그것을 열쇠의 머리 부분으로 융합해 주겠다.'),
(5805, '안녕하세요! 만나서 반갑습니다! 특별한 상품권을 가지고 계신 것 같은데, 저에게 주시면 보답으로 무언가를 드리겠습니다.'),
(5821, '왜 나는 자꾸 그 망할 캠핑카를 기다리고 있는 걸까?<스미드는 무언가를 깨달은 듯 보인다.>아, 맞다. 그들이 생활비를 내주잖아. 봤어?'),
(5841, '안녕하세요! 만나서 반갑습니다! 특별한 상품권을 가지고 계신 것 같네요. 상품권을 주시면 제가 보답으로 무언가를 드리겠습니다.'),
(5842, '안녕하세요! 만나서 반갑습니다! $B$BI 특별한 상품권을 가지고 계신 것 같은데, 저에게 주시면 보답으로 무언가를 드리겠습니다.'),
(5843, '안녕하세요! 만나서 반갑습니다! 특별한 상품권을 가지고 계신 것 같네요. 상품권을 주시면 제가 보답으로 무언가를 드리겠습니다.'),
(5844, '안녕하세요! 만나서 반갑습니다! $B$BI 특별한 상품권을 가지고 계신 것 같은데, 저에게 주시면 보답으로 무언가를 드리겠습니다.'),
(5845, '내 믿음이 너를 인도할 것이다, $n. 빛은 한계가 없다.'),
(5847, '안녕하세요! 만나서 반갑습니다! $B$BI 특별한 상품권을 가지고 계신 것 같은데, 저에게 주시면 보답으로 무언가를 드리겠습니다.'),
(5848, '그 그림, 가격은 $n입니다. 그 그림을 가지고 계신가요?'),
(5861, '나는 이런 날이 올 줄 알았다.'),
(5862, '당신들은 티르의 손에서 온 지원군입니까?'),
(5863, '너무 걱정돼요! 조심하세요!'),
(5881, '마그란 어스바인더 소식 있나요?'),
(5882, '세나리온 비컨을 소유하면 대의를 위해 처치된 타락한 짐승들에게서 타락한 영혼 조각을 볼 수 있습니다. 저는 그 조각들을 갈아서 세나리온 식물 연고를 만드는 데 필요한 재료로 사용합니다. 그 연고를 사용하면 타락한 식물을 다시 건강한 식물로 되돌릴 수 있습니다. 이 조각들을 대가로 제가 미리 만들어 둔 세나리온 식물 연고 몇 개를 드리겠습니다.'),
(5883, '펠우드에서 광물을 캐는 동안 세나리온 신호기를 가지고 있다면, 원광석 광맥을 오염시키는 오염된 황산을 볼 수 있을 겁니다. 저는 그 황산을 정화해서 세나리온 식물 연고를 만드는 방법을 알고 있습니다. 그 연고는 야생에서 발견되는, 살릴 필요가 있는 식물에 사용하면 됩니다. 오염된 황산을 모아두셨다면, 제가 미리 만들어둔 세나리온 식물 연고를 드리겠습니다.'),
(5884, '세나리온 신호기를 사용하면 숙련된 약초학자는 펠우드의 타락이 낳은 사악한 펠 크리프를 발견할 수 있습니다. 저는 이곳에서의 경험을 통해 펠 크리프를 정화하여 세나리온 식물 연고라고 부르는 약으로 만드는 방법을 터득했습니다. 펠우드에서 약초를 채집할 때 신호기를 가지고 있다면 펠 크리프를 발견할 수 있을 겁니다. 저에게 가져다주시면 미리 만들어둔 세나리온 식물 연고를 드리겠습니다.'),
(5885, '세나리온 신호기를 사용하면 숙련된 가죽 벗기기 전문가가 펠우드에서 사냥한 전리품에서 오염된 가죽 조각을 찾아낼 수 있습니다. 저는 이 쓸모없어 보이는 조각들을 걸쭉한 반죽으로 만들어 세나리온 식물 연고의 경화제로 사용합니다. 펠우드에서 사냥감을 가죽 벗길 때는 꼭 신호기를 휴대하세요! 오염된 가죽 조각을 모으면 저에게 가져오세요. 제가 미리 만들어둔 세나리온 식물 연고를 드리겠습니다.'),
(5886, '마법이 해제된 마법 아이템의 힘은 그것이 만들어내는 정수에서 느껴집니다. 저는 마법사들이 사용하는 원시 정수를 세나리온 식물 연고를 만드는 데 적합한 재료로 바꾸는 방법을 고안했습니다. 세나리온 비컨은 필요 없습니다. 하급 네더 정수를 생성하는 적절하게 마법이 해제된 아이템이면 무엇이든 사용할 수 있습니다. 저는 하급 네더 정수 하나만 있으면 됩니다. 그 대가로 세나리온 식물 연고를 드리겠습니다. 이 정수는 매우 강력해서 소량만으로도 효과가 뛰어납니다!'),
(5887, '세나리온 신호기를 소유하면 대의를 위해 처치된 타락한 짐승들에게서 타락한 영혼 조각을 볼 수 있습니다. 저는 그 조각들을 갈아서 세나리온 식물 연고를 만드는 데 필요한 재료로 사용합니다. 그 연고를 사용하면 타락한 식물을 다시 건강한 식물로 되돌릴 수 있습니다. 이 조각들을 대가로 제가 미리 만들어 둔 세나리온 식물 연고 몇 개를 드리겠습니다.'),
(5888, '펠우드에서 광물을 캐는 동안 세나리온 신호기를 가지고 있다면, 원광석 광맥을 오염시키는 오염된 황산을 볼 수 있을 겁니다. 저는 그 황산을 정화해서 세나리온 식물 연고를 만드는 방법을 알고 있습니다. 그 연고는 야생에서 발견되는, 살릴 필요가 있는 식물에 사용하면 됩니다. 오염된 황산을 모아두셨다면, 제가 미리 만들어둔 세나리온 식물 연고를 드리겠습니다.'),
(5889, '세나리온 신호기를 사용하면 숙련된 약초학자는 펠우드의 타락이 낳은 사악한 펠 크리프를 발견할 수 있습니다. 저는 이곳에서의 경험을 통해 펠 크리프를 정화하여 세나리온 식물 연고라고 부르는 약으로 만드는 방법을 터득했습니다. 펠우드에서 약초를 채집할 때 신호기를 가지고 있다면 펠 크리프를 발견할 수 있을 겁니다. 저에게 가져다주시면 미리 만들어둔 세나리온 식물 연고를 드리겠습니다.'),
(5890, '세나리온 신호기를 사용하면 숙련된 가죽 벗기기 전문가가 펠우드에서 사냥한 전리품에서 오염된 가죽 조각을 찾아낼 수 있습니다. 저는 이 쓸모없어 보이는 조각들을 걸쭉한 반죽으로 만들어 세나리온 식물 연고의 경화제로 사용합니다. 펠우드에서 사냥감을 가죽 벗길 때는 꼭 신호기를 휴대하세요! 오염된 가죽 조각을 모으면 저에게 가져오세요. 제가 미리 만들어둔 세나리온 식물 연고를 드리겠습니다.'),
(5891, '마법이 해제된 마법 아이템의 힘은 그것이 만들어내는 정수에서 느껴집니다. 저는 마법사들이 사용하는 원초적인 정수를 세나리온 식물 연고를 만드는 데 적합한 시약으로 바꾸는 방법을 고안했습니다. 세나리온 비컨은 필요 없습니다. 하급 네더 정수를 생성하는 적절하게 마법이 해제된 아이템이라면 무엇이든 사용할 수 있습니다. 저는 하급 네더 정수 하나만 있으면 됩니다. 그 대가로 세나리온 식물 연고를 드리겠습니다. 이 정수는 매우 강력해서 소량만으로도 효과가 뛰어납니다!'),
(5892, '필요한 물품은 다 준비됐나요, $n? 아무리 많아도 부족하거든요!'),
(5893, '$n, 콜드투스 광산에 가본 적 있나? 내가 부탁한 물품은 가지고 있나?'),
(5901, '$n, 흰개미가 벌써 생겼나요? 당신처럼 똑똑한 $c라면 당연히 알겠죠. 흰개미가 충분히 많아지면, 다시는 아무도 제재소를 이용하지 못하게 만들 겁니다!'),
(5903, '$n, 흰개미집 찾았어? 플래그우드 곳곳에 흰개미가 있다고 들었어.'),
(5941, '당신 친구 칼린과 연락이 닿았습니다. 그는 마을의 몰락에 큰 슬픔을 느끼지만, 당신을 매우 존경하며 당신이 모든 것을 바로잡을 수 있을 거라고 믿고 있습니다. 아, 그런데 이야기가 딴 데로 새버렸네요... 제가 부탁드린 유물은 가지고 계신가요?'),
(5942, '이 상자는 오래되었고 먼지로 뒤덮여 있다.'),
(5943, '있잖아, 만약 저 캐러밴이 사라진다면 난 완전히 망할 거야! 설마 캐러밴에 대한 안 좋은 소식을 전하러 온 건 아니지?<스미드는 이마의 땀을 닦는다.>탐욕의 여신이시여, 감사합니다!'),
(5944, '<티리온은 평정심을 되찾았다.>'),
(5981, '당신은 계속해서 자신의 능력을 증명해야 합니다, $n.'),
(6004, '잘 지내? $n, 그들이 네 생각보다 강한가? 그러지 않았으면 좋겠어. 내가 이 일을 끝까지 해내려면, 지금까지 네게 요구했던 것보다 훨씬 더 많은 힘이 필요할 테니까.'),
(6021, '은신처를 찾았나, $n? 젤다르는 처리했나?'),
(6022, '울고 있는 건가? ''영웅''이여, 이게 너무 ''지루하다''면 어둠의 여왕에게 돌아가 내 농장에서 당한 끔찍한 학대에 대해 보고하는 게 좋을 것이다. 자, 이제 내 눈앞에서 사라져라!'),
(6023, '$n, 그들을 찾았나요? 그 둘을 처리하고 나면, 저는 하스글렌에 들어가 그들의 상황을 자세히 살펴볼 수 있을 겁니다. 당신의 도움이 없으면 불가능해요. 부디, 래들리와 더겐을 찾아주세요.'),
(6024, '여기에 묻힌 이 상자는 단단히 잠겨 있습니다.'),
(6025, '위험한 임무군요, $n. 당신의 용기가 부럽습니다.'),
(6026, '스모키 아저씨를 믿어봐, $R. 보상은 그만한 가치가 있을 거야. 아르젠트 던 사람들은 보상에 있어서 절대 봐주지 않거든.'),
(6027, '아, $n! 다시 만나서 반갑네. 혹시 고대인의 책을 가지고 있니?'),
(6028, '안녕하세요, $c님. 아르젠트 던을 대표하여 칠윈드 캠프에서 안전과 숙소를 제공해 드리겠습니다. 또한, 몇 가지 일거리도 드릴 수 있습니다...'),
(6029, '안녕하세요, $c님. 아르젠트 던을 대표하여 불워크에서 안전과 보호를 제공해 드리겠습니다. 또한, 싸울 가치가 있는 대의를 위해 싸울 기회도 드릴 수 있습니다!'),
(6030, '힘든 시기에 빛이 당신을 인도하길 바랍니다, $C님. 어둠과 절망 속에서 희망의 등불이 된 이곳에 당신을 이끈 이유는 무엇인가요?'),
(6031, '룬천을 가지고 계신가요? 우리 백성들이 룬천을 간절히 원하고 있습니다!'),
(6032, '$n, 달빛 가리개 가져왔어?'),
(6041, '특수 연초를 몇 개 더 만들 재료가 남았어. 더 필요하면 스모키 아저씨한테 말해.'),
(6042, '더 나쁠 수도 있었지. 네가 박쥐 똥이나 모으게 될 뻔했잖아.<나타노스는 생각에 잠긴 듯 당신을 바라봅니다.>흠... 잠깐만! 어디 가는 거야?'),
(6061, '실력을 갈고닦아라, $n. 성체 평원쥐를 길들여라.'),
(6062, '행운을 빌어요, 젊은 C씨.'),
(6063, '당신은 배우게 될 거예요, $n, 그리고 언젠가는 훌륭한 $C가 될 겁니다.'),
(6064, '걱정 마, 아가씨! 하나만 고르기 전에 몇 가지를 맛볼 수 있을 거야.'),
(6082, '전갈을 길들일 수 있었나요?'),
(6083, '애완동물을 효과적으로 조종하려면 연습이 필요합니다. 서핑 크롤러를 길들여 보셨나요?'),
(6084, '$n님, 눈표범에 대해 어떻게 생각하세요?'),
(6085, '얼음 발톱 곰을 길들였나요?'),
(6087, '초원 사냥꾼을 찾으셨나요?'),
(6088, '곧 준비되실 겁니다, $n.'),
(6101, '자연과 자신 사이의 균형을 이해하는 것은 모든 $R에게 삶의 방식입니다.'),
(6102, '$n, 당신의 성과가 자랑스럽습니다. 제가 마지막으로 맡긴 과제는 완료했나요?'),
(6122, '당신이 바로 문글레이드의 세나리온 서클에서 보낸 분이시군요? 정말 반갑습니다! 저희가 불쌍한 사슴들 때문에 꽤 곤란한 상황에 처해 있는데, 도움을 주시면 정말 감사하겠습니다. 덴드라이트 스타블레이즈가 알려주겠다고 했던 물 샘플을 가지고 계신가요? 그분이 치료법을 함께 연구하기 위해 당신이 샘플을 채취해 줄 거라고 알려주셨는데요…'),
(6123, '연고를 만드는 데 필요한 시약은 가지고 있나요? 사슴들이 스스로 나아지지 않으니 서둘러 도와줘야겠어요!'),
(6124, '오베르딘의 알란다리아 나이트송이 당신에게 요구한 것을 완료했습니까? 완료하지 않으면 당신의 임무는 끝나지 않은 것입니다.'),
(6127, '당신이 바로 문글레이드의 세나리온 서클에서 보낸 분이시죠? 정말 다행입니다! 북부 황무지를 떠도는 병든 가젤들의 균형을 되찾는 데 어려움을 겪고 있었는데, 도움을 받을 수 있다면 더할 나위 없이 기쁠 겁니다. 혹시 덴드라이트 스타블레이즈가 가지고 있다고 했던 물 샘플을 가지고 계신가요? 그가 당신이 샘플을 채취해서 함께 치료법을 연구할 수 있을 거라고 알려줬거든요…'),
(6128, '연고를 만드는 데 필요한 시약은 가지고 있나요? 가젤들은 저절로 나아지지 않을 테니, 우리가 서둘러서라도 가젤들을 구해야 해요!'),
(6129, '당신은 통가 룬토템이 교차로에서 당신에게 요구한 것을 완료했습니까? 완료하지 않으면 당신의 임무는 끝나지 않은 것입니다.'),
(6132, '제 여동생 멜리자 보셨어요? 걔는 항상 바쁘게 움직여서 늘 사고를 쳐요.'),
(6133, '날 기다리게 하지 마, $c.'),
(6134, '내 고스트오플라즈마는 어디 있지, $n?'),
(6135, '$c님, 이 도전을 혼자서 감당하시는 것은 권장하지 않습니다.'),
(6136, '내가 최근에 너를 싫어한다고 말했던가?'),
(6142, '싱싱한 바지락을 가지고 낚시하러 가는 게 너무 기대돼요. 제가 필요한 바지락 10개 가져오셨나요?'),
(6143, '나가들이 우리에게 혼란을 불러일으켰을 때, 그들이 살려달라고 울부짖던 목소리가 아직도 귓가에 맴도는 것 같아. 무릎만 괜찮았더라면, 가서 그 망할 나가들을 처치하는 걸 도와줬을 텐데!$B$B그들은 보통 수면 아래 산호초 깊숙한 곳에 숨어서… 음모를 꾸미고 있을 거야…'),
(6145, '지금 성공하면 당신은 거의 내 존경을 얻게 될 겁니다, $c.'),
(6146, '이건 용납할 수 없어, 병사!'),
(6148, '$n님, 현재 상황이 어떻습니까?'),
(6161, '이 상자는 단단히 잠겨 있습니다.');

INSERT INTO `_koKR_stage_quest_request_items_locale` (`ID`, `CompletionText`) VALUES
(6162, '$n, 그 짐승의 발톱은 손에 넣었나? 그 짐승은 자신의 죄값을 치르게 될 것이다. 그 짐승이 부패했든, 아니면 이런 음침한 숲에서 사는 것에 화가 났든 상관없다. 내 가족에게 그런 죄를 저지른 퍼볼그는 오래 살지 못할 것이다!'),
(6163, '실바나스가 저를 풀어준 후, 저는 몇 달 동안 이 황무지 곳곳에서 그 괴물을 추적했습니다. 괴물은 스트라솔름의 안전한 곳으로 도망쳤습니다. 그 괴물은...'),
(6164, '제 영수증 책자 가지고 계신가요? 어서 업무에 복귀하고 싶어요!'),
(6181, '급하신 것 같네요. 그렇다면 잘 찾아오셨습니다!'),
(6185, '혹시... 뭐 찾으셨어요??'),
(6187, '<볼바르 포드라곤 대영주는 깊은 생각에 잠겨 있다.>'),
(6261, '이마에 땀이 맺혔구나, 얘야? 너무 많이 뛰었나 보구나. 다음엔 그리핀을 타고 가렴!'),
(6281, '여행 다니셨군요? 재밌는 곳 어디 가셨어요?'),
(6282, '그을린 계곡을 두려워하지 마라. 그 언덕에는 수많은 사악한 존재들이 살고 있다. 강인함을 유지하라, $n. 그러면 우리 백성을 위협하는 이 악을 물리칠 수 있을 것이다. 지금 가서 강력하게 공격하라. 우리 아이들은 과거의 악을 결코 알지 못할 것이다.'),
(6283, '블러드퓨리 리퍼는 끔찍한 괴물입니다! 불에 탄 계곡의 서쪽 언덕 지대에서 그녀를 찾을 수 있을 겁니다. 블러드퓨리들은 우리 없이는 무력할 겁니다... 분명 우리는 그들을 영원히 물리칠 수 있을 거예요!'),
(6284, '베셀레스는 무자비한 포식자입니다... 밤에 웹와인더 길을 지나가는 사람들은 정말 위험합니다. 밤에 그녀와 그녀의 자식들이 무고한 여행자들을 노리기 때문입니다. 저 또한 그녀의 60cm짜리 죽음의 송곳니에 희생될 뻔했지만, 다행히 그녀를 물리치고 안전한 곳으로 도망칠 수 있었습니다. 그 괴물을 없애버릴 수만 있다면 무엇이든 할 겁니다.'),
(6285, '스톰윈드에서 돌아오셨군요? 오스릭이 갑옷을 보내줬나요?'),
(6301, '전쟁으로 인한 끊임없는 파괴와 목재로 이윤을 추구하는 자들의 행태는 제게 깊은 고통을 안겨줍니다. 자연의 재생을 돕고 땅을 되살리기 위해 저는 가이아 씨앗이 필요합니다. 혹시 가지고 계신가요, $c님?'),
(6321, '당신은 공무 중이신 것 같습니다...'),
(6322, '장거리를 이동해야 한다면 야구 방망이가 최선의 선택입니다.'),
(6323, '저는 제 무기들을 항상 최상의 상태로 유지합니다. 깨끗하게 세척해 놓고 언제든 사용할 수 있도록 준비해 둡니다.'),
(6324, '$n, 돌아왔군. 지하도시에서 우리 물자를 가져왔나?'),
(6341, '어떻게 도와드릴까요?'),
(6342, '돌라나르로 돌아갈 준비가 되셨나요?'),
(6343, '$n, 다르나소스에서 돌아오셨군요?'),
(6344, '어떻게 도와드릴까요?'),
(6361, '윈드라이더를 찾으러 오셨나요? 운반할 물건이 있으신가요?'),
(6362, '당신 어깨에 묻은 먼지는 멀고어에서 온 먼지임이 틀림없어요. 제 친구 바르그와 이야기를 나누셨나요?'),
(6363, '안녕하세요, $c님. 무엇을 도와드릴까요?'),
(6364, '$n, 썬더 블러프에서 돌아왔나? 아하누에게 가죽은 전달했나?'),
(6365, '어딘가로 빨리 가야 할 일이 있다고? 그렇다면 제대로 찾아오셨군, 오크!'),
(6381, '당신이 심은 이 씨앗들은 강인하여 부패에 저항하고 다른 생명체가 자랄 수 있는 발판을 마련해 줍니다. 이 씨앗들은 자라나 부패를 막고 상처 입은 땅을 치유하며, 언젠가는 스톤탈론을 다시 울창한 숲으로 되돌릴 것입니다. 당신은 가이아의 씨앗을 모두 심었습니까?'),
(6384, '뭔가 좋은 냄새가 나네요! 혹시 생고기를 몸에 두른 건 아니죠?'),
(6385, '제 윈드 라이더가 필요하세요?'),
(6386, '오그리마에서 돌아오셨습니까? 제가 보내드린 고기는 그리슈카가 마음에 들어했나요?'),
(6387, '카라노스에 벌써 질리셨나요? 다른 도시로 떠날 준비가 되셨나요?'),
(6388, '어디 가시는 길인 것 같군요. 제 그리핀이 필요하신가요?'),
(6389, '$n, 네가 그 짓을 저질렀나? 흰개미들을 풀어놓았나? 스칼렛 크루세이드가 제분소와 하스글렌을 모두 장악했다면 정말 큰일 날 거야. 그들은 둘 다 가져서는 안 돼. 지난 전쟁의 희생자들을 이용해 먹고 있을 뿐이니, 미친 짐승처럼 처단해야 해!'),
(6390, '$n, 너 그랬어? 제재소에 흰개미를 풀어놓은 거야? 우리 가족이 일자리와 목숨을 잃은 것도 모자라, 내가 어린 시절을 보낸 곳까지 그 역겨운 소위 성직자들에게 점령당하다니... 쳇!!'),
(6391, '무엇을 도와드릴까요, 손님?'),
(6392, '아, $n. 아이언포지에서 돌아오셨습니까?'),
(6393, '조류의 심판소는 점점 초조해지고 있다. 그들은 오랜 세월 동안 모든 차원을 휩쓸고 지나간 이 전쟁을 끝내려 한다. 나의 동족들은 증오스러운 불의 정령들에 대한 영광스러운 승리 소식을 간절히 기다리고 있다. 내가 필요로 하는 화염의 정령들을 가지고 있는가?'),
(6394, '불타는 칼날단 소굴에는 들어가 봤소? 내 곡괭이는 찾아오셨소이까?'),
(6395, '우리는 죽은 자들을 존중해야 합니다, $n. 그것이 바로 우리가 재앙과 다른 점 중 하나입니다...'),
(6403, '저는… 저는… 저는 무력했어요.'),
(6421, '볼더슬라이드 협곡에서 무슨 소식을 들었나요? 레조나이트와 관련된 전설이 있었던 것 같은데… 도무지 기억이 나지 않네요. 동굴 바닥에 무엇이 있는지 알게 되면 그들의 간교한 의도를 밝혀낼 수 있을지도 모르겠어요.'),
(6441, '$n, 뿔 좀 빨리 구해다 주면 좋겠어. 나 곧 라쳇으로 돌아가야 하거든!'),
(6442, '나가족의 수가 $n만큼 증가했습니다. 이 작업을 완료해 주세요.'),
(6461, '야, 친구, 털복숭이 흡혈귀들 처치했어? 스톤탈론에서는 그런 놈들을 두려워하지 않지만, 밤에는 돌아다니지 않아... 무슨 말인지 알지, 친구? 내가 걔네들 밥그릇에 올라가지 않는 한 괜찮아. 행운을 빌어, 친구!'),
(6462, '$n, 부적을 찾았나? 퍼볼그들이 그 신성한 물건들을 손에 넣을 때마다 내 피는 분노로 끓어오르지!'),
(6481, '이 위협을 즉시 제거하지 않으면 스톤탈론 전체가 파멸할지도 모릅니다. 대지의 힘은 그 어떤 것도 따라올 수 없습니다. 고게록은 오랜 잠에서 깨어나면 약해져 있을 테니, 바로 이 기회를 잡아야 합니다... 지금 당장 가십시오!'),
(6482, '제 동생 룰을 보셨나요? 며칠 전에 숲으로 들어갔는데 아직 돌아오지 않았어요…'),
(6501, '$R, 당신에게서 악의 기운이 뿜어져 나오는 것을 느낍니다. 도대체 무엇을 들고 있길래 그런 기운이 나는 겁니까?'),
(6502, '시간의 흐름은 멈추거나 느려지지 않아, $R. 내 삶은 영원하지만 네 삶은 그렇지 않아. 네게 주어진 시간을 낭비하지 마...'),
(6503, '$n, 당신의 추격자 처치 보고를 기다리겠습니다.'),
(6504, '$n님, 페이지들을 곧 찾으시길 바랍니다! 저는 정말 얼른 업무에 복귀해야 해요!'),
(6521, '대사를 찾았나, $n? 죽었나? 우리는 스컬지가 칼림도어에 발판을 마련하도록 내버려 둘 수 없어. 그들은 우리 국경에 이미 충분한 위협이 되기 때문에 두 방면에서 상대해야 해. 자네가 알려준 사건들 중에서 유일하게 희망적인 건 그 노파가 타락하지 않은 것 같다는 거야. 그녀는 마음속 깊이 스컬지가 막대한 힘을 가져다줄 수는 있지만, 그들의 제안에 동의한다면 황무지는 진정으로 자신의 것이 될 수 없다는 걸 알고 있을 거야.'),
(6522, '$n 님, 도대체 무슨 이야기를 하고 싶으신 겁니까? 계속해서 저를 귀찮게 하시는 걸 보니 중요한 일인 것 같군요.'),
(6543, '서둘러요, $n. 그들이 보고서를 받아야 해요. 급해요.'),
(6544, '토렉은 실버윙 전초기지를 공격하는 임무를 맡았습니다. 공격은 성공적이었을까요?'),
(6545, '내 명령을 가지고 왔군. 활기 넘치고 의지가 강한 신병을 보니 반갑군.$B$B여기서 버티려면 빨리 배워야 할 거야. 나가의 위협이 점점 커지고 있거든.$n. 내가 여기 온 이후로 이 전초기지에 대한 여러 차례의 공격을 관찰하고 방어 태세를 갖췄지.$B$B하지만 자네도 그 일에 동참하고 싶다면, 여기 전초기지에 있는 다른 사람들에게 말해 보네.'),
(6546, '이 길에는 많은 위험이 도사리고 있네, $n. 이 땅을 여행하는 동안 이 점을 명심하는 게 좋을 거야. 동맹의 위협이 아주 가까이에 있거든.$B$B우리는 사방에서 적과 마주하고 있어. 사티로스는 아셴베일 동부에서 막강한 세력을 형성하고 있지. 또한 나가족이 아즈샤라 땅의 넓은 지역을 점령했다는 사실도 알게 되었네.$B$B우리 병력이 계속 증강되고 있다는 건 다행스러운 일이군. 앞으로 닥칠 일에 대비하렴, $n.'),
(6547, '$R, 잘 살펴봐야 해. 엘프들은 그림자 속에 숨어 있는 경우가 많아... 우리는 항상 경계해야 해. 우리가 이 땅을 차지하기 위해 얼마나 많은 노력을 기울였는지, 엘프들은 우리에게서 이 땅을 빼앗을 기회를 노리고 있어.$B$카드락에게서 받은 다음 명령은 가지고 있겠지?'),
(6548, '당신은 그들을 죽였습니까?'),
(6561, '대지의 어머니께서 당신과 함께 하시기를, $n. 지구와 모든 생명체 사이의 평화가 우리의 목표가 되어야 합니다. 대지는 자연을 위한 위대한 계획을 가지고 계시며, 우리 모두는 그 계획 안에서 각자의 역할을 해야 합니다.'),
(6563, '$n, 수정 찾는 건 어떻게 되어가고 있나요? 나가족이 수정을 채취하는 걸 목격했나요? 조상님들께 기도하는데, 나가족이 왜 그런 것들을 모으는지 이유를 찾을 수 있기를 바랍니다.'),
(6564, '네, $n님? 무슨 일이죠? 나가족이 모으고 있는 수정에 대해서는 아직 배워야 할 게 많아요.'),
(6565, '$n, 그를 찾았나요? 로르구스를 막아야 해요!'),
(6566, '인내심을 가져, $n. 집중해!'),
(6568, '로데론 이 지역에서 호드 사람을 보는 건 흔한 일이 아니군. 미란다에게 무슨 용건이 있나?'),
(6569, '우리가 흉내 내고자 하는 대상의 눈은 어떤 환상이든 가장 중요한 요소죠. 미란다는 ''스칼렛 크루세이드''라고 적힌, 눈알이 가득 담긴 자루를 가리켰다. 미란다는 웃었다.'),
(6571, '물품을 제때 보내주시면 정말 감사하겠습니다! 빨리 전달하지 못하면 큰일 날 것 같아요!'),
(6581, '라쳇에서 직송된 워송 톱날입니다! 네, 여기 있습니다. 하지만 어떻게 지불하실 건가요? 그냥 가져가실 순 없잖아요! 제 시간은 값싼 게 아니라고요! 제가 정말 필요한 건 여행 중에 휴대할 좋은 총입니다. 여자는 스스로를 보호해야 하잖아요? 제가 정말 마음에 드는 총이 있는데, 엔지니어라면 문제없이 만들 수 있을 것 같아요. 그러니 치명적인 블런더버스를 가져다주시면 톱날을 드리겠습니다. 거래 성립할까요?'),
(6582, '<엠버스트라이프가 쉿 소리를 낸다.>'),
(6583, '우리 적들의 피로 몸을 담그고 그들의 고통을 마시기 전에는 이곳으로 돌아오지 마라.'),
(6584, '아이러니하게도, 뭐, 시간이 정말 중요하죠.'),
(6585, '변화가 일어나고 있군, 꼬마야. 이 시험을 통과하면 이제 남은 건 형식적인 의식뿐이겠지.'),
(6601, '당황하지 마세요, $n!'),
(6602, '드라키사스를 결코 만만하게 볼 인물이 아니라는 건 굳이 설명할 필요도 없겠죠. 그의 손에 죽은 수천 명의 희생자들이 모든 걸 말해줄 겁니다.'),
(6607, '오늘 뭐 물어뜯는 거 있어?'),
(6610, '이 식욕 때문에 내가 죽을 것 같아! $n, 서둘러 줘 - 내가 내 비축분을 다 써버리기 전에.'),
(6621, '$n 님, 머거트 족장을 물리치셨나요? 그의 파울웰드 토템을 되찾으셨나요?'),
(6622, '정말 기적 같은 솜씨입니다, 의사 선생님. 그야말로 기적이에요.'),
(6624, '정말 기적 같은 솜씨입니다, 의사 선생님. 그야말로 기적이에요.'),
(6626, '사냥은 어떻게 진행되고 있나, $n? 이 외교관의 힘을 보여주는 이 작은 예시만 봐도 스컬지가 이 세상 역사상 가장 큰 위협 중 하나라는 사실에 대한 의심이 완전히 사라졌다.'),
(6627, '인생은 질문으로 가득 차 있죠, $C. 모든 질문에 답을 찾을 수는 없겠지만, 시간을 갖고 공부하다 보면 조금 더 많은 지식을 얻게 될 거예요.'),
(6628, '이 세상에서 살아남고 싶다면 반드시 알아야 할 단 하나의 규칙이 있다고 생각합니다. 바로 아는 것이 많을수록 보는 것도 많아진다는 것입니다. 공부하고 관찰하면 다른 누구도 보지 못하는 세상의 것들을 보게 될 것입니다.'),
(6629, '그룬디그 다크클라우드와 그의 부하 덩치 큰 부하들을 처치했습니까?'),
(6642, '심연에는 풍부하게 존재하지만, 암흑철은 여전히 형제단에게 귀중한 자원입니다. 라그나로스의 신성한 무기는 암흑철을 선호합니다. 암흑철 광석 10개를 바칠 때마다 형제단의 호감도를 얻게 됩니다.'),
(6643, '용암의 핵 안에서 운명을 시험하는 자들에게 화가 있을지어다. 죽음은 순식간에 찾아오며, 자비 없는 형벌이 내려진다. 수많은 형제단원들이 불타는 핵을 찾아 헤매다 목숨을 잃었다. 불타는 핵 하나를 바치면 형제단의 호의를 얻을 수 있을 것이다.'),
(6644, '토륨 형제단은 당신의 곤경에 공감합니다, $R. 이것이 바로 록토스에게 협상 권한을 부여한 이유입니다. $B$BO에게 용암 핵 1개를 바치면 형제단의 호의를 얻을 수 있을 것입니다.'),
(6645, '많은 신성한 제조법에는 라그나로스가 선택한 애완동물의 가죽이 필요합니다. 용암 심장부의 코어 하운드의 타오르는 시체에서 얻은 코어 가죽 2개를 바치면 형제단의 호의를 얻을 수 있을 것입니다.'),
(6646, '불의 군주의 눈물은 참으로 귀한 보물입니다. 산의 피 1개를 바치면 형제단에서 호의를 얻을 수 있을 것입니다.'),
(6661, '야르르... 스와비, 왜 이렇게 늦는 거야?'),
(6662, '<닙시가 상자의 공기 구멍 중 하나에 검지손가락을 집어넣는다.>$b$b살아있고 건강해... 딱 맞춰 왔네!'),
(6681, '밀턴을 만났나요?'),
(6701, '우리는 수년간 신디케이트와 치열한 전투를 벌여왔습니다. 그들은 실력은 부족하지만 수적으로는 압도적입니다. 그들의 규모를 눈에 띄게 줄이려면 아무리 빨리 섬멸해도 불가능할 정도입니다! 우리가 알아낸 가장 효과적인 방법은 그들의 문장을 훔치는 것입니다. 문장을 훔친 조직원은 내부적으로 처벌을 받습니다. 주머니를 싹 비우고 문장을 저나 다른 경비병에게 가져오십시오. 여기 남쪽에 있는 던홀드에서 시작하세요.'),
(6741, '갑옷 조각이 더 필요해, $n! 혹시 있어?'),
(6781, '$N, 우리 병력에게 보급할 장갑 부품이 더 필요해!'),
(6801, '저는 썬더 블러프 출신입니다. 케른 경께서 직접 저를 보내어 이 위급한 시기에 서리늑대 부족을 돕도록 하셨습니다. 하지만 더 이상 시간을 낭비할 수 없습니다. 당신은 적들을 쓰러뜨리고 그들의 피를 제게 가져와야 합니다. 충분한 피가 모이면 소환 의식을 시작할 수 있습니다. 정령 군주가 스톰파이크 군대에 풀려나면 승리는 보장될 것입니다.'),
(6804, '팔 보호대 있으세요?'),
(6805, '겁쟁이는 우리가 용납할 수 없는 것이다, $c. 실리투스로 가서 네 용기를 증명해 보이거라.'),
(6821, '$C, 당신은 그 눈을 갖고 있습니까? 블랙록 첨탑에 들어갈 힘이 있습니까?'),
(6822, '$n님, 용암 핵에서의 성공이 당신을 기다립니다.'),
(6824, '$n, 루시프론과 다른 적들을 물리쳤습니까? 적의 손을 손에 넣었습니까?'),
(6825, '새로운 워 라이더 함대를 준비해야 합니다, $r! 제 라이더들은 중앙 전장을 공격할 준비가 되어 있지만, 먼저 그들의 식욕을 돋워줘야 합니다. 공격에 대비해야죠.$b$b함대를 먹여 살릴 만큼 충분한 스톰파이크 병사의 살점이 필요합니다! 수백 파운드나 되죠! 당신이라면 충분히 해낼 수 있겠죠? 어서 가세요!'),
(6826, '수고 많았소, $n, 하지만 이제 시작일 뿐이오!$b$b내 워 라이더들은 목표물의 살점을 맛봐야 하오. 그래야 적에게 정확한 타격을 가할 수 있을 것이오!$b$b내 함대는 공군력 중 두 번째로 강력하오. 따라서 그들은 더 강력한 적들을 공격할 수 있을 것이오. 그러기 위해서는 스톰파이크 중위들의 살점이 필요하오!$b$b서두르시오, 병사여!$b$b'),
(6827, '난 며칠 동안 드워프 지옥에 갇혀 있었어. 복수심에 불타오르는 건 두말할 필요도 없지! 신중하게 계획을 세워야 해. 우선, 내 기병들이 공격할 목표물이 필요해. 그것도 최우선 목표물이 말이야. 스톰파이크 사령관들의 살점을 먹여 살려야겠어. 그런데 불행히도 그 녀석들은 적진 깊숙이 참호를 파고 있어! 자네 할 일이 산더미 같군.'),
(6844, '어머, 안녕하세요! 흠... 솔직히 말씀드리자면, 친구분께서 좀 냄새가 나시는 것 같아요. 좀 역한 냄새라고 할까요. 물론 당신을 개인적으로 비난하려는 건 아니고요. 그냥... 앞으로는 들판에서 돌아오신 후에 좀 상쾌하게 하시는 게 좋을 것 같다는 말씀이에요. 그러면 첫인상이 좀 더 좋아질 거예요! 어쨌든... 무슨 일로 오셨나요?'),
(6846, '내 병력은 보급을 마쳤고 공격할 준비가 완료되었습니다. 노렉 스톰파이크의 명령만 받으면 바로 전투에 투입하겠습니다!'),
(6881, '서리늑대 부족은 정령의 에너지로 물들어 있습니다. 그들의 주술사들은 통제되지 않으면 우리 모두를 파멸시킬 힘을 다루고 있습니다. 피해가 너무 커져서 마법사 서클이 감당할 수 없게 되었습니다! 이부스를 불러내야만 합니다. 서리늑대 부족의 병사들은 폭풍 수정이라는 정령 부적을 가지고 있습니다. 우리는 이 부적을 사용하여 이부스를 소환할 수 있습니다. 어서 나아가 수정을 획득하십시오!'),
(6921, '심해 핵을 찾는 데 성공했습니까? 그것 없이는 황혼의 망치가 심해에서 정확히 무슨 일을 꾸미고 있는지 알 수 없습니다.'),
(6922, '아, 반가워요, $n. 늘 그렇듯 방금 바다의 물결을 읽고 있었어요. 무슨 일로 이 외딴곳에 오셨나요?'),
(6941, '전선을 지키는 정예 프로스트울프 부대를 처리해야 한다, 병사! 저 야만인 무리를 소탕하는 임무를 자네에게 맡긴다. 그들의 중위와 병사들에게서 훈장을 받아 오게. 충분한 수의 잡몹이 처리되었다고 판단되면 공습을 감행하겠다.'),
(6942, '내 그리핀들은 최전선을 공격할 태세를 갖추고 있지만, 적의 전선이 흩어지기 전까지는 공격할 수 없다. 최전선 사수 임무를 맡은 서리늑대 전사들은 가슴에 자랑스럽게 훈장을 달고 있다. 저 썩어가는 시체에서 훈장을 뜯어내 이곳으로 가져와라. 최전선의 적의 전선이 충분히 흩어지면, 공중 공격을 명령하겠다! 하늘에서 내려지는 죽음이여!'),
(6943, '병사들의 사기가 많이 떨어졌군. 지난번 호드 공습이 실패로 돌아간 후로, 그들은 비행을 거부하고 있어! 자네가 그들의 사기를 북돋아 줘야 해. 전장으로 돌아가 서리늑대 부대의 심장부를 공격해. 지휘관과 수호자들을 쓰러뜨리고, 최대한 많은 훈장을 챙겨서 내게 돌아오게 하시오! 내 그리핀들이 전리품을 보고 적들의 피 냄새를 맡으면 다시 날아오를 거라고 장담하네! 지금 당장 가거라!'),
(6962, '간식 얘기가 나오니 저도 갑자기 먹고 싶어졌어요. 음... 진저브레드 쿠키랑 우유...'),
(6981, '안녕하세요, $R님. 무엇을 도와드릴까요?'),
(6982, '$n님, 호드 영토에 있는 콜드투스 광산에 들어가셨나요? 그곳의 보급품을 약탈하셨나요?'),
(6983, '$n - 겨울 축제에 필요한 간식들이 없으면 축제가 망쳐질 거예요! 그라쿠스 신도 이번 시즌에 착한 아이들과 맛있는 고기 파이를 나눠 먹지 못하게 되겠네요...'),
(6985, '$n, 아이언딥 광산에 들어갔나? 그곳의 물자를 약탈했나?'),
(7001, '당신의 도움이 없었다면 서리늑대기병대는 전투에 나설 탈것이 없었을 겁니다. 정말 큰 도움을 주셨습니다!'),
(7002, '우리 병사들 중 일부는 마구간지기에게 줄 늑대를 잡는 데 바쁘지만, 다른 병사들은 승마에 필요한 기본적인 것들을 준비해야 합니다. 물론 승마용 마구를 말하는 겁니다.$B$B이 지역의 토종 숫양들을 공격해야 합니다. 바로 스톰파이크 기병대가 타는 그 숫양들이죠!$B$B그들을 처치하고 가죽을 가져와 제게 제출하십시오. 충분한 가죽이 모이면 기수들을 위한 마구를 만들 수 있을 겁니다. 서리늑대 기병대가 다시 한번 말을 타고 달릴 것입니다!'),
(7003, '소형화 과정에서 발생하는 잔여물은 엔지니어링에 있어서 매우 귀중한 자원입니다! 적어도 제가 만든 전기충격기가 사용자가 폭발하는 것과 같은 실망스러운 결과를 초래하지 않도록 하는 데 도움이 되기 때문이죠. 아, 제가 당신에게 드린 것 말고 다른 전기충격기에 대해서 말씀하시는 거군요. 물론입니다!'),
(7025, '간식 얘기가 나오니 저도 갑자기 먹고 싶어졌어요. 음... 진저브레드 쿠키랑 우유...'),
(7026, '스톰파이크 여단은 맨몸으로 돌격할 수 없다! 우리는 야만인이 아니니, 말에 씌울 마구가 필요하다. 기지 근처를 돌아다니는 숫양들을 죽여 마구를 만드는 데 필요한 가죽을 얻을 수도 있겠지만, 그렇게 하는 건 어리석은 짓이다. 우리는 그 숫양들을 말로 써야 한다. 그러니 적의 기지를 공격하여 그들이 말로 쓰는 서리늑대를 처치하고 가죽을 가져와라. 그 가죽을 내게 가져오면 기병대를 위한 마구를 만들 수 있을 것이다. 가거라!'),
(7027, '당신의 도움이 없었다면 스톰파이크 램 라이더스는 전투에 나설 탈것이 없었을 겁니다. 정말 큰 도움을 주셨습니다!'),
(7028, '질문하지 마세요! 제 요청은 이것입니다.'),
(7029, '식물을 되살릴 수 있다면 다시 자라기 시작할 것입니다. 우리는 할 수 있는 일을 해야 합니다.'),
(7041, '식물을 되살릴 수 있다면 다시 자라기 시작할 것입니다. 우리는 할 수 있는 일을 해야 합니다.'),
(7043, '$n - 겨울 축제에 필요한 간식들이 없으면 축제가 망쳐질 거예요! 그라쿠스 신도 이번 시즌에 착한 아이들과 맛있는 고기 파이를 나눠 먹지 못하게 되겠네요...'),
(7044, '나는 끝없이 이어질 것 같았던 악몽에서 깨어났다...'),
(7046, '의식을 다시 시작하고 싶으시다면, 첫 번째 시도를 중단하고 다시 저에게 말씀해 주십시오.'),
(7061, '친구여, 멀고어와 저희 소박한 마을 썬더 블러프에 오신 것을 환영합니다. 저는 왕국과 그 백성, 그리고 그 역사에 관심을 갖는 자들에게 늘 흥미를 느낍니다. 혹시 당신도 그런 이유로 제 앞에 서 있는 것입니까?'),
(7063, '친구여, 아이언포지 왕국에 오신 것을 환영합니다. 저는 언제나 이 왕국과 그 백성, 그리고 그 역사에 관심을 갖는 자들에게 흥미를 느낍니다. 당신이 제 앞에 서 있는 이유도 그것 때문입니까?'),
(7064, '저는 이 싸움을 우리 스스로 해내고 싶지만, 다른 선택의 여지가 없습니다. 더 강력한 자들의 도움이 필요하고, 아제로스의 종족들은 힘을 합치면 이러한 어려움을 극복할 수 있다는 것을 이미 증명해 보였습니다. 그래서 저희는 당신들께 도움을 청할 수밖에 없었습니다. 부디 충분하기를 바랄 뿐입니다. 레물로스의 형제인 자에타르는 이 세상에 많은 고통을 안겨주었고, 결국 그것이 그의 죽음을 초래했습니다. 제가 당신들께 도움을 청함으로써 더 많은 죽음을 초래한 것은 아니기를 바랄 뿐입니다.'),
(7065, '필멸의 종족들에게 간절히 호소해야 한다는 부담감을 느끼지만, 우리에게는 다른 선택의 여지가 없습니다. 아제로스의 종족들은 협력할 때 이러한 어려움을 극복할 수 있다는 것을 이미 증명해 보였기에, 저는 그들에게 도움을 청합니다. 부디 그것으로 충분하기를 바랄 뿐입니다. 레물로스의 형제인 자에타르는 이 세상에 많은 고통을 안겨주었고, 결국 그것이 그의 죽음을 초래했습니다. 우리가 현명하다면, 우리 모두에게 교훈이 될 만한 이야기가 있습니다.'),
(7066, '$n, 자네에게서 부패의 냄새가 풍기는군... 요즘 모험가들 중 상당수가 그렇듯이. 하지만 자네는 뭔가 달라. 내게 할 말이 있나? 자네에게서 왠지 낯익은 기운이 느껴지는데, 정확히 누구인지 떠오르지 않네. 부디, 간청하건대, 왜 나를 찾아왔는지 말해 주시오.'),
(7067, '$n, 어떻게 결정했어? 날 도와줄 수 있어? 나와 함께 성스러운 땅에 발을 디디고 위대한 켄타우로스 부족을 만들어낼 수 있도록 도와주겠어!?'),
(7068, '수정들을 찾았나요? 강력한 의식이나 마법을 부릴 때, 그 그림자 조각들은 온갖 신비로운 마법에 아주 유용할지도 몰라요.'),
(7070, '여행을 다녀오셨나요? 꽤 위험한 여정이라는 건 알지만, 성공한다면 그만한 가치가 있을 거예요.'),
(7081, '$N, 자네는 아직 묘지를 공격하지 않았네. 이 임무를 완료하면 내게 돌아오게.'),
(7082, '얼라이언스가 점령한 묘지를 공격하세요!'),
(7101, '$n, 넌 아직 벙커를 공격해 본 적도 없잖아! 남들이 네 영광을 가로채가길 기다리는 거야?'),
(7102, '$n, 넌 아직 탑을 공격해 본 적이 없잖아! 뭘 기다리고 있는 거야?'),
(7122, '아직 광산을 점령하지 못했잖아! 우리가 광산을 장악하면 광물과 물자를 훨씬 쉽게 채취할 수 있을 거야.'),
(7124, '$n, 자네는 아직 광산을 점령하지 못했군! 우리가 장악하지 않은 광산을 찾아 그곳의 우두머리를 처치해라!'),
(7141, '가자, $n. 알터랙 계곡으로 가서 오크 장군을 물리쳐라!'),
(7161, '일어나! 일어나, $n! 이건 꿈이 아니야. 넌 지금 정말 치열한 전투 한복판에 있어!'),
(7162, '이 지역의 하피들을 조심하세요, $c. 그들은 당신의 목을 물어뜯는 데 조금도 망설이지 않을 겁니다!'),
(7201, '그것들을 내게 보여줘!'),
(7223, '혹시 갑옷 조각이라도 가져왔어, $n?'),
(7224, '사냥은 잘 되고 있나, $n. 혹시 나한테 줄 갑옷 조각 있어?'),
(7281, '사랑하는 형이 승천했는데도 여전히 살아있는 그가 얼마나 고통스러울까.'),
(7282, '병사, 유감스럽게도 이러한 명령을 내립니다.'),
(7301, '제가 듣고 싶은 말씀이 있으신가요?'),
(7302, '수색 작전은 어떻게 진행되고 있습니까, 병사?'),
(7321, '재료 구하는 데 성공했어? 있잖아, 이 지역에 동맹군 구더기가 너무 많아졌어... 내 생각엔 걔네들이 너무 가까이 다가온 것 같아...'),
(7341, '안녕하세요, $r님. 저는 썬더블러프 출신의 현상금 사냥꾼 콜라크입니다. 세계 곳곳을 누비며 많은 것을 보았죠. 남태평양을 누비던 중 이 놀라운 토륨 화살촉을 발견했습니다. 화살은 무한정 있지만, 화살촉이 바닥났네요. 쳇, 자존심 있는 타우렌이라면 허술한 활을 쓰는 짓은 절대 안 할 겁니다. 화살은 쓸모가 없잖아요! $b$b거래를 제안합니다. 토륨 화살촉과 토륨 화살촉을 똑같이 교환해 주시겠습니까? 어때요?'),
(7342, '이게 무슨 말도 안 되는 소리야?! 카라노스에서 온 마지막 탄약 수송이 엉망이었어! 이제 우리에게 남은 탄약이라고는 이 조잡하고 쓸모없는 화살뿐이라고! 토륨 화살 50만 개를 가지고 뭘 하라는 거야?! 자, 꼬마야. 네가 토륨 포탄을 가져다주면, 토륨 화살과 맞바꾸자! 거래할래?'),
(7361, '그들이 우리를 전멸시키려 한다고? 오히려 그들이 전멸될 것이다.'),
(7362, '머리카락이 어디서 왔는지는 상관없어, $R.'),
(7363, '네, 사실입니다. 제 동생도 인간입니다. 부끄러운 일이죠... 거의 흠잡을 데 없는 제 경력에 오점이 생겼습니다.'),
(7366, '베네딕투스여! 저는 그분의 위대함에 비하면 한낱 작은 티끌에 불과합니다. 그분을 찬양하라!'),
(7383, '오라클 트리 앞에 서 있으면... 마치 지혜가 형체를 갖추는 것을 느끼는 것과 같습니다.'),
(7401, '병사, 나는 도매로 아이러니를 취급한다.'),
(7429, '이건 고르독 족쇄 열쇠라고 불려. 뭐, 이 "재밌는 녀석들"이 계속 그렇게 부르거든. 오우거들 중 누구든 가지고 있을 것 같긴 한데, 특정 오우거가 가지고 있는지는 확실하지 않아. 경비병들이 가지고 있을 확률이 더 높을지도 몰라...$b$b내가 무슨 소리를 하는 거지? 너 이미 가지고 있잖아?! 저기 있는 거 아니야?!'),
(7441, '나그네여, 나는 아무것도 후회하지 않는다. 여왕은 오래전에 세상을 떠났고, 셴드랄라의 업적은 토르텔드린 왕자의 광기로 더럽혀졌다. 나는 오직 자유, 탈출만을 원한다…'),
(7461, '모험가여, 조심하십시오. 왕자는… 설득력이 있습니다.'),
(7463, '네? 저 아세요?'),
(7481, '내 동료인 나이트 엘프 학자 룬손이 이 임무를 위해 동맹들을 모집하고 있다.'),
(7482, '내 동료인 나이트 엘프 학자 룬손이 이 임무를 위해 동맹들을 모집하고 있다.'),
(7483, '이게 뭐지? 정리할 목록이 엄청 많네!'),
(7484, '또 너야? 이번엔 또 뭘 원하는 거야?'),
(7485, '내 인내심이 당신의 고통을 막아줍니다.'),
(7487, '용암의 핵에 접근하려면 먼저 당신의 영혼을 용암의 핵과 조화시켜야 합니다.'),
(7488, '웹을 가지고 있나요, $n? 웹에 집중된 마법의 에너지를 없애야 합니다!'),
(7489, '$n님, Lethtendris''s Web을 가지고 계신가요?'),
(7490, '쓰랄의 냉정한 태도가 오닉시아의 거대한 머리를 보는 순간 순식간에 변했다. 강력한 둠해머가 거의 칼집에서 뽑힐 뻔했다.'),
(7495, '우서 왕의 수염을 걸고 맹세코!'),
(7498, '당신은 두꺼운 책을 되찾았습니다!'),
(7499, '당신은 두꺼운 책을 되찾았습니다!'),
(7500, '당신은 두꺼운 책을 되찾았습니다!'),
(7501, '당신은 두꺼운 책을 되찾았습니다!'),
(7502, '당신은 두꺼운 책을 되찾았습니다!'),
(7503, '당신은 두꺼운 책을 되찾았습니다!'),
(7504, '당신은 두꺼운 책을 되찾았습니다!'),
(7505, '당신은 두꺼운 책을 되찾았습니다!'),
(7506, '당신은 두꺼운 책을 되찾았습니다!'),
(7507, '아, 저희가 자랑하는 최고의 컴필레이션 중 하나네요. 이 컴필레이션은 정말 오랫동안 없었는데 말이죠.'),
(7508, '좋습니다, 시작하겠습니다...'),
(7509, '어쩌면 언젠가 또 다른 누군가가 이 무지개빛 검을 휘두르게 될지도 모릅니다.'),
(7563, '$n, 사나운 올빼미 괴물들을 본 적 있나? 그 괴물들의 마법은 강력하고, 고통에 몸부림치는 그들의 몸에 흐르는 피에 응축되어 있지.'),
(7564, '나한테 줄 거 있어? 설마 크고 통통한 거미는 아니겠지? 아니면 바퀴벌레? 살아있으면 좋겠는데... 살아있는 바퀴벌레 씹는 거 진짜 좋아하거든...'),
(7581, '야생 사티로스의 피만이 충분할 것이다.'),
(7582, '헤데린은 쉽게 귀중한 보석을 포기하지 않을 겁니다.'),
(7583, '흠? 그래서?'),
(7602, '아무한테도 말하지 마, 니비는 좀 멍청해.'),
(7603, '길을 잃으셨나요?'),
(7604, '거래가 성사된 건가요?'),
(7624, '벌써 입술에 울라테크의 심장 맛이 느껴지는군. 배신자의 살점은 이토록 달콤하구나...'),
(7625, '$n, 제이든나르에 가본 적 있어? 베인할로우 경에게서 별가루를 얻었니?'),
(7626, '$n, 그 영약들을 가지고 있나요? 모르줄이 데스무라의 종이 필요하다고 했는데, 그걸 만들려면 엄청난 양의 그림자 힘이 필요하대요!'),
(7627, '검은 행진의 수레바퀴는 만들기가 쉽지 않고 재료도 많이 필요해요. 재료는 다 모으셨나요?'),
(7628, '용 비늘 가져왔어, $n? 비늘이 없으면 양초 만들기 시작하고 싶지 않아... 안 그러면 캠프 전체가 폭발할지도 몰라!'),
(7629, '$n, 스콜로맨스에 가본 적 있나요? 그 악마가 아직 양피지에 별가루를 묻혔나요?'),
(7630, '아르카나이트 가지고 있어, $n? 아르카나이트를 얻으면 블랙 로드스톤을 만들어 줄 수 있어.'),
(7632, '<바르트루스가 신음한다.>'),
(7634, '젊은 $c 님, 다시 오신 것을 환영합니다.'),
(7635, '$n, 자네가 검은 용을 찾아 처치하는 데는 별 어려움이 없을 거라고 확신하네. 쓸데없는 잡담으로 내 시간을 낭비하지 마.'),
(7636, '그들의 변장에 속지 마세요!'),
(7637, '존경하는 $C님, 안녕하십니까! 제가 아끼는 향로에 가장 신선한 향을 채우고 세 번 축복을 내렸습니다. 당신의 기부는 아이언포지에서 새 향로를 만드는 데 도움이 될 뿐만 아니라, 궁핍한 사람들을 위한 식량 비축량을 늘리는 데에도 큰 도움이 될 것입니다.'),
(7639, '$n님, 다시 오신 것을 환영합니다. 퇴마 향로는 구하셨나요?'),
(7640, '다시 만나서 반가워요, $n. 테러데일에서 일은 끝났나요?'),
(7642, '아, $C님. 제가 말씀드린 것들이 없으면 갑옷 제작을 끝낼 수 없을 것 같습니다. 필요한 것들은 다 준비하셨나요?'),
(7643, '고대 말의 정령은 마치 당신에게서 무언가를 원하는 듯 기대에 찬 눈빛으로 당신을 바라봅니다.'),
(7644, '$N, 돌아왔구나! 메리디스 칼슨과 텐드리스 워프우드를 무사히 처리했니? 솔직히 누가 더 큰 위협인지 잘 모르겠네...'),
(7645, '그래, 이제 내가 틀렸다는 걸 증명했잖아, 안 그래? 모두가 틀렸다는 걸 증명했어! 내가 처음부터 옳았어!!!'),
(7646, '당신은 정말 멀리까지 왔습니다, $n. 당신이 마지막으로 행하는 세속적인 희생은 당신의 가장 위대한 업적 중 하나의 시작이 될 것입니다. 저는 온몸으로 그것을 느낄 수 있습니다!'),
(7647, '쓰러진 군마의 영혼이 슬픔에 잠긴 눈빛으로 당신을 바라봅니다. 슬픔과 공허함이 가득한 눈빛은 마치 모든 희망을 잃어버린 듯 당신을 응시합니다.'),
(7648, '$n님, 순조롭게 진행되고 있네요. 갑옷 제작이 완료되면 다음 단계로 순조롭게 넘어갈 수 있을 거예요.'),
(7649, '당신은 두꺼운 책을 되찾았습니다!'),
(7650, '당신은 두꺼운 책을 되찾았습니다!'),
(7651, '당신은 두꺼운 책을 되찾았습니다!'),
(7653, '벨트 제작을 위해 토륨 막대 10개가 필요합니다.'),
(7654, '부츠 제작에 토륨 막대 20개가 필요해. 맞아, 20개. 울 거야? 손수건 줄까?<데로탱이 웃는다.>'),
(7655, '팔 보호대 제작 계획에 토륨 막대 10개가 필요해. 괜찮아, 얘야? 얼굴이 새빨개졌잖아.'),
(7656, '가슴 보호대 제작을 위해 토륨 막대 30개가 필요하겠군. 아이고, 또 그러네. 이제 신들에게 달려가서 왜 널 버렸냐고 빌 거야? 정신 차려, 낸시! 인생이 공평하다고 누가 그랬어?'),
(7657, '토륨 막대 25개만 건네주시면 조타 장치 설계도를 드리겠습니다.'),
(7658, '토륨 막대 30개만 내놓으면 다리 설계도는 네 거야. 내가 널 파산으로 몰아넣고 있다는 거 알아! 그런 얘기는 다 들어봤으니 징징거리지 마, 약골아.'),
(7659, '어깨 보철물 제작을 위해 토륨 막대 10개가 필요합니다.'),
(7660, '당신의 낡고 빠른 늑대를 가져오시면, 새 늑대 무리의 늑대로 바꿔 드리겠습니다. 새 늑대는 당신의 낡은 늑대만큼 빠르지만, 생김새는 다를 겁니다. 마당에 있는 우리 날렵한 늑대들을 보시면 어떤 모습일지 알 수 있을 겁니다.'),
(7661, '당신의 낡고 빠른 늑대를 가져오시면, 새 늑대 무리의 늑대로 바꿔 드리겠습니다. 새 늑대는 당신의 낡은 늑대만큼 빠르지만, 생김새는 다를 겁니다. 마당에 있는 우리 날렵한 늑대들을 보시면 어떤 모습일지 알 수 있을 겁니다.'),
(7662, '늙은 코도를 데려오시면 새로 온 코도 한 마리로 교환해 드리겠습니다. 새 코도는 당신의 옛 코도만큼 빠르지만, 외모는 다를 겁니다. 저희 농장에 있는 훌륭한 코도들을 둘러보시고 어떤 코도가 있는지 확인해 보세요.'),
(7663, '늙은 코도를 데려오시면 새로 온 코도 한 마리로 교환해 드리겠습니다. 새 코도는 당신의 옛 코도만큼 빠르지만, 외모는 다를 겁니다. 저희 농장에 있는 훌륭한 코도들을 둘러보시고 어떤 코도가 있는지 확인해 보세요.'),
(7664, '당신이 낡은 랩터를 가져오면, 저는 날카로운 발톱을 새로 단 랩터를 드리겠습니다! 새 랩터는 당신의 낡은 랩터만큼이나 빠르지만, 외모는 새롭습니다. 여기에서 날렵한 랩터들을 살펴보고 어떤 랩터를 선택할지 결정하세요.'),
(7665, '당신이 낡은 랩터를 가져오면, 저는 날카로운 발톱을 새로 단 랩터를 드리겠습니다! 새 랩터는 당신의 낡은 랩터만큼이나 빠르지만, 외모는 새롭습니다. 여기에서 날렵한 랩터들을 살펴보고 어떤 랩터를 선택할지 결정하세요.'),
(7667, '물질적인 도움을 요청드리는 게 좀 쑥스럽지만, 제가 완성하고 싶은 점술 도구에 각각 하나씩 필요해서요. 만약 도와주실 수 없으시더라도 충분히 이해하겠습니다.'),
(7701, '내 머리숱 많은 거 안 보여? *딸꾹* 뭘 원하는 거야? *딸꾹*'),
(7702, '$n, 그 이상한 고글에 속지 마. 여기서 똑똑한 건 나야.'),
(7703, '하하, 못 찾으셨나 보군요, 사장님? 옛날이야기가 좀 허무맹랑한 이야기일지도 몰라요... 그 소름 끼치는 엘프가 고르독 왕에게서 물건을 훔칠 수 있다니 믿기 힘들잖아요!'),
(7704, '베개가 정말 크네요! 어디서 샀어요?'),
(7721, '원소 핵의 활용법에 대한 기술적인 세부 사항으로 여러분을 지루하게 할 수도 있겠지만, 대신 이 중요한 임무를 완수하도록 귀중한 코인과 상품을 제공하여 여러분의 참여를 유도하겠습니다. 욘, 당신은 정말로 임무를 완료했습니까?'),
(7722, '설계도를 찾으셨나요?'),
(7723, '그것들을 두들겨 패셨나요?'),
(7724, '그 사람이 옳았나요? 그게 엉덩이에서 나오는 건가요?'),
(7725, '아, 연구와 활용의 결실이 달콤한 잔여물 형태로 나타났군요. 음, 다시 말해서, 연구할 때는 맛을 느끼거나 하진 않아요. 거의요.'),
(7726, '제가 필요한 원소 핵을 찾으셨나요?'),
(7727, '<헨젤은 발가락에 생긴 뾰루지를 열심히 문지르고 있다.>$B$B그냥 서 있지 말고, 오일이랑 수세미 가져와서 어서 문질러 닦아.$B$B수세미가 없다고? 그럼! 수세미를 사러 나가야겠군.%$B$B어디 가는 거야?'),
(7728, '현상금을 노리고 온 거라면, 훔친 물건을 내게 넘겨줘야 할 거야.'),
(7729, '정확한 무게를 재려면 옷을 입었을 때와 벗었을 때 모두 재봐야 합니다.'),
(7730, '사냥은 어떻게 진행되고 있나요, $n? 성공을 보고하러 오셨나요?'),
(7731, '스팅래셔를 쓰러뜨리는 데 성공하셨나요?'),
(7732, '안녕하세요, 친구분. 급한 일이 있으신 것 같네요. 제가 도와드릴 일이 있으신가요?'),
(7733, '만약 이 ''분노의 흉터'' 예티 가죽이 ''야생의 흉터'' 예티 가죽처럼 품질이 좋다면, 토륨만큼이나 단단할지도 모릅니다! 상상해 보세요!'),
(7734, '만약 이 ''분노의 흉터'' 예티 가죽이 ''야생의 흉터'' 예티 가죽처럼 품질이 좋다면, 토륨만큼이나 단단할지도 모릅니다! 상상해 보세요!'),
(7735, '이게 뭐야, $n - 나한테 특별한 걸 가져왔어?'),
(7736, '쓸데없는 소리로 내 소중한 시간을 더 이상 낭비하지 마, $r. 이제 줄어드는 화염 플럭스 공급량을 보충하는 데 집중해야 해.$B$B내가 자네에게 필요한 건 다음과 같네.$B$B*인센도사우루스 비늘.$B$B*킹스블러드.$B$B*석탄.$B$B 자네가 줄 수 있는 건 뭐든지 받겠네!$B$B형제단과 사이좋게 지내고 싶다면 빨리 해내야 할 거야.'),
(7737, '$R, 자네는 형제단의 조직 내에서 차근차근 승진했군. 우리는 자네를 호의적으로 보기 시작했지. 정말 대단한 업적이네! $B $B더 많은 일을 하고 우리 사이에서 더 존경받고 싶다면 잘 들어보게.$B $B우리는 검은 철 잔여물을 혼합물에 첨가함으로써 불꽃 용암을 정제할 수 있지. 검은 철 잔여물은 검은바위 심층부에서 찾을 수 있네.'),
(7738, '이게 뭐야, $n - 나한테 특별한 걸 가져왔어?'),
(7781, '상상도 할 수 없어!'),
(7783, '$n, 당신이 그 짐승에게 결정타를 날렸을 때 그 짐승의 얼굴 표정을 직접 볼 수 있었더라면 좋았을 텐데.'),
(7785, '당신은 그를 영원한 감옥에서 풀어주시겠습니까?'),
(7786, '필요하다면 세상을 무릎 꿇게 만들어라!'),
(7787, '<데미트리안은 당신 앞에서 움츠러듭니다.>'),
(7789, '적의 피는 영광의 표식이다. 너에게도 그런 표식이 있느냐?'),
(7791, '만약 당신이 양모 천 60장을 가지고 있고 기증할 의향이 있다면, 지금 바로 제가 받을 수 있습니다.'),
(7792, '만약 당신이 양모 천 60장을 가지고 있고 기증할 의향이 있다면, 지금 바로 제가 받을 수 있습니다.'),
(7793, '덧붙여 말씀드리자면, 비단과 같은 귀한 선물은 지역 사회에서 당신의 위상을 높이는 데 확실히 도움이 될 것입니다! 만약 비단 천 60장을 가지고 계시고 기증하실 의향이 있으시다면, 지금 바로 제가 받겠습니다.'),
(7794, '만약 당신이 마법직물 60장을 가지고 있고 기증할 의향이 있다면, 지금 바로 제가 받을 수 있습니다.'),
(7795, '$n님, 저희 천 기증 운동에 정말 큰 도움을 주셨습니다. 저희는 재고를 보충하기 위해 열심히 노력하고 있지만, 특히 룬천이 심각하게 부족한 상황입니다. 룬천이 절실히 필요하며, 이전처럼 $n님께서 도움을 주시면 정말 감사하겠습니다!$b$b가능하시다면, 여유가 되시는 룬천을 가져다주시면 감사하겠습니다. 처음에는 60장씩 한 번에 기증해 주시면 되고, 그 후로 더 많은 기증을 받겠습니다.'),
(7796, '룬천 묶음을 제출할 준비가 되면 언제든지 받겠습니다.'),
(7798, '덧붙여 말씀드리자면, 비단과 같은 귀한 선물은 지역 사회에서 당신의 위상을 높이는 데 확실히 도움이 될 것입니다! 만약 비단 천 60장을 가지고 계시고 기증하실 의향이 있으시다면, 지금 바로 제가 받겠습니다.'),
(7799, '만약 당신이 마법직물 60장을 가지고 있고 기증할 의향이 있다면, 지금 바로 제가 받을 수 있습니다.'),
(7800, '$n님, 저희 천 기증 운동에 정말 큰 도움을 주셨습니다. 저희는 재고를 보충하기 위해 열심히 노력하고 있지만, 특히 룬천이 심각하게 부족한 상황입니다. 룬천이 절실히 필요하며, 이전처럼 $n님께서 도움을 주시면 정말 감사하겠습니다!$b$b가능하시다면, 여유가 되시는 룬천을 가져다주시면 감사하겠습니다. 처음에는 60장씩 한 번에 기증해 주시면 되고, 그 후로 더 많은 기증을 받겠습니다.'),
(7801, '룬천 묶음을 제출할 준비가 되면 언제든지 받겠습니다.'),
(7802, '현재 양모 천 기부를 받고 있습니다. 양모 천 60장을 기부해 주시면 아이언포지에서 여러분의 관대한 행동에 대해 진심으로 감사 인사를 전해드립니다. 저희 창고에는 양모가 충분히 있어서 60장만 기부해 주시면 됩니다. 왕국 내 다른 분들로부터도 충분한 양을 확보할 수 있을 것입니다. 양모 천 60장을 가지고 계시고 기부하실 준비가 되셨다면 지금 바로 받아 가겠습니다.'),
(7803, '다른 대부분의 직물과 마찬가지로 저희 실크 재고도 역대 최저 수준입니다. 저희 매장 사정상 실크는 총 60장만 있으면 충분합니다. 다른 분들의 도움만 있다면 목표량을 달성할 수 있을 것 같습니다. 실크와 같은 귀한 기증은 지역 사회에서 귀하의 위상을 높이는 데 큰 도움이 될 것입니다! 실크 60장을 가지고 계시고 기증하실 의향이 있으시다면 지금 바로 받아갈 수 있습니다.'),
(7804, '마법직물이 부족해지고 있습니다! 재고를 채우는 데 여러분의 도움이 절실히 필요합니다! 마을 전체의 도움을 받는다면, 여러분께서 마법직물 60장만 기부해 주셔도 목표 달성이 가능합니다. 아이언포지 주민들은 여러분의 이러한 관대한 마음을 결코 잊지 않을 것입니다! 혹시 마법직물 60장을 가지고 계시고 기부해 주실 의향이 있으시다면, 지금 바로 받아가겠습니다.'),
(7805, '$N님, 저희 천 기증 운동에 정말 큰 도움을 주셨습니다. 저희는 재고를 보충하기 위해 열심히 노력하고 있지만, 특히 룬천이 심각하게 부족한 상황입니다. 룬천이 절실히 필요하며, 이전처럼 $N님께서 도움을 주시면 정말 감사하겠습니다!$B$B가능하시다면, 여유가 되시는 룬천을 가져다주시면 감사하겠습니다. 우선 60개씩 한 번에 기증해 주시면 받고, 그 후로 더 많은 기증을 받겠습니다.'),
(7806, '룬천 묶음을 제출할 준비가 되면 언제든지 받겠습니다.'),
(7807, '현재 양모 천 기부를 받고 있습니다. 양모 천 60장을 기부해 주시면 아이언포지에서 당신의 관대한 행동에 대해 진심으로 감사 인사를 전해드립니다. 저희 창고에는 양모가 충분히 있어서 60장만 있으면 됩니다. 왕국 내 다른 분들로부터도 충분한 양을 구할 수 있을 것입니다. 양모 천 60장을 가지고 계시고 기부할 준비가 되셨다면 지금 바로 받아 가겠습니다.'),
(7808, '덧붙여 말씀드리자면, 비단과 같은 귀한 선물은 지역 사회에서 당신의 위상을 높이는 데 확실히 도움이 될 것입니다! 만약 비단 천 60장을 가지고 계시고 기증하실 의향이 있으시다면, 지금 바로 제가 받겠습니다.'),
(7809, '만약 당신이 마법직물 60장을 가지고 있고 기증할 의향이 있다면, 지금 바로 제가 받을 수 있습니다.'),
