(7812, '룬천 묶음을 제출할 준비가 되면 언제든지 받겠습니다.'),
(7813, '만약 당신이 양모 천 60장을 가지고 있고 기증할 의향이 있다면, 지금 바로 제가 받을 수 있습니다.'),
(7814, '덧붙여 말씀드리자면, 비단과 같은 귀한 선물은 지역 사회에서 당신의 위상을 높이는 데 확실히 도움이 될 것입니다! 만약 비단 천 60장을 가지고 계시고 기증하실 의향이 있으시다면, 지금 바로 제가 받겠습니다.'),
(7815, '사냥은 어떻게 진행되고 있나요?'),
(7816, '이해하셨나요?'),
(7817, '만약 당신이 마법직물 60장을 가지고 있고 기증할 의향이 있다면, 지금 바로 제가 받을 수 있습니다.'),
(7818, '$n님, 저희 천 기증 운동에 정말 큰 도움을 주셨습니다. 저희는 재고를 보충하기 위해 열심히 노력하고 있지만, 특히 룬천이 심각하게 부족한 상황입니다. 룬천이 절실히 필요하며, 이전처럼 $n님께서 도움을 주시면 정말 감사하겠습니다!$b$b가능하시다면, 여유가 되시는 룬천을 가져다주시면 감사하겠습니다. 처음에는 60장씩 한 번에 기증해 주시면 되고, 그 후로 더 많은 기증을 받겠습니다.'),
(7819, '$n님, 다시 한번 인사드립니다! 저희는 룬천이 항상 필요하며, $n님께서 기꺼이 나눠주신다면 언제든 환영입니다. 룬천 20묶음을 추가로 보내주시면, 언더시티를 위해 꾸준히 노력해주신 것에 대한 감사를 표하겠습니다. $n님께서 룬천을 보내주실 준비가 되시면 언제든 보내주세요.'),
(7820, '현재 양모 천 기부를 받고 있습니다. 양모 천 60장을 기부해 주시면 썬더 블러프에서 여러분의 관대한 행동에 대해 진심으로 감사를 표할 것입니다. 저희 창고에는 양모가 충분히 있어서 60장만 있으면 됩니다. 왕국 내 다른 분들로부터도 충분한 양을 확보할 수 있을 것입니다. 양모 천 60장을 가지고 계시고 기부하실 준비가 되셨다면 지금 바로 받아 가겠습니다.'),
(7821, '다른 대부분의 직물과 마찬가지로 저희 실크 재고도 역대 최저 수준입니다. 저희 매장 사정상 실크는 총 60장만 있으면 충분합니다. 다른 분들의 도움만 있다면 목표량을 달성할 수 있을 것 같습니다. 실크와 같은 귀한 기증은 지역 사회에서 귀하의 위상을 높이는 데 큰 도움이 될 것입니다! 실크 60장을 가지고 계시고 기증하실 의향이 있으시다면 지금 바로 받아갈 수 있습니다.'),
(7822, '마법직물이 부족해지고 있습니다! 재고를 채우는 데 여러분의 도움이 절실히 필요합니다! 마을 전체의 도움을 받는다면, 여러분께서 마법직물 60장만 기부해 주셔도 목표 달성이 가능합니다. 썬더 블러프에서는 여러분의 이러한 관대한 마음을 결코 잊지 않을 것입니다! 혹시 마법직물 60장을 가지고 계시고 기부해 주실 의향이 있으시다면, 지금 바로 받아가겠습니다.'),
(7823, '$n님, 저희 천 기증 운동에 정말 큰 도움을 주셨습니다. 저희는 재고를 보충하기 위해 열심히 노력하고 있지만, 특히 룬천이 심각하게 부족한 상황입니다. 룬천이 절실히 필요하며, 이전처럼 $n님께서 도움을 주시면 정말 감사하겠습니다!$b$b가능하시다면, 여유가 되시는 룬천을 가져다주시면 감사하겠습니다. 처음에는 60장씩 한 번에 기증해 주시면 되고, 그 후로 더 많은 기증을 받겠습니다.'),
(7824, '$n님, 저희 천 기증 운동에 정말 큰 도움을 주셨습니다. 저희는 재고를 보충하기 위해 열심히 노력하고 있지만, 특히 룬천이 심각하게 부족한 상황입니다. 룬천이 절실히 필요하며, 이전처럼 $n님께서 도움을 주시면 정말 감사하겠습니다!$b$b가능하시다면, 여유가 되시는 룬천을 가져다주시면 감사하겠습니다. 처음에는 60장씩 한 번에 기증해 주시면 되고, 그 후로 더 많은 기증을 받겠습니다.'),
(7825, '룬천 묶음을 제출할 준비가 되면 언제든지 받겠습니다.'),
