(7827, '다른 대부분의 직물과 마찬가지로 저희 실크 재고도 역대 최저 수준입니다. 저희 매장 사정상 실크는 총 60장만 있으면 충분합니다. 다른 분들의 도움만 있다면 목표량을 달성할 수 있을 것 같습니다. 실크와 같은 귀한 기증은 지역 사회에서 귀하의 위상을 높이는 데 큰 도움이 될 것입니다! 실크 60장을 가지고 계시고 기증하실 의향이 있으시다면 지금 바로 받아갈 수 있습니다.'),
(7828, '레반투스크의 위력을 보여줘라!'),
(7829, '머릿속의 불순한 생각을 모두 비우고, 야생과 하나가 되십시오!'),
(7830, '레이저비크 스카이로드는 그리핀 중에서도 매우 희귀한 종으로, 짝짓기를 통해 살인적인 자손을 낳는 존재입니다.'),
(7831, '마법직물이 부족해지고 있습니다! 재고를 채우는 데 여러분의 도움이 절실히 필요합니다! 공동체 전체의 힘을 빌리자면, 여러분께서 마법직물 60장만 기부해 주시면 목표 달성이 가능합니다. 여러분의 이러한 관대한 마음은 오그리마에서 결코 잊지 않겠습니다!$B$B만약 마법직물 60장을 가지고 계시고 기부해 주실 의향이 있으시다면, 지금 바로 받아가겠습니다.'),
(7832, '룬천 묶음을 제출할 준비가 되면 언제든지 받겠습니다.'),
(7833, '만약 당신이 양모 천 60장을 가지고 있고 기증할 의향이 있다면, 지금 바로 제가 받을 수 있습니다.'),
(7834, '다른 대부분의 직물과 마찬가지로 저희 실크 재고도 역대 최저 수준입니다. 저희 매장 사정상 실크는 총 60장만 있으면 충분합니다. 다른 분들의 도움만 있다면 목표량을 달성할 수 있을 것 같습니다. 실크와 같은 귀한 기증은 지역 사회에서 귀하의 위상을 높이는 데 큰 도움이 될 것입니다! 실크 60장을 가지고 계시고 기증하실 의향이 있으시다면 지금 바로 받아갈 수 있습니다.'),
(7835, '마법직물이 부족해지고 있습니다! 재고를 채우는 데 여러분의 도움이 절실히 필요합니다! 공동체 전체의 도움을 받는다면, 여러분께서 마법직물 60장만 기부해 주시면 목표 달성이 가능합니다. 여러분의 이러한 관대한 마음은 다크스피어 트롤들에게 큰 힘이 될 것입니다! 혹시 마법직물 60장을 가지고 계시고 기부해 주실 의향이 있으시다면, 지금 바로 받아가겠습니다.'),
(7836, '$n님, 저희 천 기증 운동에 정말 큰 도움을 주셨습니다. 저희는 재고를 보충하기 위해 열심히 노력하고 있지만, 특히 룬천이 심각하게 부족한 상황입니다. 룬천이 절실히 필요하며, 이전처럼 $n님께서 도움을 주시면 정말 감사하겠습니다!$b$b가능하시다면, 여유가 되시는 룬천을 가져다주시면 감사하겠습니다. 처음에는 60장씩 한 번에 기증해 주시면 되고, 그 후로 더 많은 기증을 받겠습니다.'),
(7837, '룬천 묶음을 제출할 준비가 되면 언제든지 받겠습니다.'),
(7838, '이봐, 멍청아! 투기장 대장의 장신구 12개를 가져오너라.'),
(7839, '이 지역의 사악한 가지 트롤들을 조심하세요, $n. 그들은 무자비하고 살인적인 악당들입니다.'),
(7840, '라드가 너무 배고파요.'),
(7841, '너 너무 깔끔하잖아. 좀 더 다양하게 해야지. 적과 맞서 싸울 때도 거칠고 투박하게 행동해야지.'),
(7842, '마지막 메시지는 분명히 그들을 겁먹게 하거나, 아니면 아주 아주 화나게 만들 거예요.'),
(7843, '왜 이렇게 늦어?'),
(7844, '사악한 가지의 예언가와 약탈자들은 오지 북동쪽 지역에 거주합니다.'),
(7846, '서두르셔야 해요!'),
(7848, '용암의 핵에 접근하려면 먼저 당신의 영혼을 용암의 핵과 조화시켜야 합니다.'),
(7849, '그의 유해를 수습하는 대로 야요진에게 가져가 제대로 장례를 치르도록 하겠습니다.'),
(7850, '바일브랜치와 싸울 때는 조심해야 합니다, $n. 그들은 정신이 혼미해져서 죽을 때까지 싸웁니다.'),
(7861, '진타알로르에서 온 소식인가요?'),
(7862, '채용 공고 때문에 오셨나요?'),
(7874, '적의 피는 영광의 표식이다. 너에게도 그런 표식이 있느냐?'),
(7875, '적의 피는 영광의 표식이다. 너에게도 그런 표식이 있느냐?'),
(7876, '적의 피는 영광의 표식이다. 너에게도 그런 표식이 있느냐?'),
(7881, '다크문 축제에서 우리는 정말 많이 걸어 다닙니다. 축제장 이곳저곳을 걸어 다니죠... 사실, 일하는 동안 앉아 있는 모습은 절대 보실 수 없을 거예요! 그러니 부츠가 닳아 없어지는 건 당연한 일입니다! 우리에게는 튼튼하면서도 멋스러운 부츠가 필요한데, 양각 가죽 부츠가 딱이죠. 자, 당신! 가죽 세공에 능숙하시죠? 저에게 양각 가죽 부츠를 만들어 주시면 다크문 축제 입장권을 드리겠습니다.'),
(7882, '우리 축제 일꾼들은 쓰레기를 쓸고 못을 박는 일만 하는 게 아닙니다! 축제가 이동하는 동안 경비도 서는데, 그러려면 튼튼한 가죽 갑옷이 항상 필요하죠. 튼튼한 가죽 갑옷을 만들어서 제게 가져다주시면, 필요한 사람들에게 전달해 드리겠습니다. 그리고 그 대가로 다크문 축제 티켓도 드리겠습니다.'),
(7883, '예브 네블기어는 자신의 쇼에 더 많은 재능 있는 사람을 영입하려고 하는데, 세상에서 가장 큰 노움을 찾고 있습니다. 혹시 상당한 크기의 노움을 아시나요? 노움을 찾기 전에 먼저 의상을 준비해야 한다고 하더군요. 야만적인 갑옷이 의상의 좋은 기본이 될 것 같은데, 갑옷을 몇 개 만들어서 가져다주시겠어요? 그렇게 해주시면 다크문 축제 티켓을 한 뭉치 드리겠습니다...'),
(7884, '예브는 자신의 동물원에 다른 볼거리들을 구상 중인데, 악어에게 길러진 소년을 위한 축축하고 늪지대 같은 집과, 어쩌면 멀록을 위한 집도 포함될지도 몰라. 설치하고 철거하는 동안 물에 흠뻑 젖지 않도록 방수 레깅스가 필요할 거야. 내 생각엔 거북이 비늘로 만든 레깅스가 딱 좋을 것 같아. $B$B$n, 너 그 레깅스 만들 수 있어? 만약 만들어준다면, 보상으로 다크문 축제 티켓을 한가득 줄게...'),
(7885, '당신은 잘 모르실 수도 있지만, 이동식 유원지를 운영하는 데는 많은 비용이 듭니다! 모든 게 너무 빨리 닳아서 이윤을 남기는 게 신기할 정도예요.$B$B이런 숨겨진 비용 때문에 우리는 항상 장비를 최대한 저렴하게 유지할 방법을 찾고 있습니다. 예를 들어, 우리 텐트는 자주 찢어지는데, 가죽 갑옷 키트가 훌륭한 땜빵이 된다는 걸 알게 됐어요. 갑옷 키트를 찾아서 좀 가져다주시겠어요? 그러면 비용을 크게 절약할 수 있을 거예요! 그렇게 해주시면, 다크문 축제 티켓을 한 움큼 드리겠습니다...'),
(7889, '세상에서 가장 강한 여자가 되려면 엄청난 노력이 필요해! 내 역기 세트가 너무 가벼워져서, 몸매를 유지하려면 더 많은 역기가 필요해! 혹시 역기 좀 가져다줄 수 있을까? 가져다주면 다크문 축제 티켓을 줄게.'),
(7890, '운동 효과를 높이려고 무거운 맷돌 사이에 지팡이를 끼워 머리 위로 들어 올리는 운동을 즐겨 해요. 쉽지는 않지만, 저처럼 세상에서 가장 강한 여자가 되려면 가만히 앉아서는 안 되잖아요! 혹시 도와주실 수 있나요? 맷돌이 더 필요한데, 좀 가져다주시면 다크문 축제 티켓이랑 교환할게요.'),
(7891, '제가 세상에서 가장 강한 여자로 부스를 차릴 때 입을 새로운 의상을 만들고 있어요! 지금은 착용할 팔 보호대를 찾고 있는데, 근육이 드러나야 하니까 많이 가리면 안 되지만 색깔도 좀 있어야 하거든요. 혹시 녹색 철제 팔 보호대는 어떠세요? 녹색 철제 팔 보호대를 만들어 주실 수 있나요? 만들어 주시면 다크문 축제 티켓을 잔뜩 드릴게요.'),
(7892, '제가 세상에서 가장 힘센 여자라는 걸 보여주기 위해 관객석에서 물건을 받아서 크고 검은 철퇴로 부숴버릴 거예요! $B$B혹시 저한테 크고 검은 철퇴 만들어 주실 수 있나요?'),
(7893, '$N, 세상에서 가장 강한 여자가 되기 위한 여정에서 저는 전 세계를 여행하며 멀리 떨어진 역도 고수, 근력 전문가, 그리고 고대 서적들로부터 근육 강화 비법을 배웠습니다. 이제 저는 약한 자는 죽고, 경험 없는 자는 불구가 될 수 있는 금지된 운동법들을 알고 있습니다! 이러한 근력과 체력 단련을 위해서는 가장 단단한 맷돌을 이용한 훈련이 필요합니다. $n, 맷돌을 구하거나 만들어서 저에게 가져다주실 수 있나요? 가져다주시면 티켓을 드리겠습니다...'),
(7894, '예브는 동물원 축제(Zoo Bizarre)에 사람들을 경이로움과 즐거움으로 가득 채울 새로운 놀이기구를 개발하고 있습니다! 하지만 많은 노력과 재료가 필요할 겁니다... 특히 구리 변조기가 필요해요. 놀이기구의 기계 장치에 사용할 변조기가 많이 필요합니다. 구리 변조기를 가져다주시면 다크문 축제(Darkmoon Faire) 티켓과 교환하겠습니다.'),
(7895, '제 새 부스는 정말 볼만한 광경이 될 겁니다! 눈으로 보고... 운이 좋은 몇몇 분들은 만져볼 수도 있죠! 벌써부터 손님들이 제 부스에 와서 솜씨를 시험해 보는 동안 윙윙거리는 청동 기계 장치들이 기계적인 황홀경의 노래를 부르는 소리가 들리는 것 같습니다! 아... 이제 제 꿈을 실현하려면 그 기계 장치들이 필요하군요. 제발, $n, 윙윙거리는 청동 기계 장치들을 가져다주세요... 그러면 다크문 축제 티켓을 드리겠습니다!'),
(7896, '드디어 이 부스를 제대로 운영하게 되면 홍보를 해야겠어! 불꽃놀이보다 더 좋은 홍보 방법이 있을까? 음, 어떤 사람들은 적들의 머리가 끓어오르는 가마솥 냄새가 사람들을 끌어모으는 데 더 효과적이라고 생각할지도 모르지만… 여긴 남녀노소 할 것 없이 다 같이 모이는 곳이니까 불꽃놀이가 제격이지! 초록색 불꽃놀이 폭죽을 가져다주면, 자네에게 다크문 축제 티켓을 한 움큼 줄게.'),
(7897, '제가 부스를 열 수 없는 가장 큰 이유는... 모든 게 고장 났기 때문이에요! 이 모든 걸 고치려면 기계 수리 키트가 필요해요! $B$B 혹시 그 키트 좀 가져다주실 수 있나요, $n? 키트랑 다크문 축제 티켓을 교환할게요. 어때요?'),
(7898, '예브 네블기어는 저처럼 미래에 들어설 멋진 놀이기구를 개발하고 있습니다. 네브의 말에 따르면, 이 놀이기구는 너무나 놀라워서 전 세계에서 사람들이 몰려들 것이고, 우리 모두를 엄청나게 부자로 만들어 줄 거라고 합니다! 그는 이 놀이기구를 건설하는 데 토륨 위젯이 필요하다고 하면서, 저에게 그걸 모아달라고 부탁했습니다. 자, 어때요, $n? 토륨 위젯을 어디서 구할 수 있는지 아세요? 혹시 엔지니어시라면 직접 만들 수도 있나요? 아니면 다크문 축제 티켓과 교환하실 생각은 없으세요?'),
(7899, '사람들을 모으는 첫 번째 비결은 바로 장난감이나 장신구로 유혹하는 겁니다! 도와주시겠어요? 경품으로 쓸 작고 복슬복슬한 발바닥이 필요해요. 황무지나 다크쇼어에 사는 고양이들에게서 찾을 수 있을 거예요. 발을 좀 가져다주시면 다크문 축제 티켓을 드릴게요.'),
(7900, '아이들은 장난감을 좋아하죠! 그리고 종족에 상관없이, 모든 아이들은 찢은 곰 가죽으로 만든 털이 복슬복슬한 봉제 인형을 좋아한다는 걸 알게 됐어요! 곰 가죽은 아셴베일이나 힐스브래드에 있는 곰들에게서 얻을 수 있어요. 곰 가죽을 한가득 가져오시면 다크문 축제 티켓을 잔뜩 드릴게요!'),
(7901, '사람들이 무엇을 소중히 여기는지 참 놀랍죠! 예를 들어, 부드럽고 푹신한 꼬리가 달린 나무 막대기를 생각해 보세요. 우리라면 그런 건 별로 가치 없다고 생각할지도 몰라요... 하지만 그 쓸모없는 물건에 "야생 털꼬리" 같은 멋진 이름을 붙이고 예쁜 상자에 담아 놓으면, 사람들은 그걸 귀중하게 여길 거예요. 쓰레기가 보물이 되는 거죠! 데솔레이스와 배드랜드의 늑대들에게서 부드럽고 푹신한 꼬리를 구해다 주면, 다크문 축제 티켓을 줄게요.'),
(7902, '사람의 상상력은 정말 놀라운 것입니다. 가장 작은 언덕도 가장 큰 산처럼 보이게 할 수 있고, 가장 평범한 그림자도 끔찍한 악몽처럼 보이게 할 수 있죠! 저희 다크문 축제에서는 방문객 여러분의 상상력이 활짝 피어나도록 도와드립니다! 하지만 상상력을 더욱 키우기 위해... 때로는 약간의 묘수를 부려야 할 때도 있습니다. 제 놀이기구에 사용할 화려한 깃털이 필요한데요. 아제로스의 위험한 지역에 사는 새들에게서 얻을 수 있습니다. 깃털을 가져다주시면 축제 티켓을 많이 드리겠습니다!'),
(7903, '혹시 한밤중에 모험을 찾아 동굴을 헤매본 적 있어? 그래? 정말? 그럼 높은 곳에서 널 노려보는 박쥐의 섬뜩한 눈을 본 거잖아. 네가 방심하는 틈을 타 피를 빨아먹으려고 말이야! 생각만 해도 무섭지 않아? 당연하지! 박쥐 눈이 무서운 건 두말할 필요 없어! 혹시 나한테 사악한 박쥐 눈 좀 가져다줄래, $n? 내가 뭘 만들고 있는데… 좀 무서운 거 말이야. 동부 역병지대의 박쥐들에게서 얻을 수 있을 거야.'),
(7905, '네, 친구분, 무엇을 도와드릴까요? 사용하시려는 상품권이 있으신가요?'),
(7907, '야수 덱을 완성하셨군요! 축하드립니다!'),
(7926, '네, 친구분, 무엇을 도와드릴까요? 사용하시려는 상품권이 있으신가요?'),
(7927, '포털 카드 덱을 완성하셨군요! 축하드립니다!'),
(7928, '워로드 덱을 완성하셨군요! 축하드립니다!'),
(7929, '엘리멘탈 덱을 완성하셨군요! 축하드립니다!'),
(7930, '어서 오세요! 다크문 축제 티켓을 사용하고 싶으시다면 말씀해 주세요! 다양한 종류의 티켓으로 멋지고 환상적인 상품을 교환할 수 있습니다. 망설이지 말고 지금 바로 신청해 보세요!'),
(7931, '어서 오세요! 다크문 축제 티켓을 사용하고 싶으시다면 말씀해 주세요! 다양한 종류의 티켓으로 멋지고 환상적인 상품을 교환할 수 있습니다. 망설이지 말고 지금 바로 신청해 보세요!'),
(7932, '어서 오세요! 다크문 축제 티켓을 사용하고 싶으시다면 말씀해 주세요! 다양한 종류의 티켓으로 멋지고 환상적인 상품을 교환할 수 있습니다. 망설이지 말고 지금 바로 신청해 보세요!'),
(7933, '어서 오세요! 다크문 축제 티켓을 사용하고 싶으시다면 말씀해 주세요! 다양한 종류의 티켓으로 멋지고 환상적인 상품을 교환할 수 있습니다. 망설이지 말고 지금 바로 신청해 보세요!'),
(7934, '어서 오세요! 다크문 축제 티켓을 사용하고 싶으시다면 말씀해 주세요! 다양한 종류의 티켓으로 멋지고 환상적인 상품을 교환할 수 있습니다. 망설이지 말고 지금 바로 신청해 보세요!'),
(7935, '어서 오세요! 다크문 축제 티켓을 사용하고 싶으시다면 말씀해 주세요! 다양한 종류의 티켓으로 멋지고 환상적인 상품을 교환할 수 있습니다. 망설이지 말고 지금 바로 신청해 보세요!'),
(7936, '어서 오세요! 다크문 축제 티켓을 사용하고 싶으시다면 말씀해 주세요! 다양한 종류의 티켓으로 멋지고 환상적인 상품을 교환할 수 있습니다. 망설이지 말고 지금 바로 신청해 보세요!'),
(7937, '이 건초더미는 당신이 꿈에서 본 것과 똑같아 보이네요.'),
(7938, '이 상자는 당신이 본 환상 속의 상자와 똑같아 보이네요...'),
(7939, '$N, 그동안 도와주셔서 정말 감사합니다. 얼마나 감사한지 말로 다 표현할 수 없어요!$B$B비록 지금은 많이 필요하지는 않지만... 혹시 더 단단한 맷돌을 가져다주신다면, 다크문 축제 티켓을 더 드릴게요.'),
(7940, '어서 오세요! 다크문 축제 티켓을 사용하고 싶으시다면 말씀해 주세요! 다양한 종류의 티켓으로 멋지고 환상적인 상품을 교환할 수 있습니다. 망설이지 말고 지금 바로 신청해 보세요!'),
(7941, '$N님, 도와주셔서 정말 감사합니다. 덕분에 물자는 충분히 확보했지만, 혹시 갑옷 세트를 더 가져다주실 수 있다면 다크문 축제 티켓과 기꺼이 교환하겠습니다.'),
(7942, '$N, 당신은 지치지 않고 제게 물품을 가져다주셔서 정말 감사했습니다!$B$B비록 토륨 위젯이 예전만큼 많이 필요하지는 않지만, 언제든 가져다주시면 기꺼이 다크문 축제 티켓으로 교환해 드리겠습니다.'),
(7943, '$N, 내가 디자인 중인 이 어트랙션은 그놈레간이 함락된 이후로 가장 무시무시한 이벤트가 될 거야! 그건 대부분 네가 가져다준 온갖 장식품 덕분이지. 정말 정말 고마워!$B$BI, 더 이상 필요한 건 없지만... 동부 역병지대의 박쥐들에게서 사악한 박쥐 눈을 더 가져다주면... 다크문 축제 티켓을 더 줄지도 몰라.'),
(7944, '이 상자는 당신이 본 환상 속의 상자와 똑같아 보이네요...'),
(7945, '이 나무 그루터기는 당신이 본 환상 속의 그루터기와 똑같아 보이네요.'),
(7946, '주브주브가 더 이상 길을 잃지 않아서 너무 기뻐요. 주브주브는 다크 아이언 에일을 너무 좋아해서 제가 다 떨어졌을 때… 더 찾으러 도망쳐 버렸거든요! 이제 주브주브가 돌아왔으니, 에일을 최대한 많이 구하고 싶어요! 다시는 도망가지 않게 해야 하니까요! 혹시 다크 아이언 에일 있으세요? 있다면 주브주브의 개구리 알 하나랑 머그잔 하나 교환할게요…'),
(7981, '어서 오세요! 다크문 축제 티켓을 사용하고 싶으시다면 말씀해 주세요! 다양한 종류의 티켓으로 멋지고 환상적인 상품을 교환할 수 있습니다. 망설이지 말고 지금 바로 신청해 보세요!'),
(8042, '건강하게 잘 지내시는 모습을 보니 기쁩니다, $n. 당신이 치르신 영광스러운 전투들은 이 행성의 모든 생명에 영향을 미칩니다. 하카르는 줄구룹의 경계를 절대 벗어나서는 안 됩니다. 그가 엄청난 굶주림에 사로잡히면 세상은 무너질 것입니다.$b$b당신의 부적을 제게 주십시오. 제가 그 힘을 증폭시켜 드리겠습니다. 무감바의 힘으로 적들을 응징하십시오!'),
(8043, '스승님, 돌아오셨군요! 몰토르가 당신의 업적을 왕께 전했습니다. 당신의 이름은 남해까지 알려져 있습니다. 언젠가 당신은 전설적인 인물이 되어 역사에 길이 남을 이야기가 될 것입니다. 부디 당신의 부적을 제게 주십시오. 제가 다시 한번 그 힘을 증폭시킬 수 있도록 말입니다.'),
(8044, '라스타칸 왕께서 안부를 전하셨습니다, 스승님. 잔달라 부족 밖의 자에게는 이런 영광이 주어진 적이 없습니다.<진로크가 고개를 숙인다.> 부적을 내게 주십시오. 제가 다시 한번 강화해 드리겠습니다. 무감바의 분노는 이제 당신의 영혼과 깊이 연결되어 있음을 알아두십시오.'),
(8046, '$c, 제가 너무 성급하게 판단했던 것 같습니다. 당신의 이 빛에 대한 맹목적인 믿음이 결국에는 어느 정도 가치가 있는 것 같군요.$b$b당신의 브랜드를 알려주세요. 제가 그 힘을 증폭시켜 드리겠습니다.'),
(8047, '솔직히 말씀드리자면, 당신이 이 일을 끝까지 해낼 의지가 있다고는 생각하지 못했습니다, $c. 이제 잔달라는 당신을 없어서는 안 될 소중한 동맹으로 여기고 있습니다. 정말 훌륭하십니다.$b$b당신의 브랜드를 제게 주십시오. 그러면 제가 다시 한번 그 힘을 증폭시켜 드리겠습니다.'),
(8048, '왕께서 당신의 존재를 인정하셨습니다, $c. 당신은 라스타칸에게 잔달라의 진정한 동맹으로 인정받은 최초의 존재입니다.$b$b당신의 노력에 대한 보상은 매우 클 것입니다. 당신의 낙인을 제시하십시오. 그러면 제가 최종 증폭을 적용해 드리겠습니다.'),
(8050, '여사제여, 구루바시와의 전투에 대한 이야기가 바람에 실려 전해지고 있습니다. 심지어 왕족들조차 당신의 업적에 대해 이야기하기 시작했으며, 라스타칸 왕께서 당신의 이름을 직접 언급하셨다는 소문까지 돌고 있습니다. 이제 눈에 힘을 불어넣을 때가 왔습니다. 부적을 제게 주시오. 제가 그 의식을 행하겠습니다.'),
(8051, '어서 오세요, $c님. 줄다자르의 눈은 강력한 에너지로 가득 차 있습니다. 이제 다음 단계로 나아갈 준비가 되셨습니다. 부적을 제게 주시오. 제가 힘을 불어넣어 드리겠습니다.'),
(8052, '당신 같은 사람이 만 명만 더 있었더라면, 하카르의 군대는 눈 깜짝할 사이에 뿔뿔이 흩어졌을 텐데.<알타빔은 한숨을 쉬었다.>아, 이제 그 눈이 제 잠재력을 완전히 발휘할 때가 되었군. 내게 넘겨주시오.'),
(8053, '돌아왔나? 힘의 정점들을 가져왔나? 내 시간을 낭비하는 건가? 아니길 바라네, 이교도여.'),
(8054, '당신의 존재가 승리를 의미합니까? 당신은 최고의 기량을 갖추고 있습니까? 당신은 적들의 잔해로 뒤덮여 있습니까?'),
(8055, '패러곤들을 가지고 있습니까? 그 안에 마법의 힘이 깃들어 있습니다. 우리는 그것들이 필요합니다. 당신이 우리를 도와줄 것입니다.'),
(8056, '줄구룹에게서 필요한 힘의 정수를 얻었나요? 이 손목 보호대는 그만한 노력을 들일 가치가 충분히 있어요!'),
(8057, '줄구룹에서 얻는 힘의 정수(Paragons of Power)는 다 모았어? 이 팔찌 진짜 얻을 가치가 있어, $n. 내 말 믿어!'),
(8058, '힘의 정점들을 데려왔는가? 잔달라의 이름으로 복수를 이루었는가?'),
(8059, '힘의 정점들을 데리고 돌아왔는가? 하카르의 사악한 하수인들을 물리침으로써, 너는 우리에게 너의 실력을 증명할 뿐만 아니라, 악마의 길을 배우려는 의지도 보여줄 것이다.'),
(8060, '$n - 벌써 돌아오셨군요? 제가 필요한 힘의 정점들을 구해오셨나요?'),
(8061, '줄구룹에서 돌아오셨습니까? 하카르의 하수인들에게서 힘의 정수를 되찾는 데 성공하셨습니까?'),
(8062, '줄구룹에서 힘의 정수를 손에 넣으려는 자들을 사냥하라, $n. 그들이 바로 네 사냥감이다. 그들은 우리 둘 다 반드시 가져야 할 것을 손에 쥐고 있다.'),
(8063, '줄구룹 내부의 광기를 찾아내어 네 광기로 덮어버려라, $n! 그렇게 하면 성공이고, 성공은 곧 보상을 의미한다! 피의 신이 다시는 절대적인 권세를 누리지 못하게 하라!'),
(8064, '줄구룹에게서 필요한 힘의 정수를 얻으셨나요? 정수를 가지고 계시면 예언자의 허리띠를 드리겠습니다.'),
(8065, '줄구룹에게서 필요한 힘의 정수를 모두 얻었나요? 예언자의 튜닉은 그만한 노력을 들일 가치가 충분히 있습니다.'),
(8066, '줄구룹에서 하카르의 미친 하수인들을 공격하세요. 그들이 바로 힘의 정수 $n을 손에 넣은 자들입니다. 포식자의 자리를 열망하는 자로서, 그들과 부족에게 당신의 성공을 증명하십시오.'),
(8067, '$n, 줄구룹 공격은 성공적이었나? 내가 원하는 것을 가져오고 부족에게 네 능력을 완전히 증명했을 때에만 잔달라에서 누구에게도 뒤지지 않는 칭호를 얻을 수 있을 것이다.'),
(8068, '줄구룹 원정은 어떠셨습니까? 환영 마법으로 적들을 미치게 만드셨습니까? 환영 마법이든 아니든, 그들의 죽음과 그들에게서 빼앗은 힘의 정수는 하카르의 부상을 저지하는 데 도움이 될 것입니다.'),
(8069, '우리가 필요로 하는 힘의 정점들을 데리고 돌아왔나? 쉽지는 않겠지만… 나는 오래전부터 외부인이 하카르와의 싸움에서 우리를 도울 것이라고 예견해 왔다. 바로 당신이어야 한다!'),
(8070, '힘의 정점들... 당신은 그것들을 가지고 있습니까? 그것들을 손에 넣어야만 비로소 그 안에 잠재된 힘을 활용할 수 있을 겁니다. 피의 신의 하수인들에게 역습을 가할 수 있게 될 테니까요...'),
(8071, '줄구룹의 힘의 정수를 가지고 계신가요?'),
(8072, '돌아왔군. 내가 필요한 힘의 정점들을 가져왔나?$B$B균열한 카르박살의 전설은 오늘날 우리에게 아무리 큰 위협이라 할지라도 극복할 수 없는 적은 없다는 사실을 일깨워줍니다. 혼돈은 모두를 무릎 꿇게 만들겠지만… 어쩌면 혼돈의 가장 비혼돈적인 요소조차도 그럴 수 있다는 것은 확실합니다.'),
(8073, '섬에 다시 오신 것을 환영합니다, $n... 권력의 정점들을 이끌고 의기양양하게 돌아오셨습니까?'),
(8074, '힘의 정수들이 필요해. 줄구룹의 악과 싸울 때 그들의 힘을 빌려야지. 혹시 가지고 있어?'),
(8075, '힘의 정점은 마법의 힘의 핵심 원천입니다. 예언자의 갑옷을 만드는 데 필요한 바로 그 힘이죠. 필요한 것을 가져다주시면, 잔달라의 예언자라면 누구나 탐낼 만한 최고의 의복을 나눠드릴 수 있습니다.'),
(8076, '줄구룹에게서 힘의 정수를 되찾았습니까? 우리는 이 아이템에 담긴 잠재적인 힘을 빼앗아 우리 것으로 만들겠지만, 당신이 성공한다면 당신만의 힘의 보상을 주겠습니다...'),
(8077, '권력의 화신들... 당신이 그들을 데리고 돌아왔습니까? 우리가 그들을 손에 넣어야만 악마적인 힘의 궁극적인 상징을 당신과 공유할 수 있습니다, $n.'),
(8078, '힘의 화신들을 데려왔는가? 부족의 적들을 쓰러뜨렸는가? 하카르는 반드시 복수자의 분노를 경험해야 한다!'),
(8079, '당신의 존재가 승리를 의미하는가? 당신은 권력의 정점에 있는가? 오늘 당신이 행한 복수에 대해 말해 보아라!'),
(8080, '혹시 자원 상자 $n 가지고 계신가요? 아라토르 연맹은 그 상자 없이는 제대로 된 전투를 치를 수 없거든요...'),
(8081, '$N, 아라토르 연맹에서 당신에게 아라시 분지에 다시 진입하여 자원 상자를 더 확보해 제게 가져오라는 임무를 맡겼습니다.'),
(8102, '$c, 돌아온 걸 환영한다. 조약돌이 꽤 많이 사용된 게 눈에 선하군. 우리의 적들 중 다수가 자네의 초자연적인 능력에 쓰러졌지. 그들의 고통은 컸을 테니까. 이제 내가 조약돌의 힘을 강화할 때가 됐군. 내게 주시오.'),
(8103, '하카리족은 당신을 두려워합니다. 그들은 얼굴 없는 신만이 저지를 수 있다고 믿는 끔찍한 일들에 대해 이야기합니다. 당신은 카자로의 힘으로 그들을 불태웠습니다. 이제 그들은 두 곳에서 공포를 느낍니다. 이제 조약돌을 더욱 강화할 때입니다. 부적을 제게 주십시오.'),
(8104, '부적을 내게 줘, $n. 내가 너에게 보여줄 게 있어.'),
(8107, '잔달라 트롤 사이에서 명예는 노력으로 얻는 것이다. 명예에는 보상이 따른다. 우정, 동맹… 부적을 내게 넘겨주어 그 힘을 강화시켜 주도록 하라.'),
(8108, '준비됐습니다, $c. 다시 한번 당신의 부적을 강화해 드리겠습니다. 하카르와 그의 부하들을 계속해서 섬멸해 주시기만 하면 됩니다.$b$b부적을 제게 주십시오.'),
(8109, '네 안의 악마들을 불러내라, $c. 케잔의 오염된 기운을 흠뻑 적시게 하라. 전장에서 그들을 지휘하라! 적을 섬멸하라!$b$b그래... 이제 케잔의 오염에 최종적인 강화를 가할 때가 왔다. 부적을 내게 넘겨주시오.'),
(8111, '야, 친구! 다시 만나서 반갑다. 부족 사람들이 네가 하카리들을 처치한 이야기를 하고 있더군. 몰토르가 네 부적에 마법을 더하라고 명령했어. 여기 주면 메이위키가 더 강력하게 만들어 줄게.'),
(8112, '그 부적은 어때, 친구? 잎사귀에 마법과 기운을 좀 더 불어넣어 줘야 할 것 같군. 시들어가는 잎에 생기를 불어넣어야겠어. 여기로 가져와 봐. 메이위키가 바로 손봐줄게.'),
(8113, '$n! 정말 오랜만이군. 라스타칸 왕께서 직접 내게 네 부적에 마지막 마법을 더하라고 명하셨다는 거 알아? 진짜야, 친구! 내가 직접 보지 않았더라면 믿지 않았을 거야. 이리 줘 봐.'),
(8117, '좋은 소식이야, $n. 몰토르가 요즘 자네를 칭찬하고 다니더군. 자네가 잔달라의 진정한 영웅으로 변모하고 있다고 하더군.$b$b그리고 메이위키에게 자네의 오브를 더 잘 닦으라고 했어! 여기로 오브를 가져다 주면 메이위키가 시야를 더 밝게 해 줄 거야.'),
(8118, '샤몬! 메이위키가 농담하는 거야!$b$b<메이위키가 웃는다.>$b$b그래서, 줄구룹에서 우리 적들을 상대로 정령과 원소를 사용했군? 정령이여 찬양받으소서!$b$b메이위키가 네 오브를 밝게 해 줄게. 이리 줘 봐, $n.'),
(8119, '<메이위키가 당신의 부적을 가리킵니다.>$b$b이것 좀 봐, $n! 살아 움직이는 것 같아. 영혼들이 구슬 주위를 춤추고 있어.$b$b메이위키에게 줘서 마지막으로 조정을 하도록 해.'),
(8124, '디파일러스의 $N은 당신에게 아라티 분지에 다시 진입하여 자원 상자를 더 확보하고 저에게 가져오라는 임무를 맡겼습니다.'),
(8142, '인상적이군, $n. 자네는 내가 수년 동안 다른 누구에게서도 느껴보지 못한 살육의 재능을 지녔어. 몰토르조차도 자네가 잔달라를 위해 한 일을 알고 있지. 이제 자네의 부적을 더욱 강화할 때가 됐군. 내게 주시오.'),
(8143, '자네가 하카리족에게 수많은 죽음을 안겨준 것 같군, $n. 자네에게는 그들의 악취가 배어 있다.$b$b그림자 부적이 그 학살에 일조했겠지? 그 부적을 내게 넘겨주오. 내가 그 힘을 강화시켜 주겠소.'),
(8144, '그것은 성장하기를 갈망한다, $n. 이 부적은 네가 행한 모든 것을 흡수했다. 줄구룹에 널린 수천 구의 트롤 시체가 그 힘을 키워주었다. 내게 넘겨주면 내가 마지막 강화를 해 주겠다.'),
(8146, '여기서도 당신의 포격 소리가 적들을 휩쓸고 지나가는 소리가 들립니다. 그들의 고통스러운 비명 소리가 메아리칩니다. 당신은 잔달라의 트롤들 사이에서 꽤 명성을 떨쳤군요. 당신이 해주신 모든 일에 감사드립니다. 부적을 제게 주십시오. 제가 한 번 더 엮어보겠습니다.'),
(8147, '아, $n, 다시 당신 냄새를 맡으니 반갑군요.$b$b<팔티르가 씩 웃는다.>$b$b제 유머 감각은 좀 심할 수 있으니 양해 부탁드립니다.$b$b당신이 우리 적들에게 큰 고통을 안겨준 것 같군요. 하카르의 군대가 분노에 차 당신의 이름을 부르짖고 있습니다. 아주 훌륭하군요.$b$b당신의 부적에 새로운 문양이 새겨졌습니다. 제게 주십시오.'),
(8148, '몰토르가 라스타칸 왕의 소식을 전합니다. 왕궁에서는 자네가 하카리 군대를 궤멸시킨 공적에 깊은 감명을 받았네. 자네의 부적에 마지막 장식을 수여하기로 했네. 내게 건네주시오.'),
(8149, '우서의 무덤으로 가서 공물을 바치셨습니까? 경험이 부족한 모험가들에게는 위험한 여정일 수 있습니다. 상대적으로 안전한 길은 힐스브래드를 가로질러 역병지대로 흐르는 강에서 북쪽으로 가는 것입니다. 그 강은 슬픔의 언덕 옆에 있는 호수에서 발원합니다. 언덕을 따라 서쪽으로 이동하되, 바로 옆에 있는 무덤, 즉 스컬지가 들끓는 무덤은 피하십시오.'),
(8150, '그롬의 기념비까지 가서 그의 공물을 바치셨습니까? 그곳은 여전히 불타는 군단의 오염이 남아 있는 기념비입니다. 모험 경험이 부족한 분이라면 기념비에 접근할 때 각별히 주의하십시오.'),
(8153, '뿔을 찾으셨나요?'),
(8154, '혹시 자원 상자 $n 가지고 계신가요? 아라토르 연맹은 그 상자 없이는 제대로 된 전투를 치를 수 없거든요...'),
(8155, '혹시 자원 상자 $n 가지고 계신가요? 아라토르 연맹은 그 상자 없이는 제대로 된 전투를 치를 수 없거든요...'),
(8156, '혹시 자원 상자 $n 가지고 계신가요? 아라토르 연맹은 그 상자 없이는 제대로 된 전투를 치를 수 없거든요...'),
(8157, '$N, 아라토르 연맹에서 당신에게 아라시 분지에 다시 진입하여 자원 상자를 더 확보해 제게 가져오라는 임무를 맡겼습니다.'),
(8158, '$N, 아라토르 연맹에서 당신에게 아라시 분지에 다시 진입하여 자원 상자를 더 확보해 제게 가져오라는 임무를 맡겼습니다.'),
(8159, '$N, 아라토르 연맹에서 당신에게 아라시 분지에 다시 진입하여 자원 상자를 더 확보해 제게 가져오라는 임무를 맡겼습니다.'),
(8163, '디파일러스의 $N은 당신에게 아라티 분지에 다시 진입하여 자원 상자를 더 확보하고 저에게 가져오라는 임무를 맡겼습니다.'),
(8164, '디파일러스의 $N은 당신에게 아라티 분지에 다시 진입하여 자원 상자를 더 확보하고 저에게 가져오라는 임무를 맡겼습니다.'),
(8165, '디파일러스의 $N은 당신에게 아라티 분지에 다시 진입하여 자원 상자를 더 확보하고 저에게 가져오라는 임무를 맡겼습니다.'),
(8183, '$n, 사악한 영혼의 악취가 당신을 감싸고 있습니다. 당신은 영혼 파괴자의 저주를 받은 것입니까?'),
(8184, '이것들을 가져오면 강력한 마법을 걸어주겠다!'),
(8185, '이것들을 가져오면 강력한 마법을 걸어주겠다!'),
(8186, '이것들을 가져오면 강력한 마법을 걸어주겠다!'),
(8187, '이것들을 가져오면 강력한 마법을 걸어주겠다!'),
(8188, '이것들을 가져오면 강력한 마법을 걸어주겠다!'),
(8189, '이것들을 가져오면 강력한 마법을 걸어주겠다!'),
(8190, '이것들을 가져오면 강력한 마법을 걸어주겠다!'),
(8191, '이것들을 가져오면 강력한 마법을 걸어주겠다!'),
(8192, '이것들을 가져오면 강력한 마법을 걸어주겠다!'),
(8193, '오늘 오후 2시부터 4시 사이에 최고의 낚시꾼을 가리는 대회가 열립니다! 스트랭글쏜 해안을 따라 서식하는 맛있는 물고기 떼에서 잡은 맛있는 물고기 40마리를 누구보다 먼저 가져오는 사람이 바로 최고의 낚시꾼으로 선정됩니다!$b$b만약 40마리를 먼저 가져오지 못하더라도, 제 제자가 가져오는 맛있는 물고기 5마리마다 상금을 드릴 겁니다.$b$b아, 그리고 서두르세요! 맛있는 물고기는 금방 상하니까요!'),
(8194, '이미 대회 우승자가 정해졌지만, 그래도 저는 당신의 테이스티피쉬를 적당한 가격에 사겠습니다. 어떻게 생각하세요!'),
(8195, '저는 부족의 동전으로 알려진 힘의 정수를 찾고 있습니다. 이 동전들은 줄구룹의 다양한 주민들이 사용하는 화폐이며, 각각 미묘하지만 강력한 마법이 깃들어 있습니다. 총 아홉 종류가 있습니다. 혹시 여분이 있으시면 저희 명예 토큰 하나와 세 개 세트를 교환하겠습니다. 이 토큰은 상인 린워쇼에게 사용할 수 있으며, 그는 우리 영웅들에게 특별한 아이템을 제공합니다.'),
(8196, '남태평양의 여러 섬에서 자라는 망고는 매우 강력한 효능을 지니고 있습니다. 망고 하나만 먹어도 몸과 마음이 상쾌해집니다. 아직 드셔보지 않으셨다면 정말 손해 보시는 겁니다! 저희 섬에는 망고가 충분히 있어서 잔달라 명예 토큰으로 몇 개 드릴 수 있습니다. 토큰을 얻는 방법을 알고 싶으시면 빈착사에게 문의하세요. 그럼 본론으로 들어가죠!'),
(8201, '$n, 머리들을 모아놨나요? 하카르가 더 강해지는 걸 막아야 해요!'),
(8221, '윙윙* *딸깍* 저는 피쉬마스터 블루길의 도감 등록을 위해 희귀 물고기를 찾고 있습니다. 키퍼 엔젤피시를 가져다주시면 이 귀한 보상을 드리겠습니다. 짹짹* *윙윙*'),
(8222, '축제에서 일하는 동안 손님들에 대해 많은 것을 배웠습니다. 그중 하나를 알려드리자면, 손님들은 빛나는 물건을 정말 좋아합니다! 무엇이든 상관없어요. 부러진 의자 다리를 빛나게 만들어도 아이들은 멀리서도 달려와서 하나쯤 사갈 겁니다! 자, $n, 빛나는 전갈 피가 필요해요. 실리투스나 황폐한 땅, 또는 불타는 초원의 전갈에게서 구할 수 있습니다.'),
(8223, '그 전갈 피, 효과 정말 좋네요, $n! 반짝임이 조금 더해지니 평범한 쓰레기가 값진 장신구로 변신하는 게 정말 놀랍습니다. 손님들도 아주 좋아하고, 결국 중요한 건 사랑이잖아요, 안 그래요? $n, 정말 큰 도움이 됐어요. 지금 당장 빛나는 전갈 피가 많이 필요한 건 아니지만, 더 가져다주시면 티켓 몇 장 드릴게요.'),
(8224, '윙윙* *딸깍* 저는 피쉬마스터 블루길의 도감 등록을 위해 희귀 물고기를 찾고 있습니다. 데지안 퀸피쉬를 가져오시면 이 귀한 보상을 드리겠습니다. 짹짹* *윙윙*'),
(8225, '윙윙윙* *딸깍* 저는 피쉬마스터 블루길의 도감 등록을 위해 희귀한 물고기를 찾고 있습니다. 브라우넬의 블루 스트라이프 레이서를 가져오시면 이 귀한 보상을 드리겠습니다. 짹짹윙윙'),
(8227, '안녕, 꼬마야. 낚시하러 왔니?'),
(8231, '성공을 거두셨나요?'),
(8232, '$n, 당신의 눈에서 지혜를 봅니다. 사냥은 끝났습니까?'),
(8234, '저 아세요?'),
(8235, '내 작업을 계속하기에 충분한 조각들을 찾으셨나요?'),
(8236, '대마법사 자일렘이 보낸 가방은 이미 도착했는데, 열쇠는 찾았나요?'),
(8238, '저는 부족의 동전으로 알려진 힘의 정수를 찾고 있습니다. 이 동전들은 줄구룹의 다양한 주민들이 사용하는 화폐이며, 각각 미묘하지만 강력한 마법이 깃들어 있습니다. 총 아홉 종류가 있습니다. 혹시 여분이 있으시면 저희 명예 토큰 하나와 세 개 세트를 교환하겠습니다. 이 토큰은 상인 린워쇼에게 사용할 수 있으며, 그는 우리 영웅들에게 특별한 아이템을 제공합니다.'),
(8239, '저는 부족의 동전으로 알려진 힘의 정수를 찾고 있습니다. 이 동전들은 줄구룹의 다양한 주민들이 사용하는 화폐이며, 각각 미묘하지만 강력한 마법이 깃들어 있습니다. 총 아홉 종류가 있습니다. 혹시 여분이 있으시면 저희 명예 토큰 하나와 세 개 세트를 교환하겠습니다. 이 토큰은 상인 린워쇼에게 사용할 수 있으며, 그는 우리 영웅들에게 특별한 아이템을 제공합니다.'),
(8240, '잔자 제단의 보석을 파괴했습니까? 그렇게 하면 잔자의 축복을 두 배로 받게 될 것입니다!'),
(8241, '쓸데없는 소리로 내 소중한 시간을 더 이상 낭비하지 마, $r. 이제 줄어드는 화염 플럭스 공급량을 보충하는 데 집중해야 해.$B$B내가 자네에게 필요한 건 다음과 같네.$B$B*인센도사우루스 비늘$B$B*철괴$B$B*석탄$B$B 자네가 줄 수 있는 건 뭐든지 받겠네!$B$B형제단과 사이좋게 지내고 싶다면 빨리 해내야 할 거야.'),
(8242, '쓸데없는 소리로 내 소중한 시간을 더 이상 낭비하지 마, $r. 이제 줄어드는 화염 플럭스 공급량을 보충하는 데 집중해야 해.$B$B내가 자네에게 필요한 건 다음과 같네.$B$B*인센도사우루스 비늘$B$B*두꺼운 가죽$B$B*석탄$B$B 자네가 줄 수 있는 건 뭐든지 받겠네!$B$B형제단과 사이좋게 지내고 싶다면 빨리 해내야 할 거야.'),
(8243, '부족 내에서 당신의 지위가 높아짐에 따라, 저희가 보유한 더욱 강력한 술들을 접할 수 있게 되었습니다. 보십시오... 이 술들은 잔자의 축복을 받은, 모든 모험가에게 어울리는 강력한 술입니다! 제가 제공하는 세 가지 술 중에서 하나를 선택하실 수 있습니다. 그 대가로 잔달라 명예 토큰 하나를 주셔야 합니다. 참고로, 한 번에 하나의 토큰 효과만 당신의 영혼에 미칠 수 있습니다. 거래할 준비가 되면 알려주십시오!'),
(8246, '$n - 잔달라에서 당신처럼 고귀한 분께 아주 특별한 것을 준비했습니다. 남태평양에 있는 저희 고향에서 직접 가져온... 잔달라의 인장입니다! 이 인장은 당신이 소유한 모든 어깨 장비를 강화하는 데 사용됩니다. 힘, 기개, 또는 평온을 원하신다면, 제가 도와드리겠습니다!$B$BI는 당신이 선택하신 인장 하나를 드리는 대가로 잔달라 명예 토큰 15개를 요구합니다. 토큰이 준비되어 있다면, 거래를 진행할 준비가 되었습니다!'),
(8249, '내 도적들은 자물쇠 따기 기술을 연마해야 하고, 나는 적당한 난이도의 자물쇠가 필요해. 잔이 만들어주는 자물쇠는 초보 도적들조차 풀기 힘들 정도거든. 좋아, 그럼 무거운 잡동사니 상자 5개를 가져오면 도적들이 쓰는 최고의 투척용 칼을 몇 자루 주겠어. 상자를 열어서 뒤져봐도 되지만, 동전은 몇 개 정도 남겨둬야 해... 훈련 중인 도적이라도 동기부여가 필요하거든.'),
(8251, '먼지가 있나요?'),
(8252, '악의섬망 사이렌들은 놀라울 정도로 뛰어난 마법사들이군. 자네만큼은 아니겠지, 안 그래?'),
(8253, '내 오랜 숙적을 처치했는가?'),
(8255, '돌아왔군요. 성공했습니까?'),
(8256, '우리는 신의 피를 빨리 구해야 합니다. 찾았습니까?'),
(8257, '모르파즈의 피를 갖고 있습니까?'),
(8258, '시간이 촉박합니다, $n - 죽음의 기사 다크리버의 위협을 막는 데 성공하셨습니까?'),
(8277, '샘플 채취 다 하셨어요? 노글을 언제라도 잃어버릴 수 있어요!'),
(8278, '노글을 구할 마지막 기회야! 서두르세요!'),
(8279, '누구세요? 아, 당신이시군요! 사전 챕터를 전부 찾으셨나요?'),
(8280, '준설선 파업은 심각한 위협이므로 신속하게 처리해야 합니다!'),
(8281, '준설선 파쇄기는 심각한 위협이므로 즉시 처리해야 합니다!'),
(8282, '아직 내 가방을 못 찾았다고? 그래도 다행인 줄 알아야지. 적어도 독은 제거됐으니까.'),
(8283, '증거로 그 생물의 집게발이 필요합니다. 집게발이 없으면 보상은 없습니다.'),
(8284, '파괴된 캠프는 여기에서 북서쪽으로 떨어져 있습니다. 모든 조각을 다 모으면 다시 오세요.'),
(8285, '너! 어떻게 날 찾았지? 너 누구야? 미행당한 건 아니지? 말해 봐!'),
(8286, '아나크로노스가 돌아왔는가?'),
(8287, '당신이 내게 가져온 것은 무엇입니까, $n?'),
(8288, '당신이 얻어야 할 것은 노즈도르무의 후손들의 호의입니다.'),
(8294, '적의 피는 영광의 표식이다. 너에게도 그런 표식이 있느냐?'),
(8297, '혹시 자원 상자 $n 가지고 계신가요? 아라토르 연맹은 그 상자 없이는 제대로 된 전투를 치를 수 없거든요...'),
(8298, '$N, 아라토르 연맹에서 당신에게 아라시 분지에 다시 진입하여 자원 상자를 더 확보해 제게 가져오라는 임무를 맡겼습니다.'),
(8300, '디파일러스의 $N은 당신에게 아라티 분지에 다시 진입하여 자원 상자를 더 확보하고 저에게 가져오라는 임무를 맡겼습니다.'),
(8301, '그들이 필멸의 종족들을 불신하게 된 데에는 오랜 역사가 얽혀 있습니다. 하지만 안타깝게도, 그러한 이야기는 적절한 시기가 되면 드워프들이 직접 들려주는 것이 더 나을 것입니다.'),
(8302, '어쩌면 언젠가 세나리온 요새 전체가 당신의 지휘 아래 움직이게 될지도 모릅니다.'),
(8304, '시간 낭비하지 마세요, $n!'),
(8306, '나탈리아?'),
(8308, '이런.'),
(8309, '만약 그곳에서 정신 나간 나이트 엘프 아가씨를 발견한다면, 꼭 그녀의 알몸을 걷어차 버려.'),
(8310, '얘야, 가서 원숭이랑 놀아. 난 이럴 시간 없어.'),
(8311, '할로윈 사탕 얻으러 다니는 거 다 끝냈어? 나도 가고 싶은데, 데스윙 마주치고 싶지 않아서.'),
(8312, '할로윈 사탕 얻으러 다니는 거 다 끝냈어? 사감 선생님이 한 곳만 골라서 가도 된다고 하셨는데, 여기는 할 일이 많네.'),
(8313, '레시피를 배우셨나요? 혼자만 알고 있지는 않겠죠?'),
(8314, '어머나! $n, 뭘 들고 있는 거야?'),
(8315, '기회가 왔을 때 반드시 잡아야 합니다!'),
(8317, '만두는 어떻게 되어가고 있나요?'),
(8318, '나한테 문자 메시지 좀 가져다줬어?'),
(8319, '계속 문자를 보내줘. 곧 황혼의 망치단을 실리투스에서 몰아낼 수 있을 거야.'),
(8320, '사막으로 들어가 황혼의 지질 군주들($n)을 찾아 처치한 후 내게 돌아오십시오.'),
(8321, '$n, 당신은 아직 바이럴 더 바일을 물리쳤습니까? 그의 인장 반지를 가지고 있습니까?'),
(8322, '맥주통에는 에일이 가득 차 있다.'),
(8323, '혹시 암호화된 글을 찾으셨나요? 이번 달 True Believer를 읽어보고 싶네요.'),
(8324, '암호화된 텍스트를 더 찾았나요? 많이 가져오세요. 해독 작업에 시간이 좀 걸립니다.'),
(8325, '이번 임무는 우리 사회를 재건하는 출발점이 될 것입니다. 고향을 지켜낼 수 있어야 그 이상의 일을 해낼 수 있습니다.'),
(8326, '그대에게 그 동물들을 처치하라고는 했지만 저라고 내키는 일이었겠습니까? 과거에 우리는 숲의 생명체들과 조화를 이루며 살았지만 지금은 상황이 다릅니다. 모든 신도레이의 첫 번째 과제는 바로 살아남는 것이라는 점을 명심하십시오.'),
(8328, '아, $n님, 이 섬에 새로 오신 마법사 중 한 분이시죠? 잘 찾아오셨습니다. 마법의 달인이 되고 싶으시다면 제가 도와드릴 수 있습니다. 단, 훈련 비용을 감당할 수 있고 제가 가르치는 수업에 집중할 수 있어야겠죠. 자, 시작해 볼까요!'),
(8330, '내 소지품을 찾았습니까? 선스트라이더 섬에 대한 우리의 지배권을 되찾고 나면, 제 임무에 그것들이 필요할 겁니다. 하지만 지금은 태양샘을 지켜야 합니다... 아니, 태양샘의 남은 부분을 지켜야 합니다.'),
(8332, '$n님, 파편과 문장을 가지고 계신가요? 황혼 숭배자의 지위 메달을 만들려면 그것들이 필요합니다.'),
(8333, '황혼 숭배자 신분 메달이 하나 더 필요하시다면 기꺼이 만들어 드리겠습니다. 하지만 그러려면 찬란한 조각 하나와 심연의 문장이 몇 개 더 필요합니다...'),
(8334, '생존에 대해, 그리고 생존에 따르는 대가에 대해 나중에 배우는 것보다 지금 배우는 것이 낫습니다. 블러드 엘프로 살아가면서 어려운 선택을 하는 것에 익숙해져야 할 것입니다. 스컬지가 우리의 고향을 갈기갈기 찢어놓았을 때, 아무도 우리 곁에 없었지요. 오직 우리 스스로의 힘으로 살아남아야 했습니다.'),
(8335, '잘 들으십시오. 사실 추방자 펠렌드렌은 앞으로 벌어질 더욱 심각한 문제를 예고하는 시작에 불과합니다. 그를 처치하면 당장 발등에 떨어진 문제는 해결되겠지만... 마법에 대한 욕망을 극복하지 못하는 한 모든 ?$r가 그와 같은 운명에 처할 수 있지요.'),
(8336, '이 섬의 많은 생명체들은 한때 우리의 마법 능력으로 불공평하고 온순한 상태에 갇혀 있었습니다. 하지만 스컬지가 태양샘을 파괴하면서 우리는 이 생명체들을 통제할 수 없게 되었습니다. 마법 조각들은 우리가 한때 가졌던 통제력의 잔재이며, 따라서 이 조각들을 이용해 우리가 다시 통제력을 되찾는 데 도움이 될 새로운 장치를 만들 수 있을지도 모릅니다. 더 나아가, 이 조각들을 통해 이 섬이 진정으로 어떤 병폐에 시달리고 있는지 알아낼 수도 있을 것입니다.'),
(8338, '말투로 보아 급한 일이 있으신 것 같은데, 구체적으로 어떤 도움을 드릴 수 있을까요?'),
(8341, '$n님, 파편과 인장을 가지고 계신가요? 군주의 반지를 만들려면 그것들이 필요합니다.'),
(8342, '$N, 심연의 최고 의회를 다시 노릴 생각이라면 황혼의 군주 반지 하나가 더 필요할 거야. 파편과 인장을 더 가져오면 하나 만들어 줄게.'),
(8344, '망령의 정수는 훌륭한 실험 재료가 될 겁니다. 당신이 마법사로서 살아온 삶과 마찬가지로, 세상에서 발견하는 것들을 통해 배우는 것이 중요하죠... 물론, 그것을 우리 뜻대로 왜곡하기 전에 말입니다. 악마가 가장 풍부한 힘의 원천인 만큼, 만약 그런 오염이 섬에 실제로 존재한다면 꽤 큰 도움이 될 겁니다. 음... 적어도 우리 마법사들에게는 말이죠.'),
(8345, '$c님, 사당에 있는 명판을 읽어보셨나요?'),
(8346, '아, $n님. 임무를 완료하셨나요?'),
(8348, '심연의 공작은 어땠어? 꽤 힘들었어?'),
(8350, '우리 여관에 오신 것을 환영합니다. 제게 주실 물건은 가져오셨겠죠?'),
(8352, '어떻게 됐어? 나도 내 자리를 떠나서 저 녀석들 중 하나랑 직접 싸워보고 싶어!'),
(8355, '자, 그럼 말씀해 보세요...'),
(8356, '네가 나한테 근육 자랑하기 전까지는 사탕 없어, $n...'),
(8357, '너 춤출 줄 알지? 오른발을 안으로 넣었다가... 뺐다가... 다시 안으로 넣고... 빙글빙글 흔들어 봐...'),
(8358, '자, 그럼 말씀해 보세요...'),
(8359, '네가 나한테 근육 자랑하기 전까지는 사탕 없어, $n...'),
(8360, '너 춤출 줄 알지? 오른발을 안으로 넣었다가... 뺐다가... 다시 안으로 넣고... 빙글빙글 흔들어 봐...'),
(8361, '일을 끝내셨나요?'),
(8362, '$n, 자네는 싸움에서 스스로를 지킬 수 있다는 걸 증명했네. 황혼의 망치단을 계속 압박하자. 심연의 기사들을 좀 더 처치해 주면, 후움과 내가 전투에서 얻은 전리품들을 보상으로 주겠네.'),
(8363, '$n, 자네는 심연의 공작을 상대할 능력이 충분하다는 것을 보여줬네. 난 언제나 좋은 습관을 장려하는 사람이지. 인장을 더 가져오면 보상을 주겠네.'),
(8364, '$n, 당신은 정말 제 모든 기대를 뛰어넘었습니다. 당신은 Huum과 제가 감히 맞서 싸우기 전에 오랫동안 고민했을 적들을 상대해 왔으니까요.$B$B지금으로서는 당신이 황혼의 망치단과 그들의 지배자들에 맞서 싸운 노고에 계속 보답하는 것이 최선입니다.$B$B심연의 홀을 더 많이 가져다주시면 그에 걸맞은 보상을 드리도록 최선을 다하겠습니다.'),
(8365, '모자 20개 전부 다 가지고 있다고? 믿기지 않아, 좀 보여줘 봐. 흠집 하나 없이 깨끗해야 할 텐데!'),
(8366, '벌써 돌아오셨군요? 사우스시 불량배들에게 잊지 못할 교훈을 제대로 가르쳐주셨기를 바랍니다.'),
(8367, '아라티는 여전히 위대한 전사들의 피로 물들어 있고, 알터랙 전역에는 아직도 칼날이 부딪치는 소리가 울려 퍼지고 있다. 전선 소식이 없다면 내 시간을 낭비하지 마라!'),
(8368, '워송 협곡에서 은날개 파수꾼과의 전투는 매우 중요합니다. 얼라이언스는 자신들의 것이 아닌 숲을 보호한다는 구실로 호드의 가장 큰 목재 공급원 중 하나를 빼앗으려 하고 있습니다. $B$B이런 일이 일어나도록 내버려 두지 마십시오, $n! 호드를 위해 가치 있는 일을 했다는 증거를 가지고 돌아오십시오!'),
(8369, '서리늑대들의 땅에서 무슨 소식이 있습니까? 알터랙 계곡 전투는 어떻게 진행되고 있습니까?'),
(8371, '여행은 잘 되어가고 있느냐, 젊은이?'),
(8375, '스톰파이크 부족의 땅에서 무슨 소식이 있습니까? 알터랙 계곡 전투는 어떻게 진행되고 있습니까?'),
(8385, '아, $n. 앞으로도 여러 전선에서 당신의 경험을 계속해서 나눠주시길 바랍니다. 전장의 많은 병사들이 당신 같은 노련한 베테랑들을 우러러보고 있습니다.'),
(8386, '워송 협곡에서 소식이 있나요, $n?'),
(8387, '서리늑대들의 땅에서 무슨 소식이 있습니까? 알터랙 계곡 전투는 어떻게 진행되고 있습니까?'),
(8388, '아라티는 여전히 위대한 전사들의 피로 물들어 있고, 알터랙 전역에는 아직도 칼날이 부딪치는 소리가 울려 퍼지고 있다. 전선 소식이 없다면 내 시간을 낭비하지 마라!'),
(8389, '워송 협곡에서 은날개 파수꾼과의 전투는 매우 중요합니다. 얼라이언스는 자신들의 것이 아닌 숲을 보호한다는 구실로 호드의 가장 큰 목재 공급원 중 하나를 빼앗으려 하고 있습니다. $B$B이런 일이 일어나도록 내버려 두지 마십시오, $n! 호드를 위해 가치 있는 일을 했다는 증거를 가지고 돌아오십시오!'),
(8410, '나한테 줄 거 뭐 있어, $C?'),
(8411, '원소들은 어디 있어, 친구?'),
(8412, '영혼들이 우리가 무슨 짓을 꾸미는지 알고 날 죽이려고 하고 있어! 필요한 부품은 구했길 바라.'),
(8413, '깃털은 어디 있어, 친구?'),
(8414, '네가 내게 무슨 악을 가져왔느냐?'),
(8416, '탈다니스는 재앙의 돌을 정화할 수 있었을까요?'),
(8417, '스톨리가 내 술을 토해냈나요?'),
(8418, '그 끔찍한 트롤들을 처치했습니까?'),
(8419, '내 펠클로스 가지고 있니?'),
(8420, '내 펠클로스 가지고 있니?'),
(8421, '물건은 가지고 계신가요?'),
(8422, '깃털 가져왔어요? 이 인형에 솜을 채워 넣어야 해요!'),
(8423, '헬보어의 불타는 가시는 끔찍한 흉터를 남긴다. 전사여, 고통과 흉터를 두려워하지 마라. 그것들은 내가 갇힌 감옥에 비하면 아무것도 아니다.'),
(8424, '그림자의 맹세자들은 쉽게 패배하지 않지, 그렇지? 하지만 자네는 전사이니, 승리하든가 아니면 싸우다 죽든가 둘 중 하나일세.'),
(8425, '벌써 돌아오셨군요? 제게 시간은 예전과 같지 않네요. 당신에게도 정말 긴 여정이었겠어요...'),
(8426, '워송 협곡에서 은날개 파수꾼과의 전투는 매우 중요합니다. 얼라이언스는 자신들의 것이 아닌 숲을 보호한다는 구실로 호드의 가장 큰 목재 공급원 중 하나를 빼앗으려 하고 있습니다. $B$B이런 일이 일어나도록 내버려 두지 마십시오, $n! 호드를 위해 가치 있는 일을 했다는 증거를 가지고 돌아오십시오!'),
(8427, '워송 협곡에서 은날개 파수꾼과의 전투는 매우 중요합니다. 얼라이언스는 자신들의 것이 아닌 숲을 보호한다는 구실로 호드의 가장 큰 목재 공급원 중 하나를 빼앗으려 하고 있습니다. $B$B이런 일이 일어나도록 내버려 두지 마십시오, $n! 호드를 위해 가치 있는 일을 했다는 증거를 가지고 돌아오십시오!'),
(8428, '워송 협곡에서 은날개 파수꾼과의 전투는 매우 중요합니다. 얼라이언스는 자신들의 것이 아닌 숲을 보호한다는 구실로 호드의 가장 큰 목재 공급원 중 하나를 빼앗으려 하고 있습니다. $B$B이런 일이 일어나도록 내버려 두지 마십시오, $n! 호드를 위해 가치 있는 일을 했다는 증거를 가지고 돌아오십시오!'),
(8429, '워송 협곡에서 은날개 파수꾼과의 전투는 매우 중요합니다. 얼라이언스는 자신들의 것이 아닌 숲을 보호한다는 구실로 호드의 가장 큰 목재 공급원 중 하나를 빼앗으려 하고 있습니다. $B$B이런 일이 일어나도록 내버려 두지 마십시오, $n! 호드를 위해 가치 있는 일을 했다는 증거를 가지고 돌아오십시오!'),
(8430, '워송 협곡에서 은날개 파수꾼과의 전투는 매우 중요합니다. 얼라이언스는 자신들의 것이 아닌 숲을 보호한다는 구실로 호드의 가장 큰 목재 공급원 중 하나를 빼앗으려 하고 있습니다. $B$B이런 일이 일어나도록 내버려 두지 마십시오, $n! 호드를 위해 가치 있는 일을 했다는 증거를 가지고 돌아오십시오!'),
(8431, '워송 협곡에서 은날개 파수꾼과의 전투는 매우 중요합니다. 얼라이언스는 자신들의 것이 아닌 숲을 보호한다는 구실로 호드의 가장 큰 목재 공급원 중 하나를 빼앗으려 하고 있습니다. $B$B이런 일이 일어나도록 내버려 두지 마십시오, $n! 호드를 위해 가치 있는 일을 했다는 증거를 가지고 돌아오십시오!'),
(8432, '워송 협곡에서 은날개 파수꾼과의 전투는 매우 중요합니다. 얼라이언스는 자신들의 것이 아닌 숲을 보호한다는 구실로 호드의 가장 큰 목재 공급원 중 하나를 빼앗으려 하고 있습니다. $B$B이런 일이 일어나도록 내버려 두지 마십시오, $n! 호드를 위해 가치 있는 일을 했다는 증거를 가지고 돌아오십시오!'),
(8433, '워송 협곡에서 은날개 파수꾼과의 전투는 매우 중요합니다. 얼라이언스는 자신들의 것이 아닌 숲을 보호한다는 구실로 호드의 가장 큰 목재 공급원 중 하나를 빼앗으려 하고 있습니다. $B$B이런 일이 일어나도록 내버려 두지 마십시오, $n! 호드를 위해 가치 있는 일을 했다는 증거를 가지고 돌아오십시오!'),
(8434, '워송 협곡에서 은날개 파수꾼과의 전투는 매우 중요합니다. 얼라이언스는 자신들의 것이 아닌 숲을 보호한다는 구실로 호드의 가장 큰 목재 공급원 중 하나를 빼앗으려 하고 있습니다. $B$B이런 일이 일어나도록 내버려 두지 마십시오, $n! 호드를 위해 가치 있는 일을 했다는 증거를 가지고 돌아오십시오!'),
(8435, '워송 협곡에서 은날개 파수꾼과의 전투는 매우 중요합니다. 얼라이언스는 자신들의 것이 아닌 숲을 보호한다는 구실로 호드의 가장 큰 목재 공급원 중 하나를 빼앗으려 하고 있습니다. $B$B이런 일이 일어나도록 내버려 두지 마십시오, $n! 호드를 위해 가치 있는 일을 했다는 증거를 가지고 돌아오십시오!'),
(8446, '네, $r?'),
(8460, '계속 노력하세요, $n. 당신이 우리의 신뢰를 얻으려면 우리에게 당신의 능력을 증명해야 할 겁니다.'),
(8461, '팀버모우의 신뢰를 얻게 된다면, 우리가 당신을 위해 해드릴 수 있는 일이 분명히 있을 겁니다. 팀버모우는 동맹을 잊지 않으며, 특히 지금처럼 암울한 시기에는 더욱 그렇습니다.'),
(8463, '벌써 도난당한 물건을 찾았습니까?'),
(8464, '$n 님, 팀버모우 부족을 위해 해주신 일에 진심으로 감사드립니다. 앞으로도 꾸준히 노력해 주신다면 저희 부족의 신뢰와 존경을 얻을 수 있을 것입니다.'),
(8466, '당신은 제게 당신의 능력을 증명했지만, 우리 부족의 의심 많은 동족들에게도 계속해서 당신의 능력을 증명해야 할 것입니다. 그 과정에서 제가 계속해서 당신을 도울 수 있을지도 모릅니다. 데드우드 퍼볼그 중 일부는 독특한 머리 장식을 착용하는데, 이는 그들의 수를 줄이는 데 증거로 사용될 수 있습니다. 당신이 얻게 되는 머리 장식에서 깃털 하나를 제게 가져오십시오. 깃털 다섯 개를 가져올 때마다 당신은 팀버모우 부족 사이에서 인정을 받게 될 것입니다.'),
(8467, '당신은 제게 당신의 능력을 증명했지만, 우리 부족의 의심 많은 동족들에게도 계속해서 당신의 능력을 증명해야 할 것입니다. 그 과정에서 제가 계속해서 당신을 도울 수 있을지도 모릅니다. 데드우드 퍼볼그 중 일부는 독특한 머리 장식을 착용하는데, 이는 그들의 수를 줄이는 데 증거로 사용될 수 있습니다. 당신이 얻게 되는 머리 장식에서 깃털 하나를 제게 가져오십시오. 깃털 다섯 개를 가져올 때마다 당신은 팀버모우 부족 사이에서 인정을 받게 될 것입니다.'),
(8468, '저에게 보여주실 게 있으신가요?'),
(8469, '$n, 자네는 분명히 내 신뢰를 얻었지만, 의심 많은 우리 부족의 신뢰도 계속 얻어야 할 걸세. 그 신뢰를 얻을 수 있는 방법이 하나 있지.$B$B윈터폴 부족은 악령을 막기 위해 영혼 구슬을 지니고 다니는 것으로 알려져 있다. 하지만 윈터폴 부족 자체가 타락의 하수인인 만큼, 이 구슬들은 제 역할을 다하지 못하고 있다. 쓰러진 윈터폴 퍼볼그들에게서 영혼 구슬을 가져오게. 다섯 세트씩 가져올 때마다 자네는 팀버모우 부족 사이에서 인정을 받게 될 것이다.'),
(8470, '네, $c님, 무엇을 도와드릴까요? 당신은 우리 사이를 평화롭게 거니시는 것 같지만, 분명 뭔가 이상한 점이 느껴집니다. 뭔가… 불안한 기운이 감돌고 있어요…'),
(8471, '$c - 당신은 평화로운 태도로 우리에게 다가오셨지만, 저는 당신이 퍼볼그와 $r 모두에게 중대한 문제를 안고 오셨다는 것을 느낍니다. 무슨 말씀을 하시려고 오셨습니까?'),
(8472, '$n님, 비전 핵을 벌써 다 모으셨나요?'),
(8473, '묻기가 좀 그렇지만, $n... 작업이 완료된 건가요?'),
(8474, '저에게 보여주실 게 있으신가요?'),
(8475, '돌아왔구나, $n. 데드 스카에서 언데드들을 물리쳤어?'),
(8476, '토르와타와 제브와타는 여기 남동쪽에 있습니다. 트롤들을 처치하고 다시 오세요.'),
(8477, '오템베의 망치는 가져오셨나요, $n?'),
(8479, '줄마로쉬를 처치한 증거는?'),
(8480, '잃어버린 무기는 아직 못 모았소?'),
(8481, '당신이 우리에게 돌아왔군요, $n... 이것은 악마가 처치되었다는 뜻인가요?'),
(8482, '내게 가져온 물건이라도 있습니까? 어디 한번 봅시다.'),
(8483, '침입자를 처리했습니까?'),
(8484, '$c 님, 제 영역에 오신 것을 환영합니다. 아이언포지는 언제나 당신과 같은 영웅의 고향으로 여겨져야 마땅합니다. 그런데, 제게 무슨 용건이 있으십니까?'),
(8485, '대족장의 안부를 전합니다, $c. 당신의 훌륭한 업적 덕분에 호드는 이 어려운 시기에 더욱 강해지고 있습니다. 그런데, 제게 무슨 용건이 있습니까?'),
(8486, '신비로운 망령들은 처리했나요?'),
(8487, '$n, 부탁한 견본은 모두 모으셨나요?'),
(8490, '$n님, 벌써 마법석에 동력을 공급하셨나요?'),
(8491, '돌아왔군. 모피는 가져왔소?'),
(8492, '병사, 구리 막대 20개는 다 모았나?'),
(8493, '$C, 다시 돌아왔군? 정말 훌륭해! 지금까지 보내준 구리 막대는 전쟁 물자를 만드는 데 큰 도움이 될 거야. 예를 들어, 이 구리는 제작 중인 증기 탱크 부품과 시간이 허락한다면 배치할 계획인 소형 자이로콥터 편대에 사용될 예정이야. $B$B하지만 여기 쌓여 있는 구리 막대에 속지 마. 안퀴라즈 전쟁을 위해 더 많은 구리 막대가 필요해. 도와줄 수 있겠나?'),
(8494, '만약 당신이 그 철괴 스무 개를 가지고 있다면, 어디에 숨겨두었는지 알고 싶지 않아요!'),
(8495, '벌써 돌아왔다고? $C, 너에 대한 내 낮은 평가를 다시 생각하게 만들지 마. 마음이 뭉클해지잖아. 보시다시피, 벌레 사냥에 필요한 무기, 갑옷, 증기 탱크 등을 만들기에 철괴가 아직 부족해. 줄구룹인가, 아니면 너희들이 요즘 어디를 가는지 모르겠지만, 그 와중에 철괴 20개 묶음 정도 더 가져다줄 수 있겠지?'),
(8496, '저한테 주실 게 있으신가요, $n?'),
(8497, '저에게 주실 게 있으신가요?'),
(8498, '저를 위해 뭘 가져오셨나요?'),
(8499, '오, 형이 보낸 물건이군? 정말 좋군! 오늘따라 운이 참 좋군!'),
(8500, '$n, 다시 만나서 정말 반가워요. 잘 지내셨길 바라요. 맞아요, 저희는 아직 토륨 막대가 부족해요. 혹시 여분이 있으시면 안퀴라즈 전쟁 물자로 쓸 수 있도록 모아두고 있어요.'),
(8501, '$n님, 저에게 뭔가 말씀하고 싶으신가요?'),
(8502, '$c, 나한테 할 말이 있어?'),
(8503, '사실이 아니에요! 저는 여기 쌓여 있는 해초 더미 맨 위에 있는 해초를 절대 걷어내지 않을 거예요. 물론, 실용적인 면에서 거의 만병통치약이나 다름없으니 유혹을 느낄 수도 있겠지만요. *콜록* 혹시 아까 얘기했던 그 해초 가지고 계세요?'),
(8505, '제가 요청한 자색 연꽃 약초가 있나요?'),
(8507, '블랙앤빌 대위의 부대는 하이브조라 외곽에 주둔하고 있습니다. 만약 그를 찾을 수 없다면, 그의 부관인 자넬라 스타우트해머에게 말을 걸어보세요.'),
(8508, '$Glad:lass;님, 서류에 서명을 원하시는 거죠?'),
(8509, '뭐라고요? 말해봐요, $C! 내가 부탁한 아서스의 눈물 배송됐어요?'),
(8511, '$C, 당신이 약속했던 밝은 색 가죽이 맞기를 진심으로 바랍니다.'),
(8512, '$n, 다시 만나서 반갑습니다. 여러 전쟁 물자를 제작하는 데 필요한 밝은 색 가죽이 더 필요한 것 같습니다. 열 장 정도 가져다주시면 정말 감사하겠습니다.'),
(8513, '네, 기억합니다. 지금 들고 계신 가죽 재킷이 중간 사이즈 가죽 재킷 맞습니까?'),
(8514, '네, 사장님. 중간 크기 가죽은 많이 모았지만, 더 필요합니다. 모든 가죽은 버릴 것 없이 모두 유용하게 쓰일 테니 걱정하지 마세요. 부탁드리는 게 많다는 건 알지만, 그래도 도와주실 의향이 있으시다면 남은 가죽을 모으는 데 도움을 주시면 감사하겠습니다.'),
(8515, 'C씨, 배낭에 있는 저 두꺼운 가죽이 그거 맞나요? 정말 기대돼요! 다들 우리한테 엄청 만족할 거예요, 안 그래요?'),
(8516, '네, 아직 가죽이 충분히 쌓이지 않았어요. 두꺼운 가죽 목표량을 아직 채우지 못했거든요. 그 가죽으로 만들 수 있는 것들을 생각해 보세요! 온갖 종류의 갑옷과 무기, 증기 탱크 내부 부품이나 소총 조준경 같은 것들 말이죠! 그리고 공학용 고글도 만들면 재밌잖아요! 두꺼운 가죽 좀 더 가져다 줄래요?'),
(8517, '$C, 제가 필요한 린넨 붕대 20개 가지고 계신가요?'),
(8518, '많은 사람들이 이기심에 사로잡힐 때, 이타심을 보여주는 사람들의 모습에 늘 감탄하게 됩니다. C님, 제 임무를 완수하려면 아마 붕대가 몇 개 더 필요합니다. 다시 한번 붕대를 구하는 것을 도와주시겠습니까?'),
(8520, '야생 가죽 투구에 대한 지식을 전수하기 전에 튜닉과 머리띠, 그리고 야생 덩굴 한 조각이 필요합니다. 머리 장비는 모험가들 사이에서 매우 귀중한데, 단순한 머리띠든 머리 전체를 덮는 투구든 종류에 상관없이 그렇습니다. 장비의 외형과 상관없이 가치 있는 머리 장비를 만드는 기본 원칙은 동일합니다.'),
(8521, '$c님, 다시 한번 도와주시겠다고 제안해 주셔서 정말 감사합니다. 저희에게 맡겨진 비단 붕대는 상당량 모았지만, 아직 더 필요합니다. $n님, 붕대를 한 묶음 더 만들어서 이곳으로 보내주실 수 있을까요? 동맹과 저는 정말 감사히 받겠습니다.'),
(8522, '날들이 하루하루 흘러가지만, 우리는 계속 나아간다. $C, 룬천 붕대 있어?'),
(8523, '그래서 또다시 중요한 문제를 논의하게 되었군요, $C. 다시 한번 당신의 지난 노력에 감사드립니다. 그렇게 헌신적으로 봉사하는 사람은 흔치 않습니다. 하지만 아직 할 일이 더 남아 있습니다. $B$B$n, 다시 한번 룬천 붕대를 모아서 여기로 가져다주시겠습니까?'),
(8524, '$C, 전에 얘기했던 무지개 지느러미 참치를 전부 잡아서 돌아왔을 거라고 확신하는데, 그렇지?'),
(8525, '뭐라고! 또 너야? 세상에... 내가 바로 $R. 슬리키 미식가라고! 또 도와주러 온 거냐? 뭐, 네 마음도 이해가 가네. 이 맛있는 음식 냄새, 안 그래? <침 흘림>$B$B 이제 그만 어슬렁거리고! 어서 나가서 무지개 지느러미 알바코어 더 많이 가져와!'),
(8526, '그래서 구운 랩터는 다 구우셨나요?'),
(8528, '나는 당신이 우리가 이야기했던 점박이 방어를 잡아 곧 돌아올 것이라고 확신합니다.'),
(8529, '아직 괜찮으시다면, 다시 한번 나가서 점박이 방어를 한 마리 더 잡아오시도록 부탁드리고 싶습니다. 첫 번째 출조에서 얻으신 경험 덕분에 이번에는 훨씬 빠르고 쉽게 잡으실 수 있을 거라고 생각합니다. 해보시겠어요?'),
(8532, '$C, 당신이 가지고 있는 게 구리 막대 20개 맞기를 바랍니다.'),
(8533, '벌써 돌아왔다고? $C, 넌 금세 진짜 광부가 되겠군. 자, 어떻게 해야 하는지는 이미 알고 있지? 나가서 구리 광석을 잔뜩 캐내서 제련한 다음 여기로 가져와야 해. 네가 그 정도는 할 수 있다는 걸 알아. 문제는 네가 할 의향이 있느냐는 거지.'),
(8534, '하이브조라 안에서 정찰병 아제넬을 찾을 수 있을 거야. 서두르렴, $n! 시간이 중요해.'),
(8535, '$n님, 작업이 끝났나요?'),
(8536, '$n님, 작업이 끝났나요?'),
(8537, '$n님, 작업이 끝났나요?'),
(8538, '$n님, 작업이 끝났나요?'),
(8539, '$c, 나한테 할 말이 있어?'),
(8541, '저에게 주실 게 있으신가요?'),
(8542, '준설선 파업은 심각한 위협이므로 신속하게 처리해야 합니다!'),
(8543, '아주 좋아, 자네가 전쟁에 진심인 게 분명하군. 나도 자네처럼 전쟁이 시작되기를 기다리면서 약간 초조해. $C, 전쟁이 시작되면 정말 장엄할 거야. 호드가 실리투스 사막의 모래 위를 질주하며 무기를 손에 쥐고 곤충 떼를 향해 돌격하는 모습! 그날 모두가 큰 영광을 누리게 될 거야!$B$BHar! 하지만 먼저 양철 막대가 더 필요해. 이렇게 작은 게 얼마나 큰 차이를 만들어낼 수 있는지 참 신기하지 않나?'),
(8544, '제가 필요한 부품들을 다 모으셨나요?'),
(8545, '안퀴라즈 전쟁에 필요한 미스릴 주괴를 전부 확보할 수 있다면 정말 좋겠군. 그래서 돌아온 건가? 내 미스릴 주괴는 가져왔나?'),
(8547, '안녕하세요! 만나서 반갑습니다! $B$BI 특별한 상품권을 가지고 계신 것 같은데, 저에게 주시면 보답으로 무언가를 드리겠습니다.'),
(8548, '우리의 가장 충성스러운 동맹국들이 최상의 장비를 갖추도록 하는 것이 우리에게 가장 이익이 됩니다, $n.'),
(8549, '자, $C. 가서 $n을 찾아라.'),
(8551, '어이, $n! 고를라쉬 찾았어? 저 상자는 내가 제일 아끼던 거였는데, 안에는 내 가장 소중한 보물들이 숨겨진 비밀 공간이 있었거든!'),
(8552, '안녕하세요. 저와 볼일이 있으신가요?'),
(8554, '내 커틀러스 받았어, $n?'),
(8556, '$n, 반지와 재료를 가져다주셨나요?'),
(8557, '망토 만들 재료는 가져왔어, $n?'),
(8558, '$n 님, 제가 필요한 부품들을 가져오셨나요?'),
(8559, '제가 요청한 물품들을 구해오셨습니까, $n?'),
(8560, '$n님, 제가 필요한 부품들을 가져오셨나요?'),
(8561, '$n 님, 제가 부탁드린 부품들을 가져오셨나요?'),
(8562, '안퀴라즈에 있는 그의 거처에서, 무시무시한 크툰은 깊은 잠에 빠져 기다리고 있다.'),
(8563, '예?'),
(8564, '예?'),
(8572, '우리의 가장 충성스러운 동맹국들이 최상의 장비를 갖추도록 하는 것이 우리에게 가장 이익이 됩니다, $n.'),
(8573, '우리의 가장 충성스러운 동맹국들이 최상의 장비를 갖추도록 하는 것이 우리에게 가장 이익이 됩니다, $n.'),
(8574, '우리의 가장 충성스러운 동맹국들이 최상의 장비를 갖추도록 하는 것이 우리에게 가장 이익이 됩니다, $n.'),
(8575, '오오! 마법처럼 깜빡이는 물건이네! 나한테 주는 건가?'),
(8578, '용암 핵이라... 내 고글이 멀쩡하길 바라야겠군!'),
(8580, '샘플 채취 다 하셨어요? 노글을 언제라도 잃어버릴 수 있어요!'),
(8582, '대사를 찾았나, $n? 죽었나? 우리는 스컬지가 칼림도어에 발판을 마련하도록 내버려 둘 수 없어. 그들은 우리 국경에 이미 충분한 위협이 되기 때문에 두 방면에서 대처해야 해. 네가 알려준 사건들 중에서 유일하게 희망적인 건 그 노파가 타락하지 않은 것 같다는 거야. 그녀는 스컬지가 막대한 힘을 가져다줄 수는 있지만, 그들의 거래에 동의한다면 황무지가 진정으로 자신의 것이 될 수 없다는 것을 마음속 깊이 알고 있을 거야.'),
(8585, '음... 키메록...'),
(8586, '빨리해, 얘야. 고기가 상하면 안 되잖아.'),
(8587, '이 맛있는 냄새는 뭐지?'),
(8588, '$C, 쓸데없는 소리나 지껄일 시간 없어. 건조시켜야 할 두꺼운 가죽 더미가 너무 많거든. 최소 열 개는 준비해 와.'),
(8590, 'C씨, 우리가 얘기했던 두꺼운 가죽 10장을 이렇게 빨리 가지고 돌아온 거야?'),
(8592, '$n 님, 제가 부탁드린 부품들을 가져오셨나요?'),
(8593, '$n님, 제가 필요한 부품들을 가져오셨나요?'),
(8594, '제가 필요한 부품들을 다 모으셨나요?'),
(8595, '인간으로서 키라지 군주 하나를 처치하는 것은 대단한 업적입니다, $n. 하지만 그들은 수가 많고 강력합니다. 계속해서 그들을 물리쳐 우리의 용사로서 당신의 가치를 증명하십시오.'),
(8596, '제가 요청한 물품들을 구해오셨습니까, $n?'),
(8598, '무슨 일이야?'),
(8599, '너 생선 냄새 나!'),
(8600, '나를 위해 두꺼운 가죽 열 장을 잘라내는 데 이렇게 오래 걸릴 리가 없잖아! 혹시 가죽 벗기는 칼을 갈아야 하나? 아니면 내가 착각해서 네 배낭에 칼이 있는 건가?'),
(8602, '제가 필요한 부품들을 다 모으셨나요?'),
(8603, '안퀴라즈에 있는 그의 거처에서, 무시무시한 크툰은 깊은 잠에 빠져 기다리고 있다.'),
(8604, '준설선 파업은 심각한 위협이므로 신속하게 처리해야 합니다!'),
(8607, '$C, 실패해서 내 체면을 망치지 마! 우리가 얘기했던 마법 붕대를 가지고 최대한 빨리 여기로 돌아와!'),
(8609, '독에 감염됐나요?'),
(8611, '스프라이트 다터는 자극을 받으면 위험한 녀석들이니 조심해서 상대하세요, $C. 그리고 근처에 있는 나이트 엘프들은 더더욱 조심해야 합니다. 그 성가신 녀석들은 숲 속에 숨어 있는 경향이 있거든요.$B$B날개를 충분히 모으면 알려주세요. 꼭 후하게 보상해 드리겠습니다!'),
(8613, '스프라이트 다터는 자극을 받으면 위험한 녀석들이니 조심해서 상대하세요, $C. 그리고 근처에 있는 나이트 엘프들은 더더욱 조심해야 합니다. 그 성가신 녀석들은 숲 속에 숨어 있는 경향이 있거든요.$B$B날개를 충분히 모으면 알려주세요. 꼭 후하게 보상해 드리겠습니다!'),
(8615, '스프라이트 다터는 자극을 받으면 위험한 녀석들이니 조심해서 상대하세요, $C. 그리고 근처에 있는 나이트 엘프들은 더더욱 조심해야 합니다. 그 성가신 녀석들은 숲 속에 숨어 있는 경향이 있거든요.$B$B날개를 충분히 모으면 알려주세요. 꼭 후하게 보상해 드리겠습니다!'),
(8620, '나도 너처럼 바지를 한쪽 다리씩 입어. 다만 바지를 다 입고 나면 아르카나이트 부표를 만들지. 아르카나이트 부표 말이야!'),
