(8710, '$n 님, 제가 필요한 부품들을 가져오셨나요?'),
(8711, '$n 님, 제가 필요한 부품들을 가져오셨나요?'),
(8712, '$n 님, 제가 필요한 부품들을 가져오셨나요?'),
(8728, '아르카나이트 부표는 저절로 만들어지는 게 아닙니다, $n. 그리고 돈을 빌릴 수도 없습니다.'),
(8729, '시간이 얼마 남지 않았습니다, 챔피언.'),
(8730, '우리의 또 다른 영웅이 데스윙의 자식들에게 목숨을 잃었습니다. 우리는 이 고통에 영원히 시달릴 것입니다...'),
(8731, '$n님, 현장 임무를 완료하셨습니까? 스컬스플릿 대위는 하이브리갈 외곽에서 찾으실 수 있습니다.'),
(8732, '$Gboy:girl;, 당신은 그 서류에 서명을 받고 싶은 거죠?'),
(8735, '<레물로스는 깊은 생각에 잠겨 있다.>'),
(8737, '$n님, 작업이 끝났나요?'),
(8738, '하이브리갈 안에서 스카웃 랜디온을 찾을 수 있을 거야. 서두르렴, $n! 시간이 중요해.'),
(8739, '하이브아시 안에서 정찰병 잘리아를 찾을 수 있을 거야. 서두르렴, $n! 시간이 중요해.'),
(8740, '$n님, 작업이 끝났나요?'),
(8741, '<아나크로노스가 고개를 끄덕인다.>'),
(8742, '천 년의 세월이 흘렀고, 운명처럼 한 자가 내 앞에 서 있다. 그는 백성을 새로운 시대로 이끌 것이다. 고신은 떨고 있다. 그렇다, 그는 너의 믿음을 두려워한다. 크툰의 예언을 산산이 조각내라. 고신은 네가 오는 것을 알고 있다, 용사여. 너와 함께 칼림도르의 힘도 올 것이다. 준비가 되면 내게 알려주기만 하면, 내가 너에게 변하는 모래의 홀을 주겠다.'),
(8743, '풍뎅이 종이 당신 앞에 불길하게 드리워져 있습니다. 마음을 단단히 먹으십시오, $n. 풍뎅이 종이 울리면 안퀴라즈의 문이 열릴 것입니다. 그 벌어진 짐승의 입에서는 오직 혼돈과 파괴만이 쏟아져 나올 뿐입니다. 당신의 백성을 지키십시오!'),
(8746, '$n! 그를 찾았습니까? 제가 드린 가방 속 쪽지에 메첸을 찾을 만한 정보가 충분했습니까? 그 잔인한 깡패들이 그에게 무슨 짓을 할지 생각만 해도 끔찍합니다… 하지만 우리는 그렇게 터무니없는 몸값을 지불할 여유가 없습니다!'),
(8747, '훌륭하구나, 꼬마야. 청동 비행단의 호의를 얻기 위해 얼마나 많은 노력을 기울였는지 알겠다. 너의 헌신은 높이 평가한다. 수호자의 인장 반지는 악의 세력으로부터 탁월한 보호를 제공할 것이다. 하지만 경고하건대, 일단 네 길을 선택하면 마음을 바꿀 수 있는 방법은 없을 것이다.'),
(8748, '칼림도르의 아이들을 계속해서 지켜준 당신의 노고를 인정합니다. 당신의 인장 반지를 제게 주십시오. 그 힘을 강화해 드리겠습니다.'),
(8749, '$n, 자네는 내 동족을 빛내는 자네로군. 칼림도르의 적들을 쓰러뜨려라! 영원한 별빛의 땅을 더럽히는 것이 무엇을 의미하는지 보여주어라! $B$B자네는 또 다른 강화를 얻었다. 자네의 인장 반지를 내게 넘겨주어 그 힘을 더욱 강화시켜주도록 하라.'),
(8750, '이 정도의 헌신은 매우 드뭅니다. 당신은 흔들림 없는 의지를 보여주셨습니다, $n. 우리 세상을 굳건히 지켜주신 것에 대해 큰 보상을 받으실 겁니다.$B$B당신의 인장 반지를 제게 주십시오. 제가 그 마법을 강화해 드리겠습니다.'),
(8751, '이토록 끈질긴 모습은 처음 보네! 청동 비행단이 자네에게 마지막 마법을 부여한다. 영원하신 분께서 직접 명하셨네! 자네의 인장 반지를 내게 넘겨주시오. 필요한 조정을 해드리도록.'),
(8752, '훌륭하구나, 꼬마야. 청동 비행단의 호의를 얻기 위해 얼마나 많은 노력을 기울였는지 알겠다. 네 헌신에 감탄한다. 정복자의 인장 반지는 네 공격력을 크게 향상시켜 줄 것이다. 하지만 경고하건대, 일단 네 길을 선택하면 마음을 바꿀 수 있는 방법은 없을 것이다.'),
(8753, '칼림도르의 아이들을 계속해서 지켜준 당신의 노고를 인정합니다. 당신의 인장 반지를 제게 주십시오. 그 힘을 강화해 드리겠습니다.'),
(8754, '$n, 자네는 내 동족을 빛내는 자네로군. 칼림도르의 적들을 쓰러뜨려라! 영원한 별빛의 땅을 더럽히는 것이 무엇을 의미하는지 보여주어라! $B$B자네는 또 다른 강화를 얻었다. 자네의 인장 반지를 내게 넘겨주어 그 힘을 더욱 강화시켜주도록 하라.'),
(8755, '이 정도의 헌신은 매우 드뭅니다. 당신은 흔들림 없는 의지를 보여주셨습니다, $n. 우리 세상을 굳건히 지켜주신 것에 대해 큰 보상을 받으실 겁니다.$B$B당신의 인장 반지를 제게 주십시오. 제가 그 마법을 강화해 드리겠습니다.'),
(8756, '이토록 끈질긴 모습은 처음 보네! 청동 비행단이 자네에게 마지막 마법을 부여한다. 영원하신 분께서 직접 명하셨네! 자네의 인장 반지를 내게 넘겨주시오. 필요한 조정을 해드리도록.'),
(8757, '정말 대단하구나, 꼬마야. 청동 비행단의 호의를 얻기 위해 얼마나 많은 노력을 기울였는지 알겠다. 네 헌신에 감탄한다. 소환사의 인장 반지는 너의 마법 능력과 타고난 재능을 크게 향상시켜 줄 것이다. 하지만 경고하건대, 일단 네 길을 선택하면 마음을 바꿀 수 있는 방법은 없을 것이다.'),
(8758, '칼림도르의 아이들을 계속해서 지켜준 당신의 노고를 인정합니다. 당신의 인장 반지를 제게 주십시오. 그 힘을 강화해 드리겠습니다.'),
(8759, '$n, 자네는 내 동족을 빛내는 자네로군. 칼림도르의 적들을 쓰러뜨려라! 영원한 별빛의 땅을 더럽히는 것이 무엇을 의미하는지 보여주어라! $B$B자네는 또 다른 강화를 얻었다. 자네의 인장 반지를 내게 넘겨주어 그 힘을 더욱 강화시켜주도록 하라.'),
(8760, '이 정도의 헌신은 매우 드뭅니다. 당신은 흔들림 없는 의지를 보여주셨습니다, $n. 우리 세상을 굳건히 지켜주신 것에 대해 큰 보상을 받으실 겁니다.$B$B당신의 인장 반지를 제게 주십시오. 제가 그 마법을 강화해 드리겠습니다.'),
(8761, '이토록 끈질긴 모습은 처음 보네! 청동 비행단이 자네에게 마지막 마법을 부여한다. 영원하신 분께서 직접 명하셨네! 자네의 인장 반지를 내게 넘겨주시오. 필요한 조정을 해드리도록.'),
(8762, '$n! 내가 준 가방 속 쪽지로 메첸을 찾을 수 있었나? 그 잔인한 깡패들이 그에게 무슨 짓을 할지 생각만 해도 끔찍해… 하지만 우리가 그토록 터무니없는 몸값을 지불할 여유는 없어!'),
(8763, '"호랑가시나무 보존기"는 처음 보면 증류기처럼 보이지만, 자세히 살펴보면 도깨비들이 만든 듯한 장치들이 숨겨져 있습니다. 하지만 당신의 뛰어난 요리 실력 덕분에 이 기계의 작동 원리를 이해할 수 있을 것 같습니다. 기계 안에는 이미 신선한 호랑가시나무가 들어있고, 이제 암염과 금화 다섯 개만 넣으면 기계를 작동시킬 수 있습니다.'),
(8764, '용사여, 만약 다른 길을 택하기로 결정한다면, 당신의 인장 반지와 안퀴라즈에 있는 우리 적들로부터 얻은 엄청난 양의 풍뎅이를 내게 바치시오.'),
(8765, '용사여, 만약 다른 길을 택하기로 결정한다면, 당신의 인장 반지와 안퀴라즈에 있는 우리 적들로부터 얻은 엄청난 양의 풍뎅이를 내게 바치시오.'),
(8766, '용사여, 만약 다른 길을 택하기로 결정한다면, 당신의 인장 반지와 안퀴라즈에 있는 우리 적들로부터 얻은 엄청난 양의 풍뎅이를 내게 바치시오.'),
(8770, '$c, 나한테 할 말이 있어?'),
(8771, '$c, 나한테 할 말이 있어?'),
(8772, '$c, 나한테 할 말이 있어?'),
(8773, '$c, 나한테 할 말이 있어?'),
(8774, '$n님, 저에게 뭔가 말씀하고 싶으신가요?'),
(8775, '$n님, 저에게 뭔가 말씀하고 싶으신가요?'),
(8776, '$n님, 저에게 뭔가 말씀하고 싶으신가요?'),
(8777, '$n님, 저에게 뭔가 말씀하고 싶으신가요?'),
(8778, '저한테 주실 게 있으신가요, $n?'),
(8779, '저한테 주실 게 있으신가요, $n?'),
(8780, '저한테 주실 게 있으신가요, $n?'),
(8781, '저한테 주실 게 있으신가요, $n?'),
(8782, '저한테 주실 게 있으신가요, $n?'),
(8783, '저한테 주실 게 있으신가요, $n?'),
(8784, '얼굴이 환하게 빛나네요! 그게 무슨 뜻인지 알아요...'),
(8785, '$n님, 제 자료 가지고 계신가요?'),
(8786, '저한테 주실 게 있으신가요, $n?'),
(8787, '저한테 주실 게 있으신가요, $n?'),
(8789, '내가 요청한 것을 찾아라. 그러면 너는 네 능력의 합보다 훨씬 더 위대한 존재가 될 것이다, 챔피언.'),
(8790, '주님께서 그들을 쳐부수시고 우리를 이 속박에서 해방시켜 주실 것입니다.'),
(8791, '아, $n, 돌아왔구나! 게다가 무사히 돌아왔군. 안퀴라즈에서 무슨 소식을 가져왔나?'),
(8799, '"호랑가시나무 보존기"는 처음 보면 증류기처럼 보이지만, 자세히 살펴보면 도깨비들이 만든 듯한 장치들이 숨겨져 있습니다. 하지만 당신의 뛰어난 요리 실력 덕분에 이 기계의 작동 원리를 이해할 수 있을 것 같습니다. 기계 안에는 이미 신선한 호랑가시나무가 들어있고, 이제 암염과 금화 다섯 개만 넣으면 기계를 작동시킬 수 있습니다.'),
(8801, '주님, 당신은 우리를 그것의 손아귀에서 해방시켜 주셨습니다.'),
(8802, '주님! 끝났습니다...'),
(8806, '저에게 주실 게 있으신가요?'),
(8809, '저한테 주실 게 있으신가요, $n?'),
(8810, '저한테 주실 게 있으신가요, $n?'),
(8811, '훈장 인장을 하나만 가지고 계신 모험가분들께는 스톰윈드에서 받을 수 있는 약간의 표창으로 교환해 드리겠습니다. $B$B열 개 묶음을 한 번에 제출해 주시면 더 큰 인정을 받으실 수 있습니다. 열 개 묶음을 제출할 만큼 인장이 부족하신 분들을 위해 한 개씩 교환해 드리는 서비스도 제공하고 있습니다. $B$B그러므로, 한 개만 제출하고 싶으신 경우에도 언제든지 도와드리겠습니다.'),
(8812, '단 하나의 공적 인장만 가지고 계신 모험가분들께는 아이언포지에서 인정받을 수 있는 소량의 인장으로 교환해 드리겠습니다. 단, 인장 10개를 한 번에 제출하시는 것이 더 큰 인정을 받으실 수 있습니다. 인장 10개를 모두 모으지 못하신 분들을 위해 1개씩 교환해 드리는 서비스도 제공하고 있습니다. 그러니 인장 1개만 제출하고 싶으시다면 언제든지 편하게 연락 주십시오.'),
(8813, '단 하나의 공적 인장만 가지고 계신 모험가분들께는 다르나서스에서 인정받을 수 있는 소량의 인장으로 교환해 드리겠습니다. 다만, 인장 10개를 한 번에 제출해 주시면 더 큰 인정을 받으실 수 있습니다. 인장 10개를 모두 제출할 만큼 충분한 인장이 없으신 분들을 위해 1개씩 교환해 드리는 서비스도 제공하고 있습니다. 그러니 인장 1개만 제출하고 싶으시다면 언제든지 도와드리겠습니다.'),
(8814, '단 하나의 공적 인장만 가지고 계신 모험가분들께는, 그 인장을 그놈레간 망명자들에게 약간의 인정을 받는 것으로 교환해 드리겠습니다. 단, 인장 10개를 한 번에 제출하시는 것이 더 좋습니다. 그렇게 하시면 더 큰 인정을 받으실 수 있습니다. 인장 10개를 모두 제출할 만큼 충분한 인장이 없으신 분들을 위해, 단 하나의 인장만 교환해 드리는 서비스도 제공하고 있습니다. 그러니, 인장 하나만 제출하고 싶으시다면 언제든지 도와드리겠습니다.'),
(8815, '훈장 인장을 하나만 가지고 계신 모험가분들께는 오그리마에서 인정받을 수 있는 소량의 훈장으로 교환해 드리겠습니다. $B$B열 개 묶음을 한 번에 제출해 주시면 더 큰 인정을 받으실 수 있습니다. 열 개 묶음을 제출할 만큼 충분한 인장이 없으신 분들을 위해 한 개씩 교환해 드리는 서비스도 제공하고 있습니다. $B$B그러니 한 개만 제출하고 싶으신 경우에도 언제든지 도와드리겠습니다.'),
(8816, '단 하나의 표창장만 가지고 계신 모험가분들께는 언더시티에서 인정받을 수 있는 소량의 표창장으로 교환해 드리겠습니다. 표창장은 열 개씩 묶어서 한 번에 제출해 주시는 것이 더 큰 인정을 받을 수 있다는 점을 유념해 주십시오. 열 개 묶음을 채울 만큼의 표창장이 없으신 분들을 위해 한 개씩 교환해 드리는 서비스도 제공하고 있습니다. 한 개만 제출하고 싶으신 경우에도 언제든지 도와드리겠습니다.'),
(8817, '단 하나의 표창장만 가지고 계신 모험가분들께는 썬더 블러프에서 인정받을 수 있는 소량의 표창장으로 교환해 드리겠습니다. 표창장은 열 개씩 묶어서 한 번에 제출해 주시는 것이 더 큰 인정을 받을 수 있다는 점을 유념해 주십시오. 열 개 묶음을 채울 만큼의 표창장이 없으신 분들을 위해 한 개씩 교환해 드리는 서비스도 제공하고 있습니다. 한 개만 제출하고 싶으신 경우에도 언제든지 도와드리겠습니다.'),
(8818, '단 하나의 훈장 인장만 가지고 계신 모험가분들께는 다크스피어 부족에서 인정받을 수 있는 소량의 훈장으로 교환해 드리겠습니다. 훈장은 열 개씩 묶어서 한 번에 제출해 주시는 것이 더 큰 인정을 받을 수 있다는 점을 유념해 주십시오. 열 개 묶음을 채울 만큼의 훈장이 없으신 분들을 위해 한 개씩 교환해 드리는 서비스도 제공하고 있습니다. 한 개의 훈장만 제출하고 싶으신 경우에도 언제든지 도와드리겠습니다.'),
(8819, '저는 임무 수행 중 표창장을 받은 모험가들의 표창장을 받습니다. 표창장 10장을 제게 제출해 주시면 스톰윈드에서 당신의 공적을 크게 인정해 드리겠습니다. 표창장 한 장씩도 받지만, 인정해 주는 정도는 훨씬 낮습니다. 저희는 더 큰 공적에 관심이 많지만, 어떤 공적도 무시하지는 않을 것입니다. 그러니 표창장 10장을 제출해 주시면 기꺼이 받겠습니다.'),
(8820, '저는 임무 수행 중 표창장을 받은 모험가들의 표창장을 받습니다. 표창장 10장 세트를 제출해 주시면, 아이언포지에서 당신의 공적을 크게 인정해 드리겠습니다. 표창장 한 장씩도 받지만, 인정해 주는 정도는 훨씬 낮습니다. 저희는 더 큰 공적에 관심이 많지만, 어떤 공적도 무시하지는 않을 것입니다. 그러니 표창장 세트를 제출해 주실 준비가 되셨다면 기꺼이 받겠습니다.'),
(8821, '저는 임무 수행 중 표창장을 받은 모험가들의 표창장을 받습니다. 표창장 10개 세트를 제출해 주시면, 다르나서스에서 당신의 공적을 크게 인정해 드리겠습니다. 표창장 한 장씩도 받지만, 인정해 주는 정도는 훨씬 낮습니다. 저희는 더 큰 공적에 관심이 많지만, 어떤 공적도 무시하지는 않을 것입니다. 그러니 표창장 세트를 제출해 주실 준비가 되셨다면 기꺼이 받겠습니다.'),
(8822, '저는 임무 수행 중 표창장을 받은 모험가들의 표창장을 받습니다. 표창장 10개를 제게 가져다주시면, 그놈레간 추방자들에게 당신의 공적을 크게 인정해 드리겠습니다. 표창장 한 장씩도 받지만, 인정해 주는 정도는 훨씬 낮습니다. 저희는 더 큰 공적에 관심이 많지만, 어떤 공적도 무시하지는 않을 것입니다. 그러니 표창장 10장을 가져다주실 준비가 되셨다면 기꺼이 받겠습니다.'),
(8823, '저는 임무 수행 중 표창장을 받은 모험가들의 표창장을 받습니다. 표창장 10장을 제게 제출해 주시면, 오그리마에서 당신의 공적을 크게 인정해 드리겠습니다. 표창장 한 장씩도 받지만, 인정해 주는 정도는 훨씬 낮습니다. 저희는 더 큰 공적에 관심이 많지만, 어떤 공적도 무시하지는 않을 것입니다. 그러니 표창장 10장을 제출해 주시면 기꺼이 받겠습니다.'),
(8824, '저는 임무 수행 중 표창장을 받은 모험가들의 표창장을 받습니다. 표창장 10장을 제게 제출해 주시면, 언더시티에서 당신의 공적을 크게 인정해 드리겠습니다. 표창장 한 장도 받지만, 인정해 주는 정도는 훨씬 낮습니다. 저희는 더 큰 공적에 관심이 많지만, 어떤 공적도 무시하지는 않을 것입니다. 그러니 표창장 10장을 제출해 주시면 기꺼이 받겠습니다.'),
(8825, '저는 임무 수행 중 표창장을 받은 모험가들의 표창장을 받습니다. 표창장 10개를 가져오시면 썬더 블러프에서 당신의 공적을 크게 인정해 드리겠습니다. 표창장 토큰도 받지만, 인정 정도는 훨씬 낮습니다. 저희는 더 큰 공적에 관심이 많지만, 어떤 공적도 무시하지는 않습니다. 그러니 표창장 세트를 가져오실 준비가 되셨다면 기꺼이 받겠습니다.'),
(8826, '저는 임무 수행 중 표창장을 받은 모험가들의 표창장을 받습니다. 표창장 10개를 가져오시면, 다크스피어 부족에서 당신의 공적을 크게 인정해 드리겠습니다. 표창장 한 장씩도 받지만, 인정해 주는 정도는 훨씬 낮습니다. 저희는 더 큰 공적에 관심이 많지만, 어떤 공적도 무시하지는 않습니다. 그러니 표창장 10장을 가져오실 준비가 되셨다면 기꺼이 받겠습니다.'),
(8830, '훈장 인장을 하나만 가지고 계신 모험가분들께는 스톰윈드에서 받을 수 있는 약간의 표창으로 교환해 드리겠습니다. $B$B열 개 묶음을 한 번에 제출해 주시면 더 큰 인정을 받으실 수 있습니다. 열 개 묶음을 제출할 만큼 인장이 부족하신 분들을 위해 한 개씩 교환해 드리는 서비스도 제공하고 있습니다. $B$B그러므로, 한 개만 제출하고 싶으신 경우에도 언제든지 도와드리겠습니다.'),
(8831, '저는 임무 수행 중 표창장을 받은 모험가들의 표창장을 받습니다. 표창장 10장을 제게 제출해 주시면 스톰윈드에서 당신의 공적을 크게 인정해 드리겠습니다. 표창장 한 장씩도 받지만, 인정해 주는 정도는 훨씬 낮습니다. 저희는 더 큰 공적에 관심이 많지만, 어떤 공적도 무시하지는 않을 것입니다. 그러니 표창장 10장을 제출해 주시면 기꺼이 받겠습니다.'),
(8832, '단 하나의 표창장만 가지고 계신 모험가분들께는 언더시티에서 인정받을 수 있는 소량의 표창장으로 교환해 드리겠습니다. 표창장은 열 개씩 묶어서 한 번에 제출해 주시는 것이 더 큰 인정을 받을 수 있다는 점을 유념해 주십시오. 열 개 묶음을 채울 만큼의 표창장이 없으신 분들을 위해 한 개씩 교환해 드리는 서비스도 제공하고 있습니다. 한 개만 제출하고 싶으신 경우에도 언제든지 도와드리겠습니다.'),
(8833, '저는 임무 수행 중 표창장을 받은 모험가들의 표창장을 받습니다. 표창장 10장을 제게 제출해 주시면, 언더시티에서 당신의 공적을 크게 인정해 드리겠습니다. 표창장 한 장도 받지만, 인정해 주는 정도는 훨씬 낮습니다. 저희는 더 큰 공적에 관심이 많지만, 어떤 공적도 무시하지는 않을 것입니다. 그러니 표창장 10장을 제출해 주시면 기꺼이 받겠습니다.'),
(8834, '단 하나의 공적 인장만 가지고 계신 모험가분들께는 아이언포지에서 인정받을 수 있는 소량의 인장으로 교환해 드리겠습니다. 단, 인장 10개를 한 번에 제출하시는 것이 더 큰 인정을 받으실 수 있습니다. 인장 10개를 모두 모으지 못하신 분들을 위해 1개씩 교환해 드리는 서비스도 제공하고 있습니다. 그러니 인장 1개만 제출하고 싶으시다면 언제든지 편하게 연락 주십시오.'),
(8835, '저는 임무 수행 중 표창장을 받은 모험가들의 표창장을 받습니다. 표창장 10장 세트를 제출해 주시면, 아이언포지에서 당신의 공적을 크게 인정해 드리겠습니다. 표창장 한 장씩도 받지만, 인정해 주는 정도는 훨씬 낮습니다. 저희는 더 큰 공적에 관심이 많지만, 어떤 공적도 무시하지는 않을 것입니다. 그러니 표창장 세트를 제출해 주실 준비가 되셨다면 기꺼이 받겠습니다.'),
(8836, '단 하나의 공적 인장만 가지고 계신 모험가분들께는 다르나서스에서 인정받을 수 있는 소량의 인장으로 교환해 드리겠습니다. 다만, 인장 10개를 한 번에 제출해 주시면 더 큰 인정을 받으실 수 있습니다. 인장 10개를 모두 제출할 만큼 충분한 인장이 없으신 분들을 위해 1개씩 교환해 드리는 서비스도 제공하고 있습니다. 그러니 인장 1개만 제출하고 싶으시다면 언제든지 도와드리겠습니다.'),
(8837, '저는 임무 수행 중 표창장을 받은 모험가들의 표창장을 받습니다. 표창장 10개 세트를 제출해 주시면, 다르나서스에서 당신의 공적을 크게 인정해 드리겠습니다. 표창장 한 장씩도 받지만, 인정해 주는 정도는 훨씬 낮습니다. 저희는 더 큰 공적에 관심이 많지만, 어떤 공적도 무시하지는 않을 것입니다. 그러니 표창장 세트를 제출해 주실 준비가 되셨다면 기꺼이 받겠습니다.'),
(8838, '단 하나의 공적 인장만 가지고 계신 모험가분들께는, 그 인장을 그놈레간 망명자들에게 약간의 인정을 받는 것으로 교환해 드리겠습니다. 단, 인장 10개를 한 번에 제출하시는 것이 더 좋습니다. 그렇게 하시면 더 큰 인정을 받으실 수 있습니다. 인장 10개를 모두 제출할 만큼 충분한 인장이 없으신 분들을 위해, 단 하나의 인장만 교환해 드리는 서비스도 제공하고 있습니다. 그러니, 인장 하나만 제출하고 싶으시다면 언제든지 도와드리겠습니다.'),
(8839, '저는 임무 수행 중 표창장을 받은 모험가들의 표창장을 받습니다. 표창장 10개를 제게 가져다주시면, 그놈레간 추방자들에게 당신의 공적을 크게 인정해 드리겠습니다. 표창장 한 장씩도 받지만, 인정해 주는 정도는 훨씬 낮습니다. 저희는 더 큰 공적에 관심이 많지만, 어떤 공적도 무시하지는 않을 것입니다. 그러니 표창장 10장을 가져다주실 준비가 되셨다면 기꺼이 받겠습니다.'),
(8840, '훈장 인장을 하나만 가지고 계신 모험가분들께는 오그리마에서 인정받을 수 있는 소량의 훈장으로 교환해 드리겠습니다. $B$B열 개 묶음을 한 번에 제출해 주시면 더 큰 인정을 받으실 수 있습니다. 열 개 묶음을 제출할 만큼 충분한 인장이 없으신 분들을 위해 한 개씩 교환해 드리는 서비스도 제공하고 있습니다. $B$B그러니 한 개만 제출하고 싶으신 경우에도 언제든지 도와드리겠습니다.'),
(8841, '저는 임무 수행 중 표창장을 받은 모험가들의 표창장을 받습니다. 표창장 10장을 제게 제출해 주시면, 오그리마에서 당신의 공적을 크게 인정해 드리겠습니다. 표창장 한 장씩도 받지만, 인정해 주는 정도는 훨씬 낮습니다. 저희는 더 큰 공적에 관심이 많지만, 어떤 공적도 무시하지는 않을 것입니다. 그러니 표창장 10장을 제출해 주시면 기꺼이 받겠습니다.'),
(8842, '단 하나의 표창장만 가지고 계신 모험가분들께는 썬더 블러프에서 인정받을 수 있는 소량의 표창장으로 교환해 드리겠습니다. 표창장은 열 개씩 묶어서 한 번에 제출해 주시는 것이 더 큰 인정을 받을 수 있다는 점을 유념해 주십시오. 열 개 묶음을 채울 만큼의 표창장이 없으신 분들을 위해 한 개씩 교환해 드리는 서비스도 제공하고 있습니다. 한 개만 제출하고 싶으신 경우에도 언제든지 도와드리겠습니다.'),
(8843, '저는 임무 수행 중 표창장을 받은 모험가들의 표창장을 받습니다. 표창장 10개를 가져오시면 썬더 블러프에서 당신의 공적을 크게 인정해 드리겠습니다. 표창장 토큰도 받지만, 인정 정도는 훨씬 낮습니다. 저희는 더 큰 공적에 관심이 많지만, 어떤 공적도 무시하지는 않습니다. 그러니 표창장 세트를 가져오실 준비가 되셨다면 기꺼이 받겠습니다.'),
(8844, '단 하나의 훈장 인장만 가지고 계신 모험가분들께는 다크스피어 부족에서 인정받을 수 있는 소량의 훈장으로 교환해 드리겠습니다. 훈장은 열 개씩 묶어서 한 번에 제출해 주시는 것이 더 큰 인정을 받을 수 있다는 점을 유념해 주십시오. 열 개 묶음을 채울 만큼의 훈장이 없으신 분들을 위해 한 개씩 교환해 드리는 서비스도 제공하고 있습니다. 한 개의 훈장만 제출하고 싶으신 경우에도 언제든지 도와드리겠습니다.'),
(8845, '저는 임무 수행 중 표창장을 받은 모험가들의 표창장을 받습니다. 표창장 10개를 가져오시면, 다크스피어 부족에서 당신의 공적을 크게 인정해 드리겠습니다. 표창장 한 장씩도 받지만, 인정해 주는 정도는 훨씬 낮습니다. 저희는 더 큰 공적에 관심이 많지만, 어떤 공적도 무시하지는 않습니다. 그러니 표창장 10장을 가져오실 준비가 되셨다면 기꺼이 받겠습니다.'),
(8846, '아, 추가 물자를 받으러 오셨군요? 추가 물자가 필요한 건 충분히 이해합니다... 증거가 필요하시면 주변을 둘러보세요. 제가 추가 물자를 지급해 드리겠지만, 그 대가로 적절한 수의 표창 인장을 주셔야 합니다. 이런 식으로 인장을 바친다고 해서 특별한 보상을 받으시는 건 아니지만, 전투가 시작될 때 생존에 도움이 될 만한 유용한 물건을 찾으실 수도 있을 겁니다.'),
(8857, '네? 거기에 뭘 들고 계세요?'),
(8858, '흠...'),
(8859, '친구, 부츠를 신으니 좀 무거워 보이네요.'),
(8860, '안녕하세요! 파티에 오셨나요? 아니면 피곤한 발을 쉬게 하려고 오셨나요?'),
(8861, '안녕하세요, $c님! 썬더 블러프 축제에 오셨나요? 아니면 사냥 사이에 지친 발을 쉬려고 오신 건가요?'),
(8862, '엘룬의 양초는 음력 축제 신도들에게 매우 존경받는 유물입니다. 양초 안에는 진정한 달빛이 담겨 있으며, 언제든 뿜어져 나올 준비가 되어 있습니다! 이 빛은 대부분의 생명체에게는 무해하지만, 오멘과 그의 부하들은 이 빛에 타버리고 눈이 부시게 될 것입니다.'),
(8864, '제가 몇 가지 드레스를 준비했는데, 마음에 드실지도 모르겠습니다. 이런 드레스들은 예전 음력 설날에 입던 옷들이고, 제가 오늘 보여드리는 드레스들은 제가 본 것 중 가장 아름다운 것들입니다. 하나하나 최고급의 부드러운 소재만을 사용하여 손수 제작했습니다. 조상의 은화를 주시면, 제가 가지고 있는 세 가지 스타일 중 하나를 골라 소장하실 수 있도록 해드리겠습니다. 괜찮으시겠습니까?'),
(8865, '제가 멋진 정장 세트를 준비했는데, 조상의 동전으로만 교환해 드릴 수 있다는 기쁜 소식을 전해드립니다. 패션을 중요하게 생각하신다면 바로 이 정장이 제격입니다! 이런 정장은 어디에서도 찾아볼 수 없을 거라고 장담합니다. 조상의 동전을 주시면 제가 준비한 세 가지 스타일 중 하나를 골라 소유하실 수 있도록 해 드리겠습니다. 괜찮으시겠습니까?'),
(8867, '발사기를 찾았나요, $n?'),
(8881, '대형 집속 로켓을 제작하려면 막대한 자원과 기술이 필요하지만, 그 화려함과 아름다움은 그만한 가치가 있습니다! 조상의 동전을 가져오면 그 제작법을 알려드리겠습니다.'),
(8882, '가장 화려한 불꽃놀이에는 집속탄이 빠질 수 없고, 그 집속탄은 반드시 집속탄 발사기에서 발사되어야 한다! 그렇다면 당신이 집속탄 발사기 제작 비법을 배우는 것이 당연하지 않겠는가? 조상의 동전을 가져오면 내가 그 비법을 알려주겠다.'),
(8884, '우리 파스트라이더 은신처의 순찰대원들은 아름다운 우리 땅에 가해진 피해를 바로잡는 데 헌신하고 있소이다. 우리는 그 일을 위해서라면 어떤 어려움도 감수할 것이오. 내가 네게 부탁했던 멀록 머리를 가지고 돌아왔기를 믿는다오.'),
(8885, '당신은 내 성공과 복수의 도구입니다, $c. 반지를 갖고 있습니까?'),
(8886, '$n님, 그대와 같은 분이 저를 도와주시니 기뻐서 웃음이 절로 나네요. 하지만, 저 괴물들이 내 배에 무슨 짓을 저질렀는지, 그리고 쿠엘탈라스에 무슨 일이 일어나고 있는지 난 똑똑히 알고 있답니다.'),
(8887, '안녕하세요, $c 님. 정말 반갑습니다. 저도 알아요, 끔찍한 괴물들이 정박지를 점령한 이 상황에서 제가 여기 있다는 게 믿기지 않네요. 벨렌드리스와 그의 레인저들이 제 화물을 되찾는 대로 여기서 나가겠다는 조건으로 저를 보호해 주기로 맹세했습니다. 그런데 당신이 들고 있는 건… 어딘가 익숙한데요?'),
(8889, '멀리서는 확실한 결과를 알 수 없군요... 더스크위더 첨탑의 마력원천은 벌써 차단하셨나요?'),
(8891, '이게 뭐요? 낯익은 물건이군. 아, 이럴 수가! 내 일지... 내 연구... 모든 사태의 원인은 바로 이것이오.'),
(8892, '저 비열한 놈들에게 본때를 보여주었나요?'),
(8893, '슈퍼 에그오매틱은 커글 크랭클홉의 최신 발명품입니다. 상당히 인상적인 기계 장치입니다. 당신이 제어판에 다가가면 슈퍼 에그오매틱은 심하게 덜컹거립니다.'),
(8894, '그럼 그 문제는 해결하신 건가요? 마법적인 이상 현상들을 상당수 처리하셨나요? 만약 더스크위더 마법사가 이런 문제들을 안고 다시 나타난다면 저는 어떻게 해야 할까요?'),
(8895, '네, $c요?'),
