(8961, '지난번 그 일을 맡은 건 우리 어리석음이자 파멸이었어. 부적에 깃든 발탈락 경의 영혼을 우리가 실수로 훔치지 않았더라면, 용병단에 그 영혼을 나눠 가진 탐욕스러운 자들이 없었더라면, 난 오늘 살아있었을 거야. 맥주나 한잔 들이키고, 애들을 공중으로 던져 올리고 있을지도 몰라. $n, 우리 옛 용병단의 비열한 탐욕 때문에 너도 파멸하지 않도록 조심해.'),
(8962, '그럼 $c, 내가 너에게 가져오라고 보낸 것들을 벌써 가지고 돌아왔니?'),
(8963, '그럼 $c, 내가 너에게 가져오라고 보낸 것들을 벌써 가지고 돌아왔니?'),
(8964, '그럼 $c, 내가 너에게 가져오라고 보낸 것들을 벌써 가지고 돌아왔니?'),
(8965, '그럼 $c, 내가 너에게 가져오라고 보낸 것들을 벌써 가지고 돌아왔니?'),
(8966, '그럼 모든 게 끝난 겁니까? 발탈락 경의 부적의 왼쪽 조각을 되찾아 마침내 제 오랜 동료 모르 그레이후프의 영혼을 편히 쉬게 해 주신 겁니까?'),
(8967, '설마 이살리엔의 영혼을 구출하고 발탈락 경의 부적 왼쪽 조각을 되찾는 일을 벌써 끝낸 건 아니겠죠, $n?'),
(8968, '그렇다면, $c 님, 당신은 이미 그 두 바보의 영혼을 편히 쉬게 해 주고 발탈락 경의 부적의 왼쪽 조각을 되찾았다는 뜻인가요?'),
(8969, '$n님, 부적의 왼쪽 조각을 가지고 돌아오셨다면 칭찬드립니다. 하지만 만약 그렇지 못하셨다면, 시간이 얼마 남지 않았으니 부디 꼭 되찾아 오시길 바랍니다!'),
(8970, '블러드켈프, 그것도 한 움큼이 필요해. 내 점술 마법에 필요한 재료거든. 알카즈 섬에 가서 블러드켈프를 캐려면 친구 두세 명 정도는 데려가야 할 거야... 스트라샤즈 녀석들이 아주 고약하거든!'),
(8977, '돌아오셨군요?'),
(8978, '기기를 가지고 돌아오셨군요?'),
(8979, '어떻게 도와드릴까요?'),
(8985, '그럼 $C, 내가 너에게 가져오라고 보낸 것들을 벌써 가지고 돌아왔나?'),
(8986, '그럼 $c, 내가 너에게 가져오라고 보낸 것들을 벌써 가지고 돌아왔니?'),
(8987, '그럼 $c, 내가 너에게 가져오라고 보낸 것들을 벌써 가지고 돌아왔니?'),
(8988, '그럼 $c, 내가 너에게 가져오라고 보낸 것들을 벌써 가지고 돌아왔니?'),
(8989, '그럼 모든 게 끝난 겁니까? 발탈락 경의 부적 조각을 되찾아 다시 하나로 합쳐, 마침내 제 오랜 동료 모르 그레이후프의 영혼을 편히 쉬게 해 주신 겁니까?'),
(8990, '설마 이살리엔의 영혼을 구출하고 발탈락 경의 부적 조각을 되찾는 일을 벌써 끝낸 건 아니겠지, $n? 부적을 내게 넘겨주기 전에 조각들을 다시 맞춰 놓는 걸 잊지 마.'),
(8991, '그렇다면, $c 님, 당신은 이미 그 두 바보의 영혼을 편히 쉬게 해 주고 발탈락 경의 부적 조각들을 다시 합쳤다는 뜻인가요?'),
(8992, '$n님, 부적을 완성해서 돌아오셨다면 칭찬드립니다. 하지만 아직 완성하지 못하셨다면, 시간이 얼마 남지 않았으니 어서 완성하시길 바랍니다!'),
(8993, '당신은 가장 좋아하는 지도자에게 사랑과 존경의 선물을 전하러 오셨나요?'),
(8994, '$n, 우리는 정말 먼 길을 함께 걸어왔어. 무슨 일이 있더라도 정말 고맙다는 말밖에 하고 싶지 않아! 넌 우리 용병단 ''베일드 블레이드''의 생존자들을 돕기 위해 목숨을 걸었잖아. 내 생각엔 넌 이제 우리 일원이야.'),
(8995, '$c, 감히 내 휴식을 방해하다니!'),
(8996, '$n, 돌아왔구나! 그것도 살아있네! 적어도 우리 중 한 명은 살아남았군. 모든 이야기를 다 해 줘야겠어!'),
(8999, '우리 계약대로, 와일드하트 장비들을 새로운 페럴하트 후드와 조끼로 교환할 준비가 되셨나요?'),
(9000, '우리 계약대로, 당신의 비스트스토커 장비들을 새로운 비스트마스터 모자와 튜닉으로 교환할 준비가 되셨습니까?'),
(9001, '우리 계약대로, 당신은 새로운 마법사 왕관과 로브를 받는 대가로 마지스터의 조각들을 넘겨줄 준비가 되셨습니까?'),
(9002, '우리 계약대로, 당신은 라이트포지 장비를 새로운 소울포지 투구와 흉갑으로 교환할 준비가 되셨습니까?'),
(9003, '우리 계약대로, 당신은 당신의 신앙심 깊은 물건들을 새로운 덕의 왕관과 예복으로 교환할 준비가 되셨습니까?'),
(9004, '우리 계약대로, 새로운 다크맨틀 모자와 튜닉을 받기 위해 섀도우크래프트 장비를 넘겨주실 준비가 되셨나요?'),
(9005, '우리 계약대로, 당신은 드레드미스트 장비들을 새로운 데스미스트 마스크와 로브로 교환할 준비가 되셨습니까?'),
