(9008, '우리 계약대로, 당신은 비스트스토커 장비들을 새로운 비스트마스터 모자와 튜닉으로 교환할 준비가 되셨습니까?'),
(9009, '우리 계약대로, 당신은 당신의 신앙심 깊은 물건들을 새로운 덕의 왕관과 예복으로 교환할 준비가 되셨습니까?'),
(9010, '우리 계약대로, 새로운 다크맨틀 모자와 튜닉을 받기 위해 섀도우크래프트 장비를 넘겨주실 준비가 되셨나요?'),
(9011, '우리 계약대로, 당신은 새로운 오천둥의 두건과 조끼를 받기 위해 당신의 원소 아이템들을 넘겨줄 준비가 되셨습니까?'),
(9012, '우리 계약대로, 당신은 드레드미스트 장비들을 새로운 데스미스트 마스크와 로브로 교환할 준비가 되셨습니까?'),
(9013, '우리 계약대로, 당신은 새로운 영웅심의 투구와 흉갑을 받기 위해 당신의 용맹 장비를 넘겨줄 준비가 되셨습니까?'),
(9014, '우리 계약대로, 당신은 새로운 마법사 왕관과 로브를 받는 대가로 마지스터의 조각들을 넘겨줄 준비가 되셨습니까?'),
(9015, '돌아왔구나, $n!'),
