(9118, '퀘스트에 필요한 부품이 몇 개 부족하니, 가서 모두 가져오세요!'),
(9120, '축복받은 빛! $g, 자네는 무슨 추악한 짓을 저지르고 있나?'),
(9121, '나크라마스에 들어간 사람 중 살아남아 그 이야기를 전할 수 있는 사람은 아무도 없습니다.'),
(9122, '나크라마스에 들어간 사람 중 살아남아 그 이야기를 전할 수 있는 사람은 아무도 없습니다.'),
(9123, '나크라마스에 들어간 사람 중 살아남아 그 이야기를 전할 수 있는 사람은 아무도 없습니다.'),
(9124, '사냥은 어떻게 진행되고 있나요?'),
(9125, '첫 번째 묶음 작업 정말 훌륭하게 해주셨어요, $n. 더 있으시면 지금 바로 받겠습니다. 묶음을 제출하실 때마다 휘장을 하나씩 드리겠습니다.'),
(9126, '해골이 우글거리는 장소를 알려드릴 수 있습니다, $c.'),
(9127, '내 직업에 종사하는 사람에게 뼈 조각은 아무리 많아도 부족하지 않다, $n. 뼈 조각이 남으면 내게 가져오너라. 그러면 또 다른 휘장을 보상으로 주겠다.'),
(9128, '저는 단지 당신을 올바른 방향으로 안내해 드릴 수 있을 뿐입니다, $n.'),
(9129, '솔직히 말씀드리면, 저는 그 코어들을 이용해서 서리불꽃 갑옷을 만듭니다. 낙스라마스에서 싸우는 마법사들이 사용하는 갑옷이죠. 당신과 같은 분들이 없었다면 우리는 이 전쟁에서 분명히 졌을 겁니다. 그러니 코어를 더 가져오시면 더 많은 문장을 드리겠습니다.'),
(9130, '네, 이게 뭐죠?'),
(9131, '<코르팍스가 당신에게 으르렁거립니다.>$B$B뭘 원해? 길 안내? 내가 알려줄 수 있는데...'),
(9132, '자투리 고기 한 아름 가져올 때마다 휘장을 하나씩 주겠다. 많을수록 좋다. 어서 내 눈앞에서 사라져라, 안 그러면 널 두 동강 내 버릴 테니까!'),
(9133, '친구, 꽤 방대한 목록을 가지고 있군요. 제가 한번 살펴보겠습니다.'),
(9134, '와, 그 상자 엄청 무거워 보이네요! 제 멋진 비행선 중 하나에 실어 보시겠어요?'),
(9135, '$c, 벌써 돌아왔어? 내가 요청한 건 다 안 보이는데...'),
(9136, '저는 우리 세계의 식물에 대해 해박한 지식을 가지고 있습니다. 길 안내가 필요하신가요?'),
(9137, '당신이 내게 가져다주는 나뭇잎 묶음 하나당, 새벽의 기사단 또는 십자군 기사단의 휘장 중 하나를 선택하여 보상으로 드리겠습니다. 휘장은 보급관에게 제출하면 다양한 보상을 받을 수 있습니다.'),
(9138, '당신의 도움으로 스컬지 문제를 해결할 수 있을 겁니다, $c. 다르칸은 반드시 처리하겠습니다!$B$B선크라운 마을의 네루비안 문제는 해결하셨나요?'),
(9139, '이곳에 있는 동안 스컬지와 싸우는 법을 많이 배웠습니다. 그들을 물리칠 수는 있지만, 단계적으로 접근해야 합니다. 쓰러진 아군을 데려가 새로 부활한 자들아로 만드는 그들의 끔찍한 행태 때문에, 그 과정에서 어떤 실수도 해서는 안 됩니다. 자, 그럼 황금안개 마을과의 전투는 어떻게 되어가고 있습니까?'),
(9140, '$c, 윈드러너 마을은 해방되었습니까? 태양의 성소에 있는 그 빌어먹을 마법사들이 제가 당신에게 모아달라고 부탁했던 스컬지 잔해들을 손에 넣으려고 저를 괴롭히고 있습니다. 하지만 걱정하지 마세요. 천천히, 제대로 일을 마무리하세요. 마법사들은 제가 처리하겠습니다.'),
(9141, '<메츠 사령관이 시가를 씹으며 말했다.>$B$B무슨 일이야? 난 바쁜 사람이야.'),
(9143, '너 트롤 귀 생겼어? 있잖아, 트랭퀼리엔이 가끔씩 도와주면 이런 문제는 없을 텐데. 네가 여기 있어서 정말 다행이야.'),
(9147, '자, 어때? 필요한 거 가져왔어? 서두르지 않으면 저 잘생긴 블러드 엘프 녀석은 죽을 거야!'),
(9148, '편지 가지고 있어요?'),
(9149, '$n, 제가 부탁드린 표본들을 구해오셨습니까?'),
(9150, '$n님, 정수를 구하셨나요?'),
(9152, '나머지 물자를 구하는 대로 바로 영업을 시작할 겁니다. 여기 있는 병력들은 필요한 물품을 구하지 못하면 멀리 가지 못할 거예요. 전쟁터는 정말 돈벌이가 잘 되는 곳이죠, 안 그래요, $c? 자, 저 구울들을 다 헤치고 제 수레까지 오셨나요?'),
(9153, '이 위협을 극복하려면 시간이 걸릴 겁니다. $n 씨는 어떻게 지내셨나요?'),
(9154, '당신은 우리 단체에 가입하러 오신 거죠, 그렇죠?'),
(9155, '작업 다 끝내셨나요?'),
(9156, '$n, 나한테 보여줄 게 있어?'),
(9157, '$n, 메달을 손에 넣었나요? 익사한 자들의 영혼이 아직도 이 호수를 떠돌아다닙니다!'),
(9158, '$n, 내가 부탁한 일을 완료했나요?'),
(9159, '$n, 내가 부탁한 일을 완료했나요?'),
(9160, 'C. 안다로스와 그곳에서 나이트 엘프들이 무슨 일을 벌였는지에 대해 무슨 소식을 들었습니까?'),
(9162, '$n, 무슨 사실을 알아냈는지 말해봐.'),
(9163, '샬란디스 섬에서 벌어지는 나이트 엘프의 음모를 밝혀내려는 우리의 노력은 어떻게 진행되고 있습니까, $c?'),
(9164, '데스홀름에 갇혔던 죄수들은 어떻게 되었나요? 그곳에 가보셨나요?'),
(9165, '이름, 계급, 군번!'),
(9166, '아, 정말 다행이에요!'),
(9167, '그럼 끝난 건가요? 다르칸은 파괴된 건가요?'),
(9169, '그럼 끝난 건가요, $c? 아노윈에 있는 나이트 엘프 달 수정구를 비활성화했나요?'),
(9170, '$n, 스컬지의 지휘 계통을 끊는 데 성공했습니까? 다르칸의 부하들은 모두 죽었습니까?'),
(9171, '여기서도 부인의 배에서 꼬르륵 소리가 들리는 것 같군요! 당신이 제게 말을 걸고 있는 건 제가 부탁한 것을 가지고 왔기 때문이겠죠?'),
(9172, '저와 이야기하고 싶으신가요?'),
(9173, '윈드러너 스파이어가 스컬지 감염에서 완전히 정화되었다는 소식을 가지고 돌아오시기를 바랍니다.'),
(9174, '아콴티온은 파괴되었나요?'),
(9175, '$n, 네가 들고 있는 건 뭐야?'),
(9176, '수정들을 회수하셨나요?'),
(9177, '당신은 누구시죠? 그건 뭐예요? 그 목걸이 어딘가 익숙해 보이는데. 이리 줘 보세요!'),
(9178, '작업 지시서 작성, $C?'),
(9179, '작업 지시서 작성, $c?'),
(9180, '당신은 누구시죠? 그건 뭐예요? 그 목걸이 어딘가 익숙해 보이는데. 이리 줘 보세요!'),
