(9189, '안녕, 형님. 무슨 소식을 가져왔나?'),
(9190, '작업 지시서 작성, $C?'),
(9191, '작업 지시서 작성, $C?'),
(9192, '좋은 소식이야, 나쁜 소식이야, 자기?'),
(9193, '이건 정말 끔찍하고 품위 없는 일입니다, $c. 당신이 이 일을 마님을 완전히 만족시킬 수 있도록 완수해 주시리라 믿습니다.'),
(9194, '작업 지시서 작성, $C?'),
(9195, '작업 지시서 작성, $C?'),
(9196, '작업 지시서 작성, $C?'),
(9197, '작업 지시서 작성, $C?'),
(9198, '작업 지시서 작성, $C?'),
(9199, '트롤 시체가 바로 우리 집 뒷마당에서 되살아나는 이 사태에 우리가 얽힐 여유가 없다는 걸 굳이 다시 말씀드릴 필요는 없겠죠! 남쪽의 데스홀름 때문에도 골치 아픈데 말입니다!'),
(9200, '작업 지시서 작성, $c?'),
(9201, '작업 지시서 작성, $C?'),
