(9205, '작업 지시서 작성, $C?'),
(9206, '작업 지시서 작성, $c?'),
(9207, '어떻게 도와드릴까요, $c님?'),
(9208, '당신은 비법을 가지고 있습니까?'),
(9209, '당신은 비법을 가지고 있습니까?'),
(9210, '당신은 비법을 가지고 있습니까?'),
(9211, '이 아르젠트 던 경비병들이 없었더라면, 당신은 이 바닥에 오점으로 남았을 겁니다.'),
(9212, '예?'),
(9213, '저리 가, 벌레야. 혹시 내게 줄 게 있는 건 아니겠지?'),
(9214, '그 무기들은 확보했습니까? 섀도우파인 지역의 수가 크게 줄어들었으니 이제 드디어 스컬지와의 전투에 집중할 수 있겠군요.'),
(9215, '이 끔찍한 냄새는 뭐지?'),
(9216, '$n님, 제가 요청한 좀비 심장 가지고 계신가요?'),
(9217, '구울 심장을 더 가져왔어? 모아주는 대로 다 쓸 수 있어, $n.'),
(9218, '제가 요청한 샘플이 있으신가요, $n?'),
(9219, '척추 분말을 더 구해왔나? 가져다주는 만큼 쓸 수 있어.'),
(9220, '$n, 데스홀름에서 승리하고 돌아오셨습니까?'),
(9221, '신중하게 선택하세요. 환불은 불가합니다.'),
(9222, '신중하게 선택하세요. 환불은 불가합니다.'),
