(9224, '신중하게 선택하세요. 환불은 불가합니다.'),
(9225, '신중하게 선택하세요. 환불은 불가합니다.'),
(9226, '신중하게 선택하세요. 환불은 불가합니다.'),
(9227, '신중하게 선택하세요. 환불은 불가합니다.'),
(9228, '신중하게 선택하세요. 환불은 불가합니다.'),
(9229, '라말라드니 소식 있나요?'),
(9230, '얼어붙은 룬은 낙스라마스 내부에서 발견될 가능성이 높습니다.'),
(9232, '오마리온을 만난 적은 없지, 그렇지?'),
(9233, '내가 생각하는 게 맞나요? 빌헬름이 침을 흘리는 것 같네요.'),
(9234, '재료는 가져오셨나요?'),
(9235, '재료는 가져오셨나요?'),
(9236, '재료는 가져오셨나요?'),
(9237, '재료는 가져오셨나요?'),
(9239, '재료는 가져오셨나요?'),
(9240, '재료는 가져오셨나요?'),
(9241, '재료는 가져오셨나요?'),
(9242, '재료는 가져오셨나요?'),
(9243, '재료는 가져오셨나요?'),
(9244, '재료는 가져오셨나요?'),
(9245, '재료는 가져오셨나요?'),
(9246, '재료는 가져오셨나요?'),
(9248, '판두다스벨로어? 아, 죄송합니다, $n. 못 알아봤습니다. 홀을 가지고 계신가요?'),
(9249, '어서 오세요! 다크문 축제 티켓을 사용하고 싶으시다면 말씀해 주세요! 다양한 종류의 티켓으로 멋지고 환상적인 상품을 교환할 수 있습니다. 망설이지 말고 지금 바로 신청해 보세요!'),
(9250, '필멸의 존재여, 그녀의 때가 된 것이다.'),
(9251, '현재 형태로서는 그 지팡이는 인간의 손에 들어가기에는 너무 위험합니다.'),
(9252, '우리는 승리할 것이다, $n.'),
(9255, '내게 가져온 물건이 있소?'),
(9259, '저 더러운 개자식 레빌가즈가 선장을 배신하는 옛 블러드세일즈 선원들을 사면해 주겠다고 제안했소! 저 얼간이가 나보고 옛 동료들을 죽이고 증거로 그들의 두건을 가져오라고 했지. 하지만 난 차마 그럴 마음이 없고, 자네에게도 그런 부탁은 하지 않겠네. 비단 천과 붉은 염료를 가져오면 내가 적당한 복제품을 만들어 주게. 자네가 배신했다고 남작께 말씀드리겠지만, 명심하건대... 블러드세일즈는 절대 좋아하지 않을 거네!'),
(9260, '침략에 대한 조사를 시작했습니까? 꾸물거릴 시간이 없습니다!'),
(9261, '침략에 대한 조사를 시작했습니까? 꾸물거릴 시간이 없습니다!'),
(9262, '침략에 대한 조사를 시작했습니까? 꾸물거릴 시간이 없습니다!'),
(9263, '침략에 대한 조사를 시작했습니까? 꾸물거릴 시간이 없습니다!'),
(9264, '음. 당신이 말해준 바에 따르면, 원 안의 목소리들은… 어떤 종류의 소통 수단으로 쓰이는 게 분명하군. 그런 마법을 통해 어떤 비정상적인 정신을 가진 자들이 접촉할지 생각만 해도 소름이 끼친다. 어쨌든 당신은 온전하고 제정신으로 돌아온 것 같으니 다행이다. 은빛 새벽단은 당신의 헌신에 감사한다.'),
(9265, '침략에 대한 조사를 시작했습니까? 꾸물거릴 시간이 없습니다!'),
(9266, '$n, 자네가 우리나 우리 친구들에게 정말 나쁜 짓을 저질렀음에 틀림없군. 어쨌든, 자네가 우리 호의를 되찾을 수 있는 방법을 알려주려고 왔네.$b$b아시다시피, 윈터스프링은 꽤 춥지. 다른 도시에서 온 고블린들이 많아서 따뜻하게 지낼 수 있도록 도와줄 사람이 필요해. 룬천과 석탄을 좀 가져다주면 내가 자네를 위해 좋은 말을 해 줄게. 하지만 조심해, 우리 적들은 자네가 우리를 돕는 걸 좋게 보지 않을 거야.'),
(9267, '라쳇에 발을 들이기 전에 두 번 생각하는 게 좋을 거야, $n! 네 악행에 대한 소문이 돌고 있거든.$b$b하지만 운이 좋게도, 블러드세일 해적단과의 교전에서 부상당한 사람들을 태운 배가 방금 도착했어. 네가 완전한 악당이 아니라는 걸 증명할 기회지. 붕대용 아마포와 물약용 빈 병을 가져와서 우리를 도와줘.'),
(9268, '$n, 당신은 타나리스의 고블린들과 다시 친분을 쌓으려는 겁니까? 우리는 옛 적, 블러드세일 해적단과 싸우기 위해 돛과 총을 만들 재료가 필요합니다. 마법 직조물과 강력한 플럭스를 가져오면 당신의 죄를 용서해 드리겠습니다.'),
(9274, '$n, 내 부탁을 들어줬지?'),
(9275, '이거 정말 신나지 않나요? 저는 제 일에 정말 큰 자부심을 가지고 있어요. $c.$B$BSo, 당신도 알아주셨으면 좋겠네요. 제브노와에 있는 트롤 캠프의 음식에 양념을 잘 하셨겠죠?'),
(9276, '제브텔라 공격은 어떻게 진행되고 있나요?'),
(9277, '제브노와 공격이 벌써 완료되었습니까?'),
(9278, '안녕하세요! 만나서 반갑습니다! $B$BI 특별한 상품권을 가지고 계신 것 같은데, 저에게 주시면 보답으로 무언가를 드리겠습니다.'),
(9280, '$n, 치유의 수정에 필요한 나방의 피는 모두 모았는가? 이 골짜기 곳곳에 흩어져 있는 생존자들의 생존이 촌각을 다투고 있네!'),
(9281, '우리가 얘기했던 일은 처리했나요, $n?'),
(9283, '그대들의 도움 덕분에 우리는 이 위기를 극복할 수 있을 겁니다.'),
(9292, '필요한 게 있으신가요?'),
(9293, '호수를 정화하려면 모든 샘플이 양호한 상태여야 합니다. 시간이 얼마 남지 않았습니다!'),
(9294, '호수에 병원체를 빨리 살포할수록, 그 물을 마시고 변이되는 토착 생물, 우리를 포함한 생물들의 수가 줄어들 것입니다! 이미 감염된 불쌍한 생물들을 도울 수 없어서 정말 유감입니다. 제 실험 장비만 온전했더라면 좋았을 텐데요.'),
(9299, '네? 거기에 뭘 들고 계세요?'),
(9301, '네? 거기에 뭘 들고 계세요?'),
(9303, '더 많은 다닥나무 올빼미야수에게 예방 접종을 하면 할수록 자나가 보다 빠르게 일에 복귀할 수 있다네.'),
(9304, '네? 거기에 뭘 들고 계세요?'),
(9305, '부품만 구한다면 이 영사기를 수리할 수 있습니다. 운이 따른다면 그곳에도 누군가가 생존해 있을 거예요.'),
(9311, '그렇다면 사실이군... 암멘 골짜기에 블러드 엘프 첩자가 있다니! 어떻게 우리를 따라왔지? 당장 사람을 보내 톨란을 데려오도록 하겠다.'),
(9315, '네루비안 지도자라고? 정찰 임무에서 이 아녹스텐에 대한 보고는 전혀 없었는데!'),
(9319, '어둠 속에서 길을 찾으셨나요?'),
(9322, '칼림도르의 불꽃은 밝게 타오르고 있는가?'),
(9323, '이 위협을 극복하려면 시간이 걸릴 겁니다. $n 씨는 어떻게 지내셨나요?'),
(9324, '$r, 얼굴이 정말 빛나네요. 뭘 들고 계세요?'),
(9325, '$r, 얼굴이 정말 빛나네요. 뭘 들고 계세요?'),
(9326, '$r, 얼굴이 정말 빛나네요. 뭘 들고 계세요?'),
(9328, '저를 만나고 싶어하시는 겁니까, $c? 저는 그런 약속이 있다는 이야기를 들은 적이 없는데요.'),
(9329, '이상하게 들릴지 모르지만, 포세이큰이 당신을 돕기 위해 왔습니다. 그들의 지도자인 최고 집행관 마브렌과 이야기해 보세요. 그는 마을 서쪽 탑에 있습니다. 그리고, 그와 이야기를 마치면 제게 돌아오세요. 당장 처리해야 할 중대한 일이 있습니다!'),
(9330, '$r, 얼굴이 정말 빛나네요. 뭘 들고 계세요?'),
(9331, '$r, 얼굴이 정말 빛나네요. 뭘 들고 계세요?'),
(9332, '$r, 얼굴이 정말 빛나네요. 뭘 들고 계세요?'),
(9338, '비록 우리가 제공하는 물질적인 보상이 필요하지 않더라도, 이 배지는 우리의 상호 신뢰와 우정을 상징합니다. 제게 가져다주십시오. 당신의 뛰어난 활약이 기록으로 남을 경우, 특별히 언급해 두겠습니다.'),
(9340, '돌아왔군요. 임무는 끝났나요?'),
(9345, '식물들을 가져오셨나요?'),
(9349, '계란은 준비됐어?'),
(9351, '핵심을 파악하셨나요?'),
(9352, '뭔가 알아낸 게 있나요? 나이트 엘프가 이 일의 배후에 있는 건가요?'),
(9355, '길을 치우셨나요?'),
(9356, '그가 음식을 먹기 시작할 때 어떤 표정을 지을지 정말 기대돼요. 추락 사고 이후로 그는 제가 맨날 음식 생각만 한다고 투덜거렸거든요. 뭐, 그가 비행선을 손보는 동안 누군가는 우리 밥을 챙겨줘야 하잖아요!'),
(9360, '제게 보여줄 문서가 있다고요?'),
(9361, '헬보어 고기를 정화하는 데 성공하셨습니까?'),
(9362, '시간 낭비할 시간이 없어! 껍데기 있어?'),
(9364, '마법을 다 모으셨나요?'),
(9366, '그 악마의 피... 혹시 얻으셨습니까, $n?'),
(9367, '불이 났나요?'),
(9368, '$n님, 혹시 좋은 소식 있으셨나요?'),
(9369, '치유 수정에 필요한 나방 피를 채취하셨나요? 생존자들이 계곡 곳곳에 흩어져 있으니 시간이 촉박합니다!'),
(9370, '돌아왔군, $n. 드레나이의 어리석음을 끝냈나?'),
(9372, '혈액 샘플을 채취할 수 있었습니까?'),
(9373, '안녕하세요, $c님. 무슨 일로 제 야영지에 오셨나요?'),
(9374, '$n님, 찾으셨나요? 아고나르의 웅덩이는 헬파이어 성채 북쪽에 있습니다.'),
(9375, '$c님, 무엇이 필요하세요?'),
(9376, '상황이 좋지 않아요. 이대로라면 그녀는 다시는 길을 떠날 수 없을 거예요. 그 가방은 찾으셨나요?'),
(9381, '깃털을 전부 모으셨나요?'),
(9383, '통제 불능의 공허방랑자를 상대로 수정의 마법을 사용해 보셨나요?'),
(9385, '약탈자들을 상대로 진전이 있었나요?'),
(9387, '샘플을 확보하셨습니까?'),
(9388, '축제가 끝날 때까지 불길은 꺼지지 않을 거예요!'),
(9389, '당신은 맡은 일을 처리했습니까?'),
(9391, '$n, 내가 부탁한 일 다 했어?'),
(9396, '$n님, 두루마리를 얻으셨나요?'),
(9397, '돌아왔군. 칼리리 암컷을 데려왔나?'),
(9398, '$n님, 다시 오신 것을 환영합니다. 제가 부탁드린 임무는 완료하셨나요?'),
(9399, '돌아왔군요! 임무는 완료했나요?'),
(9401, '말해봐, 암살자는 죽었어?'),
(9402, '물은 어때요?'),
(9403, '엘렌다르 폭포의 물만이 마법에 사용할 수 있을 만큼 순수합니다. 그 물을 가지고 있습니까?'),
(9404, '살아있는 나뭇가지 가지고 있나요? 빨리 내놓으세요!'),
(9405, '당신이 찾는 것이 무엇인지 말씀해 주세요. 그러면 제가 찾는 데 도움을 드리겠습니다.'),
(9406, '$n, 당신은 우리에게 무엇을 가져다 주시겠습니까?'),
(9409, '안녕하십니까, 형제여? 거기 그건 뭡니까? 저에게 가져오신 겁니까?'),
(9410, '당신은 살아있다는 것 자체가 행운입니다.'),
(9417, '돌아왔군요! 잘 지냈어요?'),
(9418, '그토록 갈망하던 자유가 드디어 내 것이 되었다!'),
(9419, '조심하세요, 하지만 서둘러야 합니다. 시간이 없습니다.'),
(9420, '칼리리 깃털 가져왔어, $c?'),
(9422, '사막의 위험을 조심하세요, $n. 동맹군이 모래 언덕에 숨어 있으니, 한 발짝도 마지막이 될 수 있습니다.'),
(9424, '마쿠루를 위해 세다이의 복수를 하였나요?'),
(9426, '$n님, 임무를 완료하셨나요?'),
(9427, '당신이 돌아왔습니다, $n. 물은 깨끗해졌나요?'),
(9430, '샤나르 유물을 회수했나요, $n?'),
(9431, '엘로사이 마지스트릭스의 쪽지는 좀 모호했지만, 그녀가 내게 원하는 게 뭔지 알 것 같아요. 그녀가 말한 흙을 가지고 있다면, 달샘물을 담을 용기에 넣어드릴 수 있어요.'),
(9433, '제 역할을 했나요?'),
(9434, '너랑 위즐로는 시약을 다 모았니?'),
(9435, '포세이큰에게서 수정들을 회수할 수 있었나요?'),
(9436, '$n, 날 실망시키지 마. 우리가 이 블러드스칼프의 마법을 우리 뜻대로 다룰 수 있다면, 우리 백성은 아마니족의 위협을 제거할 수 있을 거야.'),
(9437, '이타니아를 해방시키고 그 잘난 사략선들로부터 내 화물을 되찾았습니까?'),
(9438, '아웃랜드 소식을 가져왔다고요, $C 씨? 당장 말씀해 주세요!'),
(9439, '선스트라이더 신이시여, 제발 저를 쳐다보지 마세요! 더러워진 옷차림으로 이곳에 나와 있어야 하는 것만으로도 충분히 괴로운데, 제가 겪은 모든 일에 비하면 남들이 저를 쳐다보는 것까지 참을 순 없어요. 혹시 다크 아이언족이 요새라고 부르는 그 땅굴에서 제 소지품은 찾으셨나요?'),
(9440, '잡힌 동물들에게 먹이를 다 줬어? 잠깐! 저기 우리 안에 있는 그 멍청한 인간한테는 안 줬지? 아, 다행이다! 아깝잖아!'),
(9442, '$n님, 제가 필요한 버섯을 구하셨나요?'),
(9443, '그의 ''표식''을 되찾으시면, 저희가 그걸 조금 바꿔서 더 좋게 만들 거예요.'),
(9444, '그럼 이제 끝난 건가? 우서의 무덤이 더럽혀진 건가?'),
(9446, '당신은 은둔자 트루엔과 함께 우서의 무덤으로 걸어가야 하는 거 아닌가요?'),
(9447, '돌아왔군요, $n님. 임무는 완료되었나요?'),
(9448, '사냥꾼이여, 당신은 옳은 일을 하고 있습니다. 길 잃은 자들은 이미 너무나 많은 고통을 겪었습니다. 그들이 더 이상의 모욕을 당해서는 안 됩니다.'),
(9451, '부서진 자들과 $R은 함께 원소들이 지닌 신비에 대한 더 깊은 이해를 되찾을 것입니다.$B$B당신은 당신의 지구 토템을 창조하는 데 필요한 것을 가지고 돌아왔습니까?'),
(9452, '멀록을 조심하세요: 이상하고 아주 성가신 작은 생물체입니다.'),
(9453, '제 갑옷 어때요? 제가 직접 만들었어요! 우리가 전통적으로 입는 갑옷과는 조금 다르지만, 아주 편안해요.'),
(9454, '사슴 가죽은 부드러워서 육질이 부드럽고 촉촉한 편입니다.'),
(9455, '뭘 찾았다고? 어디서?'),
(9456, '이 오염이 확산되는 것을 용납할 수 없습니다. 블러드 워치에서 들은 보고만으로도 상황이 심각합니다. 지금 당장 막아야 합니다!'),
(9457, '나이아스 소식은 어때요, $n?'),
(9460, '뭐 샀어?'),
(9463, '저는 그녀의 건강이 꾸준히 악화되고 있는 것 같아 걱정됩니다.'),
(9465, '손전등 있어요?'),
(9466, '블랙탈론에 관한 소식이 있나요?'),
(9467, '오퇴르의 유골을 손에 넣기 전까지는 다시는 내게 말을 걸지 마라.'),
(9468, '네 얼굴 가장자리가 좀 그을린 것 같군. 불꽃과의 교감은 어땠어, $C?'),
(9470, '주술사 마이진의 사망 소식을 가지고 돌아왔습니까?'),
(9471, '실버메인 개체수를 조절하셨나요?'),
(9472, '자, $n. 다 됐나요?'),
(9473, '시간 낭비하지 마라, 얘야.'),
(9474, '빛을 가져오는 자의 표식은 우서가 빛에 대한 믿음을 갖고 있음을 보여주는 강력한 상징입니다.'),
(9475, '얼굴 표정을 보니 나쁜 소식을 전하러 오신 것 같군요. 무슨 소식을 들으셨나요?'),
(9483, '순례길에 올랐다고 해서 삶의 모든 즐거움을 포기해야 하는 건 아니잖아. 좋은 와인 마신 지 정말 오래됐네. 세나리온 증류주 한 병만 있으면 뭐든지 할 수 있을 것 같아! 알아, 나도 알아. 나이트 엘프가 빚은 술을 즐기는 내가 얼마나 시대에 뒤떨어진 사람인지.'),
(9484, '드래곤호크 기술을 완전히 익히셨나요?'),
(9485, '안개박쥐 기술을 완전히 익히셨나요?'),
(9486, '당신은 스프링포우와 함께 사냥해 본 적이 있나요?'),
(9487, '그 짐승들한테 너무 가까이 가지는 않았겠죠, 그렇죠?'),
(9488, '필요한 재료 없이는 예복을 완성할 수 없지. 하지만 너도 알고 있었잖아, 그렇지?'),
(9489, '희망이 사라진 곳에 희망을 불어넣어 보셨나요?'),
(9490, '블랙탈론의 사망 증거를 가져왔나요, $n?'),
(9491, '반지를 찾았다고 말해주세요. 그 상인도 머지않아 자기 몫의 돈을 찾을 겁니다.'),
(9492, '''대족장'' 카르가스 블레이드피스트의 죽음을 증명할 증거를 가지고 돌아왔습니까?'),
(9493, '나는 부서진 손 군단병들의 패배가 지옥 호드에 대한 우리의 승리를 예고한다고 생각할 만큼 순진하지는 않지만, 좋은 첫걸음이라고 생각합니다.'),
(9494, '혹시, 그, 불씨를 가져오셨나요?'),
(9495, '카르가스 블레이드피스트가 패배했다는 증거가 있습니까?'),
(9496, '부서진 손 군단을 격파하고 나면, 우리는 지옥의 호드에 대한 작전에서 진전을 이룰 수 있을 겁니다. $n, 임무는 완수했습니까?'),
(9500, '예?'),
(9501, '예?'),
(9503, '$n, 내 불쌍한 여동생들의 역겨운 정수를 그렇게 빨리 모아들였단 말이오?'),
(9504, '유적지에서 깨끗한 물을 얻으셨나요?'),
(9506, '혹시 뭐 찾으셨나요, 낯선 분?'),
(9508, '성공하셨습니까?'),
(9509, '자연의 요소들이 당신이 이룩한 위대한 업적에 대해 내게 이야기해 주었습니다. 자, 우리 이야기를 나눠 봅시다.'),
(9512, '아르르... 야르... 맙소사... 어, 미안해 얘야, 해적 말투 연습 좀 해야겠다. 안 그러면 잊어버릴 테니까...'),
(9513, '당신은 우리 민족에게 좋은 일을 해 주셨군요, $n.'),
(9514, '뭔가 찾으셨나요?'),
(9515, '경계를 늦추지 마세요!'),
(9516, '아직도 악마들이 남아 있는가?'),
(9517, '건축가 네모스는 당신이 삼림 벌채자들의 야영지에서 가져온 목재를 가져와 사티르나르를 더럽히고 있을지도 모른다고 말했습니다.'),
(9518, '고르탁 감독관이 살아 있는 한, 나는 그에게 반대할 것이다. 벌목장 소식은 어떻소?'),
(9519, '느껴지시나요, $n? 바람에 실려오는 부패의 기운을요? 우리가 아무것도 하지 않으면 부패는 계속해서 확산될 겁니다. 그래서 저는 엘룬의 성배를 찾고 있는 겁니다. 혹시 찾으셨나요?'),
(9520, '무엇을 들고 계십니까, 선생님?'),
(9521, '$c님, 그게 뭐예요?'),
(9522, '우리 나이트 엘프 정찰병들이 공격 준비가 아직 진행 중일지도 모른다고 보고했습니다. 저 공포의 군주들을 하루빨리 처치해야 합니다!'),
(9523, '고대 유물 몇 점 가져오지 않고는 돌아오지 마.'),
(9526, '설마 내 씨앗을 전부 심으신 건 아니겠지?'),
(9527, '제 아내 이름은 탈리사였고, 딸 이름은 매그윈이었습니다.'),
(9528, '우박, $n.'),
(9530, '계획대로 일이 착착 진행될 때가 제일 좋아요...'),
(9531, '저 배신자는 연합 해군 사령부를 건드린 걸 뼈저리게 후회하게 될 거야!'),
(9534, '아직도 악마들이 남아있지 않은가? 자네가 자칭 $r이라고? 지금은 싸움을 멈출 때가 아니다!'),
(9535, '정찰병, 거기 뭘 가지고 있지?'),
(9536, '저 공포의 군주들은 하루빨리 죽어야 해, $n!'),
(9537, '누워있는 개를 찾았나요?'),
(9538, '토템에서 낮고 웅웅거리는 소리가 들립니다.'),
(9544, '[푸르볼그] 아키다의 예언이 사실이었군… 우리에게 영웅이 나타났어.'),
(9545, '$n, 비전을 보셨나요?'),
(9548, '제 장비를 찾으셨나요?'),
(9549, '제가 아이언포지로 보낼 샘플들을 가지고 계신가요?'),
(9550, '어쩌면 이 오래된 일지가 지도에서 가리키는 것일지도 모릅니다.'),
(9554, '벌써 돌아왔어? 머리가 헝클어져 보이는데. 노분도는 의미심장한 미소를 지었다.'),
(9557, '당신의 모든 노력에 빛이 비추기를 바랍니다, $c. 거기에 무엇을 들고 있나요?'),
(9560, '저것들은 못생긴 작은 생물체들이야. 눈먼 감시자조차도 저것들을 볼 수 있을 정도지... 그는 눈이 멀었잖아.'),
(9562, '멀록이 대낮에 내 엉덩이를 걷어차고 침을 뱉었어!'),
(9563, '쓴맛 나는 술을 찾기 힘드세요? 네더가드 요새의 친절한 버니 아저씨가 통에 가득 담아두고 있을 거예요. 혹시 다 떨어졌다면 큰일 나겠지만요!'),
(9564, '제가 생각하는 게 맞나요?'),
(9567, '나지부스 사티로스에 대한 정보를 얻는 데 성공하셨습니까?'),
(9569, '내가 요청한 대로 사티로스 우두머리를 상대로 조치를 취했습니까?'),
(9570, '<쿠르츠가 당신에게 으르렁거립니다.>'),
(9571, '안녕하세요, 영웅님!'),
(9572, '$n 맞죠? 스톡턴이 당신 보고서를 기다리라고 하던데요. 좋은 소식을 가져다주시길 바랍니다.'),
(9573, '작업이 완료되었습니까?'),
(9574, '제가 필요한 샘플을 구하셨나요?'),
(9575, '$n, 맞지? 채드윅이 네 보고서를 기다리라고 했어. 내 앞에서 뭐 하는 거야?! 임무는 끝났어? 완전 멍청이냐? 토할 것 같아! 당장 네 쓸모없는 몸뚱이를 성벽 위로 끌어올려 명령받은 일이나 해! 내 말 들려?!'),
(9576, '거기에 무엇을 들고 있나요?'),
(9578, '예?'),
(9579, '수색 결과 갈렌의 흔적을 찾았습니까?'),
(9580, '사냥은 어떻게 진행되고 있나요, $n?'),
(9581, '첫 번째 결정 샘플을 채취할 수 있었습니까?'),
(9582, '그 짐승을 처치했습니까?'),
(9584, '두 번째 결정 샘플도 가지고 계신가요?'),
(9585, '제 세트에 필요한 마지막 샘플을 가지고 돌아오셨나요?'),
(9586, '타바라를 찾으셨나요?'),
(9587, '아들아, 네가 들고 있는 건 뭐니?'),
(9588, '저 글자, $c는 뭐죠?'),
(9589, '자기 피가 그 피인가요? 우리가 부탁하면 좀 중요할 수도 있거든요, 알죠?'),
(9590, '그렇게 빨리 모든 혈액을 채취한 건 아니겠죠?'),
(9591, '토템의 마법을 활용해서 가시벌레와 친구가 될 수 있었나요? 정말 사납고 활발한 생물이랍니다!'),
(9592, '팀버스트라이더는 힘이 센 새라서 포식자들이 종종 잘못 판단하여 끔찍한 결과를 초래하기도 합니다.'),
(9593, '나이트스토커는 기본적으로 면도날처럼 날카로운 발톱과 육식성을 가진 커다란 고양이과 동물입니다.'),
(9594, '네, $c님? 거기에 뭘 들고 계시죠?'),
(9595, '악몽에 맞서 보셨나요?'),
(9598, '다시 오신 것을 환영합니다, $n님.'),
(9600, '우리에게 적대적이지 않은 모든 생명은 구할 가치가 있다. 다만 우리의 적들만이 영원히 묻어버려야 한다.'),
(9602, '돌아오셨군요!'),
(9603, '안녕하세요, $n님. 히포그리프를 대여하는 데 관심 있으신가요?'),
(9604, '안녕하세요, 친구분. 먼 길을 오신 것 같군요. 무슨 일로 오셨나요?'),
(9605, '$c님, 어디로 가시는 거예요?'),
(9606, '$n님, 다시 오신 것을 환영합니다. 누르구니님은 목록에 있는 모든 것을 다 모으셨나요?'),
(9607, '이등병, 보고해! 블러드 퍼니스 전 구역을 정찰했나?'),
(9608, '블러드 퍼니스 전체를 정찰했습니까? 저에게 전해줄 말이 있습니까?'),
(9610, '아탈라이 유물을 충분히 모아주시면 연구를 시작할 수 있을 것 같습니다. 한때 위대했던 그들의 문명에 무슨 일이 일어났는지 너무나 궁금합니다.'),
(9616, '네? 저 지금 굉장히 바빠요, $n.'),
(9617, '예?'),
(9618, '켈투스를 찾으셨나요?'),
(9619, '공허석이 보여준 길을 따라가 보셨나요?'),
(9620, '예?'),
(9621, '아, 퀘르탈라스에서 오신 손님이시군요! 무슨 소식을 가지고 오셨나요?'),
(9623, '이게 우리가 아르거스의 손에 바칠 수 있는 최선인가?'),
(9624, '모래배를 구하기가 점점 어려워지고 있어요. 당연히 그 말은 여기 있는 엘렉들이 먹을 파이와 간식이 줄어든다는 뜻이죠. 제가 필요한 과일은 다 모아두셨나요?'),
(9626, '날 보러 왔나, 아가씨? 빨리 말해, 아가씨. 네 인종에 따른 격식 따위에 신경 쓸 시간 없어.'),
(9628, '조사팀이 복귀하지 못한 이유를 알아낼 수 있었나요?'),
(9629, '그 장치는 제대로 작동했나요? 제가 조사할 수 있도록 멀록들을 표시해 두셨나요?'),
(9631, '알투루스가 당신을 보냈습니다. 별들이 당신의 도래를 예고했습니다.'),
(9632, '안녕하세요, $c님. 무엇을 가지고 계신가요?'),
(9633, '오베르딘에 오신 것을 환영합니다, 친구. 다크쇼어에는 무슨 일로 오셨나요?'),
(9634, '우리는 약탈자가 블러드미스트 섬의 토착 포식자들을 몰아내기 전에 행동해야 합니다. 약탈자 개체 수 조절 작업을 시작했습니까?'),
(9635, '부품들 구했어? 나 잠수 좀 해야겠다.'),
(9636, '부품들 구했어? 앵커라이트 아후른이 내 뒤를 쫓아오기 전에 압축 코일을 고쳐야 해!'),
(9637, '$n, 내가 찾는 책들을 구했나?'),
(9640, '일기장 같은 거 찾고 계셨던 거 아니었나요?'),
(9641, '블러드미스트의 생물들에게서 수정 조각을 모았습니까?'),
(9642, '방사능에 오염된 수정 조각이 더 있으시면 제가 가진 다른 수정과 교환해 드리겠습니다.'),
(9643, '덩굴식물을 구하는 데 성공했나요?'),
(9644, '무슨 소식을 가져오셨나요, $n?'),
(9645, '돌아왔군요! 무슨 소식을 가져왔나요?'),
(9646, '어떻게 도와드릴까요, $c님?'),
(9647, '나방들을 제거하셨나요?'),
(9648, '제가 요청한 버섯들은 블러드미스트의 각기 다른 환경에 따라 고유한 특성을 지닌다는 점을 기억해 주세요.'),
(9649, '벌써 돌아오셨네요?'),
(9663, '지금은 긴장을 풀 때가 아닙니다!'),
(9664, '탑들을 우리 손에 넣게 되면 곧 포세이큰을 포위할 수 있을 것이다. 그 후에는 그들을 섬멸하는 것은 시간 문제일 뿐이다.'),
(9665, '그들이 우리 수도 중 한 곳과 그렇게 가까운 곳에 기지를 세우도록 우리가 허용할 거라고 생각하는 건 정말 어리석은 짓이다. 우리는 그들이 꼬리를 내리고 남쪽으로 후퇴할 때까지 그들의 병력을 깎아내릴 것이다.'),
(9666, '다 됐나요?'),
(9667, '시간이 얼마 남지 않았어, $n. 곧 그들이 날 죽일 거야...'),
(9669, '정말 엉망진창이었어요...'),
(9670, '혹시 좋은 소식 있으셨나요?'),
(9672, '예?'),
(9674, '걔네들은 끔찍한 생물들이야...'),
(9676, '네 가슴속에 솟아오르는 자부심이 보이는군. 벌써부터 스스로를 블러드 나이트의 일원이라고 생각하는 모양이군. 시간이 지나면 너도 우리와 함께할 자격을 얻게 될 것이다. 하지만 먼저 빛의 힘을 다스리고 숙달하는 법을 배우고, 무술 실력을 갈고닦아 네 자격을 증명해야 한다. 네가 지키기로 맹세한 자들의 조롱, 두려움, 그리고 혐오를 견뎌낼 준비를 해야 한다. 그들을 보호하는 위대한 힘의 대가를 이해하지 못하는 자들 사이에서는 당연한 일이다. 고개를 꼿꼿이 들고 칼을 항상 준비하라, $n.'),
(9677, '예?'),
(9678, '모든 노력에 있어 빛이 당신의 뜻대로 움직이기를 바랍니다.'),
(9680, '제가 필요한 뼈 조각을 가져오셨나요, $n?'),
(9681, '예?'),
(9682, '그들의 죽음을 슬퍼하지 마십시오, $n.'),
(9683, '아토프를 유인해내야 해!'),
(9684, '마지스터 아스탈로르 블러드스원과 이야기해 보셨습니까?'),
(9686, '블러드 나이트는 적에게 굴복하느니 차라리 죽음을 택한다. 명심해라, $n.'),
(9687, '용들의 전쟁은 오래전에 끝났다. 이제 남은 것은 뼈와 이세라의 새끼들이 남긴 불안한 잔해뿐이다.'),
(9688, '그 장면을 보는 게 너무 괴로워요. 제발, 이 이야기는 더 이상 꺼내지 말아요.'),
(9689, '동맹을 데려오시는 것을 추천합니다, $n.'),
(9692, '당신은 요청받은 모든 일을 다 했습니까?'),
(9694, '너무 많아서 마치 끊임없이 증식하는 것 같다는 생각이 자꾸 듭니다.'),
(9696, '요원님, 제가 지금 좀 바쁩니다. 중요한 일이어야 할 겁니다.'),
(9698, '안녕하세요, $n님. 기다리고 있었습니다.'),
(9699, '잘?'),
(9700, '이 지역에 이상한 생명체들이 나타났다는 보고를 받았습니다. 그것들이 토착 동물의 변종인지 아니면 진정한 공허 변칙 현상인지는 당신이 알아내야 할 문제입니다.'),
(9701, '벌써 돌아오셨군요? 스포레거 포자 유충에 대한 당신의 관찰은 제 연구에 매우 중요합니다. 서두르는 성격이 아니시겠죠? 인내심을 갖고 산란 계곡 전체를 꼼꼼히 탐사한 후에 최종 보고서를 제출해 주세요.'),
(9702, '$c, 모든 증거를 꼼꼼히 수집해야 해! 우리는 지금 거대한 퍼즐 조각들을 맞춰나가고 있는 거야. 네 실수 하나라도 있으면 잘못된 결론에 도달할 수 있어. 그렇게 되면 우리가 잔가르마쉬의 생태계를 어떻게 이해하게 되겠어?'),
(9703, '그 정보는 정확했습니까?'),
(9705, '뭐 발견한 거라도 있나요, $n?'),
(9706, '$n, 그거 뭐 들고 있어? 일기장이야?'),
(9707, '축하합니다, $n. 숙련자의 경지에 오르는 건 결코 쉬운 일이 아닙니다. 제가 직접 봤거든요. 그 건물에 들어오는 사람들의 수를 보면, 그중에서 이 자료를 가지고 저를 찾아올 만큼 오래 머무르는 사람은 극소수에 불과합니다.'),
(9708, '샘플은 이미 받으셨나요?'),
(9709, '늪지대 군주들을 위한 새로운 정원을 만드는 데 필요한 버섯을 모두 가지고 있나요?'),
(9711, '예?'),
(9714, '코일팽 저수지 언더보그에 서식하는 섐블러, 보그 자이언트, 언더배트에서 붉은 히비스커스 꽃이 더 필요합니다. 다섯 송이씩 묶어서 가져다주시면 정말 감사하겠습니다.'),
(9715, '제가 부탁드린 히비스커스 꽃을 모두 가져오셨나요?'),
(9716, '$n, 뭔가 발견했나요?'),
(9717, '언더보그는 매우 위험한 곳입니다. 그곳에 가는 것을 꺼린다고 해서 당신을 겁쟁이라고 생각하지는 않겠습니다. 하지만 제가 부탁한 것을 가져오지 않는다면 당신에게 감사하지 않을 겁니다.'),
(9718, '우박, $n.'),
(9719, '당신이 돌아왔군요. 그렇다면 블랙 스토커는 더 이상 존재하지 않는다는 뜻인가요?'),
(9720, '다 됐나요, $c?'),
(9723, '아스탈로르 마지스터가 요구하는 재료를 가지고 돌아왔습니까?'),
(9725, '$n님, 다시 오신 것을 환영합니다. 재앙과 그들의 고기 수송대를 물리치셨나요?'),
(9726, '나가를 찾아가 보셨나요?'),
(9727, '나가를 찾아가 보셨나요?'),
(9728, '$n, 다시 만나서 반가워요. 나가 사냥은 어떻게 진행되고 있나요?'),
(9729, '프후르는 괜찮나요? 방주를 되찾으셨나요?'),
(9730, '하가제드 현상금에 대해 얘기하고 싶으신 건가요? 글쎄요, 그가 죽었나요? 그럼 더 이상 얘기할 거리가 없겠네요!'),
(9731, '무슨 소식을 가져오셨나요, $n?'),
(9735, '물을 가져오셨나요?'),
(9736, '제가 필요한 시약들을 다 준비하셨나요?'),
(9737, '내가 부탁한 대로 내 메시지를 전달했는가? 세상의 거짓 기사들은 이제 자신들의 시대가 끝났음을 알아야 할 것이다.'),
(9738, '내 동료 네 명의 행방을 알아냈습니까?'),
(9739, '포자낭! 다 찾았어?'),
(9740, '게이트를 파괴하기 전에 먼저 포털 컨트롤러를 제거해야 합니다!'),
(9741, '공허 생물은 공허 변칙체로 성장합니다. 사실, 우리는 이 생물들이 정확히 무엇인지 알지 못합니다... 이름은 일종의 분류 체계일 뿐입니다.'),
(9742, '$r님, 포자낭을 더 구출하셨나요?'),
(9743, '늪의 군주 처치는 잘 되어가고 있나? 저 짐승들이 포자덩굴 영역에 얼씬도 못하게 혼내줘야겠어!'),
(9744, '당신은 많은 거인들을 처치했지만, 아직 많은 거인들이 남아있습니다. 그리고 그들은 여전히 우리의 포자낭을 공격하고 있어요!'),
(9746, '그들의 지도자는 우리에게서 영원히 숨어 지낼 수 없다. 시로나스를 찾아낼 때까지 모든 은신처를 체계적으로 제거할 것이다.'),
(9747, '돌아왔군. 카타루와 움브라펜 노예상들은 죽었나?'),
(9748, '물 마시지 마, $n!'),
(9753, '예?'),
(9756, '예?'),
(9759, '예?'),
(9760, '시?'),
(9761, '이 근처에서 유난히 용감하고 강력한 드레나이를 보셨나요?'),
(9762, '예?'),
(9763, '칼리트레쉬는 어떻게 됐어? 죽었어, $n?'),
(9764, '$n, 네가 들고 있는 건 뭐야?'),
(9765, '$n, 내가 찾는 무기를 구했나?'),
(9766, '우리는 나가족의 강철을 단조하여 그들을 상대할 무기를 만들 것이다. 코일팽 저수지에서 건져낼 수 있는 모든 무기를 내게 가져오라.'),
(9769, '저건 뭐지? 날개에 푹 빠지셨나 보네?'),
(9770, '난 아직도 늪지송곳니가 보여, $n. 설마 그렇게 빨리 끝난 건 아니겠지?'),
(9772, '돌아왔군요, 그런데 조바는 같이 없네요. 그에게 무슨 일이 생긴 거죠?'),
(9773, '빈손으로 돌아오지 않았다고 말해줘. $n.'),
(9774, '당신이 비웃는 게 보이네요. 네, 낡은 금속 부품을 전부 교체하기 전까지는 갑옷이 좀 이상해 보이겠지만, 그래도 무방비 상태보다는 낫죠.'),
(9775, '당신은 내 부하처럼 보이지 않는데. 할 말 다 해 봐, $r.'),
(9777, '상황을 보니 곧 포자를 보충해야 할 것 같습니다.'),
(9779, '벌써 돌아오셨군요? 편지는 찾으셨나요?'),
(9780, '저희 매장에 기증하실 생선이 있으신가요?'),
(9781, '사냥은 어떻게 진행되고 있나요, 친구?'),
(9782, '죽은 늪지대의 토양 샘플을 채취할 수 있었습니까?'),
(9783, '죽음의 늪에 사는 생물들을 죽이는 건 마음 아픈 일이지만, 이제 그들을 구할 길은 없다. 우리가 할 수 있는 최선은 그 지역을 복원하고 새로운 세대를 육성하는 것뿐이다.'),
(9784, '식물 재료가 좀 더 필요해요. 호수의 물이 줄어들면서 외래종이 늘어나고 있는 것 같아요. 하지만 제 추측을 뒷받침할 더 많은 자료가 필요해요.'),
(9785, '$n, 혹시 고대인들과 이야기를 나눠보셨나요?'),
(9786, '보하무 유적지를 살펴보셨나요? 그곳이 전성기 시절 얼마나 웅장했을지 상상해 보셨나요?'),
(9787, '당신은 우상을 가지고 있습니까?'),
(9788, '$n, 내 물건 찾았어? 동굴은 움브라펜에서 멀지 않고 나그란드와의 경계 근처에 있어.'),
(9789, '나그란드의 갈라진발굽새는 꽤 도전적인 사냥감이죠. 전 꽤 많이 잡았어요. 당신은 어떠세요?'),
(9790, '혹시 투명한 날개를 구하셨나요?'),
(9791, '늪지뱀 사냥에 성공하셨나요?'),
(9793, '어떻게 도와드릴까요?'),
(9794, '$r님, 저는 당신을 모릅니다. 저와 볼일이 있으십니까?'),
(9798, '거기 가지고 있는 게 뭔가?'),
(9799, '안녕하세요, $c님. 꽃은 모으셨나요?'),
(9800, '오우거 크기만 한...'),
(9801, '시약은 다 준비하셨나요?'),
(9802, '혹시 식물 조각이라도 찾으셨나요, $n?'),
(9803, '페랄펜의 장로와 이야기를 나누셨나요?'),
(9804, '호수 속으로 너무 깊이 들어가기 전에 나그란드 체리를 사용하세요.'),
(9805, '큰 부끄러움을 느끼며 말씀드립니다. 나그란드 강의 물을 퍼 올려 늪지를 만들려는 자들이 바로 제 친척입니다.'),
(9806, '돌아왔구나, $n. 번식 가능한 포자는 얻었니?'),
(9807, '우리는 언제나 더 많은 포자를 필요로 합니다. 톨스토크 버섯은 정말 유용한 버섯입니다. 이 버섯을 재배할 수 있다면 다양한 용도로 활용할 수 있습니다.'),
(9808, '$n, 혹시 발광 버섯 찾았어? 습지 곳곳에 널려 있어. 잘 살펴보면 멀리서도 밝게 빛나는 걸 볼 수 있을 거야.'),
(9809, '혹시 발광캡이 더 있으시면 더 주세요. 우리 마을에는 발광캡이 항상 더 필요하거든요.'),
(9810, '흙의 고리는 가능한 모든 방법으로 도울 것입니다.'),
(9811, '저를 만나고 싶어하시는 겁니까, $c? 저는 그런 약속이 있다는 이야기를 들은 적이 없는데요.'),
(9812, '퀘르탈라스에서 손님이 온다는 소식을 들었습니다. 솔직히 말씀드리면 블러드 엘프일 거라고 생각했는데요. 무슨 소식을 가지고 오셨습니까?'),
(9813, '네, $c요?'),
(9814, '버섯 있어, 친구?'),
(9815, '오염된 쓰레기를 절대 남기지 마십시오!'),
(9816, '<마법사 토르가쉬가 씩 웃는다.>$B$B작은 길 잃은 자들이 선물을 마음에 들어했나요?'),
(9817, '피아셰 현상금을 받으러 오셨군요? 오늘 들은 소식 중 최고네요.'),
(9819, '그들은 잠을 자나요?'),
(9820, '$n, 거기에 뭘 들고 있어요?'),
(9821, '고르도그가 이 돌을 먹습니다. 고르도그가 찬탈자를 발견했습니다. 돌을 가져오세요!'),
(9822, '오거들의 의도를 입증할 증거를 찾으셨나요?'),
(9823, '앙고로쉬의 위협이 우리를 덮치고 있습니다. 그들의 우두머리를 제거했습니까?'),
(9824, '과제들, $n. 다 읽으셨나요?'),
(9825, '$c, 내가 필요로 하는 유령의 정수를 구했나?'),
(9826, '바이올렛 아이를 아시나요? 당신은 낯이 익지 않네요.'),
(9827, '$n, 당신이 가지고 있는 건 뭐죠?'),
(9828, '$n, 당신이 가지고 있는 건 뭐죠?'),
(9830, '텔레도르에 있는 은둔자 아후른과 다른 이들에게 출혈독의 용도를 보여주고 싶습니다. 그러려면 출혈독 재고를 두 배로 늘려야 할 겁니다.'),
(9831, '조각 $c를 구하셨습니까? 이 문제에 시간을 낭비하지 않는 것이 좋을 것입니다.'),
(9832, '핵심 조각을 찾는 작업은 어떻게 진행되고 있나요, $n?'),
(9833, '도로 안전 확보에 진전이 있었습니까?'),
(9834, '$n은 막투를 위한 가죽을 가지고 있나요?'),
(9835, '앙고로쉬와의 싸움은 어떻게 진행되고 있습니까?'),
(9836, '당신은 누구이며 무엇을 원하십니까?'),
(9839, '끝났나요? 오버로드 고어피스트는 처리하셨나요?'),
(9841, '소리가 멀리 사라진 것 같네요. 그저 희망사항일까요, 아니면 정말로 문제를 해결하신 건가요?'),
(9842, '혹시 늪지송곳니 칼날을 좀 구하셨나요?'),
(9843, '키애나의 일기... 찾았어?'),
(9844, '묻기가 정말 싫지만, 카라잔 내부 상황은 어떻게 되었나요?'),
(9845, '이제 다시 낚시를 해도 안전할까요?'),
(9846, '그 토템들을 다 모으셨나요?'),
(9847, '페랄펜의 정령을 소환할 수 있었나요?'),
(9848, '데거펜 마을 수색에서 이 독극물 미스터리를 해결하는 데 필요한 정보를 얻으셨나요?'),
(9849, '고르도그는 바위를 돌려받고 싶어합니다.'),
(9850, '발굽이 갈라진 황소들이 모닥불 앞에서 당신 발치에 그냥 쓰러져 죽을 거라고 생각하세요?'),
(9851, '따뜻한 불길과 곁에서 한가롭게 수다를 떨 수 있는 여인은 집에서도 누릴 수 있는 것이다. 하지만 여기서는 큰 사냥감을 쫓거나, 쫓기다 죽을 각오로 임한다.'),
(9852, '이 땅에서 가장 강력한 동물을 사냥할 용기가 없다는 것을 인정하는 것은 부끄러운 일이 아닙니다.'),
(9853, '고르도그는 구록의 힘을 먹어치운다.'),
(9854, '자연 속에서 자신의 위치를 아는 데서 오는 평화를 경험해 보셨나요? 당신은 사냥꾼인가요, 아니면 사냥감인가요?'),
(9855, '당신은 심장의 고동을 진정시키는 법을 배웠습니까? 잔잔한 호수처럼 고요하고 인내심을 갖고, 목표물을 맞힐 적절한 순간을 기다리는 법을 배웠습니까?'),
(9856, 'Gutripper를 상대해 보셨나요?'),
(9857, '좀 더 여기 누워있을게요. 곧 괜찮아질 거예요.'),
(9858, '혹시…<기침>… 저…<기침>… 가시덤불개미들은 아직 처리 안 하셨겠죠?'),
(9859, '당신은... 발굽을 가지고 있나요?'),
(9861, '이리 줘! 빨리!'),
(9862, '공기의 정령은 머크블러드가 선스프링에서 무언가를 찾고 있다고 주장합니다...'),
(9863, '우리가 스스로 할 수 없으니 우리를 위해 해 주세요.'),
(9865, '내 친족 한 명이 살해될 때마다 그들 중 열 명이 죽어야 한다!'),
(9867, '저들의 우두머리의 목을 가져와라, $n.'),
(9868, '가로쉬는 당신의 존재를 거의 알아채지 못합니다. 그는 매우 우울해 보입니다.'),
(9871, '그게 뭐죠?'),
(9872, '그게 뭐죠?'),
(9873, '$n, 오르토르는 엄청난 힘을 가진 샤먼이라는 것을 명심하세요.'),
(9874, '오크들은 우리가 하는 일을 이해하지 못할 테지만, 반드시 해야 한다. 오크와 브로큰 모두의 안녕을 위해서.'),
(9875, '저에게 보여주실 게 있으신가요?'),
(9878, '머크블러드는 브로큰 종족의 사악한 부족입니다. 겉모습은 쿠레나이와 비슷해 보이지만, 틀림없이 야만적이고 살인을 일삼는 짐승들입니다.'),
(9882, '$n, 내가 부탁했던 수정 조각들을 찾아왔나요?'),
(9883, '수정 조각을 더 가지고 있나요? 산에 붙어 있는 조각은 가져가지 않도록 주의하세요. 나루와 문제를 일으키고 싶지는 않으니까요.'),
(9889, '항복합니다! 항복합니다!'),
(9892, '전쟁 구슬을 더 구했나요? 북쪽 끝, 잔가르마쉬와의 경계 근처에 오우거들이 많이 있을 겁니다.'),
(9893, '그 괴물들은 당신을 어떻게 대하고 있나요, $n? 꽤 만만치 않은 녀석들이죠?'),
(9894, '클락 경을 찾아내서 처리하셨습니까?'),
(9895, '보글래쉬를 만나보셨나요?'),
(9896, '벌침은 구했나요? 손상된 벌침은 저에게 쓸모가 없다는 걸 잊지 마세요.'),
(9897, '크리스틴은 정말 좋은 사람이에요... 자기 피부를 공유해줘서 고마워요, 그렇지 않나요?'),
(9898, '내 운이 곧 바뀔 것 같아. 그런 느낌이 들어.'),
(9899, '정말이지, 그의 마음은 절대 바뀌지 않을 거야. 아무래도 섀도우 헌터 덴자이에게 자브라진으로 다시 전출시켜달라고 부탁해야 할 것 같아.'),
(9900, '돌아왔군, $r. 가바시는 죽었나?'),
(9901, '스포어윙을 찾아내셨나요?'),
(9902, '노예 신세가 된 동족들을 더 많이 도울 수 없다는 사실이 부끄럽습니다. 하지만 적어도 더 많은 불필요한 죽음을 막을 수 있었습니다.'),
(9903, '당신은 늙은 므라게쉬를 "은퇴"시켰나요?'),
(9904, '테러클로는 더 이상 살아있지 않다는 뜻인가요?'),
(9905, '아주 오래전, 막투는 므라게쉬의 가죽으로 튼튼한 갑옷을 만들었을지도 모릅니다. 하지만 므라게쉬는 이제 너무 늙어서 그럴 수 없죠. 가죽도 너무 부드러워서 좋은 갑옷을 만들 수는 없을 겁니다.'),
(9906, '나머지 마을 사람들을 찾기 위해 소규모의 조직적인 수색대를 파견하겠습니다.'),
(9907, '우리가 이 지역에서 만만치 않은 세력이라는 사실을 그들에게 다시 한번 상기시켜야 합니다.'),
(9910, '두려움에서 우러나오는 존경! 다른 어떤 존경 방식 못지않게 훌륭하다.'),
(9911, '그거… 어디서 구했어?'),
(9914, '내가 원하는 건 상아지, 변명이 아니라고요. 물론, 원하신다면 수익 분배 비율을 다시 협상할 수도 있습니다. 하지만 그 결과에 만족하실 것 같진 않네요.'),
(9915, '저는 여전히 이 땅을 배회하는 야생 엘렉의 상아 어금니가 더 필요합니다. 하지만 안타깝게도 제 예산으로는 당신이 가져가는 수익금을 더 이상 감당할 수 없습니다. 그러나 만약 당신이 계속해서 제게 필요한 것을 제공해 주신다면, 당신은 컨소시엄의 환심을 사게 될 것입니다.'),
(9916, '아이들은 배고픔을 느끼지 않고 하루를 보낼 수 있을지도 모릅니다.'),
(9917, '새로운 정보를 찾으셨나요?'),
(9918, '그는 아마 산등성이에서 자고 있을 거예요.'),
(9919, '나한테 보여줄 거 있어, $n?'),
(9921, '우리는 최근에야 텔라르를 되찾았습니다. 다시는 잃지 않을 겁니다!'),
(9922, '분지 속 정령들을 조심하세요, $n.'),
(9923, '저 녀석... 아레크론은 못마땅한 듯 고개를 흔든다. 저 녀석 때문에 내가 죽을지도 몰라.'),
