(9995, '걱정스러운 표정이시네요. 무슨 일이에요, $c?'),
(9996, '보고드립니다. 파이어윙 포인트에서 어떤 소식을 가져오셨나요?'),
(9997, '보고드립니다. 파이어윙 포인트에서 어떤 소식을 가져오셨나요?'),
