(9999, '벌써 돌아오셨네요?'),
(10000, '로카그에게 공격을 권장하는 메시지를 보내려던 참이었는데, 그럴 필요가 없을 것 같네요.'),
(10001, '감독관들을 무슨 수를 써서라도 피하십시오. 그들이 당신의 존재를 알아차리게 해서는 안 됩니다. 그렇지 않으면 끔찍한 결과가 초래될 수 있습니다!'),
(10002, '캠프 내 활동이 계속해서 격화되고 있습니다. 당신은 임무를 완수했습니까?'),
(10003, '그들이 준비할 시간을 오래 줄수록 그들을 뿌리 뽑기는 더욱 어려워질 것입니다. 당신은 그 연결고리를 끊어냈습니까?'),
(10004, '[악마] Ik il romat sardon.'),
