(10009, '살살라빔의 금화를 가져가지 않고는 돌아올 수 없어!'),
(10011, '다 됐나요?'),
(10012, '$n, 당신이 가지고 있는 건 뭐죠?'),
(10013, '$n, 당신이 가지고 있는 건 뭐죠?'),
(10015, '그 코드들 아직 못 구했어? 세나리온 숲에서 드루이드들에게 무슨 일이 일어났는지 봤잖아. 스톤브레이커 요새에도 그런 일이 일어나길 바라는 거야?'),
(10016, '험난한 숲길을 무사히 견뎌내셨군요. 제 망토에 달 꼬리는 가져오셨나요?'),
(10017, '독주머니를 구했습니까, $n? 이 난민들은 더 이상 기다릴 수 없습니다.'),
(10018, '제가 필요한 가죽을 모두 찾으셨나요?'),
(10019, '많은 난민들이 여전히 독에 중독된 상처를 치료받아야 합니다. 제가 사용할 독주머니를 더 가져오셨나요, $n?'),
(10020, '$n, 혈액을 구했습니까? 혈액이 없으면 잘리아는 아들을 다시는 볼 수 없을지도 모릅니다.'),
(10021, '$n님, 임무를 완료하셨나요?'),
