(10023, '그 영혼이 기다리고 있네, $n. 늑대 우두머리의 가죽을 가지고 있느냐?'),
(10024, '보렌탈의 비약을 만들기 위한 바실리스크의 눈을 얻으셨나요?'),
(10025, '보렌탈의 영약 한 방울을 만드는 데에도 수많은 바실리스크 눈이 필요합니다. 더 가져다주시면 예언자들의 호의를 얻을 수 있을 겁니다.'),
(10026, '요새 주변의 워프 스토커들을 모두 제거했습니까?'),
(10027, '케베질은 화염구를 던져도 또 망신당하지 않을지 알고 싶어합니다. (임프가 딸깍거리는 소리를 몇 번 내자 흑마법사가 그를 향해 돌아섭니다.) 아니, 내 그림자 화살이 아니었어! 취소해, 이 덩치 큰 요정아!'),
