(10045, '안녕.'),
(10047, '그 울음소리가 어쩐지 전보다 더 희미해진 것 같다. 빛이 허락한다면 그건 단순한 희망사항이 아닐 것이다.'),
(10048, '왕실 테로모스의 가루를 구했습니까? 충분한 양이 없으면 눈의 마법에서 느껴지는 저항을 뚫을 수 없을 겁니다.'),
(10049, '왕실 테로모스의 가루를 구했습니까? 충분한 양이 없으면 눈의 마법에서 느껴지는 저항을 뚫을 수 없을 겁니다.'),
(10050, '제가 당신에게 부탁드린 것은 누구에게나 끔찍한 일입니다. 하지만 당신이 이해해 주셔야 할 것은 많은 사람들이 폐허 근처에도 가려고 하지 않는다는 것입니다. 기억과 고통이 너무나 생생하기 때문입니다. 하지만 우리는 영혼들이 계속 떠돌아다니도록 내버려 둘 수 없습니다. 그들이 오래 머무를수록 전생과의 남은 연결고리를 끊어내고 악의에 사로잡히게 될 것입니다.'),
