(10057, '폐허에서 장교들을 제압할 수 있었습니까?'),
(10058, '나를 귀찮게 하지 말라고 부탁했잖아요. 무슨 일이에요?'),
(10063, '예?'),
(10064, '예?'),
(10065, '그 지역의 약탈자들을 어느 정도 소탕하셨나요?'),
(10066, '변이된 얽힘들을 제거하는 데 성공했나요?'),
(10067, '더럽혀진 물의 정령들을 쫓아내기 시작했습니까?'),
