(10073, '부패를 완전히 마스터하셨습니까?'),
(10074, '산에서 채취한 결정질 분말이 이 지역의 토양 핵 속에 스며들어 있다.'),
(10075, '이 기지는 나루 수정 연구를 위한 드레나이의 주요 연구 시설이었습니다. 우리가 발견한 것은 ''다이아몬드'' 산, 오슈군에서 나온 수정에 대한 연구 기록으로 가득 찬 보물창고와 같습니다. 이 지역의 모든 것에는 오슈군 수정의 잔여 가루가 묻어 있는 것 같습니다. 이 지역을 탐험하다가 가루를 발견하면 저에게 가져다주세요. 그러면 감사의 표시로 보급관에게서 물건을 구입하는 데 사용할 수 있는 작은 선물을 드리겠습니다.'),
(10076, '산에서 채취한 결정질 분말이 이 지역의 토양 핵 속에 스며들어 있다.'),
(10077, '이 기지는 나루 수정 연구를 위한 드레나이의 주요 연구 시설이었습니다. 우리가 발견한 것은 ''다이아몬드'' 산, 오슈군에서 나온 수정에 대한 연구 기록으로 가득 찬 보물창고와 같습니다. 이 지역의 모든 것에는 오슈군 수정의 잔여 가루가 묻어 있는 것 같습니다. 이 지역을 탐험하다가 가루를 발견하면 저에게 가져다주세요. 그러면 감사의 표시로 보급관에게서 물건을 구입하는 데 사용할 수 있는 작은 선물을 드리겠습니다.'),
(10078, '기분이 좋아 보이시네요. 불타는 호드 공성 무기 덕분에 기운을 되찾으신 건가요?'),
