(10091, '네? 무슨 일로 오셨나요, $c님?'),
(10095, '$N, 그림자 미궁 소식을 가져왔나? 그곳의 위험은 드디어 해결됐나?'),
(10096, '뭐라고? 벌써 돌아왔다고? 어땠어?'),
(10097, '그녀를 찾았나요, $n? 그녀는 아직 건물 안에 갇혀 있었나요?'),
(10098, '테로크의 유물이 스케티스에서 너무 오랫동안 사라졌습니다. 세테크에서 그 유물들을 되찾을 수 있었습니까?'),
(10099, '솔직히 묻기가 두려워요. 당신이 광산에서 살아 나왔다는 건 두 가지 중 하나일 거예요. 그 자식을 죽였거나, 아니면 겁을 먹고 도망쳤거나. 둘 중 어느 쪽이죠?'),
(10106, '$N, 각 요새를 점령하는 데 도움을 준 후에 내게 돌아오시오!'),
(10109, '주유하셨나요?'),
(10110, '각 요새를 점령하는 데 도움을 준 후에 내게 돌아오시오!'),
(10111, '제가 계란을 얼마나 좋아하는지 말씀드렸던가요?'),
(10112, '음, 내 기억력이 좋아지고 있는 걸까?'),
(10115, '대거펜이 무슨 짓을 저질렀는지 봤나? 이제 왜 우리가 그들을 다른 잃어버린 자들과 격리해야 하는지 알겠지.'),
(10116, '족장 무마키의 현상금을 노리고 계신 겁니까?'),
(10117, '족장 무마키의 현상금을 노리고 계신 겁니까?'),
(10118, '대거펜 놈들이 아는 건 오직 신속하고 잔혹한 행동뿐이다. 우리는 그들이 원하는 대로 하게 놔두지 않을 거라는 걸 그들은 알아야 한다.'),
(10120, '당신이 오리온과 이야기하는 걸 봤는데, 중요한 일이었나 보군요...'),
(10123, '마법사와 그의 혈마법사들이 전선에 남아있는 한, 스랄마르는 안전할 것이다.'),
(10129, '첫 번째 시도에서 실패했다면, 다시 시도하세요...'),
(10132, '당신은 그 거대한 위협을 제거했습니까?'),
(10134, '그거 엄청 큰 수정이네요. 능선에서 거상들을 처치하면서 얻으신 건가요? 제가 한번 살펴볼까요.'),
(10136, '운명이 부른다, $n. 잔혹한 아라지우스는 너무 오랫동안 정의의 심판을 피해 왔다. 그의 죽음이 호드에 맞서는 모든 자들에게 경고가 되도록 하라. 다음은 너희 차례다.'),
(10138, '우리가 근원에 거의 다다랐어, $n. 뭘 발견했지?'),
(10140, '무사히 도착해줘서 정말 다행이야. 아너 홀에는 노련한 전사들이 한둘이 아니야.'),
(10142, '궁수들이 하늘을 지켜주는 한, 아너 홀은 안전할 것입니다.'),
(10144, '불꽃놀이를 직접 볼 수 있었으면 좋았을 텐데. 그 폭죽들은 정말 엄청난 위력을 자랑하겠어!'),
(10146, '이건 아주 중요한 임무야, $n. 아무에게나 맡길 수 있는 일이 아니라고 생각해.'),
(10159, '쏜팽 힐을 클리어하려는 당신의 시도는 어떻게 진행되고 있습니까?'),
(10161, '필요한 부품은 충분히 찾았어? 만약 그렇지 않으면, 레가시가 계속 휘두르는 그 프라이팬을 써야 할지도 몰라. 그럼 비행선 이름을 "날아다니는 프라이팬"으로 바꿔야겠군.'),
(10162, '하늘조차 안전하지 않다는 것을 그들에게 보여주세요!'),
(10163, '하늘조차 안전하지 않다는 것을 그들에게 보여주세요!'),
(10164, '술들을 아껴두세요, $n.'),
(10165, '저는 "공유하는 것"을 좋아하지 않아요.'),
(10166, '돌아왔군, $n. 충분히 하지 않았나?'),
(10167, '<도레의 영혼이 콧노래를 부른다.>$B$B안녕하세요, $n.'),
(10168, '이 나루들은 이 세상의 모든 생명체보다 훨씬 더 현명합니다.'),
(10169, '냄비 주변에는 허브와 향신료 냄새가 가득하다.'),
(10172, '<위대한 어머니 게야가 누워 있다.>'),
(10173, '대마법사 바르고스의 지팡이가 그에게 돌아갈 때까지 나는 쉬지 않겠다. 악마의 손아귀에서 그 지팡이를 되찾을 수 있었느냐?'),
(10176, '드디어 만났군요.'),
(10182, '$n, 뭘 찾았어?'),
(10183, '너무 바빠요! 시간 낭비할 틈이 없어요! 로켓을 만들어야 하거든요! 뭘 원하세요?'),
(10184, '우리 동지들을 위해 할 수 있는 일이 너무나 적다는 사실이 너무나 마음 아픕니다.'),
(10185, '마을 유적에서 마나 괴물들을 좀 제거하셨나요?'),
(10186, 'X-52 네더 로켓이 이륙 준비를 마친 것처럼 보이나요? 제가 조종석에 편안히 앉아 뒤틀린 네더를 누비고 있나요? 낯선 신세계를 탐험하고 있나요? 새로운 기술과 사업 기회를 찾고 있나요? 그 어떤 고블린도 가보지 못한 곳으로 용감하게 나아가고 있나요? 아니요! 그러니 제가 보내드린 수정들을 잘 보관해 두셨기를 바랍니다.'),
(10188, '탑의 저주에서 벗어나려면 그 문장을 손에 넣어야 한다.'),
(10189, '$n 님, 제가 부탁드린 물품들을 구해오셨나요?'),
(10190, '그 블래스터 배터리 충전했어?'),
(10191, '벌써 돌아오셨네요? Maxx A. Million Mk. V는 괜찮은 건가요?!'),
(10192, '책 가져오셨어요?'),
(10193, '$n, 잘 지내? 무슨 소식 있어? 최근에 나를 위해 뭘 해줬어?'),
(10195, '당신이 처음 깃털을 가져다주셔서 베르텔름의 모자를 완성한 이후로, 탄더를 포함한 다른 용병들이 모두 자기 모자를 달라고 아우성치고 있어요. 바로 만들어주겠다고 했지만, 이 프로젝트에는 아라코아 깃털이 꾸준히 필요하거든요. 숲에서 모험하며 모아오는 깃털이 있다면 기꺼이 받겠습니다.'),
(10196, '아라코아 정령들을 제게 가까이 끌어들이는 데 어느 정도 성공했지만, 여전히 너무 수줍어합니다. 변장을 더 잘하면 최면 상태에서 제게 더 쉽게 다가올지도 모르겠습니다. 하지만 그러려면 당신이 가져다준 것과 같은 깃털이 더 필요합니다. 깃털을 더 구하게 되면 기꺼이 받겠습니다.'),
(10197, '내가 부탁한 의상 부품들을 구했나요?'),
(10198, '도청은 어떻게 되어가고 있나, $n? 서둘러야겠어. 나도 슬슬 초조해지거든.'),
(10199, '만약 내가 저 지옥 가오리의 침에서 독을 충분히 빼낼 수 있다면, 지금까지 고안된 연료 중 가장 폭발력이 강한 연료를 만들어낼 수 있을 것 같아!'),
(10201, '검사 결과 나왔나요?'),
(10203, '이곳 정말 멋지지 않나요? 매일매일 새롭고 이국적인 풍경이 펼쳐지네요! 우리가 여기를 파헤치다가 마을을 거의 파괴할 뻔했는데, 정말 다행이에요.'),
(10204, '선퓨리 마법사들이 사용한 혈석에 대해 조사해 보셨나요, $n?'),
(10205, '그럼 끝난 건가? 워프 레이더 네사드가 죽은 건가?'),
(10206, '그 기술이 벌써 돌아왔다고? 설마 날 놀리는 건 아니겠지, $c. 여기 X-52 프로젝트의 성공은 네가 그 기술을 최대한 빨리 가져다주는 데 달려있어!'),
(10208, '레기온은 네가 준비한 깜짝 놀랄 만한 일에 전혀 대비하지 못할 거야, 그렇지, $n?'),
(10209, '빙하석을 확보하셨습니까?'),
(10211, '인간의 이야기는 덧없지만, 도시의 이야기는 오랜 세월 동안 지속된다.'),
(10216, '이 기기에는 10개가 넘는 버튼이 있는데, 그중 어느 것도 당신에게 익숙하지 않을 겁니다.'),
(10218, '안녕, 작은 살덩어리 짐승아.'),
(10220, '당신은 불굴의 자들에게 버림받은 자들을 거역하는 것의 결과를 가르쳤습니까?'),
(10221, '닥터 붐의 만행으로부터 우리를 구해줬나요? 이번에는 폭발하는 마차는 없을 거라고 약속할게요. 물론 정말 재밌었지만요! 앞으로 이런 걸 더 자주 해야겠어요.'),
(10222, '다 끝났나, $n? 키린바르 마을의 희생자들을 위한 복수를 했나?'),
(10223, '$n님, 작업을 완료하셨나요?'),
(10224, '그 에센스들을 전부 다 모으셨나요?'),
(10225, '안녕하세요. 제가 지금 좀 바빠서요. 들고 계신 건 뭐예요?'),
(10226, '정령들의 힘을 얻었나요? 아, 서두르지 마세요. 제 목숨과 경력이 걸린 문제니까요.'),
(10229, '이게 뭐지? 불굴의 영혼이 지닌 책인가? 이상하군. 자세히 살펴봐야겠다. 어쩌면 불굴의 영혼의 역사를 알 수 있을지도 몰라.'),
(10230, '우리는 불굴의 자들을 조속히 도와야 합니다. 만약 그들을 설득하여 우리 편으로 끌어들일 수 있다면, 호드는 강력한 동맹을 얻게 될 것입니다.'),
(10231, '뭘 원해?'),
(10232, '불타는 군단과의 싸움을 잘 헤쳐나가길 진심으로 바라네. 약속을 어기는 놈들이나 (콜록) 노움들을 혐오하는 것도 모자라, 악마도 확실히 그중 하나지!'),
(10233, '선퓨리 요새 성벽에서 연기가 피어오르는군. 자네 소행인가?'),
(10234, '그 부품들은 확보하셨나요? 불타는 군단이 이 지역 우리 영토를 하나씩 점령해 오고 있어서 시간이 얼마 남지 않았습니다.'),
(10235, '둠클로는 처리했나요?'),
(10236, '내 파쇄기 부품 좀 찾았어? 빨리 고쳐서 다시 채굴하고 싶어. 어떻게든 먹고 살아야 하잖아. 그래야 부티 베이로 돌아가는 편도 티켓이라도 살 수 있을 텐데.'),
(10238, '내 하인들을 구했나요? 어서요, 잡아먹힐 것 같아요. 맛이 없을지도 몰라요. 정말 맛이 없으면 펠 오크들이 저한테 엄청 화낼 거예요.'),
(10239, '그들의 에너지원을 조금이라도 확보할 수 있었나요?'),
(10240, '룬을 모두 활성화했습니까? 블러드 엘프의 방식을 우리가 어떻게 개선할 수 있을지 정말 기대됩니다. 켈타스의 부하들이 할 수 있는 일이라면, 진정한 키린 토는 그보다 더 잘할 수 있을 겁니다.'),
(10241, '$n님, 임무를 완료하셨나요?'),
(10242, '스파인브레이커 포스트에 오신 것을 환영합니다. 제 재능이 어떻게 도움이 될 수 있을까요?'),
(10243, '눈앞에 스크롤되는 기호들은 낯설고 이해할 수 없어 보입니다.'),
(10245, '$n 님, 당신이 우리에게 가져온 것을 보여주세요.'),
(10246, '$n님, 임무를 완료하셨나요?'),
(10248, '어떻게 생각하세요? 아직 좀 더 손볼 부분이 있죠?'),
(10250, '공성탑 옆에서 뿔피리를 불어보았나? 빨리 해야 해. 스랄마르가 언제 불굴의 전사들을 필요로 할지 누가 알겠어.'),
(10252, '레빅서스의 군대는 시간이 흐를수록 규모와 힘이 커지고 있습니다. 서둘러야 합니다.'),
(10253, '당신은 누구고 무엇을 원하십니까? 아... 바로 당신이군요.'),
(10255, '실험 결과가 있나요?'),
(10257, '핵심을 획득하셨나요?'),
(10261, '제가 올린 구인 광고 때문에 오셨기를 바랍니다!'),
(10262, '다 끝났나? 아웃랜드에서 자시스 놈들을 쓸어버리고 그들의 문장을 가져왔나?'),
(10265, '왕자님이 특정한 수정구를 찾고 있는 것 같은데, 정확히 뭔지는 모르겠어요. 혹시 공포의 군주에게서 그 수정구를 되찾으셨나요?'),
(10267, '당신은 블러드 엘프들이 빚을 지고 떠난 측량 장비를 가지고 있습니까?'),
(10268, '접근하다.'),
(10269, '안녕하세요, 여행자님. 제 물건이 필요해서 하진에 오셨습니까?'),
(10270, '$n 님, 지금 사업 이야기를 나눌 준비가 되셨습니까?'),
(10271, '궁금한 점이 많으실 텐데, 모든 질문에 대한 답변은 적절한 시기에 드리겠습니다.'),
(10272, '달걀을 모으셨나요?'),
(10273, '이 마리드는 바보였어, 아니, 바보였지.'),
(10274, '베라쿠에게 도전하여 물리치셨습니까?'),
(10275, '구매 또는 판매를 원하십니까?'),
(10276, '안녕하세요, 친구. 수정 찾기 노력은 어떻게 진행되고 있나요?'),
(10277, '무슨 일이 일어나고 있는지 최소한 기본적인 이해라도 할 때까지는 돌아오지 마십시오.'),
(10278, '제 실험 장치를 사용해 보셨나요? 제 불안정한 워프 균열 생성기가 심연과 아주 가까운 곳에서는 작동할 것 같습니다.'),
(10280, '$r, 당신이 뭔가 엄청난 힘을 지닌 것을 감지합니다. 당신이 내게 가져다주는 것은 무엇입니까?'),
(10283, '누구세요?'),
(10284, '<에로지온이 고개를 끄덕인다.>'),
(10288, '저기서 듀론과 이야기하는 걸 봤어요. 중요한 임무를 수행 중이시군요!'),
(10289, '오리온에서 온 보고서인가? 빨리 내놔! 젠장, 우리가 우려했던 대로군. 오리온과 그의 전사들은 언제든 포위될 수 있어!'),
(10290, '파라흘라이트를 모으는 데 따르는 위험이 크다는 것을 알고 있지만, 그만큼 기회도 많습니다. 위험을 감수할 의지가 없는 상인이라면 차라리 가게 문을 닫고 고생을 안 하는 게 낫겠죠.'),
(10293, '당신이 아직 살아있다는 건, 핵심을 얻었거나 마음을 바꿨다는 뜻이죠. 둘 중 어느 쪽인가요?'),
(10294, '그럼 해낸 겁니까? 우리가 필요한 조각들을 손에 넣었습니까?'),
(10295, '보이드 바론 갈락시스를 처치하셨나요?'),
(10297, '시간대별로 크로노비콘은 하나만 사용할 수 있습니다.'),
(10299, '$n님, 임무를 성공적으로 완수하셨습니까?'),
(10300, '대마법사의 지팡이에 달 새 머리 장식에 적합한 수정들을 찾으셨나요?'),
(10301, '오큘러스를 복구하셨나요?'),
(10302, '저는 그 이상한 생물들을 상대하는 데 효과적일 것 같은 해결책을 연구하고 있습니다. 다만 시간이 좀 더 필요할 뿐이지요.'),
(10303, '너무 많습니다... 놈들을 줄여야만 살아남은 자들에게 승산이 있습니다.'),
(10305, '$n, 뭘 찾았어?'),
(10306, '$n, 뭘 찾았어?'),
(10307, '$n, 뭘 찾았어?'),
(10308, '컨소시엄은 남쪽의 힙 지역에 있는 자시스 반군을 완전히 소탕하는 데 큰 관심을 갖고 있습니다. $B$B$c, 우리에게 더 잘 보이고 싶다면 그곳으로 다시 내려가서 그들의 연합 휘장을 더 가져오십시오.'),
(10309, '내 시력이 네더의 방사능 때문에 나빠지고 있는 것 같아. 너 펠 리버의 심장은 얻었어?'),
(10310, '어떻게 도와드릴까요?'),
(10312, '레지스트리를 찾으셨나요?'),
(10313, '$n님, 제가 요청한 측정 작업을 하셨나요?'),
(10314, '$n, 무엇을 발견했나요?'),
(10315, '지금까지 네더맨서를 몇 명이나 쓰러뜨렸나요?'),
(10318, '마나포지 아라에서 무슨 소식 가져왔나? 포먼 선다운과는 어떻게 됐나?'),
(10319, '나베리우스를 공격하려면 먼저 그의 부적을 되찾아야 합니다. 그렇지 않으면 그는 무적 상태가 될 것입니다.'),
(10320, '그 비열한 나베리우스의 리치를 처치했습니까?'),
(10321, '$n님, 작업을 완료하셨나요?'),
(10322, '$n님, 작업을 완료하셨나요?'),
(10323, '$n, 내가 부탁한 일을 완료했나요?'),
(10324, '수사슴 가죽은 거칠고 질겨서 고기가 매우 질겨 거의 먹을 수 없지만, 다른 용도로 사용할 수 있습니다.'),
(10325, '당신은 우리 적의 휘장을 지니고 있습니까, $n?'),
(10326, '$C, 당신은 우리 적들의 문장을 더 많이 지니고 있습니까? 불타는 군단은 여전히 위협적인 존재이며, 우리는 그들을 발견하는 곳이라면 어디든 추격할 것입니다.'),
(10327, '혹시 남은 점수가 있다면 제가 다 받아드리겠습니다. 걱정하지 마세요. 당신의 행동은 모두 기록될 것입니다.'),
(10328, 'Manaforge Duro의 브리핑에서 좋은 결과를 얻으셨나요?'),
(10329, '계획은 성공했어? 솔직히 말하면 네가 폭발에 휘말릴 줄 반쯤 예상했었어.'),
(10330, '$n님, 작업을 완료하셨나요?'),
(10331, '제 망치를 찾으셨나요?'),
(10332, '제자의 눈에 눈물이 고인 듯 보인다. 그는 말을 이어갔다. "론수스 스승님을… 처리하셨습니까?"'),
(10334, '소는 당신을 의심스러운 눈으로 바라보지만, 꿋꿋이 자리를 지킵니다.'),
(10335, '정말 빠르시네요. 벌써 세 개의 표식을 모두 설치하셨다니, 정말 효율적인 분이시겠어요.'),
(10336, '파라론 유적에 있는 악마들을 모두 처치했나요?'),
(10338, '종료 작업 완료했나요? 제가 마음을 바꾸기 전에 서두르세요.'),
(10339, '잘했어, 인간아...'),
(10341, '$n님, 임무를 완료하셨나요?'),
(10342, '그 셰일은 충분히 확보했나요? X-52 네더 로켓 연료에 필요한 양의 석유를 추출하려면 셰일이 많이 필요할 겁니다.'),
(10343, '켈타스가 마을을 공격할 때 사용했던 무기의 잔해를 찾았습니까?'),
(10345, '야식스를 찾는 데 성공했나요?'),
(10346, '심연의 선반에는 아직 목표물이 많이 남아있습니다, $n. 다음 탐험을 준비할 때 그리폰을 싣고 가세요.'),
(10347, '군단은 심연의 선반 꼭대기에 있다고 해서 안전하다고 생각해서는 안 된다. 우리는 그들을 끊임없이 공격해야 한다!'),
(10348, '약초는 다 모으셨나요?'),
(10349, '저건 폴른 스카이 리지에 있는 거대한 수정 조각의 일부인가요?'),
(10351, '효과가 있었나요? 무엇을 알게 되었나요? 폴른 스카이 릿지에서 일어난 일의 배후에 누가 또는 무엇이 있는지 알아냈나요?'),
(10352, '만약 당신이 양모 천 60장을 가지고 있고 기증할 의향이 있다면, 지금 바로 제가 받을 수 있습니다.'),
(10353, '인간아, 네 신분은 무엇인가?'),
(10354, '덧붙여 말씀드리자면, 비단과 같은 귀한 선물은 지역 사회에서 당신의 위상을 높이는 데 확실히 도움이 될 것입니다! 만약 비단 천 60장을 가지고 계시고 기증하실 의향이 있으시다면, 지금 바로 제가 받겠습니다.'),
(10355, '샘플을 채취하셨나요?'),
(10356, '만약 당신이 마법직물 60장을 가지고 있고 기증할 의향이 있다면, 지금 바로 제가 받을 수 있습니다.'),
(10357, '$n님, 저희 천 기증 운동에 정말 큰 도움을 주셨습니다. 저희는 재고를 보충하기 위해 열심히 노력하고 있지만, 특히 룬천이 심각하게 부족한 상황입니다. 룬천이 절실히 필요하며, 이전처럼 $n님께서 도움을 주시면 정말 감사하겠습니다!$b$b가능하시다면, 여유가 되시는 룬천을 가져다주시면 감사하겠습니다. 처음에는 60장씩 한 번에 기증해 주시면 되고, 그 후로 더 많은 기증을 받겠습니다.'),
(10358, '룬천 묶음을 제출할 준비가 되면 언제든지 받겠습니다.'),
(10359, '만약 당신이 양모 천 60장을 가지고 있고 기증할 의향이 있다면, 지금 바로 제가 받을 수 있습니다.'),
(10360, '덧붙여 말씀드리자면, 비단과 같은 귀한 선물은 지역 사회에서 당신의 위상을 높이는 데 확실히 도움이 될 것입니다! 만약 비단 천 60장을 가지고 계시고 기증하실 의향이 있으시다면, 지금 바로 제가 받겠습니다.'),
(10361, '만약 당신이 마법직물 60장을 가지고 있고 기증할 의향이 있다면, 지금 바로 제가 받을 수 있습니다.'),
(10362, '$n님, 저희 천 기증 운동에 정말 큰 도움을 주셨습니다. 저희는 재고를 보충하기 위해 열심히 노력하고 있지만, 특히 룬천이 심각하게 부족한 상황입니다. 룬천이 절실히 필요하며, 이전처럼 $n님께서 도움을 주시면 정말 감사하겠습니다!$b$b가능하시다면, 여유가 되시는 룬천을 가져다주시면 감사하겠습니다. 처음에는 60장씩 한 번에 기증해 주시면 되고, 그 후로 더 많은 기증을 받겠습니다.'),
(10363, '룬천 묶음을 제출할 준비가 되면 언제든지 받겠습니다.'),
(10365, '$n, 내가 부탁한 일을 완료했나요?'),
(10367, '열쇠를 얻으셨나요, $n?'),
(10368, '말해봐, $n. 드레그후드 장로들은 석방되었니?'),
(10369, '끝났나요, $n? 아르제스는 죽었나요?'),
(10380, '$n님, 임무를 성공적으로 완수하셨습니까?'),
(10384, '데이터 셀을 복구하셨나요?'),
(10385, '중계 데이터를 복구하셨습니까?'),
(10389, '자, $C님, 테러범들은 패배했나요?'),
(10390, '$C, 빨리 움직여! 악마들이 포지 캠프: 마게돈 건설을 끝내기 전에 폐쇄해야 해!'),
(10391, '저 군단이 언제든 포격을 시작할 수 있어, $n! 저 망할 대포들을 파괴해야 해!'),
(10392, '" 서둘러, $n. 저 워프 포털이 열려 있는 매 순간, 또 다른 사악한 악마가 이 세상으로 소환돼!"'),
(10393, '$C, 나 시간 낭비할 시간 없어. 대체 뭘 자꾸 나한테 하는 거야?'),
(10394, '설마 겁먹은 건 아니겠지, $C? 대장간 캠프 건설이 끝나면 펠 리버보다 더 걱정해야 할 일이 생길 거야! 어서 시작해!'),
(10395, '그게 뭐죠, $c? 뭔가 다가올 재앙을 예고하는 것을 발견한 것 같은 느낌이 드는데요.'),
(10396, '군단이 언제든 호드를 포격할 수 있어! 저 망할 대포들을 파괴해야 해!'),
(10397, '$n, 너 아직 전쟁 포털 안 닫았어? 네가 여기서 발이나 꼼지락거리는 동안, 더 많은 악마들이 아웃랜드로 들어오고 있다고!'),
(10399, '$c, 당신의 마음속에 어둠이 점점 짙어지는 것을 느낍니다. 두려움에 맞섰습니까? 아니면 아고나르의 연못에서 여전히 두려움이 당신을 기다리고 있습니까?'),
(10400, '말해봐, $n, 일이 끝났나? 군단장이 패배했나?'),
(10405, '포장지를 다시 뜯으셨나요?'),
(10406, '그는 반드시 성공해야 한다!'),
(10407, '$n님, 소크레타르의 순간이동석을 얻으셨나요?'),
(10408, '그는... 그는 정말 죽은 건가요? 완전히 파괴된 건가요?'),
(10409, '$C님, 빛이 당신과 함께하길 바랍니다.'),
(10410, '무슨 고민이 있니, 얘야?'),
(10411, '슬러지와 폐기물 모두 극도로 유독합니다. 방치하면 굳어져 끔찍한 덩어리를 형성할 것입니다!'),
(10412, '자, $n. 말해 봐.'),
(10413, '흠, 몰골이 좀 말이 아니네... 대체 무슨 일에 휘말린 거야?'),
(10414, '우리의 대의를 위한 아주 작은 기여라도 소중히 여기겠습니다. 적은 많지만, 우리는 반드시 승리할 것입니다!'),
(10415, '$n, 당신은 최근에 우리를 위해 무엇을 했습니까? 켈타스와의 전쟁은 저절로 벌어지는 게 아니라는 걸 아시잖아요?'),
(10416, '$n님, 혹시 신비로운 책을 얻으셨나요?'),
(10417, '진단 결과 받으셨나요?'),
(10418, '그 동물들을 고통에서 해방시켜 주셨나요? 오해는 마세요, 저는 정말 동물을 사랑하지만, 자신들에게 먹이와 보금자리를 제공해 준 손을 물어뜯는 동물이라면 이야기가 다르죠.'),
(10419, '혹시 신비로운 고서를 더 구했나요, $n?'),
(10420, '혹시 악마의 무기를 구했나요, $n?'),
(10421, '최근에 사악한 무기를 마주친 적이 있습니까? 빛이 제 역할을 하도록 하십시오, $n. 이러한 불결한 물건들이 이 세상에 남도록 내버려 두지 마십시오.'),
(10422, '티랄리우스를 찾으셨나요?'),
(10424, '진단 결과 받으셨나요?'),
(10425, '예?'),
(10426, '돔의 에너지를 집중시켜 보셨나요?'),
(10427, '탈북을 충분히 많이 태그할 수 있었나요?'),
(10429, '그 거대한 히드라에게서 샘플을 채취했나요?'),
(10430, '시제품을 받으신 것 같네요. 가바르가 보내준 건가요?'),
(10432, '그래서? 텔레돈은 뭐라고 했지?'),
(10433, '혹시 저에게 팔 가죽이 있으신가요?'),
(10435, '모든 걸 다 모으셨나요?'),
(10436, '테스트 구역을 정리하셨나요?'),
(10437, '조각을 충분히 모으셨나요?'),
(10438, '목표를 맞혔나요?'),
(10439, '공허의 군주는 어떻습니까?'),
(10445, '당신에게 불가능한 일을 요구했지만, 당신이 성공할 거라고 믿습니다. 많은 것이 거기에 달려 있으니까요.'),
(10446, '메리디안 중위가 파이어윙 포인트의 상황을 계속 알려주고 있습니다. 모든 게 괜찮은 건가요?'),
(10447, '차우니 상사가 파이어윙 포인트의 상황을 계속 알려주고 있습니다. 모든 게 괜찮은 건가요?'),
(10449, '호드의 뜻을 섬길 수 있게 되어 영광입니다. 어떻게 도와드릴까요?'),
(10450, '$n, 뼈를 씹는 자들과 맞섰습니까? 그들의 피가 흥건하게 흘렀기를 바랍니다!'),
(10451, '윌다 수녀님을 찾으셨나요?'),
(10455, '내 말이 사실이 아닌가? 숲을 쫓는 스라소니들은 이곳으로 오는 길목에 있는 이들뿐 아니라 실바나르 그 자체에도 위협이 되고 있다. 그들의 죽음은 안타깝지만, 우리가 살아있는 숲을 만든 근본적인 이유는 실바나르를 자연의 아름다움과 평온함으로 둘러싸인 방어 지역으로 만들기 위함이다.'),
(10456, '썬더로드 다이어울프들을 반드시 처리해야 한다는 점을 아무리 강조해도 지나치지 않습니다. 그들의 존재 자체가 리빙 그로브의 안정과 우리가 이곳에서 이루어낸 모든 것을 위협합니다.'),
(10457, '생명의 숲 방어 시설 강화는 어떻게 진행되고 있습니까? 베일 라쉬에 있는 아라코아의 의도를 알 수 없고, 호드는 바로 협곡 건너편에 있습니다. 우리가 신속하게 움직이지 않으면 새로운 보금자리와 숲에서 우리가 이룩한 업적을 지키기에 매우 어려운 상황에 처하게 될까 두렵습니다.'),
(10458, '이 땅에는 희망이 없을까 두렵습니다.'),
(10464, '$n 님, 계속해서 저희에게 큰 도움을 주셔서 감사합니다.'),
(10465, '$n 님, 계속해서 저희에게 큰 도움을 주셔서 감사합니다.'),
(10466, '$n 님, 계속해서 저희에게 큰 도움을 주셔서 감사합니다.'),
(10467, '$n 님, 계속해서 저희에게 큰 도움을 주셔서 감사합니다.'),
(10468, '돌아왔군. 나와 이야기하고 싶은 게 있나?'),
(10469, '돌아왔군. 나와 이야기하고 싶은 게 있나?'),
(10470, '돌아왔군. 나와 이야기하고 싶은 게 있나?'),
(10471, '돌아왔군. 나와 이야기하고 싶은 게 있나?'),
(10472, '시간이 언제나 당신 편이길 바랍니다, $n.'),
(10473, '시간이 언제나 당신 편이길 바랍니다, $n.'),
(10474, '시간이 언제나 당신 편이길 바랍니다, $n.'),
(10475, '시간이 언제나 당신 편이길 바랍니다, $n.'),
(10476, '자, $n? 말만 번지르르한 거야, 아니면 보여줄 게 있어?'),
(10477, '혹시 추가로 흑요석 전투구슬을 가지고 계신가요, $n?'),
(10478, '$n, 워비즈를 더 구했나요?'),
(10479, '$n, 나한테 보여줄 게 있어?'),
(10480, '나가를 볼 수 있는 곳에는 거의 틀림없이 고통받는 물의 정령도 있을 것입니다.'),
(10481, '머지않아 우리는 영혼들과 대화하게 될 것입니다.'),
(10482, '본체워들이 대량으로 나타났습니다. 그들을 처치하지 않으면 사악한 오크들이 우리를 덮칠 것입니다!'),
(10483, '아너 홀에서 보고드립니다, $n? 좋습니다. 악마와 타락한 오크에 맞서는 우리 작전에 필요한 병력이 부족해지고 있습니다!'),
(10484, '$n, 부적을 가지고 있습니까? 저 저주받은 오크들이 우리 병사들의 휘장을 손에 넣었다는 사실이 너무나 고통스럽습니다...'),
(10485, '모르크의 부서진 갑옷을 가지고 있습니까? 제스고르에게 다시 도전해 보셨습니까?'),
(10486, '우리의 생존은 단순한 블레이드윙 블러드레터가 아니라 진정으로 중요한 적들에게 우리의 역량을 집중하는 능력에 달려 있습니다. 당신이 다시 여기에 있다는 것은, 당면한 문제를 해결했다는 뜻이겠죠?'),
(10487, '동맹군은 우리가 가는 곳마다 따라오려는 것 같군. 그들의 존재에 겁먹지 않는다는 것을 보여줍시다. 제가 부탁드린 물건을 가지고 있습니까?'),
(10488, '썬더로드 다이어 울프의 방어력 강화는 어떻게 진행되고 있습니까?'),
(10489, '그거 들고 있는 거 뭐야? 너 진짜 강하구나!'),
(10492, '$n, 내가 부탁한 물건을 가져왔나?'),
(10493, '$n님, 제가 필요한 물품들을 구하셨나요?'),
(10494, '거래를 진행할 준비가 되셨나요?'),
(10495, '거래를 진행할 준비가 되셨나요?'),
(10502, '우리 정찰병들이 보고한 바에 따르면, 블러드몰 오우거들이 그들의 본거지에서 리빙 그로브로 이어지는 굽이진 길을 따라 올라오기 시작했습니다. 오우거들과 평화롭게 공존할 방법을 찾지 못하는 것은 유감스러운 일이지만, 우리가 언제 그렇게 할 수 있었던 적이 있었단 말인가?'),
(10503, '정찰병들이 보고한 바에 따르면, 블레이드스파이어 오우거들이 그들의 은신처에서 이곳으로 이어지는 굽이길 근처에 진을 쳤습니다. 이 오우거 놈들을 우리 뜻대로 굴복시킬 수 없다는 것이 유감스럽지만, 만약 그들이 싸움을 원한다면 호드는 기꺼이 응해줄 것입니다.'),
(10504, '블러드몰이든 블레이드스파이어든 상관없다. 모든 오우거 부족은 용 사냥꾼 그룰의 총애를 얻기 위해 서로 싸우고 있다. 그 총애가 누구에게 돌아갔든, 비치는 여전히 우리의 적이다.'),
(10505, '블레이드스파이어든 블러드몰이든 상관없다. 모든 오우거 부족은 용 사냥꾼 그룰의 총애를 얻기 위해 서로 싸우고 있다. 그룰의 총애가 누구에게 돌아갔든, 비치는 여전히 우리의 적이며, 우리는 그들을 몰아낼 것이다!'),
(10506, '혹시 뭔가 발견한 사람 있나요? 블러드몰 오우거들 사이에서 이런 일을 하는 건 위험한 일인 건 알지만, 더 이상 동물들이 죽는 걸 막을 수만 있다면 정말 다행일 거예요.');

INSERT INTO `_koKR_stage_quest_request_items_locale` (`ID`, `CompletionText`) VALUES
(10507, '다 됐나요, $n?'),
(10508, '$n님, 소크레타르의 순간이동석을 얻으셨나요?'),
(10510, '정말 신나지 않나요? 실리투스의 온갖 흙먼지와 곤충들을 겪고 나니 이곳은 마치 천국 같아요.'),
(10511, '여기 날씨가 너무 건조해졌네요. 마실 것도 없이 어떻게 휴가를 즐기라는 거죠?'),
(10512, '요즘 어떻게 돼? 블레이드스파이어 오우거들이 블러드몰처럼 무차별적으로 공격하는 거야, 아니면 나처럼 거의 죽을 뻔한 적도 있는 거야?'),
(10514, '그 감자 좀 가져다줘!'),
(10515, '자비는 없다!'),
(10516, '$c, 내 검과 방패를 가지고 있느냐? 언제든 떠날 수는 있지만, 내 장비 없이 실바나르로 돌아가는 건 좀 창피할 것 같구나.'),
(10517, '저 소음은 뭐였지? 고르딤이랑 싸우는 중이었니?'),
(10518, '무슨 일로 저를 찾아오셨습니까? 설마 블러드몰 오우거 일족과 또 문제가 생긴 건 아니겠죠?'),
(10519, '참을성을 갖고 들어주세요, $n.'),
(10522, '혹시 좋은 소식 있으셨나요?'),
(10523, '성공하셨습니까?'),
(10524, '저 아세요?'),
(10525, '무엇을 봤어? 말해줘, 어디 있는지 꼭 알아야 해!'),
(10526, '당신은 이 유물들의 중요성을 이해하지 못하는 게 분명하군. 우리가 이 다섯 개를 모두 손에 넣으면, 죽은 영혼들을 달래서 천둥군주 요새의 소유권을 확보할 수 있을 것이다. 이제 왜 이것이 그토록 중요한지 감이 잡히나? 내가 왜 예의범절을 참지 못하는지 알겠나?'),
(10528, '아르토르가 당신 앞에 힘없이 떠 있습니다.'),
(10537, '두려워하지 마십시오, 영웅이시여. 적절한 시기가 되면 제가 당신을 돕겠습니다...'),
(10538, '$n, 삶은 피 있나요? 이번에는 방해받지 않고 자세히 연구해 보고 싶습니다...'),
(10540, '암호를 복구해야 합니다!'),
(10541, '오로녹의 뺨에 한 줄기 눈물이 흘러내렸다.'),
(10542, '야, 물담배랑 맥주는 준비했어?'),
(10543, '티찰리가 이런 식으로 사는 걸 좋아한다고 생각하세요? 아니죠! 그래서, 제 복수는 끝났나요? 그림녹과 코르가는 죽었나요?'),
(10544, '트찰리는 $n이 부적을 사용하여 블레이드스파이어와 블러드몰 클랜의 건물과 탑들을 저주할 때까지 다시는 말을 하지 않겠다고 했습니다!'),
(10545, '티찰리에게 전해줘... 물약은 효과가 있었나? 블레이드스파이어 오우거들이 좋아했나?'),
(10547, '블러드시슬? 처음 들어보는데… 혹시 평화유지군 소속이세요? 만약 그렇다면 저한테 말씀하셔야죠… 저도 권리가 있단 말이에요!'),
(10548, '인재 영입은 어떻게 진행되고 있나요?'),
(10550, '혹시 피엉겅퀴를 가지고 계신가요?'),
(10555, '낡은 고서 페이지에 새겨진 조잡한 그림문자를 통해, 그 안에 담긴 주문을 시전하려면 많은 양의 라쉬안 깃털이 필요할 것임을 알 수 있다.'),
(10556, '정말 신나네요! 주문의 작동 원리를 어서 살펴보고 싶어요.'),
(10557, '두려워하지 마세요! 이건 과학을 위한 거고, 과학은 고통스러운 과정이니까요!'),
(10562, '$c, 벌써 지쳤어?'),
(10563, '무엇을 발견했나요?'),
(10564, '군단의 지옥 무기고를 파괴할 방법을 찾으셨습니까?'),
(10565, '베크니르 아라코아는 오랫동안 온순했지만, 이제 무언가가 그들을 자극했습니다.'),
(10566, '$n님, 결과를 간절히 기다리겠습니다.'),
(10567, '일단 전조가 당신이 그의 무리를 공격했다는 사실을 알게 되면, 그는 즉시 대응할 것입니다.'),
(10568, '$n, 태블릿을 찾았나요?'),
(10569, '무엇을 발견하셨나요?'),
(10570, '빨리 움직여, 얘야.'),
(10571, '$n, 무슨 소식 있어? 시간이 얼마 안 남았어.'),
(10572, '<당신은 그 자료들을 비행단장에게 건네줍니다.>'),
(10574, '네 개의 메달 조각을 모두 얻으셨나요, $n?'),
(10576, '너무 복잡해, $r. 넌 이해 못 할 거야.'),
(10577, '변장은 매우 섬세하다. 걷는 것을 제외한 거의 모든 행동은 변장을 유지시켜주는 마법을 깨뜨릴 것이다.'),
(10578, '신속하게 행동해야 합니다!'),
(10582, '죽음의 대장간으로 가는 길을 확보했나요?'),
(10583, '죽음의 대장간에서 플라니스의 흔적을 찾았나요?'),
(10584, '우리가 진행 중인 전기 지성체 연구는 정말 흥미진진해요! 생각해 보세요... 우리가 마음대로 만들어낼 수 있고 우리의 모든 지시에 따르는 지능형 전기 생명체라니! 도대체 뭐가 문제될 게 있겠어요?'),
(10585, '우리는 그들의 생산 활동을 계속 용납할 수 없습니다. 소환 의식을 중단했습니까?'),
(10586, '죽음의 대장간에서 무슨 소식을 가져왔나?'),
(10587, '$n, 내가 부탁한 일을 완료했나요?'),
(10588, '다 됐나요?'),
(10589, '우리는 남은 악마들을 모두 없앨 방법을 찾아야 해, $n. 여기까지 왔지만, 실패하면 모든 걸 잃을 수도 있어.'),
(10590, '당신의 무기 아래 재앙이 무너졌습니까?'),
(10592, 'R님, 저에게 주실 게 있으신가요?'),
(10593, '당신이 살아있는 것을 보니, 실바나스 여신으로부터 죽음이 아닌 지혜를 얻는 행운을 누리셨나 보군요.'),
(10594, '제가 부탁드린 노래하는 수정의 측정값을 가지고 계신가요?'),
(10595, '$c, 벌써 지쳤어?'),
(10596, '무엇을 발견했나요?'),
(10597, '<당신은 굴목에게 재료를 건네줍니다.>'),
(10598, '군단의 지옥 무기고를 파괴할 방법을 찾으셨습니까?'),
(10600, '죽음의 대장간으로 가는 길을 확보했나요?'),
(10601, '죽음의 대장간에서 카그로쉬의 흔적을 찾았나요?'),
(10602, '우리는 그들의 생산 활동을 계속 용납할 수 없습니다. 소환 의식을 중단했습니까?'),
(10603, '죽음의 대장간에서 무슨 소식을 가져왔나?'),
(10604, '우리 가운데 군단이 있다는 건 용납할 수 없어! 그들이 다시 공격을 시작하기 전에 반드시 처리해야 해.'),
(10606, '설명서 받으셨어요?'),
(10607, '$n은 무엇인가요? 그들은 그가 무엇을 할 것이라고 생각하는 걸까요? 그들은 그가 그들을 어디로 이끌 것이라고 생각하는 걸까요?'),
(10608, '싱잉 리지에서 수정 조각상들을 모두 제거했습니까? 당신이 그 작업을 완료하지 않으면 제 연구를 시작할 수 없습니다.'),
(10609, '그것들을 가지고 있다고? 내가 연구를 계속하려면 절실히 필요한 드레이크 정수 세 개를 가지고 있다고? 저 네더 드레이크 알들이 원래는 검은 용의 알이었다는 걸 알고 있나? 사실이야! 하지만 드레노어가 산산조각 났을 때, 남은 땅을 휩쓸고 지나간 네더의 액체가 알들을 변이시켰지.'),
(10611, '설명서 받으셨어요?'),
(10612, '돌아왔으니 수술은 잘 된 것 같군. 무슨 보고할 게 있나?'),
(10613, '돌아왔으니 수술은 잘 된 것 같군. 무슨 보고할 게 있나?'),
(10617, '수확에는 빠르고 정확한 손놀림이 필요합니다. 성공하시길 바랍니다.'),
