(10821, '내 소모품 목록에 이름을 올리고 싶은 건가? 열쇠를 챙겨서 둠크라이어를 침묵시켜라!'),
(10822, '우리의 대의를 위한 아주 작은 기여라도 소중히 여기겠습니다. 적은 많지만, 우리는 반드시 승리할 것입니다!'),
(10823, '$n, 당신은 최근에 우리를 위해 무엇을 했습니까? 켈타스와의 전쟁은 저절로 벌어지는 게 아니라는 걸 아시잖아요?'),
(10824, '자, $n. 말해 봐.'),
(10825, '$c, 너도 느껴? 뭔가 비정상적이고 사악한 기운이 근처에 느껴져.'),
(10826, '당신은 우리 적의 휘장을 지니고 있습니까, $n?'),
(10827, '$C, 당신은 우리 적들의 문장을 더 많이 지니고 있습니까? 불타는 군단은 여전히 위협적인 존재이며, 우리는 그들을 발견하는 곳이라면 어디든 추격할 것입니다.'),
(10828, '혹시 남은 점수가 있다면 제가 다 받아드리겠습니다. 걱정하지 마세요. 당신의 행동은 모두 기록될 것입니다.'),
(10830, '나무에 깃든 악이 숲속 모든 자연으로 스며들기 시작했습니다. 모든 것이 파멸하기 전에 서둘러 행동해야 합니다!'),
(10831, '원시 달의 천 샘플을 만드셨나요?'),
(10832, '네더 레이스 샘플을 얻으셨나요?'),
(10833, '당신은 수정의 힘을 사용하여 그림자 제단과의 교감을 심화시켰습니까?'),
(10834, '피 흘리는 골짜기 오크들의 악행은 끝이 없으며, 오직 산산조각난 손 오크들만이 그에 필적할 만하다.'),
(10835, '안녕하세요, $n님. 헬파이어 반도에서의 생활은 어떠신가요? 보람찬 시간 보내셨기를 바랍니다.'),
(10836, '다 끝난 건가요? 너무 늦지 않았기를 바랄 뿐이에요...'),
(10837, '저는 네더바인 결정이 필요합니다.'),
(10838, '점을 보셨나요? 악령 점술가와의 임무는 성공적이었나요?'),
(10839, '어둠이 우리를 에워싸고 있습니다. 베일 스키스에 대해 어떻게 생각하시나요?'),
(10840, '당신은 에테리얼을 몇 마리나 처치했습니까? 그 정도면 빛의 무덤에서 그들을 몰아낼 수 있기를 바랍니다.'),
(10842, '당신은 우리 모두를 구해 주셨습니다. 어떻게 감사를 표현해야 할까요?'),
(10843, '목나탈은 실패를 용납하지 않으며, 변명도 하지 않는다. 적을 물리치거나, 아니면 적이 당신을 죽일 것이다!$B$B네가 내 앞에 서 있는 걸 보니, 이미 그노쉬 브로그낫을 처치했겠군.'),
(10845, '비록 내 눈에는 당신이 더 나은 사람이 되지 못할지라도, 노래하는 능선의 네더 드레이크 어미를 처치하는 도전에 당신이 적합하지 않다는 것을 인정하는 데에는 부끄러울 것이 없습니다. 혹시 당신이 내게 말하려는 게 그거였나요?'),
(10846, '우리에게는 많은 적이 있다. 우리가 선택한 적도 있고, 베크니르처럼 선택하지 않은 적도 있다. 하지만 우리는 그들의 모든 족장을 처치하여 우리 앞에 설 자가 한 명도 남지 않도록 할 것이다.'),
(10847, '돌아왔군요, $c. 무슨 소식을 가져왔나요?'),
(10848, '베일 레이즈에서 악이 자라납니다. 그만둬, $r.'),
(10849, '먼 길을 오셔서 제게 소식을 전해주셨군요.'),
(10850, '연료를 펠 리버에 주입하는 구멍을 발견합니다.'),
(10851, '블레이드스파이어 전초기지에 가서 그들의 토템을 가져왔나요?'),
(10852, '심심해, 같이 놀 사람이 없어. 내 친구들 찾았어?'),
(10853, '노래하는 능선의 수사슴들은 우리에게 위협이 될지도 모르지만, 저는 그들이 정말 위엄 있는 생물이라고 생각합니다. 적어도 예전에는 그랬죠. 부디 그들의 영혼을 지켜주시길 바랍니다. 그리고 토템이 더 필요하시다면, 제가 몇 개 더 드릴 수 있습니다.'),
(10854, '시간 낭비하지 마세요, 할 일이 많습니다!'),
(10855, '$n님, 제가 만든 간단한 실험에 참여해 보셨나요?'),
(10856, '어떻게 지내? 레기온에게 한두 가지 교훈을 줄 기회가 있었어?'),
(10857, '그럼 끝난 건가요? 순간이동 장치는 모두 꺼진 건가요?'),
(10859, '필요한 라자니 빛의 오브를 모두 모으셨나요?'),
(10860, '재료는 다 준비됐어? 너랑 얘기하니까 군침이 도네!'),
(10861, '당신은 당신의 명령을 수행했습니까? 너무 늦기 전에 악을 진압하십시오!'),
(10864, '악마의 예언자는 아직 진정되지 않았다, $n. 산산이 조각난 손 오크들의 영혼을 거두고 나서 내게 돌아오라.'),
(10866, '<카리나쿠가 신음한다.>'),
(10867, '그 일을 해냈습니까? 우리 조상들의 영혼은 영계의 악으로부터 무사히 되찾았습니까?'),
(10868, '아라코아가 $n을 죽인 건 몇 건이나 되나요? 그들은 당신에게서 도망쳤나요? 당신이 그들의 진영을 습격했을 때 도망쳐 숨었나요?'),
(10869, '당신은 아라코아를 몇 마리나 죽였습니까?'),
(10873, '실종된 사람들을 찾으셨나요?'),
(10874, '베일 샬라스는 침묵해야 한다!'),
(10876, '$n님, 카르가스의 손과 맞서 싸워보셨나요?'),
(10877, '공포의 유물을 가지고 있습니까? 우리는 그것이 필요합니다.'),
(10878, '$n, 내가 부탁한 대로 했습니까? 우리 목숨이 위험할까 봐 걱정됩니다.'),
(10879, '지금은 쓸데없는 잡담을 할 때가 아니야, $n. 공격받고 있어! 침략자들을 막아내!'),
(10880, '$n님, 제게 뭔가를 보여주고 싶으신 건가요?'),
(10881, '유물을 회수했습니까, $n? 우리는 그림자 의회가 어둠의 목적을 위해 그들의 힘을 사용하는 것을 용납할 수 없습니다.'),
(10882, '<아달이 당신에게 시선을 고정합니다. 그의 시선은 거의 견딜 수 없을 정도입니다.>$B$B반도르인이여, 당신은 자신의 임무가 얼마나 중대한지 이해하지 못하는 것 같소? 시간을 낭비할 여유가 없소... 동료들을 모아 아르카트라즈로 들어가시오.$B$B하빈저 스카이리스를 처치하시오.'),
(10884, '<아달이 인사드립니다.>'),
(10885, '<아달이 인사드립니다.>'),
(10886, '<아달이 인사드립니다.>'),
(10887, '네, $n?'),
(10888, '<아달이 인사드립니다.>'),
(10893, '그녀가 죽었나요?$B$B$n, 우리가 여기서 승산이 있으려면 드라카 롱테일을 죽여서 적진에 혼란을 일으켜야 해요!'),
(10894, '어떻게 도와드릴까요? 에버그로브 소식을 가져오셨나요?'),
(10895, '시간이 중요해, $n. 저 감시탑들을 불태워야 해!'),
(10896, '가장 심각한 해충 문제는 해결하셨나요?'),
(10897, '정말 괜찮으시겠어요, $n? 물약 제조를 전문으로 하게 되면 다른 전문 분야를 추구할 수 없게 될 거예요.'),
(10898, '무슨 일로 오셨나요?'),
(10899, '정말 변환술의 달인이 되고 싶은 건가요? 이 분야에 특화되면 물약이나 비약 제조에는 특화할 수 없을 거예요.'),
(10901, '곤봉을 다시 만들었으니, 이제 속박에서 벗어나 뱀의 신전으로 돌아가 바쉬와 그녀의 부하들에게 복수하겠다!'),
(10902, '에센스들! 가지고 계신가요?'),
(10904, '포탄은 준비됐나요?'),
(10909, '산산이 조각난 손 오크들의 사악한 영혼은 불쌍한 줄스의 영혼을 괴롭히고 있어. 말해봐, $n... 그가 달래졌는지?'),
(10911, '워프 게이트 두 개를 모두 파괴했나요?'),
(10912, '그럼 모든 게 끝난 건가요? 죽음의 문턱에서 벗어난 건가요?'),
(10913, '이런 부탁을 드리는 게 끔찍한 일인 거 알아요...'),
(10914, '포로를 잡지 마라!'),
(10915, '고대의 악이 다시 힘을 되찾기 전에 반드시 그 악을 없애야 합니다.'),
(10916, '$n, 염주를 찾았나요? 염주의 힘은 많은 성스러운 의식, 특히 퇴마 의식에 매우 중요해요.'),
(10917, '$n, 제가 부탁드린 깃털 가져오셨나요?'),
(10918, '스케티스의 앞잡이들이 여전히 우리 추방자들을 감시하고 있다. 우리 중 누구라도 샤트라스 밖으로 발을 내딛는 순간, 우리는 죽은 목숨이나 다름없을 것이다. 그들을 물리쳤다는 증거로 깃털을 더 가져오너라.'),
(10919, '페이페이가 당신을 기대하는 눈빛으로 바라봅니다...'),
(10920, '내 혈관에 독이 흐르는 게 느껴져. 나루가 나를 부르고, 빛이 보여. 공포의 송곳니 과부들은 패배했는가?'),
(10921, '테로카란툴라가 죽었나요?'),
(10922, '$Gsonny:missy;, 일이 끝나면 돈을 받게 될 거야.'),
(10923, '저주받은 테리부스는 테로카르의 하늘에서 완전히 사라졌습니까?'),
(10924, '제핏이 내가 필요한 피를 다 얻을 수 있을 만큼 충분히 협조했나요?'),
(10927, '나는 센티넬 문위스퍼에게 직접 명령을 내리라고 분명히 말했는데, 당신은 그 명령을 따르지 않고 있는 겁니까?'),
(10928, '나는 그런트 그라크에게 직접 명령을 내리라고 분명히 말했는데, 당신은 그 명령을 따르지 않는 겁니까?'),
(10929, '땅을 파다가 튀어나온 건 사실 애벌레였던 것 같아요!'),
(10930, '친구와 함께 가세요!'),
(10935, '은둔자 바라다(Barada, $n)에게 가십시오. 대령을 구하려면 그가 의식을 성공적으로 수행해야 합니다.'),
(10937, '훈련교관이 죽었나? 흠, 내 정찰병들이 틀렸을지도 모르겠군.'),
(10938, '축복 카드 덱을 완성하셨군요! 축하드립니다!'),
(10939, '폭풍 카드 덱을 완성하셨군요! 축하드립니다!'),
(10940, '퓨리 덱을 완성하셨군요! 축하드립니다!'),
(10941, '루나시 덱을 완성하셨군요! 축하드립니다!'),
(10946, '일이 끝났나, $n? 일리단은 참을성이 없는 주인이야!'),
(10947, '$n님, 부적함을 찾으셨나요?'),
(10957, '네, $n?'),
(10959, '네, $n?'),
(10961, '약재는 가져왔나요? 제게 꽃가루가 묻지 않도록 조심해 주세요. 꽃가루만 닿으면 재채기가 멈추지 않아요. (모르티스는 재채기가 얼마나 수치스러운 일인지 생각하며 코를 킁킁거렸다.)'),
(10962, '시간의 동굴에 대한 이야기가 사실이라고 생각하세요?'),
(10963, '시간의 동굴에 대한 이야기가 사실이라면, 그곳은 엄청난 힘을 지닌 장소임에 틀림없다.'),
(10964, '당신은 잠든 $C에게 물약을 투여할 준비를 합니다.'),
(10965, '서둘러, $r. 만약 이 괴물들이 무덤에서 탈출한다면, 클린타르 드림워커만 위험에 처하는 게 아닐 거야.'),
(10966, '다시 만나서 반갑습니다, C님. 도르나 양과 즐거운 시간을 보내셨기를 바랍니다.'),
(10967, '다시 만나서 반가워요, $C. 당신과 어린 살란드리아가 즐거운 시간을 보냈기를 바라요.'),
(10970, '혹시 좋은 소식 있으셨나요?'),
(10971, '혹시 식별표를 회수하셨나요?'),
(10973, '무리한 부탁인 건 알지만, 얼마나 많은 생명을 구할 수 있을지 생각해 보세요!'),
(10974, '성공하셨군요! 혹시 좋은 결과 있으셨나요?'),
(10975, '$n, 지금 우리는 교착 상태에 빠졌습니다. 당신이 수집한 데이터 덕분에 네더스톰의 작은 감옥에 갇힌 우리 동맹들을 구할 수 있는 충분한 정보를 얻었지만, 바시르의 착륙지에서 더 큰 이더리움 위협을 제거해야 합니다.$b$b이더리움과의 전투에 참여하십시오! 이더리움 감옥 열쇠를 제게 가져오면 바시르의 정지실에서 사용할 수 있는 이더리움 정지실 열쇠를 만들어 드리겠습니다.'),
(10976, '이것이 당신에게 가장 어려운 과제가 될 것입니다, $n.'),
(10977, '$n님, 더 이상 진행하지 않으셔도 이해하겠습니다.'),
(10978, '클린타르가 유물을 되찾는 데 도움을 줬나요?'),
(10980, '<아르토른이 희망에 찬 눈빛으로 당신을 바라봅니다.>$B$B그 책에 대한 정보를 좀 찾으셨나요?'),
(10981, '오직 가장 굳건하고 전투 경험이 풍부한 모험가만이 내 제안을 받아들일 수 있을 것이다, $n. 마나 무덤의 두 번째 정지실의 공포에 맞서고 싶다면, 내가 열쇠를 합성해 줄 수 있다. 넥서스 왕의 표식을 가져오면 그렇게 해 주겠다.'),
(10985, '<시리는 당신의 존재를 알아차렸습니다.>'),
(10987, '매를 한 마리 잡으셨나요?'),
(10988, '내가 ''까마귀의 책''을 복원할 수 있을 만큼 충분한 부분을 복구했나요?'),
(10990, '<매가 아르토른의 목소리로 말하는 것 같군요.>$B$B독수리 영혼의 정수를 해방하는 데 성공했나요?'),
(10991, '<다시 한번, 아르토른의 목소리가 참매의 입에서 흘러나온다.>$B$B매의 정수를 가지고 있습니까?'),
(10992, '매의 수호자를 물리치고 그 정수를 얻었습니까?'),
(10993, '아르토른의 소식을 기다리고 있었어요. 무슨 소식을 알아냈나요?'),
(10994, '꽤 힘든 일을 겪으신 것 같네요. 월장석 찾기가 정말 그렇게 어려웠나요?'),
(10995, '그룰록은 더 이상 존재하지 않는 건가요?'),
(10996, '상자가 있나요?'),
(10997, '슬라그의 깃발을 손에 들고 돌아오는 건가?'),
(10998, '당신은 사악한 빔골을 소환하여 그의 죽은 손아귀에서 마법서를 빼앗았습니까?'),
(11000, '스컬록의 영혼을 가져갔습니까?'),
(11001, '세테크 홀에서 무슨 소식 있어? 안즈를 물리쳤어?'),
(11002, '내가 기억하는 한, 처음으로 정적이 흘렀다.'),
(11003, '내가 기억하는 한, 처음으로 정적이 흘렀다.'),
(11004, '먼지를 구했나요, $n?'),
(11005, '일이 끝났나, $n? 부상만 아니었으면 내가 직접 저 망할 새 인간들을 죽였을 텐데.'),
(11006, '지휘관은 정신착란이 아니었던 것 같군. 먼지를 더 가져오면 영약을 하나 더 만들어 주겠다.'),
(11007, '내 목소리 들었어? 응...'),
(11008, '과제 다 끝냈어?'),
(11010, '저들이 쌓아놓은 지옥의 포탄들을 다 제거했나요?'),
(11013, '늦었잖아...'),
(11015, '네더 수정은 여러 가지 용도로 사용됩니다. 주로 무기와 갑옷을 만드는 데 쓰이죠.'),
(11016, '우리는 가죽 벗기는 데 사용하는 가죽을 갑옷 안감과 구조용 방수포에 사용합니다.'),
(11017, '앞서 말했듯이, 네더스트 꽃가루는 우리 마법사들이 사용합니다.'),
(11018, '저기 있는 구그가 그 광석을 이용해서 우리 무기와 갑옷을 강화할 거야.'),
(11020, '그건 더러운 일이야, $n.'),
(11021, '제게 보여주실 게 있으신가요?'),
(11023, '폭격 임무는 어떻게 진행되고 있나요?'),
(11024, '너한테서 스케티스 냄새가 나잖아! 설명 좀 해봐!'),
(11025, '파편과 수정에 대해 이해하게 되면, 우리 자신과 아래에 있는 오우거 동족을 보호하는 데 더 큰 도움을 줄 수 있을 겁니다. 이 파편들은 한때 이곳 산꼭대기에 살았던, 지금은 멸종한 고대 아라코아 문명의 이름을 따서 지어졌습니다. 파편들을 가지고 있습니까?'),
(11026, '추방의 수정구를 사용해서 불타는 군단 녀석들을 전부 쫓아내셨겠죠?!'),
(11027, '저 캠프의 악마들이 항상 순간이동 장치를 고쳐놓지. 가크가 이번엔 제대로 박살내라고 했어! 하지만 가크는 수정 단조 다크룬을 만들려면 다크룬이 하나 더 필요해. 만약 꼬맹이가 다크룬이 없다면 크론크에게 말을 걸어봐. 크론크는 매일 다크룬 하나씩 만들려고 노력해! 어쩌면 네 보물상자에서 하나 얻을 수도 있을 거야!'),
(11029, '그 책, $n입니다. 구하셨습니까?'),
(11030, '그 마법의 물약은 구했나요? 어린 토르쿠스 주니어에게는 정말 소중한 물건이 될 거예요.'),
(11031, '이전 선택을 번복하기로 하셨군요? 제가 도와드릴 수 있을 것 같습니다. 결국 달라란은 당신이 어떤 방식으로 충성심을 표현하든 그보다 당신의 충성심을 더 중요하게 생각하니까요. 하지만 비용은 만만치 않을 겁니다. 그리고 물론, 당신의 예전 반지를 돌려주셔야 합니다.'),
(11032, '이전 선택을 번복하기로 하셨군요? 제가 도와드릴 수 있을 것 같습니다. 결국 달라란은 당신이 어떤 방식으로 충성심을 표현하든 그보다 당신의 충성심을 더 중요하게 생각하니까요. 하지만 비용은 만만치 않을 겁니다. 그리고 물론, 당신의 예전 반지를 돌려주셔야 합니다.'),
(11033, '이전 선택을 번복하기로 하셨군요? 제가 도와드릴 수 있을 것 같습니다. 결국 달라란은 당신이 어떤 방식으로 충성심을 표현하든 그보다 당신의 충성심을 더 중요하게 생각하니까요. 하지만 비용은 만만치 않을 겁니다. 그리고 물론, 당신의 예전 반지를 돌려주셔야 합니다.'),
(11034, '이전 선택을 번복하기로 하셨군요? 제가 도와드릴 수 있을 것 같습니다. 결국 달라란은 당신이 어떤 방식으로 충성심을 표현하든 그보다 당신의 충성심을 더 중요하게 생각하니까요. 하지만 비용은 만만치 않을 겁니다. 그리고 물론, 당신의 예전 반지를 돌려주셔야 합니다.'),
(11035, '죽은 오크는 아무 말도 하지 않아, $n. 드래곤마우 수송기가 탈출하지 못하게 해.'),
(11036, '저거 올드 오록에서 온 배달품인가요?'),
(11040, '저 상자는 마치 노움 장인이 만든 것처럼 보이네요. 보시가 보낸 건가요?'),
(11041, '누가 감히 모르고르에게 접근하는가? 이건 분명 중요한 일일 것이다.'),
(11049, '부활절 달걀 찾기는 어떻게 진행되고 있나요?'),
(11050, '그 달걀들이 잘못된 사람들의 손에 들어가는 걸 원치 않아, $N. 혹시 더 발견한 달걀이 있으면 가져와. $B$B단, 눈에 띄지 않게 행동하고 의심을 사지 않도록 조심해야 해!'),
(11051, '당신처럼 노련한 전문가라면 악마를 쫓아내는 데 어려움을 겪을 리가 없죠. 당신은 아무 어려움도 없는 거죠, 그렇죠, $r?'),
(11052, '아달은 당신이 다가오는 것을 알아차리고 따뜻한 빛이 당신을 감쌉니다. 아달은 당신이 그에게 줄 무언가가 있음을 아는 듯합니다.'),
(11054, '훈육해야 할 하인들이 있어, $n! 서둘러!'),
(11055, '모든 건 손목에 달려있어, $n.'),
(11056, '돌아왔군요, $n. 당신이 저를 포기한 줄 알았어요.'),
(11058, '아펙시스 유물 사용법을 익혔습니까? 우리와 북쪽에 있는 샤타리 스카이가드 모두 당신이 그것에 대해 알게 된 것에 관심이 있습니다.'),
(11059, '우리는 폭력을 혐오하지만, 적어도 우리가 당신을 보낸 대상은 살아있는 생명체가 아닙니다. 그런데, 머리는 가지고 있습니까?'),
(11060, '악마들이 분노의 대장간 캠프를 점점 더 크게 만들고 있어. 곧 너무 커져서 우리를 짓눌러 버릴 거야. 네가 먼저 놈들을 짓밟아 버려! 샤르툴의 순간이동 장치가 열쇠지만, 마법 방패와 디그레이더라는 악마가 지키고 있어. 우리는 강력한 힘을 가지고 있고, 디그레이더를 조종할 수 있는 특별한 어둠의 룬을 만들 수 있어. 네가 가크에게 어둠의 룬을 주면, 우리는 너에게 수정으로 단조된 어둠의 룬을 돌려줄게. 디그레이더를 조종해서 문을 통해 들어오는 악마들을 최대한 많이 조종해서 막아내!'),
(11061, '저 마법사의 물약은 분명 우리 아들들을 지금보다 더 똑똑하게 만들어 줄 거야. 그러면 샤타리 스카이가드에 들어가면 해야 할 일들을 수행하는 데 엄청난 도움이 될 테지.'),
(11065, '에테르 광선 좀 구해다 줄 수 있나? 밧줄 다루는 솜씨가 꽤 괜찮아 보이니, 금방 구할 수 있을 것 같군.'),
(11066, '$n님, 정말 수고 많으셨습니다. 신선한 마운트를 꾸준히 공급해 주셔서 진심으로 감사드린다는 말씀을 전하고 싶습니다!'),
(11067, '트로프는 내 최고의 라이더 몇 명을 패배시켰다. 겉모습에 속지 마라.'),
(11070, '멀버릭은 내가 본 기수 중 가장 뛰어난 실력을 지녔다. 그가 오크 최고 자리에 오르지 못하는 유일한 이유는 그의 무모함 때문일 뿐이다.'),
(11071, '2등도 나쁘지 않아, $n. 멀버릭 자리를 네가 차지해도 돼...'),
(11072, '$n님, 임무를 완료하셨나요?'),
(11073, '끝났나요, $n? 테록은 패배했나요?'),
(11074, '테록의 가장 강력한 적들의 후손들로부터 각각 토큰 하나씩을 받아야 한다. 그래야만 테록을 소환할 준비가 될 것이다.'),
(11076, '화물을 다 모으셨나요?'),
(11077, '그 가죽벌레 침입 문제는 어떻게 되어가고 있나요?'),
(11078, '임무는 어떻게 진행되고 있나, $n? 이 임무가 우리가 이 하늘에서 계속 비행할 수 있도록 하는 데 얼마나 중요한지 굳이 말할 필요는 없겠지.'),
(11079, '너 채찍 있어?'),
(11080, '당신 주변에 정점 유물의 기운이 느껴지십니까?'),
(11081, '이게 뭐지?'),
(11082, '그래서? 왜 이렇게 오래 걸리는 거야?'),
(11083, '문제가 "해결"되었습니까?'),
(11085, '네, $n?'),
(11086, '결국 악마들을 아웃랜드에서 몰아내고 그들의 차원문을 닫으신 분은 바로 우리 주님이시니, 모두가 일리단의 위대함에 경의를 표해야 마땅하다.'),
(11089, '영혼의 대포를 제작하는 데 필요한 부품들을 모두 모았습니까?'),
(11090, '다 됐나요?'),
(11093, '돌아왔구나! 네 가오리는 잘 지냈니?'),
(11094, '진정해, 얘야.'),
(11095, '<홉이 고개를 끄덕인다.>'),
(11096, '$n님, 임무를 완료하셨나요?'),
(11097, '사령관님, 그들을 발로 짓밟으셨습니까?'),
(11098, '$glad : 아가씨, 저한테 줄 거 있어요?'),
(11099, '진정해, 얘야.'),
(11100, '<아르쿠스가 고개를 끄덕인다.>'),
(11101, '사령관님, 그들을 발로 짓밟으셨습니까?'),
(11102, '저들이 쌓아놓은 지옥의 포탄들을 다 제거했나요?'),
(11103, '반지에 깃든 힘은 변형 가능하지만, 선택을 되돌리는 것은 쉽지 않습니다. 현재의 형태를 정말로 바꾸고 싶으신가요?'),
(11104, '반지에 깃든 힘은 변형 가능하지만, 선택을 되돌리는 것은 쉽지 않습니다. 현재의 형태를 정말로 바꾸고 싶으신가요?'),
(11105, '반지에 깃든 힘은 변형 가능하지만, 선택을 되돌리는 것은 쉽지 않습니다. 현재의 형태를 정말로 바꾸고 싶으신가요?'),
(11106, '반지에 깃든 힘은 변형 가능하지만, 선택을 되돌리는 것은 쉽지 않습니다. 현재의 형태를 정말로 바꾸고 싶으신가요?'),
(11108, '정말 흥미진진한 모험을 하셨군요, $n님.'),
(11117, '그 꼬맹이들을 볼 정도로 취했었나?'),
(11118, '그 성가신 분홍색 엘렉들은 이제 없어졌나요?'),
(11120, '우리 얘기했던 그 작은 문제 해결됐어?'),
(11122, '맥주통이 필요해! 자, 뭘 기다리고 있는 거야!?!'),
(11126, '당신은 테라모어에서 탈영한 요원들을 몰아냈습니까?'),
(11128, '나머지 선전 전단들을 찾아서 확보하셨나요?'),
(11129, '카일을 찾았나요?'),
(11130, '$c님, 거기에 무엇을 가지고 계신가요?'),
(11131, '$N, 당신은 아이들을 구해주겠다고 약속했잖아요!'),
(11132, '아, 맞다, $n이군요? 제 지도는 되찾으셨나요?'),
(11133, '병영에서 웃음소리가 들리는 것 같았어요. 제가 드린 전단지를 나눠주셨나요?'),
(11134, '탈영병 기지에 대한 공격을 완료하셨습니까?'),
(11137, '그들의 우두머리를 찾아낼 수 있었나요?'),
(11138, '반갑습니다, $C님. 무슨 일로 오셨나요?'),
(11139, '데피아 가문에서 뭘 "빌려왔는지" 한번 볼까요?'),
(11140, '잔해 수색에서 데피아스 화물에 대한 단서를 찾았습니까?'),
(11144, '주문서의 흔적을 찾을 수 있었나요?'),
(11145, '블랙후프 마을의 포로들을 구출하는 데 성공하셨나요?'),
(11146, '그 맹금류들을 포획했나요?'),
(11147, '블랙후프 마을에 맹금류를 풀어놓았나요?'),
(11148, '그 무기들은 블랙후프 마을에서 얻은 건가요?'),
(11150, '그 손전등을 제대로 활용해 보셨나요?'),
(11152, '화환을 놓으셨나요?'),
(11153, '우리가 다시 얘기하는 거야? 그럼 네가 해냈다는 뜻이겠지! 그 썩어빠진 북해 해적들에게 본때를 보여줬다는 거잖아! 그렇지?'),
(11154, '혹시 다크클로 구아노를 가지고 계신 건 아니겠죠?!'),
(11155, '삽상어의 옆구리에서 발라낸 부드러운 고기만큼 훌륭한 것은 없습니다!'),
(11156, '그림토템의 공격을 막는 데 진전이 있었습니까?'),
(11157, '당신의 노력은 어떻게 진행되고 있나요?'),
(11158, '<브로그가 희망에 찬 눈으로 당신을 바라봅니다.>$B$B브로그 깃털을 가져오셨나요?'),
(11159, '브로그는 알아야 해, 스톤몰의 사나운 영혼들에게 평화를 가져다주었는가?'),
(11160, '스톤마울 배너 가져오셨나요?'),
(11161, '정수를 가지고 있습니까? 브로그는 친구들의 복수를 위해 그것들이 반드시 필요합니다!'),
(11162, '브로그는 복수할 것이다!'),
(11164, '서둘러, 친구! 내가 곧 그 송곳니를 주지 않으면 버드가 날 줄아만으로 혼자 보내서 자기 가면을 시험해 보게 할 거야!'),
(11166, '제가 손수 만든 변장이 줄아만에서 당신을 충분히 보호해 주었을 거라고 믿습니다.$B$B그 지역들을 정찰해 보셨나요? 아니면 제가 당신의 후임자를 찾아야 할까요?'),
(11167, '컨테이너를 구하셨나요, $n?'),
(11168, '$n, 내가 찾는 독샘을 구했나?'),
(11169, '토템 테스트에서 뭔가 성과를 거두셨나요?'),
(11170, '돌아왔군요!'),
(11171, '다이드쓰리엑스, 내가 자네에게 준 기회의 소중함을 알아주길 바라네.$B$B늙은 말라크라스는 이제 처리했나?'),
(11173, '그 독액은 얻었나? 몰란은 곧 독액이 사라진 걸 알게 될 거야...'),
(11174, '그 끈적거리는 괴물들을 처리하는 데 진전이 있었나요?'),
(11178, '또 너야...? 달리 어떻게 말해야 할지 모르겠네. 난 준비하느라 너무 바빠서 더 이상 네 손을 잡아줄 여유가 없어. 믿어줘, $n, 다 잘 될 거야. 어쩌면 기적처럼 네가 언젠가 이름을 떨치게 될지도 몰라. 그렇게 된다면, 넌 비할 데 없는 버드 네드렉 덕분에 시작했다고 말할 수 있을 거야!'),
(11180, '이곳을 떠도는 영혼들로부터 무엇을 배웠나요?'),
(11181, '그 약초를 조금이라도 모으셨나요? 이 재앙의 배후에 있는 악의 세력이 이 지역을 완전히 장악하기 전에 서둘러야 합니다.'),
(11182, '꼬마야, 간섭하는 관리자들에 맞서 싸운 노력은 얼마나 잘 됐니?'),
(11183, '끝난 건가요?'),
(11184, '꽤 만족스러워 보이시네요. 저 무시무시한 랩터에 걸린 현상금을 받으러 오셨나요?'),
(11185, '$C, 당신이 들고 있는 건 뭐죠?'),
(11186, '$C, 당신이 들고 있는 건 뭐죠?'),
(11188, '선장께서 당신에게 원시 용들을 자극하라고 시키신 것은 유감스러운 일입니다. 비록 우리가 아는 용들만큼 지능이 높지는 않지만, 그래도 그들은 고귀한 생명체인 것 같습니다. 게다가 이로 인해 우리가 처한 상황도 심각합니다. 혹시 이 문제를 해결하셨는지 여쭤봐도 될까요?'),
(11190, '여기 탄약이 거의 다 떨어졌어, $c. 우리 적들을 박살내야 해, 특히 스콘! 우리한테 줄 탄약 좀 더 있어?'),
(11192, '탈곡기용 기름을 좀 구할 수 있었나요?'),
(11193, '오늘은 뭘 드시겠어요? 스누크가 꽤 맛있네요.'),
(11195, '야, $n! 버드 패거리에 들어간다는 소문 들었어. 그 선택 절대 후회 안 할 걸, 친구. 그거 뭐 들고 있어?'),
(11196, '이 새로운 군벌은 잔달라리 세력이 이곳에 영구적으로 발판을 마련하기 전에 반드시 쓰러져야 한다.'),
(11198, '보고서를 작성하세요.'),
(11200, '블랙후프 마을을 검색해 보니 무엇이 나왔나요?'),
(11201, '주문서의 흔적을 찾을 수 있었나요?'),
(11202, '여기서 멀리 떨어져 있어서 아래쪽에서 무슨 일이 벌어지고 있는지 정확히 알기는 어렵네요. 전염병 탱크들을 불태우는 데 성공했나요?'),
(11205, '그 손전등을 제대로 활용해 보셨나요?'),
(11207, '<목시는 걱정으로 안절부절못하는 표정이다.>$B$B화물은 무사했나요? 혹시라도 찾은 게 있나요?'),
(11208, '예?'),
(11209, '명심해, 조건은 "뭔가에 물릴 때까지 돌아오지 마"야.'),
(11217, '혹시 웜테일을 찾으셨나요?'),
(11218, '이곳 공사는 끝이 없는 것 같습니다. 저희가 공사를 계속할 수 있도록 필요한 것을 지원해 주시길 바랍니다.'),
(11219, '호드의 아이들이 당신의 도움이 필요합니다! 그들을 버리지 마십시오!'),
(11221, '보고서 가지고 돌아오셨나요, $n?'),
(11224, '이건 우리 노력에 큰 타격이야. 도대체 뭘 발견했는지 알고 싶지도 않아. 상상만 해도 밤에 잠이 안 올 정도야.'),
(11227, '이 녀석 밥은 줬어?'),
(11231, '걀레르브론의 죄수들이 풀려나면 브리쿨은 더 이상 불경스러운 의식을 행할 수 없을 겁니다. 당신이 그들을 막을 유일한 희망입니다.'),
(11232, '대포는 $n입니다. 누가 저것들을 관리해 줄 건가요?'),
(11233, '동맹 지도자들이 죽었습니까, $n? 그들이 죽을 때까지 돌아오지 마십시오.'),
(11236, '$c, 당신이 메젠과 그의 네크로로드들을 정말로 죽인 게 맞나요?'),
(11237, '뭐라고?! 요새 공격 계획이라고? 서리 용이라니?!!!'),
(11238, '공격은 막아냈습니까? 서리 용과 그 주인은 처치했습니까? 뿔피리를 되찾았습니까?'),
(11239, '성스러운 빛은 당신의 행동과 모든 사물 속에 흐릅니다. 어떤 피조물도, 어떤 장소도, 아무리 사악하더라도 그 진노를 피할 수 없습니다!'),
(11242, '나한테 줄 거 있어? 좋은 거 있어?'),
(11243, '세계의 운명이 우리에게 달려 있을지도 모릅니다.'),
(11244, '그 정찰병들을 찾아내세요!'),
(11245, '저 탑들에 너무 가까이 다가가는 건, 마법사들이 위에 있는 한 확실한 죽음이나 마찬가지야.'),
(11246, '한 가지 확실한 건, 우리가 저 거물들을 쓰러뜨린 후에 그들이 다시 일어나는 모습을 보고 싶지 않다는 겁니다!'),
(11247, '건물에 불을 지르실 때, 그 안에 너무 오래 머물지 않는 것이 좋겠습니다.'),
(11249, '네? 무엇을 도와드릴까요, 얘야?'),
(11250, '당신이 여기 계신 걸 보니 스콘은 더 이상 존재하지 않는 것 같군요?'),
(11252, '$n, 잘 지내시는 것 같아 다행입니다. 저희는 감당할 수 있는 만큼의 사상자를 냈습니다.'),
(11254, '$c, 나한테 보여줄 거 있어?'),
(11255, '$n, 좀 단호하게 행동해! 사람들의 목숨이 걸린 문제라고!'),
(11257, '이 브리쿨족은 이상한 풍습을 가지고 있지 않나요, $n?'),
(11258, '건물에 불을 지를 때는 안에 머물지 않는 것이 좋겠습니다. 불의 정령은 파괴하려는 갈증 때문에 우리를 가만두지 않을 것입니다.'),
(11259, '저 탑들에 너무 가까이 다가가는 건, 마법사들이 위에 있는 한 확실한 죽음이나 마찬가지야.'),
(11260, '네? 무엇을 도와드릴까요, 얘야?'),
(11261, '스콘에 대한 소식은 무엇인가요, $n 님?'),
(11262, '말하자면, 이것은 빙산의 일각에 불과합니다.'),
(11263, '걀레르브론에서의 경기는 어떻게 진행되고 있나요?'),
(11265, '걀레르브론 수용소의 죄수들이 풀려나면서 브리쿨은 더 이상 자신들의 의식을 행할 수 없게 되었습니다.'),
(11266, '뭐라고?! 우리 진영을 공격할 계획을 세웠다고? 하늘의 거대한 용이 그런 계획을 세웠다고?!!!'),
(11267, '공격은 막아냈습니까? 거대한 죽음의 용과 그 주인은 처치했습니까? 뿔피리를 되찾았습니까?'),
(11268, '걀레르브론에서 좀비들을 소탕했나요?'),
(11269, '그거 좀 가져다 놓으셨어요? 저한테 정말 필요할 것 같은데요...'),
(11270, '네가 전에 거인이나 용, 코볼드를 몇 마리나 죽였는지는 상관없어. 이 일을 끝내고 다시 와.'),
(11271, '솜털을 좀 모으셨나요?'),
(11272, '다시 만나서 반갑습니다, $n. 혹시 아직 그 괴물 엘프를 처치하지 못했다면, 나라면 어서 가보는 게 좋겠군.'),
(11275, '적당한 뿔피리를 가져오셨나요?'),
(11277, '구석구석 꼼꼼히 확인하세요!'),
(11278, '돌아왔군요!'),
(11279, '그 샘플들이 없으면, 이 최신 변종 흑사병 바이러스가 모든 종류의 생물에게 적용될 수 있는지 어떻게 알 수 있겠습니까?'),
(11280, '자, 이제 말해 보자! 우리 실험은 성공했을까?$B$B초기 드레이크는 간식을 맛있게 먹었을까? 속에서부터 녹아내렸을까?'),
(11281, '그 경적 시험해 볼 기회 있었어?'),
(11282, '브리쿨들을 처치했나요? 정말 강하네요!'),
(11283, '살인은 이제 끝났나? 윈터스콘 마을은 바로 여기 맞은편에 있어!'),
(11285, '다 태우셨나요? 혹시라도 안 탄 게 있으면 남겨두지 마세요.'),
(11286, '이 강철 문에서 유물을 몇 개나 모았나요?'),
(11288, '<아레스는 의식을 잃었다.>'),
(11289, '빛으로 말미암아!'),
(11290, '드래곤플레어 전투 계획을 회수하셨습니까?'),
(11291, '발가르드가 함락되지 않았다고요? 놀랍군요. 당신 덕분임이 틀림없습니다. 켈러 덕분은 절대 아니었을 겁니다.'),
(11292, '빈손으로 돌아오신 건 아니겠죠? 우리 거래한 줄 알았는데요.'),
(11293, '브루페스트 홍보는 다 하셨나요? 그리고 더 중요한 건, 발리브루에 대해서도 사람들에게 알리셨나요?'),
(11294, '썬더브루즈가 브루페스트에 참가한다는 사실을 모두에게 알렸나요?'),
(11296, '내 사냥 부대가 아직 살아있기를 간절히 바란다. 과부거미의 독침은 치명적이기까지 오랜 시간이 걸린다. 새끼들이 부화해서 배를 채울 수 있을 만큼 오랫동안 희생자를 살려두는 것을 좋아한다.'),
(11298, '그 맥주통들 가져왔어, 안 가져왔어?'),
(11300, '대건? 암호?'),
(11301, '그 뇌들 가져왔어? 못 가져왔으면 내 톱 돌려줘. 그 톱 가지고 도망가지 마.'),
(11304, '네, $n?'),
(11305, '제가 요구하는 샘플을 구하셨습니까, $n?'),
(11306, '$n님, 실험은 잘 진행되고 있나요? 관련된 과학적 원리에 대해 궁금한 점이 있으면 언제든지 알려주세요!'),
(11309, '내 부품들 받으셨나요?'),
(11310, '할그라인드 정리 작업 다 끝내셨나요?'),
(11311, '정령들을 모두 처치했나요?'),
(11313, '코어를 일부라도 복구하셨나요?'),
(11314, '그 펜던트를 사용해서 제 자매들 중 누군가를 치료할 수 있었나요?'),
(11315, '활기 넘치는 숲에서 돌아오셨나요?'),
(11316, '당신은 뒤틀린 숲의 공포를 직접 목격했습니까?'),
(11317, '신사에서 마음의 평화를 찾으셨나요? 마음의 혼란이 사라지셨나요?'),
(11318, '그 속도를 감당할 수 있었나요?'),
(11319, '트위스티드 글레이드는 끔찍한 곳이야. 우리 집이 이렇게 혐오스러운 곳으로 변할 줄은 상상도 못했어.'),
(11321, '잘 지내? 나한테 뭐 줄 거 있어?'),
(11322, '신사에서 마음의 평화를 찾으셨나요? 마음의 혼란이 사라지셨나요?'),
(11324, '$n, 돌아왔구나. 울팡 소식은 어떻게 됐지?'),
(11326, '$n, 돌아왔구나. 울팡 소식은 어떻게 됐지?'),
(11327, '그곳은 악몽 같아 보이네요. 브리쿨이든 아니든, 누구도 왕립 약제사 협회의 희생양이 될 자격은 없어요. 제가 여기 안전하게 서 있어서 다행이에요. 그 소포는 찾았어요?'),
(11328, '그래, 뭘 원해...? (딸꾹질)'),
(11329, '멀쩡해 보이네. 미끼 좀 물었어?'),
(11332, '그 전염병 방어 탱크들은 파괴되었나요? 그 새로운 전염병이 우리 머리 위에 마치 확실한 죽음처럼 드리워져 있어요!'),
(11333, '제 시약 파우치를 찾으셨나요?'),
(11335, '말해봐, $n. 전선에서 무슨 소식을 가져왔어?'),
(11336, '말해봐, $n. 전선에서 무슨 소식을 가져왔어?'),
(11337, '말해봐, $n. 전선에서 무슨 소식을 가져왔어?'),
(11338, '말해봐, $n. 전선에서 무슨 소식을 가져왔어?'),
(11339, '벌써 돌아오셨군요. 승리의 소식을 가져오셨나요?'),
(11340, '돌아왔군요! 승리의 소식을 가져왔나요?'),
(11341, '벌써 돌아오셨군요. 승리의 소식을 가져오셨나요?'),
(11342, '벌써 돌아오셨군요. 승리의 소식을 가져오셨나요?'),
(11343, '무엇을 발견하셨나요?'),
(11344, '무엇을 발견하셨나요?'),
(11346, '책을 되찾으셨나요?'),
(11348, '룬을 사용해 보셨나요?'),
(11349, '그 도구들을 가지고 돌아오셨나요?'),
(11350, '책을 되찾으셨나요?'),
(11351, '그 도구들을 가지고 돌아오셨나요?'),
(11352, '룬을 사용해 보셨나요?'),
(11354, '승마용 채찍 주세요.'),
(11355, '무엇을 발견하셨나요?'),
(11358, '거인들을 끌어당기는 자석이 무엇인지 알아내셨나요?'),
(11359, '메갈리스의 몰락 소식을 가져오셨나요?'),
(11360, '안녕하세요, $n님. 소방 기술 연마는 잘 하고 계신가요? 북쪽에 있는 연습장도 잊지 마세요!'),
(11361, '$n님, 혹시 화재 진압용 수색 작업을 해보셨나요? 훈련장은 레이저 힐 서쪽 출구 서쪽에 있습니다.'),
(11362, '우리가 다시 이야기하고 있군요... 당신은 지팡이를 가지고 있어야 합니다.'),
(11363, '그 전쟁 지도자는 손 대신 무기가 달려 있다는 소문을 들었습니다. 사실인가요?'),
(11364, '돌아오셨군요. 백부장들은 모두 죽었습니까?'),
(11365, '무엇을 발견하셨나요?'),
(11366, '거인들을 끌어당기는 자석이 무엇인지 알아내셨나요?'),
(11367, '메갈리스의 몰락 소식을 가져오셨나요?'),
(11368, '심장을 운송 중에 보존할 수 있는 방법을 알고 계시리라 믿습니다.'),
(11369, '우리가 다시 이야기하는 건 당신이 달걀을 가지고 있어서인가요? 훌륭하네요, 보여주세요!'),
(11370, '내 의뢰인은 초조해하는 것 같다. 그는 현재 진행 중인 분쟁 해결에 도움이 될 만한 군벌의 전술적 사고방식을 심층적으로 파악하고 싶어하는 것 같다.'),
(11371, '코일팽 미르미돈과의 싸움은 어떻게 진행되고 있나요?'),
(11372, '족장의 취임식이 가까워지고 있다.'),
(11373, '샤파르의 마법의 근원이 오직 그의 부적에 있다는 사실을 아는 사람은 많지 않다. 부적이 없으면 그는 무력하다. 하지만 부적을 가지고 있다는 건 그가 죽었다는 뜻이기도 하다.'),
(11374, '영원히 보석 안에 갇혀 있는 것을 상상할 수 있나요?'),
(11375, '물리적 세계에서 속삭임이 어떤 형태를 띠는지조차 확실히 모르겠지만, 교수님은 직접 보면 알게 될 거라고 장담하셨어요. 아마도 그 존재의 성대와 비슷한 것일까요?'),
(11376, '교관들, 모두 죽었나요? 아니라고요? 제가 그들을 모두 죽이지 않으면 돌아오지 말라고 하지 않았나요?'),
(11377, '맛있는 냄새가 나는 것 같은데?'),
(11378, '시대 사냥꾼의 머리라니... 대체 어떻게 그걸 벽에 걸어두고 싶다는 생각을 하게 된 걸까? 게다가 직접 사냥하지도 않고, 친구들이 싸움이 어땠냐고 물으면 뭐라고 대답해야 할까? 아마 거짓말을 하겠지.'),
(11379, '제 실험이 좀 성과를 거두었나요?'),
(11380, '친구, 뭐 찾았어?'),
(11381, '무슨 냄새가 이렇게 좋은 거죠?'),
(11382, '나라면 시간 여행을 할 때 아주 조심할 거야. 실수로 조상 중 한 명을 죽이고 나서, 그 실수로 현재에서 네 자신을 지워버리는 그런 일을 겪고 싶진 않겠지!'),
(11383, '우리는 대화를 나누고 있지만, 균열의 군주들이 아직 모두 죽지 않은 것 같소. 그들이 죽으면 다시 돌아오시오, $C.'),
(11384, '보타니카로 가는 길을 잃으셨나요? 찾기 어렵지 않아요... 폭풍 요새 동쪽 가장자리에 있거든요.'),
(11385, '채널러들이 모두 죽은 것도 아닌데 어떻게 우리가 지금 말을 하고 있을 수 있죠?'),
(11386, '프로젝터 기술 자체가 특별한 것은 아니지만, 이 특정 모델의 범위는 진정한 혁신입니다!'),
(11387, '네더 스토커는 당신의 존재에 당황한 듯 고개를 갸우뚱거립니다. 파괴자들이 모두 파괴된 것은 아닙니다.'),
(11388, '옛 신들의 일에 직접 간섭하는 건 정말 위험한 짓임에 틀림없어. 차라리 네가 하는 게 낫겠어!'),
(11389, '템페스트 요새와 아르카트라즈로 가는 길을 모르시나요? 네더스톰을 지나 동쪽으로 가세요. 날아가거나 떨어지거나, 선택은 당신 몫입니다.'),
(11390, '어? 짐 나르는 거 다 끝냈어?'),
(11391, '가고일이라고?! 저기서 봤어! 다 처리했어? 세상이 어떻게 돌아가는 거야? 드워프가 땅 파는 것조차 공격받다니.'),
(11394, '글쎄, $c, 아직 충분히 파괴하지 못한 것 같네.'),
(11395, '$c 님, 정말 특이하게 생긴 기기를 가지고 계시네요. 좀 더 자세히 살펴봐야겠습니다.'),
(11396, '글쎄요, $n님. 몇 가지를 더 빼내야 할 것 같아요.'),
(11397, '흥미롭네요. 제가 마지막으로 봤을 때는 아직 충분히 파괴하지 못한 것 같았는데요. 혹시 노력을 더 기울여 보실 생각은 없으신가요?'),
(11398, '$c님, 그게 뭐죠? 좀 더 자세히 살펴볼게요!'),
(11399, '아직 정화의 수정들을 충분히 파괴하지 못했습니다. 목표를 달성하기 전까지는 보상을 받을 수 없습니다.'),
(11400, '손에 "명예 양조업자" 도장이 찍혀 있는 건가요?'),
(11403, '$n, 다시 만나서 반갑습니다. 아이들이 당신의 영웅담을 아주 좋아할 거라고 확신해요.'),
(11407, '브루페스트 홍보를 다 끝내셨나요?'),
(11408, '브루페스트 홍보는 다 하셨나요? 그리고 더 중요한 건, 이 놀라운 트롤 맥주에 대해서도 사람들에게 알리셨나요?'),
(11409, '경주용 숫양 타는 법을 잘 아시나요?'),
(11410, '새 미끼를 써보고 싶어서 안달이 났어요. 혹시 프로스트핀으로 조과 좋으셨나요?'),
(11412, '그 고블린이 저지른 난장판 봤어? 혹시 너무 무모하게 오프로드를 달린 건 아니겠지?'),
(11413, '잘 지내? 나한테 뭐 줄 거 있어?'),
(11415, '울팡의 목에서 낮고 으르렁거리는 소리가 새어 나온다. "$B$BBjomolf와 Varg는 죽지 않았어!"'),
(11416, '당신은 독수리의 눈을 가졌습니까?'),
(11417, '당신은 독수리의 눈을 가졌습니까?'),
(11418, '아데란의 매력이 통했을까요?'),
(11419, '손에 "명예 양조업자" 도장이 찍혀 있는 건가요?'),
(11420, '설명서 찾으셨나요?'),
(11421, '와이번스컬이 불타고 있나요?'),
(11422, '<늙은 아이스핀의 죽은 물고기 같은 눈 하나가 당신을 훑어보며, 아들의 삼지창 흔적을 찾고 있는 듯하다.>'),
(11423, '그 두루마리들, $n? 구하셨습니까?'),
(11424, '그럼 내 뼈는 가져갔어?'),
(11426, '작동 장치를 찾으셨나요?'),
(11427, '이게 뭐죠? 제가 베이비시터처럼 보이나요?'),
(11428, '뒤틀린 숲에서 수호자 위더리프를 제거했습니까?'),
(11429, '아직 살아있군. 분명히 넌 충분히 노력하지 않고 있어.'),
(11431, '나한테 줄 게 있어? 아니면 그냥 술 마실 핑계를 찾고 있는 거야?'),
(11432, '$N, 당신이 휴면 상태의 브리쿨을 충분히 처리했다는 건 믿기 어렵군요. 다 처리하고 나서 다시 오세요.'),
(11433, '당신이 휴면 상태의 브리쿨을 충분히 처리했을 것 같지는 않습니다. 모두 처리하고 나서 다시 오십시오.'),
(11434, '$n, 내 유물을 손에 넣었나? 이 세상에서 외모만으로 살아가는 사람은 아무도 없어... 나도 마찬가지야!'),
(11436, '<조렉이 당신을 보고 눈썹을 치켜올립니다.>'),
(11439, '안녕하세요, $n님. 소방 기술 연마는 잘 하고 계신가요? 남쪽에 있는 연습장도 잊지 마세요!'),
(11440, '안녕하세요, $n님. 소방 기술 연마는 잘 하고 계신가요? 서쪽에 있는 연습장도 잊지 마세요!'),
(11443, '그 물품들을 찾으셨나요?'),
(11448, '<스탠와드가 투덜거린다.>'),
(11449, '$n, 혹시 화재 진압용으로 물수색을 해보셨나요? 훈련장은 브릴 서쪽에 있습니다.'),
(11450, '$n, 혹시 화재 진압용 수색 작업을 해보셨나요? 훈련장은 팔콘윙 광장 남쪽에 있습니다.'),
(11451, '아, 그거 시인가요?'),
(11452, '$n, 무슨 소식을 가져오셨나요?'),
(11453, '$n, 무슨 소식을 가져오셨나요?'),
(11455, '친구, 나한테 줄 곰 사향 좀 있어?'),
(11456, '우리가 필요한 고기를 구했습니까?'),
(11457, '다시 만나서 반가워요, $r.'),
(11458, '$n, 내가 부탁한 일 다 했어?'),
(11460, '이건 중요한 연습이야, $n. 매사냥꾼이 되려면 새에게 먹이를 주는 법을 배워야 해.'),
(11464, '돌아왔군. 내게 빚진 돈은 받았나?'),
(11465, '매는 끊임없이 먹이를 주어야 합니다. 그렇지 않으면 매가 당신이 사냥하라고 보낸 먹잇감을 먹어버릴 것입니다.'),
(11466, '내 몫인 $n을 가져갔어?'),
(11467, '보물을 찾았나요, $n?'),
(11468, '매는 끊임없이 먹이를 주어야 합니다. 그렇지 않으면 매가 당신이 사냥하라고 보낸 먹잇감을 먹어버릴 것입니다.'),
(11469, '저 뚱뚱한 녀석 지방은 어디 갔어? 지방이 하나도 없다고는 말하지 마. 저 덩치 큰 로이는 얼마나 큰지, 아직도 쿵쾅거리며 돌아다닐 수 있는지 신기할 정도야!'),
(11470, '이제 네가 통제권을 쥐고 있다, $n. 네 매를 잘 이끌어 내게 알을 가져다주도록 해.'),
(11471, '자, $n. 요나의 망원경은 구했나? 암살에 대한 네 말만 믿을 순 없잖아? 난 어쨌든 해적이니까.'),
(11475, '1단계: 월트에게 필요한 도구를 가져다 주세요.'),
(11476, '크로커랑 카버 가져왔어, 친구?'),
(11478, '도니 소식 있나요?'),
(11483, '기반 시설 자재는 확보하셨나요?'),
(11484, '곧 다시 유물 수집을 위해 돌아올게요!'),
(11485, '이런 부정적인 사람들의 말에 휘둘리지 마세요!'),
(11486, '이게 뭐지?'),
(11487, '그거 뭐 들고 있어?'),
(11488, '저는 청소 서비스를 주문한 기억이 없는데요... 아, 맞다. 저는 약제사 훔멜입니다.$B$B... 잠깐, 이게 무슨 뜻이죠? 이런 하찮은 서류들이 저를 막을 수 있다고 생각하세요? 하!'),
(11490, '가거라, 필멸의 존재여.'),
(11491, '그 사람 걱정하지 마세요, $n. 곧 괜찮아질 거예요.'),
(11492, '음, $c, 솔직히 다시 만날 수 있을지 확신이 없었어요. 무슨 소식이 있나요?'),
(11494, '진전?'),
(11495, '혹시 좋은 소식 있으셨나요?'),
(11496, '$n님, 수정 보호막을 다시 활성화하셨나요?'),
(11499, '마법사들의 테라스는 태양샘과 너무 가까워서 정말 위험한 곳임이 틀림없습니다. 혹시 마음이 바뀌신 건 아니겠죠?'),
(11500, '저승의 바람을 타고 말하는 그것이 마흐둔에게 속삭인다. 네가 아직 자매들을 처리하지 않았다고 말한다. $b$b$n은 현상금에 아무런 관심도 없는 건가?'),
(11502, '$n님, 임무가 완료되었습니까?'),
(11503, '$n님, 임무가 완료되었습니까?'),
(11504, '코끼리들이 여러분의 도움이 필요해요!'),
(11505, '영혼들이 불안해하고 있군요, $n. 당신은 임무를 완수했습니까?'),
(11506, '아우친둔의 정령들이 우리 주위 곳곳에 깃들어 있다. 과연 그들은 우리에게 소원을 들어줄까?'),
(11507, '오르푸스 소식인가요?'),
(11510, '길을 잃으셨나요?'),
(11511, '직원은 확보하셨나요?'),
(11512, '이... 이술도프의 얼어붙은 심장?'),
(11513, '마나 셀을 획득하셨나요?'),
(11514, '$n, 오늘 우리를 위해 마나 세포를 얻으려는 노력은 어떻게 진행되고 있습니까?'),
(11515, '이 괴물들은 우리 민족의 수치야. 넌 반드시 저들을 없애버려야 해, $n.'),
(11516, '다 됐나, $n? 우리는 더 이상의 군단 병력이 켈타스를 증원하는 것을 막아야 해.'),
(11520, '정말이지, $n, 난 쓸데없는 잡담할 시간이 너무 없어.$B$B뿌리 다 캐면 꼭 알려줘.'),
(11521, '정말이지, $n, 난 쓸데없는 잡담할 시간이 없어. 뿌리 다 모으면 알려줘.'),
(11523, '$n님, 크리스탈 워드를 다시 활성화하셨나요?'),
(11524, '경비병들을 전환시켰나요, $n?'),
(11525, '경비병들을 전환시켰나요, $n?'),
(11526, '조용히 해, $c. 군단 병력이 성문 남쪽을 경계하고 있어.'),
(11527, '반항적인 바다 사나이들과 거인들이 도처에 널려 있다!'),
(11529, '똑똑하군, 친구!'),
