(11540, '$n, 던블레이드 놈들을 처치했나?'),
(11541, '내 정찰병들이 말하기를, 오늘은 아직 나가족을 충분히 교란시키지 못했다고 합니다.'),
(11542, '$n님, 임무를 완수하셨습니까?'),
(11543, '$n님, 임무를 완수하셨습니까?'),
(11544, '$C, 나는 구할 수 있는 모든 정화된 아타말 금속이 필요해.'),
(11545, '기부를 원하십니까?'),
(11546, '그 열매들을 다 모았나요?'),
(11547, '$c님, 수정 조율하셨나요?'),
(11548, '기부를 원하십니까?'),
(11549, '기여할 준비가 되셨나요?'),
(11559, '이게 뭐야? 너 누구야? 너 혹시 그 $r 같은 거 아니야? 어떻게 우리 말을 할 수 있지?'),
(11560, '더 많은 올챙이를 구조하지 않으면 우리가 무슨 일을 하든 소용없을 거예요. 윈터핀 멀록들은 미래를 기대할 기회를 완전히 잃게 될 테니까요!'),
(11561, '당신이 윈터핀의 배신자들을 그렇게 많이 죽였다면, 어째서 내가 바다를 바라보면 여전히 그들이 너무 많이 보이는 걸까요?'),
(11563, '글르글의 머리가 없으면 내 시간을 낭비하지 마세요!'),
(11564, '제가 필요한 범고래 지방을 모두 가지고 계신가요?'),
(11565, '$n, 제 여벌 정장 있으신가요?'),
(11566, '$c, 해냈어? 클락시무스가 죽었어?'),
(11567, '갑옷을 찾으셨나요?'),
(11568, '다 끝난 건가요? 영혼들은 이제 안식을 찾았나요?'),
(11569, '열쇠 있어요? 아니요, 다른 건 신경 안 써요. 그냥 여기서 나가고 싶을 뿐이에요!'),
(11570, '네, $n님, 무엇을 도와드릴까요?'),
(11571, '스칼더의 증기로 소라껍데기를 채우는 데 성공했나요?'),
(11576, '제가 요청한 측정값을 확인하셨나요, $c님?'),
(11582, '자, $c?$b$b이상 현상을 찾아내셨나요?'),
(11587, '당신이 투옥된 마법사를 구출하기 위해 부지런히 노력하고 계시리라 믿습니다....'),
(11590, '$n님, 베릴 마법사를 잡으셨나요?'),
(11593, '나는 그냥 둘러보다가 전사한 우리 편 시체들이 아직도 저기에 있는 걸 발견했어. 호드에 대한 네 의무를 다해라, $c!'),
(11594, '그렇게 훌륭하게 일을 처리했다면, 왜 아직도 그들이 내 눈앞에 보이는 걸까요?'),
(11598, '우리가 네루비안 터널 시스템을 기반으로 건설한 게 아니야, 그 괴물들이 우리 쪽으로 터널을 파고 온 거지!'),
(11600, '윌리엄 씨와 이야기하셨나요, $n?'),
(11602, '알주머니들을 파괴해야 해요!'),
(11603, '노인은 멍한 표정으로 당신을 올려다봅니다.'),
(11605, '멀리서 들려오는 목소리가 다시 들려온다. 떠돌아다니는 장로들의 이름을 알아냈습니까?'),
(11606, '시간이 얼마 남지 않았어요, $c.'),
(11607, '무고한 이들의 영혼은 어떻게 지내고 있을까요?'),
(11608, '잘?'),
(11609, '의식 용품 세트를 모두 회수하셨나요?'),
(11610, '조상님을 위한 제례를 모두 마치셨나요?'),
(11612, '적들을 사냥감에서 제거하는 작업을 시작했습니까?'),
(11613, '성공했나, $r? 크발디르족은 잔혹한 전사들이다. 그들에게서 자비는 기대하지 마라.'),
(11615, '그는 죽었나요?'),
(11616, '이 방해는 무슨 뜻입니까? 쓸데없는 소리로 저를 귀찮게 하지 마세요!'),
(11617, '마법사 사냥꾼들의 비행 플랫폼을 파괴하는 데 성공하셨습니까?'),
(11619, '$r님, 가멜을 물리치셨나요?'),
(11623, '큐레이터를 없앴나요?'),
(11625, '삼지창을 가지고 있나요?'),
(11628, '매머드 가죽을 가져오셨나요?'),
(11629, '$n, 돌아왔구나. 무엇을 배웠니? 저 소리는 뭐지?'),
(11630, '당신은 세이지 아이어가 망토를 완성하는 데 필요한 흙을 가지고 있습니까?'),
(11631, '충분히 보았다고 생각되면, 그 근원을 내게 돌려주시오.'),
(11632, '거기에 뭘 들고 있는 거야?'),
(11633, '스컬지의 요새에 있는 사원들을 정찰하는 작업을 마쳤습니까?'),
(11637, '서둘러, $c, 너무 늦기 전에 내게 그 페티시를 사용해 줘.'),
(11638, '예상보다 빨리 돌아왔군요. 무엇을 배웠나요?'),
(11639, '록타르, $c. 그렇게 짧은 시간에 마그모스의 모든 적을 처치했을 리가 없잖아!'),
(11640, '우리가 재앙을 뚫고 마을 사람들을 위한 길을 열려면 그 공동묘지에 들어가야만 합니다.'),
(11641, '임무 성공 보고를 하러 온 경우가 아니라면 저를 귀찮게 하지 마세요.'),
(11643, 'PTT를 찾으셨나요?'),
(11644, '안개는 위험하다는 것을 명심하세요!'),
(11645, '$c, 내 필요한 물품 다 챙겨줬어? 이 물건들 없이는 아무것도 못 하거든!'),
(11647, '역병 가마솥에 토템을 모두 사용하셨나요?'),
(11648, '자, 그럼요? 에바노르 부인이 어디에 억류되어 있는지 아세요?'),
(11649, '필요한 입자들을 모두 모으면, 내 정수의 일부를 그들의 정수와 결합시키겠습니다. 그러면 당신이 원하는 것을 얻을 수 있을 겁니다.'),
(11650, '내가 보기에 당신이 내 목록에 있는 모든 것을 다 모으지 못한 것 같은 느낌이 드는 건 왜일까요?'),
(11652, '그래서? 무슨 일이 있었어?'),
(11653, '그 거대한 괴물들을 상대로 블래스터를 충분히 시험해 본 게 확실해?'),
(11654, '어떻게... 어떻게 저를 찾으셨어요?'),
(11655, '혈통과 명예로 섬겨야 한다... 투스카르 유물을 돌려주어라.'),
(11656, '끝났나요? 배들은 불타고 있나요?'),
(11658, '이 일이 제대로 되려면 그들의 옷이 많이 필요할 거예요. 전 재봉사가 아니니까... 당신 몸에 맞는 옷을 찾아야겠네요! 그리고 제 엔지니어 천재성을 살짝 더하면, 짜잔, 당신은 배역에 딱 맞는 모습이 될 거예요.'),
(11660, '고대 뱃사람의 뿔피리를 찾아라!'),
(11661, '오라부스는 반드시 파괴되어야 한다!'),
(11665, '하수도에서 악어를 잡은 적 있나요?'),
(11666, '오늘 낚시는 어때, 얘야?'),
(11667, '그놈을 잡았다고 말해줘. 제발 그 망할 잉어 자식을 잡았다고 말해줘.'),
(11668, '오늘 잡은 물고기가 뭐냐, 얘야?'),
(11669, '펠블러드는 진화의 경이로운 산물입니다. 어떤 물속은 물론 용암 속에서도 살아남을 수 있고, 어부만이 유일한 천적입니다. 사냥감은 잡으셨나요?'),
(11670, '그럼 모든 게 끝난 건가? 네가 보르고록 전초기지의 오크들에게 누명을 씌우는 비열한 짓을 저지른 건가?'),
(11671, '살란드의 열쇠를 얻으셨나요?'),
(11676, '저 죄수들을 구해줘!'),
(11679, '감히 내게 접근하려 드는 건 필멸의 인간인가? 네놈의 태어날 자식들을 위해서라도, 네놈의 대의가 가치 있는 것이기를 기도하거라.'),
(11683, '그렇게 짧은 시간 안에 그렇게 많은 스컬지를 처치했을 리는 없겠죠?'),
(11684, '싱크홀 위치를 표시해 두셨나요?'),
(11685, '마한 할아버지께서 당신이 터널을 무너뜨리는 것을 돕기로 동의했다고 말씀하셨습니다.'),
(11686, '농장들을 다 찾아보셨나요?'),
(11687, '$N, 당신이 돌아왔습니다!'),
(11688, '시간이 더 필요해! 저 돼지 같은 놈들이 내 코도스에 접근하지 못하게 해!'),
(11690, '저들을 역병이 들끓는 들판에서 구출해내세요!'),
(11693, '아직 역병에 걸린 마그나타우르스가 충분히 처치되지 않은 것 같군, $C.$B$B돌아오시기 전에 몇 마리 더 처리해 주실 수 있겠나?'),
(11694, '시간 낭비야, $C. 우리가 제일 피해야 할 건 역병에 걸린 마그나우르스를 상대하는 거야.$B$B평소 마그나우르스만으로도 충분히 골치 아프단 말이야!'),
(11695, '뿔피리를 찾으셨나요? 전설은 사실이었나요?'),
(11698, '그렇게 짧은 시간에 그렇게 많은 스컬지를 처치했을 리가 없어!'),
(11699, '그 물건들 다 샀어?'),
(11705, '<헬스크림이 눈썹을 치켜올리며 당신을 바라봅니다.>$B$B스컬지 네크로로드에 대한 소문이 들리던데요?'),
(11706, '알루비우스를 풀어 네루비안의 공격을 격퇴했습니까?'),
(11708, '안녕.'),
(11710, '이 기계를 계속 작동시키려면 예비 부품이 많이 필요할 겁니다. 필요한 부품을 모두 가지고 돌아왔다고 말씀해 주세요.'),
(11711, '<퉁곡이 으르렁거린다.>$B$B탈영병 처리했나?'),
(11712, '$c, 당신은 메카그놈을 몇 마리나 재저주시켰나요?'),
(11713, '싱크홀 위치를 표시해 두셨나요?'),
(11714, '이 직업은 정말 끔찍해...'),
(11715, '연료 있으세요?'),
(11716, '시험은 계속되어야 합니다!'),
(11717, '꽃가루가 핵심이에요!'),
(11718, '가죽들을 최대한 빨리 가져오세요! 가죽 없이는 기계를 완성할 수 없어요!'),
(11721, '이 가루는 모든 마그나타우르를 약화시키는 데 사용할 수 있습니다. 그래서 이 지역의 쥐 인간들이 이 가루를 그토록 철저하게 지키는 것입니다.'),
(11722, '벌써 돌아오셨네요?'),
(11723, '그럼, 셰이크앤퀘이크 5000을 설치하셨나요?'),
(11724, '인사말!'),
(11726, '양념 주머니 있으세요?'),
(11728, '마이크로필름을 복구하셨나요?'),
(11729, '여기요!'),
(11730, '지금까지 로봇을 몇 대나 재프로그래밍해 보셨나요?'),
(11788, '기어마스터 메카조드의 부하들은 처리되었습니까?'),
(11789, '해독제... 가지고 있나요?'),
(11792, '돌아왔군요, $n.'),
(11793, '하빈저 부렌이 당신을 보냈나요?'),
(11794, '$n, 내가 부탁한 일을 완료했나?'),
(11795, '그 휘장들 받았어?'),
(11796, '잔해를 침몰시켰습니까?'),
(11797, '돌아왔군. 적의 수를 좀 줄였기를 바라.'),
(11798, '징키가 당신이 올 거라고 했어요. 다 됐나요?'),
(11807, '블레이드 엣지 산맥의 불꽃을 기리십시오!'),
(11821, '나그란드의 불꽃을 기리십시오!'),
(11865, '그들을 동정하지 마세요, $r.'),
(11866, '귀면 아주 괜찮을 거예요...'),
(11867, '보물 사냥꾼이든 피에 굶주린 황무지 사냥꾼이든, 네싱와리를 지지하고 우리의 소중한 야생 동물을 감히 공격하는 자는 누구든지 데흐타의 적으로 간주될 것이다. 이 더러운 네싱와리 동조자들을 처치하고 그들의 죽음을 증명하는 증거를 가져오면 데흐타 드루이드들의 축복을 받게 될 것이다.'),
(11868, '자연은 정의를 요구한다!'),
(11869, '우리가 하는 일은 끔찍한 일입니다.'),
(11871, '우리는 그 동물들에게 제대로 된 장례를 치러줄 것입니다.'),
(11872, '좋은 소식을 가져다 주시겠어요?'),
(11875, '혹시 저에게 주실 잔여물이 있으신가요?'),
(11876, '그들은 반드시 풀려나야 한다!'),
(11877, '설계도를 가지고 돌아오셨나요?'),
(11879, '무슨 일이에요?'),
(11880, '측정값 얻었어? 저 난쟁이가 소중한 데이터를 안 주면 또 나한테 소리를 지를 거야.'),
(11881, '실패하지 마! 널 믿고 있어.'),
(11884, '그것들을 내려놓으셨나요?'),
(11885, '$n님, 임무를 완료하셨나요?'),
(11886, '당신은 무엇을 발견했습니까?'),
(11887, '거기에 무엇을 들고 있나요?'),
(11889, '돌아오셨군요. 좋은 소식이길 바라요?'),
(11890, '$r님, 무슨 사실을 알아내셨나요?'),
(11891, '그들의 비밀을 알아냈나요?'),
(11892, '보레안의 정육점 주인은 살해당했습니까?'),
(11893, '토템에 에너지를 충전하셨나요?'),
(11894, '나를 위해 그 말린 순록 가죽 구해왔어?'),
(11895, '폭풍을 완전히 제압하셨나요?'),
(11896, '당신은 그 부자연스러운 창조물들에게 폭풍의 위력을 풀어놓았습니까?'),
(11897, '$n, 성공했나요? 스컬지의 확산을 늦춰야 합니다. 그렇지 않으면 발리언스 요새가 함락될 겁니다.'),
(11898, '발라나르 왕자를 물리치셨습니까?'),
(11899, '진행 상황은 어떻습니까?'),
(11900, '$c님, 제 악보를 전부 읽어보셨나요?'),
(11903, '저 악귀들을 제대로 혼내주고 있겠죠?'),
(11904, '그 광석($n)은 안전한가요?'),
(11905, '넥서스의 균열에 가보셨나요?'),
(11906, '우리가 땅을 돌보지 않으면, 땅은 우리가 오래 살도록 내버려 두지 않을 것이다.'),
(11907, '부족장들은 처리되었습니까?'),
(11908, '제 책 돌려받으셨나요?'),
(11909, '그럼 끝난 건가요? 기어마스터 메카조드의 위협은 완전히 사라진 건가요?'),
(11910, '제가 요청한 샘플들을 수집하셨나요?'),
(11911, '수정의 고대인들... 그들은 정말 존재하는가?'),
(11912, '먹을 것을 좀 찾으셨나요?'),
(11913, '$n, 내가 부탁한 일 다 했어?'),
(11914, '제가 부탁드린 마나 정수를 가지고 계신가요?'),
(11917, '승리하고 돌아오셨습니까?'),
(11918, '우리 적 $c에 대해 알아봤나?'),
(11919, '넥서스 드레이크를 포획하는 데 성공하셨나요?'),
