(12096, '별의 안식처에 사는 드라이어드와 나이트 엘프보다 먼저 고대인들을 구할 수 있다면, 그들이 호드와 동맹을 맺는 것을 고려해 볼지도 모릅니다. 아니면 적어도 우리를 공격하기 전에 두 번 생각하게 될 겁니다. 자, 지금까지 몇 명이나 구했습니까?'),
(12097, '벌써 돌아오셨네요?'),
