(12172, '준비가 되었습니까? 이 점에 대해 거짓말을 해서는 안 됩니다, $n.$B$B만약 제대로 준비하지 못하고 제가 주문을 가르쳐드린다면, 당신이 그 주문을 처음 시전하는 순간이 아무도 당신을 볼 수 없는 마지막 순간이 될 것입니다!'),
(12174, '병사, 거기에 뭘 들고 있는 겁니까?'),
