(12190, '제가 뭘 도와드릴까요?'),
(12191, '머그잔을 벌컥벌컥 마시고, 그 머그잔을 스타우트에게 던져버려. 스타우트는 그 정도는 견딜 수 있을 거야. 견딜 수 없었으면 내가 훔치지도, 만들지도 않았겠지!'),
