(12205, '$Gboy:girl;, 당신은 내 시간을 낭비하러 온 건가요, 아니면 스칼렛 온슬로트에 대한 내 복수를 대신해 주러 온 건가요?'),
(12206, '네가 그랬어? 아, 참! 그거 몸에 묻으면 안 된다는 걸 깜빡했네! 진짜 역겹고, 얼룩도 절대 안 지워질 뿐더러, 물집이 생겨서 곪아 터진 부분도 엄청 아물 거야.'),
