(12230, '그들이 나에게 역병 확산기를 사용하게 해줄 거라고 생각했지... 거기에 뭔가 끔찍한 걸 넣어서 발리스타를 파괴할 수도 있을 텐데 말이야. 하지만 아니, 그들은 특수 임무용으로만 쓰라고 하네. 어휴!'),
(12231, '$n님, 우르속의 자녀들과 이야기를 나눠보셨나요?'),
