(12242, '$n님, 보드라실의 씨앗을 얻으셨나요?'),
(12243, '설마 그들의 돛이 내 뜨거운 물로부터 보호되었다는 말은 아니겠죠! 여기서 다시 그런 상황을 겪어야 한다면 정말 끔찍할 거예요.'),
(12244, '잡담할 시간이 없어. 이 파쇄기들이 동맹의 승패를 좌우할지도 몰라!'),
(12245, '사실 간단해. 넌 언제든 우리 비밀을 다 폭로할 가능성이 높은 무능한 바보 네 명을 처치하라는 명령을 받았고, 나가서 그걸 해내면 돼.<최고 사형 집행관은 섬뜩한 미소를 지었다.>'),
