(12264, '그들이 내가 이런 상황을 참아줄 거라고 생각할 만큼 순진한 건지, 아니면 그냥 자살하려는 건지 궁금할 따름이다.'),
(12265, '약하고 쓸모없는 자들에게 낭비되는 힘. 그들이 부여받은 생명과 마법에 걸맞은 존재를 보여주시오. 그러면 그들의 존재를 없애기 전에 낭비에 대해 이야기해 볼 수 있을 겁니다. 걱정 마시오, 기다리겠습니다.'),
