(12484, '$r, 거기 뭐 들고 있어?'),
(12491, '$n, 당신 얼굴에 심각한 기색이 역력하네요. 무슨 안 좋은 소식이라도 있나요?'),
(12492, '야, $n, 얼굴에 얼룩이 잔뜩 묻었잖아! 블랙록 심층부에 가봤어?'),
(12498, '너무 늦기 전에 갈라크론드의 안식처에서 스컬지를 섬멸하십시오!'),
(12501, '저희 게시글 관련해서 무슨 소식 있으세요, $r?'),
(12503, '혹시 몇 개 더 파괴해 주실 수 있을까요?'),
(12504, '그보다 더 많은 사람들이 보고해 줘야 할 것 같아요.'),
(12505, '이게 다 무슨 얘기야?'),
(12506, '$r, 뭘 보셨어요?'),
(12507, '저게 뭐예요?'),
(12508, '몇 명 더 죽이는 건 어때?'),
(12510, '귀중한 액체를 가지고 계신가요?'),
(12512, '$n님, 저희 참전 용사들을 구출해 주셨나요?'),
(12513, '그 시절엔 내가 무적이었죠... 자랑스러웠고, 당연한 일이었어요. 이 멋진 모자를 차지할 도전자는 아무도 없었으니까요...'),
(12514, '버섯은 전부 다 모았나요? 아, 그리고 저기 숨어있는 바실리스크 조심하세요.'),
(12515, '그 시절엔 내가 무적이었죠... 자랑스러웠고, 당연한 일이었어요. 이 멋진 모자를 차지할 도전자는 아무도 없었으니까요...'),
(12516, '끝났나요?$B$B변형된 마법이 효과가 있었나요?$B$B세라투스의 예언자를 죽여서 그의 복수를 했나요?'),
(12517, '도적 카드 덱을 완성하셨군요! 정말 대단합니다.'),
(12518, '마법사 덱을 완성하셨군요! 축하드립니다!'),
(12519, '$r, 저 대신 메달 좀 구해다 주시겠어요?'),
(12520, '코뿔소 사냥에 성공했나요, 아니면 포기하는 건가요?'),
(12522, '그래서, 엔진은 구했나요? 탐험 자금을 지원한 대마법사가 초조해하고 있는 것 같던데요.'),
(12523, '그 부품들 받으셨어요?'),
(12525, '스윈들레그린과 그의 경호원을 처리했습니까?'),
(12527, '이게 다 뭐지? 혹시 내 쓸모없는 제자 페슬팟 못 봤나? 꽤 오래전에 심부름 보냈는데 아직 안 돌아왔거든!'),
(12529, '아직 살아있네! 하드너클이 아직 널 잡아먹지 않았어? 나중에 잡아먹을지도 몰라.'),
(12530, '네가 원하는 게 뭐냐, 노예야?'),
(12531, '난 당신을 원하지 않아요, $r. 뭘 원하세요?'),
(12532, '닭 잡으세요?'),
(12533, '사냥하는 법을 배우셨나요?'),
(12534, '너한테서 말벌 같은 냄새가 나.'),
(12535, '긴 여정을 떠날 준비가 거의 다 됐어. 겡게크가 방금 전에 악어를 데리고 돌아왔거든.'),
(12536, '그들은 제픽에게 네가 프렌지하트가 아니어서 훌륭한 사냥꾼이라고 말한다.'),
(12537, '제픽은 이게 파트너와 함께 할 때 훨씬 더 잘 어울린다고 생각해요. 당신은 프렌지하트가 아니라서 정말 강해요.'),
(12538, '우리는 분지 최고의 사냥꾼이다!'),
(12541, '$n, 알다시피 진정한 연금술은 단순히 몇 가지 재료를 섞는 것보다 훨씬 더 많은 것을 담고 있습니다....'),
(12543, '우리는 알아야 해, 송곳니를 가져오니?'),
(12544, '음, 토착 신탁에 자문을 구해 보셨나요?'),
(12545, '리치 왕이 부활할 틈을 전혀 남겨두지 마라!'),
(12546, '생명을 위협하는 자들은... 처리되었습니까?'),
(12547, '<에티미디아인의 가슴에 있는 룬 문자 모양의 홈에서 희미한 빛이 나는 듯하다.>'),
(12549, '당신은 드레드세이버를 상대로 실력을 시험해 보셨나요?'),
(12550, '배송 추적은 어떻게 진행되고 있나요?'),
(12551, '킬을 달성했나요?'),
(12552, '아니, $c, 아직 완전히 끝난 게 아니야. 콜라마스에는 아직도 네크로마법사들이 돌아다니고 있다는 걸 내가 확실히 알고 있어.'),
(12553, '제가 그것들을 조립해서 당신이 사용할 수 있는 장치를 만들려면, 그 방사돌기들이 손상되지 않아야 합니다.'),
(12554, '그의 머리를 창에 꽂아 전시하는 날이 오기를 기대한다. 그가 거기서 어떻게 살아남을지 두고 보자!'),
(12555, '그거 충분히 많이 처리한 거 맞아? 내가 전염병 걸리고 싶어 하는 것처럼 보여?!'),
(12556, '그 짐승을 죽였습니까?'),
(12557, '$c님, 제 연구실에 익숙해지셨나요?'),
(12558, '샹고를 상대해 봤나요?'),
(12559, '돌아왔구나, 아가. 네가 잘 있는지 걱정하기 시작했어.'),
(12560, '필요한 고사리를 다 가져오셨나요?'),
(12561, '필멸자여, 내 시간을 낭비하지 마라. 티탄의 창조물은 반드시 지켜내야 한다!'),
(12562, '제가 제안드려도 될까요? 드라카리 물 결속자들을 몇 명 더 처리해 두시는 게 좋을 것 같습니다.'),
(12563, '저희 게시글 관련해서 무슨 소식 있으세요, $r?'),
(12564, '물양귀비를 다 모았나요, $n?'),
(12565, '짐아브와는 알 수 없는 표정으로 북쪽과 남쪽을 응시한다.'),
(12567, '짐아브와의 돌 같은 얼굴이 당신의 영혼을 꿰뚫습니다. 짐아브와는 기뻐하지만, 더 많은 드라카리 제물을 바쳐 감사와 존경을 표해주기를 바랍니다. 그러면 그는 그에 상응하는 보상을 해줄 것입니다.'),
(12569, '우리의 계획은 성공했을까요?'),
(12570, '너 누구야? 너 완전 강아지 인간 냄새가 나.'),
(12571, '<수세이 대신탁은 마치 당신을 꿰뚫어보는 듯한 눈빛을 보내고 있습니다.>'),
(12572, '안녕하세요, 건성 피부이신가요? 라푸 제품은 잘 맞으시나요?'),
(12573, '강아지 같은 남자들이 이제 사이좋게 지내는 건가요?'),
(12575, '멍청한 강아지 도둑놈들.'),
(12576, '그들은 항상 싸움을 걸려고 해요! 우리는 싸움을 원하지 않지만, 신성한 물건들을 지켜야 해요.'),
(12578, '수세이는 좀 머뭇거리지만 멍청한 건 아니야. 하지만 너무 관대했던 것 같아... 강아지 인간들은 멈추지도 않고 우리를 내버려 두지도 않을 거야. 그들을 멈추는 유일한 방법은 죽이는 것뿐이야... "평화"란 없어.<무들은 가슴을 펴고 자신을 가리킨다.> 그건 내가 잘하는 일이지.'),
(12579, '모스워커 가족은 좋은 사람들이었어요... 이런 일을 당할 자격은 없었어요.'),
(12580, '그 기둥과 돌들이 얼마나 중요한지 훨씬 더 일찍 알았더라면 좋았을 텐데... 어쩌면 이런 일이 일어나는 것을 막을 수 있었을지도 몰라.'),
(12581, '<아르트루이스의 시신 옆 땅바닥에 불길하게 놓인 부적함.>'),
(12583, '부품 있어요? 네? 있어요?'),
(12584, '네, $c님? 저희가 루퍼트 선장님께 구해달라고 부탁드렸던 사로나이트를 가지고 계신 건가요?'),
(12585, '불 피울 나무 있어?'),
(12587, '저희 게시글 관련해서 무슨 소식 있으세요, $r?'),
(12589, '결과에 만족하시나요?'),
(12592, '세어보시겠어요?'),
(12596, '$r님, 제 부하 대장들을 모두 만나보셨나요?'),
(12597, '물양귀비를 다 모았나요, $n?'),
(12598, '네루비안 터널을 봉쇄했나요, $n?'),
(12599, '불 피울 나무 있어?'),
(12603, '실력을 시험해 보셨나요?'),
(12605, '어미 새의 관심을 끌기 위해 필요한 미끼는 확보했나요?'),
(12606, '우리 병사들을 네루비안의 손아귀에서 구출했습니까?'),
(12607, '모든 게 다 처리됐나요?'),
(12609, '$c, 제가 필요한 시약들을 다 모아두셨나요?'),
(12610, '핀클스테인을 위해 박쥐 날개를 다 모으셨나요?'),
(12611, '다 됐나요, $n?'),
(12614, '살아계셨군요. 어떻게 지내셨어요?'),
(12615, '<번영의 어머니의 시선이 당신에게 닿아 있음을 느낄 수 있습니다. 그녀는 당신 같은 사람이 왜 그녀 앞에 서 있는지 궁금해하고 있습니다.>'),
(12616, '무엇을 발견하셨나요?'),
(12617, '침입자들을 처치했습니까, $n?'),
(12618, '짐토르가는 무표정하게 바라본다. 그녀는 당신이 그녀에게 더 많은 드라카리 제물을 바쳐 그녀의 지속적인 축복을 구하는 것인지 궁금해한다.'),
(12619, '룬검은 당신 존재의 연장선입니다. $c는 룬검 없이는 싸울 수 없습니다.'),
(12620, '$n, 광신도들은 처리했나요?'),
(12621, '시간이 얼마 남지 않았습니다. 재앙이 최후의 공세를 준비하고 있습니다.'),
(12622, '$c가 아후나에와 다시 연락하고 있는 게 틀림없어. 왜냐하면 $c가 그 모든 보물을 가지고 있으니까.'),
(12624, '반지, $n! 제발... 찾았다고 말해주세요!'),
(12627, '나는 아직 연락이 닿지 않는다. 주술사들의 의식은 여전히 그대로 남아 있다. 그곳으로 돌아가서 그들이 켜놓은 가마솥들을 모두 뒤져 보라.'),
(12629, '$n 님, 제가 요청한 부품들을 가져오셨나요?'),
(12630, '그 부츠는 잘 버티고 있어, $r?'),
(12632, '당신이 고통에서 구해내야 할 내 자식들이 더 있습니다!'),
(12634, '그 키 크고 인색한 나무에서 과일을 좀 따는 데 성공했나요?'),
(12635, '드라카리족은 스스로를 파멸시키는 데 너무 바빠서, 그들의 제국이 지닌 역사적 중요성마저 함께 잊혀진다면 정말 안타까운 일일 것이다.'),
(12637, '네, $r?'),
(12638, '네, $r?'),
(12639, '충분한 물자를 가지고 돌아왔기를 바랍니다. 당신이 진알라이의 웅덩이에 한 일을 생각하면, 그들의 공격이 더욱 필사적으로 변했습니다.'),
(12640, '우리가 다시 이야기하기 전에 해결해야 할 갈등이 몇 개 더 남아있어, $n.'),
(12641, '우리가 붉은 십자군을 공격한 것은 전설이 될 것이다.'),
(12643, '$n 님, 제가 요청한 부품들을 가져오셨나요?'),
(12644, '그래서 결과는 어떻게 됐나요?'),
(12645, '날 기다리게 하지 마, $n. 결과가 어떻게 나와?'),
(12646, '$r, 빨리, 내 모조를 가지고 있어?'),
(12647, '$n, 당신이 내 고통을 빨리 끝내주지 않으면 모든 것이 끝장날지도 몰라요.'),
(12648, '자, $n님? 그 플라스크는 구매하신 건가요?'),
(12649, '자, $n님? 그 플라스크는 구매하신 건가요?'),
(12650, '드라카리족은 도저히 이해할 수 없다. 그들은 극도로 잔인하고 야만적인 존재들이다.'),
(12652, '유 던 다 울즈?'),
(12654, 'Pitch를 찾으셨나요?'),
(12655, '짐루크가 당신을 신뢰하지 않는다는 것을 느낄 수 있습니다. 그는 자신의 수호자 중 한 명을 부르려고 하고 있습니다.'),
(12656, '짐루크는 당신이 또다시 그의 수호자들을 피해 다니는 것에 감탄하면서도 좌절감을 느낍니다. 적어도 지금은 말이죠. 제물을 그 앞에 바치면 그는 다시 당신에게 축복을 내릴 것입니다.'),
(12658, '계란 있으세요?'),
(12659, '아후나에는 $n이 그렇게 빨리 헤브드라카르의 많은 사람들을 제압할 방법이 없다는 것을 알고 있습니다.'),
(12660, '다 됐나요, $n?'),
(12661, '$n, 당신은 그들의 지휘관의 신뢰를 얻었습니까?'),
(12662, '그는 죽지 않았어. 여기서도 아직도 그의 외침이 들려!'),
(12663, '너랑 나랑 군드락을 차지할 거야, 임마.'),
(12664, '전장의 모습은 좀 봤어, 친구?'),
(12665, '지연되는 이유는 무엇인가요, $n?'),
(12666, '이런 사태가 벌어질 줄은 상상도 못 했어요. 드라카리족은 정말 길을 잃었군요.'),
(12668, '네 임무가 아직 끝나지 않았는데 왜 돌아왔느냐? 내가 생각만으로도 너를 파멸시킬 수 있다는 것을 모르느냐? 이제 가라, 꼬마야. 내가 네게 명령한 일을 완수하라!'),
(12669, '$n, 제발, 설마 정체를 들킨 건 아니겠지...?'),
(12671, '네, $n?'),
(12672, '하르코아가 당신을 좀 더 일찍 보내지 않은 게 참 안타깝군요. 하지만 생각해 보니, 그녀와 나는 원래 사이가 좋지 않았어요. 아마 그녀가 당신을 일부러 늦게 보낸 게 이런 일이 벌어진 거겠죠.'),
(12673, '내 부하들을 제대로 길들였지, 그렇지?'),
(12674, '내가 바보인 줄 알아? 그들은 죽지 않았어!'),
(12675, '돌아왔군요, $n님.'),
(12676, '$n, 그 징벌 마차들을 치우는 데 성공했나요?'),
(12677, '$n님, 다시 오신 걸 환영합니다. 드라쿠루의 수정 샘플을 좀 훔쳐오셨나요?'),
(12678, '이것은 오프닝 소나타입니다. 스컬지 죽음의 행진은 전선의 섬멸로 시작됩니다.'),
(12679, '그들이 쏘는 화살의 궤적을 보면 대부분의 화살이 우리 남쪽에 있는 헤이븐셔 농장이나 그 근처에 떨어질 것 같습니다.'),
(12680, '영원히 걷고 싶지는 않잖아요, 그렇죠?'),
(12681, '뒤틀린 발톱을 찾으셨나요?'),
(12683, '샘플 받으셨나요?'),
(12684, '맘토스를 되살릴 수 있는 방법이 있다면 좋겠지만, 그런 방법은 없습니다. 우리는 드라카리와의 싸움을 계속함으로써 그와 그의 희생을 기릴 수 있습니다.'),
(12685, '무슨 일로 다시 저를 찾아오셨나요, $n?'),
(12686, '다르무크는 자신의 실패에 대한 대가를 치렀을까요, $n?'),
(12687, '$c, 넌 데스차저를 무력으로 탈환해야 해!'),
(12690, '트롤들을 박살냈어, $n?'),
(12691, '돌로 만든 궤짝은 꿈쩍도 하지 않는다.'),
(12698, '참고로, 광부들이 항상 구울이 되는 건 아닙니다. 때로는 분노에 찬 악령으로 변해 당신을 죽이려 들기도 합니다.'),
(12699, '혹시 뭐 찾으셨어요, $n님?'),
(12701, '죽음의 기사는 두려움을 모른다!'),
(12702, '닭들은 보통 멀리 가지 못해요... 말벌이 잡아먹지 않으면 다음에는 그냥 들판에 놔두는 게 나을지도 모르겠네요.'),
(12703, '죽여야 할 혀 큰 녀석들이 너무 많잖아! 정말 재밌지, 그렇지?'),
(12704, '반짝이는 아이템은 아무리 많아도 부족하지... 위대한 비의 돌은 우리에게 좋은 일을 많이 해주었으니, 우리도 위대한 비의 돌에게 잘 대해줘야겠다.'),
(12705, 'dryskin님, 도와주셔서 감사합니다. 정말 친절하시네요.'),
(12706, '$c, 네가 여기로 무사히 돌아올 거라고는 생각 못 했어. 어쩌면 네게는 내가 처음 생각했던 것보다 더 많은 면이 있는 것 같군.'),
(12707, '뭐라고? 벌써 끝냈다고? 불쌍한 얼음 트롤들에게 털복숭이 정의를 구현했나?'),
(12708, '설마 그 마법에 걸린 티키 전사들을 그렇게 빨리 처리했을 리는 없잖아요?'),
(12709, '어쩌면 지금 이 순간에도 당신은 배낭 속에 숨겨진 물건들을 가지고 있을지도 모르겠네요?'),
(12710, '$n, 내 작품들을 보러 갔었니?'),
(12712, '어떤 대가를 치르더라도 군벌의 열쇠를 손에 넣어야 한다는 점을 아무리 강조해도 지나치지 않습니다.'),
(12713, '$n님, 드라쿠루와 전투를 벌여본 적이 있으신가요?'),
(12716, '제가 요청한 자료들을 다 준비하셨나요?'),
(12717, '역병 가마솥은 작동을 멈춘 채 서 있다.'),
(12718, '역병 가마솥이 부글부글 끓어오르며 독성 물질을 휘젓고, 주변에 짙은 가스를 뿜어냅니다. 안에 넣을 십자군 해골이 더 있습니까?'),
(12719, '도망칠 곳이 없어!'),
(12720, '스칼렛 크루세이더즈에게 설득력을 발휘해 보세요. 결국 한 명은 무너질 겁니다.'),
(12721, '무슨 일이에요?'),
(12722, '마치 도살장으로 끌려가는 어린 양처럼...'),
(12724, '문을 활짝 열어젖혀라! 일정표가 거기 있다!'),
(12727, '콜티라는 어떻습니까?'),
(12728, '$n님, 윈터핀 동굴에서 데이터를 수집하셨나요?'),
(12729, '필요한 것, $n을 가지고 계신가요?'),
(12730, '제가 드릴 수 있는 건 따뜻한 말과 격려뿐입니다. 마음을 다잡고 준비하는 데 필요한 시간을 충분히 가지세요. 하지만 너무 오래 걸리지 않기를 간곡히 부탁드립니다. 그렇지 않으면 선지자가 반드시 우리에게 강림할 것입니다.'),
(12732, 'Rejek 선물 가져오셨나요?'),
(12733, '죽음의 도전을 완료하셨나요?'),
(12734, '당신은 레젝의 칼날에 피를 묻혔습니까?'),
(12735, '$n, 너 정화의 노래 틀었어?'),
(12736, '이제 똑똑해진 기분이야, $r?'),
(12739, '기분이 어때요?'),
(12740, '당신이 여기로 돌아와서 나에게 말을 걸고 있다면, 왜 나는 여전히 내 백성들이 죽어가는 모습을 보는 걸까요?'),
