(12750, '기분이 어때요?'),
(12754, '택배를 놓치면 널 죽일 수밖에 없을 거야. 어쩔 수 없다는 건 네 목숨을 끊는 데서 큰 쾌감을 느낄 거라는 뜻이지. 서둘러!'),
(12755, '어디 있었소? 두 시간이나 늦었소. 우리는 최고 사령관께 전령을 보내려던 참이었소.'),
(12756, '이게 뭐지? 애들 색칠 공부 책인가?'),
(12757, '네가 뭘 했다고?'),
(12758, '레젝의 새 헬멧을 가져오셨나요?'),
(12759, '좀 정신없긴 하지만, 그래도 너무 재밌었어요!'),
(12760, '베크가르가 너에게 초특급 비밀을 가르쳐줬다고? 최강의 프렌지하트만이 알 수 있는 비밀이지.'),
(12761, '엄청나게 강력하군. 멍청한 인간들은 위대한 존재들의 힘에 대해 아무것도 몰라. 어리석은 인간들 같으니.'),
(12762, '도와주러 와주셔서 감사합니다. 긴 싸움이 될 겁니다.'),
(12771, '안녕하세요, $n. 이렇게 늠름한 $r은 처음 보군요! 아웃랜드의 시련이 당신을 강하게 만들었군요, 형제여. 당신은 당신의 종족을 자랑스럽게 만듭니다!'),
(12773, '내 아들아, 또다시 우리가 알고 있는 모든 것을 산산이 조각낼지도 모르는 갈등에 휘말렸구나. 너처럼 재능 있는 아들이 이 세계수를 지키는 데 힘을 보태주다니 다행이구나.'),
(12774, '$n, 만나서 반갑습니다. 당신의 강인함과 능력은 이 어려운 시기에 큰 도움이 될 것입니다.'),
(12776, '내 아들아, 인간과 오크의 땅은 너에게 좋은 환경을 제공해 주었단다. 이제 네 안에는 강인함이 솟아오르고 있구나...'),
(12779, '모두 죽여라...'),
(12781, '특별한 상품권을 가지고 계신 것 같군요. 제게 주시면 그에 대한 보답으로 무언가를 드리겠습니다.'),
(12785, '오그리마에 오신 것을 환영합니다, $n님. 대약제사 푸트레스가 당신보다 먼저 소식을 전했습니다... 감염된 뇌를 가지고 있습니까?'),
(12786, '썬더 블러프에 오신 것을 환영합니다, $n. 대약제사 푸트레스가 당신보다 먼저 소식을 전해왔습니다... 감염된 뇌를 가지고 있습니까?'),
(12787, '안녕하세요, $n님. 샤트라스에서 오셨나요? 대약제사 푸트레스의 지시를 받으셨나요?'),
(12788, '실버문에 오신 것을 환영합니다, $n. 대약제사 푸트레스가 당신보다 먼저 소식을 전했습니다... 감염된 뇌를 가지고 있습니까?'),
(12790, '아직 순간이동 수정 두 개를 모두 시험해보지 않으신 것 같군요. 괜찮아요, 천천히 하세요.'),
(12791, '안녕하세요, $c님.'),
(12794, '안녕하세요, $c님.'),
(12796, '안녕하세요, $c님.'),
(12797, '돌아왔군요, $n님.'),
(12798, '검 카드 덱을 완성하셨군요. 훌륭합니다.'),
(12799, '안녕하세요, $r님. 핀클스테인이 요청한 외형질을 수집하셨나요?'),
(12801, '<모그레인 대령이 고개를 끄덕인다.>'),
(12804, '스테이크 샀어요?'),
(12805, '정령들의 에너지를 되찾았나요, $n?'),
(12809, '안녕하세요, $n! 정말 많이 컸네요! 마지막으로 봤을 때보다 정확히 1.73 마이크로스팬이나 자랐군요. 아웃랜드의 공기가 당신에게 영향을 준 게 분명해요.'),
(12810, '화려한 일은 아니지만 필요한 일이죠. 그런데 왜 당신이 말을 끝내기도 전에 우리가 또 이야기를 나누고 있는 거죠?'),
(12812, '안녕하세요, $n님. 샤트라스에서 오셨나요? 대약제사 푸트레스의 지시를 받으셨나요?'),
(12813, '설마 그렇게 빨리 끝내시는 건 아니겠죠?'),
(12814, '왜 이렇게 오래 걸렸지? 쟤네 그리폰이 느린 건가? 뭔가 조치를 취해야겠어.'),
(12815, '왜 이렇게 빨리 돌아왔어? 아직도 온슬로트 녀석들이 저 아래에서 날아다니는 게 보이는 것 같은데!'),
(12816, '침략에 대한 조사를 시작했습니까? 꾸물거릴 시간이 없습니다!'),
(12817, '침략에 대한 조사를 시작했습니까? 꾸물거릴 시간이 없습니다!'),
(12818, '엔진을 이 추위로부터 보호할 수 있는 단열재가 필요해... 생각해 봐, 지어, 생각해 봐! 아, 맞다! 혹시 그 잔해 좀 가져다 놨어?'),
(12819, '잰크스가 여기 있었으면 그냥 그 사람한테 이 심부름을 시켰을 텐데. 아... 다시 생각해 보니... 안전한 길이 어딘지 그 사람한테 제대로 알려줬는지도 잘 모르겠네. 그래도 너희 같은 재치 있는 모험가들이 있어서 다행이지, 안 그래?'),
(12820, '너도 그들의 역겹고 잘난 척하는 친구들을 몇 명 데리고 있기를 바라.'),
(12821, '마그나타우르조차도 고블린을 건드리면 안 된다는 걸 알아야 한다.'),
(12822, '고블린 공병만큼 적에게 공포감을 심어주는 것도 없을 겁니다!'),
(12823, '저 폭발적인 덩어리는 제 아기예요... 완성하는 데 몇 주가 걸렸어요. 몇 주요!$B$B꽤 오래 걸렸죠... 그렇죠?'),
(12826, '광산 일은 끝났나? 좋군.'),
(12827, '안녕하세요! 배가 고픈데... 어떻게 됐어요?'),
(12828, '내 계획이 훌륭했다는 건 나도 알아. 걱정하지 마. 위대한 사람 곁에 있는 기분이 어때? 약간 짜릿하지?'),
(12829, '저 자판기 근처에서는 조심하세요! 저건 위험해요.'),
(12830, '나한테 줄 광석 좀 있어?'),
(12831, '부상당한 고블린 광부가 고통에 몸부림친다.'),
(12832, '동굴에서의 일은 잘 진행된 것 같군요? 토레는 당신에게 잘 대해줬나요?'),
(12833, '쾅! 하하!'),
(12836, '리켓이 너무 맛있어서 좋아! 어머, 또 왔네! 해충 방제는 잘 되고 있어?'),
(12838, '저에게 알려주실 정보가 있으신가요?'),
(12839, '스칼렛 온슬롯 관련 정보는 오록스 그림베인에게 전달하십시오. 사령관은 당신을 기대에 찬 눈빛으로 바라보며 물러나게 합니다.'),
(12840, '웨스트윈드 제독은 어디에 있습니까?'),
(12841, '내 룬 문자 $n? 가지고 있어?'),
(12842, '시간 낭비하지 마세요, $n. 우리는 종말의 문턱에 서 있습니다!'),
