(12847, '예?'),
(12848, '두 개의 삶, 하나의 열쇠... 날 실망시키지 마, $n.'),
(12851, '전투에서 살아남았나요, $n?'),
(12854, '브란의 야영지를 찾았나요?'),
(12855, '누구세요?'),
(12856, '$gbrother:sister, 임무 성공했나요?'),
(12857, '불쌍한 라게메인. 그는 처남이 선물로 준 거였어.'),
(12858, '디스크 작업을 완료하셨나요?'),
(12859, '흠, 불을 끄는 거요?'),
(12860, '디스크를 사용해 보셨나요? 어떤 결과를 얻으셨나요?'),
(12861, '당신은 레이지클로를 구출하나요?'),
(12863, '안녕하세요.'),
(12865, '이 새들은 오랫동안 우리에게 충성해 왔어요... 우리는 꽤 잘 지내고 있죠.'),
(12866, '정말 끈질긴 녀석들이야... 도무지 없앨 수가 없네. 토끼처럼 번식도 빨라.'),
(12867, '이 하피 문제는 곧 해결될 겁니다... 독수리들은 머지않아 다시 자유롭게 하늘을 날 수 있을 거예요.'),
(12868, '여기는 너무 추워서 평소에 흔히 볼 수 있는 해충들이 없어요... 하피가 나타나죠. 참 운이 좋네요.'),
(12869, '이건 완전히 통제 불능 상태야.'),
(12870, '나를 위해 유물 좀 찾아줬어?'),
(12871, '안녕!'),
(12872, '자, 거기 가만히 서 있지 말고 껍데기를 보여줘!'),
(12874, '너희가 내게 돌아왔구나. 승리하여 내게 돌아왔느냐?'),
(12876, '정찰병들의 말이 맞았을까? 정말 그곳에 드워프들이 있었을까?'),
(12877, '안녕하세요, $r님. 저를 만나실 때 칼 대신 혀를 사용해주셔서 기쁩니다. 최근 들어 당신 같은 분들이 점점 더 드물게 보이는 미덕이라고 생각합니다.'),
(12879, '누군가 의지의 대장간을 이용해 이 군대를 만들고 있어... 울두아르는 더 이상 안전하지 않아. $r, 코어를 회수했니?'),
(12880, '이봐, 친구! 직접 만나서 반갑네. 찾았어?'),
(12882, '제가 말씀드렸던 유물을 찾으셨습니까?'),
(12883, '드라쿠루라... 어디선가 들어본 이름인데...'),
(12884, '$r, 거기 뭘 들고 있는 거야?'),
(12886, '가라!'),
(12887, '오큘러는 아직 건재하군! 타사리안은 널 믿은 게 바보였어. 네가 누구든 간에, 오큘러가 파괴될 때까지 다시는 돌아오지 마. 내 입지는 절대 훼손되어서는 안 돼!'),
(12888, '<SCRAP-E의 접근 패널을 엽니다.>'),
(12891, '제가 요청한 것을 구해오시면, 저희 목적에 맞게 몇 가지 수정을 거쳐 장치를 제작하고 사업을 진행할 수 있을 겁니다.'),
(12892, '오큘러는 아직 건재해! 콜티라는 널 믿은 게 바보였어. 네가 누구든 간에, 오큘러가 파괴될 때까지 다시는 돌아오지 마. 내 입지는 절대 훼손되어서는 안 돼!'),
