(12900, '가죽은 찾았나요? 예티는 아래쪽 언덕에 있을 거예요.'),
(12901, '이 계획이 효과가 있을지는 솔직히 잘 모르겠어요, $n. 그냥 고철만 가져다주시면 제가 할 수 있는 한 최선을 다해 볼게요.'),
(12904, '친구, 당신은 세상에 큰 도움을 주고 있어요. 이 괴물들을 반드시 막아야 합니다!'),
