(13075, '만나서 반가워요, $c. 내 경고에도 불구하고 당신이 돌아올 줄 알았지만, 다른 사람에게 위험을 주고 싶지 않다는 내 바람을 들어줘서 기쁩니다. 그런데 왜 내게 돌아온 거죠?'),
