(13143, '주인들이 녀석들을 가만두지 않는다는 건 확실하지만, 우리가 녀석들의 피부에 새겨 넣은 교훈을 녀석들이 잊을 리는 없어. 이 땅을 기어 다니는 한, 녀석들은 저 문양들을 두려워할 거야.'),
