(13241, '대마법사는 손가락을 관자놀이에 대고 집중했다. 광전사들은 아직 쓰러지지 않았다. 내 경고를 명심하라, $n. 너는 반드시 이 일을 해내야 한다!'),
(13242, '내 마음... 내 힘...'),
(13243, '시간은 언제나 소중한 자원이지만, 특히 이 경우에는 더욱 그렇습니다. $n. 너무 늦기 전에 무한 요원들을 처리하세요!'),
(13244, '당신들이 아직 티타늄 선봉대의 위협을 제거하지 못했는데, 왜 우리가 여기에 서서 이야기를 나누고 있는지 저조차도 이해할 수 없습니다.'),
(13245, '도끼 가지고 있어? 잉바르가 죽었어?'),
(13246, '만약 그녀를 구원할 방법이 있다고 생각했다면, 당신에게 그녀의 목숨을 끊어달라고 부탁하지 않았을 겁니다. 하지만 우리는 말리고스가 마법을 얼마나 강력하게 다루는지 잘 알고 있습니다. 아제로스의 마력선을 조종하는 그는 마법에 있어서는 비할 데가 없습니다.'),
(13247, '$C?$B$BI, 레이 가디언은 처리됐나? 말리고스가 세상의 모든 마법 사용을 막으려 하고 있고, 푸른 용군단은 마법을 다룰 줄 아는 자들 중 자기 편으로 돌아오지 않는 자들을 모두 죽이고 있다는 걸 굳이 다시 말할 필요는 없겠지?'),
(13248, '이미론이 브리쿨 민족을 조직하도록 절대 허용해서는 안 된다. 그가 아이스크라운으로 개선하여 돌아온다면 모든 것이 파멸할 가능성이 매우 높다.'),
(13249, '예언자를 만나보셨나요? 티키를 가지고 계신가요?'),
(13250, '마법의 기운이 있나요? 또 하나의 위대한 트롤 국가가 몰락하는 것을 보니 정말 속이 상합니다. 리치 왕의 간섭이 없었더라면 트롤들이 스컬지에 맞서 자신들의 신을 배신하고 그들의 힘을 훔칠 필요조차 느끼지 않았을 거라고 생각할 뿐입니다.'),
(13251, '우리는 말가니스의 실수를 반드시 이용해야 해. 이런 기회는 흔치 않아.$B$B그 유물을 연구할 수 있다면 나스레짐에 대해 더 잘 이해할 수 있을지도 몰라!'),
(13252, '디스크 있으세요?'),
(13253, '우리가 다시 통화하게 됐군, $n. 이제 로켄의 광기에서 안전해진 건가, 아니면 파멸할 운명인가?'),
(13254, '내가 아니라 네가 아졸네루브로 내려가는 게 다행이야. 난 세상 아래에 있는 걸 좋아하지 않거든.'),
(13255, '$N? 당신 제정신이에요?'),
