(13261, '당신은 그 와이번들을 건배하는 건가요, $r?'),
(13264, '네, $c요?'),
(13265, '옷차림을 보니 재단사시나 짐작이 가는데, 제가 가르쳐 드릴 기술을 금방 배우실 수 있을 것 같군요. 북부 휴머노이드들은 요령만 알면 금방 천으로 바꿀 수 있는 옷을 많이 입고 다닙니다. 소정의 비용으로 노스렌드 휴머노이드들에게서 천을 얻는 기술을 가르쳐 드릴 수 있습니다.'),
(13268, '당신은 바느질 솜씨가 좋아 보이시는데, 제가 도와드릴 수 있을 것 같습니다. 북부 휴머노이드들은 옷감을 천으로 만들 수 있는 옷을 입고 다니거든요. 약간의 금화를 주시면 노스렌드 휴머노이드에게서 천을 얻는 방법을 알려드리겠습니다.'),
(13269, '북부 땅의 인간형 생명체들은 방법을 알면 천으로 바꿀 수 있는 옷을 입고 있습니다. 약간의 금화를 주시면, 노스렌드의 인간형 생명체를 처치하여 서리직물 천을 추가로 얻을 수 있는 천 채집 기술을 가르쳐 드리겠습니다.'),
(13270, '당신은 바느질 좀 할 줄 아는 것처럼 보여서, 내가 당신에게 줄 게 있어. 북쪽의 인간형 생물들은 요령만 알면 천으로 바꿀 수 있는 것들을 입고 다니거든. 돈을 좀 낸다면, 노스렌드 인간형 생물들에게서 서리직물 천을 얻는 천 채집 기술을 가르쳐 줄 수 있어.'),
(13272, '재봉사로서 당신은 제가 가르쳐 드릴 것을 배울 준비가 된 것 같군요. 북부 지역의 인간형 생물들은 대부분 옷을 입고 있는데, 적절한 기술만 있다면 그 옷들을 빠르게 천으로 바꿀 수 있습니다. 금화 몇 닢만 주시면 노스렌드 인간형 생물들에게서 추가로 천을 얻을 수 있는 ''천 채집'' 기술을 가르쳐 드리겠습니다.'),
