(13874, '당신은 엉겅퀴 요새에서 트롤의 부적을 모두 회수했다고 생각하십니까? 만약 하나라도 남아 있다면, 엉겅퀴 부족은 계속해서 그 부적의 영향을 받게 될 것이고, 결국 이곳을 공격할 것입니다.'),
(13875, '안녕하세요, $n님.'),
(13876, '자, 어때요? 시슬퍼의 미래는 당신 어깨에 달려 있습니다, $r.'),
(13880, '완료?'),
(13882, '생명은 강력해, $n. 가장 순수한 형태로 응축된 생명은 무엇이든 극복할 수 있지. 언젠가는 다크쇼어조차도 상처를 치유할 거야. 내가 필요한 건 다 찾았어?'),
(13883, '$r님, 그 장갑판을 회수할 수 있었습니까?'),
(13887, '그 달걀들 찾았어?'),
(13889, '갓 부화한 새끼가 고개를 갸우뚱하며 당신을 쳐다봅니다.'),
(13891, '묻기 좀 그렇지만, $n님. 그 유물은 파괴되었나요? 그리고 그 수호자는 어떻게 되었나요?'),
(13903, '갓 부화한 새끼가 고개를 갸우뚱하며 당신을 쳐다봅니다.'),
(13904, '갓 부화한 새끼가 당신을 쳐다봅니다.'),
