(13906, '그 맹금류를 잘 돌보고 있었나요?'),
(13909, '이 정도면 충분히 젖은 거 아니야?'),
(13910, '새로 이사한 바닷가 콘도는 어떠세요?'),
(13912, '찾았어? 그로프는 이 폐허에서 최대한 빨리 나가고 싶어해!'),
(13914, '독가죽 새끼가 기대에 찬 눈으로 당신을 바라봅니다.'),
(13915, '독가죽 새끼는 입술을 핥고 고개를 옆으로 기울인다.'),
(13917, '갓 부화한 새끼가 고개를 갸우뚱하며 당신을 쳐다봅니다.'),
(13918, '슬롯형 장치의 모든 부품을 조립했습니까? 프로스펙터 렘트래블의 샌드위치를 오래된 데이터 인터페이스에서 제거해야 할 수도 있습니다.'),
(13920, '네, $r?'),
(13922, '소녀의 치유를 위해서는 다섯 개의 월장석이 필요합니다.'),
(13924, '$n, 너니? 렐라라를 치료할 방법을 가지고 돌아왔니?'),
(13925, '당신이 들고 있는 묘목은 지금 이 순간에도 계속해서 자라나고 있습니다. 생명은 재생력이 있죠. 효과가 있었나요?'),
(13926, '우리를 돌봐주고 있는 거야?'),
(13927, '고아 소녀가 케케크가 너와 함께 간다고 말했어요.'),
(13928, '$r, 당신이 호드 진영을 뚫고 여기까지 들어왔다는 게 정말 놀랍네요.'),
(13929, '저 큰 나무가 보이나요? 보이나요?'),
(13930, '케케크는 곰 인간 나무를 방문하고 싶어해요. 그래서 우리는 갑니다.'),
(13931, '잘 지내? 나한테 뭐 줄 거 있어?'),
(13932, '잘 지내? 나한테 뭐 줄 거 있어?'),
(13933, '우리는 용 형상을 한 신상들을 모신 사당에 가는 건가요?'),
(13934, '케케크는 용의 신전에 가고 싶어해요.'),
(13937, '우리 원더웍스에 가는 거야?'),
(13938, '이 장난감 가게 아직 안 가봤어요?'),
(13942, '$r, 뭘 가져왔는지 한번 볼까요?'),
(13945, '그들의 병력이 약화되었습니까?'),
(13946, '그렐킨들을 우리 쪽으로 보내주는 데 성공하셨나요?'),
(13949, '모크라, 낯선 분이시군요. 파 워치에서 오셨나요?'),
(13950, '윈터핀 리트리트에 데려가 주실래요? 새로운 친구들도 만날 수 있을지도 몰라요?'),
(13951, '지금 케케크를 스노우폴 글레이드로 데려가는 거야?'),
(13952, '혹시 죽은 자의 빵은 없으신 거죠?'),
(13955, '이제 드래곤 퀸 보러 가는 거야?'),
(13956, '위대한 존재를 찾는 방법을 아시나요? 저희는 아직 한 번도 본 적이 없어요.'),
(13959, '꼭 돌아가야 하나요? 당신과 함께 있고 싶어요.'),
(13960, '케케크는 가고 싶지 않아. 케케크는 제르시와 함께 노스렌드를 더 보고 싶어.'),
(13961, '포로를 너무 심하게 다루지 마십시오. 질문에 답하려면 머리가 붙어 있어야 합니다.'),
(13967, '자, $n. 다 됐나요?'),
(13970, '그 생물은 고개를 들지 않고, 크고 촉촉한 눈으로 당신을 애원하듯 바라봅니다.'),
(13975, '지난번 캠핑카 뒤편에서 총을 휘두르던 사람이 당신인가요?'),
(13977, '사장님, 그거 뭐 들고 계세요?'),
(13979, '그 역겹고 사마귀투성이인 고블린을 완전히 입 다물게 만들었나요?'),
