(14325, '$r, 우리 부족을 위해 음식을 가져왔나요?'),
(14339, '그렇게 빨리 돌아오셨네요, $c?'),
(14350, '지금 성공하면 당신은 거의 내 존경을 얻게 될 겁니다, $c.'),
(14351, '$C, 왜 전장에 나가지 않는 겁니까?'),
(14352, '$n, 무슨 일이야? 중요한 일이어야 할 텐데.'),
(14353, '이 말신이라는 놈이 레이저펜 다운즈 외곽에 있다고 하더군. 틀림없이 죽여야 해. 오그리마에 있는 내 정보원에 따르면 정찰병들이 그곳에서 역병의 흔적을 발견했다고 해. 퀼보어들도 역병에 걸린 기색을 보이고 있고, 훨씬 강력해졌대. 스컬지가 그곳에서 벌이는 짓은 반드시 끝내야 해. 지금 당장. 말신을 찾아서 처치해. 그가 죽으면 여기로 보고해.'),
(14356, '책들을 안전하게 보관했나요? 잘못된 사람들의 손에 들어가지 않도록 해야 합니다.'),
(14362, '$c님, 거기에 무엇을 가지고 계신가요?'),
(14363, '불타는 칼날이 계획을 성공시키도록 절대 허용해서는 안 된다!'),
(14368, '저는… 저는 그들 없이 살아갈 수 있을지 모르겠어요.'),
(14369, '$n, 그 버려진 놈들을 처리했나?'),
(14370, '샘플 더 있습니까? 부주의한 모험가들이 수년 동안 이 물건들을 약탈해 왔는데, 그들은 이것이 얼마나 귀중한지 모릅니다!'),
(14371, '안개날개키메라가 번개를 쏠 수 있다는 걸 미리 알려드렸어야 했는데.'),
(14378, '자, $c? 그 얼간이 찾았어?'),
(14379, '$r님, 바닷가재 꼬리 좀 잡으셨나요?'),
(14382, '돌아왔구나, $n. 바깥 상황은 어때?'),
(14385, '변비약을 구했으면 고르문간에게 먹여 보세요. 그리고 잡지 같은 것도 좀 줘 보세요. 과학을 위해서라도 꼭 해봐야죠!'),
(14386, '다 됐나요, $n?'),
(14390, '<아주레고스가 당신을 노려봅니다.>'),
(14395, '이제 우리에겐 얼마 남지 않았어, $n. 남은 길네아인들을 잘 보살펴야 해.'),
(14399, '책은 찾았어? 차라도 한 잔 할래 여보?'),
(14400, '괜찮은 옷을 찾았어 여보?'),
(14401, '아주 친절하구나, $n. 고마워!'),
(14404, '물건들을 찾아오셨습니까, $n?'),
(14408, '내 생각엔 보관소가 가까이에 있을 거야, $n. 그 설계도를 찾아봐!'),
(14409, '통화할 시간이 있는 것 같네요. 무슨 일로 이야기하시는 건가요?'),
(14412, '빌어먹을 포세이큰! 바다조차도 그들을 원하지 않아.'),
(14418, '예?'),
(14419, '안녕하세요. 제가 도와드릴 일이 있을까요?'),
(14420, '성공 사례를 보고하시겠습니까?'),
(14421, '성공, $n?'),
(14423, '마진은 잘 지내고 있나요? 예전처럼 활기차게 뛰어다니고 있나요?'),
(14428, '$n, 연락이 닿았나요? 무슨 소식을 전해줄 수 있나요?'),
(14429, '$n, 너 맞니? 이 돌의 해상도가 너무 안 좋네. 도대체 어떤 하드웨어를 쓰는 거야?'),
(14431, '블랙모우 일족은 흉포합니다. 만약 그들이 조직적으로 움직인다면, 우리의 활동에 엄청난 차질을 빚게 될 것입니다.'),
(14432, '사냥은 어떻게 진행되고 있나요? 저도 예전에 브리아루트(briaroot)를 한번 먹어봤는데, 저처럼 흙길을 걸어 다닌 노련한 사람에게도 너무 쓰더라고요.'),
(14433, '로브는 있나요? 안도렐이 우리가 쓸 마법을 좀 부리고 있거든요.'),
(14435, '우리의 계략이 성공한다면, $n, 우리는 동맹과 블랙모우 사이에 영원히 균열을 일으킬 수 있을 것이다.'),
(14438, '팔레마 사람들이 땅과 주민들을 좀 더 존중했더라면 이런 갈등은 결코 일어나지 않았을 것이다.'),
(14443, '거기에 무엇을 들고 있나요?'),
(14456, '우리 소총을 몇개나 되찾아 오셨나요?'),
(14457, '해당 요원에게서 유용한 정보를 찾으셨나요?'),
(14460, '시험은 모두 통과했나, 젊은이?'),
(14464, '좋은 소식이 있기를 바라요, $n?'),
(14469, '재활용품을 사용하는 것은 전혀 나쁜 일이 아닙니다.'),
(14470, '신병, 내 로켓 발사기는 어디 있지?'),
(14483, '그 못된 악당들을 처리했나요?'),
(14486, '블러드 엘프들은 저 석판들을 아주 좋아하죠. 최고가에 팔리니까요.'),
(14487, '사람들이 값비싼 유물을 아무렇게나 놔두는 걸 보면 정말 재밌어요.'),
(14491, '땅은 만족했나요?'),
