(24427, '말해봐, $n. 전선에서 무슨 소식을 가져왔어?'),
(24428, '노즈도르무의 이빨로 맹세코!'),
(24429, '이게 무슨 뜻이야?!'),
(24431, '와인의 진가는 그 와인을 마시는 사람에 따라 달라진다고 저는 늘 말합니다.'),
(24432, '$r, 아직 살아계셔서 다행입니다. 제가 필요한 물건들은 찾으셨나요?'),
(24439, '야로데누스는 여전히 명령을 내리고 있습니까, 아니면 당신이 그의 머리에서 짐을 덜어주었습니까?'),
(24440, '지체하지 마세요, 윈터후프 우물을 정화해야 합니다!'),
(24441, '$n, 내가 가져오라고 보낸 발톱은 가지고 있나? 썬더혼 우물은 시간이 지날수록 점점 더 오염되고 있어!'),
(24442, '$n 님, 무엇을 찾으셨나요?'),
(24449, '아, 바로 이 시대의 주인공이시군요!'),
(24451, '당신은 와이번레스트에서 그 책을 되찾았습니까?'),
(24454, '우리는 당신의 복귀를 기다리고 있었습니다. 무슨 일로 늦으셨습니까?'),
(24458, '들고 있는 게 뭐예요? 그래플해머가 보낸 거예요?'),
(24461, '퀘르델라르를 재건할 수 있었습니까?'),
(24468, '승객 중 생존한 사람이 있었나요?'),
(24469, '몇 개나 얻었어?'),
(24470, '자, 뭘 기다리고 있는 거야, $C?'),
(24471, '도와주셔서 감사합니다, $n님.'),
(24472, '어떻게 돼가고 있소, $n?'),
(24474, '이봐요, 맥주가 필요하다니까요!'),
(24475, '사람들이 힘들어하고 있어요. 보급품을 구해오셨나요?'),
(24476, '칼을 단련하기 전까지는 쓸모가 없을 것이다.'),
(24477, '그래 뭐?'),
(24480, '성찰의 전당 안에서는 무슨 일이 일어났을까요?'),
(24484, '돌아왔구나, $n. 거미들은 처리됐어?'),
(24486, '트로그에게서 귀중한 유물을 되찾는 데 성공했나?'),
(24488, '자네만 믿고 있겠네, $n!'),
(24489, '도대체 무슨 이유로 악플러들이 이런 짓을 하는지 상상조차 할 수 없네요.'),
(24492, '일은 모두 마무리하셨나요? 출발하신 후에는 언제 돌아올 수 있을지 아무도 몰라요.'),
(24494, '정령들이 당신의 도착을 미리 알려줬어요, $n. 당신도 들었나요?'),
(24495, '혹시 잃어버린 페이지를 찾았나요?'),
(24496, '요나가 당신에게 제 룬 문자 메시지를 전해줬다고 하더군요. 아직 가지고 계신가요?'),
(24500, '이 정보를 얼라이언스에 전달해야 해! 아서스를 물리치는 열쇠가 될지도 몰라.'),
(24501, '$n, 뤼그나 잘 돌보셨나요?'),
(24504, '<만크릭이 으르렁거린다.> 무슨 일이야!? 나 바쁘다고!'),
(24513, '피크는 괴물이다. 상관들이 이 사실을 알게 된다면, 그를 처치해준 호드에게 감사할 것이다.'),
(24514, '테러투스 랩터는 무리를 지어 사냥하며 먹이를 에워쌉니다. 우리는 그들을 사냥하지만, 동시에 존중하기도 합니다.'),
(24518, '아, 시신 중 하나에서 뭔가를 발견했다고요?'),
(24522, '무슨 일로 오셨나요?'),
(24523, '$n. 제가 부탁드린 이빨 있으세요?'),
(24534, '브리스틀백 고양이들의 기세를 꺾으셨나요?'),
(24536, '꼬마야, 그 악취를 분석해 봤니?'),
(24541, '그들이 당신에게 배달할 상자를 던져줬나요?'),
(24542, '저는 굉장히 바쁩니다.'),
(24545, '가까이 다가갈수록 대장간의 불꽃은 더욱 맹렬하게 타오르는 듯 보입니다...'),
(24548, '$c님, 얼어붙은 왕좌의 조각들을 얻으셨나요?'),
(24551, '당신은 일을 척척 해내는 타입처럼 보이네요. 현장에서 무슨 소식 있나요?'),
(24553, '선웰에 있는 동안 무슨 일이 있었나요?'),
(24554, '무엇을 발견하셨나요?'),
(24556, '샌디가 실버 코버넌트 타바드를 얻는 데 도움을 주었나요?'),
(24557, '해당 요원에게서 유용한 정보를 찾으셨나요?'),
