(24560, '칼을 단련하기 전까지는 쓸모가 없을 것이다.'),
(24561, '성찰의 전당 안에서는 무슨 일이 일어났을까요?'),
(24562, '무슨 일로 오셨나요?'),
(24564, '선웰 안에서 무슨 일이 일어났나요?'),
(24569, '가르둘은 왜 얼라이언스가 이렇게 많은 중형 공성 차량을 증강하도록 내버려 둔 걸까? 내가 도착할 때까지 왜 공격 명령이 내려지지 않았던 거지? 가르둘은 이 모든 것에 책임을 져야 할 것이다...'),
(24570, '충분히 모으셨나요? 제대로 비교하려면 여러 개가 필요합니다.'),
(24571, '씨앗 있으세요?'),
(24573, '그들의 영혼은 대지 어머니와 화해했을까요?'),
(24574, '덩굴을 잘라내는 건 단지 시간을 벌어주는 것일 뿐입니다. 수상한 부분을 발견하셨나요?'),
(24575, '마을 사람들을 구출했나요, $n? 포세이큰 밑에서 그들이 얼마나 고통받고 있을지 상상도 할 수 없네요.'),
(24576, '그 남자를 찾았나요, 아니면 바위 밑으로 기어들어갔나요?'),
(24592, '조심하세요, $n.'),
