(24621, '브라아 ...'),
(24625, '나가들은 아주 오랜 세월 동안 우리의 적이었습니다. 이제까지 나가들을 잘 물리치지 못했지요. 그래도 이번엔 다를 거라 확신합니다. 세상은 변했고 당신도 그러한 변화의 부분이니까요.'),
