(24629, '향수는 저절로 뿌려지는 게 아니잖아요. 어서 가세요!'),
(24631, '와일드해머는 공중에서든 지상에서든 맹렬한 전사들입니다. 전투는 어떻게 진행되고 있습니까?'),
(24634, '조심해, $c. 그들은 어디에나 있을 수 있어.'),
