(24636, '아시다시피, 초콜릿이 저절로 사람들에게 날아다니는 건 아니잖아요. 어서 일을 시작해야죠!'),
(24638, '그들에게 교훈을 주었나요?'),
(24641, '별로 어려운 상대는 아닐 것 같지만, 발놀림이 빠르지 않으면 발목을 할퀴일 수도 있어.'),
(24645, '그들에게 교훈을 주었나요?'),
(24646, '낫을 찾았소, $n?'),
(24647, '그들에게 교훈을 주었나요?'),
(24648, '그들에게 교훈을 주었나요?'),
(24649, '그들에게 교훈을 주었나요?'),
(24650, '그들에게 교훈을 주었나요?'),
(24651, '그들에게 교훈을 주었나요?'),
(24652, '그들에게 교훈을 주었나요?'),
(24653, '해골들을 가지고 계신가요?'),
(24654, '동맹은 아무것도 아니야. 저 벌레 같은 놈들이 떼로 몰려온다고? <크로골은 몸서리친다.>'),
(24655, '꼬마야, 그 악취를 분석해 봤니?'),
(24656, '그들이 당신에게 배달할 상자를 던져줬나요?'),
(24657, '그 남자를 찾았나요, 아니면 바위 밑으로 기어들어갔나요?'),
(24658, '그들에게 교훈을 주었나요?'),
(24659, '그들에게 교훈을 주었나요?'),
(24660, '그들에게 교훈을 주었나요?'),
(24662, '그들에게 교훈을 주었나요?'),
(24663, '그들에게 교훈을 주었나요?'),
(24664, '그들에게 교훈을 주었나요?'),
(24665, '그들에게 교훈을 주었나요?'),
(24666, '그들에게 교훈을 주었나요?'),
(24667, '아, 북쪽에서 온 소식을 전해주시는 건가요?'),
(24674, '다 됐나요?'),
(24675, '고기는 가져왔어, $n?'),
(24676, '돌아왔군요, $n.'),
(24679, '다 됐나요, $n?'),
(24681, '돌아왔군요!'),
(24685, '설계도를 빨리 줘! 시간이 얼마 안 남았어. 내가 변장 도구를 먹어버렸거든.'),
(24686, '씨앗은 구하셨나요?'),
(24691, '배송비, 취급비, 마케팅비 등을 지불해야 하므로 많이 필요합니다... 아, 그리고 당신에게도 돈을 지불해야 합니다.'),
(24699, '$n, 자네를 믿고 있어. 이 "타르를 접착제로 쓰는" 계획에 꽤 많은 돈을 투자했는데, 자네가 빈손으로 돌아오면 정말 안타까울 거야.'),
(24700, '혹시 타르꽃을 얻으셨나요? 저는 안 보이네요...'),
(24701, '좋은 거 찾으셨어요?'),
(24702, '튼튼한 탈것이자 믿음직한 친구였습니다. 대격변 직후에 세상을 떠났습니다. 그는 언제나 시끄러운 소리를 싫어했습니다. 꽃 대신 블러드페탈 새싹을 몇 개 놓아주시면 감사하겠습니다. 살아생전 그가 가장 사랑했던 것이었습니다.'),
(24708, '뭔가 찾으셨나요? 효과가 있었나요?'),
(24709, '일이 끝났나요? 그의 메모는 건졌나요?'),
(24715, '<A-Me 01이 절전 모드로 전환되었습니다.>'),
(24717, '유행하는 스타일을 전혀 모르기 때문에 여러 가지 색상을 준비해야겠어요. 거기에 있는 고릴라 종류별로 가죽을 구해볼 생각입니다.'),
(24718, '붉은 털? 뭘 기다리고 있어! 돌아가서 그 붉은 고릴라를 데려와! 두 배로 보상해 줄게!'),
(24719, '발톱은 얻었나요?'),
(24720, '내가 뭔가 중요한 단서를 찾은 것 같아, $n!'),
(24730, '나에 대해 어떻게 생각하든 상관없지만, 그들이 연구할 뼈가 고대 스테고돈이나 디메트라돈의 뼈인지, 아니면 우리가 야영지를 세우려 할 때 우리를 거의 잡아먹을 뻔했던 놈들의 뼈인지는 신경도 안 쓸 거야. 난 그저 우리가 여기서 살아남기만 하면 행복할 뿐이야...'),
(24731, '내 말을 가볍게 여기지 마시오, $n. 진정으로 이 괴물과 맞서 싸우고 싶다면 조심해야 하고… 현명해야 하오. 라르코르위를 끌어내어 물리치려면 엄청난 힘과 통찰력이 필요할 것이오.'),
(24732, '조심해, $n. 알 둥지 근처에 가면 어미들을 자극할 게 분명해... 설령 네가 이미 어미에게서 분비샘을 확보했더라도 말이야. 어미들은 새끼를 지키려고 싸울 때는 라르코르위만큼이나 위험할 수 있어. 하지만 네가 성공한다면, 우리는 라르코르위를 숨어있는 곳에서 불러낼 확실한 방법을 갖게 될 거야.'),
(24733, '두려움에 굴복하지 마세요, $n. 두려움은 가장 큰 배신자입니다... 강인함을 유지해야 합니다!'),
(24734, '링고의 자루가 당신 앞 바위 위에 놓여 있습니다.'),
(24736, '모든 훌륭한 차량에는 이름이 필요하죠... 제 생각엔 ''Pwned''라고 부르는 게 좋을 것 같아요!'),
(24737, '타라가 또 해냈네요! 이 초강력 접착제는 엄청난 인기를 끌 것 같아요!'),
(24740, '화산이 활화산이라고 생각하세요? 대재앙이 닥쳤을 때 왜 폭발하지 않았는지 궁금하네요.'),
(24741, '몇 개나 가져왔어? 지금 우리가 만들어 먹을 엄청난 오믈렛 맛이 벌써부터 느껴지는 것 같아!'),
(24742, '저도 직접 가보고 싶지만… 거기 있는 불의 정령들이 좀 무서워요!'),
(24744, '역대 최대 크기의 달걀이 돌아오면 우리에게 쏟아질 찬사를 상상해 보세요!'),
(24745, '그 못된 악당들을 처리했나요?'),
(24752, '시간이 지나면서 너희들은 좀 더 투박하지만 전투에 더 큰 영향을 미치는 마법들을 배우게 될 거야. 공격을 흡수하는 방패, 상대를 얼어붙게 하는 갑옷 같은 것들이지. 심지어 너희 자신과 똑같은 복제체를 만들어 마법을 시전하는 법도 배우게 될 거야.'),
(24753, '별로 어려운 상대는 아닐 것 같지만, 발놀림이 빠르지 않으면 발목을 할퀴일 수도 있어.'),
