(24801, '퀘르델라르를 복원했다는 게 사실인가요?'),
(24803, '칼루악족은 매주 낚시 실력을 시험해 보는 오랜 전통을 가지고 있습니다. 제게 흑기흉상어를 처음으로 잡아 가져오는 사람에게는 후한 보상이 주어질 것이며, 적어도 며칠 동안은 북쪽 최고의 어부로 알려지게 될 것입니다. 흑기흉상어가 가장 좋아하는 먹이는 피그미 빨판상어입니다. 평소에 빨판상어를 잡는 곳에서 흑기흉상어를 낚아 보세요.'),
(24806, '젊은 $n님, 유감스럽게도 오늘의 우승자는 이미 결정되었습니다. 하지만 상어를 한 마리 가져오시면, 제가 바다로 다시 풀어드리고 작은 선물을 드릴 수도 있습니다...'),
(24816, '$n, 그래플해머를 너무 몰아세우지 마. 그는 천재지만 자존심이 약해.'),
(24819, '당신은 당신이 걷는 길을 바꾸고 싶어하는군요, $n?'),
