(24851, '누구세요?'),
(24857, '$n님, 표정에 걱정이 가득하시네요. 무슨 소식이 있으신가요?'),
(24859, '자, 그럼 몇 개나 준비하셨나요? 95대 5로 나눠주시면 아주 후한 것 같은데요.'),
(24863, '현재 상황은 어떤가요?'),
(24865, '거기에 뭘 들고 있는 거야?'),
(24866, '네, $n?'),
(24872, '필멸의 존재여, 네 손에 쥐고 있는 것은 무엇인가?'),
(24880, '필멸의 존재여, 네 손에 쥐고 있는 것은 무엇인가?'),
(24902, '그녀를 찾았나요, $n?'),
(24904, '아니요...'),
(24906, '자, 어떤 실력을 갖췄는지 보여주세요.'),
(24912, '<대영주 다리온 모그레인이 당신에게 의미심장하게 말합니다.>$B$B섀도우즈 엣지는 마지막 힘을 부여받을 준비가 되었습니다.$B$B이제 섀도우모운을 단조할 때가 왔습니다!'),
(24915, '$c, 네가 들고 있는 건 뭐지?$B$B 그것이 나를 부르며, 오래전에 죽었다고 생각했던 감정들을 불러일으킨다.'),
(24916, '네, $c님? 어떻게 도와드릴까요?'),
(24917, '$r, 거기 뭐 들고 있어?'),
(24918, '그게 뭐죠, $r인가요?'),
(24919, '어떻게 도와드릴까요, $r님?'),
(24920, '다 됐나요, $n?'),
(24926, '이게... 이게 뭐지?'),
(24930, '그래요 그게 뭐죠, $n?'),
(24931, '혹시, 혹시 가지고 계신가요?'),
(24933, '이거 싱싱하죠? 햇볕에 시들어버린 건 절대 안 먹으려고 할 거예요.'),
(24941, '팩스턴은 이미 대포에 화약을 장전했습니다. 이제 당신이 즉석에서 만든 탄약만 있으면 됩니다.'),
(24944, '붕대는 충분히 가지고 계시길 바랍니다. 이 짐승 같은 놈들이 제가 사랑하는 길네아스를 약탈했을 때, 약초 공급이 끊겼거든요.'),
(24946, '음, 얼마나 가지고 있는지 한번 볼까요?'),
(24948, '다 태워버려, $c. 잿더미로 만들어버려!'),
(24949, '어디 한번 보여줘요. 혹시 혼자 가지려고 숨기는 건 아니죠? 저 없이는 절대 구매자를 못 찾을 거예요.'),
(24952, '자, 여기 있습니다!'),
(24953, '친구, 난 붕괴 소리 하나도 못 들었어! 다시 말해 봐!'),
(24954, '지금이야말로 제가 당신에게 맡긴 간단한 일을 끝낼 절호의 기회입니다, $n. 동의하시지 않겠습니까?'),
(24956, '그가 죽었나요? 그의 투구를 가지고 있나요?'),
(24957, '충분히 준비됐나요? 이 오거들은 적은 양을 좋아할 것 같지 않거든요.'),
(24960, '이제 꾸물거릴 시간이 없소. 당신은 이제 포세이큰의 일원이 되었고, 우리는 그대에게 거는 기대가 크다오.'),
(24961, '그녀와 이야기해 봤나요? 그녀에게 진실을 알려줘야 해요.'),
(24962, '아, 도착했군. 잘 왔어. 몇몇 사람들이 ''죽음''을 면하고 마을로 향하고 있다는 소식을 들었어. 그런 강인함이 미래에도 도움이 될지도 모르겠군. 자유를 준 건 실바나스 덕분이야... 정신과 육체의 자유 말이지. 비록 여전히 역병과 그 후유증에 시달리고 있지만, 이제 네 마음대로 자유롭게 드나들 수 있어.'),
(24965, '무슨 일이야... 돈이 다 떨어졌어?'),
(24972, '그래, 무슨 일인가?'),
(24974, '아, 외로움의 고통은 너무나 견디기 힘들어요!'),
(24975, '$n님, 호박 10개 다 모으셨나요?'),
(24976, '이번 게 지금까지 만든 것 중에 최고일 것 같은 예감이 드네요. 좋은 하루 보내세요.'),
(24977, '저리 가, 더럽고 불경스러운 괴물아! 빛이 나를 보호하소서! 붉은 성전이 아제로스에서 너의… …아, 잠깐. 저건 내 먹을 건가? 너무 배고파…'),
(24979, '편지인가요? 뭐라고 쓰여 있나요?'),
(24980, '어둠의 여왕에게 당신의 가치를 증명하고 싶다면, 스칼렛 워리어 10명을 처치하십시오.'),
(24981, '우리는 붉은 십자군을 소떼처럼 몰아넣어 파멸로 이끌 것이다.'),
(24988, '$n님, 황혼박쥐 가죽 다섯 장 다 모으셨나요?'),
(24990, '$n, 다크하운드의 피를 모았나요? 시간이 얼마 남지 않았어요!'),
(24994, '그들이 나에게 우울초를 가져다줬다고? 우울초라고?!'),
(24995, '$n, 멀록에게서 그 비늘을 얻을 수 있었나요?'),
(24996, '내게 믿음직한 소총만 있었다면 넌 이제 죽은 목숨이나 다름없을 텐데, $c. 증기 전차 여단이 날 구하러 도착할 때까지 기다려 봐!'),
(24997, '당신의 임무는 완료되었습니까? 그 개 같은 것들을 파괴하고 그 안에 든 피를 모두 빼냈습니까?'),
(24998, '예?'),
(25000, '이게 뭐야, $c? 여기는 관광하기엔 적합하지 않아.'),
(25002, '뭐라고? 내 보급 수송대가 그 냉혈한 가위발 괴물들에게 약탈당했다고?'),
(25004, '재앙과의 싸움은 계속된다, $n. 네 역할을 다해서 저 저주받은, 생각 없는 $r들을 역병지대로 다시 던져버려라!'),
(25005, '재앙의 악취가 당신을 맴돌고 있군요, $n. 당신이 찾는 것은 무엇입니까?'),
(25009, '돌아왔군. 하지만 네 임무는 아직 끝나지 않았다. 혹시 하찮은 인간들이 어둠의 여왕의 계획을 방해하는 것에 만족하는 건가? 아니면 의무를 다해 바로 코앞에 있는 붉은 무리를 처치할 작정인가?'),
(25013, '$n, 혹시 사나운 밤거미의 독을 좀 구했나요? 제 실험을 테스트하는 데 필요한 마지막 재료거든요.'),
(25014, '뭔가 찾으셨나요?'),
(25015, '참고로 말씀드리자면, 이 엉망진창인 곳을 헤쳐나가려면 아마도 마체테가 필요할 겁니다. 이 정글은 갑자기 어디선가 솟아났거든요!'),
(25020, '태블릿 있으세요?'),
(25021, '너 직접 마셔본 건 아니지? 나 전부 다 필요해...'),
(25024, '우리가 이 섬에서 탈출하는 일을 진행하려면 아직 더 많은 연합군 공수부대를 파견해야 합니다, $n.'),
(25025, '영혼들이 한 말이 맞았지, 친구? 알겠어?'),
(25026, '필요한 거 다 갖췄어, 친구?'),
(25027, '호드가 왜 이런 골칫거리들을 싫어하는지 알겠네요. 세 이빨 녀석은 상대해 보셨나요?'),
(25028, '저는 지금 매우 바쁩니다, $c. 이 통제되지 않은 성장은 대륙 전체를 집어삼킬 위험이 있습니다. 무슨 소식 있나요?'),
(25029, '아가만드족의 유해를 가지고 있습니까? 그 저주받은 짐승들은 마침내 완전히 파괴되었습니까?'),
(25030, '어머나... 이게 뭐지?'),
(25037, '바다에서 얻는 양식 중에 신선한 게살만큼 맛있는 음식도 드물지.'),
(25038, '그 쓸모없는 괴물은 어디 있지? 네가 내가 필요한 걸 가지고 있든가, 아니면 어서 나가서 찾아와.'),
(25042, '<트롤리는 입술을 핥으며 침을 간신히 참았다.> 스테이크 나왔어? 핏기가 뚝뚝 떨어지는 걸로?'),
(25044, '세이버스나우트! 죽었어? 무슨 소식 있어?'),
(25048, '상자가 엄청 많으신가요? 어디 한번 볼까요!'),
(25054, '설마 당신이 몰래 숨기고 있는 건 아니겠죠, 바보야! 이 고글은 가방도, 갑옷도 꿰뚫어 볼 수 있어요.'),
(25055, '악천후는 이미 진압하셨나요?'),
(25056, '어디 보자... 가죽은 충분한가?'),
(25057, '타우라호 사태는 통제되고 있습니까?'),
(25059, '유적지를 다 뒤져보셨나요?'),
(25062, '무엇을 발견하셨나요?'),
(25063, '당신이 거북이를 무참히 파괴했지만, 다행히 거북이는 온전하게 남아있었기를 바랍니다.'),
(25065, '상자 안의 내용물을 조심해서 다루세요.'),
(25066, '여기서 뭐 하는 거야? 어서 올라가서 쏴버려!'),
(25068, '그것들은 조심해서 다루세요, $n. 그것들은 세상만큼이나 오래된 것들입니다.'),
(25075, '나에게 줄 게 뭐야?'),
(25079, '블래스트-오 파우더 한 통 구하셨나요? 구하시면... 절대 흔들지 마세요.'),
(25080, '얼굴에서 번개를 쏠 수 있다는 건 엄청난 진화적 이점일 거예요.'),
(25082, '싸움은 어떻게 진행되고 있나요, $n?'),
(25087, '흠, 요새에서 소식이 있나? 그럼, 어서 말해 봐!'),
(25090, '내가 너에게 맡긴 임무를 완수했느냐? 네놈은 그 썩어빠진 발톱을 가지고 있느냐?'),
(25092, '악천후는 이미 진압하셨나요?'),
(25093, '정의가 실현되었습니까?'),
(25105, '제가 필요한 고체 제피라이트를 가져오셨나요?'),
(25106, '그쪽 상황은 어때? 습격이 시작됐을 때 내가 우두머리인 스톤스파이어에게 총알을 박아 넣었는데, 놈들이 계속 몰려왔어.'),
(25107, '돌아왔군요! 무엇을 발견했나요?'),
(25110, '뭐?'),
(25127, '전갈 껍질이 아무리 두껍다 해도 용맹함을 갖춘 전사에겐 큰 문제가 되지 않는다오. 이길 수 있다는 마음가짐으로 강하게 내리치다 보면 전갈도 어려운 상대가 아니란 걸 곧 알게 될 거요.'),
(25129, '아... 아버지는 늘 내가 별 볼일 없는 사람이 될 거라고 하셨는데, 이렇게 나무 아래 누워 생명이 서서히 꺼져가는 걸 보니, 아버지 말씀이 맞았던 것 같아 두렵다. 적어도 내 마지막 적이 죽었다는 걸 알고 죽고 싶다.'),
(25132, '임무는 완료했나, $n?'),
(25134, '아무짝에도 쓸모없는 게으름뱅이들...$B$B엉? 내 가죽곤봉은 가져왔소? 일하다 말고 자는 놈들은 전부 잡았겠지?'),
(25135, '불타는 칼날단 소굴에는 들어가 봤소? 내 곡괭이는 찾아오셨소이까?'),
(25136, '선인장 열매 모으기 다 하셨나요?'),
(25138, '뭐라고? 너 누구야? 저리 가! 아, 너 그 마법사구나, 새로 온 녀석, 팔뚝이 크고 머리 모양이 특이한 녀석 말이야. 자, 어서 일하러 가자.'),
(25151, '말리의 숨소리는 거칠고, 떨리는 헐떡임으로 이어진다. 그의 눈은 애원하듯 당신을 바라본다.'),
(25154, '내게 밤의 돌을 가져왔나요?'),
(25155, '제가 필요한 보석을 가져오셨나요?'),
(25156, '당신이 내게 원소의 끈적한 물질을 가져왔나요?'),
(25158, '내가 필요한 단단한 제피라이트를 가져왔나요?'),
(25160, '내게 밤의 돌을 가져왔나요?'),
(25161, '제가 필요한 보석을 가져오셨나요?'),
(25162, '당신이 내게 원소의 끈적한 물질을 가져왔나요?'),
(25169, '저 인간들을 없애버려, $n.'),
(25170, '네가 주주스를 가져오면, 내가 내 모조를 보여줄게.'),
(25176, '<당신에게 아양을 떠는 게일>'),
(25178, '우리 백마 탄 왕자님이 돌아오셨네?'),
(25180, '택배 기사님을 만나셨나요?'),
(25181, '택배 기사님을 만나셨나요?'),
(25190, '전 가시멧돼지가 정말 싫습니다!'),
(25193, '크론은 기억될 것입니다.'),
(25199, '기초 훈련은 무사히 마쳤나? 교관님의 명령은 반드시 잘 따르도록 해.'),
(25201, '자, 거기에 뭐가 있는지 볼까요, $n.'),
(25202, '당신은 무엇을 선택했나요? 죽음인가요, 용서인가요?'),
(25210, '이건 슬픈 일이지만, 필요한 일입니다, $n.'),
(25212, '모든 기기를 배포하셨나요?'),
(25218, '공기가 그렇게 둥둥 뜨지만 않았더라면! 아니면 물속에서 숨쉬는 마법에 멋진 헬멧이 딸려 있었더라면! 둘 중 하나라도 있으면 좋겠는데.'),
(25219, '알아요, 그다지 바람직한 일은 아니지만, 저 껍데기에 대해 궁금하지 않을 수 있겠어요? 엄청나게 크잖아요. 분명 뭔가 더 있을 거예요.'),
(25224, '네, 은다무스 씨?'),
(25228, '그래서, 뭔가 알아낸 게 있나요?'),
(25229, '새로운 인재를 몇 명 구하셨나요?'),
(25232, '두루마리를 가져오게, $n, 두루마리 말이네!'),
(25234, '$n, 거기 아래쪽에 무슨 소동이라도 일으킨 거야?'),
(25237, '눈물은 거인들이 솟아오른 바로 그 바위들 사이에 있습니다. 이 거대한 석상들의 기저부 근처에는 흩어진 눈물 조각들이 있을 것입니다.'),
(25239, '당신은 힘의 길을 계속 걸어가고자 하는 겁니까?'),
(25240, '당신은 힘의 길을 계속 걸어가고자 하는 겁니까?'),
(25242, '당신은 힘의 길을 계속 걸어가고자 하는 겁니까?'),
(25243, '여보, 어떻게 하기로 결정했어?'),
(25246, '당신은 당신이 걷는 길을 바꾸고 싶어하는군요, $n?'),
(25247, '당신은 당신이 걷는 길을 바꾸고 싶어하는군요, $n?'),
(25248, '당신은 당신이 걷는 길을 바꾸고 싶어하는군요, $n?'),
(25249, '당신은 당신이 걷는 길을 바꾸고 싶어하는군요, $n?'),
(25253, '구시가지에서 무엇을 경험하셨나요?'),
(25260, '무슨 문제라도 있나?'),
(25262, '해골 바위굴에는 들어가 봤소, $n? 이글거리는 목걸이를 가져온 거요?'),
(25263, '$c 님, 진심으로 반갑군. 그래 $r 형씨를 어떻게 도와드릴 수 있을까?'),
(25266, '오그리마에서 무슨 용무를 보시려는 겁니까, $r?'),
(25267, '이게 뭐냐, $r? 너 같은 놈은 그롬마쉬 홀드에 들어올 자격이 없어. 내가 네 주제를 가르쳐주기 전에 당장 나가.'),
(25270, '이들은 한때 인간이었지만, 황혼의 망치에 의해 이성을 잃은 짐승으로 변해버렸다. 주저하지 말고 모두 처치하라.'),
(25271, '나 같은 늑대인간들은 골드린의 이야기, 그의 힘과 지혜에 매료되었지. 하지만 이 반달족들은 늑대 신의 전혀 다른 면모를 숭배하는군.'),
(25272, '당신의 용기는 다른 사람들에게 큰 영감을 줍니다, $c. 성함을 말씀해 주시겠어요?'),
(25273, '당신의 용기는 다른 사람들에게 큰 영감을 줍니다, $c. 성함을 말씀해 주시겠어요?'),
(25274, '서류 받으셨어요?'),
(25276, '신병, 너는 내게 마땅히 보여야 할 존경심을 가지고 나를 대해야 한다.'),
(25283, '안녕하세요, 제 연설을 들어보셨나요?'),
(25284, '경비병들에 대해 말해 보세요. 혼란이었나요? 공포였나요? 공황 상태였나요? 응?'),
(25285, '저 탈출 시스템들은 스스로 시험해 보지는 않을 겁니다... 물론 그런 아이디어를 내는 것도 나쁘지는 않지만요...'),
(25287, '당신은 토비 자이거의 연설을 전달하기 위해 여기에 오셨습니까?'),
(25289, '저는 그 검사 결과를 기다리고 있어요, $n.'),
(25292, '안녕하세요, $c님. 진흙 대신 먼지가 잔뜩 묻어 계시네요. 황무지에서 여기까지 오신 것 같군요?'),
(25295, '무슨 일이야? 총 쏘는 법을 잊어버렸어?'),
(25296, '서류 받았어, $n?'),
(25297, '<가마솥이 부글부글 끓으며 역겨운 액체가 가득 찼다.>'),
(25298, '가뭄은 효과가 있었나요?'),
(25303, '당신은 외경을 꼼꼼히 살펴보며 그 모든 것을 이해하려고 애씁니다.'),
(25321, '핵심은 $n입니다. 이해하셨나요?'),
(25325, '스태그헬름이 당신과 함께 있나요, $n?'),
(25328, '열쇠요? 지금요? 제발요?'),
(25336, '괴물 무이섹을 얻었나요?'),
(25337, '히포그리프를 포획할 수 있었나요?'),
(25338, '숲 속을 거니는 사람들의 모습을 포착하셨나요?'),
(25340, '에다나가 전국에 퍼뜨리는 증오를 반드시 막아야 합니다.'),
(25341, '오브를 가지고 계신가요?'),
(25342, '예?'),
(25345, '요정 용들의 음악을 포착할 수 있었나요?'),
(25346, '산의 거인들을 포획할 수 있었나요?'),
(25347, '드디어 돌아왔군. 난 네가 그 광신도들과 영원히 손을 잡은 줄 알았어.'),
(25353, '$c, 다시 만났군요. 당신은 지나간 자리에 공포와 혼란을 남겼습니다.'),
(25355, '$c, 다시 만났군. 잘 싸웠어! 네가 지나간 자리에는 공포와 혼란이 가득하군.$B$B<로고쉬가 기대에 찬 눈빛으로 너를 바라본다.>'),
(25358, '$r, 필요한 물품 좀 구해왔어?'),
(25361, '스프라이트 다터는 자극을 받으면 위험한 녀석들이니 조심해서 상대하세요, $c. 그리고 이 근처에 있는 나이트 엘프들은 더더욱 조심해야 합니다. 그 성가신 녀석들은 숲 속에 숨어 있는 경우가 많거든요. 날개를 충분히 모으면 알려주세요. 꼭 후하게 보상해 드리겠습니다!'),
(25362, '내 말을 진지하게 받아들여, $c. 그림토템 일족은 사악해. 그들의 행방을 알아냈다면, 이제 돌아가서 그들에게 첫 일격을 가해야 해... 그들이 우리 땅으로 쳐들어와 마을을 파괴하고 땅을 약탈하기 전에 말이야.'),
(25363, '우리가 그들을 물리쳤는데도 계속 공격해오네! 누군가 또는 무언가가 그들을 광란에 빠뜨리고 있는 게 틀림없어... 아, 돌아왔군, $n? 현상금을 받으려면 내가 원하는 갈기를 갖고 있나?'),
(25366, '$n님, 다시 오신 것을 환영합니다. 놀족의 계획에 대한 구체적인 증거를 찾으셨나요?'),
(25367, '사냥은 어떻게 진행되고 있나요, $n? 성공을 보고하러 오셨나요?'),
(25369, '스팅래셔를 쓰러뜨리는 데 성공하셨나요?'),
(25372, '정말 어찌할 바를 모르겠어! 에시나는 아무 말도 하지 않는다. 뭐 찾았어? 이게 뭐야?'),
(25377, '약간 찌꺼기가 낀 이 자물쇠는 여전히 작동할 수도 있습니다.'),
(25385, '작은 동물들을 구했나요? 그리고 그들의 작은 친구들도요?'),
(25388, '$n, 거기 뭘 들고 있는 거야?'),
(25389, '오, 제발 저를 위해 먹을 것을 좀 찾아주셨다고 말해주세요, $c.'),
(25390, '그래서, $r 씨? 제 귀중품은 되찾으셨나요?'),
(25395, '가지고 계세요? 그 불쌍한 물건은 멀쩡한가요?'),
(25396, '눈물은 거인들이 솟아오른 바로 그 바위들 사이에 있습니다. 이 거대한 석상들의 기저부 근처에는 흩어진 눈물 조각들이 있을 것입니다.'),
(25401, '오브를 가지고 계신가요?'),
(25402, '지금 들고 있는 건 뭐예요?'),
(25408, '지역 식물들이 당신에게 어려움을 주고 있나요?'),
(25417, '드디어 돌아왔군. 난 네가 그 광신도들과 영원히 손을 잡은 줄 알았어.'),
(25419, '당신은 사슬을 조사하며, 복구할 수 있기를 바랍니다.'),
(25421, '돌아왔군요! 무엇을 발견했나요?'),
(25422, '흙 있어요? 제가 정신을 차리기가 힘들어요...빨리...'),
(25423, '다 모으셨나요?'),
(25426, '갈기는 단순히 트로피용이 아닙니다. 어차피 도살이 불가피하다면, 그 도살을 헛되이 하지 않는 것이 좋겠죠.'),
(25428, '말해봐! 톨렘바르와 싸워봤어? 난 네 덕분에 대리만족하고 있어, $r. 실망시키지 마!'),
(25429, '사냥은 어떻게 진행되고 있나요, $n? 성공을 보고하러 오셨나요?'),
(25442, '네, $c님? 뭐 찾으셨나요?'),
(25444, '개구리 처리하는 거 도와줄 거야, 말 거야?'),
(25447, '이건 슬픈 일이지만, 필요한 일입니다, $n.'),
(25449, '두꺼운 예티 가죽 10장을 가져오시면 제가 직접 만든 아이템 중 하나를 선택하실 수 있습니다. 저는 품질을 중요하게 생각하기 때문에 좋은 아이템을 받으실 수 있도록 보장해 드립니다!'),
(25450, '이 가죽들은 토륨만큼 탄력적이지는 않지만, 부드럽고 유연합니다.'),
(25451, '이게 뭐야, $n - 나한테 특별한 걸 가져왔어?'),
(25452, '두꺼운 예티 가죽 열 장 정도를 구할 수 있었나요? 제가 만드는 가죽 제품은 최고 수준인데, 가죽이 있다면 샘플을 나눠드리겠습니다.'),
(25453, '야생 흉터 예티는 아직 거기 있나요? 가죽은 얻으셨나요?'),
(25454, '이게 뭐야, $n - 나한테 특별한 걸 가져왔어?'),
(25458, '장군이 쓰러졌습니까?'),
(25461, '우리는 가능한 한 많은 자원봉사자가 필요합니다.'),
(25464, '다 됐나요, $n?'),
(25465, '산악 거인들에게 효과가 없도록 장치를 약간 수정해야 했습니다. 제가 직접 돌아다니면서 적들을 공격한 건 아니지만, 그 나이트 엘프들이 작아진 거인들을 발견하고는 저를 흠씬 두들겨 팠거든요.'),
(25466, '원소 핵의 활용법에 대한 기술적인 세부 사항으로 여러분을 지루하게 할 수도 있겠지만, 대신 이 중요한 임무를 완수하도록 귀중한 코인과 상품을 제공하여 여러분의 참여를 유도하겠습니다. 욘, 당신은 정말로 임무를 완료했습니까?'),
(25467, '사물함의 열쇠 구멍에 따개비가 잔뜩 붙어 있지만, 여전히 작동할 수도 있습니다.'),
(25472, '네, $n?'),
(25473, '<카자콜라 6개들이 한 상자를 전해주자, 혹시 폭발하는 건 아닐지 유심히 살펴보는 새시>$B$B카자콜라가 이것 뿐이라고요? 너무 부족해요!$B$B조만간 그 $r을 해고하지 않으면 제 손가락에 장을 지지겠어요!'),
(25475, '자, 당신이 발견한 것은... 로봇 닭의 잔해인 것 같군요? 달걀 속에서 다시 목소리가 들려왔습니다. "훌륭합니다! 이것은 제 귀환 로봇이 맞습니다. 하지만 센서에 따르면 수리를 위해 부티 베이로 돌아가기 전에 시동을 걸어줘야 합니다. 자, 비콘을 로버 안에 넣어 두세요. 비콘이 나머지를 알아서 처리할 겁니다!"'),
(25477, '$n님, 바다거북을 길들일 수 있었나요?'),
(25491, '화산재 아래에서도 생명체가 여전히 힘겹게 살아가고 있을 거라고 생각해요. 무엇을 발견하셨나요?'),
(25493, '내장은 다 모았나? 코어 하운드는 이 지역 토착종이 아니야. 황혼의 망치단과 함께 땅의 저승에서 온 놈들이지. 걔네들을 없애려고 애쓰지 마.'),
(25494, '이해하셨어요?'),
(25500, '신병, 뭘 들고 있는 거야?'),
(25503, '당신은 길블링글 가문의 보물을 발견했군요!'),
(25504, '드디어 부품 목록이 나온 건가요? 하루 종일 기다렸어요!'),
(25505, '저게 포직에서 보내준 부품 목록 맞나요?'),
(25507, '네메시스는 순수한 증오로 이루어진 돌껍질에 둘러싸인, 끓어오르는 분노의 덩어리다. 그의 최후의 순간이 반드시 올 것이다.'),
(25515, '그 부품 목록에 있는 모든 걸 다 가져올 때까지는 이 작업에 대한 근무 기록을 남기지 않을 거야.'),
(25516, '목록에 있는 모든 것을 준비해 주시면 바로 시작할 수 있습니다.'),
(25521, '혹시 가지고 계세요? 제발...'),
(25522, '돌아왔구나! 가져왔어?'),
(25524, '오, 제발, 쇠지렛대 좀 가져오셨어요? 여기서 물에 빠져 죽을 것 같아요!'),
(25526, '아, 제발, 이윤을 위해서라도, 쇠지렛대는 아직 못 구했어? 나 여기서 물에 빠져 죽어가고 있어!'),
(25539, '조개를 잔뜩 넣은 즐거운 파티가 결실을 맺었나요?'),
(25540, '당신은 어떤 목적을 가지고 돌아온 것 같군요. 여행은 성공적이었나요?'),
(25541, '나한테 징징거리지 마.'),
(25545, '$r, 우리 장비를 되찾았나요?'),
(25546, '$c, 저와 제 부하들이 먹을 만한 걸 좀 찾아주셨나요?'),
(25552, '돌아왔군요, $r님.'),
(25554, '$n님, 임무를 성공적으로 완수하셨나요?'),
(25563, '이건 또 뭐지? 다른 기기인가?'),
(25564, '그 장비를 확보하셨나요, $c님?'),
(25565, '태블릿 있으세요?'),
(25571, '당신은 이걸 정령의 균열 근처에서 발견했다고 했잖아요?'),
(25574, '다 됐나요, $n?'),
(25583, '네, $c요?'),
(25594, '반짝이는 것의 매력을 절대 과소평가하지 마세요.'),
(25595, '뱃속에서 꼬르륵 소리가 나는 걸 보니 동굴 안에 괴물이 있는 것 같아. 신경이 곤두서네.'),
(25599, '그 두꺼운 책! 찾으셨나요?'),
(25602, '캠프에서 폭발물을 가져왔어, $c?'),
(25604, '이건 또 뭐지? 다른 기기인가?'),
(25607, '쓰레기 같은 거? 여드름 났어?'),
(25609, '어머나, 벌써 그 침몰한 보물을 다 가지셨어요?'),
(25610, '당신은 이미 그 침몰한 보물을 전부 가지고 있나요?'),
(25627, '무슨 일이야? 나 여기서 꺼내줄래?'),
(25628, '무슨 일이야? 나 여기서 꺼내줄래?'),
(25641, '당신의 존재에서 왠지 모르게 익숙한 느낌이 듭니다...'),
(25642, '그 광석 샘플 좀 가져와!'),
(25645, '돌아왔군요. 무엇을 발견했나요?'),
(25647, '거기에 뭘 들고 있는 거야?'),
(25649, '거기에 뭘 들고 있는 거야?'),
(25650, '그래서? 뭐라고 써 있어?'),
(25651, '$r, 당신은 나랑 엮이고 싶지 않을 거예요. 난 좀... 이상하거든요.'),
(25654, '우리는 하르피아들이 조상의 유적을 침범하는 것을 결코 용납해서는 안 됩니다.'),
(25656, '티살리는 단검으로 손톱을 다듬고 있다. 그녀는 기대에 찬 눈빛으로 당신을 올려다본다.'),
(25659, '적은 이 복도를 조금만 헤엄쳐 가면 바로 있다. 가라, 그리고 죽음을 몰고 와라.'),
(25661, '신선한 심장, 폐, 간이 필요해. 그의 선장들이 준 것들을 써야겠지만, 아마 다 선별된 것들일 거야.'),
(25662, '나를 납치한 자가 이 우리 열쇠를 쥐고 있다.'),
(25663, '그 영혼은 마치 여기와 다른 곳에 동시에 존재하는 것처럼 당신의 시야에서 희미하게 나타났다 사라졌다 합니다.'),
(25664, '블레이스의 상태는 걱정하지 마세요. 슬픔은 오래전에 그 녀석의 영혼을 앗아갔습니다. 그는 예전의 모습을 잃고 순수한 분노에 휩싸인 짐승에 불과합니다.'),
(25668, '잃어버린 물품들을 찾으셨나요?'),
(25672, '야, 그 시체들을 많이 가져와야 해! 안 그러면 그 어리석은 악령을 없앨 수 없어!'),
(25673, 'P씨는 너무 슬퍼 보여요. 우리는 그를 행복하게 해줘야 해요!'),
(25682, '돌아왔군요, $n?'),
(25685, '오우거의 피만으로는 한계가 있다. 너는 그 피를 가지고 있는가?'),
(25687, '날 믿어... 로라무스에게 무슨 일이 일어났든, 우린 고칠 수 있어. 혈마법의 한계는 아직 정해지지 않았으니까.'),
(25689, '안녕하세요, 저를 아시나요?'),
(25690, '너무 배고파요! 서두르지 않으면 시약을 마셔버릴지도 몰라요.'),
(25691, '좀 조용히 해 줄래?'),
(25692, '으, 무슨 냄새지? 네 냄새야, 아니면 피 냄새야?'),
(25693, '$C... 당신이 돌아오는군요...'),
(25697, '알리스타즈는 그 부적에 자신의 일부를 남겨두었다. 지금도 그의 악의 기운을 느낄 수 있다.'),
(25698, '세빈의 부적... 다른 것들과 함께라면, 우리는 디파일러의 부활에 도달할 수 있습니다.'),
(25699, '세 번째 부적은 라젤리크의 셋째 부관이 준 것이다.'),
(25705, '넵툴론이 너를 인도하리라, 지상의 여행자여.'),
(25716, '광신도들은 자신들의 상징물을 쉽게 내놓지 않을 것이다. 그들이 우리의 의도를 눈치채기 전에 재빨리 처치하라.'),
(25719, '던플라이트의 계획은 훌륭합니다. $n님, 배는 가지고 계신가요?'),
(25722, '그럼 퇴적물을 살펴봅시다.'),
(25723, '살이 통통한가요? 한번 살펴볼까요.'),
(25725, '얼마나 가지고 있어요?'),
(25726, '그 뚱뚱한 사람을 찾았어?'),
(25727, '그럼 한번 볼까요?'),
(25730, '당신은 그 짐승을 죽였습니까?'),
(25732, '그래서, $r... 이 저주를 풀어줄 거야, 말 거야?'),
(25734, '자, 뭐가 있는지 한번 볼까요?'),
(25735, '다행히 멀쩡해 보이네요.'),
(25736, '어? 그거 뭐 들고 있어?'),
(25741, '제가 요청했던 독주머니들을 회수하셨나요?'),
(25751, '똑딱똑딱. 늘 이렇게 바쁘기만 하다니. 혁신을 위한 시간은 전혀 없다. 연구실이 다시 생겼으면 얼마나 좋을까!'),
(25756, '호드 측의 제안서를 받았습니까? 시추권에 대해 그들은 얼마를 제시하고 있습니까?'),
(25757, '연합 측의 제안서를 가지고 계신가요? 시추권에 대해 그들은 얼마를 제시하고 있나요?'),
(25758, '번호판 좀 구했어? 그걸 얻으려고 누구 죽여야 했어? 그랬으면 좋겠네.'),
(25759, '이건 또 뭐지? 다른 기기인가?'),
(25761, '오, 다행이다. 아직 살아있었구나.'),
(25762, '성스러운 불꽃을 갖고 있느냐? 없다면 내게 말을 걸지 마라, $r!'),
(25767, '고대 유물을 되찾으셨습니까?'),
(25770, '그래? 나한테 뭘 가져왔어?'),
(25771, '자, 그럼? 드레네시스트는?'),
(25772, '흠 없는 드레네시스트 구체를 찾으셨나요?'),
(25773, '이걸 정령의 균열 근처에서 찾았나요?'),
(25774, '황철석을 충분히 가져오면 붓으로 한 번 칠하고 팔레트에 쌓아서 족장에게 다시 보내드리겠습니다.'),
(25775, '황철석을 충분히 가져오면 붓으로 한 번 칠하고 팔레트에 쌓아서 족장에게 다시 보내드리겠습니다.'),
(25776, '세트리아처럼 보잘것없는 용이 우리에게 이토록 많은 문제를 일으킨다면, 트와일라잇 해머가 앞으로 또 어떤 일을 벌일지 생각만 해도 끔찍하군...'),
(25777, '메네틸에 오신 것을 환영합니다, 낯선 분이시군요. 좋은 소식이나 독한 술 한 잔을 가져오셨기를 바랍니다.'),
(25778, '이게 뭐죠? 금이 정말 많네요.'),
(25779, '이게 뭐죠? 금이 정말 많네요.'),
(25780, '그가 죽었나요? 호르가스트가 죽었나요?'),
(25789, '이건 또 뭐지? 다른 기기인가?'),
(25800, '작은 집게발은 굳이 손대지 마세요. 껍질 벗기는 수고에 비해 살이 별로 없어요.'),
(25801, '고블러와 그 멀록들을 없애기 전까지는 우리 상인들이 안전하지 않을 겁니다.'),
(25805, '조각상 가지고 계세요?'),
(25815, '아, 너무 목이 마르네요! 이 불쌍하고 한심한 바보에게 음료수 좀 사주시겠어요?'),
(25818, '이 상자는 단단히 잠겨 있습니다.'),
(25819, '어떻게 도와드릴까요, $glad:lass;?'),
(25822, '전쟁에 필요한 무기를 모두 모았습니까?'),
(25825, '이게 뭐지? 기름인가?!'),
(25826, '안녕하세요, 친구. 저거 기름인가요?!'),
(25837, '이 작은 오두막은 저절로 만들어지지 않을 거야!'),
(25844, '저희를 위해 뭔가 가져오셨나요?'),
(25845, '잘???'),
(25846, '무기를 가지고 있습니까?'),
(25847, '그림토템에 무기를 장착했습니까?'),
(25848, '장군들은 죽었습니까?'),
(25849, '쑥스러워하지 말고, 어서 한 아름 가져와!'),
(25853, '모두 여기 있나요? 저기에 많이 두고 왔어요.'),
(25854, '계란 충분히 있어요? 하나만으로는 안 될 것 같아요. 통계적으로 보면 알잖아요.'),
(25855, '찾으셨나요?'),
(25856, '악어 가죽 좀 줄 수 있어?'),
(25857, '얻었어? 호러죠 가죽 있어?'),
(25865, '도난당한 금괴는 대략 8개 정도일 겁니다.'),
(25873, '이게 뭐죠, $c?'),
(25874, '$n? 무슨 소식 있어?'),
(25876, '항해일지를 되찾으셨나요?'),
(25885, '$c님, 혹시 그쪽에서 해초 좀 찾아주셨나요?'),
(25895, '정말 놀라운 물건들이 가득 담긴 커다란 상자예요! 제 삶에 더 많은 놀라운 것들이 필요해요. 걱정 마세요, 함께 나눠 먹을게요.'),
(25897, '밧줄이 전체 계획을 하나로 묶어줍니다!'),
(25901, '워든의 화살은 달빛샘에서 축복받은 살아있는 참나무로 만들어졌으며, 자연의 축복을 기원하는 룬 문자가 새겨진 흑요석 화살촉이 달려 있습니다. 결코 싸지 않습니다.'),
(25904, '그 상형문자를 보여줘.'),
(25909, '이게 효과가 있기를 바랍니다. 저는 주술사로서 능력이 부족해서 이 일이 저희에게 너무 버거울까 봐 걱정됩니다.'),
(25912, '제 스케치북 찾으셨나요?'),
(25913, '파수꾼의 글레이브($n)를 회수하세요. 각 글레이브는 파수꾼마다 고유한 아이템입니다.'),
(25918, '젊은 시절에 창술 훈련을 받은 적이 있습니다. "뾰족한 끝으로 찔러라"라는 말이었던 것 같습니다.'),
(25920, '나가족은 이 진주들에 어떤 숨겨진 의도가 있는 게 분명해. 시간을 내서 자세히 연구해 보면 그 이유를 알아낼 수 있을 거야.'),
(25929, '$r님, 제가 요청한 물품들을 준비해 오셨나요?'),
(25934, '당신은 불타오르는 심장을 되찾았습니까?'),
(25935, '서둘러, $n, 강아지들이 배고파!'),
(25937, '그곳에서 유물을 발견하셨나요?'),
(25943, '군인들을 위한 식량을 준비했나요, $r?'),
(25944, '$r님, 저희 장비를 다 챙겨주셨나요?'),
(25947, '$n님, 얼라이언스 장비를 더 찾으셨나요?'),
(25956, '네, $c요?'),
(25962, '똑딱똑딱. 늘 이렇게 바쁘기만 하다니. 혁신을 위한 시간은 전혀 없다. 연구실이 다시 생겼으면 얼마나 좋을까!'),
(25964, '이 병사들 상태가 좋지 않군. 예상보다 빨리 후퇴해야 할지도 몰라.'),
(25970, '정말 놀라운 물건들이 가득 담긴 커다란 상자야! 내 삶에 더 많은 놀라운 것들이 필요해. 걱정 마, 나눠줄게.'),
(25971, '밧줄이 전체 계획을 하나로 묶어줍니다!'),
(25975, '$n, 약탈품을 얼마나 되찾았습니까?'),
(25976, '약탈품을 얼마나 얻었지, $n?'),
(25981, '몇 개나 가지고 있어요?'),
(25982, '무슨 냄새지?'),
(25989, '이게 효과가 있기를 바랍니다. 저는 주술사로서 능력이 부족해서 이 일이 저희에게 너무 버거울까 봐 걱정됩니다.'),
(25992, '젊은 시절에 창술 훈련을 좀 받았어요. "뾰족한 끝으로 찔러라"였던 것 같아요.'),
(25994, '나가족은 이 진주들에 어떤 숨겨진 의도가 있는 게 분명해. 시간을 내서 자세히 연구해 보면 그 이유를 알아낼 수 있을 거야.'),
(25997, '다크 아이언스는 무슨 일을 꾸미고 있는 걸까?'),
(26002, '퍼즈휘슬을 찾으셨나요?'),
(26004, '이 방해는 무슨 의미인가? 왜 이 졸개는 크롬가르 군주 앞에 서 있는 거지?'),
(26015, '특히 멀록들과 경쟁하려면 정말 밝은 빛을 내려면 충분한 양의 인광체가 필요해요.'),
(26016, '더 많은 난쟁이 인형이 필요하세요?'),
(26017, '몇 마리나 잡았어?'),
(26019, '$n, 거기 뭐 들고 있어?'),
(26022, '나는 허황된 주장에 흔들리지 않을 것이다. 당신의 충성심을 증명할 증거가 있는가?'),
(26024, '안녕하세요, $c님. 보고서를 작성하실 예정이신가요?'),
(26025, '내 혈관 속의 불길은… 날이 갈수록 거세지고 있다. 저 마법사를 반드시 막아야 한다.'),
(26026, 'D씨는 너무 슬퍼 보여요. 우리가 그분을 행복하게 해드려야 해요!'),
(26029, '빨리 말하세요.'),
(26030, '스트롬가드에 있는 신디케이트 요원들만이 그 문장을 가지고 있을 것이다. 요새 성벽 밖에서 피를 흘리는 것은 시간 낭비일 뿐이다.'),
(26031, '문장을 복원하려면 다섯 조각 모두가 필요합니다...'),
(26032, '당신은 그 인장을 가지고 있습니까?'),
(26033, '트롤칼라를 가지고 있나요?'),
(26035, '지금까지 뭔가 성과를 거두셨나요?'),
(26036, '우리의 목표는 마법 지팡이 $n입니다. 지금은 거기에 집중하세요.'),
(26037, '$n님, 안녕하세요. 혹시 푸른 마노를 찾으셨나요?'),
(26038, '이렇게 하면 말린이 분명히 아주 만족해할 거예요.'),
(26039, '이 파편 덩어리는 미즈라엘의 파편들과 매우 흡사해 보인다. 하지만 그곳에서 느껴지는 안정감은 전혀 느껴지지 않는다.'),
(26040, '$r, 혹시 그쪽에서 해초 좀 찾아주셨나요?'),
(26041, '이것은 내면의 결속석입니다. 결속석 중에서 가장 강력하며, 다른 결속석들을 열려면 먼저 이 결속석의 잠금을 풀어야 합니다.'),
(26042, '키스톤은 엄청난 지리적 에너지를 지니고 있습니다.'),
(26043, '무엇이 필요하신가요?'),
(26045, '부품 구하는 건 어떻게 되어가고 있어?'),
(26048, '내 부품들 받을 수 있을까?'),
(26049, '미즈라엘의 파편들은 지금 이상할 정도로 조용하다.'),
(26051, '고글은 어땠나요? 모든 기능이 제대로 작동했나요? 필요하면 조정할 수 있습니다. 아, 그리고 다 끝나면 고글을 돌려주셔야 해요. 오브린 선장님이 나중에 유용하게 쓰실 것 같거든요.'),
(26052, '안녕하세요, $c님. 무슨 일로 다리에 오셨나요?'),
(26060, '저는 클리프 스토머의 심장이 필요해요.'),
(26061, '스톤탈론 숫양 뿔이 필요해!'),
(26062, '레조나이트 결정이 필요해요!'),
(26064, '계란이 필요해요!'),
(26079, '안녕하세요. 제출하실 보고서가 있으신가요?'),
(26080, '오스카와 험프리를 찾으셨나요?'),
(26081, '이렇게 하면 말린이 분명히 아주 만족해할 거예요.'),
(26087, '우리는 광채 주스가 아주 많이 필요해요.'),
(26088, '몇 마리나 잡으셨어요?'),
(26090, '<쾅!>$b$b뭘 가져왔어?'),
(26092, '그는 어디에 있었나요? 무슨 일이 있었나요?'),
(26095, '$n, 스트롬가드 배지를 회수했습니까? 신디케이트는 우리의 죽음을 통해 이득을 취할 수 없다는 것을 깨달아야 합니다.'),
(26096, '당신이 악마 한 마리를 머리 위에 얹었다가 불쾌한 일을 겪었다는 이야기를 들었습니다. 하지만 이제 그 악마들은 모두 죽었으니 안심하십시오.'),
(26098, '그… 내 아이가 죽었다고요?'),
(26103, '그 장치는 어떻게 작동했나요, $n?'),
(26107, '맹금류의 눈빛에 담긴 사나움은 우리 전사들의 눈빛에 그대로 드러날 것입니다.'),
(26108, '준비는 다 끝났고, 이제 맹금류 심장만 있으면 돼.'),
(26110, '$n, 그 택배원을 찾는 데 도움을 주셔서 감사합니다. 당신이 없는 동안 Kin이 여기 남쪽에 있는 그 집에서 약사가 나오는 것을 봤다고 합니다. 저는 그들이 뭔가 꿍꿍이가 있다고 확신합니다. 다만 섣부른 행동을 하기 전에 증거가 필요합니다. 혹시 단서를 찾으셨나요?'),
(26111, '$n, 가지고 있나요?$B$B헤아릴 수 없는 자의 뇌가 있다면, 우리는 아직 눈앞에 있는 죽어가는 고대 존재, 르고렉과 소통할 수 있을지도 모릅니다.'),
(26112, '이번 침입의 의미는 무엇인가요?'),
(26122, '제발... 내가 환경운동가라는 걸 다른 고블린들에게 말하지 마! 놀림받는 건 견딜 수 없을 것 같아!'),
(26140, '뭔가 느껴지는데... 더 가까이 와 봐...'),
(26141, '필요한 모든 것을... 갖추셨나요?'),
(26145, '트로그 석기 이빨 여덟 개를 보여주시겠습니까? 없다면, 아직 할 일이 남아 있습니다, $n.'),
(26152, '현상금을 반납하시나요?'),
(26153, '호박 모으기 다 하셨어요?'),
(26157, '나는 당신을 모릅니다.'),
(26159, '가지고 계세요?'),
(26160, '의식은 아직 끝나지 않았습니다.'),
(26161, '날 믿어... 로라무스에게 무슨 일이 일어났든, 우린 고칠 수 있어. 혈마법의 한계는 아직 정해지지 않았으니까.'),
(26163, '안녕하세요, 저를 아시나요?'),
(26164, '목소리를 낮춰주세요.'),
(26165, '으, 무슨 냄새지? 네 냄새야, 아니면 피 냄새야?'),
(26166, '돌아왔군요, $c님.'),
(26167, '알리스타즈는 그 부적에 자신의 일부를 남겨두었다. 지금도 그의 악의 기운을 느낄 수 있다.'),
(26168, '세빈의 부적... 다른 부적들과 함께라면, 우리는 디파일러를 소환할 수 있습니다.'),
(26169, '세 번째 부적은 라젤리크의 셋째 부관이 준 것이다.'),
(26172, '너무 배고파요! 서두르지 않으면 시약을 마셔버릴지도 몰라요.'),
(26176, '제가 무엇을 도와드릴까요?'),
(26177, '손놀림이 정말 빠르시네요! 그렇게 빨리 게를 다 잡으셨다니 믿을 수가 없어요!'),
(26180, '벤처 컴퍼니가 이윤이라는 미명하에 우리에게 저지를 만행을 생각하면 분노가 치밀어 오릅니다.'),
(26183, '즙이 많은 사과를 충분히 찾으셨나요?'),
(26186, '샤야나의 계획은 훌륭해요. $n님, 배는 가지고 계신가요?'),
(26188, '열이 점점 심해지고 정신은 악몽 속으로 빠져드는 것 같아… 할아버지께서도 물리치지 못하신 짐승을 내가 감당할 수 있을 리 없다는 걸 알았어야 했는데… 치료제 재료를 가지고 계신가요? 빨리 치료하지 않으면 죽을 것 같아요.'),
(26190, '물고기를 훔칠 수 있었나요?'),
(26192, '제과용 설탕을 찾으셨나요?'),
(26196, '그래, 나한테 뭘 가져왔어?'),
(26210, '이해하셨나요?'),
(26212, '<라드가 자신의 거대한 배를 문지른다.> 라드는 너무 배고프다.'),
(26213, '놀에 대해 뭔가 찾으셨나요?'),
(26214, '멀록 사냥은 어떻게 진행되고 있나요?'),
(26220, '돼지 도살을 다 끝냈나요?'),
(26222, '부품 좀 찾았나요?'),
(26225, '병이 12개 있어요? 저 셀 줄 알아요!');

