(26241, '재료가 다 준비되는 대로 바로 음식이 준비될 거예요! 서둘러요!'),
(26244, '돌아왔군요, $n님.'),
(26252, '$n, 거기 뭘 들고 있는 거야?'),
(26256, '우리가 세계 기둥을 재건하려면 서둘러야 합니다, $n.'),
(26259, '당신은 돌아왔습니다, $n. 혈액을 확보했습니까?'),
(26264, '방사능에 오염된 노움들의 소유물을 되찾을 수 있던가요?'),
(26266, '안녕하세요. 무엇을 도와드릴까요?'),
(26268, '상자를 몇 개나 찾으셨나요?'),
(26269, '찾으셨나요? 거의 다 읽은 책을 헤멧에 반품하고 싶지 않아요.'),
(26275, '별로 어려운 상대는 아닐 것 같지만, 발놀림이 빠르지 않으면 발목을 할퀴일 수도 있어.'),
(26281, '내 지휘 아래선 동정심은 설 자리가 없다. 트롤들은 다른 데 가서 먹이를 찾을 수 있을 것이다. 여긴 넓은 정글이니까.'),
(26283, '그래서? 뭘 찾았어?'),
(26285, '자, 잃어버린 제 보급품을 찾아오셨습니까?'),
(26286, '공격 명령을 복구하셨습니까?'),
(26295, '혹시 좋은 소식 있으셨나요?'),
(26296, '빨간색 반다나?!'),
(26298, '$c. 블러드스칼프 부족을 사냥했다는 증거를 보여줘. 네 전리품을 보여줘.'),
(26299, '$n. 우리 족장님의 아들이 걱정됩니다. 축소된 머리들을 가지고 계신가요? 제가 한번 살펴보겠습니다.'),
(26300, '솥 안의 초록빛 국물이 보글보글 끓고 있다.'),
(26301, '나는 해골들을 기다린다...'),
(26303, '안녕하십니까, $n님. 정령들은 당신의 용맹함을 칭송하지만, 마이조스에 맞선 당신의 모험에 대한 이야기는 들려주지 않습니다. 혹시 ''눈''을 가지고 계십니까?'),
(26305, '킨윌레이가 당신이 예니쿠를 잡으러 나섰다고 하던데요. 사실입니까? 그를 잡았습니까?'),
(26309, '$c, 저 가마솥 근처에서는 조심해. 바일브랜치가 가만히 있지 않을 거야.'),
(26310, '몇 개나 얻으셨어요?'),
(26311, '아, $c, 돌아왔군. 뭘 발견했나?'),
(26313, '우리는 정령 군주들과 깊은 우정을 나눈 적은 없지만, 혼돈 속에서 약간의 안정을 기대하고 있습니다. 그들이 조직화되지 않은 상태로 있는 한, 우리는 두려워할 것이 거의 없었습니다. 하지만 돌의 어머니가 정말로 지구를 규합하여 우리에게 대항한다면, 우리는 훨씬 더 많은 것을 두려워해야 할 것입니다.'),
(26325, '몇 개나 찾으셨나요?'),
(26329, '다시 돌아와서 반갑군, $n.'),
(26330, '간줄라...'),
(26332, '커다란 트롤의 두개골이 가마솥 안에서 둥둥 떠다닌다.'),
(26334, '내가 바라는 건 랩터 하나뿐이야, $r. 그걸 내게 주면 트롤은 살 거야.'),
(26343, '내 장비는 다 준비됐어, $n, 이제 스킨만 있으면 돼. 리들복스를 기다리게 하고 싶진 않아, 그건 확실해.$b$b팅커스 연합의 최고 발명가를 만족시키지 못하는 건 누구에게도 좋은 생각이 아니야.'),
(26344, '드리즐릭의 엑셀시오르 가죽 부츠, 최고의 장인 정신으로 제작된 100% 최고급 바닷물 악어 가죽 부츠. 이보다 더 좋을 순 없죠!$b$b이렇게 찬사를 받을 만한 게 또 있을까요?$b$b하지만, 혹시 그 가죽을 저에게 주실 수 있다면 얘기가 달라지겠죠?'),
(26345, '어디선가 나이 든 악어들이 서서히 멸종하고 있다는 글을 읽었어요... 제 사업에는 안 좋은 소식이죠?$b$b어쨌든, 나이 든 스냅죠 악어 가죽 좀 구해다 주시면 좋겠어요!'),
(26347, '불꽃은 오래 타오르지 못하고 녹아내릴 거예요. 예전에는 기름을 썼는데, 구하기가 어려웠거든요!'),
(26349, '그 악당, ''늙은 검은 눈''을 처치했습니까? 웨스트폴 해안가를 배회하는 모습이 목격됐습니다. 그 흉악한 짐승을 죽이면 제게 돌아오십시오.'),
(26351, '오가나카라는 이름의 랩터는 여전히 너의 친구야.'),
(26352, '벤처 컴퍼니가 스트랭글쏜에게 저지른 행위는 용서받을 수 없다.'),
(26354, '이게 맞는 총열 같아 보이네요.'),
(26355, '빈 병에 단서가 하나 튀어나와 있다.'),
(26356, '샌더스 선장의 잃어버린 보물이 기다리고 있다!'),
(26361, '스무트는 훌륭한 엔지니어입니다. 사모플란지는 감압식 칼리프락트의 조준을 잘못하면 30야드 거리에서도 사람을 죽일 수 있습니다.'),
(26363, '무엇을 발견했나요?'),
(26366, '어디 한번 볼까요!'),
(26368, '당신은 독을 가지고 있습니까...?'),
(26369, '그녀의 시신을 꼼꼼히 수색하십시오. 바일브랜치가 설치한 함정이 그들의 죽음 속에 감춰지는 것을 원치 않습니다.'),
(26380, '어서 오세요, 손님. 편히 쉬러 오셨나요, 아니면 새 난로돌이 필요하신가요?'),
(26381, '만약 그 태블릿이 속임수였다면, 나는 기쁘지 않을 것이다. 눈을 찾았느냐?'),
(26382, '충분히 가져오셨기를 바랍니다.'),
(26389, '날뛰는 오크 무리를 섬멸했습니까?'),
(26391, '불을 껐나요?'),
(26393, '급하신 것 같네요. 그렇다면 잘 찾아오셨습니다!'),
(26394, '여행 다니셨군요? 재밌는 곳 어디 가셨어요?'),
(26395, '이마에 땀이 맺혔네요, 글래드 부인? 너무 많이 뛰셨나 봐요. 다음에는 그리폰을 타고 가세요!'),
(26396, '스톰윈드에서 돌아오셨군요? 오스릭이 갑옷을 보내줬나요?'),
(26397, '$r님, 왜 호드의 대족장을 찾으시는 겁니까?'),
(26399, '어째서 오거들은 항상 값비싼 유물을 찾아내는 걸까?'),
(26400, '그 상자 열어봤어? 안에 뭐가 들어있는지 너무 궁금해.'),
(26401, '돌아왔군요... 하지만 그가 없이...'),
(26403, '혹시 그 수정 가지고 계세요? 저한테 필요해요! 그러니까... 악랄한 벤처 컴퍼니가 스트랭글쏜에서 세력을 잃어가고 있다는 걸 알아야 하거든요. 아시다시피, 우리 같은 정직한 사람들도 먹고 살아야 하잖아요!'),
(26406, '송곳니를 갖고 있니?'),
(26407, '손이라고요?'),
(26410, '수지는 많이 필요하지 않을 거예요. 하지만 저 바위 깎는 기계들은 꽤 위험하죠.'),
(26414, '그 도전이 너무 버거웠나요?'),
(26418, '가지고 계세요?'),
(26420, '미끼가 효과가 있었나요?'),
(26427, '제가 부탁드린 거 가지고 계세요?'),
(26428, '모두 죽이고 그들의 머리를 가져오라!'),
(26433, '맑은 정신을 가져다주는 성수가 여기 있는 건가!?'),
(26434, '시약이 아주 부드러운지 확인하세요, $n. 거칠고 뻣뻣한 시약은 절대 안 됩니다.'),
(26435, '네, $r님? 저 지금 굉장히 바빠요.'),
(26437, '내가 부탁했던 일을 해줬나요? 수정들을 가져왔나요?'),
(26440, '<페블이 기대에 찬 눈빛으로 당신을 올려다봅니다.>'),
(26442, '상어는 피하신 것 같네요. 덫에 바닷가재는 있었나요?'),
(26443, '무엇을 들고 계십니까, 선생님?'),
(26445, '우리 나이트 엘프 정찰병들이 공격 준비가 거의 완료되었다고 보고했습니다. 저 공포의 군주들을 하루빨리 처치해야 합니다!'),
(26447, '정찰병, 거기 뭘 가지고 있지?'),
(26449, '저 공포의 군주들은 하루빨리 죽어야 해, $n!'),
(26450, '어디 한번 보여줘 봐!'),
(26454, '건축가 네모스는 당신이 오염된 사티르나르에서 건져낸 목재를 가져올지도 모른다고 말했습니다.'),
(26455, '느껴지시나요, $n? 바람에 실려오는 부패의 기운을요? 우리가 아무것도 하지 않으면 부패는 계속해서 확산될 겁니다. 그래서 저는 엘룬의 성배를 찾고 있는 겁니다. 혹시 찾으셨나요?'),
(26456, '$c님, 그게 뭐예요?'),
(26464, '아, 다시 오신 걸 환영합니다, $n님.'),
(26465, '$n님, 작은 조각상을 많이 찾으셨나요?'),
(26466, '조람의 반지가 도시 안의 모든 자물쇠를 열 수 있는 열쇠라고 전해집니다. 혹시 그 반지를 가지고 계신가요, $n?'),
(26468, '그들을 찾았나요? 아닐리아는 뭐라고 했어요? 그녀는 어디에 있나요?'),
(26469, '제발, 아닐리아의 죽음에 대한 복수를 할 수 있도록 도와주세요.'),
(26473, '바트란의 머리카락을 모았습니까, $n? 아이의 건강이 시간이 지날수록 악화되고 있습니다....'),
(26474, '죄송하지만 지금은 통화할 시간이 없습니다. 제 아이 렐라라가 몹시 아픕니다!'),
(26475, '$n, 호수의 흔적을 찾았나요? 눈물을 가지고 있나요?'),
(26476, '안녕하세요. 어떻게 지내세요?'),
(26477, '나무 정령들이 타락해 버린 것이 너무나 안타깝습니다. 그들을 도울 수 있는 일이 더 많았으면 좋겠습니다.'),
(26478, '낚싯대의 마지막 조각, $n을 찾으셨나요? 제 방법은 어땠나요?'),
(26479, '네, $n님? 노력은 어떻게 진행되고 있나요?'),
(26481, '친구여, 란을 처치했습니까? 우리 백성을 노예 상태에서 해방시키려면 그의 두개골이 필요합니다.'),
(26482, '돌아왔군, $n. 막대기 끝에 붙어 있는 건 뭐지? 해골인가?'),
(26485, '닭똥집 있어요?'),
(26486, '12개 정도면 충분하겠죠?'),
(26487, '어디 보자... 자연 하이킹에는 엽총이 필요하고, 석유 시추 시설 당일 여행에는 노 젓는 보트가 필요하겠네... 아, 벌써 돌아왔어?'),
(26488, '제 목걸이를 찾으셨나요?'),
(26489, '어디 보자... 자연 산책에는 엽총이 필요하고, 석유 시추 시설 당일 여행에는 노 젓는 보트가 필요하겠군... 아, 사장님 $n. 벌써 돌아오셨군요?'),
(26490, '네, 가지고 계세요?'),
(26492, '상자들 가져왔어?'),
(26493, '우리가 논의했던 추출 절차를 사용하셨기를 바랍니다.'),
(26494, '어, 그거 잡지에 나온 거 아니야?'),
(26495, '$c님, 설명 좀 해주시겠어요?'),
(26502, '넌 대체 뭐야? 살덩어리로 된 실수라도 되는 거야? 넌 저주받은 존재야! 쓸모 있는 짓이나 하든가, 아니면 내 앞에서 꺼져!'),
(26503, '놀 설계도를 찾으셨나요?'),
(26505, '내 외알 안경 어디에 뒀지?! 코나처, 너야?'),
(26506, '재료는 다 받으셨나요?'),
(26507, '페블이 당신을 올려다보기 시작합니다. 희미하게 빛나는 눈이 점점 더 동그랗고 커집니다.'),
(26508, '안녕. 내 목걸이가 그리워. 아빠가 사주셨는데. 아빠는 호수에 괴물이 있다고 하셔. 혹시 괴물들을 물리쳤니?'),
(26509, '벨리그럽은 아직도 활동하고 있나요, 아니면 레이크셔에서 그 골칫거리를 완전히 없애버리셨나요?'),
(26510, '그놈코더를 복구하셨나요?'),
(26513, '물자를 회수하셨습니까?'),
(26514, '그 목걸이들을 되찾으셨나요?'),
(26517, '무엇을 발견했나요?'),
(26518, '어디 한번 볼까요!'),
(26523, '자, 어떤 실력을 갖췄는지 보여주세요.'),
(26524, '$c, 저 가마솥 근처에서는 조심해. 바일브랜치가 쉽게 내놓지 않을 거야!'),
(26526, '그녀의 시신을 꼼꼼히 수색하십시오. 바일브랜치가 설치한 함정이 그들의 죽음 속에 감춰지는 것을 원치 않습니다.'),
(26528, '태블릿이 맞았나요? 눈을 찾으셨나요?'),
(26529, '송곳니를 갖고 있니?'),
(26530, '가지고 계세요?'),
(26533, '훌륭해... 아직 좀비가 아니시군요. 다행입니다. 아, 음... 아무것도 아니에요. 그냥... 혹시나 위험할 수도 있어서요. 제가 미리 경고해 드렸나요?'),
(26535, '그가 쉬머위드를 썼을까? 아마 쉬머위드를 썼을 것 같아. 아니, 잠깐... 호박씨앗! 분명 호박씨앗일 거야.'),
(26536, '폭포를 찾으셨나요?'),
(26540, '당신은 우리 부상자들에게 희망을 줄 수 있습니까?'),
(26543, '조개를 찾으셨나요?'),
(26544, '무엇을 알아냈나요?'),
(26545, '블랙록 침공 계획을 가지고 있습니까?'),
(26549, '$N, 당신이 우리 "대족장"과 호드에 합류하는 것에 대해 이야기하러 간다고 들었습니다. $B$B조심하세요, $c.$B$B나중에 다시 뵙죠...'),
(26556, '표본 몇 개라도 잡으셨나요?'),
(26557, '그 눈알이 미끼 역할을 했나요?'),
(26560, '메스너! 젠장, 반가운 얼굴을 보니 반갑군. 여기서 나가게 해 줘!'),
(26562, '어머나! 팀원들이 다 모였네... 키샨만 빼고.'),
(26564, '그래서요? 저는 하루 종일 시간이 없어요.'),
(26569, '망원경을 되찾으셨나요?'),
(26571, '머던크와 호머크를 해고했나요?'),
(26572, '거기 어땠어? 꼬리랑 쏠배감펭은 좀 잡았어?'),
(26573, '머리띠와 부적을 찾으셨나요?'),
(26585, '증거를 기다리겠습니다, $r...'),
(26587, '새장 열쇠 구했어?'),
(26588, '혹시 초대형 pike를 잡으셨나요?'),
(26590, '맑은 정신을 가져다주는 성수가 여기 있는 건가!?'),
(26592, '저게 보석인가요?'),
(26593, '어이! 당신이 나를 쳐다보는 눈빛이 마음에 안 드는데요, $gmister:lady;.'),
(26594, '네, 네. 셰이키한테 돈 받았어요?'),
(26595, '$n, 그 채무자들을 찾았나요?'),
(26597, '....어머니? ...너무 추워... ...뒤틀린 지옥으로 향하고 있어...흐흐-엄마, 안아줘...'),
(26598, '주술사 운바그와는 야만인 목이 뭘 좋아하는지 잘 알고 있지. 맞아, 맞아! 내가 영혼과 소통해서 그를 불러낼 수 있어. 하지만 다른 고릴라 괴물들도 영혼과 대화할 수 있지. 네가 주술사 운바그와를 보호해 주면 내가 그를 너에게 보내줄게. 주술사 운바그와는 먼저 원하는 게 있어. 네가 고릴라 송곳니를 가져오면 내가 영혼과 대화를 시작할게!'),
(26599, '어이, $n! 고를라쉬 찾았어? 저 상자는 내가 제일 아끼던 거였는데, 안에는 내 가장 소중한 보물들이 숨겨진 비밀 공간이 있었거든!'),
(26600, '우리는 많은 식량이 필요할 거야, $n. 양보다 질이 중요해.'),
(26605, '무클라가 나에게 무슨 짓을 하려는지 생각만 해도 소름이 끼친다.'),
(26606, '조상님들께 감사드립니다. 누군가 저를 도와주러 왔군요. 저를 풀어줄 열쇠를 가지고 계신가요?'),
(26607, '또 너야?'),
(26612, '안녕, $n. 남쪽 블러드세일 진영에 대한 소식은 어떻게 되는가?'),
(26613, '원하는 물건 찾았어, 친구?'),
(26614, '이봐, 친구! 잘 안 보일지 몰라도 항구 건너편에서도 네 냄새가 나. 내 눈이 정말 필요해. 선장님이 내 눈이 그 더러운 블러드세일 해적들 손에 들어갔다는 걸 알면 날 가만두지 않을 거야. 볼 수 없는 망보는 무슨 소용이야? 망루가 내 집이나 다름없었는데... 내 등대가 없었으면 뱃저기 청소라도 할 수 있었을 텐데.'),
(26617, '$r, 그게 뭐예요? 좀 보여주세요.'),
(26620, '늑대 치마살 스테이크 다섯 개를 찾으셨나요?'),
(26623, '안녕하세요, $n님. 저를 위해 덩어리 고기를 구해 오셨나요?'),
(26625, '그 사람 죽었어? 몽둥이 있어?'),
(26629, '피랄론이 직접 특별 주문한 겁니다. 타우렌은 너무 위험 부담이 크다고 하더군요.'),
(26630, '대부분의 타우렌들은 이걸 부끄러운 일로 여길 거라는 걸 알아야 해. 난 오히려… 재밌다고 생각하지만 말이야.'),
(26631, '서류는 잘 챙겼겠지, 이봐. 널 얀시로 다시 돌려보내고 싶진 않으니까.'),
(26634, '너무나 많은 훌륭한 사람들이 예방 가능한 질병으로 죽어가는 것을 봤습니다. 우리에게는 라임이 필요합니다.'),
(26635, '제가 처음부터 병원 청소부였던 건 아니었어요.'),
(26636, '나뭇잎이랑 똥 - 그게 바로 내가 필요한 거야.'),
(26637, '림프선을 회복하셨나요?'),
(26640, '그들이 브루베이커를 데려갔나요?'),
(26641, '계란 있어요?'),
(26652, '<흐느낌> 제발, 저를 보지 마세요! 제가 제 손으로 이 눈들을 뽑아냈는데도 당신의 시선이 느껴져요! 전 끔찍해요! 정말 끔찍해요! 제발, 눈을 돌려주세요!!'),
(26654, '당신이 맹인 메리를 본 것 같군요. 제 빗을 가지고 계신가요...?'),
(26655, '원치 않는 악령을 막기 위해 문과 창문에 귀신 머리카락 실을 꿰어야 하는데, 혹시 구해다 주셨나요?'),
(26658, '망치를 찾으셨나요?'),
(26661, '안녕하세요, $n님. 혹시 저에게 주실 썩은 꽃이 있나요?'),
(26667, '저봐요, 아가씨, 전 정말 아무런 문제도 일으키고 싶지 않아요...'),
(26669, '무사히 돌아오셨군요.'),
(26670, '제가 말씀드렸잖아요, $n, 이건 추구할 가치가 없다고...'),
(26671, '돌아왔구나! 내 동생에 대해 뭐 찾은 거 있어?'),
(26672, '어떤 어두운 속삭임이 당신을 내 문 앞까지 이끌었나요, $c?'),
(26676, '이 춥고 어두운 밤에 몸을 따뜻하게 하려면 좀비 주스가 필요해. 사다 줬어?'),
(26677, '레이븐 힐에서도 맛있는 립을 많이 찾을 수 있을 거라고 확신하지만, 밤에 그렇게 멀리까지 돌아다니고 싶지는 않을 거예요...'),
(26679, '당신이 없는 동안 누가 나타났는지 맞춰보세요?'),
(26680, '제 상자 가지고 계신가요? 있다면, 제발... 빨리 주세요!'),
(26681, '편지라고? 이게 다 무슨 뜻이지?'),
(26684, '나는 코그에게 우리가 만든 별 관측 장치의 초기 모습을 보여주었다. 그는 감명을 받았다. 혹시 반사 장치를 찾으셨나요?'),
(26685, '자르크불을 설득해서 우리 실험에 쓸 외알 안경을 빌릴 수 있었나요?'),
(26691, '네, 무슨 일이죠? 빨리 말씀해 주세요, 급한 일이 있어서요.'),
(26693, '네, 말씀하신 내용이 아주 잘 들립니다, $n님.'),
(26695, '너 아직 살아있어?'),
(26706, '위험을 무릅써도 승리할 수만 있다면 괜찮아요.'),
(26707, '시체풀 있나요?'),
(26719, '무슨 일로 여기까지 오셨습니까, 부인?'),
(26721, '이해했나요? 이해했다고 말해주세요...'),
(26729, '네, $n?'),
(26730, '소금 말인가요?'),
(26731, '결과를 간절히 기다리고 있습니다.'),
(26732, '저는 여가 시간에 연금술을 좀 하곤 해요.'),
(26733, '이 묘약에는 뭔가 석연치 않은 점이 있어, $n. 아직 분석을 완료하진 않았지만, 그런 느낌이 들어.'),
(26734, '$n, 그거 조심해서 다뤄. 뭔지 모르잖아.'),
(26735, '$n님, 무엇을 찾으셨나요?'),
(26740, '안녕하세요! 저한테 뭐 가져오셨어요?'),
(26742, '조심하세요: 그들은 저항할지도 모릅니다.'),
(26743, '이러한 토템 생물들은 이 정글을 배회하는 환상적인 생물들을 바탕으로 만들어졌을 가능성이 높습니다.'),
(26744, '발랄 유적까지 내려가 봤어요? 석판은 찾았나요?'),
(26746, '몇 개나 찾으셨나요?'),
(26747, '간줄라는 잔인하고 폭군 같은 존재였지. 하지만 이 트롤은 뭔가 다를 것 같아. 이 트롤의 마법은 생각보다 훨씬 쉽군!'),
(26748, '내가 바라는 건 랩터 하나뿐이야, $r. 그걸 내게 주면, 그놈은 살 거야.'),
(26760, '실례합니다만, 아직 끝나지 않았습니다.'),
(26763, '그 수정들을 가지고 계신가요?'),
(26765, '안녕하세요, $n님. 고블린 크라젝이 제 냄비를 고쳐줬나요?'),
(26766, '고기를 구하셨나요?'),
(26768, '만약 그 덫이 스톤 드레이크에게 효과가 있다면, 어비션에서도 효과가 있을지도 모릅니다.'),
(26769, '어서 오세요, $c님. Ratchet에서 막 돌아오셨나요? 무슨 소식 있으세요?'),
(26772, '오가나카라는 이름의 랩터는 여전히 너의 친구야.'),
(26774, '엄청나게 강력한 마법에는 엄청나게 뛰어난 두뇌가 필요하죠, 맞습니다.'),
(26781, '당신은 그 눈을 갖고 있습니까?'),
(26782, '어째서 오거들은 항상 값비싼 유물을 찾아내는 걸까?'),
(26783, '어째서 오거들은 항상 값비싼 유물을 찾아내는 걸까?'),
(26784, '강 안에서의 싸움이 너무 위험하지 않았기를 바랍니다.'),
(26787, '받으셨습니까? 받으셨냐고요?'),
(26788, '흙 있으세요? 새 벽체 공사가 이미 시작됐어요!'),
(26795, '그와 문제가 생기더라도 당신을 탓하지 않겠습니다, $n. 우리 파수꾼 중 가장 뛰어난 몇몇이 모르라딤에게 희생되었으니까요.'),
(26797, '날 내버려 둬...'),
(26799, '가장 약하고 멍청한 생물체조차 죽이지 못한다면 이 새로운 삶에서 멀리 나아가지 못할 것이오. $n. 성공 사례를 보고할 때까지 돌아오지 마시오.'),
(26800, '그곳에서 시체 좀 가져왔나?'),
(26801, '이 일에 미적거리는 자들은 마을에서 쓰러진 우리 형제자매들처럼 목적 없이 방황하게 될지도 모릅니다. 당신은 그들보다 더 나은 운명을 맞이하길 바랍니다, 그렇죠?'),
(26802, '내가 방어구를 만들어주기 전까지는 다치지 않도록 조심하게.'),
(26806, '오그리마로 돌아갈 준비가 되셨나요?'),
(26807, '보고서 가져오셨나요?'),
(26808, '$c님, 설명 좀 해주시겠어요?'),
(26815, '훌륭해... 아직 좀비가 아니시군요. 다행입니다. 아, 음... 아무것도 아닙니다. 그냥... 혹시나 위험할 수도 있을 것 같아서요. 제가 미리 경고하는 걸 깜빡했나요?'),
(26816, '그가 쉬머위드를 썼을까? 아마 쉬머위드를 썼을 것 같아. 아니, 잠깐... 호박씨앗! 분명 호박씨앗일 거야.'),
(26817, '<다스크는 당신이 다가오자 당신의 배낭을 간절한 눈빛으로 바라봅니다.>'),
(26818, '오... 부드러웠으면 좋겠네요!'),
(26819, '다시 오신 것을 환영합니다!'),
(26820, '어디 한번 보여줘 봐!'),
(26821, '네, $r님? 저 지금 굉장히 바빠요.'),
(26823, '임무는 네가 맡았어? 난 플라스크를 맡을게.'),
(26824, '연기가 보였어요. 괜찮으세요?'),
(26825, '섞어야 할 게 있으세요?'),
(26826, '섞어야 할 게 있으세요?'),
(26841, '$n 님, 와주셔서 기쁩니다.'),
(26842, '그럼, 내 말을 들어줄 사람 좀 있나요?'),
(26845, '설마 저기 아래에 있던 사람이 모이라였겠어요? 기적은 일어나기도 하죠.'),
(26855, '안녕하세요, $n님. 제 친구 힐델브의 소식을 아시나요?'),
(26858, '타라가만이 죽었다면, 그의 심장을 내게 보여주시오.'),
(26860, '요리할 준비는 다 됐는데, 곰고기 있어요?'),
(26862, '제본된 책갈피 있으세요?'),
(26863, '$n님, 광부 장비 가지고 계신가요?'),
(26864, '알가즈 기지 소식 있나요?'),
(26871, '살아있군요. 다행입니다. 보석은 가지고 있나요?'),
(26872, '네가 그 짐승들을 몇 마리나 죽였느냐?'),
(26873, '당신이 충분한 양의 뱀꽃을 모을 수 있을지 정말 기대됩니다.'),
(26875, '제본 작업이 중단되면 안 됩니다. 뒷방에서 당신의 도움이 필요해요. 서둘러 주세요.'),
(26876, '$n! 돌아오셨군요!'),
(26882, '다시 만나서 반갑습니다, $n. 무슨 소식이 있나요? $B$B탐험은 성공적이었나요? Thaelrid를 찾았나요?'),
(26883, '블랙패덤 심연은 한때 고대 나이트 엘프 사원이었습니다. 그곳에는 한때 매우 강력한 달의 샘이 있었죠. 황혼의 망치단이 지금 그곳에서 어떤 사악한 음모를 꾸미고 있을지 누가 알겠습니까?$b$b그들을 사원에서 몰아내는 데 진전이 있었습니까?'),
(26884, '연구에 필요한 표본을 충분히 확보하면 비로소 진정한 연구가 시작될 수 있겠지. 블랙패덤 심해의 사티르와 나가의 변형된 뇌간을 분석해 돌연변이 사이의 상관관계를 밝혀낼 수 있을 거야. 어쩌면 그 지식을 통해 블러드 엘프들이 더욱 기형적이고 사악한 길로 빠져드는 것을 막을 수 있을지도 몰라.'),
(26885, '친구, 자네의 임무는 쉽지 않네. 하지만 원고를 가져다준다면, 자네는 큰 보상을 받을 것이고, 우리는 황혼의 망치와 나가들이 꾸미고 있는 일에 대해 더 잘 이해하게 될 것이네.'),
(26887, '충치 치료하셨나요?'),
(26890, '$n, 수정 찾는 건 어떻게 되어가고 있어? 그 수정으로 나가를 막을 수 있는 물건을 만들 수 있을 거라고 생각해?'),
(26891, '심해 핵을 찾는 데 성공했습니까? 그것 없이는 황혼의 망치가 심해에서 정확히 무슨 일을 꾸미고 있는지 알 수 없습니다.'),
(26899, '복수...보상...'),
(26901, '아, 돌아오셨군요. 크롤 구아노는 구하셨나요?'),
(26905, '<아가마간의 정령이 당신을 인내심 있게 바라봅니다.>'),
(26910, '안녕하세요, $n님. 제가 도와드릴 일이 있을까요?'),
(26912, '미즈라엘의 파편들은 지금 이상할 정도로 조용하다.'),
(26913, '자, 한번 시도해 보셨소?'),
(26914, '자, 한번 시도해 보셨나요?'),
(26915, '자, 한번 시도해 보셨소?'),
(26916, '자, 한번 시도해 보셨나요?'),
(26917, '자, 한번 시도해 보셨나요?'),
(26918, '자, 한번 시도해 보셨나요?'),
(26919, '자, 한번 시도해 보셨나요?'),
(26925, '아라즈는 만만치 않은 상대다. 철저히 대비해야 한다.'),
(26928, '너 진짜 지독하게 냄새나! 멀록 때문인 것 같은데, 확실히는 모르겠네.'),
(26929, '그래서 그 악어 같은 것들을 정말로 얻었나요, 아니면 제가 지어낸 이야기인가요?'),
(26934, '동물 조직은 식물 조직보다 질병을 훨씬 더 잘 보존하는 것 같지 않나요?'),
(26951, '마스크는 다 모았어, $c?'),
(26961, '그 우상들을 가지고 있습니까? 우리는 그것들을 연구하고 그 결과를 아이언포지에 보고해야 합니다!'),
(26966, '당신은 인장과 판단력을 사용하는 연습을 해보셨나요?'),
(26992, '제가 요청한 사나운 파멸의풀을 채집하셨나요?'),
(26993, '나는 언데드를 혐오하는 광신도들로 가득 찬 수도원에 더 이상 머물고 싶지 않아. 내 심정을 이해하시겠지? 책을 가지고 있지 않으면 내게 말을 걸지 마.'),
(26995, '기억하세요, 우리가 개발 중인 새로운 역병균에는 깨끗한 짐승의 내장만 사용할 수 있습니다.'),
(26996, '<도미닉이 당신을 응시합니다.>'),
(26998, '새벽의 섬에 사는 사악한 지느러미 멀록들을 전멸시켰습니까?'),
(26999, '동물들이 모두 회복되면, 이곳에서의 우리의 임무는 거의 끝나는 것입니다.'),
(27004, '그 계획들이 모든 것의 핵심입니다.'),
(27005, '그 계획들이 모든 것의 핵심입니다.'),
(27011, '나이 지긋하신 벌목꾼 몇 분 말씀으로는 레드파인이 몇 년 전까지만 해도 이 지역에 살았지만, 전염병이 돌자 떠났다고 합니다. 하지만 그렇다고 해서 그들이 도둑질을 해도 된다는 건 아니죠.'),
(27012, '어머니의 걱정 때문에 놀족을 대량 학살하라는 명령을 내리고 싶은 게 아닙니다. 그저 제 집에서 안전함을 느끼고 싶을 뿐입니다.'),
(27014, '만나서 반갑습니다, $n님.'),
(27015, '만나서 반갑습니다, $n님.'),
(27017, '$n님, 향수에 젖은 노인의 변덕을 당신이 들어주실 거라고는 기대하지 않습니다. 하지만 혹시라도 이 근처에 오시게 된다면...'),
(27019, '저는 정치에는 관심이 없습니다. 당신이 호드 편이든 얼라이언스 편이든 상관없습니다. 저는 모든 종족을 위협하는 직접적이고 심각한 위협을 제거하는 데 더 관심이 있습니다... 그리고 이곳에는 아주 큰 위협이 도사리고 있습니다. 만약 당신이 모든 종족을 위한 진정한 영웅이 될 의향이 있다면, 제가 당신에게 준 맹세석을 제게 넘겨주십시오. 저는... 이 지역 출신이 아닙니다. 우리 종족에게 맹세석은 약속의 증표로서 중요한 의미를 지닙니다.'),
(27025, '지금 바로 안전하게 다루세요!'),
(27028, '저 말벌들은 어떻게 지내나요?'),
(27029, '상아를 가지고 있나요?'),
(27030, '나한테 뭘 준비했어?'),
(27031, '최고급 깃털만 사용해야 합니다!'),
(27036, '아, $n! 벌써 돌아왔군? 또 사냥을 나갔었나 보군? 혹시 어려움이 있었더라도 걱정 마. 결국엔 더 나아질 거야!$b$b...어쨌든 더 나빠질 순 없잖아...'),
(27037, '정말 잘했어, $n! 우리가 제대로 혼쭐을 내줬군! 자, 머리 좀 줘 봐. 내가 알아서 할게.'),
(27038, '어? 내 부품들. 어디 있지? 부품 없이 탱크를 만들 순 없잖아! 만약 만든다고 해도 작고, 대부분 내부 부품으로만 만들어질 거라고.'),
(27047, '파이나이트는 우리에게 가장 가치 있는 재료 중 하나이며, 특히 우리가 자체적으로 대부분의 매장지에 접근할 수 없다는 점에서 더욱 그렇습니다.'),
(27048, '팔?'),
(27051, '내가 부탁한 대로 했습니까? 그들이 소유하고 있는 성장 촉진제를 완전히 제거해야 합니다.'),
(27053, '마법 솥의 점검용 덮개는 단단히 잠겨 있습니다. 덮개를 열려면 열쇠를 찾아야 합니다.'),
(27054, '말리시아가 가지고 있던 서류를 살펴보세요...'),
(27056, '여왕 앞에 무릎 꿇어라, $n.'),
(27057, '가론의 시들어가는 곳에는 맹렬한 역병을 내뿜는 가마솥이 있습니다. 그곳에서 뿜어져 나오는 역병 샘플을 확보하면 저주받은 자들의 교단이 정말로 이 땅을 계속해서 오염시키고 있는 것인지 밝혀낼 수 있을 것입니다.'),
(27070, '제가 필요한 걸 가지고 계신가요?'),
(27077, '뾰족한 부분을 뽑아버렸나요?'),
(27082, '우리는 버림받았어! 이게 우리가 하는 방식이야, $c.'),
(27096, '그럼 오크들은요?'),
(27100, '메모들을 훑어보며 순서를 정하려고 애쓴다.'),
(27103, '봉인된 순수의 성물을 손에 넣게 되면, 세상을 타락시키는 위협을 제거할 수 있을 뿐 아니라, 우리의 신중한 관찰 하에 그것을 연구할 수도 있을 것입니다. 어쩌면 아제로스를 끊임없이 위협하는 타락의 오염에 맞서 싸울 새로운 방법을 고안해낼 수도 있을 것입니다.'),
(27105, '당신은 그 핵심을 담아냈습니까, 아니면 그 임무가 너무 어렵다고 판단했습니까?'),
(27107, '$R에게 책이 있나요?'),
