(27112, '당신은 그 끔찍한 괴물들을 처치했습니까?'),
(27119, '오우거 탄닌만 구해다 주면, 크롬크러쉬 선장이 당신을 자기 부하로 착각할 만큼 멋진 오우거 복장을 뚝딱 만들어 줄게요.'),
(27126, '저것들은 예비 부품인가요?'),
(27135, '당신은 아직 마음을 먹었나요?'),
(27143, '$r, 내 앞에서 고개를 숙이시오. 나는 귀족이고, 당신은 돈 한 푼 없는 농민일 뿐이오.'),
(27164, '아라즈는 만만치 않은 상대다. 철저히 대비해야 한다.'),
(27166, '$n님, 다시 뵙게 되어 반갑습니다.'),
(27167, '저희는 먼 길을 왔습니다. 조금이라도 도움을 주시면 정말 감사하겠습니다.'),
(27171, '우서의 무덤에서 무슨 일이 있었나요, $n?'),
(27172, '발로피스트가 보낸 겁니까? 그는 정말 멈출 줄 모르는군요.'),
(27176, '네, $n?'),
(27177, '얼마나 회복하셨나요?'),
