(27247, '저에게 주실 게 있으신가요?'),
(27252, '셰이디 레스트 인 부지에서 증거를 찾으셨습니까?'),
(27254, '$n, 당신이 들고 있는 건 뭐죠? 셰이디 레스트 여관 유적에서 나온 증거인가요?'),
(27255, '저한테 주실 것 좀 있나요, $c?'),
