(27296, '그 손전등을 제대로 활용해 보셨나요?'),
(27302, '저걸 정령한테 뿌리면 어떻게 될지 궁금하네. 초대형 불꽃 정령이 될까? 그럴 것 같아. 한번 시도해 봐야겠어.'),
