(27321, '우리는 그냥 걸려 있는 두루마리가 아니라, 실제 영장이 필요합니다.'),
(27322, '코록이 죽었나요?'),
(27325, '타우렌족은 북을 정말 좋아하죠. 전쟁의 북소리는 다른 북소리와는 뭔가 특별할 거라고 상상만 해도 즐겁네요.'),
(27326, '전쟁은 대지의 어머니의 가르침에 충실한 사람들이 참여해서는 안 되는 활동입니다.'),
