(27411, '브로그는 복수할 것이다!'),
(27413, '혹시 웜테일을 찾으셨나요?'),
(27414, '검은 용 군대의 불타버린 자손들의 심장과 혀를 이용해, 어떤 비열한 짐승이 우리 고향에 그 자식들을 데려왔는지 알아낼 수 있을 것이다. 침략자에 대한 더 깊은 이해를 통해, 우리는 그들을 완전히 섬멸하고 스톤몰 마을을 폐허에서 되찾을 수 있을지도 모른다. 물론, 목모록을 그 무기력하고 뚱뚱한 몸뚱이에서 이 진흙탕 구덩이에서 나오게 설득하는 것 자체가 하나의 장대한 모험이 될 것이다...'),
(27424, '술이 목마르군. 코담배도 그립고. 금고는 어디 있지? 목모록 군주에게 가서 가져오라고. 옛집 남쪽으로 가 봐. 난 오우거들을 이끌고 있어서 갈 시간이 없어.'),
(27426, '주문서의 흔적을 찾을 수 있었나요?'),
(27427, '그 무기들은 블랙후프 마을에서 얻은 건가요?'),
(27429, '그 손전등을 제대로 활용해 보셨나요?'),
(27432, '은신처를 찾았나, $n? 젤다르는 처리했나?'),
(27433, '$n, 나한테 뭐 사줬어?'),
(27434, '내가 무기를 만드는 데 필요한 재료들을 가져왔나요?'),
(27435, '내가 무기를 만드는 데 필요한 재료들을 가져왔나요?'),
(27436, '내가 무기를 만드는 데 필요한 재료들을 가져왔나요?'),
(27437, '내가 무기를 만드는 데 필요한 재료들을 가져왔나요?'),
(27439, '내가 무기를 만드는 데 필요한 재료들을 가져왔나요?'),
(27441, '내가 무기를 만드는 데 필요한 재료들을 가져왔나요?'),
(27444, '렌드는 쉽게 무너지지 않을 것이다.'),
(27450, '혹시… 혹시 물고기 가져오셨어요?'),
(27451, '코린스 크로싱은 어떻게 지내고 있나요?'),
(27452, '지금까지는 모든 게 순조롭게 진행되고 있는 거죠, $n?'),
(27453, '우리는 거의 공격할 준비가 되었습니다, $n.'),
(27456, '당신도 그 맛에 익숙해질 거예요, $r. 저도 그랬거든요.'),
(27458, '언데드와 싸우고 있었군. 브로먼은 찾았나?'),
(27468, '바위, 그루터기, 언덕, 진흙... 쳇. 난 자연이 싫어.'),
(27474, '뭔가 찾으셨나요?'),
(27475, '서비터 코어를 복구하셨습니까?'),
(27476, '네? 무슨 일이죠?'),
(27478, '달라란 대마법사의 인장 반지를 되찾으셨나요?'),
(27479, '<안달 부제는 깊은 기도에 잠겨 있습니다.>'),
(27480, '$n, 네가 들고 있는 건 뭐야?'),
(27481, '나는 이 날을 오랫동안 기다려왔다.'),
(27484, '무엇을 배웠나요?'),
(27488, '노스데일에는 유령과 밴시가 몇 마리 출몰하지만, 기디라면 뭐든 해결할 수 있지.'),
(27489, '시간이 없어, $n! 계속 나아가야 해!'),
(27500, '배낭에서 피가 떨어지는 건가요?'),
(27501, '배낭에서 피가 뚝뚝 떨어지는 건가요? 설마 당신 피는 아니겠죠?'),
(27508, '황혼의 용들은 그들의 역겨운 실험의 결과물이다. 황혼의 망치단은 너무 멀리 갔다. 데스윙 또한 너무 멀리 갔다.'),
(27512, '포털에서 윙윙거리는 소리가 난다.'),
(27515, '$c, 나한테 뿌리 좀 구해줬어? 어때?'),
(27517, '$n, 뭘 찾았어?'),
(27523, '그 괴물을 없애버렸기를 바랍니다.'),
(27531, '필요한 물건은 다 갖췄어?'),
(27532, '하이비컨의 소포... 아르거스는 안전한가요? 무슨 일이라도 생긴 건가요?'),
(27534, '제 영수증 책자 가지고 계신가요? 어서 업무에 복귀하고 싶어요!'),
(27536, '저기, 내가 물어봤던 것들 받았어?'),
(27537, '안녕하세요, $c. Kurdran 님이 이 포털을 열 수 있는 해결책을 찾으셨다고 하던데요?'),
(27538, '베럴 강에 진흙탕이 있다는 얘기를 자꾸 듣는데, 그게 무슨 말일까요?'),
(27539, '꽤 바쁘신 것 같군요. 저건 해골인가요?'),
(27541, '무슨 소식 있어, $n?'),
(27549, '그래서? 흥미로운 거라도 찾았어?'),
(27551, '뭐라고요? 뭐 찾았어요?'),
(27574, '나는 얼굴을 절대 잊지 않아!'),
(27575, '적어도 악어 가죽으로 멋진 신발을 만들 수는 있겠죠.'),
(27577, '더러운 드워프 시체를 모두 수색해라.'),
(27586, '조개껍데기 있어요? 이리 주세요! 살살!'),
(27587, '꼬리 달았어? 엉성하게 잘린 꼬리 달고 나한테 들이밀려고 하지 마!'),
(27592, '"형, 물건 가져왔어?"'),
(27596, '당신은 산의 심장을 갖고 있습니까? 제게 있어 그 가치는 무한합니다.'),
(27599, '너 그 작은 주머니들 받았어? 고블린들은 거기다 두고 왔길 바라!'),
(27600, '알았어? 알았냐고? 대포 쏴봤어? 폭발 안 했잖아!'),
(27604, '자말란을 죽였습니까? 그 일을 끝냈다는 증거가 필요합니다.'),
(27608, '배낭에서 피가 떨어지는 건가요?'),
(27609, '배낭에서 피가 뚝뚝 떨어지는 건가요? 설마 당신 피는 아니겠죠?'),
(27614, '그들과 치열한 접전을 벌였기를 바랍니다.'),
(27623, '상형문자에 묻은 모래를 닦아내도 새로운 모래층이 다시 덮인다. 서둘러야 할 것이다.'),
(27624, '재밌는 거 찾았어, $n?'),
(27626, '그들은 안전한가요?'),
(27632, '이게 바로 당신이 찾던 지도일지도 몰라요.'),
(27647, '너 맨정신인데 냄새가 너무 심해! 술 좀 찾아줘!'),
(27648, '그들은 계속 몰려오지만, 난 계속 주먹을 휘두를 거야!'),
(27649, '내 술 어디 있지?'),
(27652, '펜던트가 몇 개나 있으세요?'),
(27653, '펜던트가 몇 개나 있으세요?'),
(27663, '닭다리 있어요?'),
(27664, '화산 덱을 완성하셨군요! 축하드립니다!'),
(27665, '허리케인 덱을 완성하셨군요! 축하드립니다!'),
(27666, '쓰나미 덱을 완성하셨군요! 축하드립니다!'),
(27667, '지진 덱을 완성하셨군요! 축하드립니다!'),
(27673, '코어는 어디 있느냐, 얘야? 무라딘의 수염을 걸고 맹세하건대, 그 빌어먹을 코어는 어디 있냐고? 미안하다. 코어는 구했느냐?'),
(27675, '저에게 주실 것이 있으신가요?'),
(27682, '핵심 재료들을 가지고 오셨나요, 아니면 그냥 담소 나누러 오신 건가요? 이 허세는 그만하고 안주와 좋은 와인이나 즐기러 가는 게 어떨까요?'),
(27686, '저에게 주실 것이 있으신가요?'),
(27687, '$c, 네가 그 바다 거인을 쓰러뜨렸어?'),
(27694, '당신이 이 유물들을 모으는 것은 신앙의 증표가 될 것입니다. 유물들이 준비되면 제가 의식을 거행하겠습니다.'),
(27695, '도끼 있어? 걔네들이 곧 리라스트라자를 죽일 거야.'),
(27696, '도끼 가지고 있어?'),
(27699, '그거 뭐 들고 있어, 친구?'),
(27706, '돌아왔구나, $n!'),
(27713, '들을 건가요, 말 건가요?'),
(27716, '하! 제독이 날 매섭게 노려보는 걸 보고 동정심을 느껴서 그런 거야? 이 폐허가 이 엉망진창 속에서 뭔가 쓸모를 건져낼 기회를 준다는 걸 그에게 이해시킬 희망은 거의 없어. 사실 자네가 다시 나타나주길 바랐네. 자네만이 내가 믿을 수 있는 유일한 사람 같거든. 잠깐... 자네 손에 든 건 뭐지?'),
(27717, '하! 선장이 날 매섭게 노려보는 걸 보고 동정심을 느껴서 그런 거야? 이 폐허가 이 엉망진창 속에서 뭔가 쓸모를 건져낼 기회를 준다는 걸 그에게 이해시킬 희망은 거의 없어. 사실 네가 다시 나타나주길 바랐거든. 네가 내가 믿을 수 있는 유일한 사람 같아. 잠깐... 네가 들고 있는 건 뭐지?'),
(27737, '당신들 핵심 인물들 있습니까? 우리 병사들이 여기서 죽어가고 있어요!'),
(27739, '호거를 물리치셨나요?'),
(27742, '얼마나 들 수 있을 것 같아?'),
(27750, '배고픈.'),
(27751, '$c, 네가 모은 휘장들을 보여줘.'),
(27752, '$n, 맥주 좀 가져다 줘. 야, 너 혹시 위에 맥주 얹어 먹고 있는 거 아니지?'),
(27753, '먹을 거 좀 있어요?'),
(27754, '싸움은 어떻게 진행되고 있나요, $c?'),
(27760, '단말기의 작동 메커니즘이 가동되면서 윙윙거리는 소리가 난다.'),
(27764, '아... 날 찾았군. 잘됐군.'),
(27765, '계란 가져오셨어요?'),
(27766, '내가 부탁한 대로 했니?'),
(27767, '다시 만나서 반갑습니다, $n. 폭군 린의 경비병들이 당신을 감옥에 가둔 줄 알고 걱정했었습니다.'),
(27771, '$n... 명심해. 이건 검은 용군단을 위한 거야. 우린 그들을 해치려는 게 아니라 구원하려는 거야. 이건 그들의 회복을 위한 한 걸음일 뿐이야.'),
(27772, 'H. 블램 박사입니다. 어떻게 도와드릴까요?'),
(27775, '저는 제 발명품에 마법을 쓰는 걸 좋아하지 않지만, 이번 일은 어쩔 수 없이 비상사태네요.'),
(27776, '그들이 벼랑 끝에 너무 가까이 서 있었던 게 잘못이다.'),
(27777, '성공하셨나요, $n님? 제가 예상한 생존 확률은 68.5%입니다.'),
(27789, '아직 완전히 끝나지 않았어요. 시간이 좀 더 필요해요.'),
(27792, '가방이 무거워 보이네요. 해방된 유물들로 가득 차서 그런가 보군요?'),
(27794, '자, 어때요? 우리의 무모한 시도가 성공했을까요?'),
(27800, '$n, 다시 만나서 반갑습니다. 우리는 워치프가 당신을 잡았을지도 모른다고 생각했습니다.'),
(27805, '그들의 귀중품을 찾으셨나요? 사소해 보일지 모르지만, 이런 시기에는 작은 것 하나하나가 누군가에게는 큰 의미가 있거든요.'),
(27814, '지금까지 몇 개나 모으셨나요?'),
(27815, '이게 뭐지?'),
(27818, '겁먹지 마세요.'),
(27823, '<지그룬은 기대감에 입술을 핥는다.>'),
(27824, '벌써 돌아오셨네요?'),
(27825, '다시 오신 것을 환영합니다.'),
(27826, '$n 님이 가지고 계신 짐은 정말 귀중하군요.'),
(27839, '돌아왔군요, $n님. 수술은 어떻게 됐나요?'),
(27840, '크리스탈 가지고 계세요?'),
(27841, '혹시 죽은 자의 빵은 없으신 거죠?'),
(27846, '혹시 죽은 자의 빵은 없으신 거죠?'),
(27851, '상황이 어떻습니까?'),
(27875, '기도꽃을 가져오셨나요?'),
(27876, '샘플 받으셨나요?'),
(27877, '<리디아는 기대에 찬 눈으로 기다린다.>'),
(27878, '벌써 돌아오셨네요?'),
(27879, '다시 오신 것을 환영합니다.'),
(27882, '당신은 해방된 유물들을 가지고 돌아오셨겠죠?'),
(27888, '자, 어때요? 우리의 무모한 시도가 성공했을까요?'),
(27889, '$n 님이 가지고 계신 짐은 정말 귀중하군요.'),
(27901, '타이탄 활성화 장치 가지고 계신가요, $n?'),
(27902, '원소들이 그 근원을 드러낸 것일까?'),
(27903, '이 오래된 방식이 여전히 작동하는지 확인해 볼 시간입니다...'),
(27904, '크리스탈 가지고 계세요?'),
(27907, '기도꽃을 가져오셨나요?'),
(27908, '헬그럼은 아직 숨을 쉬고 있다. 진흙은 있느냐?'),
(27909, '돌아왔군요.'),
(27910, '더스크팽이 모습을 드러낸 건가요?'),
(27916, '예?'),
(27920, '주된 목표와는 전혀 상관없는 유령 병사들을 죽여야 한다는 게 정말 짜증나지만, 어쩔 수 없죠. 고드프리는 정말 교활한 적입니다.'),
(27924, '$n, 부품 다 받았어?'),
(27928, '사냥에 성공하셨나요?'),
(27933, '필요한 모든 것을 갖추셨나요?'),
(27938, '돌아왔군요. 중간 조각은 되찾았나요?'),
(27939, '사막여우를 잡으셨나요, $c?'),
(27941, '필요한 유니폼을 되찾으셨나요?'),
(27942, '당신이 내게 우상을 가져다주었나요, 그렇죠?'),
(27943, '자, 꼬마 $gman:lady;? 성공했나요?'),
(27945, '심장. 순수한 검은색의 돌 심장. 혹시 찾으셨나요?'),
(27948, '끈적끈적한 누에실샘을 모으실 수 있었나요?'),
(27954, '블랙 브리치에서 뭔가 성과를 거두셨나요?'),
(27956, '기어를 구하셨어요? 어떻게 구하셨어요?'),
(27958, '와, 정말 빠르시군요! 독도 있으시죠?'),
(27961, '불쌍한 동물들.'),
(27962, '뿔피리를 가져와, $n.'),
(27963, '무슨 소식 있어요?'),
(27964, '딘위스커에서 우리가 원하는 것을 찾지 못한다면, 다음에 뭘 해야 할지 모르겠네요.'),
(27966, '대퇴골을 되찾으셨나요? 제가 시도하는 것보다 당신이 시도해 보는 게 나을 것 같네요.'),
(27972, '럼주를 되찾으셨나요? 저도 시도해 보고 싶지만 물이 너무 무서워요. 게다가 그 무시무시한 상어까지!'),
(27973, '귀신이 무서워서 도망쳤나요?'),
(27977, '현상금을 노리고 온 거라면, 훔친 물건을 내게 넘겨줘야 할 거야.'),
(27979, '그거 받았어?'),
(27981, '오일피스트가 곧 우리한테 화염병 만드는 법을 가르칠 거라고 하네. 그러니 플라스크가 더 필요하겠어.'),
(27982, '루비 손잡이가 달린 망치라니... 꽤 멋진 이름이군.'),
(27985, '<당신은 나이트 엘프의 기도문을 흘끗 훑어봅니다.>'),
(27987, '포탄을 찾았나요?'),
(27989, '루움보는 꿀이 있는지 없는지 냄새로 알아챌 수 있어요!'),
(27992, '그 자석 장치는 실제로 작동했나요?'),
(27996, '주문하신 상품이 있습니다, $n.'),
(28030, '진짜 사나이였다면 이빨로 총알을 막았을 거야.'),
(28031, '내가 생각하는 것과는 다른 것 같은데? 그렇지?!'),
(28032, '드디어 도마뱀 모래주머니를 손에 넣게 됐어요!'),
(28041, '<갓 잡은 사체를 모으세요.>'),
(28042, '내가 생각하는 것과는 다른 것 같은데? 그렇지?!'),
(28044, '$n, 거기 내 말 들려? 집게 있어?'),
(28045, '첫 번째 배치에 필요한 벌레 점액은 충분히 확보했나요?'),
(28049, '그 슬라임 있어?'),
(28057, '뭐라고요? 베개요? 뭐라고요?'),
(28058, '베개가 정말 크네요! 어디서 샀어요?'),
(28063, '그 소총들 구하는 데 성공했나요?'),
(28087, '도대체 어떤 광기가 사람을 그토록 끔찍한 짓을 저지르게 만들었을까?'),
(28090, '아시다시피, 그냥 게이트를 폭파시켜 버릴 수도 있겠지만, 우리 폭파 전문가를 생각하면 위험을 감수하지 않는 게 나을 것 같아요.'),
(28093, '어서 오세요, $r님.'),
(28099, '우리가 정령들에게 위협이 된다는 것이 증명될 때까지는 어떤 정령과도 싸우지 않겠습니다.'),
(28104, '그들은 지나치게 자신만만해졌다. 점점 더 많은 경우, 그것이 가장 강력한 군대의 몰락으로 이어지는 것 같다.'),
(28105, '돌아왔군요. 열쇠는 가지고 있나요?'),
(28114, '내 수확물을 가져왔나요?'),
(28116, '$n, 우는 제비꽃 찾았어? 빨리 필요해.'),
(28118, '대마법사를 처치하셨나요?'),
(28119, '타락한 달샘의 물을 가지고 있습니까?'),
(28120, '일지를 회수하셨습니까? 보고서에 따르면 그곳 감방 안팎에서 일지가 목격되었다고 합니다.'),
(28123, '가지고 있습니까? 네? 드래곤마우의 운명은 악마의 사슬에 달려 있습니다!'),
(28125, '갑옷을 얼마나 모았어? 다음에 해야 할 일을 위해 제대로 변장해야 할 거야.'),
(28137, '강도 행각에 성공해서 우리한테 생선 좀 구해다 줄 수 있었어?'),
(28139, '엘더 크론의 결속 암호를 가지고 계신가요?'),
(28141, '성공하셨나요?'),
(28144, '우리 "물품"을 되찾아라, $n!'),
(28147, '좋아, $n. 자네 같은 영웅들이 여기서 소란을 일으키면, 우리가 주력 작전을 펼치려는 사이비 종교 집단의 주의를 다른 데로 돌릴 수 있겠군.$B$B변장할 거라도 있나?'),
(28148, '악마의 잔재를 정화하려면 가죽이 필요하다.'),
(28149, '쉿, $n! 들어봐. 들어봐...'),
(28152, '안녕하세요, $c님. 무슨 일로 오셨나요?'),
(28154, '내가 무슨 멀록 과학자처럼 보이니?'),
(28157, '필요한 요소들을 모두 갖추셨나요, $c?'),
(28159, '$c님, 파멸의 돌을 가지고 계신가요?'),
(28162, '그 늪은 다 정리했어?'),
(28166, '영혼의 빛. 너 그거 가지고 있니, 친구?'),
(28172, '우리가 너무 늦지 않았기를 바라요.'),
(28177, '벌써 돌아오셨어요?'),
(28178, '가죽들을 한번 살펴볼까요.'),
(28179, '흑요석 정령들을 조심해야 할 거예요. 걔네들은 몰래 다가오는 경향이 있거든요.'),
(28181, '모든 걸 다 맞혔는지 한번 볼까요?'),
(28183, '고르제키를 잘 처리하신 것 같네요.'),
(28185, '코어하운드는 죽었나요?'),
(28186, '족쇄를 많이 발견하셨나요? 보고서에 따르면 그 지역 곳곳에 족쇄가 널려 있었다고 하던데요.'),
(28194, '$r, 유니폼 좀 구해다 주셨나요?'),
(28196, '이게 뭐지?'),
(28199, '과학을 위하여!'),
(28200, '당신이 이런 일을 마다하지 않는다는 것을 알게 되어 기쁩니다.'),
(28207, '밝은 초록색으로 빛나는 것들을 기억하세요!'),
(28208, '새끼 고양이를 찾으셨나요?'),
(28209, '열쇠를 가져오세요!'),
(28210, '집계 결과가 어떻게 되나요?'),
(28211, '창이요? 제 속사 작살총은 창이 없으면 무용지물이 될 겁니다.'),
(28212, '녹아내리는 분노를 갖고 있나요? 아니, 아니, 제 손에 쥐어주지 마세요. 여기, 집게를 사용하세요!'),
(28215, '지금 당장 배낭에서 엘레멘티움 코일을 잔뜩 꺼내주시면, 저는 정말 행복한 노움이 될 거예요!'),
(28216, '훔볼트 노인은 수년 동안 자신의 가장 큰 문제가 산등성이에 사는 글롭거트 오거 때문이라고 생각했습니다. 그러다 황혼의 망치가 나타났습니다. 순식간에 그들은 마치 생일 케이크를 태우듯 계곡 전체를 불태워 버렸습니다. 정말 잔인했죠.'),
(28223, '교도소장은 죽었나요?'),
(28226, '아시다시피, 우리는 이 골렘들을 직접 만듭니다. 약간의 기계 작업과 약간의 원소 작업을 거치면... 제 생각엔 결과물이 꽤 괜찮습니다.'),
(28231, '트윙클스를 위해!'),
(28232, '식량을 회수하셨습니까? 보고에 따르면 그 지역 곳곳에서 식량을 찾을 수 있었다고 하던데요.'),
(28234, '찾으셨나요? 이 곡물이 꽤 가려워요.'),
(28237, '내 시간을 낭비하지 마세요, $n.'),
(28243, '또 너야? 뭐? 뭐 좀 가져왔어?'),
(28253, '병사여, 돌아오신 것을 환영합니다.'),
(28266, '무슨 일이야, 무서워?'),
(28272, '$n님, 흥미로운 것을 찾으셨나요?'),
(28311, '흑요석 정령의 재는 특히 어둡습니다. 바로 우리가 원하는 것이죠.'),
(28312, '불꽃족은 약하지만 무리를 지어 다닙니다. 조심하세요.'),
(28313, '혹시 좋은 소식 있으신가요?'),
(28315, '자, $n, 아직 남은 적들이 더 있어. 우리 임무는 아직 끝나지 않았어.'),
(28316, '도착하셨군요, $n님.'),
