(28340, '우리 약속했잖아, 그렇지? 그렇지?'),
(28341, '그 정수를 다룰 때는 조심하십시오. 강력한 만큼 독성도 강합니다.'),
(28342, '사냥한 동물의 뒷정리도 꼭 해주세요.'),
(28343, '우리는 암흑철 드워프가 황혼의 망치단과 동맹을 맺는 것을 용납할 수 없습니다.'),
(28350, '$n, 내 양동이를 채울 만큼 충분히 있나요?'),
(28354, '진흙코를 되찾으셨나요?'),
(28359, '핵심 부품은 Shatter Scar Vale에서 멀리 떨어뜨려 놓아야 합니다.'),
(28364, '열쇠 받았어?'),
(28366, '무기를 가지고 있습니까?'),
(28376, '그 용을 쓰러뜨렸다고요!? 정말 대단해요!'),
(28386, '제 말이 맞았나요? 몇 개나 찾으셨어요?'),
(28393, '우리는 암흑철 드워프가 황혼의 망치단과 동맹을 맺는 것을 용납할 수 없습니다.'),
(28394, '우리는 저 골렘들이 우리에게 대항하는 데 이용당하는 것을 용납할 수 없습니다.'),
(28396, '당신은 제게 당신의 능력을 증명했지만, 우리 부족의 의심 많은 동족들에게도 계속해서 당신의 능력을 증명해야 할 것입니다. 그 과정에서 제가 계속해서 당신을 도울 수 있을지도 모릅니다. 데드우드 퍼볼그 중 일부는 독특한 머리 장식을 착용하는데, 이는 그들의 수를 줄이는 데 증거로 사용될 수 있습니다. 당신이 얻게 되는 머리 장식에서 깃털 하나를 제게 가져오십시오. 깃털 다섯 개를 가져올 때마다 당신은 팀버모우 부족 사이에서 인정을 받게 될 것입니다.'),
(28398, '화염술사의 마도서를 손에 넣는 데 성공했습니까?'),
(28399, '결속석을 찾으셨나요?'),
