(28408, '패니의 깃털을 가지고 있나요?'),
(28410, '공습은 어떻게 진행됐나요?'),
(28411, '식량 상황은 어떻습니까, $n님?'),
(28415, '오랄리우스는 허공에 손을 뻗고 주먹을 쥐어 쥔 손가락 사이로 희망에 찬 눈빛으로 바라보았다.'),
(28417, '우리가 너무 늦지 않았기를 바라요.'),
