(28436, '병사여, 돌아오신 것을 환영합니다.'),
(28443, '흑요석 정령의 재는 특히 어둡습니다. 바로 우리가 원하는 것이죠.'),
(28444, '불꽃족은 약하지만 무리를 지어 다닙니다. 조심하세요.'),
(28445, '혹시 좋은 소식 있으신가요?'),
(28448, '도착하셨군요, $n님.'),
