(28457, '우리는 암흑철 드워프가 황혼의 망치단과 동맹을 맺는 것을 용납할 수 없습니다.'),
(28458, '화염술사의 마도서를 손에 넣는 데 성공했습니까?'),
(28459, '결속석을 찾으셨나요?'),
(28461, '우리는 저 골렘들이 우리에게 대항하는 데 이용당하는 것을 용납할 수 없습니다.'),
(28467, '$n님, 뭔가 찾으셨길 바랍니다. 윈터폴이 점점 더 공격적으로 변하고 있어요!'),
(28469, '윈터폴이 독한 술을 구하지 못하면 어떻게 될지 두고 보자!'),
(28471, '자, 이게 뭐지? $n이네?'),
(28472, '$c 님, 무엇을 가지고 다니시나요?'),
(28483, '$n님, 다시 뵙게 되어 반갑습니다.'),
(28484, '예티 심장을 가져와, $n.'),
(28485, '예티무스는 반드시 죽어야 한다!'),
(28486, '안녕하세요, $n!'),
(28487, '나 거의 벌거벗은 상태야, $n. 좀 도와줘, 응?'),
(28488, '이 수정들은 특히 고르식에게 매우 귀중한 보물이다. 내가 이 수정 하나를 손에 넣게 된다면 그에게 막강한 영향력을 행사할 수 있을 것이다. 나는 그렇게 되기를 바란다.'),
(28489, '사슴고기가 필요해!'),
