(28498, '찾았나요, $n? 쓸 만한 것들이었나요?'),
(28500, '코덱스를 가져오셨나요, $n?'),
(28518, '마에니우스는 강력한 마법사이자 명예로운 엘프였다. 그의 영혼은 그토록 비참한 운명을 맞이할 자격이 없었다.'),
(28522, '$n 님, 팀버모우 부족을 위해 해주신 일에 진심으로 감사드립니다. 앞으로도 꾸준히 노력해 주신다면 저희 부족의 신뢰와 존경을 얻을 수 있을 것입니다.'),
(28524, '온천에 오신 것을 환영합니다. 뭘 가져오셨나요?'),
(28529, '어떻게 도와드릴까요, $c님?'),
(28530, '무엇을 발견했나요?'),
(28537, '그 색조를 찾으셨나요? 그 색조의 출처를 알 수 있는 단서가 남아 있었나요?'),
(28540, '곰 잡았어? 곰 좀 보여줘 봐.'),
(28583, '당신 알아요! 들어올 때 비행선에 같이 타고 있었잖아요.'),
(28593, '크라즈가 기다리고 있어요. 계속 움직이세요.'),
(28595, '약속 지켰다고 말해줘? 넌 언제나 약속을 지키잖아. 내 아름다움을 보여줘!'),
(28597, '파우더가 더 필요해! 파우더 더 가져다줘! 더, 더, 더!'),
(28598, '폭탄으로 해결 못 할 문제는 없어.'),
(28602, '수사는 어떻게 진행되고 있나요?'),
(28608, '암흑의 무덤 안에서 그 물건을 찾을 수 있을 것이오. 내 작업용 책상에 놓고 온 게 확실하다오.'),
(28610, '그 잔해들 가져왔어?'),
(28618, '어머, 또 너구나. 그 바위는 어디 있어?'),
(28625, '목재를 보여주세요.'),
(28626, '싹둑싹둑!'),
(28628, '아, 돌아오셨군요!'),
(28629, '여기서 시작해야 할 일이 많아요. 모피들을 최대한 빨리 보내주세요!'),
(28631, '그들은 완벽한가요? 완벽해야 할 텐데요!'),
(28632, '어머, 돌아오셨군요! 예티들은 어땠어요?'),
(28633, '어머나 세상에. 저것 좀 봐!?'),
(28658, '그 늪은 다 정리했어?'),
