(28665, '족쇄를 많이 발견하셨나요? 보고서에 따르면 그 지역 곳곳에 족쇄가 널려 있었다고 하던데요.'),
(28669, '교도소장은 죽었나요?'),
(28670, '식량을 회수하셨습니까? 보고에 따르면 그 지역 곳곳에서 식량을 찾을 수 있었다고 하던데요.'),
(28680, '럼주를 되찾으셨나요? 저도 시도해 보고 싶지만 물이 너무 무서워요. 게다가 그 무시무시한 상어까지!'),
(28684, '끈적끈적한 누에실샘을 모으실 수 있었나요?'),
