(28701, '그것들을 온전한 상태로 찾으셨기를 바랍니다...'),
(28707, '여기서 낯선 사람을 만날 줄은 몰랐네요!'),
(28710, '여기서 뭐 하는 거야?'),
(28713, '아직 할 일이 남아 있다, $n. 나이트세이버 개체 수를 줄인 후에 다시 내게 돌아오너라.'),
(28714, '내 의심을 풀어주시오, $n. 그렐킨에게서 펠 이끼를 가져오시오.'),
(28715, '그렐 놈들이 손님에게 팔 여분의 식량까지 싹 쓸어가 버렸소. 놈들이 훔쳐간 내 자루 좀 찾아봤소?'),
(28722, '그녀는 절대 예상하지 못할 거예요!'),
(28724, '이베론이 제 치료에도 차도를 보이지 않고 있어요. 필요한 재료를 가져오셨나요?'),
(28726, '이건 끔찍한 일입니다. 숲의 생명체들이, 비록 타락했더라도, 이렇게 끝내야 한다는 사실이 제 마음을 아프게 하는군요.'),
(28727, '저는 이 숲들을 너무나 사랑합니다. 이곳에서 부패가 완전히 사라지기를 바라뿐입니다. 다음에 다시 돌아올 때는 마음이 한결 가벼워지기를 소망합니다.'),
(28729, '최근의 우리 역사는 갈등과 폭력으로 얼룩져 있어요. 우리가 감내해야 하는 것이 아직도 많이 있답니다.'),
(28730, '달샘의 물은 사실 영원의 샘에서 온 것이랍니다. 그 샘은 우리 세계에 수많은 비극을 불러왔던 고대 마법의 원천이에요.$B$B드루이드들은 그 물의 특성을 이용하고 있고 파수대에서는 그 샘을 엘룬의 제단으로 신성시하고 있으며, 돌아오는 명가조차도 그 샘을 간절히 찾고 있답니다.'),
(28731, '어서 오시오, $c. 무슨 일로 이렇게 날 찾아왔는지 말해 주시겠소?'),
