(28799, '언뜻 보면 이 기둥은 아주 평범해 보이지만, 고고학 지식을 가진 당신이라면 다른 사실을 알게 될 겁니다. 만약 당신에게 드워프 룬석이 있다면, 이 기둥의 기원을 밝혀낼 수 있을 것입니다.'),
(28800, '이 화로는 분명 마법의 힘을 지니고 있지만, 당신이 그 힘을 불러일으키려는 시도에는 전혀 영향을 받지 않는 것 같군요. 톨비르 상형문자 해독석이 있었다면 옆면에 새겨진 문자를 해독하는 데 도움이 되었을 텐데 말입니다.'),
(28802, '이 돌 오벨리스크는 분명 일종의 배치도나 지도이지만, 완전히 해독할 수는 없습니다. 톨비르 상형문자가 새겨진 쐐기돌이 있다면, 그 표시를 더 잘 이해할 수 있을지도 모릅니다.'),
(28804, '이것들은 분명 어떤 종류의 설계도이지만, 무엇을 위한 것인지는 확실하지 않습니다. 이것들에는 드워프 룬석과 유사한 독특한 문양이 새겨져 있습니다.'),
