(29015, '광부들 중 누가 에메랄드를 발견했는지 알기만 한다면, 일은 식은 죽 먹기일 텐데...'),
(29023, '센터 콘솔 조명은 어두워져 있고, 계기판과 다이얼은 모두 0을 가리키고 있으며, 모든 것이 공회전 상태입니다.'),
(29024, '어머, 돌아오셨군요, $n! 사모플란지 가지고 계신가요?'),
(29026, '$C님, 저는 지금 일이 너무 바빠요. 혹시 저에게 부탁하실 일이 없으시다면, 다른 곳으로 가주시는 게 좋겠습니다.'),
(29027, '$n님, 너겟 슬러그 있으세요? 이 사모플란지를 눈여겨보고 있는데, 어서 만져보고 싶네요.'),
(29032, '우리는 검치호랑이 새끼들이 사람과 유대감을 형성할 수 있을 만큼 어릴 때 데려와야 합니다. 너무 나이가 들면, 그 고양이들은 영원히 야생 상태로 남을 것입니다.'),
(29034, '젊은 검객은 잘 지내고 있나요?'),
