(29135, '자, $C?$B$B필요한 재료는 모두 확보하셨나요?'),
(29138, '다행히도 라그나로스의 군대는 우리 전사들을 즉사시키기보다는 부상을 입히는 경우가 훨씬 많습니다. 그들의 공격은 자연스럽게 상처를 지지는 역할을 합니다. 매우 고통스럽지만, 죽는 것보다는 낫습니다.'),
