(29166, '어디 보자... 몇 개나 모았어?'),
(29179, '이 정령들이 땅을 차지하도록 내버려 둘 수 없습니다. 그들이 공격을 멈출 틈도 없이 계속 공격을 퍼부을 것이기 때문에 우리가 땅을 되찾을 기회는 없을 겁니다.'),
(29181, '다시 만나서 반갑습니다.'),
(29186, '헥스 로드 말라크라스를 처치했나요?'),
(29199, '우리가 침략 포털을 빨리 뚫을수록 좋습니다.'),
