(29234, '$C님, Nordrassil''s Bough를 복구하실 수 있었나요?'),
(29242, '그래서, 뭐 찾았어? 네 보물을 잔뜩 들고 있으니 바지가 엄청 무거워지네.'),
(29246, '이 심장들은 하물에게 휴식이 절실히 필요함을 정확히 줄 것입니다.'),
(29247, '일부 사람들은 그 포장지에 들어있는 유황이 치료 효과가 있다고 말합니다. 개인적으로는 확신이 서지 않지만, 혹시라도 효과가 있다면 냄새는 감수할 용의가 있습니다.'),
(29248, '저울이 있습니까? 대드루이드를 다시 베는 건 망설여지지만, 어떻게든 부기를 가라앉혀야 합니다.'),
(29251, '$n님, 뭐 찾으셨어요?'),
(29252, '$n님, 뭐 찾으셨어요?'),
