(29257, '정말 매혹적이네요! 불의 땅에서 시간을 보낼수록 이곳에 생태계가 작동하고 있다는 것을 더욱 분명히 알게 됩니다.'),
(29265, '어디에서든 자랄 수 있으니, 주변을 잘 살펴보세요.'),
(29270, '다시 만나서 반가워요, $n.'),
(29274, '우리가 얻을 수 있는 모든 정보는 우리 병사들이 섀녹스를 물리치는 데 매우 중요할 것입니다.'),
(29275, '제 말을 믿으세요. 여기서 얻을 수 있는 모든 정보는 판드랄의 힘의 근원을 이해하는 데 큰 도움이 될 겁니다.'),
(29276, '$n, 그 액체들을 다룰 때 조심해. 아무 데나 쏟으면 안 되잖아.'),
