(29287, '알을 회수할 수 있었나요?'),
(29288, '이 생물들을 어떻게 생각해야 할지 도무지 모르겠습니다. 다른 조류와 행동은 비슷하지만, 이 불타는 땅의 토착민임이 너무나 분명합니다. 라그나로스와 그의 부하들이 왜 이들을 우리에게 대항하도록 규합하려 하지 않는지 궁금하네요...'),
