(29323, '우리 어부들이 모두 힘을 합친다면, 식량 공급을 다시 확보하는 데는 그리 오래 걸리지 않을 것입니다.'),
(29324, '아퀴네의 잃어버린 펜던트를 찾는 데 성공했나요? 저는 그 괴물들을 쉰 마리는 넘게 잡았는데 아무것도 못 찾았어요!'),
