(29350, '새로 만든 그 멋진 미끼는 어떻게 되어가고 있어?'),
(29352, '닭들, $n, 당신은 닭들을 가지고 있나요, 아니면 가지고 있지 않나요?'),
(29353, '그 재료들 다 가지고 계세요?'),
(29354, '혹시 반짝이는 돌멩이를 가져오셨나요?'),
(29355, '그 향신료 빵은 어때요?'),
(29357, '저는 빵 굽는 냄새, 특히 향신료 빵 냄새를 정말 좋아해요. 여러분도 그렇지 않나요?'),
(29358, '맛있는 잣을 많이 찾으셨나요?'),
(29359, '청어 잡으셨어요?'),
(29360, '저 "고기" 중 일부는 아직 먹을 만할 거라고 장담해.'),
(29362, '버섯을 좀 따셨나요?'),
(29363, '멀고어 향신료 빵은 구워보셨나요?'),
(29365, '필요한 재료는 모두 준비하셨나요?'),
(29371, '$c님, 호드의 위커맨을 처치하셨나요?'),
(29396, '잘 지내? 나한테 뭐 줄 거 있어?'),
(29397, '잘 지내? 나한테 뭐 줄 거 있어?'),
(29399, '당신은 이 분실물에 대해 뭔가 알고 있는 것 같군요.'),
(29401, '$gmister:miss;님, 제 풍선을 모두 찾으셨나요?'),
(29402, '재료는 다 구하셨나요?'),
(29411, '우리가 얘기했던 대로 상자를 가져오셨나요?'),
(29412, '제 풍선을 모두 찾으셨나요, 아저씨?'),
(29418, '손에 흙이 묻는 걸 부끄러워하지 않으셨으면 좋겠어요.'),
(29424, '요정들을 다치게 할까 봐 걱정할 필요 없어요. 사실 요정들은 그냥 살아있는 식물일 뿐이니까요. 나중에 다시 자라날 거예요.'),
(29425, '당신은 이 분실물에 대해 뭔가 알고 있는 것 같군요.'),
(29426, '재료는 다 구하셨나요?'),
(29428, '우리가 얘기했던 대로 상자를 가져오셨나요?'),
(29433, '고통 없이는 얻는 것도 없다.'),
(29436, '안전한 착륙 되세요!'),
(29443, '거기에 무엇을 들고 있나요?'),
(29444, '거기에 무엇을 들고 있나요?'),
(29445, '거기에 무엇을 들고 있나요?'),
(29446, '거기에 무엇을 들고 있나요?'),
(29451, '저건 평범한 책처럼 보이지 않는데요...'),
(29456, '거기에 무엇을 들고 있나요?'),
(29457, '거기에 무엇을 들고 있나요?'),
(29458, '거기에 무엇을 들고 있나요?'),
(29464, '거기에 뭘 가지고 있어요?'),
(29475, '당신이 제작한 공학 아이템을 검토할 수 있게 되면, 당신은 고블린 공학자라는 특별한 모임에 가입하는 데 필요한 지식을 얻게 될 것입니다!'),
(29477, '제가 여러분이 제작한 공학 아이템을 검토할 수 있게 되면, 여러분은 공인 노움 공학자가 되어 노움 공학 설계도에 무제한으로 접근할 수 있게 됩니다.'),
(29481, '플라스크 있으세요?'),
(29482, '금 가지고 계세요?'),
(29506, '문베리 탄산음료는 어떻게 되어가고 있나요?'),
(29507, '어때요? 화석 조각 좀 기증하시겠어요?'),
(29509, '신선하고 바삭한 개구리 냄새가 나는 것 같은데?'),
(29510, '혹시 그 점쟁이의 가루를 좀 얻으셨나요?'),
(29513, '그 물고기 있어요?'),
(29514, '허브 수집은 어떻게 되어가고 있나요?'),
(29515, '당신은 그런 운세들을 직접 써본 적이 있나요?'),
(29516, '공연자들의 장신구에 사용할 교체용 보석을 제작할 수 있었나요?'),
(29517, '혹시 그 상품들을 만들어보셨나요?'),
(29518, '혹시 폐품이라도 찾으셨나요? 마당에 폐품이 널려 있어요.'),
(29520, '새로 산 배너를 걸 자리를 찾으셨나요?'),
(29523, '기회가 생기면 주저하지 말고 잡아야 할 책임이 있습니다. 망설이는 것은 포기하는 것과 마찬가지입니다.'),
(29527, '이 작업은 귀하의 성공 여부에 달려 있습니다. $n.'),
(29528, '성공하셨나요? 이번 작전에 많은 것이 걸려 있습니다. (금액은 $n입니다.)'),
(29529, '그곳에서 악마를 발견했나요?'),
(29530, '그 끔찍한 생물을 처리할 수 있었습니까?'),
(29535, '돌아왔군! 게다가 죽지 않았어! 정말 잘했어. 지금까지 누구보다도 훌륭해.'),
(29538, '자기 피가 그 피인가요? 우리가 부탁하면 좀 중요할 수도 있거든요, 알죠?'),
(29555, '잘?'),
(29560, '해골은 우리 부족에게 귀중한 보물입니다. 당신은 몇 개나 모았나요?'),
(29565, '당신이 그들을 죽였습니까?'),
(29567, '당신이 돌아왔군요. 그렇다면 블랙 스토커는 더 이상 존재하지 않는다는 뜻인가요?'),
(29574, '내가 원하는 게 없으면 시간 낭비하지 마세요.'),
(29575, '샤파르의 현상금에 관심 있으셨나요?'),
(29580, '남아있는 도구가 있었나요?'),
(29581, '네, 필요한 게 있으셨나요?'),
(29593, '몇 개의 더미를 가져갈 수 있었나요?'),
(29594, '몇 개의 더미를 가져갈 수 있었나요?'),
(29606, '테로크의 유물이 스케티스에서 너무 오랫동안 사라졌습니다. 세테크에서 그 유물들을 되찾을 수 있었습니까?'),
(29607, '눈은 가져오셨나요?'),
(29614, '가능한 한 철저하게 조사하십시오. 잔가르마쉬의 운명이 거기에 달려 있습니다.'),
(29619, '연회 준비됐어요? 너무 기대돼요.'),
(29627, '<우가 기대에 찬 눈빛으로 당신을 바라봅니다.>'),
(29629, '고대 약초학의 대가들은 꽃 한 송이에서 20병 분량의 추출물을 추출할 수 있었다고 전해집니다.'),
(29641, '토군을 찾으셨나요?'),
(29649, '불씨 가져왔어? 시간이 얼마 없어!'),
(29650, '불씨를 가져왔나? 카자레스는 전사다운 죽음을 맞이해야 마땅해.'),
(29653, '카르가스 블레이드피스트가 패배했다는 증거가 있습니까?'),
(29654, '''대족장'' 카르가스 블레이드피스트의 죽음을 증명할 증거를 가지고 돌아왔습니까?'),
(29655, '당신이 제게 천을 가져다주셨나요?'),
(29656, '당신이 제게 천을 가져다주셨나요?'),
(29659, '이미 구하셨겠죠?'),
(29662, '내 힘을 말로만 설명하는 건 아무 소용이 없어. 직접 보여줘야 해.'),
(29667, '잎사귀를 구하셨군요. 아주 잘하셨습니다.'),
(29677, '수영장으로 돌아가지 않기로 한 결정은 정말 힘든 결정이었어요. 슈는 그 결정을 진정으로 이해하지 못하는 것 같아요. 그는 늙고 약해진다는 게 어떤 건지 모르니까요.'),
(29685, '글쎄, C씨, 솔직히 다시 만날 수 있을지 확신이 안 섰어요.'),
(29686, '그것의 정수를 구할 수 있었나요?'),
(29691, '히비스커스를 좀 따셨나요?');

INSERT INTO `_koKR_stage_quest_request_items_locale` (`ID`, `CompletionText`) VALUES
(29692, '붉은 히비스커스가 더 필요해요. 항상 구하기가 어렵거든요. 다섯 송이씩 묶어서 가져다주시면 정말 감사하겠습니다.'),
(29749, '영혼 결속술이라니! 어째서 모구들이 그런 역겨운 짓을 다시 시작하도록 내버려 둔 건가?! 그리고 지금 나는, 반쯤 실패한 소환술의 결과물이 되어버렸군…<영혼은 잠시 분노에 차더니 당신을 향해 돌아섭니다.><지금이 몇 세기지?>'),
(29750, '모구족이 그동안 계속해서 스피릿클로를 훈련시켜 왔다니... 병은 받았어?'),
(29751, '의식에 필요한 물품들을 찾으셨나요? 그것들이 없으면 영혼들을 돌려보낼 수 없습니다.'),
(29756, '죽은 자조차도 굶주림을 안다.'),
(29759, '그를 찾았나요?'),
(29761, '반갑습니다, $c.$B$B장신구 하나만 얻는다고 진정한 투기장 고수가 되는 건 아니죠.$B$B이제 당신의 강철 같은 의지를 증명할 시간입니다.'),
(29762, '우리는 여전히 전사한 형제들을 애도합니다.'),
(29763, '$n.$B$B잘 지내시는 걸 보니 다행입니다. 저희는 감당할 수 있는 만큼의 사상자를 냈습니다.'),
(29764, '너 그 브리쿨 도끼들을 잔뜩 훔쳐왔어?'),
(29765, '나한테 필요한 거 있어?'),
(29768, '자, 그들은 더 이상 경고받을 필요가 없습니다. 망치 있으세요?'),
(29770, '대지의 정령인 우구가 잠든 이후로 땅이 점점 메말라가고 있고, 새 씨앗이 싹을 틔우기가 점점 더 어려워지고 있어요. 우리가 가진 식량을 최대한 아껴 써야 해요. 그렇지 않으면 섬에 힘든 시기가 닥칠 거예요.'),
(29771, '내가 부탁한 대로 했니?'),
(29777, '저는 호젠족의 열망을 폄하하려는 것이 아닙니다. 각 민족은 저마다의 길을 걸어야 합니다. 하지만 지금 그들은 우리의 신체와 문화에 해를 끼치고 있습니다. 이는 결코 넘어서는 안 될 선입니다.'),
(29781, '저런 것들로 마을에 불을 지르지 않은 게 오히려 신기하네요.'),
(29783, '육체적인 힘은 정신적인 힘 없이는 존재할 수 없다.'),
(29789, '휴식은 기분 좋다. 오랜 세월이 흐르면서 삶의 짐이 너무나 무겁게 느껴졌다.'),
(29795, '호드는 싸움에서 물러서지 않는다.'),
(29797, '제가 말했던 상자들을 찾으셨나요?'),
(29801, '우리의 임무를 완수했습니까? 이 유물들은 소지자가 죽으면 사라지도록 제작되었기 때문에 숙련된 도둑만이 획득할 수 있습니다.'),
(29802, '저는 아프라사스트라즈 경께서 유능한 $C.$B$B를 찾아주시길 바랐습니다. $n, 뭘 가지고 있습니까? 이 메시지를 해독할 방법이 있습니까?'),
(29803, '다시 만나서 반가워요, $n.'),
(29807, '끝났나요, $C? 반역자 왕은 드디어 최후를 맞이한 건가요?'),
(29811, '크릭티르의 영혼은 언데드의 저주에서 풀려났습니까? 부적은 어떻게 되었습니까?'),
(29815, '성공하셨기를 바랍니다. 우리의 생존이 여기에 달려 있을지도 모릅니다.'),
(29828, '그 거대한 짐승은 정말 존재하는가?'),
(29838, '저 골렘 조각 좀 가져다줄래?'),
(29839, '골렘 찾았어? 분명 어딘가에 있을 거야.'),
(29840, '다 드라카리 역사 명판을 찾았나요?'),
(29844, '다 드라카리 역사 명판을 찾았나요?'),
(29848, '다른 방법이 있었으면 좋겠지만, 이제 소녀에게는 죽음만이 유일한 구원인 것 같군요.'),
(29861, '로켄에게 정의가 실현되었습니까?'),
(29866, '실크우드를 찾으셨나요?'),
(29879, '위켓이 나한테 슬리키를 줬어!?'),
(29881, '꽃잎이 떨어진 후 완벽한 색조를 얻기 위해 사용할 수 있는 시간은 아주 짧습니다.'),
(29882, '벌침 좀 구하셨나요? 보통 이런 건 스님께 여쭤보는데, 지금은 다들 다른 곳에 계신 것 같네요.'),
(29885, '시간이 얼마 남지 않았습니다. 한 시간이라도 지체하면 흰 폰이 더 멀리 이동할 수 있습니다. 제가 요청한 물품들은 어디 있습니까?'),
(29887, '그 장로는 물과 소통하는 자입니다. 그가 물에게 말하면 물이 대답합니다.'),
(29891, '안개는 마치 제멋대로인 것 같지 않나요?'),
(29892, '늪지대에서는 발조심하렴, 내 새 친구야.'),
(29893, '재료를 모두 모으셨나요? 이제 곧 드림 브루를 만들 시간입니다.'),
(29900, '혹시… 그 두루마리를 찾으셨나요?'),
(29911, '순무 냄새가 나는 것 같은데?'),
(29913, '돼지들이 굶주려서 꽥꽥거리는 소리를 들으면 귀가 아파요. 하지만 돼지 농장을 좀 하다 보면 굶주린 돼지의 꽥꽥거리는 소리와 일반적인 꽥꽥거리는 소리를 구분할 수 있게 되죠.'),
(29914, '찾으셨나요? 세 개가 빠진 것 같은데요.'),
(29915, '어머... 제 양 한 마리를 가지고 계신 건가요?'),
(29918, '당신은 두려움이 없어요. 당신의 마음속에서 그걸 느낄 수 있어요.'),
(29925, '아, 다시 만나서 반갑습니다, $n님! 제 메시지 받으셨나요?'),
(29928, '<맨은 눈을 크게 뜨고 콧구멍을 벌렁거리며 당신을 기대에 찬 눈으로 바라봅니다.>'),
(29933, '미끈미끈한 음식!'),
(29937, '너 그거 손으로 만진 거 아니지?'),
(29939, '다이너마이트로 해결할 수 없는 위기는 아직 겪어보지 못했습니다.'),
(29940, '아버지가 채소를 드시고 싶어 하시면, 당신의 도움이 필요할 거예요.'),
(29942, '위켓 그루크 걔네들 다 잡아먹었지?'),
(29945, '페인트칠할 재료는 다 준비됐어? 난 미리 순무 좀 따왔어.'),
(29948, '나는 그 바이러스 놈들에게 내 땅에 들어오지 말라고 경고했어.'),
(29951, '널 처음 본 순간부터 친구로 삼을 수 있겠다는 걸 알았어.'),
(29968, '젖은 것들을 조심해야 해...휴!'),
(29988, '부활절 달걀 찾기는 잘 진행되고 있나요?'),
(29992, '아야! 아야! 아야!'),
(29997, '연못물이 탁해졌어. 직원들이 마음을 진정시키고 물과 대화를 나눠야겠어.'),
(30028, '새와 요정들 때문에 우리는 스톰스타우트 양조장에 대한 할당량을 절대 채울 수 없을 거예요.'),
(30032, '그 정글은 으스스하게 들리네요.'),
(30054, '이빨을 가져오면 멍멍이 너에게 홉을 좀 줄지도 몰라.'),
(30063, '마스크를 조심스럽게 다뤄주세요. 조심하지 않으면 마스크가 당신을 잡아먹으려 할 겁니다.'),
(30064, '경전들은 어떤가요? 손상된 부분은 없나요?'),
(30065, '화살표를 찾으셨나요?'),
(30072, '모든 물건을 찾으셨나요? 저희가 안내해 드린 과정을 꼼꼼히 살펴보셨나요?'),
(30076, '이거 정말 멋질 거야. 맥주 만드는 거랑 똑같을 텐데, 물 대신 워터 스프라이트 미트를 쓰는 거지.'),
(30080, '이모는 길게 한숨을 내쉬었다.'),
(30081, '켄켄이 이걸 왜 진작 생각 못 했을까. 딱 하나만으로 그의 하루를 망칠 수 있는데...'),
(30088, '<켄켄이 나무껍질로 무언가를 열심히 조각하고 있어요.>$B$B이거 정말 멋질 거예요, 두고 보세요.'),
(30097, '노즈도르무는 서두르고 있습니다. 이는 노즈도르무가 평소에 하지 않는 행동입니다. 평소 같으면 기록을 더 꼼꼼하게 남겼겠지만, 지금 상황에서는 기록할 내용을 선별할 수밖에 없고, 당신 같은 용병의 도움도 받아야 합니다.'),
(30107, '보석을 몇 개나 모았어? 내 아버지의 부하들도 그처럼 뒤틀린 걸까?'),
(30109, '넬리스. 죽었어?'),
(30113, '아, 돌아오셨군요! 날리스의 존재가 더 이상 느껴지지 않아요. 죽은 건가요? 아니면 어떻게든 우리 둘 다 피해 간 건가요?'),
(30116, '클러스터를 몇 개나 획득하셨나요? 당신들의 끈기는 저에게 계속해서 영감을 줍니다!'),
(30117, '안녕하세요, $c님.'),
(30118, '내 아버지는 어떻게 되셨습니까?'),
(30123, '정글의 공기조차 위험으로 가득 차 있다.'),
(30128, '레자의 고통은 너무나 극심하다. 이제 나와 아기를 구할 수 있는 건 내 능력 이상의 힘뿐이다.'),
(30129, '모구족은 한때 황제로 군림하며 마주치는 모든 종족을 정복했습니다. 그런데 이 모구족은 과거의 영광을 되살리려는 야망을 품고 있는 듯합니다.'),
(30130, '저는 주먹으로 맞고, 칼에 찔리고, 절벽에서 떨어지고, 누군가의 최루 스프레이에 얼굴을 맞고, 제 최루 스프레이에 얼굴을 맞고, 썬더 블러프의 엘리베이터에서 여러 번 떨어지기도 했습니다. 하지만 그 어떤 고통도 레자가 겪고 있는 고통의 절반도 안 되는 것 같습니다. 이 차가 조금이라도 도움이 되기를 바랍니다...'),
(30132, '전쟁. 결국 모든 건 전쟁으로 귀결된다.'),
(30137, '사우록족은 훔친 뱀 알을 자신들의 진영에 보관하고 있다.'),
(30139, '야생 구름뱀은 자연과 섬세한 균형을 이루며 살아갑니다. 그들의 귀한 알은 천적에게 매우 취약합니다.'),
(30140, '야생 구름뱀은 자연과 섬세한 균형을 이루며 살아갑니다. 그들의 귀한 알은 천적에게 매우 취약합니다.'),
(30141, '야생 구름뱀은 자연과 섬세한 균형을 이루며 살아갑니다. 그들의 귀한 알은 천적에게 매우 취약합니다.'),
(30146, '낚시하기 좋은 곳을 찾으셨나요?'),
(30147, '발굴 작업은 어떻게 진행되었나요?'),
(30149, '필요한 재료들을 모두 구하셨나요?'),
(30150, '당신이 돌아오자 새끼 새는 기뻐하며 빙글빙글 돕니다.'),
(30154, '작업이 완료된 것 같네요.'),
(30158, '다 됐나요?'),
(30159, '저 끔찍한 슬리더스케일 사우록들은 도대체 언제쯤 포기할까?'),
(30160, '$n님, 다시 뵙게 되어 반갑습니다.'),
(30168, '내 소중한 침 뱉는 통까지 훔쳐간 것 같아.'),
(30179, '체진 사건 소식 있나요?'),
(30184, '"빅 게임 헌터"에 "빅"이라는 단어를 제대로 넣어주는 사람.'),
(30185, '저는 항상 아버지의 그늘 아래서 살아왔습니다. 하지만 오늘 이후로 사람들은 네싱와리 주니어라는 이름을 기억하게 될 겁니다!'),
(30189, '오늘 잘 지내시나요, $n님?'),
(30191, '도난당한 맥주통을 찾았나요?'),
(30193, '먹여 살려야 할 입이 부족할 리는 없겠죠!'),
(30195, '꽃을 많이 모으셨나요?'),
(30196, '마을 곳곳에서 배고픈 사람들의 꼬르륵 소리가 들려요!'),
(30205, '내가 말했던 룬 문자를 찾았어?'),
(30206, '이 룬석들은 아주 오래전, 모구족이 계곡을 지배하던 시절에 힘의 원천으로 사용되었습니다.'),
(30230, '우리가 소유한 모든 유물은 모구의 손에 들어갈 무기를 하나씩 줄여주는 것과 같습니다.'),
(30231, '저는 항상 이런 것들에서 얼마나 많은 에너지를 뽑아낼 수 있는지 잘못 판단해요.'),
(30232, '당신처럼 훌륭한 분께 계속해서 이런 사소한 부탁을 드리는 것이 조심스럽지만, 우리는 절박한 상황에 처해 있습니다.'),
(30256, '저것 좀 봐... 어, 여기선 뭐라고 했지? 아, 맞다, ''부유츠!''라고 하더라! 저 부유츠 좀 봐! 농부 노릇 좀 감이 잡히는 것 같아.'),
(30257, '어머, 여기 처음 보는 얼굴인데요! 이름이 뭐예요?'),
(30259, '난 씹힌 당근을 못 봤어. 너도 씹힌 당근을 못 봤잖아. 머드클로 씨는 무슨 일이 일어날지 몰라, 알겠지?'),
(30265, '이 정체불명의 반짝이는 것들은 뭐였을까요? 너무 궁금해서 미칠 것 같아요. 동전일까요? 잔일까요? 아니면 버려진 결혼반지 열두 개쯤일까요?'),
(30267, '나는 낚시를 포기할 수 없어. 낚시는 내 정체성이니까!'),
(30268, '안두인은 손에 집중하며 뱀의 독샘을 재빨리 도려내고 있었다. 턱 안쪽... 두 번째 송곳니에서 5cm 정도 뒤쪽...'),
(30275, '그건 뭐예요?'),
(30277, '유물을 회수하셨나요?'),
(30285, '그 보고서들 찾았나요? 너무 많은 정보가 모구의 손에 들어가면 현장에 있는 우리 병사들의 안전이 걱정됩니다.'),
(30291, '게다가 제 방법은 재료가 이미 익혀져 있다는 장점까지 있습니다! 이보다 더 현대 기술의 효율성이 뛰어난 게 있을까요?'),
(30300, '모구족의 포로로 사느니 차라리 죽는 게 낫다. 그들은 친절한 포로가 아니다.'),
(30318, '맹세컨대, 그녀는 전에 이런 적이 없어요.'),
(30322, '있잖아, 너 같은 깡패... 아니, 깡패가 옆에 있으니 꽤 괜찮네.'),
(30323, '저 바이러스 환자들이 얼마나 무책임하고 유치한지 믿을 수 있나요? 저 보석이 얼마나 비싼지 모르는 걸까요?'),
(30326, '호젠족의 전설도 우리 전설과 크게 다르지 않을 거라고 장담해요.'),
(30328, '병뚜껑을 열지 않도록 하세요. 만약 하나라도 열게 된다면, 냄새를 너무 가까이 맡지 않는 게 좋을 거예요.'),
(30329, '고추를 도마 위에 올려놓으세요. 저는 직접 만지고 싶지 않아요.'),
(30330, '트러플은 많이 필요하지 않을 거예요. 사실 트러플은 풍미를 더하는 용도일 뿐이니까요.'),
(30331, '나는 이 스튜 만드는 연습을 하려고 매일 산에 오르곤 했다. 그때는 내가 더 어렸지.'),
(30332, '주방장은 곧 구워낼 스테이크에 사용할 향신료와 소스를 준비하느라 바쁘다.'),
(30334, '가지고 계신가요?'),
(30338, '혹시 예쁜 돌멩이 하나나 두 개쯤 찾으셨나요? 그렇게 해주셨다면 따뜻한 포옹을 해드릴게요!'),
(30339, '앞으로 낚시할 날이 정말 많네요! 어서 낚시를 시작하고 싶어요.'),
(30340, '앞으로 낚시할 날이 정말 많네요! 어서 낚시를 시작하고 싶어요.'),
(30344, '사라진 왕조를 연구하는 것과 그 고대 유적을 방문하는 것은 완전히 다른 경험입니다. 정말 오랜만에 느껴보는 짜릿한 기분이에요!'),
(30346, '<당신은 전승지기 벨드린의 존재를 감지하고, 그의 목소리가 마음속에서 들려온다.>$B$BHmm. 젊음의 샘과 관련된 "고문"에 대한 언급은 여전히 확실하지 않군.'),
(30347, '필멸의 존재라는 사실만큼 절박함을 느끼게 하는 것도 없을 것이다.'),
(30350, '브램블스태프 엄마는 늘 스쿼미 딜라이트가 어떻게든 배고픔을 달래줄 거라고 말씀하셨어요.'),
(30351, '이렇게 많은 모구는 처음 봅니다. 항상 성가시긴 했지만 이 정도로 심각하진 않았어요.'),
(30353, '네싱와리와 함께 사냥하는 건 좋지만, 그는 오로지 사냥 자체를 위해 하는 거고, 나는 이익을 위해 하는 건데, 그는 우리에게 돈을 주지 않아요.'),
(30355, '우리가 소유한 모든 유물은 모구의 손에 들어갈 무기를 하나씩 줄여주는 것과 같습니다.'),
(30363, '정찰병을 찾았나요?'),
(30379, '거기 서서 멍하니 바라보지 말고, 어서 말해 봐.'),
(30380, '오늘 시장이 정말 붐비네요. 무엇을 도와드릴까요?'),
(30381, '혹시 반려동물 키우세요? 저는 고양이를 좋아하는데, 강아지도 좋죠.'),
(30382, '날씨 정말 좋네요, 그렇지 않나요?'),
(30383, '음? 아, 안녕하세요. 오늘 어떠세요?'),
(30387, '고객이 아예 없는 것보다는 많은 게 낫죠. 어떻게 도와드릴까요?'),
(30388, '이웃님, 거기에 무엇을 들고 계신가요?'),
(30389, '안녕하세요, $n님. 마을 사람들과 모두 친해지고 계신가요?'),
(30391, '저는 농장 일로 이미 충분히 힘든데, 당신 문제까지 엮이고 싶진 않아요.'),
(30392, '젠장, 원숭이들이 또 우리 농장에 나타났어. 정말 기분이 나쁘네.'),
(30393, '오늘은 뭘 원하세요, $r?'),
(30394, '이 늙은이는 여기서 좀 평화롭고 조용한 시간을 보낼 수 없는 건가?'),
(30395, '수확철이 다가오는데 허리가 또 아프네요. 뭐, 이 동네 사람들은 다 이렇게 살아야죠.'),
(30397, '원하는 게 뭐예요?'),
(30398, '나는 산원숭이와는 다르다는 걸 분명히 알아둬.'),
(30399, '치치는 호젠 틸러의 첫 번째 주인이었습니다. 제가 할 수 있다면 여러분도 할 수 있습니다.'),
(30400, '오킨 산속의 원숭이들! 그들은 꼬마 치치가 얼마나 열심히 일하는지 몰라. 못된 원숭이들!'),
(30401, '리틀 치치는 내 평생 동안 여기에서 살았어요. 여기가 내 집이에요.'),
(30403, '네, C님. 무엇을 도와드릴까요?'),
(30404, '쉿, 잘 들어봐. 항상 경계해야 해.'),
(30405, '정신을 단련하는 첫 번째 단계는 신체를 단련하는 것입니다.'),
(30406, '시계는 절대 완성되지 않는다.'),
(30407, '저는 산에서 호젠을 제거하느라 열심히 일해 왔습니다.'),
(30408, '당신의 힘이 흔들리지 않도록 하십시오.'),
(30409, '하프힐에 있는 틸러스 유니언 빌딩에 가보신 적 있나요?'),
(30410, '농장은 잘 돌아가고 있나요?'),
(30411, '무슨 일이죠? 저는 바쁜 사람입니다.'),
(30412, '안녕하세요, $r님.'),
(30413, '훌륭한 농부는 파종을 위해 밭을 갈아 놓습니다. 갈아 놓지 않은 밭은 아무에게도 도움이 되지 않죠, 그렇죠?'),
(30416, '안녕하세요, 시티포우입니다!'),
(30417, '$r님, 잘 지내시나요?'),
(30418, '제가 무엇을 도와드릴까요?'),
(30419, '안녕하세요, $r님!'),
(30420, '심는 일이 끝났다는 사실만큼 기분 좋은 일은 없죠.'),
(30422, '나는 아침 내내 야크를 몰고 다녔어.'),
(30423, '아침 내내 바이러스를 쫓아다녔어요!'),
(30424, '아침 내내 돼지랑 씨름했어.'),
(30425, '나는 아침 내내 지렁이를 파냈어.'),
(30426, '나는 아침 내내 물고기들과 함께 헤엄치고 있었어.'),
(30428, '오늘 어떠세요, $r님?'),
(30429, '오늘 저 어때 보여요, $n?'),
(30430, '아시다시피, 항상 이렇게 멋진 모습을 유지하는 건 정말 힘든 일이에요.'),
(30431, '잠시 앉아 계시겠어요, $r님?'),
(30432, '농장은 잘 돌아가고 있나요?'),
(30434, '음료수 한 잔 값에 동전 한 닢만 주시겠어요?'),
(30435, '진유에게 술 한 잔 사줄까?'),
(30436, '이 모든 환상을 해석하는 건 정말 힘든 일이죠.'),
(30437, '내일 수확할 작물은… 아, 아직은 잘 모르겠네요. 일단 마실 것부터 좀 챙겨야겠어요.'),
(30438, '오늘 내게 큰 행운이 찾아올 거라는 뜻이군.'),
(30449, 'Je vois que vous avez r횄?횈?쇒꺿싀궰쯷ssi 횄?횈?쇒꺿싀궰?r횄?횈?쇒꺿싀궰쯷nir une suite de Grues ! F횄?횈?쇒꺿싀궰쯮icitations !'),
(30450, 'Je vois que vous avez r횄?횈?쇒꺿€싀궰쯷ssi 횄?횈?쇒꺿€싀궰?r횄?횈?쇒꺿€싀궰쯷nir une suite de Buffles! F횄?횈?쇒꺿€싀궰쯮인용!'),
(30451, 'Je vois que vous avez r횄?횈?쇒꺿싀궰쯷ssi 횄?횈?쇒꺿싀궰?r횄?횈?쇒꺿싀궰쯷nir une suite de Serpents ! F횄?횈?쇒꺿싀궰쯮icitations !'),
(30452, 'Je vois que vous avez r횄?횈?쇒꺿싀궰쯷ssi 횄?횈?쇒꺿싀궰?r횄?횈?쇒꺿싀궰쯷nir une suite de Tigres ! F횄?횈?쇒꺿싀궰쯮icitations !'),
(30459, '화살이 몇 개 있나요?'),
(30466, '호젠은 배치 준비가 되었습니까?'),
(30469, '필요한 물품들을 찾으셨나요?'),
(30470, '안녕하세요, $n님! 다시 뵙게 되어 반갑습니다.'),
(30471, '음?'),
(30472, '오! 안녕하세요, $n님.'),
(30473, '안녕, $n! 잘 지내?'),
(30474, '아, 음... 안녕하세요.'),
(30475, '흠흠!'),
(30476, '$n! 깜짝 놀랐잖아.'),
(30477, '뭐 필요한 거 있으세요, $c?'),
(30478, '흠?'),
(30479, '안녕하세요!'),
(30481, '룩을 위한 돌을 찾아주시겠어요? 부탁드려요.'),
(30482, '그는 당신을 기대하는 눈빛으로 바라봅니다.'),
(30484, '전투 훈련은 어떻게 진행되고 있습니까?'),
(30489, '음. 바늘의 신선한 향기만큼 좋은 건 없죠.'),
(30496, '직원들을 찾으셨나요?'),
(30516, '뿌리 채집은 어떻게 진행되었나요?'),
(30524, '저 호수에는 보물이 가득해! 뭘 찾아야 하는지만 알면 돼.'),
(30525, '호젠족은 큰 놀라움을 경험하게 될 거예요!'),
(30526, '개의 눈에 빛이 들어옵니다. 마치 당신을 알아보는 것 같습니다.'),
(30527, '$n, 우리 좋은 멜론을 꼭 키워야겠어. 그 교활한 호젠들은 제일 달콤한 멜론만 좋아하거든.'),
(30535, '어떻게 됐어, 친구? 그 씨앗들 그로안퍼한테서 구했어?$B$BErr... 그린필드?'),
(30565, '잃어버린 기어와 볼트를 찾으셨나요?'),
(30581, '목록에 있는 모든 걸 다 가지고 계신가요?!'),
(30582, '아, 그리고 거기에 있는 것들도요.'),
(30583, '음... 내 고기 가져왔어?'),
(30584, '장어를 잡으셨나요?'),
(30585, '내 아들 소식은 어때요?'),
(30586, '거기 아래에서 상어를 보셨나요?'),
(30590, '무사하군. 다행이군.$B$B내가 부탁한 거 구했어?'),
(30595, '이 모든 유물들을 어디에 보관해야 할까요?'),
(30598, '은빛 망둑어를 잡으셨나요?'),
(30600, '그룸들은 소박한 사람들입니다. 우리는 탐험하고 결과를 만들어내도록 태어났습니다.'),
(30603, '그룸믈들은 특정 그룸믈에게 가장 큰 행운을 가져다준 행운아의 이름을 따서 지어졌습니다. 호젠은 그룸믈의 행운을 훔치지 않는 것이 가장 중요합니다.'),
(30607, '운이 좋은 사람이라도 더러운 야크를 타고 예티 근처로 여행하는 건 절대 금물일 것이다.'),
(30613, '그 낚시창으로 뭐 좀 찾았어?'),
(30614, '야웅골은 무섭다. 이런 "기름"을 가진 야웅골은 더 무섭다.'),
(30618, '내 물품들을 일부 되찾아오셨나요?'),
(30621, '내 행운의 장신구들을 찾으셨나요? 행운은 아무리 많아도 지나치지 않잖아요.'),
(30636, '수정을 찾으셨나요?'),
(30640, '고대 모구족 중 가장 강력한 자는 원소의 힘을 불러낼 수 있었다고 전해진다. 천둥왕은 직접 번개의 힘을 창에 불어넣을 수 있었다.'),
(30641, '역사에 따르면 레이셴은 단 한 명의 적 외에는 두려워하는 적이 없었다. 그리고 결국 그를 패배시킨 것은 죽음이었다.'),
(30642, '도끼 찾았어?'),
(30658, '그 창 조심해, $n.'),
(30667, '토니의 이마 위 털에 땀방울이 반짝였다.'),
(30668, '재료는 있어? 내가 뗏목 만들어 줄게. 재료만 있으면 돼.'),
(30670, '그들의 정수를 추출했습니까?'),
(30671, '배가 너무 고파요, $r. 며칠 동안 이 석호에서 아무것도 못 먹었어요.'),
(30678, '얕은 물에서 가오리를 발견했나요?'),
(30698, '난파선을 찾으셨나요?'),
(30700, '그 징그러운 벌레를 없앴나요?'),
(30701, '그 작고 동그란 눈들을 몇 개나 얻으셨나요?'),
(30717, '아무리 작고 가느다란 깃털이라도 치가 우리를 사랑한다는 증거는 충분합니다.'),
(30746, '코타 콘은 카파를 더 먹고 싶어 하는데, 내가 가진 건 이미 다 줬어! 예쁘게 절도 해 줬는데도 만족하지 않네! 겁에 질린 그룸믈은 꿀꺽꿀꺽 침을 삼키고 가까이 다가와 속삭인다. 내가 아침에 마신 카파 냄새를 맡은 것 같아...'),
(30751, '기름 있으세요?'),
(30754, '지렁이 잡는 데 성공했나요?'),
(30763, '혹시 좋은 소식 있으셨나요?'),
(30771, '야웅골족은 적을 단순히 물리치는 것에 만족하지 않는다. 그들은 적을 완전히 섬멸하고 궤멸시키고자 한다.'),
(30780, '저는 토템이 우리에게 유용할 수 있다고 믿습니다.'),
(30787, '이 횃불들을 복수에 쓸 수 있어. 아직 이 상처로 쓰러지지 않았어. 죽기 전에 복수할 수 있어. 아직 시간이 있어.'),
(30790, '골고스의 배고픔은 극심하다.'),
(30791, '준비는 곧 완료될 것입니다.'),
(30797, '$n, 뭘 찾았어?'),
(30799, '그림자의 무덤에서 뭔가 찾았나요?'),
(30800, '천둥왕의 유해가 어디에 숨겨져 있는지 알아냈나요?'),
(30802, '그들의 위치에 대한 정보를 찾으셨나요?'),
(30806, '혹시 당신에게서 생명의 향을 만드는 재료 냄새가 나는 건가요? 아니면... 최근에 목욕을 안 하신 건지도 모르겠네요.'),
(30807, '돌멩이들, 가져오셨나요?'),
(30808, '럭키도는 아주 좋은 행운을 가져다주는 물건입니다. 야웅골은 아직 럭키도를 어떻게 사용하는지 전혀 모릅니다.'),
(30828, '호수는 깨끗해졌나요?'),
(30891, '이 꽃들의 꽃가루를 적절히 섞으면 인체에 영구적인 손상을 주지 않으면서 독소를 분해할 수 있습니다.'),
(30894, '저는 사마귀 독에 대한 영구적인 해독제를 찾아서 사람들이 애초에 감염되지 않도록 하고 싶습니다. 그 방법을 완성하는 데는 시간이 좀 걸릴 것 같습니다.'),
(30895, '예상보다 훨씬 빨리 돌아왔네. 씨앗도 가져왔어?'),
(30897, '엄마는 이런 일이 일어날 거라고 미리 경고했었어요...'),
(30899, '또 다른 전단지 배포대가 다가오고 있습니다. 대비하세요.'),
(30922, '확실히 힘든 일이죠. 하지만 무덤을 파는 것만큼 힘들지는 않아요.'),
(30931, '찾았어요?'),
(30942, '아버지께서 저에 대해 잘못 생각하고 계신다는 걸 보여드리겠습니다!'),
(30943, '적절한 양의 휘발성 꽃을 찾으셨나요?'),
(30945, '이번 일을 헤쳐나가려면 운만으로는 부족할 겁니다. 제가 활용할 만한 자료를 찾으셨기를 바랍니다.'),
(30954, '우리 병사들은 철퇴와 곤봉으로 싸우는 데 익숙합니다. 안타깝게도 우리는 관습에 얽매일 시간이 별로 없습니다.'),
(30963, '갑옷이 부서졌다는 이유만으로 우리 동족이 쓰러지는 것을 용납할 수 없다.'),
(30964, '혹시 $n님, 뭔가 좋은 소식 있으신가요?'),
(30969, '휘장을 모두 모으셨나요?'),
(30971, '다리 위의 판다렌들이 우리에게 의지하고 있어요...'),
(30972, '이 혼란스러운 세상에 오신 것을 환영합니다.'),
(30998, '휘장을 모두 모으셨나요?'),
(31005, '영양분을 섭취하지 못하면 그 자리에서 죽을 것이다.'),
(31008, '검을 든 자들은 자부심을 가지고 검을 차고 다닙니다. 저도 제 무기 거치대에 그 검들을 꽂아두고 싶어요!'),
(31023, '거기에 뭘 가지고 있어요?'),
(31024, '코보크를 위해 무엇을 가져왔나요?'),
(31041, '혹시 알을 찾았니? 뱀들은 해변의 둥지에 알을 낳는데, 숲의 요정들이 기회만 되면 알을 훔쳐가는 것으로 알려져 있어.'),
(31042, '오닉스 스톰클로는 결코 주인의 명령을 거역하지 않을 것이다.'),
(31043, '지식은 강력한 힘을 지닌다. 바로 그 때문에 모구족은 그토록 위험한 것이다.'),
(31044, '퀼렌족은 사납지만, 당신의 눈에서도 사나움을 봅니다.'),
(31068, '저거 혹시 두루마리 같은 건가요? 제가 좀 봐도 될까요?'),
(31070, '저 재료들을 어떻게 맥주에 섞을까? 갈아서 넣으면 너무 껄끄러울 것 같아. 그냥 물에 좀 담가둬야겠다.'),
(31071, '찾으셨나요? 설마요?'),
(31072, '$n.$B$B이 예언의 다음 몇 줄을 이해하기 시작한 것 같군요. 단검은 가지고 있나요?'),
(31073, '우리는 여기서 나무통으로 맥주를 만들지 않아요. 나무통은 맥주에 와인과 비슷한 텁텁하고 밍밍한 맛을 내거든요. (부우가 침을 뱉는다.)'),
(31077, '첸은 애도 중입니다.'),
(31078, '저기 누군가 있는 것 같은데, 이 황색 빛줄기 너머로는 잘 안 보이네요.'),
(31080, '저는 그런 것들을 하나도 잡지 못했어요!'),
(31086, '혹시 좋은 소식 있으셨나요?'),
(31090, '호박을 캐러 당신과 함께 가고 싶지만, 제 재능은 여기에서 더 유용할 것 같습니다.'),
(31107, '키파리 보르는 한때 아름다운 곳이었다. 호박이 풍부하고 주변에는 훌륭한 사냥터가 펼쳐져 있었다.'),
(31108, '크리스탈 가지고 계세요?'),
(31110, '가루들을 찾으셨나요?'),
(31112, '그 물품들을 어떻게든 구해냈어, 친구?'),
(31118, '뭔가 찾으셨나요?'),
(31141, '아, 제 편지 받으셨군요, $n... 잘됐네요. 저는 당신 부족에게 $c의 방식을 가르치기 위해 먼 곳에서 왔습니다.'),
(31146, '아, 네, 제가 보내드린 거예요. 포세이큰도 $c의 기술을 배울 수 있다는 걸 증명하고 싶은데, 혹시 도와주실 수 있을까요?'),
(31156, '아, 오셨군요.'),
(31160, '별로 어려운 상대는 아닐 것 같지만, 발놀림이 빠르지 않으면 발목을 할퀴일 수도 있어.'),
(31165, '아, 만나서 반갑습니다.'),
(31168, '아, 오셨군요. 잘 오셨습니다. 저는 이곳에서 많은 것을 배우고 있습니다. 당신 나라 사람들은 제가 본 어떤 곳과도 비교할 수 없을 만큼 풍부한 지식을 가지고 계십니다. 그 사실에 겸손해지는 한편, 저 또한 당신에게 우리의 방식을 가르쳐 드릴 수 있기를 바랍니다.'),
(31176, '불가사리 즙이 내 정신을 맑게 해 줄 거야.'),
(31177, '저는 할 일이 많습니다. 빨리 싸울수록 의회로 복귀할 수 있을 겁니다.'),
(31178, '적의 피를 마심으로써 그들의 힘을 얻게 된다.'),
(31184, '솔직히 말해서, 그루퍼가 낡은 전세선을 먹어치웠으면 좋겠어.$B$B잠깐, 그럼 어쨌든 여기로 오게 될지도 모르잖아. 젠장!'),
(31186, '이건 당신이 본 것 중 가장 한심한 사자물범일 겁니다.'),
(31188, '탈곡기가 사람을 잡아먹는 걸 실제로 본 적이 있어서, 왜 굳이 그 이빨을 목에 걸고 싶어하는지 이해가 안 가지만, 뭐 어쨌든.'),
(31208, '독꼬리뱀의 침에 쏘인 느낌 알았어? 참 기분 좋은 고통이지.'),
(31209, '풍뎅이 날개를 으깨면 아주 고운 흰색의 치명적인 가루가 만들어집니다.'),
(31210, '때로는 가장 아름다운 것이 가장 위험한 것일 수도 있다.'),
(31232, '당신은 어떤 지식을 가지고 있습니까?'),
(31233, '이 나무들은 아직 어립니다. 아직 키파리 나무가 아닙니다. 이 나무들의 수액은 물과 같지만, 진짜 키파리 나무의 수액은 와인과 같습니다. 이 나무들은 더 자라도록 내버려 두어야 합니다.'),
(31234, '오오, 정말 맛있고 훌륭한 부위들을 가져오셨군요!'),
(31238, '코보크에게 적당한 식사를 찾으셨나요?'),
(31241, '뭐 가지고 있어, 위켓?'),
(31251, '살코기 부분 말인가요? 우린 그게 필요해요!'),
(31254, '또 낯선 사람들? 오늘따라 유난히 볼만하네.'),
(31255, '또 낯선 사람들? 오늘따라 유난히 볼만하네.'),
(31260, '나도 저 호랑이를 직접 상대해 볼까 생각했지만, 솔직히 말해서 난 살아있는 게 좋아...'),
(31262, '나는 그 새가 호랑이의 얼굴을 찔러 죽이는 것을 목격했다. 새가 호랑이의 천적이 되는 곳이 대체 어떤 곳인가?'),
(31268, '그들은 여전히 나의 음향 조작에 저항하고 있다. 그 이유를 알아내야만 한다.'),
(31279, '제게 온 편지가 있나요?'),
(31281, '지시를 잘 따를 수 있다는 것을 보여주세요.'),
(31286, '사우록족이 이렇게 대담한 경우는 드물다.'),
(31288, '과거를 잊는 것은 위험하다.'),
(31302, '저는 당신이 훌륭한 요리사가 될 잠재력이 있다고 믿지만, 결과로 증명해야겠죠.'),
(31311, '그릴 요리의 기술을 배우고 싶다면, 생고기 타이거 스테이크를 가져오세요.'),
(31315, '거기에 뭘 가지고 있어요?'),
(31320, '목마른...'),
(31321, '내가 술 취한 사람처럼 말한다니 무슨 소리야? 원래 내 말투가 이렇단 말이야!'),
(31322, '혹시 좋은 소식 있으셨나요?'),
(31323, '시도해 보셨나요?'),
(31324, '안녕하세요!'),
(31332, '저는 정말 요리사가 되고 싶은데, 다른 아이들은 이미 몇 달 전에 시작했어요. 당신의 도움이 없으면 따라잡을 방법이 없어요.'),
(31333, '면을 너무 익히는 건 정말 쉬운 일이에요!'),
(31334, '화상 입지 않기를 바라요. 으악.'),
(31335, '으악.'),
(31336, '결과물이 어떻게 나올지 너무 기대돼요!'),
(31338, '제 양 인형 찾으셨어요? 정말 걱정했어요.'),
(31339, '아이고, 불쌍한 시피. 얼마나 무섭고 외로울까...'),
(31357, '신과 그의 일족이 그것들을 발견하기 전에 우리는 등불, 저울, 두루마리, 활을 되찾아야 합니다.'),
(31398, '이거 어디서 찾으셨어요?'),
(31440, '스파이를 죽여라!'),
(31443, '날치?'),
(31444, '이상한 물고기인가요?'),
(31446, '위장 문어?'),
(31458, '정보는 힘이다, 웨이크너. 가장 많은 정보를 가진 자가 언제나 가장 큰 힘을 갖게 된다.'),
(31465, '군집에서 생성되는 독은 우리에게 추가 무기를 제공할 뿐만 아니라, 군집이 어떤 단계에 있는지 파악하는 데에도 도움이 될 것입니다.'),
(31467, '제게 레시피를 배우고 배운 것을 보여주세요.'),
(31470, '안녕하세요, 젊은 요리사님. 웍 요리의 기술을 배우고 싶으신가요?'),
(31471, '당근 볶음 만드는 법을 알려드릴게요.'),
(31472, '안개처럼 휘몰아치는 수프 레시피를 배우고 싶으세요? 그럼 옥폐어를 좀 가져오세요.'),
(31473, '지혜의 상징은 종종 신비술을 사용하는 자들에게서 발견되는 반면, 힘의 상징은 대개 무력을 중시하는 자들에게서 발견됩니다. 물론 항상 그런 것은 아니지만, 필요한 것을 찾는 데 도움이 될 수 있습니다.'),
(31474, '냄비 요리의 달인이 되고 싶다면, 먼저 안개처럼 휘몰아치는 수프부터 만들어야 합니다.'),
(31475, '찜 요리의 기술을 배우고 싶다면 새우가 필요할 겁니다.'),
(31476, '새우 만두 만드는 법을 알려드릴게요.'),
(31477, '제가 알려드리는 야생 조류 구이 레시피를 따라 해 보시고, 여러분의 실력을 보여주세요.'),
(31478, '야생 조류 구이를 만들려면 야생 조류 가슴살을 구해야 합니다.'),
(31479, '맥주 양조의 길을 배우고 싶으신가요?'),
(31480, '인삼차 만드는 법을 알려드릴게요.'),
(31481, '판다렌의 또 다른 지혜: "두려움은 우리가 가둬야 할 범죄자가 아닙니다. 그것은 우리가 이해하려고 노력해야 할 스승입니다." 두려움에 맞설 때 우리는 큰 힘을 얻습니다. 당신은 두려움에 맞섰습니까, $n?'),
(31486, '제게 온 편지가 있나요?'),
(31488, '제 편지가 당신에게 잘 전달되었군요!'),
(31489, '이렇게 다시 만났군요!'),
(31493, '그 코덱스를 손에 넣는 건 필수적이야.'),
(31497, '그 코덱스를 손에 넣는 건 필수적이야.'),
(31502, '표본을 가지고 계신가요?'),
(31506, '이 정도는 당신이 충분히 해낼 수 있겠죠?'),
(31508, '표본을 가지고 계신가요?'),
(31513, '이미 칼 하나를 손에 넣은 당신은 다른 칼을 집으려 합니다. 칼 뒤에 있는 조각상에는 "섭리의 손"이라는 글귀가 새겨져 있습니다.'),
(31515, '이미 칼 하나를 손에 넣은 당신은 다른 칼을 집으려 합니다. 칼 뒤에 있는 조각상에는 "섭리의 손"이라는 글귀가 새겨져 있습니다.'),
(31534, '이유는 잘 모르겠어. 매일 양조장을 바라보고 있어서 그런가 봐. 그냥… 밸리에서… 아니… 판다리아 전체에서 최고의 맥주를 만들고 싶어! 아, 바보 같은 꿈이지?'),
(31535, '요리할 재료가 없으면 요리하는 법을 배우기 어렵습니다.'),
(31536, '식재료는 제대로 보관하지 않으면 상합니다.'),
(31539, '이건 정말 대단한 프로젝트입니다. 당신처럼 숙련된 장인이라 할지라도 많은 시간과 노력이 필요할 겁니다.'),
(31603, '타락한 키파리 중 일부는 그 끔찍한 무리의 행진 중에 산산조각이 나면서 샤가 들끓는 호박 조각들을 땅 곳곳에 흩뿌렸습니다. 여행 중에 발견하는 것이 있으면 제게 가져다주십시오. 적절하게 처리하겠습니다.'),
(31681, '호박을 캐러 당신과 함께 가고 싶지만, 제 재능은 여기에서 더 유용할 것 같습니다.'),
(31690, '예?'),
(31691, '예?'),
(31692, '예?'),
(31700, '그들의 표정을 봤어? 화가 났던 것 같아?'),
(31704, '갓 부화한 새끼가 순진한 눈으로 당신을 바라봅니다.'),
(31708, '당신의 뱀이 당신을 반갑게 맞이합니다.'),
(31710, '당신이 돌아오자 당신의 뱀이 활기를 되찾습니다.'),
(31713, '술은 복구됐나요? 저는… 저는 정신을 잃어가고 있어요…'),
(31714, '구름뱀 기사단은 수 세기 동안 구름뱀을 충성스러운 동반자로 만들기 위해 노력해 왔습니다. 우리의 친절은 이 생명체들의 가장 좋은 면을 이끌어냅니다. 하지만 불행히도 폭력과 분노는 그들을 순식간에 파괴적인 괴물로 만들 수 있습니다.'),
(31716, '갓 부화한 새끼가 재미있다는 듯이 당신을 바라봅니다.'),
