(31809, '<반이 눈을 가늘게 뜨고 당신을 바라봅니다.>$B$B당신에게 뭔가... 달라졌어요. 변했어요.'),
(31945, '쪽파를 간과하지 마세요. 작고 눈에 띄지 않을지 모르지만, 정말 놀라운 풍미를 만들어냅니다.'),
(31946, '바이러스는 당근을 좋아하지만 순무는 싫어합니다. 저도 순무를 싫어해요.'),
(31947, '저는 제 야크들 모두에게 애칭을 붙여줬어요. 털복숭이, 덥수룩한, 복슬복슬한, 양털 같은 등등이요.'),
(31948, '이 계곡의 물은 북쪽의 영원한 꽃의 계곡에서 흘러옵니다. 이 물에는 신비롭고 마법적인 효능이 있다고 전해집니다.'),
(31949, '좀 빨리해 줄래? 나 늙은 여자라고. 시간이 많지 않아. 죽기 전에 소스를 한 번 더 맛보고 싶다고!'),
(32016, '이 부적들이 당신에게 큰 행운을 가져다주기를 바랍니다, $n.'),
(32017, '이 부적들이 당신에게 큰 행운을 가져다주기를 바랍니다, $n.'),
(32120, '정령들의 정수를 얻으려면 그들을 파괴해야 합니다. 자, 가세요.'),
(32130, '귀, $n, 귀 좀 보여줘!'),
(32131, '돌멩이 좀 있어? 나 뭐 좀 폭파시키고 싶어!'),
(32137, '결국 그는 귤을 활용할 방법을 찾았군요? 아껴 쓰면 부족함이 없다는 말이 맞는 것 같아요!'),
(32141, '혹시 거기 내려가다가 반짝이는 거라도 발견하셨어요?'),
(32149, '나무는 다 모았어?'),
(32151, '돌을 가져오셨나요?'),
(32152, '병사, 저 파괴병들을 제거해 줘야 해!'),
(32156, '전쟁 중에도 최소한의 예의는 지켜야 한다.'),
(32161, '여기가 바로 그 장소, 학사(雲寺) 근처입니다.'),
(32162, '여기는 호랑이 덫을 놓기에 딱 좋은 장소 같군.'),
(32163, '여기는 게를 잡기에 좋은 장소 같아 보이네요.'),
(32164, '여기가 바로 그 장소, 학사(雲寺) 근처입니다.'),
(32165, '여기는 호랑이 덫을 놓기에 딱 좋은 장소 같군.'),
