(32186, '$n님, 다시 오신 것을 환영합니다.'),
(32194, '저 블러드 엘프들은 뭘 노리고 있는 거지?'),
(32197, '이번엔 나한테 뭘 줄 거야?'),
(32199, '사장님이 찜 요리를 원하신다고요? 그럼, 직접 내려와서 만들어 보시는 건 어떠세요!'),
(32233, '그래서? 뭘 발견했어?'),
(32234, '유물을 찾으셨나요?'),
(32243, '거기 위에서 뭐 찾은 거 있어?'),
(32244, '무엇을 발견했나요?'),
(32257, '저희는 이 발굴 작업을 충분히 처리할 능력이 있습니다. 대족장께서 당신을 보내셨다는 건 알지만, 저희에게 일을 맡기시는 게 더 빠른 결과를 얻으실 수 있을 겁니다.'),
(32264, '가지고 있어요? 그 책 있어요?!'),
(32292, '잘?'),
(32318, '내가 가진 약초만이 볼진의 죽음을 막아주고 있다. 감히 그의 곁을 떠날 수 없다.'),
(32319, '저를 보러 먼 길을 오셨군요, $R. 말씀해 보세요.'),
(32332, '아, 그 똑똑한 녀석이 돌아왔군. 내 호박을 가지고 있니?'),
(32333, '메탈 브루 있어요?'),
(32336, '잉구는 훌륭한 호젠이었어요. 리더십도 좋았고, 파티도 즐거웠고, 술도 맛있었죠.'),
(32337, '너 머리 잘 놀아?'),
(32338, '모구가 어떻게 그 연고를 찾았는지는 정말 신기한 일이다. 하지만 세상이 산산조각 난 이후로 많은 일이 일어났다.'),
(32342, '덫을 가져오셨나요?'),
(32343, '본질은 저절로 생겨나지 않을 겁니다, $R.'),
(32377, '코르크론 변장을 완성한 순간, 무전기 이어폰에서 지직거리는 소리가 납니다.'),
(32379, '모구에 대해 뭔가 찾으셨나요?'),
(32397, '무엇을 발견했나요?'),
(32446, '그럼 그 리모컨은 무슨 역할을 했을까요?'),
(32448, '책 속에는 어떤 게 들어있을지 아무도 몰라요. 특히 고대 판다렌 책이라면 더더욱 그렇죠. 이 기억의 술이 어떻게 작용하는지 정말 궁금하네요.'),
(32494, '마스크 있으세요?'),
(32505, '저는 모든 조각을 다 받아야 합니다. 조약돌 하나라도 빠지면 계약을 파기하는 것을 고려하겠습니다.'),
(32506, '이 섬에는 거대한 어둠이 드리워져 있다...'),
(32556, '$c, 뭘 가져왔어?'),
(32557, '거기서 뭘 알아냈어? 도움이 될 만한 거라도?'),
(32558, '마스크는 어디 있죠?'),
(32571, '이 섬에는 거대한 어둠이 드리워져 있다...'),
(32587, '잘?'),
(32589, '우리의 노력에 성공하셨습니까?'),
(32591, '천둥의 왕좌에서 무엇을 발견했습니까? 천둥왕의 흉포한 명성은 과연 사실일까요?'),
(32594, '폭풍의 군주 날락은 어떻습니까? 그리고 창은요? 자세한 내용을 알려주세요!'),
(32596, '지금까지 무엇을 발견했나요? 우리는 가능한 모든 정보를 수집해야 합니다!'),
(32597, '천둥의 왕! 그에게 무슨 일이 일어난 걸까?'),
(32599, '레이셴의 힘이 내 지팡이와 융합되면 우리는 막을 수 없는 존재가 될 것이다.'),
(32607, '시간이 흐를수록 우리는 천둥의 왕을 쓰러뜨리는 데 한 걸음 더 가까워진다.'),
(32608, '천둥왕의 힘은 전설적이다. 그를 이기려면 우리가 얻을 수 있는 모든 이점을 활용해야 한다.'),
(32613, '쿠마에게 뭘 가져다줄 거야?'),
(32614, '그것들을 내놔! 내게 줘!'),
(32615, '당신은 누구세요? 왜 돌아오셨나요? 헤헤헤...'),
(32616, '<쿠마가 미친 듯이 웃으며 당신을 가리킵니다.>'),
(32617, '<쿠마는 오두막 주위를 춤추기 시작한다.>'),
