UPDATE `quest_request_items_locale` AS `l`
INNER JOIN `_koKR_stage_quest_request_items_locale` AS `s` ON `l`.`ID` = `s`.`ID` AND `l`.`locale` = 'koKR'
INNER JOIN `quest_request_items` AS `p` ON `p`.`ID` = `s`.`ID`
SET `l`.`CompletionText` = IF(`s`.`CompletionText` IS NOT NULL AND (`l`.`CompletionText` IS NULL OR `l`.`CompletionText` NOT REGEXP '[가-힣ㄱ-ㅎㅏ-ㅣ]'), `s`.`CompletionText`, `l`.`CompletionText`);

INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`)
SELECT `s`.`ID`, 'koKR', `s`.`CompletionText`
FROM `_koKR_stage_quest_request_items_locale` AS `s`
INNER JOIN `quest_request_items` AS `p` ON `p`.`ID` = `s`.`ID`
LEFT JOIN `quest_request_items_locale` AS `l` ON `l`.`ID` = `s`.`ID` AND `l`.`locale` = 'koKR'
WHERE `l`.`ID` IS NULL;

DROP TEMPORARY TABLE `_koKR_stage_quest_request_items_locale`;
